def _bust_all_data_caches() -> None:
    """Drop every in-memory user-data cache so the next read re-loads
    from disk — used after a Migrate-Data import replaces the data files
    underneath the running app. Driven by `_MASTER_DELETE_CACHE_ATTRS`
    (the canonical list) so a newly-added cache enrols automatically,
    exactly like the agent restore endpoint. Cancels any pending settings
    flush first so the background daemon can't write a stale settings
    dict over the freshly-imported one, and clears the derived BLAST LRU.
    """
    try:
        with _settings_flush_lock:
            _state._settings_flush_pending = None
    except NameError:
        pass
    try:
        clear_blast = globals().get("_blast_clear_cache")
        if callable(clear_blast):
            clear_blast()
    except Exception:
        _log.debug("migrate: blast cache clear failed", exc_info=True)
    with _cache_lock:
        for cache_attr in _MASTER_DELETE_CACHE_ATTRS:
            _reset_master_delete_cache(cache_attr)


def _confirm_proceed(prompt: str = "Proceed? [y/N] ") -> bool:
    """Return True iff the user typed an affirmative answer.
    Defaults to False on empty input, EOF, or Ctrl+C — never run a
    destructive action without explicit consent."""
    try:
        answer = input(prompt).strip().lower()
    except (KeyboardInterrupt, EOFError):
        print("", flush=True)  # newline so terminal prompt isn't stuck on the input line
        return False
    return answer in ("y", "yes")




_RESTORE_LIST_SENTINEL = "\x00splicecraft-restore-list-only\x00"


# ── _run_update_subcommand helpers ────────────────────────────────────────
#
# `_run_update_subcommand` was 532 lines in 0.9.2 — too big to hold in one
# review frame. Pre-refactor every branch (parse, list, restore, refuse,
# snapshot, install) lived in one function, so a bug in one branch lived
# inside 500 lines of unrelated code. Splitting each branch into a named
# helper does NOT change behaviour — the helpers exist purely to give the
# dispatcher a flat, scannable shape.
#
# Sacred invariant #39 (pre-update snapshot before any install
# subprocess) still applies; only its location has moved into
# `_update_take_snapshot`.


def _update_build_parser() -> "_SubcommandParser":
    """Construct the argparse parser for `splicecraft update`.

    Kept as a separate function so tests can introspect the parser
    without having to monkeypatch the install subprocess."""
    parser = _SubcommandParser(
        prog="splicecraft update",
        add_help=False,
    )
    parser.add_argument("--help", "-h", action="store_true",
                          dest="want_help")
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--force", action="store_true")
    # By default `update` upgrades SpliceCraft's dependencies to the latest
    # versions its pins allow (eager). --keep-deps opts out: upgrade only
    # SpliceCraft itself and leave already-satisfying deps untouched.
    parser.add_argument("--keep-deps", action="store_true", dest="keep_deps")
    parser.add_argument("--yes", "-y", action="store_true",
                          dest="assume_yes")
    parser.add_argument("--list-snapshots", action="store_true",
                          dest="list_snapshots")
    parser.add_argument("--dry-run", action="store_true", dest="dry_run")
    # Pin a specific PyPI version instead of installing latest. Supports
    # downgrade-recovery: if a release ships broken code, the user can
    # roll back to the previous working version without remembering the
    # exact pip incantation. Cannot reuse the flag name `--version`
    # because the outer parser eats it before subcommand dispatch.
    parser.add_argument("--pin", dest="pin_version", default=None,
                          metavar="VERSION",
                          help="install splicecraft==VERSION (downgrade-safe)")
    # Positional alias for `--pin`. The shorter form (`splicecraft
    # update 0.8.10`) is what a panicking user under stress is most
    # likely to type. Validated against `_PINNED_VERSION_RE` below so
    # an accidental file path can't slip into the install command.
    parser.add_argument("version_pos", nargs="?", default=None,
                          metavar="VERSION",
                          help="positional alias for --pin")
    # `--restore-pre-update` accepts an optional ID. argparse's nargs="?"
    # with const=<sentinel> models the trio of historical shapes:
    #   --restore-pre-update            → const sentinel → restore mode, no id
    #   --restore-pre-update foo        → "foo"           → restore mode, id="foo"
    #   --restore-pre-update --flag     → const sentinel → restore mode, no id
    # `--restore-pre-update=` (empty after =) is normalised to None below.
    parser.add_argument(
        "--restore-pre-update",
        nargs="?",
        const=_RESTORE_LIST_SENTINEL,
        default=None,
        metavar="ID",
        dest="restore_raw",
    )
    return parser


def _update_reconcile_pin(args) -> "tuple[str | None, int | None]":
    """Reconcile `--pin X.Y.Z` (flag) vs `splicecraft update X.Y.Z`
    (positional). Returns ``(pin_version, error_code)``:

      * Both `pin_version` and `error_code` are None when no pin was
        requested (normal upgrade path).
      * `pin_version` is the validated string + `error_code` is None
        on a clean pin.
      * `pin_version` is None + `error_code` is an int when validation
        failed; the caller should return that exit code immediately.

    If both flag + positional are given, they must agree — a typo is
    a refusal rather than a silent pick to avoid surprising the user.
    """
    raw_pin = args.pin_version
    if args.version_pos is not None:
        if raw_pin is not None and raw_pin.strip() != args.version_pos.strip():
            print(
                f"splicecraft update: --pin {raw_pin!r} conflicts with "
                f"positional {args.version_pos!r}. Pass one or the other.",
                file=sys.stderr,
            )
            return None, 2
        raw_pin = args.version_pos
    if raw_pin is None:
        return None, None
    pin_version = _validate_pin_version(raw_pin)
    if pin_version is None:
        print(
            f"splicecraft update: {raw_pin!r} is not a recognisable "
            "version string (expected something like 0.8.10, "
            "1.2.3rc1, or v0.9.0).",
            file=sys.stderr,
        )
        return None, 2
    return pin_version, None


def _update_handle_list_snapshots() -> int:
    """Handle `splicecraft update --list-snapshots`: dump the
    pre-update snapshot directory contents and exit. Read-only —
    never touches a snapshot."""
    try:
        backup_dir = _resolve_pre_update_backup_dir()
    except OSError as exc:
        print(f"Could not resolve backup directory: {exc}",
              file=sys.stderr)
        return 1
    snaps = _list_pre_update_snapshots(backup_dir)
    if not snaps:
        print(
            f"No pre-update snapshots in {backup_dir}.\n"
            "Snapshots are taken automatically before each "
            "`splicecraft update` install.")
        return 0
    print(f"Pre-update snapshots in {backup_dir}:")
    print(_format_pre_update_snapshot_table(snaps))
    return 0


def _update_handle_restore(restore_id: "str | None",
                              assume_yes: bool) -> int:
    """Handle `splicecraft update --restore-pre-update [ID]`.

    `restore_id=None` lists the available snapshots and exits 0
    (forces the user to pick explicitly). `"latest"` resolves to the
    most-recent. Any other value is looked up against the backup
    dir; missing → exit 1.

    A pre-restore snapshot is taken first so the restore itself is
    reversible — that's part of the four-restore-checks contract in
    `CLAUDE.md` invariant #39.
    """
    try:
        backup_dir = _resolve_pre_update_backup_dir()
    except OSError as exc:
        print(f"Could not resolve backup directory: {exc}",
              file=sys.stderr)
        return 1
    snaps = _list_pre_update_snapshots(backup_dir)
    if not snaps:
        print(
            f"No pre-update snapshots in {backup_dir}.\n"
            "Nothing to restore.",
            file=sys.stderr)
        return 1
    if restore_id is None:
        print(
            "No snapshot id given. Pick one and re-run with\n"
            "  splicecraft update --restore-pre-update <id>\n"
            "(or pass `latest` to restore the most recent):\n")
        print(_format_pre_update_snapshot_table(snaps))
        return 0
    if restore_id.lower() == "latest":
        chosen = snaps[0]["path"]
    else:
        chosen_path = backup_dir / restore_id
        if not chosen_path.is_dir():
            print(
                f"Snapshot not found: {restore_id!r}\n"
                f"Searched: {backup_dir}\n"
                "Run `splicecraft update --list-snapshots` "
                "to see available ids.",
                file=sys.stderr)
            return 1
        chosen = chosen_path
    print(
        f"About to restore snapshot:\n"
        f"  {chosen.name}\n"
        f"This will OVERWRITE the current contents of:\n"
        f"  library, collections, parts bin, primers, features,\n"
        f"  feature colors, grammars, entry vectors, codon tables,\n"
        f"  settings, crash-recovery autosaves, .dna sidecars\n"
        "A pre-restore snapshot will be taken first so the restore "
        "is reversible."
    )
    if not assume_yes and not _confirm_proceed("Proceed with restore? [y/N] "):
        print("Cancelled.", file=sys.stderr)
        return 130
    _log_event("update.restore.start", snapshot_id=chosen.name)
    try:
        summary = _restore_pre_update_snapshot(
            chosen, backup_dir=backup_dir
        )
    except (OSError, json.JSONDecodeError) as exc:
        _log.exception("restore-pre-update: failed")
        _log_event("update.restore.failed", error=repr(exc),
                   snapshot_id=chosen.name)
        print(f"Restore failed: {exc}", file=sys.stderr)
        return 1
    _log_event(
        "update.restore.ok",
        snapshot_id=chosen.name,
        n_files=len(summary["restored_files"]),
        n_dirs=len(summary["restored_dirs"]),
        n_failed=len(summary["failed"]),
    )
    print("\nRestore complete.")
    print(f"  Pre-restore snapshot: {summary['pre_restore_snapshot']}")
    print(f"  Files restored:  {len(summary['restored_files'])}  "
          f"({', '.join(summary['restored_files']) or '(none)'})")
    print(f"  Dirs restored:   {len(summary['restored_dirs'])}  "
          f"({', '.join(summary['restored_dirs']) or '(none)'})")
    if summary["failed"]:
        print(f"  Failed entries: {len(summary['failed'])}",
              file=sys.stderr)
        for name, reason in summary["failed"]:
            print(f"    - {name}: {reason}", file=sys.stderr)
        return 1
    return 0


def _developer_install_dir(info: dict) -> str:
    """A DIRECTORY suitable for `cd` in developer-install refusal guidance:
    the working-tree root (`git_clone`) when known, else the module's PARENT
    dir — never the bare module path, which would `cd` into a `.py` file
    (the editable branch used to leave `git_clone` unset, so the fallback
    printed `cd …/splicecraft.py`)."""
    target = info.get("git_clone")
    if target:
        return str(target)
    mod = info.get("module") or ""
    return str(Path(mod).parent) if mod else "(unknown)"


def _update_refuse_unsupported_install(method: str, info: dict,
                                          cmd: "list[str] | None"
                                          ) -> "int | None":
    """Check whether the detected install method is one we refuse to
    auto-upgrade (editable / source / pixi-project / pip-system) or
    whether the upgrade front-end isn't on PATH.

    Returns:
      * an exit code if the upgrade should be refused (caller exits)
      * `None` if the upgrade can proceed.

    These are split out from `_run_update_subcommand` because the
    refusal messages are long enough to crowd the dispatcher and the
    refusal logic is testable in isolation without monkeypatching
    `subprocess.run`.
    """
    if method in ("editable", "source"):
        target = _developer_install_dir(info)
        print(
            f"\nThis SpliceCraft is a developer install ({method}) at {target}.\n"
            "Refusing to overwrite a developer install with a PyPI build.\n"
            "Update it from the source tree instead:\n"
            f"  cd {target}\n"
            "  git pull",
            file=sys.stderr,
        )
        return 1
    if method == "pixi-project":
        target = _developer_install_dir(info)
        print(
            f"\nThis SpliceCraft is in a pixi-managed project env at {target}.\n"
            "Refusing to bypass the project manifest with a direct PyPI install.\n"
            "Update the project's pinned version instead:\n"
            f"  cd {target}\n"
            "  pixi update splicecraft",
            file=sys.stderr,
        )
        return 1
    if cmd is None:
        print(
            f"Don't know how to upgrade a {method!r} install automatically.",
            file=sys.stderr,
        )
        return 1
    if method == "pip-system":
        print(
            "\nThis is a system-wide install. Run the upgrade yourself:\n"
            f"  sudo {' '.join(cmd)}\n"
            "Or migrate to an isolated user-level install via:\n"
            "  python3 -m pip install --user pipx && pipx install splicecraft\n"
            "  uv tool install splicecraft     "
            "(https://docs.astral.sh/uv/)\n"
            "  pixi global install splicecraft "
            "(https://pixi.sh)",
            file=sys.stderr,
        )
        return 1
    front_end = cmd[0]
    needs_external = method in (
        "pipx", "uv-tool", "uv-venv", "pixi-global"
    )
    if needs_external and shutil.which(front_end) is None:
        homepage = _MANAGER_HOMEPAGES.get(front_end, "")
        suffix = f"\nOr reinstall {front_end} ({homepage})." if homepage else ""
        print(
            f"\nDetected a {method} install, but `{front_end}` isn't on PATH.\n"
            f"Open a shell where {front_end} is available and run:\n"
            f"  {' '.join(cmd)}"
            f"{suffix}",
            file=sys.stderr,
        )
        return 1
    return None


def _update_take_snapshot(pin_version: "str | None"
                            ) -> "tuple[Path | None, int | None]":
    """Take the pre-install snapshot (sacred invariant #39).

    Returns ``(snap_path, None)`` on success or ``(None, exit_code)``
    on failure. The caller MUST exit immediately on a failed snapshot
    — running the install without one violates invariant #39.
    """
    print("Snapshotting user data before update…", flush=True)
    _log_event("update.snapshot.start", from_version=__version__,
               pin=pin_version or "")
    try:
        snap_path = _create_pre_update_snapshot(__version__)
    except (OSError, shutil.Error) as exc:
        _log.exception("pre-update snapshot failed")
        _log_event("update.snapshot.failed", error=repr(exc))
        print(
            f"\nABORTING: could not snapshot user data before the upgrade.\n"
            f"  Reason: {exc}\n"
            "Refusing to proceed without a recoverable copy of your "
            "library, collections, parts bin, and primers. Free up disk "
            "space, fix permissions on the backup directory, and retry. "
            "(Override the location with $SPLICECRAFT_UPDATE_BACKUP_DIR.)",
            file=sys.stderr,
        )
        return None, 1
    _log_event("update.snapshot.ok", path=_scrub_path(str(snap_path)))
    print(f"  ✓ Snapshot saved: {snap_path}")
    return snap_path, None


def _query_installed_version(timeout: float = 15.0) -> "str | None":
    """Return the splicecraft version installed in THIS interpreter's
    environment, read in a FRESH subprocess.

    Why a subprocess (not `__version__`, not an in-process
    `importlib.metadata` read): after `splicecraft update` runs the
    upgrade, the new code is on disk but the running process still holds
    the OLD `__version__`, and an in-process metadata read can be stale
    (the dist-info was swapped underneath us). A fresh `sys.executable`
    subprocess re-scans site-packages and reports what ACTUALLY landed —
    the only trustworthy post-upgrade check. `sys.executable` is the
    install's own interpreter (the `splicecraft` console script runs
    under the pipx / uv / venv python), so it sees exactly the
    environment the upgrade modified.

    Returns the version string (≤64 chars), or None when it can't be
    determined (subprocess error, missing metadata, timeout, empty/junk
    output) — the caller treats None as "couldn't verify", NEVER as
    success.
    """
    try:
        proc = subprocess.run(
            [sys.executable, "-c",
             "import importlib.metadata as m;print(m.version('splicecraft'))"],
            check=False, capture_output=True, text=True, timeout=timeout,
        )
    except (OSError, subprocess.SubprocessError):
        return None
    if getattr(proc, "returncode", 1) != 0:
        return None
    out = (getattr(proc, "stdout", None) or "").strip().splitlines()
    if not out:
        return None
    v = out[-1].strip()[:64]
    return v or None


# ── Stale-daemon detection (petunia agent-API snag) ──────────────────────────
# A long-running `--agent` daemon keeps serving the OLD code after
# `splicecraft update` swaps the package on disk — silently. An agent driving
# the daemon then talks to pre-update code with no signal. `status` surfaces the
# on-disk installed version next to the running `__version__` so the skew is
# visible (and a `stale` flag flips when they diverge). The on-disk read shells
# out (the only post-upgrade-trustworthy source — see `_query_installed_version`),
# so it is CACHED with a TTL and refreshed OFF-THREAD: `status` is polled in tight
# readiness loops and must never pay the subprocess cost inline.
_INSTALLED_VERSION_TTL = 300.0  # re-check the on-disk version at most every 5 min
_INSTALLED_VERSION_CACHE: dict = {"version": None, "ts": 0.0, "inflight": False}
# Guards the `inflight` check-then-set so a UI status poll and an agent `status`
# handler (server thread) can't both see inflight=False and each spawn a
# `splicecraft --version` subprocess.
_INSTALLED_VERSION_LOCK = threading.Lock()


def _installed_version_worker() -> None:
    """Background refresh body — query once, stamp the cache, clear the
    in-flight flag. Never raises (a daemon thread that escaped would be
    invisible)."""
    cache = _INSTALLED_VERSION_CACHE
    try:
        v = _query_installed_version(timeout=8.0)
    except Exception:                    # pragma: no cover - defensive
        v = None
    cache["version"] = v
    cache["ts"] = _monotonic()
    cache["inflight"] = False


def _installed_version_cached(*, blocking: bool = False) -> "str | None":
    """Best-effort on-disk installed splicecraft version, cached.

    Non-blocking by default: returns the last cached result (``None``
    until the first check completes) and kicks a background refresh when
    the cache has aged past ``_INSTALLED_VERSION_TTL``. The refresh fires
    only when a real app/daemon is live (``_LIVE_APP_REF`` set) so the
    pure-handler test path never spawns a subprocess. Pass
    ``blocking=True`` (tests, CLI) to wait for a fresh subprocess read."""
    cache = _INSTALLED_VERSION_CACHE
    now = _monotonic()
    fresh = bool(cache["ts"]) and (now - cache["ts"]) < _INSTALLED_VERSION_TTL
    if fresh:
        return cache["version"]
    if blocking:
        v = _query_installed_version(timeout=8.0)
        cache["version"], cache["ts"] = v, _monotonic()
        return v
    if _state._LIVE_APP_REF.get() is not None:
        spawn = False
        with _INSTALLED_VERSION_LOCK:
            if not cache["inflight"]:
                cache["inflight"] = True
                spawn = True
        if spawn:
            try:
                threading.Thread(target=_installed_version_worker,
                                 name="sc-installed-ver", daemon=True).start()
            except RuntimeError:         # pragma: no cover - interpreter teardown
                with _INSTALLED_VERSION_LOCK:
                    cache["inflight"] = False
    return cache["version"]


def _update_run_install(cmd: "list[str]", snap_path: Path,
                          method: str,
                          pin_version: "str | None",
                          latest_version: "str | None" = None) -> int:
    """Actually run the install subprocess, VERIFY the new version, and
    report the result.

    Pre-condition: the snapshot at `snap_path` was successfully created
    (sacred invariant #39).

    Post-upgrade verification (2026-06-09): a subprocess that exits 0 is
    NOT proof the upgrade took effect. Right after a release, PyPI's
    Simple-API index (what pip/pipx resolve against) can lag its JSON
    metadata (what our update CHECK reads) by a minute or two — so the
    check sees the new version, runs `pipx upgrade`, and pipx, still
    seeing the old version as latest, no-ops and exits 0. We therefore
    re-read the ACTUALLY-installed version (`_query_installed_version`,
    a fresh subprocess) and report success only if it reached the
    target; otherwise we say so honestly and exit non-zero, instead of
    printing "Upgrade complete." over an unchanged install (the user
    report that motivated this). A pin must match EXACTLY (it's a
    precise request, incl. downgrades); a plain upgrade is satisfied by
    reaching ≥ the target.
    """
    _log_event("update.install.start", method=method,
               pin=pin_version or "", front_end=cmd[0])
    try:
        result = subprocess.run(cmd, check=False)
    except FileNotFoundError:
        _log_event("update.install.front_end_missing", front_end=cmd[0])
        print(
            f"Command not found: {cmd[0]!r}.  "
            "Install the matching package manager and retry.\n"
            f"(Pre-update snapshot is intact at {snap_path}.)",
            file=sys.stderr,
        )
        return 127
    except (OSError, subprocess.SubprocessError) as exc:
        _log.exception("splicecraft update: subprocess failed")
        _log_event("update.install.subprocess_error", error=repr(exc))
        print(
            f"Update failed to launch: {exc}\n"
            f"(Pre-update snapshot is intact at {snap_path}.)",
            file=sys.stderr,
        )
        return 1
    rc = int(result.returncode or 0)
    _log_event("update.install.end", returncode=rc, method=method,
               pin=pin_version or "")

    if rc != 0:
        print(
            f"\nUpgrade command exited with status {rc}. "
            "See output above for details.\n"
            "\n"
            "If the output mentions “failed to build” a package or "
            "“Python.h: No such file or directory”, a dependency had "
            "no prebuilt wheel for your Python/CPU and tried to compile "
            "without a C toolchain. Install one, then retry:\n"
            "  • Debian/Ubuntu/Pi:  sudo apt install build-essential python3-dev\n"
            "  • Fedora/RHEL:       sudo dnf install gcc gcc-c++ python3-devel\n"
            "  • macOS:             xcode-select --install\n"
            "  (full guide: the Troubleshooting section of docs/install.md)\n"
            f"\nYour pre-update snapshot is intact at:\n"
            f"  {snap_path}\n"
            "If your data ended up corrupted, run:\n"
            f"  splicecraft update --restore-pre-update {snap_path.name}",
            file=sys.stderr,
        )
        return rc

    # ── rc == 0: VERIFY the upgrade actually changed the version ──────
    # (See the function docstring: exit 0 ≠ "it upgraded".)
    target = pin_version if pin_version is not None else latest_version
    installed = _query_installed_version()
    if installed is None:
        # Ran fine, but we couldn't read the version back — don't claim
        # a success we can't confirm. The command itself succeeded, so
        # we still exit 0, but we tell the user to check.
        _log_event("update.install.unverified", method=method,
                   target=target or "")
        print("\nUpgrade command finished (exit 0).")
        print(
            "  Couldn't automatically confirm the new version.\n"
            f"  You were on splicecraft {__version__}; check the version "
            "after relaunching."
        )
        print(f"  Pre-update snapshot: {snap_path}")
        return rc

    pi = _parse_pypi_version(installed)
    pt = _parse_pypi_version(target) if target else None
    if target is None:
        # No explicit target (shouldn't happen on this path) — treat any
        # change from the running version as success.
        reached = installed.strip() != __version__.strip()
    elif pi is not None and pt is not None:
        reached = (pi == pt) if pin_version is not None else (pi >= pt)
    else:
        # One side isn't canonically parseable (pre-release pin, odd
        # PyPI string) — fall back to exact string match.
        reached = installed.strip() == target.strip()

    if not reached:
        _log_event("update.install.version_mismatch",
                   installed=installed, target=target or "", was=__version__)
        if installed.strip() == __version__.strip():
            # No change at all — the classic post-release index skew.
            print(
                "\nThe upgrade command reported success, but splicecraft is "
                f"STILL {installed}"
                + (f" — it did not update to {target}." if target else "."),
                file=sys.stderr,
            )
            print(
                "  • This is almost always a timing issue right after a new\n"
                "    release: PyPI can take a minute or two to make a new\n"
                "    version installable even once it's listed.\n"
                "  • Wait a minute or two, then run `splicecraft update` again.\n"
                "  • If it's still stuck after several minutes, force a clean\n"
                "    reinstall:\n"
                "      splicecraft update --force\n"
                f"  Pre-update snapshot: {snap_path}",
                file=sys.stderr,
            )
        else:
            # Changed, but not to the expected version — surface it raw.
            print(
                "\nThe upgrade command reported success, but the installed "
                f"version is {installed}, not the expected {target} "
                f"(you were on {__version__}).",
                file=sys.stderr,
            )
            print(
                "  • Re-run `splicecraft update` to retry"
                + (f", or pin it explicitly:\n"
                   f"      splicecraft update --pin {target}" if target else "")
                + f"\n  Pre-update snapshot: {snap_path}",
                file=sys.stderr,
            )
        return 1

    # ── Verified success ─────────────────────────────────────────────
    _log_event("update.install.verified", installed=installed,
               was=__version__, method=method)
    print("\nUpgrade complete.")
    if installed.strip() != __version__.strip():
        print(f"  splicecraft {__version__} → {installed}")
    else:
        # --force reinstall of the same version (or already current).
        print(f"  splicecraft {installed} (reinstalled)")
    print(f"  Pre-update snapshot: {snap_path}")
    print(
        "  If anything looks wrong on the new version, restore with:\n"
        f"    splicecraft update --restore-pre-update {snap_path.name}"
    )
    return rc


def _run_update_subcommand(argv: "list[str]") -> int:
    """Entry point for `splicecraft update`. Returns a shell exit
    code. Never raises — every failure path is converted to a printed
    message + numeric exit code.

    Emits ``update.subcommand.*`` structured events at every decision
    point so a malfunctioning updater can be diagnosed from a single
    log paste (see invariant #42 in CLAUDE.md).

    Pre-refactor this was a 532-line behemoth; the per-branch work
    has been split into the `_update_*` helpers above. The dispatcher
    here is the only place where the order of operations is
    visible — sacred invariant #39 (snapshot ALWAYS happens before
    `subprocess.run(install_cmd)`) is enforced by the fact that
    `_update_take_snapshot` is called BEFORE `_update_run_install`,
    with an early-exit on snapshot failure.
    """
    _log_event("update.subcommand.start", argv=list(argv))
    parser = _update_build_parser()

    try:
        args = parser.parse_args(list(argv))
    except _CliExit as exc:
        return exc.code

    if args.want_help:
        print(_UPDATE_HELP_TEXT)
        return 0

    restore_mode = args.restore_raw is not None
    if restore_mode and args.restore_raw not in (_RESTORE_LIST_SENTINEL, ""):
        restore_id: str | None = args.restore_raw
    else:
        restore_id = None

    pin_version, pin_err = _update_reconcile_pin(args)
    if pin_err is not None:
        return pin_err

    # `--check` and `--dry-run` are mutually exclusive: `--check` skips
    # the snapshot (read-only); `--dry-run` exercises everything up to
    # but not including the install. Allowing both would be ambiguous.
    if args.check and args.dry_run:
        print(
            "splicecraft update: --check and --dry-run are mutually "
            "exclusive. --check is read-only; --dry-run exercises the "
            "snapshot pipeline without installing.",
            file=sys.stderr,
        )
        return 2

    # A pin is incompatible with the listing/restore modes — those
    # don't touch the install at all. Refuse the ambiguous combo so
    # the user isn't surprised by which one wins.
    if pin_version is not None and (args.list_snapshots or restore_mode):
        print(
            "splicecraft update: --pin / positional version cannot be "
            "combined with --list-snapshots or --restore-pre-update. "
            "Those flags inspect / roll back local snapshots; they "
            "don't install anything.",
            file=sys.stderr,
        )
        return 2

    # ── Listing / restore early-exit branches (no PyPI fetch needed) ──
    if args.list_snapshots:
        return _update_handle_list_snapshots()

    if restore_mode:
        return _update_handle_restore(restore_id, args.assume_yes)

    # ── Upgrade path: detect install method, hit PyPI, compare ────────
    if pin_version is not None:
        print(
            f"SpliceCraft {__version__} — pinning install to "
            f"{pin_version}…", flush=True
        )
    else:
        print(f"SpliceCraft {__version__} — checking for updates…", flush=True)
    info = _detect_install_method()
    method = info["method"]

    # Hit PyPI for the latest released version. `_fetch_latest_pypi_version`
    # is already timeout-bounded (3 s) and size-capped, so this can't hang
    # the terminal. Returns None on any failure (network, parse, cap).
    # When pinning, the user has already chosen the exact version, so a
    # PyPI failure here is informational only (we still proceed). When
    # NOT pinning, we need a latest to compare against — abort on failure.
    _fetch_reason: "list[str]" = []
    latest = _fetch_latest_pypi_version(reason_out=_fetch_reason)
    if latest is None and pin_version is None:
        # Report the TRUE cause. Collapsing every failure to "Could not
        # reach PyPI" was the v1.0.36 mis-report: an oversized-but-
        # reachable response looked like an offline one, sending users
        # to debug a network that was fine. Each reason now self-explains.
        reason = _fetch_reason[0] if _fetch_reason else _PYPI_FETCH_NETWORK
        if reason == _PYPI_FETCH_OVERSIZE:
            print(
                "PyPI returned an unexpectedly large response, so the latest\n"
                "version couldn't be read (PyPI itself is reachable).\n"
                "  • This usually means SpliceCraft's metadata outgrew an\n"
                "    internal size limit — please report it so the cap can\n"
                "    be raised.\n"
                "  • Meanwhile, upgrade manually (see install method below).\n"
                f"You are currently on splicecraft {__version__}.",
                file=sys.stderr,
            )
        elif reason == _PYPI_FETCH_PARSE:
            print(
                "PyPI returned a response that couldn't be read as valid data,\n"
                "so the latest version is unknown (PyPI itself is reachable).\n"
                "  • This is usually transient — try again in a moment.\n"
                "  • If it persists, upgrade manually (see install method below).\n"
                f"You are currently on splicecraft {__version__}.",
                file=sys.stderr,
            )
        elif reason == _PYPI_FETCH_SCHEMA:
            print(
                "PyPI's response didn't contain a recognisable version number,\n"
                "so the latest version is unknown (PyPI itself is reachable).\n"
                "  • Try again in a moment; if it persists, please report it.\n"
                "  • Meanwhile, upgrade manually (see install method below).\n"
                f"You are currently on splicecraft {__version__}.",
                file=sys.stderr,
            )
        else:  # _PYPI_FETCH_NETWORK (or an unknown/empty reason)
            print(
                "Could not reach PyPI to check the latest version.\n"
                "  • Check your network connection.\n"
                "  • Try again in a moment (PyPI's CDN may be slow).\n"
                f"You are currently on splicecraft {__version__}.",
                file=sys.stderr,
            )
        # Surface install method so the user can fall back to manual upgrade.
        if method != "unknown":
            print(f"Install method: {method} ({info['details']})", file=sys.stderr)
        return 1

    is_newer = (latest is not None) and _is_newer_pypi_version(latest, __version__)
    same_version = (latest is not None and latest.strip() == __version__.strip())
    print(f"  Local : {__version__}")
    if pin_version is not None:
        print(f"  Pin   : {pin_version}")
        if latest is not None:
            print(f"  PyPI  : {latest}")
    else:
        print(f"  PyPI  : {latest}")
    print(f"  Method: {method}  ({info['details']})")

    # No upgrade needed and not forcing.
    if pin_version is None and not is_newer and not args.force:
        if same_version:
            print("You're on the latest released version. Nothing to do.")
        else:
            # Local is newer than PyPI (e.g. dev build, pre-release, or
            # PyPI returned a non-canonical string we can't compare).
            # Don't auto-downgrade.
            print(
                "Your local version doesn't appear to be older than PyPI's. "
                "Nothing to do.\n"
                "Pass --force to reinstall anyway."
            )
        return 0

    # Pinning to the currently-installed version is a no-op unless
    # --force is also set (then it re-runs the install end-to-end,
    # useful for fixing a corrupted site-packages).
    if pin_version is not None and pin_version == __version__ and not args.force:
        print(
            f"\nYou're already on splicecraft {pin_version}. Nothing to "
            "do.\nPass --force to reinstall anyway."
        )
        return 0

    cmd = _build_upgrade_command(method, force=args.force,
                                   pin_version=pin_version,
                                   eager=not args.keep_deps)
    # Refuse upgrades for install methods we don't auto-handle
    # (editable / source / pixi-project / pip-system) or where the
    # upgrade front-end isn't on PATH.
    refused = _update_refuse_unsupported_install(method, info, cmd)
    if refused is not None:
        return refused

    if args.check:
        assert cmd is not None  # refused-path returned above (assert narrows for pyright)
        print("\nUpdate available." if is_newer else "\nForce flag set.")
        print("To upgrade, run:")
        print(f"  {' '.join(cmd)}")
        print("Or simply:  splicecraft update")
        return 0

    # Defence-in-depth: if `_state._DATA_DIR` is *inside* the install path
    # (e.g. user pointed $SPLICECRAFT_DATA_DIR at site-packages), an
    # upgrade would wipe the user's library along with the package.
    # Refuse to proceed before we even take the snapshot — the
    # snapshot lives next to `_state._DATA_DIR` and would be on the chopping
    # block too. The user has to move their data dir first.
    if _data_dir_inside_install_path():
        print(
            f"\nUNSAFE CONFIGURATION: your data directory ({_state._DATA_DIR}) "
            f"is inside the SpliceCraft install path. An upgrade would "
            "destroy your library, collections, parts bin, and primers.\n"
            "Refusing to proceed.\n"
            "Move your data elsewhere and re-point $SPLICECRAFT_DATA_DIR:\n"
            "  export SPLICECRAFT_DATA_DIR=$HOME/.local/share/splicecraft\n"
            "  mkdir -p $SPLICECRAFT_DATA_DIR\n"
            f"  mv {_state._DATA_DIR}/* $SPLICECRAFT_DATA_DIR/  # then retry the update",
            file=sys.stderr,
        )
        return 1

    # Pinning-direction banner: if the pin is older than the running
    # version, surface that explicitly so the user doesn't get
    # surprised. A downgrade is the recovery path after a bad release;
    # it's a feature, but it deserves a clear callout.
    if pin_version is not None:
        try:
            is_downgrade = _is_newer_pypi_version(__version__, pin_version)
        except Exception:
            is_downgrade = False
        if is_downgrade:
            print(
                f"\nThis is a DOWNGRADE: splicecraft {__version__} → "
                f"{pin_version}.\n"
                "Your data is snapshotted before the install runs, so "
                "the rollback itself is reversible (see "
                "`splicecraft update --restore-pre-update latest`)."
            )
        elif pin_version != __version__:
            print(
                f"\nInstalling splicecraft {pin_version} (currently "
                f"on {__version__})."
            )

    assert cmd is not None  # refused-path returned above (assert narrows for pyright)
    print(f"\nWill run:  {' '.join(cmd)}")
    if not args.assume_yes:
        if not _confirm_proceed():
            print("Cancelled.", file=sys.stderr)
            return 130

    # ── SACRED INVARIANT #39 ──────────────────────────────────────
    # Snapshot the user's library, collections, parts bin, primers,
    # feature library, custom grammars, codon tables, settings,
    # crash-recovery autosaves, and .dna sidecars BEFORE invoking
    # the install subprocess. If the snapshot can't be made for any
    # reason (disk full, permission denied, refused config), abort
    # the upgrade — it is NEVER acceptable to risk destroying user
    # data without a recoverable copy first. Tested by
    # `test_update_snapshot_taken_before_subprocess` in tests/test_smoke.py.
    snap_path, snap_err = _update_take_snapshot(pin_version)
    if snap_err is not None:
        return snap_err
    assert snap_path is not None  # snap_err None ⇒ path present

    # `--dry-run` short-circuits HERE: we've gone all the way through
    # detection + PyPI fetch + snapshot, but we don't actually run the
    # install. Useful for verifying the snapshot pipeline works on a
    # given machine, for CI smoke-checks, and for documenting the
    # exact command an automated workflow would run.
    if args.dry_run:
        print(
            "\n[dry-run] No install was run. Snapshot is intact at:\n"
            f"  {snap_path}\n"
            f"To actually upgrade, re-run without --dry-run:\n"
            f"  {' '.join(cmd)}"
        )
        return 0

    return _update_run_install(cmd, snap_path, method, pin_version,
                               latest_version=latest)


# ── Fetch modal ────────────────────────────────────────────────────────────────

class FetchModal(_OneShotDismissScreen, ModalScreen):
    """NCBI Entrez fetch dialog — accession + email Inputs."""

    _blocks_undo: bool = True   # Input editing; Ctrl+Z = input undo, not app

    BINDINGS = [
        Binding("escape", "cancel", "Cancel"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    def compose(self) -> ComposeResult:
        with Vertical(id="fetch-box"):
            yield Static(" Fetch GenBank Record ", id="fetch-title")
            yield Label("NCBI Accession  (e.g.  M77789  for pUC19,  Y14837  for pUC57):")
            yield Input(placeholder="MW463917.1", id="fetch-acc", value="MW463917.1")
            yield Label("Email  (required by NCBI Entrez):")
            yield Input(placeholder="you@example.com", id="fetch-email")
            with Horizontal(id="fetch-btns"):
                yield Button("Fetch", id="btn-fetch", variant="primary")
                yield Button("Cancel", id="btn-cancel-fetch")
            yield Static("", id="fetch-status", markup=True)

    @on(Button.Pressed, "#btn-fetch")
    def _fetch(self):
        acc   = self.query_one("#fetch-acc",   Input).value.strip()
        email = self.query_one("#fetch-email", Input).value.strip() or "splicecraft@local"
        if not acc:
            self.query_one("#fetch-status", Static).update("[red]Enter an accession.[/red]")
            return
        self.query_one("#fetch-status", Static).update(
            f"[dim]Fetching {acc!r} from NCBI…[/dim]"
        )
        self._do_fetch(acc, email)

    @work(thread=True, exclusive=True, group="ncbi_fetch")
    def _do_fetch(self, acc: str, email: str):
        try:
            record = fetch_genbank(acc, email)
        except Exception as exc:
            _log.exception("NCBI fetch failed for %s", acc)
            # Capture the message BEFORE building the closure. Python 3
            # deletes the `except` binding (`exc`) at scope exit, so the
            # closure that runs later via `call_from_thread` would crash
            # with `NameError: cannot access free variable 'exc'` every
            # time NCBI errors out. Caught by Harley King (har1eyk) in
            # the closed PR #7 — thank you, Harley.
            err_msg = str(exc)
            def _err():
                # Modal may have been dismissed while the fetch was in flight;
                # query_one would then raise NoMatches. Fall back to a toast.
                if not self.is_mounted:
                    try:
                        self.app.notify(f"NCBI fetch failed: {err_msg}",
                                        severity="error", timeout=8)
                    except Exception:
                        _log.exception("notify fallback for fetch error failed")
                    return
                try:
                    self.query_one("#fetch-status", Static).update(
                        f"[red]Error: {err_msg}[/red]"
                    )
                except NoMatches:
                    try:
                        self.app.notify(f"NCBI fetch failed: {err_msg}",
                                        severity="error", timeout=8)
                    except Exception:
                        _log.exception("notify fallback for fetch error failed")
            self.app.call_from_thread(_err)
            return

        # Staleness guard: user may have hit Escape (which runs `dismiss(None)`
        # via action_cancel) while the HTTP round-trip was in flight. Calling
        # `self.dismiss(record)` on an already-dismissed modal raises, and even
        # if it didn't, we'd be stomping whatever the user did next. Silently
        # drop the fetched record if the modal is no longer mounted.
        def _apply():
            if not self.is_mounted:
                _log.info(
                    "Fetch %s completed after modal was dismissed; discarding.",
                    acc,
                )
                return
            self.dismiss(record)
        self.app.call_from_thread(_apply)

    @on(Input.Submitted)
    def _submitted(self):
        self.query_one("#btn-fetch", Button).press()

    @on(Button.Pressed, "#btn-cancel-fetch")
    def _cancel_btn(self):
        self.dismiss(None)

    def action_cancel(self):
        self.dismiss(None)


# ── Open-file modal ────────────────────────────────────────────────────────────

class OpenFileModal(ModalScreen):
    """Plasmid-file open dialog. Browse the filesystem via a
    DirectoryTree and pick a `.gb` / `.gbk` / `.dna` / `.genbank` file
    (highlighted in lime green); other files render in white but stay
    selectable for users who saved a plasmid under a non-canonical
    extension. Pre-2026-05-06 this was a free-typed path Input, which
    forced users to remember absolute paths and made typo recovery
    awkward.

    On Open, dismisses with a parsed `SeqRecord`. On Cancel / Esc,
    dismisses with `None`. The async `load_genbank` worker (with the
    "Parsing…" indicator + button-disable + stale-modal guard) is
    unchanged from the previous typed-path version — only the path-
    selection UI was swapped.
    """

    _blocks_undo: bool = True   # filename Input + record import

    BINDINGS = [
        Binding("escape", "cancel", "Cancel"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    def __init__(self, start_path: "str | None" = None) -> None:
        super().__init__()
        # Default to $HOME because the alternative ($PWD when the user
        # launched from a deep path) is often a noisy starting point.
        # Tests pass an explicit `start_path` to scope the tree to the
        # tmp dir.
        start = Path(start_path).expanduser() if start_path else Path.home()
        try:
            if not start.is_dir():
                start = Path.home()
        except OSError:
            start = Path.home()
        self._start = str(start)
        self._selected: "str | None" = None
        # Sweep #26: [INV-50] dismiss-once guard. Cancel button +
        # Esc + worker-success + FASTA-success = four exit paths
        # that all called `self.dismiss(...)` directly; the worker
        # success vs user cancel race is real because the worker
        # completes on a different tick.
        self._dismissed: bool = False

    def compose(self) -> ComposeResult:
        with Vertical(id="open-box"):
            yield Static(" Open Plasmid File ", id="open-title")
            yield Static(
                f"[dim]{self._start}[/dim]", id="open-header", markup=True,
            )
            yield _ExtensionAwareDirectoryTree(
                self._start,
                highlight_map=_PLASMID_PICKER_HIGHLIGHT_MAP,
                id="open-tree",
            )
            yield Static(
                "[dim]"
                "[#BFFF00].gb / .gbk / .genbank[/]   "
                "[#FFA500].dna[/]   "
                "[#FF69B4].fa / .fasta / .fna[/]"
                "[/dim]",
                id="open-hint", markup=True,
            )
            yield Static("", id="open-status", markup=True)
            with Horizontal(id="open-btns"):
                yield Button("Open", id="btn-open",
                              variant="primary", disabled=True)
                yield Button("Cancel", id="btn-cancel-open")

    def on_mount(self) -> None:
        try:
            self.query_one("#open-tree",
                            _ExtensionAwareDirectoryTree).focus()
        except NoMatches:
            pass

    @on(DirectoryTree.FileSelected, "#open-tree")
    def _on_file_selected(self, event) -> None:
        # Highlighting + Open button enable mirror the FastaFilePickerModal
        # pattern. Status line is cleared so a previous error toast doesn't
        # bleed across selections.
        self._selected = str(event.path)
        try:
            self.query_one("#open-header", Static).update(
                f"[dim]{self._selected}[/dim]"
            )
            self.query_one("#btn-open", Button).disabled = False
            self.query_one("#open-status", Static).update("")
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-open")
    def _open(self):
        path = self._selected
        status = self.query_one("#open-status", Static)
        if not path:
            status.update("[red]Pick a file first.[/red]")
            return
        # Probe size BEFORE invoking the parser — avoids a 30 s
        # parse on a 50 MB file the user clicked by accident.
        # lstat (not stat) so a symlink reports the symlink itself rather
        # than its target — defends against the "symlink to /dev/zero
        # reports st_size = 0, bypassing the large-file confirm" pathology.
        # The actual load path (`load_genbank`) goes through
        # `_safe_file_size_check` which rejects symlinks outright; we
        # refuse here at the confirm-probe step to match that policy
        # (and to avoid the confusing UX of "confirm a huge file" then
        # "load failed: refused symlink").
        try:
            import stat as _stat_mod
            p_resolved = Path(path).expanduser()
            p_stat = p_resolved.lstat()
            if _stat_mod.S_ISLNK(p_stat.st_mode):
                try:
                    self.query_one("#open-status", Static).update(
                        "[red]Refusing to open a symlink. Open the "
                        "real file directly.[/red]"
                    )
                except NoMatches:
                    pass
                return
            size_bytes = p_stat.st_size
        except OSError:
            size_bytes = 0
        if size_bytes > _LARGE_LOAD_DISK_BYTES:
            # Push the confirm modal on top; on Yes proceed with the
            # actual load, on No just leave the OpenFileModal open so
            # the user can pick a different file. Default focus is on
            # No inside the confirm so a stray Enter bails out.
            size_mb = size_bytes / (1024 * 1024)

            def _confirmed(ok: "bool | None") -> None:
                if not ok:
                    return
                self._actually_load(path)

            self.app.push_screen(
                LargeFileConfirmModal(
                    description=path,
                    size_text=f"{size_mb:.1f} MB on disk",
                    threshold_text=(
                        f"Threshold: > "
                        f"{_LARGE_LOAD_DISK_BYTES // (1024 * 1024)} MB. "
                        f"Parsing + first render may take many seconds."
                    ),
                ),
                callback=_confirmed,
            )
            return
        self._actually_load(path)

    def _actually_load(self, path: str) -> None:
        status = self.query_one("#open-status", Static)
        # Show an immediate "Parsing…" indicator so the user knows
        # something is happening while the worker runs. Without this
        # the modal looks frozen during a multi-second parse on big
        # files (.dna with deep history XML, BAC/cosmid records).
        status.update(f"[dim]Parsing {path!r}…[/dim]")
        # Disable the buttons during the parse so a second click can't
        # spawn a parallel parse on the same path.
        try:
            self.query_one("#btn-open",        Button).disabled = True
            self.query_one("#btn-cancel-open", Button).disabled = True
        except NoMatches:
            pass
        self._do_load(path)

    @work(thread=True, exclusive=True, group="file_open_load")
    def _do_load(self, path: str) -> None:
        """Background loader: dispatches by file extension + record count.

        `.gb` / `.gbk` / `.dna` / `.genbank` go through `load_genbank`
        as before — single-record only.

        FASTA files (`.fa` / `.fasta` / `.fna` / etc.) split by record
        count: a single-record FASTA is wrapped in a fresh SeqRecord
        with `topology="linear"` and dismisses the modal directly. A
        MULTI-record FASTA hands off to `_handle_multi_record_fasta`
        on the UI thread, which prompts the user to name a new
        collection and (on confirm) loads every record into it.

        Background-threaded since 2026-05-06: parsing a large `.gb` /
        `.dna` (multi-MB chromosome dump, `.dna` with rich history XML)
        can take 1–3 s on the UI thread; running it here keeps the
        modal interactive (Esc still cancels). On success the modal
        dismisses with the record; on failure the status line shows
        the error and the buttons re-enable.
        """
        try:
            if _is_fasta_path(path):
                # Sweep #27: hard size-cap BEFORE SeqIO.parse. The
                # downstream `list(SeqIO.parse(...))` is eager — a
                # multi-GB FASTA pasted into the Open dialog would
                # OOM the worker before any record-count check fires.
                # _FASTA_MAX_BYTES mirrors `_GB_TEXT_MAX_BYTES`'s
                # ceiling, scaled for the fact that FASTA carries
                # only the bare sequence (no annotation envelope).
                from pathlib import Path as _Path
                ok, reason = _safe_file_size_check(
                    _Path(path), _FASTA_MAX_BYTES, "fasta",
                )
                if not ok:
                    raise ValueError(
                        reason
                        or f"FASTA exceeds {_FASTA_MAX_BYTES:,} bytes."
                    )
                from Bio import SeqIO
                try:
                    parsed = list(SeqIO.parse(path, "fasta"))
                except (OSError, ValueError) as exc:
                    raise ValueError(
                        f"Failed to read FASTA: {exc}"
                    ) from exc
                if not parsed:
                    raise ValueError(
                        "No FASTA records found in file."
                    )
                if len(parsed) > 1:
                    # Hand off to the UI thread; it pushes the
                    # collection-name modal and dismisses self with a
                    # `fasta_collection` payload once the user
                    # confirms. The worker exits here so the dismiss-
                    # with-record path below doesn't fire.
                    self.app.call_from_thread(
                        self._handle_multi_record_fasta, path, parsed,
                    )
                    return
                record = _fasta_path_to_record(path)
            elif _is_ab1_path(path):
                record = _ab1_path_to_record(path)
            elif _is_fastq_path(path):
                # FASTQ: same single-vs-multi split as FASTA. Multi-read
                # files (the common case for sequencing output) become
                # a new collection with one entry per read.
                fastq_records = _fastq_path_to_records(path)
                if len(fastq_records) > 1:
                    self.app.call_from_thread(
                        self._handle_multi_record_fasta, path, fastq_records,
                    )
                    return
                record = fastq_records[0]
            elif path.lower().endswith((".gff", ".gff3")):
                # GFF3 standalone import — requires inline ##FASTA.
                # Sequence-less GFF3 is rejected here; users wanting
                # feature transfer onto the loaded canvas should use
                # the dedicated apply-gff3 path (agent endpoint or
                # the forthcoming overlay UI affordance).
                record = _gff3_path_to_record(path)
            elif path.lower().endswith((".gb", ".gbk", ".genbank")):
                # 2026-05-27: multi-record GenBank → auto-collection.
                # Pre-fix `load_genbank` refused with "split the file"
                # which forced the user to know about the multi-record
                # case + handle it manually. Now we mirror the FASTA
                # path: if multiple records, prompt for a collection
                # name and import all of them; if single, fall through
                # to the existing single-record path (which preserves
                # display-name + .dna augmentations).
                from Bio import SeqIO as _SeqIO
                from pathlib import Path as _Path
                ok, reason = _safe_file_size_check(
                    _Path(path), _GB_INGEST_MAX_BYTES, "Plasmid",
                )
                if not ok:
                    raise ValueError(reason or "Plasmid file is unsafe to load")
                try:
                    gb_records = list(_SeqIO.parse(path, "genbank"))
                except (OSError, ValueError) as exc:
                    raise ValueError(
                        f"Could not parse GenBank file {path}: {exc}"
                    ) from exc
                if len(gb_records) > 1:
                    # Hand off to the UI thread for the name picker;
                    # mirrors the FASTA flow exactly.
                    self.app.call_from_thread(
                        self._handle_multi_record_genbank,
                        path, gb_records,
                    )
                    return
                record = load_genbank(path)
            else:
                record = load_genbank(path)
        except Exception as exc:
            _log.exception("OpenFileModal load failed for %s", path)
            # PEP 3110 clears `exc` once the except block exits, and
            # the `_err` closure runs later on the UI thread via
            # `call_from_thread` — by then the closure cell is unbound
            # and the `f"{exc}"` formats would raise NameError on a
            # path that's already in the error handler. Snapshot the
            # message into a plain local that survives the scope tear.
            err_msg = str(exc)
            def _err():
                # Modal may have been dismissed mid-parse via Esc; in
                # that case fall back to a toast so the user still
                # sees what failed.
                if not self.is_mounted:
                    try:
                        self.app.notify(f"Open failed: {err_msg}",
                                          severity="error", timeout=8,
                                          markup=False)
                    except Exception:
                        _log.exception("notify fallback for open error failed")
                    return
                try:
                    self.query_one("#open-status", Static).update(
                        f"[red]{err_msg}[/red]"
                    )
                    self.query_one("#btn-open",        Button).disabled = False
                    self.query_one("#btn-cancel-open", Button).disabled = False
                except NoMatches:
                    pass
            self.app.call_from_thread(_err)
            return

        record._tui_source = path  # type: ignore[attr-defined]

        def _ok():
            # Modal dismissed during parse → drop the parsed record on
            # the floor (the user explicitly bailed). Calling dismiss
            # on an already-dismissed modal would raise.
            if not self.is_mounted:
                return
            self._dismiss_once(record)
        self.app.call_from_thread(_ok)

    def _handle_multi_record_fasta(self, path: str,
                                     parsed_records: list) -> None:
        """Push `MultiRecordFastaModal` to ask the user for a collection
        name; on confirm, build SeqRecords + create the collection +
        dismiss self with a `fasta_collection` payload that the
        app-side `_on_open_file_done` handler dispatches on.

        Runs on the UI thread (called via `call_from_thread` from
        `_do_load`). Re-enables the Open modal's buttons up front so
        the user can cancel the import and pick a different file
        without the buttons stuck-disabled from the parsing step.
        """
        # Re-enable buttons + clear the "Parsing…" status so the
        # background OpenFileModal looks normal while the user
        # answers the prompt.
        try:
            self.query_one("#btn-open",        Button).disabled = False
            self.query_one("#btn-cancel-open", Button).disabled = False
            self.query_one("#open-status", Static).update("")
        except NoMatches:
            pass

        default_name = (Path(path).stem or "Imported")[:80]

        def _on_picked(name: "str | None") -> None:
            if name is None:
                # User cancelled the collection prompt — leave the
                # OpenFileModal open so they can pick a different
                # file. No-op cleanup here; buttons are already
                # re-enabled above.
                return
            try:
                self.query_one("#open-status", Static).update(
                    f"[dim]Creating collection '{name}'…[/dim]"
                )
                self.query_one("#btn-open", Button).disabled = True
            except NoMatches:
                pass
            self._fasta_collection_worker(name, parsed_records, path)

        self.app.push_screen(
            MultiRecordFastaModal(
                len(parsed_records), default_name=default_name,
            ),
            callback=_on_picked,
        )

    def _handle_multi_record_genbank(self, path: str,
                                       parsed_records: list) -> None:
        """Multi-record GenBank → auto-collection (2026-05-27). Mirror
        of `_handle_multi_record_fasta`: prompts for a collection name
        via the same modal, then imports every record (preserving
        features, qualifiers, history, etc.) into a fresh collection."""
        try:
            self.query_one("#btn-open",        Button).disabled = False
            self.query_one("#btn-cancel-open", Button).disabled = False
            self.query_one("#open-status", Static).update("")
        except NoMatches:
            pass
        default_name = (Path(path).stem or "Imported")[:80]

        def _on_picked(name: "str | None") -> None:
            if name is None:
                return
            try:
                self.query_one("#open-status", Static).update(
                    f"[dim]Creating collection '{name}'…[/dim]"
                )
                self.query_one("#btn-open", Button).disabled = True
            except NoMatches:
                pass
            self._genbank_collection_worker(name, parsed_records, path)

        self.app.push_screen(
            MultiRecordFastaModal(
                len(parsed_records), default_name=default_name,
            ),
            callback=_on_picked,
        )

    @work(thread=True, exclusive=True, group="genbank_collection_import")
    def _genbank_collection_worker(self, name: str, parsed_records: list,
                                      path: str) -> None:
        """Off-thread GenBank → library entries + collection write.
        Mirrors `_fasta_collection_worker`. Features, qualifiers,
        annotations all preserved per-record via the normalize step.
        """
        records = _genbank_records_to_seqrecords(parsed_records, path)
        if not records:
            self.app.call_from_thread(
                self._on_fasta_import_failed,
                "[red]No valid records in GenBank file — every record "
                "was empty or unparseable.[/red]",
            )
            return
        try:
            _create_genbank_collection(name, records, path)
        except (OSError, ValueError) as exc:
            _log.exception(
                "Failed to create GenBank collection %r", name,
            )
            self.app.call_from_thread(
                self._on_fasta_import_failed,
                f"[red]Could not create collection: {exc}[/red]",
            )
            return
        n_dropped = len(parsed_records) - len(records)
        self.app.call_from_thread(
            self._on_genbank_import_success,
            name, records, n_dropped, path,
        )

    def _on_genbank_import_success(self, name: str, records: list,
                                      n_dropped: int, path: str) -> None:
        if not self.is_mounted:
            return
        # Reuse the existing "fasta_collection" payload key — the
        # caller (_on_open_file_done) handles both file types the
        # same way (load record 1 onto canvas, refresh library
        # panel). The toast text is shared too.
        self._dismiss_once({
            "kind":            "fasta_collection",
            "collection_name": name,
            "records":         records,
            "n_dropped":       n_dropped,
            "source_path":     path,
        })

    @work(thread=True, exclusive=True, group="fasta_collection_import")
    def _fasta_collection_worker(self, name: str, parsed_records: list,
                                    path: str) -> None:
        """Off-thread FASTA → SeqRecords + collection write. Pre-fix
        this ran sync on the name-modal callback — a thousand-record
        FASTA could freeze the UI for a few seconds (per-record IUPAC
        validation + ID dedupe + `_save_collections` disk write of the
        full collection payload)."""
        records = _fasta_records_to_seqrecords(parsed_records, path)
        if not records:
            self.app.call_from_thread(
                self._on_fasta_import_failed,
                "[red]No valid records in FASTA — every record was "
                "empty or had non-IUPAC characters.[/red]",
            )
            return
        try:
            _create_fasta_collection(name, records, path)
        except (OSError, ValueError) as exc:
            _log.exception(
                "Failed to create FASTA collection %r", name,
            )
            self.app.call_from_thread(
                self._on_fasta_import_failed,
                f"[red]Could not create collection: {exc}[/red]",
            )
            return
        n_dropped = len(parsed_records) - len(records)
        self.app.call_from_thread(
            self._on_fasta_import_success,
            name, records, n_dropped, path,
        )

    def _on_fasta_import_failed(self, msg: str) -> None:
        try:
            self.query_one("#open-status", Static).update(msg)
        except NoMatches:
            pass
        try:
            self.query_one("#btn-open", Button).disabled = False
        except NoMatches:
            pass

    def _on_fasta_import_success(self, name: str, records: list,
                                    n_dropped: int, path: str) -> None:
        if not self.is_mounted:
            return
        self._dismiss_once({
            "kind":            "fasta_collection",
            "collection_name": name,
            "records":         records,
            "n_dropped":       n_dropped,
            "source_path":     path,
        })

    @on(Button.Pressed, "#btn-cancel-open")
    def _cancel_btn(self):
        self._dismiss_once(None)

    def action_cancel(self):
        self._dismiss_once(None)

    def _dismiss_once(self, payload) -> None:
        """[INV-50] Dispatch the dismiss exactly once. Pre-fix four
        independent exit paths (cancel button, Esc, GenBank worker
        success, FASTA collection worker success) each called
        `self.dismiss(...)`. A worker that completed just as the
        user clicked Cancel would fire two dismisses and trip
        Textual's screen-stack underflow check."""
        if self._dismissed:
            return
        self._dismissed = True
        self.dismiss(payload)


