class ExportCommercialSaaSModal(ModalScreen):
    """Prompt for a target path, write the current record as CommercialSaaS
    `.dna` by splicing the entry's `history_xml` into its saved
    sidecar bytes (Phase 4d).

    On submit dismisses with ``{"path": str}`` on success or None on
    cancel. The caller shows the success toast. Errors render
    inline in the modal so the user can fix the path without
    re-opening.

    Requires the library entry to have a sidecar (i.e., to have
    been imported from a CommercialSaaS `.dna` file in the first place).
    The host action method handles "no sidecar" before pushing
    this modal.
    """

    BINDINGS = [
        Binding("escape", "cancel",         "Cancel"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    def __init__(self, entry: dict, default_path: str = "") -> None:
        super().__init__()
        self._entry = entry
        rec_name = entry.get("name") or entry.get("id") or "plasmid"
        fallback = f"{rec_name}.dna"
        self._start_dir, self._default_filename = _split_default_export_path(
            default_path, fallback,
        )
        self._selected_dir = self._start_dir
        self._dismissed: bool = False   # [INV-50]

    def _dismiss_once(self, payload) -> None:
        if self._dismissed:
            return
        self._dismissed = True
        self.dismiss(payload)

    def compose(self) -> ComposeResult:
        with Vertical(id="export-box"):
            yield Static(" Export as .dna ", id="export-title")
            name = self._entry.get("name") or self._entry.get("id") or "?"
            bp = self._entry.get("size", 0)
            has_history = bool(self._entry.get("history_xml"))
            hist_label = (" + history" if has_history
                          else " (no construction history)")
            yield Label(f"[{name}]  {bp} bp{hist_label}")
            yield Static(
                f"Save in: [b]{self._selected_dir}[/b]",
                id="export-dir", markup=True,
            )
            yield _ExtensionAwareDirectoryTree(
                self._start_dir,
                highlight_map=_PLASMID_PICKER_HIGHLIGHT_MAP,
                id="export-tree",
            )
            yield Label("Filename (.dna):")
            yield Input(value=self._default_filename,
                          placeholder="plasmid.dna",
                          id="export-filename")
            yield Static("", id="export-status", markup=True)
            with Horizontal(id="export-btns"):
                yield Button("Export",  id="btn-export", variant="primary")
                yield Button("Cancel",  id="btn-cancel-export")

    def on_mount(self) -> None:
        try:
            self.query_one("#export-tree",
                            _ExtensionAwareDirectoryTree).focus()
        except NoMatches:
            pass

    @on(DirectoryTree.DirectorySelected, "#export-tree")
    def _on_dir_selected(self, event) -> None:
        self._selected_dir = str(event.path)
        try:
            self.query_one("#export-dir", Static).update(
                f"Save in: [b]{self._selected_dir}[/b]"
            )
        except NoMatches:
            pass

    @on(DirectoryTree.FileSelected, "#export-tree")
    def _on_file_selected(self, event) -> None:
        p = Path(str(event.path))
        self._selected_dir = str(p.parent)
        try:
            self.query_one("#export-dir", Static).update(
                f"Save in: [b]{self._selected_dir}[/b]"
            )
            self.query_one("#export-filename", Input).value = p.name
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-export")
    def _do_export(self) -> None:
        try:
            inp = self.query_one("#export-filename", Input)
            status = self.query_one("#export-status", Static)
        except NoMatches:
            return
        filename = inp.value.strip()
        if not filename:
            status.update("[red]Enter a filename.[/red]")
            return
        path = str(Path(self._selected_dir).expanduser() / filename)
        if not path.lower().endswith(".dna"):
            path += ".dna"
        try:
            written = _export_commercialsaas_dna(self._entry, path)
        except (OSError, ValueError) as exc:
            _log.exception("CommercialSaaS export to %s failed", path)
            status.update(
                f"[red]Could not write {path!r}: {exc}.[/red]"
            )
            return
        self._dismiss_once({"path": written})

    @on(Button.Pressed, "#btn-cancel-export")
    def _cancel_btn(self, _: Button.Pressed) -> None:
        self._dismiss_once(None)

    def action_cancel(self) -> None:
        self._dismiss_once(None)

    @on(Input.Submitted, "#export-filename")
    def _submitted(self) -> None:
        try:
            self.query_one("#btn-export", Button).press()
        except NoMatches:
            pass




class ExportGenBankModal(ModalScreen):
    """Pick an output directory + filename, write the current record
    as GenBank.

    UI: a `DirectoryTree` for navigating to the parent folder + a
    filename Input below. Plasmid-flavoured files (.gb / .gbk / .dna /
    .genbank) are highlighted lime green to make existing exports easy
    to spot when over-writing. Pre-2026-05-06 this was a single typed
    path Input; the file browser cuts down on path-typing errors.

    On submit, dismisses with a summary dict from `_export_genbank_to_path`
    (keys: path, bp, features) or None if cancelled. The caller is
    expected to show a notification on success.
    """

    _blocks_undo: bool = True   # filename Input editing

    BINDINGS = [
        Binding("escape", "cancel",      "Cancel"),
        Binding("tab",    "app.focus_next",  "Next",   show=False),
    ]

    def __init__(self, record, default_path: str = "") -> None:
        super().__init__()
        self._record = record
        rec_name = getattr(record, "name", "") or "plasmid"
        fallback = f"{rec_name}.gb"
        self._start_dir, self._default_filename = _split_default_export_path(
            default_path, fallback,
        )
        self._selected_dir = self._start_dir
        self._dismissed: bool = False   # [INV-50]

    def _dismiss_once(self, payload) -> None:
        if self._dismissed:
            return
        self._dismissed = True
        self.dismiss(payload)

    def compose(self) -> ComposeResult:
        with Vertical(id="export-box"):
            yield Static(" Export as GenBank ", id="export-title")
            name = getattr(self._record, "name", "") or "plasmid"
            bp = len(getattr(self._record, "seq", "") or "")
            feats = len(getattr(self._record, "features", []) or [])
            yield Label(f"[{name}]  {bp} bp, {feats} features")
            yield Static(
                f"Save in: [b]{self._selected_dir}[/b]",
                id="export-dir", markup=True,
            )
            yield _ExtensionAwareDirectoryTree(
                self._start_dir,
                highlight_map=_PLASMID_PICKER_HIGHLIGHT_MAP,
                id="export-tree",
            )
            yield Label("Filename (.gb / .gbk):")
            yield Input(
                value=self._default_filename,
                placeholder="plasmid.gb",
                id="export-filename",
            )
            yield Static("", id="export-status", markup=True)
            with Horizontal(id="export-btns"):
                yield Button("Export",  id="btn-export", variant="primary")
                yield Button("Cancel",  id="btn-cancel-export")

    def on_mount(self) -> None:
        # Default focus on the tree so arrow keys navigate immediately;
        # users who just want to confirm the default path can still
        # Tab to the filename Input or hit Export.
        try:
            self.query_one("#export-tree",
                            _ExtensionAwareDirectoryTree).focus()
        except NoMatches:
            pass

    @on(DirectoryTree.DirectorySelected, "#export-tree")
    def _on_dir_selected(self, event) -> None:
        # Clicking a folder updates the "Save in" dir without touching
        # the filename — the user can keep their typed name across
        # navigation.
        self._selected_dir = str(event.path)
        try:
            self.query_one("#export-dir", Static).update(
                f"Save in: [b]{self._selected_dir}[/b]"
            )
        except NoMatches:
            pass

    @on(DirectoryTree.FileSelected, "#export-tree")
    def _on_file_selected(self, event) -> None:
        # Clicking an existing file = "save here, overwriting": pull
        # the filename into the Input so a stray Enter overwrites the
        # exact file the user clicked.
        p = Path(str(event.path))
        self._selected_dir = str(p.parent)
        try:
            self.query_one("#export-dir", Static).update(
                f"Save in: [b]{self._selected_dir}[/b]"
            )
            self.query_one("#export-filename", Input).value = p.name
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-export")
    def _do_export(self) -> None:
        try:
            inp = self.query_one("#export-filename", Input)
            status = self.query_one("#export-status", Static)
        except NoMatches:
            return
        filename = inp.value.strip()
        if not filename:
            status.update("[red]Enter a filename.[/red]")
            return
        path = str(Path(self._selected_dir).expanduser() / filename)
        if (ext_err := _check_export_extension(
                Path(path), _EXPORT_GENBANK_EXTS, "GenBank")) is not None:
            status.update(f"[red]{ext_err}[/red]")
            return
        status.update(f"[dim]Exporting to {path}…[/dim]")
        # Disable the Export button so the user can't double-click
        # while the worker is in flight. Cancel stays enabled so the
        # user can bail mid-export (a 5 MB plasmid GenBank serialise +
        # atomic write can take ~1–2 s and we want to keep the cancel
        # path responsive). Re-enabled by `_on_export_failed`.
        try:
            self.query_one("#btn-export", Button).disabled = True
        except NoMatches:
            pass
        self._do_export_worker(path)

    @work(thread=True, exclusive=True, group="genbank_export")
    def _do_export_worker(self, path: str) -> None:
        try:
            summary = _export_genbank_to_path(self._record, path)
        except OSError as exc:
            _log.exception("GenBank export to %s failed", path)
            msg = (
                f"[red]Could not write to {path!r}: {exc.strerror or exc}. "
                f"Check the directory exists and you have write permission."
                f"[/red]"
            )
            self.app.call_from_thread(self._on_export_failed, msg)
            return
        except ValueError as exc:
            _log.exception("GenBank export to %s rejected", path)
            msg = (
                f"[red]Export rejected: {exc}. The path needs to end in "
                f".gb / .gbk and the record must be GenBank-compliant."
                f"[/red]"
            )
            self.app.call_from_thread(self._on_export_failed, msg)
            return
        # Worker may complete after the user dismissed the modal via
        # Cancel; guard the dismiss so a successful-export call into a
        # stale modal can't trip Textual's dismiss handler. Matches the
        # `FetchModal._do_fetch` is_mounted pattern.
        def _dismiss_if_mounted() -> None:
            if self.is_mounted:
                self._dismiss_once(summary)
        self.app.call_from_thread(_dismiss_if_mounted)

    def _on_export_failed(self, msg: str) -> None:
        try:
            self.query_one("#export-status", Static).update(msg)
        except NoMatches:
            pass
        try:
            self.query_one("#btn-export", Button).disabled = False
        except NoMatches:
            pass

    @on(Input.Submitted, "#export-filename")
    def _submitted(self) -> None:
        try:
            self.query_one("#btn-export", Button).press()
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-cancel-export")
    def _cancel_btn(self) -> None:
        self._dismiss_once(None)

    def action_cancel(self) -> None:
        self._dismiss_once(None)


class GffExportModal(ModalScreen):
    """Prompt for a target path and write `record` as GFF3.

    Dismisses with the summary dict from `_export_gff_to_path`
    (`path`, `bp`, `features`) or `None` if cancelled. Mirrors the
    FASTA + GenBank export modal pattern; differs only in file
    extension validation + which serialiser fires.
    """

    BINDINGS = [
        Binding("escape", "cancel",     "Cancel"),
        Binding("tab",    "app.focus_next", "Next",   show=False),
    ]

    _GFF_HIGHLIGHT_EXTS = frozenset({".gff", ".gff3"})

    def __init__(self, record, default_path: str = "") -> None:
        super().__init__()
        self._record = record
        rec_name = (getattr(record, "name", "")
                    or getattr(record, "id", "")
                    or "plasmid")
        fallback = f"{rec_name}.gff3"
        self._start_dir, self._default_filename = _split_default_export_path(
            default_path, fallback,
        )
        self._selected_dir = self._start_dir
        self._dismissed: bool = False   # [INV-50]

    def _dismiss_once(self, payload) -> None:
        if self._dismissed:
            return
        self._dismissed = True
        self.dismiss(payload)

    def compose(self) -> ComposeResult:
        with Vertical(id="gff-export-box"):
            yield Static(" Export as GFF3 ", id="gff-export-title")
            n = len(self._record.seq) if self._record else 0
            f = len([fe for fe in (self._record.features or [])
                     if fe.type != "source"]) if self._record else 0
            yield Label(
                f"[{self._record.name or self._record.id or '?'}]  "
                f"{n} bp · {f} feature(s)"
            )
            yield Static(
                f"Save in: [b]{self._selected_dir}[/b]",
                id="gff-export-dir", markup=True,
            )
            yield _ExtensionAwareDirectoryTree(
                self._start_dir,
                highlight_map=_GFF_PICKER_HIGHLIGHT_MAP,
                id="gff-export-tree",
            )
            yield Label("Filename (.gff / .gff3):")
            yield Input(
                value=self._default_filename,
                placeholder="plasmid.gff3",
                id="gff-export-filename",
            )
            yield Static("", id="gff-export-status", markup=True)
            with Horizontal(id="gff-export-btns"):
                yield Button("Export", id="btn-gff-export-ok",
                             variant="primary")
                yield Button("Cancel", id="btn-gff-export-cancel")

    def on_mount(self) -> None:
        try:
            self.query_one("#gff-export-tree",
                            _ExtensionAwareDirectoryTree).focus()
        except NoMatches:
            pass

    @on(DirectoryTree.DirectorySelected, "#gff-export-tree")
    def _on_dir_selected(self, event) -> None:
        self._selected_dir = str(event.path)
        try:
            self.query_one("#gff-export-dir", Static).update(
                f"Save in: [b]{self._selected_dir}[/b]"
            )
        except NoMatches:
            pass

    @on(DirectoryTree.FileSelected, "#gff-export-tree")
    def _on_file_selected(self, event) -> None:
        p = Path(str(event.path))
        self._selected_dir = str(p.parent)
        try:
            self.query_one("#gff-export-dir", Static).update(
                f"Save in: [b]{self._selected_dir}[/b]"
            )
            self.query_one("#gff-export-filename", Input).value = p.name
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-gff-export-ok")
    def _do_export(self) -> None:
        try:
            inp    = self.query_one("#gff-export-filename", Input)
            status = self.query_one("#gff-export-status", Static)
        except NoMatches:
            return
        filename = inp.value.strip()
        if not filename:
            status.update("[red]Enter a filename.[/red]")
            return
        path = str(Path(self._selected_dir).expanduser() / filename)
        if (ext_err := _check_export_extension(
                Path(path), _EXPORT_GFF_EXTS, "GFF3")) is not None:
            status.update(f"[red]{ext_err}[/red]")
            return
        status.update(f"[dim]Exporting to {path}…[/dim]")
        try:
            self.query_one("#btn-gff-export-ok", Button).disabled = True
        except NoMatches:
            pass
        self._do_export_worker(path)

    @work(thread=True, exclusive=True, group="gff_export")
    def _do_export_worker(self, path: str) -> None:
        try:
            summary = _export_gff_to_path(self._record, path)
        except OSError as exc:
            _log.exception("GFF export to %s failed", path)
            msg = (
                f"[red]Could not write to {path!r}: "
                f"{exc.strerror or exc}.  Check the directory exists "
                f"and you have write permission.[/red]"
            )
            self.app.call_from_thread(self._on_export_failed, msg)
            return
        # Guard dismiss for the same reason as `GenBankExportModal`.
        def _dismiss_if_mounted() -> None:
            if self.is_mounted:
                self._dismiss_once(summary)
        self.app.call_from_thread(_dismiss_if_mounted)

    def _on_export_failed(self, msg: str) -> None:
        try:
            self.query_one("#gff-export-status", Static).update(msg)
        except NoMatches:
            pass
        try:
            self.query_one("#btn-gff-export-ok", Button).disabled = False
        except NoMatches:
            pass

    @on(Input.Submitted, "#gff-export-filename")
    def _submitted(self) -> None:
        try:
            self.query_one("#btn-gff-export-ok", Button).press()
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-gff-export-cancel")
    def _cancel_btn(self) -> None:
        self._dismiss_once(None)

    def action_cancel(self) -> None:
        self._dismiss_once(None)


