class AddCustomEnzymeModal(ModalScreen[dict]):
    """Add a user-defined restriction enzyme to the master catalog.

    Inputs: name, recognition site (IUPAC), forward + reverse cut
    positions, type tag, supplier. Persisted to `custom_enzymes.json`
    via `_save_custom_enzymes`; after save the scan catalog is rebuilt
    so the new enzyme participates in subsequent restriction scans
    without a relaunch.

    Validation:
      * Name 1–64 chars, no leading/trailing whitespace, must NOT
        collide with an existing built-in or custom enzyme.
      * Site 4–30 chars, IUPAC alphabet (``ACGTRYSWKMBDHVN``).
      * Cut positions integer in ``-30 .. len(site)+30`` (typeIIS
        enzymes cut outside their recognition site so we allow some
        slack — guards against typos, not malice).

    Dismisses with the saved entry dict on success, ``None`` on cancel.
    """

    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel", "Cancel"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    DEFAULT_CSS = """
    #ace-dlg {
        width: 80; height: auto; max-height: 92%;
        background: $surface; border: solid $primary; padding: 1 2;
    }
    #ace-title {
        background: $primary-darken-2; color: $text;
        padding: 0 1; margin-bottom: 1; text-align: center;
    }
    .ace-row { height: 3; }
    .ace-row Label { width: 18; padding: 1 0 0 0; }
    .ace-row Input { width: 50; }
    .ace-row Select { width: 50; }
    #ace-status { min-height: 1; margin-top: 1; }
    #ace-btns { align: right middle;  height: 3; margin-top: 1; }
    #ace-btns Button { margin-right: 1; }
    """

    # Type tags are informational labels — the scanner only uses
    # (site, fwd_cut, rev_cut). Keep the list short so the dropdown
    # stays readable.
    _ENZYME_TYPES = [
        ("Type II — blunt",       "II_blunt"),
        ("Type II — 5' overhang", "II_5overhang"),
        ("Type II — 3' overhang", "II_3overhang"),
        ("Type IIS",              "IIS"),
        ("Type III",              "III"),
        ("Other",                 "other"),
    ]

    _IUPAC_ALPHABET = frozenset("ACGTRYSWKMBDHVN")

    def __init__(self) -> None:
        super().__init__()
        self._dismissed: bool = False   # [INV-50]

    def _dismiss_once(self, payload) -> None:
        if self._dismissed:
            return
        self._dismissed = True
        self.dismiss(payload)

    def compose(self) -> ComposeResult:
        with Vertical(id="ace-dlg"):
            yield Static(" Add custom enzyme ", id="ace-title")
            with Horizontal(classes="ace-row"):
                yield Label("Name:")
                yield Input(placeholder="e.g. MyEnzI", id="ace-name")
            with Horizontal(classes="ace-row"):
                yield Label("Recognition site:")
                yield Input(
                    placeholder="e.g. GGATCC (IUPAC OK)",
                    id="ace-site",
                )
            with Horizontal(classes="ace-row"):
                yield Label("Forward cut:")
                yield Input(
                    placeholder="0..len(site); offset from site start",
                    id="ace-fwd",
                )
            with Horizontal(classes="ace-row"):
                yield Label("Reverse cut:")
                yield Input(
                    placeholder="offset from site start on bottom strand",
                    id="ace-rev",
                )
            with Horizontal(classes="ace-row"):
                yield Label("Type:")
                yield Select(
                    options=[(lbl, key) for lbl, key in self._ENZYME_TYPES],
                    value="II_blunt",
                    id="ace-type",
                    allow_blank=False,
                )
            with Horizontal(classes="ace-row"):
                yield Label("Supplier:")
                yield Input(
                    placeholder="optional — e.g. NEB, Thermo",
                    id="ace-supplier",
                )
            yield Static("", id="ace-status", markup=True)
            with Horizontal(id="ace-btns"):
                yield Button("Save", id="ace-save", variant="primary")
                yield Button("Cancel", id="ace-cancel")

    def on_mount(self) -> None:
        try:
            self.query_one("#ace-name", Input).focus()
        except NoMatches:
            pass

    def _set_status(self, markup: str) -> None:
        try:
            self.query_one("#ace-status", Static).update(markup)
        except NoMatches:
            pass

    def _validate(self) -> "dict | None":
        """Pull every field, validate, and return the persistable dict
        on success. Sets the status line + returns None on any error."""
        try:
            name     = (self.query_one("#ace-name", Input).value or "").strip()
            site     = (self.query_one("#ace-site", Input).value or "").strip().upper()
            fwd_raw  = (self.query_one("#ace-fwd",  Input).value or "").strip()
            rev_raw  = (self.query_one("#ace-rev",  Input).value or "").strip()
            type_v   = self.query_one("#ace-type", Select).value
            supplier = (self.query_one("#ace-supplier", Input).value or "").strip()
        except NoMatches:
            return None
        if not name or not (1 <= len(name) <= 64):
            self._set_status(
                "[red]Name must be 1–64 characters.[/red]"
            )
            return None
        known = _all_enzymes()
        if name in known:
            self._set_status(
                f"[red]{name!r} already exists in the master "
                f"catalog.[/red]"
            )
            return None
        if not site or not (4 <= len(site) <= 30):
            self._set_status(
                "[red]Recognition site must be 4–30 characters.[/red]"
            )
            return None
        bad_chars = set(site) - self._IUPAC_ALPHABET
        if bad_chars:
            self._set_status(
                f"[red]Site has non-IUPAC characters: "
                f"{', '.join(sorted(bad_chars))}.[/red]"
            )
            return None
        try:
            fwd_cut = int(fwd_raw)
            rev_cut = int(rev_raw)
        except ValueError:
            self._set_status(
                "[red]Cut positions must be integers.[/red]"
            )
            return None
        # Type IIS enzymes cut OUTSIDE the recognition site (offset
        # can be larger than len(site)) — guard for typos with
        # generous bounds but don't disallow real-world cases.
        # Sweep #26: bound from module constant `_ENZYME_CUT_RANGE`.
        lo = -_ENZYME_CUT_RANGE
        hi = len(site) + _ENZYME_CUT_RANGE
        if not (lo <= fwd_cut <= hi) or not (lo <= rev_cut <= hi):
            self._set_status(
                f"[red]Cut positions must be within "
                f"{lo}..{hi} (site length {len(site)}).[/red]"
            )
            return None
        return {
            "name":     name,
            "site":     site,
            "fwd_cut":  fwd_cut,
            "rev_cut":  rev_cut,
            "type":     type_v if isinstance(type_v, str) else "other",
            "supplier": supplier,
        }

    @on(Button.Pressed, "#ace-save")
    def _save_btn(self, _) -> None:
        payload = self._validate()
        if payload is None:
            return
        # Sweep #25 (2026-05-23): full RMW under `_cache_lock` so a
        # concurrent agent `create-custom-enzyme` can't race the
        # check-then-append. Also routes through `_notify_save_failure`
        # so failures emit the structured `save.failed` event that
        # Alt+D bug bundles pick up — pre-fix `_log.exception` was
        # the only failure trail (INV-65 said "wraps correctly" but
        # only the status-line update was wrapped, not the event).
        with _cache_lock:
            entries = _load_custom_enzymes()
            entries.append(payload)
            try:
                _save_custom_enzymes(entries)
            except (OSError, RuntimeError) as exc:
                _log.exception("save custom enzyme failed")
                _notify_save_failure(self.app, "Custom enzymes", exc)
                self._set_status(
                    f"[red]Save failed: {exc}[/red]"
                )
                return
        _log_event(
            "custom_enzyme.added",
            name=payload["name"], site=payload["site"],
            type=payload["type"],
        )
        self._dismiss_once(payload)

    @on(Button.Pressed, "#ace-cancel")
    def _cancel_btn(self, _) -> None:
        self._dismiss_once(None)

    def action_cancel(self) -> None:
        self._dismiss_once(None)


class EnzymeCollectionsModal(ModalScreen):
    """Manage enzyme catalogs — named subsets of the master enzyme
    catalog (built-in NEB ∪ user-added custom enzymes).

    Two-pane layout. **Left** = master catalog (always visible) with a
    search Input and an ``+ Add new enzyme…`` button that opens
    `AddCustomEnzymeModal`. **Right** = a switchable view with two
    modes:

      * **List mode** (default landing) — DataTable of every catalog,
        with ``New… / Rename… / Duplicate / Delete / Open`` buttons.
        Selecting a row + ``Open`` (or pressing Enter on the row)
        switches to editor mode and makes that catalog the active
        one for the restriction-overlay scan.
      * **Editor mode** — DataTable of enzymes in the currently-open
        catalog, with ``← Back`` (returns to list mode) and
        ``← Remove``. ``Add →`` happens via the master pane: pressing
        Enter / Space on a master row, double-clicking it, or hitting
        the ``Add →`` button, copies that enzyme into the open catalog
        and refocuses the search Input (clearing its value) for the
        type-search-add-repeat cycle.

    Mirrors the plasmid library / collections architecture: the
    master catalog is the equivalent of the plasmid library, catalogs
    are the equivalent of collections. The legacy
    ``restr_use_custom_list`` toggle + ``restr_custom_enzymes`` CSV
    are migrated to a single ``Custom (legacy)`` catalog at first
    launch (see `_migrate_legacy_custom_enzyme_csv`) and then dormant.

    `_blocks_undo = True` — every CRUD action mutates persistent state
    via `_save_enzyme_collections` / `_save_custom_enzymes`; a stray
    Ctrl+Z on the canvas underneath would race the save (mirrors
    `EntryVectorsModal`).
    """

    _blocks_undo: bool = True
    _MODE_LIST   = "list"
    _MODE_EDITOR = "editor"

    BINDINGS = [
        Binding("escape", "close", "Close"),
        Binding("tab",    "app.focus_next", "Next", show=False),
        # Space on the master table activates "add to current catalog"
        # (mirrors the DataTable's built-in Enter binding which fires
        # `RowSelected`). Keep `show=False` so the footer hint row
        # doesn't get crowded.
        Binding("space", "master_activate", "Add to catalog",
                show=False),
        # Down arrow from the search input → focus the master table.
        # No-op if focus is elsewhere; the table's own Down arrow
        # handles row navigation when it has focus.
        Binding("down", "search_to_table", "→ Table", show=False),
    ]

    DEFAULT_CSS = """
    #ec-dlg {
        width: 140; height: 92%;
        background: $surface; border: solid $primary; padding: 1 2;
    }
    #ec-title {
        background: $primary-darken-2; color: $text;
        padding: 0 1; margin-bottom: 1; text-align: center;
    }
    #ec-tabs { height: 1fr; }
    #ec-panes { height: 1fr; min-height: 8; }
    #ec-master-pane { width: 1fr; padding-right: 1; }
    #ec-right-pane  { width: 1fr; padding-left: 1; }
    #ec-master-label { color: $accent; margin-bottom: 1; }
    #ec-search { margin-bottom: 1; }
    #ec-master-table { height: 1fr; margin-bottom: 1; }
    #ec-add-master { width: 100%; }
    #ec-list-mode, #ec-editor-mode { height: 100%; }
    #ec-list-label, #ec-editor-label { color: $accent; margin-bottom: 1; }
    #ec-catalogs-table, #ec-current-table { height: 1fr; }
    #ec-editor-header { height: 3; margin-bottom: 1; }
    #ec-editor-header Button { margin-right: 1; }
    #ec-list-btns, #ec-list-btns2, #ec-editor-btns {
        height: 3; margin-top: 1;
    }
    #ec-list-btns Button, #ec-list-btns2 Button, #ec-editor-btns Button {
        margin-right: 1;
    }
    #ec-settings-pane { height: auto; padding: 1 2; }
    #ec-settings-pane Checkbox { margin-bottom: 1; }
    #ec-settings-pane RadioSet { margin-bottom: 1; }
    #ec-settings-pane .ec-settings-label {
        color: $accent; margin-top: 1;
    }
    #ec-status { margin-top: 1; min-height: 1; }
    #ec-btns { align: right middle;  height: 3; }
    #ec-btns Button { margin-right: 1; }
    """

    def __init__(self) -> None:
        super().__init__()
        # Search filter — substring matched against name + recognition site.
        self._search: str = ""
        # Right-pane mode. Default to "list" so the user always lands
        # on the catalog browser; "editor" is reached by clicking Open
        # (or pressing Enter on a catalog row).
        self._mode: str = self._MODE_LIST
        # Name of the catalog being edited in editor mode. None when
        # in list mode.
        self._editor_catalog: "str | None" = None
        # If a catalog is already marked active in settings, the modal
        # opens straight into its editor view — matches the user's
        # mental model "I want to keep editing where I left off".
        active = _get_active_enzyme_collection_name()
        if active and _find_enzyme_collection(active):
            self._mode = self._MODE_EDITOR
            self._editor_catalog = active
        self._dismissed: bool = False   # [INV-50]

    def _dismiss_once(self, payload) -> None:
        if self._dismissed:
            return
        self._dismissed = True
        self.dismiss(payload)

    def _save_or_status(self, entries: list) -> bool:
        """Persist via `_save_enzyme_collections` and surface failures.
        Sacred invariant #7: `_safe_save_json` re-raises on disk full /
        RO mount / EACCES; without this wrap the exception would crash
        the modal mid-CRUD. Returns True on success so callers can
        early-return before the success-side refresh + status."""
        try:
            _save_enzyme_collections(entries)
        except Exception as exc:
            _notify_save_failure(self.app, "Enzyme collections", exc)
            self._set_status(f"[red]Save failed: {exc}[/red]")
            return False
        return True

    def compose(self) -> ComposeResult:
        with Vertical(id="ec-dlg"):
            yield Static(" Enzyme collections ", id="ec-title")
            with TabbedContent(initial="tab-sets", id="ec-tabs"):
                # TAB 1: catalog manager (the original modal body).
                with TabPane("Enzyme Sets", id="tab-sets"):
                    with Horizontal(id="ec-panes"):
                        # LEFT: master enzymes (NEB + custom) — always visible.
                        with Vertical(id="ec-master-pane"):
                            yield Static(
                                "Master catalog (NEB + custom)",
                                id="ec-master-label",
                            )
                            yield Input(
                                placeholder="Search name or recognition site…",
                                id="ec-search",
                            )
                            yield DataTable(
                                id="ec-master-table",
                                cursor_type="row",
                                zebra_stripes=True,
                            )
                            yield Button(
                                "+ Add new enzyme",
                                id="ec-add-master",
                            )
                        # RIGHT: two modes; we mount BOTH and toggle `display`
                        # so the user can't tab into a hidden widget.
                        with Vertical(id="ec-right-pane"):
                            # MODE A: catalog list (default landing).
                            with Vertical(id="ec-list-mode"):
                                yield Static(
                                    "Enzyme catalogs",
                                    id="ec-list-label",
                                )
                                yield DataTable(
                                    id="ec-catalogs-table",
                                    cursor_type="row",
                                    zebra_stripes=True,
                                )
                                with Horizontal(id="ec-list-btns"):
                                    yield Button("Open",      id="ec-open",
                                                 variant="primary")
                                    yield Button("New",       id="ec-new")
                                    yield Button("Rename",    id="ec-rename")
                                with Horizontal(id="ec-list-btns2"):
                                    yield Button("Duplicate", id="ec-duplicate")
                                    yield Button("Delete",    id="ec-delete",
                                                 variant="error")
                            # MODE B: catalog editor.
                            with Vertical(id="ec-editor-mode"):
                                with Horizontal(id="ec-editor-header"):
                                    yield Button("← Back", id="ec-back")
                                    yield Static(
                                        "Editing: —",
                                        id="ec-editor-label",
                                    )
                                yield DataTable(
                                    id="ec-current-table",
                                    cursor_type="row",
                                    zebra_stripes=True,
                                )
                                with Horizontal(id="ec-editor-btns"):
                                    yield Button("Add →",    id="ec-add",
                                                 variant="primary")
                                    yield Button("← Remove", id="ec-remove")
                # TAB 2: restriction-overlay settings (moved out of the
                # Enzymes dropdown when that menu was promoted to
                # direct-open). Each control reads its initial state
                # from the live settings + app attrs; Changed events
                # delegate to the existing `action_toggle_*` methods so
                # rescan + persist + notify wiring stays in one place.
                with TabPane("Enzyme Settings", id="tab-settings"):
                    with Vertical(id="ec-settings-pane"):
                        yield Static(
                            "Restriction-site overlay",
                            classes="ec-settings-label",
                        )
                        yield Checkbox(
                            "Show RE sites (keyboard shortcut: r)",
                            # [staleguard] default False to MATCH the canonical
                            # readers (RestrictionController / app _show_restr,
                            # both default False). A True default made a fresh
                            # profile show the box checked while the overlay was
                            # off, and the compose-time Changed event tripped
                            # the differ-guard into a spurious toggle-on.
                            value=bool(_get_setting("show_restr", False)),
                            id="ec-set-show-restr",
                        )
                        yield Checkbox(
                            "Unique cutters only",
                            value=bool(_get_setting(
                                "restr_unique_only", True,
                            )),
                            id="ec-set-unique",
                        )
                        yield Static(
                            "Minimum recognition length",
                            classes="ec-settings-label",
                        )
                        _min_len = int(_get_setting("restr_min_len", 6))
                        with RadioSet(id="ec-set-min-len"):
                            yield RadioButton(
                                "4+ bp sites",
                                value=(_min_len == 4),
                                id="ec-set-min-4",
                            )
                            yield RadioButton(
                                "6+ bp sites",
                                value=(_min_len != 4),
                                id="ec-set-min-6",
                            )
                        yield Static(
                            "Map labels",
                            classes="ec-settings-label",
                        )
                        yield Checkbox(
                            "Show feature label connectors",
                            # [staleguard] default False to match the seq-panel
                            # / map `_show_connectors` (both default False) the
                            # differ-guard compares against — see show_restr.
                            value=bool(_get_setting(
                                "show_connectors", False,
                            )),
                            id="ec-set-connectors",
                        )
            yield Static("", id="ec-status", markup=True)
            with Horizontal(id="ec-btns"):
                yield Button("Close", id="ec-close")

    # ── Mount + initial population ────────────────────────────────────────

    def on_mount(self) -> None:
        # Build column headers once.
        try:
            self.query_one("#ec-master-table", DataTable).add_columns(
                "Enzyme", "Recognition site", "Source",
            )
        except NoMatches:
            pass
        try:
            self.query_one("#ec-current-table", DataTable).add_columns(
                "Enzyme", "Recognition site",
            )
        except NoMatches:
            pass
        try:
            self.query_one("#ec-catalogs-table", DataTable).add_columns(
                "Catalog", "# enzymes", "Active",
            )
        except NoMatches:
            pass
        self._apply_mode()
        self._refresh_master_table()
        self._refresh_catalogs_table()
        self._refresh_current_table()
        self._refresh_status()
        # Default focus on the search input — the type-search-add-repeat
        # cycle is the dominant workflow.
        self._focus_search(clear=False)

    # ── Mode switching ────────────────────────────────────────────────────

    def _apply_mode(self) -> None:
        """Show only one right-pane mode at a time. Toggling `display`
        keeps focus traversal honest (a hidden Vertical's children
        aren't tab targets in Textual)."""
        list_show   = self._mode == self._MODE_LIST
        editor_show = self._mode == self._MODE_EDITOR
        try:
            self.query_one("#ec-list-mode", Vertical).display = list_show
        except NoMatches:
            pass
        try:
            self.query_one("#ec-editor-mode", Vertical).display = editor_show
        except NoMatches:
            pass
        # Update editor header label.
        try:
            label = self.query_one("#ec-editor-label", Static)
            label.update(
                f"Editing: {self._editor_catalog or '—'}"
            )
        except NoMatches:
            pass

    def _enter_editor(self, name: str) -> None:
        """Switch to editor mode on the given catalog + make it active."""
        self._editor_catalog = name
        self._mode = self._MODE_EDITOR
        _set_active_enzyme_collection_name(name)
        self._apply_mode()
        self._refresh_master_table()
        self._refresh_current_table()
        self._refresh_status()
        self._kick_live_rescan()
        self._focus_search(clear=True)

    def _leave_editor(self) -> None:
        """Switch back to catalog list mode. Active pointer stays as-is —
        the user might just want to browse other catalogs without
        changing what the overlay shows."""
        self._editor_catalog = None
        self._mode = self._MODE_LIST
        self._apply_mode()
        self._refresh_master_table()
        self._refresh_catalogs_table()
        self._refresh_status()

    # ── Table population ──────────────────────────────────────────────────

    def _site_display(self, name: str) -> str:
        spec = _all_enzymes().get(name)
        if not spec:
            return ""
        site, fwd_cut, _rev_cut = spec
        if 0 <= fwd_cut <= len(site):
            return f"{site[:fwd_cut]}^{site[fwd_cut:]}"
        return site

    def _refresh_master_table(self) -> None:
        try:
            t = self.query_one("#ec-master-table", DataTable)
        except NoMatches:
            return
        t.clear()
        q = self._search.strip().upper()
        current_set: set[str] = set()
        if self._mode == self._MODE_EDITOR and self._editor_catalog:
            coll = _find_enzyme_collection(self._editor_catalog) or {}
            current_set = {
                e for e in (coll.get("enzymes") or [])
                if isinstance(e, str)
            }
        custom_names = {
            e.get("name") for e in _load_custom_enzymes()
            if isinstance(e, dict) and isinstance(e.get("name"), str)
        }
        for ename in sorted(_all_enzymes().keys()):
            site = _all_enzymes()[ename][0]
            if q and q not in ename.upper() and q not in site.upper():
                continue
            source = "Custom" if ename in custom_names else "NEB"
            if ename in current_set:
                t.add_row(
                    Text(ename, style="dim italic"),
                    Text(self._site_display(ename),
                         style="dim italic"),
                    Text(source, style="dim italic"),
                    key=ename,
                )
            else:
                t.add_row(
                    Text(ename),
                    Text(self._site_display(ename)),
                    Text(source),
                    key=ename,
                )

    def _refresh_current_table(self) -> None:
        try:
            t = self.query_one("#ec-current-table", DataTable)
        except NoMatches:
            return
        t.clear()
        if self._mode != self._MODE_EDITOR or not self._editor_catalog:
            return
        coll = _find_enzyme_collection(self._editor_catalog) or {}
        known = _all_enzymes()
        enzymes = [
            e for e in (coll.get("enzymes") or [])
            if isinstance(e, str) and e in known
        ]
        for ename in sorted(enzymes):
            t.add_row(
                Text(ename),
                Text(self._site_display(ename)),
                key=ename,
            )

    def _refresh_catalogs_table(self) -> None:
        try:
            t = self.query_one("#ec-catalogs-table", DataTable)
        except NoMatches:
            return
        t.clear()
        active = _get_active_enzyme_collection_name() or ""
        for coll in _load_enzyme_collections():
            name = coll.get("name")
            if not isinstance(name, str):
                continue
            enzymes = [
                e for e in (coll.get("enzymes") or [])
                if isinstance(e, str)
            ]
            t.add_row(
                Text(name, style="bold"),
                Text(str(len(enzymes))),
                Text("✓ active" if name == active else "",
                     style="green bold" if name == active else ""),
                key=name,
            )

    def _refresh_status(self) -> None:
        try:
            status = self.query_one("#ec-status", Static)
        except NoMatches:
            return
        active = _get_active_enzyme_collection_name()
        if not active:
            status.update(
                f"[dim]Active scan: full master catalog "
                f"({len(_all_enzymes())} enzymes).[/dim]"
            )
            return
        coll = _find_enzyme_collection(active) or {}
        known = _all_enzymes()
        n = len([
            e for e in (coll.get("enzymes") or [])
            if isinstance(e, str) and e in known
        ])
        status.update(
            f"[dim]Active scan: {active} — {n} enzyme(s).[/dim]"
        )

    def _set_status(self, markup: str) -> None:
        try:
            self.query_one("#ec-status", Static).update(markup)
        except NoMatches:
            pass

    # ── Search input flow ─────────────────────────────────────────────────

    @on(Input.Changed, "#ec-search")
    def _on_search_changed(self, event: Input.Changed) -> None:
        self._search = event.value or ""
        self._refresh_master_table()

    @on(Input.Submitted, "#ec-search")
    def _on_search_submitted(self, _: Input.Submitted) -> None:
        # Enter inside the search box: move focus to the master table
        # on its first row — matches the type-then-pick flow.
        self._focus_master_table()

    def _focus_master_table(self) -> None:
        try:
            t = self.query_one("#ec-master-table", DataTable)
        except NoMatches:
            return
        if t.row_count <= 0:
            return
        t.focus()
        try:
            t.cursor_coordinate = _Coordinate(0, 0)
        except Exception:
            pass

    def _focus_search(self, *, clear: bool) -> None:
        """Focus the search input, optionally clearing its value first.
        Called after every add so the user can type the next query
        without reaching for the mouse."""
        try:
            inp = self.query_one("#ec-search", Input)
        except NoMatches:
            return
        if clear:
            inp.value = ""
            # `value=` doesn't fire Input.Changed when set
            # programmatically; mirror the side effect manually.
            self._search = ""
            self._refresh_master_table()
        inp.focus()

    def action_search_to_table(self) -> None:
        """Modal-level Down binding: only acts when the search input
        has focus (other widgets get the normal Down behaviour)."""
        try:
            inp = self.query_one("#ec-search", Input)
        except NoMatches:
            return
        if not inp.has_focus:
            return
        self._focus_master_table()

    def action_master_activate(self) -> None:
        """Modal-level Space binding: only acts when the master table
        has focus. Mirrors DataTable's built-in Enter (which fires
        `RowSelected` and is handled separately) so the two activation
        keys behave identically."""
        try:
            t = self.query_one("#ec-master-table", DataTable)
        except NoMatches:
            return
        if not t.has_focus:
            return
        enz = self._master_row_key()
        if enz:
            self._add_to_current(enz)

    # ── Catalog row navigation in list mode ───────────────────────────────

    @on(DataTable.RowSelected, "#ec-catalogs-table")
    def _on_catalog_row_selected(
        self, event: DataTable.RowSelected,
    ) -> None:
        """Enter on a catalog row → open it (mirrors clicking Open)."""
        key = event.row_key.value if event.row_key else None
        if isinstance(key, str) and _find_enzyme_collection(key):
            self._enter_editor(key)

    # ── Master row activation (Enter / Space / double-click) ──────────────

    @on(DataTable.RowSelected, "#ec-master-table")
    def _on_master_row_selected(
        self, event: DataTable.RowSelected,
    ) -> None:
        """Enter on a master row → add to current catalog."""
        key = event.row_key.value if event.row_key else None
        if isinstance(key, str):
            self._add_to_current(key)

    @on(Click, "#ec-master-table")
    def _on_master_click(self, event: "Click") -> None:
        """Double-click on a master row → add. Single click selects
        the row (default behaviour); chain >= 2 fires the add."""
        # Textual's Click.chain is 1 for a normal click, 2 for double,
        # 3 for triple. Skip if it's just a single click — the row
        # selection from the underlying DataTable handler is enough.
        if getattr(event, "chain", 1) < 2:
            return
        enz = self._master_row_key()
        if enz:
            self._add_to_current(enz)

    def _master_row_key(self) -> "str | None":
        try:
            t = self.query_one("#ec-master-table", DataTable)
        except NoMatches:
            return None
        if t.cursor_row is None or t.cursor_row < 0:
            return None
        try:
            key = t.coordinate_to_cell_key(
                _Coordinate(t.cursor_row, 0)
            ).row_key.value
        except Exception:
            return None
        return key if isinstance(key, str) else None

    def _current_row_key(self) -> "str | None":
        try:
            t = self.query_one("#ec-current-table", DataTable)
        except NoMatches:
            return None
        if t.cursor_row is None or t.cursor_row < 0:
            return None
        try:
            key = t.coordinate_to_cell_key(
                _Coordinate(t.cursor_row, 0)
            ).row_key.value
        except Exception:
            return None
        return key if isinstance(key, str) else None

    def _catalogs_row_key(self) -> "str | None":
        try:
            t = self.query_one("#ec-catalogs-table", DataTable)
        except NoMatches:
            return None
        if t.cursor_row is None or t.cursor_row < 0:
            return None
        try:
            key = t.coordinate_to_cell_key(
                _Coordinate(t.cursor_row, 0)
            ).row_key.value
        except Exception:
            return None
        return key if isinstance(key, str) else None

    # ── List-mode CRUD ────────────────────────────────────────────────────

    def _existing_names(self) -> set:
        return {
            c.get("name") for c in _load_enzyme_collections()
            if isinstance(c, dict) and isinstance(c.get("name"), str)
        }

    @on(Button.Pressed, "#ec-open")
    def _open_btn(self, _) -> None:
        name = self._catalogs_row_key()
        if not name or not _find_enzyme_collection(name):
            self._set_status(
                "[yellow]Pick a catalog row first.[/yellow]"
            )
            return
        self._enter_editor(name)

    @on(Button.Pressed, "#ec-new")
    def _new_btn(self, _) -> None:
        def _on_named(name: "str | None") -> None:
            if not name:
                return
            if name in self._existing_names():
                self._set_status(
                    f"[yellow]A catalog named {name!r} "
                    f"already exists.[/yellow]"
                )
                return
            entries = _load_enzyme_collections()
            entries.append({"name": name, "enzymes": []})
            if not self._save_or_status(entries):
                return
            self._refresh_catalogs_table()
            self._set_status(
                f"[green]Created catalog {name!r}. "
                f"Pick a row + Open to edit.[/green]"
            )
        self.app.push_screen(
            _EnzymeNamePromptModal("New catalog — name?"),
            _on_named,
        )

    @on(Button.Pressed, "#ec-rename")
    def _rename_btn(self, _) -> None:
        name = self._catalogs_row_key()
        if not name or not _find_enzyme_collection(name):
            self._set_status(
                "[yellow]Pick a catalog row first.[/yellow]"
            )
            return
        def _on_named(new_name: "str | None") -> None:
            if not new_name or new_name == name:
                return
            if new_name in self._existing_names():
                self._set_status(
                    f"[yellow]{new_name!r} already exists.[/yellow]"
                )
                return
            entries = _load_enzyme_collections()
            for entry in entries:
                if entry.get("name") == name:
                    entry["name"] = new_name
                    break
            if not self._save_or_status(entries):
                return
            if _get_active_enzyme_collection_name() == name:
                _set_active_enzyme_collection_name(new_name)
            self._refresh_catalogs_table()
            self._set_status(
                f"[green]Renamed to {new_name!r}.[/green]"
            )
        self.app.push_screen(
            _EnzymeNamePromptModal(
                f"Rename {name!r} →", initial=name,
            ),
            _on_named,
        )

    @on(Button.Pressed, "#ec-duplicate")
    def _duplicate_btn(self, _) -> None:
        name = self._catalogs_row_key()
        if not name or not _find_enzyme_collection(name):
            self._set_status(
                "[yellow]Pick a catalog row first.[/yellow]"
            )
            return
        existing = self._existing_names()
        base = f"{name} (copy)"
        new_name = base
        n = 2
        while new_name in existing:
            new_name = f"{base} {n}"
            n += 1
        coll = _find_enzyme_collection(name) or {}
        entries = _load_enzyme_collections()
        entries.append({
            "name": new_name,
            "enzymes": list(coll.get("enzymes") or []),
        })
        if not self._save_or_status(entries):
            return
        self._refresh_catalogs_table()
        self._set_status(
            f"[green]Duplicated to {new_name!r}.[/green]"
        )

    @on(Button.Pressed, "#ec-delete")
    def _delete_btn(self, _) -> None:
        name = self._catalogs_row_key()
        if not name or not _find_enzyme_collection(name):
            self._set_status(
                "[yellow]Pick a catalog row first.[/yellow]"
            )
            return
        entries = [
            c for c in _load_enzyme_collections()
            if c.get("name") != name
        ]
        if not self._save_or_status(entries):
            return
        if _get_active_enzyme_collection_name() == name:
            _set_active_enzyme_collection_name(None)
        self._refresh_catalogs_table()
        self._refresh_status()
        self._kick_live_rescan()
        self._set_status(
            f"[yellow]Deleted {name!r}.[/yellow]"
        )

    # ── Editor mode add/remove ────────────────────────────────────────────

    @on(Button.Pressed, "#ec-back")
    def _back_btn(self, _) -> None:
        self._leave_editor()

    @on(Button.Pressed, "#ec-add")
    def _add_btn(self, _) -> None:
        enz = self._master_row_key()
        if not enz:
            self._set_status(
                "[yellow]Select an enzyme in the master pane "
                "first.[/yellow]"
            )
            return
        self._add_to_current(enz)

    @on(Button.Pressed, "#ec-remove")
    def _remove_btn(self, _) -> None:
        if not self._editor_catalog:
            self._set_status(
                "[yellow]Open a catalog first.[/yellow]"
            )
            return
        enz = self._current_row_key()
        if not enz:
            self._set_status(
                "[yellow]Select an enzyme on the right pane "
                "first.[/yellow]"
            )
            return
        entries = _load_enzyme_collections()
        for entry in entries:
            if entry.get("name") != self._editor_catalog:
                continue
            entry["enzymes"] = [
                e for e in (entry.get("enzymes") or [])
                if e != enz
            ]
            break
        if not self._save_or_status(entries):
            return
        self._refresh_master_table()
        self._refresh_current_table()
        self._refresh_status()
        self._kick_live_rescan()
        self._set_status(
            f"[yellow]Removed {enz} from "
            f"{self._editor_catalog!r}.[/yellow]"
        )

    def _add_to_current(self, enz: str) -> None:
        """The single code path that pushes an enzyme into the active
        catalog (Enter / Space / double-click / Add button all route
        here). After-add UX: focus the search input + clear it so the
        user can immediately type the next query."""
        if self._mode != self._MODE_EDITOR or not self._editor_catalog:
            self._set_status(
                "[yellow]Open a catalog first (right pane → "
                "Open).[/yellow]"
            )
            return
        if enz not in _all_enzymes():
            self._set_status(
                f"[red]Unknown enzyme {enz!r} — refresh and try "
                f"again.[/red]"
            )
            return
        entries = _load_enzyme_collections()
        for entry in entries:
            if entry.get("name") != self._editor_catalog:
                continue
            current = list(entry.get("enzymes") or [])
            if enz in current:
                # Idempotent — but still tell the user something
                # happened, and clear the search bar so the next
                # type-search-add iteration starts from a clean slate.
                self._set_status(
                    f"[dim]{enz} already in "
                    f"{self._editor_catalog!r}.[/dim]"
                )
                self._focus_search(clear=True)
                return
            current.append(enz)
            entry["enzymes"] = sorted(current)
            break
        if not self._save_or_status(entries):
            return
        self._refresh_master_table()  # dim newly-added row
        self._refresh_current_table()
        self._refresh_status()
        self._kick_live_rescan()
        self._set_status(
            f"[green]Added {enz} to "
            f"{self._editor_catalog!r}.[/green]"
        )
        # The user wants the search bar focused + cleared so they can
        # type the NEXT enzyme name without reaching for the mouse.
        self._focus_search(clear=True)

    # ── Add new enzyme (extend master) ────────────────────────────────────

    @on(Button.Pressed, "#ec-add-master")
    def _add_master_btn(self, _) -> None:
        def _on_added(payload: "dict | None") -> None:
            if not payload:
                return
            self._refresh_master_table()
            # Repaint the live restriction overlay so a newly-added master
            # enzyme whose site occurs in the loaded plasmid shows its cuts
            # immediately. Without this the overlay only refreshed on the
            # sibling "add to active catalog" path (which already calls it),
            # so a master-add went unreflected until the user navigated away
            # and back. In the default config (no active enzyme collection)
            # the overlay scans the full master catalog, so the new enzyme's
            # sites genuinely belong on the map right away.
            self._kick_live_rescan()
            self._set_status(
                f"[green]Added {payload.get('name')} to master "
                f"catalog.[/green]"
            )
            # Bring focus back so the search-add cycle resumes.
            self._focus_search(clear=False)
        self.app.push_screen(AddCustomEnzymeModal(), _on_added)

    # ── Live restriction-overlay rescan ───────────────────────────────────

    def _kick_live_rescan(self) -> None:
        """Re-dispatch the restriction scan on the underlying canvas so
        the overlay reflects the new active catalog immediately. Best-
        effort — silently no-ops if no record is loaded."""
        try:
            app = self.app
            cur = getattr(app, "_current_record", None)
            if cur is None:
                return
            try:
                pm = app.query_one("#plasmid-map", PlasmidMap)
                pm._restr_feats = []
                pm.refresh()
            except NoMatches:
                pass
            app._dispatch_restr_scan(str(cur.seq))  # type: ignore[attr-defined]
        except (AttributeError, NoMatches):
            pass

    # ── Enzyme Settings tab handlers ──────────────────────────────────────
    # Each handler routes through the existing `action_toggle_*`
    # methods so the rescan + persist + notify wiring stays in one
    # place. The "differs" guard makes the initial Changed event
    # (fired during compose when `value=...` matches the current
    # state) a no-op — without it, every modal mount would emit a
    # spurious "Restriction enzymes shown" toast.

    @on(Checkbox.Changed, "#ec-set-show-restr")
    def _on_settings_show_restr(self, event: Checkbox.Changed) -> None:
        app = self.app
        current = bool(getattr(app, "_show_restr", True))
        if bool(event.value) != current:
            try:
                app.action_toggle_restr()  # type: ignore[attr-defined]
            except (AttributeError, NoMatches):
                pass

    @on(Checkbox.Changed, "#ec-set-unique")
    def _on_settings_unique(self, event: Checkbox.Changed) -> None:
        app = self.app
        current = bool(getattr(app, "_restr_unique_only", True))
        if bool(event.value) != current:
            try:
                app.action_toggle_restr_unique()  # type: ignore[attr-defined]
            except (AttributeError, NoMatches):
                pass

    @on(RadioSet.Changed, "#ec-set-min-len")
    def _on_settings_min_len(self, event: RadioSet.Changed) -> None:
        app = self.app
        pressed_id = getattr(event.pressed, "id", "") or ""
        current = int(getattr(app, "_restr_min_len", 6))
        try:
            if pressed_id == "ec-set-min-4" and current != 4:
                app.action_toggle_restr_min4()  # type: ignore[attr-defined]
            elif pressed_id == "ec-set-min-6" and current != 6:
                app.action_toggle_restr_min6()  # type: ignore[attr-defined]
        except (AttributeError, NoMatches):
            pass

    @on(Checkbox.Changed, "#ec-set-connectors")
    def _on_settings_connectors(self, event: Checkbox.Changed) -> None:
        app = self.app
        # `_show_connectors` lives on the seq-panel + plasmid-map,
        # not on the app — fetch it defensively so the differs guard
        # falls back to the persisted setting if the panel isn't
        # mounted (unit tests).
        try:
            sp = app.query_one("#seq-panel", SequencePanel)
            current = bool(getattr(sp, "_show_connectors", True))
        except NoMatches:
            current = bool(_get_setting("show_connectors", True))
        if bool(event.value) != current:
            try:
                app.action_toggle_connectors()  # type: ignore[attr-defined]
            except (AttributeError, NoMatches):
                pass

    # ── Close ─────────────────────────────────────────────────────────────

    @on(Button.Pressed, "#ec-close")
    def _close_btn(self, _) -> None:
        self._dismiss_once(None)

    def action_close(self) -> None:
        self._dismiss_once(None)


class SettingsModal(_OneShotDismissScreen, ModalScreen):
    """Consolidate every entry from the Settings dropdown into a
    single dialog.

    Three groups: **Display** (feature tooltips, click-debug echo),
    **Workflow** (update check, Constructor grammar filter), and
    **Primers** (min primer binding integer). A final **Advanced**
    section holds buttons that launch sub-modals — cloning grammars,
    entry vectors, enzyme collections, restore from backup.

    Toggles bind directly to `_set_setting` + the live `app._<key>`
    field so the change is effective immediately without going
    through the existing `action_toggle_*` methods (the modal lives
    on the screen stack; calling those actions while we're on top
    would race the live state).

    `_blocks_undo = True` because every interaction mutates persistent
    state (settings.json).
    """

    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "close", "Close"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    DEFAULT_CSS = """
    #set-dlg {
        width: 80; height: auto; max-height: 92%;
        background: $surface; border: solid $primary; padding: 1 2;
    }
    #set-title {
        background: $primary-darken-2; color: $text;
        padding: 0 1; margin-bottom: 1; text-align: center;
    }
    .set-group-label {
        color: $accent; margin-top: 1; margin-bottom: 0;
        text-style: bold;
    }
    .set-row { height: 3; padding: 0 1; }
    .set-row Label { width: 36; padding: 1 0 0 0; }
    .set-row Input { width: 12; }
    .set-row Button { margin-left: 1; }
    /* Plasmidsaurus credential rows: narrow label, wide value field. */
    .set-row-ps Label { width: 16; }
    .set-row-ps Input { width: 48; }
    #set-ps-note { margin: 0 1; }
    Checkbox { width: 74; margin-left: 1; }
    #set-status { min-height: 1; margin-top: 1; }
    #set-btns { align: right middle;  height: 3; margin-top: 1; }
    #set-btns Button { margin-right: 1; }
    """

    def compose(self) -> ComposeResult:
        app = self.app
        # VerticalScroll (not Vertical): the Settings dialog has grown past the
        # baseline-terminal height as toggles accumulated, so it now scrolls
        # within its `max-height` instead of overflowing off-screen. Escape +
        # the Close button both still dismiss it from anywhere in the scroll.
        with VerticalScroll(id="set-dlg"):
            yield Static(" Settings ", id="set-title")
            yield Static("Display", classes="set-group-label")
            yield Checkbox(
                "Show feature hover tooltips",
                value=bool(getattr(app, "_show_feature_tooltips", False)),
                id="set-tooltips",
            )
            yield Checkbox(
                "Show button tooltips",
                value=bool(getattr(app, "_show_button_tooltips", True)),
                id="set-button-tooltips",
            )
            yield Checkbox(
                "Click debug echo  (Alt+M also toggles)",
                value=bool(getattr(app, "_click_debug", False)),
                id="set-click-debug",
            )
            yield Checkbox(
                "ASCII plasmid map  (if braille shows as boxes)",
                value=bool(_state._ASCII_MODE),
                id="set-ascii-map",
            )
            yield Static("Workflow", classes="set-group-label")
            yield Checkbox(
                "Check for updates on launch",
                value=bool(getattr(app, "_check_updates", True)),
                id="set-check-updates",
            )
            yield Checkbox(
                "Filter Constructor parts by grammar",
                value=bool(getattr(
                    app, "_constructor_filter_by_grammar", True,
                )),
                id="set-constr-filter",
            )
            yield Checkbox(
                "Allow agent online BLAST/HMMER (sends seqs to NCBI/EBI)",
                value=bool(_get_setting("allow_online_search", False)),
                id="set-allow-online",
            )
            yield Checkbox(
                "Allow Babs online database lookups (sends only a query)",
                value=bool(_get_setting("allow_online_lookups", False)),
                id="set-allow-online-lookups",
            )
            yield Static("Primers", classes="set-group-label")
            with Horizontal(classes="set-row"):
                yield Label("Min primer binding (bp):")
                yield Input(
                    value=str(getattr(app, "_min_primer_binding", 15)),
                    id="set-min-primer",
                    restrict=r"[0-9]*",
                )
                yield Button("Apply", id="set-min-primer-apply")
            yield Static("Plasmidsaurus API", classes="set-group-label")
            yield Static(
                "[dim]Credentials for ‘Fetch from Plasmidsaurus API’ "
                "(Sequencing screen). Leave blank to use the "
                "PLASMIDSAURUS_CLIENT_ID / _SECRET environment variables "
                "instead. Saved here, the secret is stored UNENCRYPTED in "
                "your data dir — prefer the env vars on shared machines.[/dim]",
                id="set-ps-note", markup=True,
            )
            with Horizontal(classes="set-row set-row-ps"):
                yield Label("Client ID:")
                yield Input(
                    value=str(_get_setting("plasmidsaurus_client_id", "")),
                    id="set-ps-id",
                )
            with Horizontal(classes="set-row set-row-ps"):
                yield Label("Client Secret:")
                yield Input(
                    value=str(_get_setting("plasmidsaurus_client_secret", "")),
                    id="set-ps-secret", password=True,
                )
            with Horizontal(classes="set-row"):
                yield Button("Save credentials", id="set-ps-save")
                yield Button("Clear", id="set-ps-clear")
            yield Static(
                "Online lookup API keys (optional)",
                classes="set-group-label",
            )
            yield Static(
                "[dim]Optional — make Babs’ web + patent search robust. A "
                "Brave Search key (free tier) powers ‘web-search’; a "
                "PatentsView key powers ‘patent-search’. Without keys these "
                "fall back to keyless Google/DuckDuckGo, which rate-limit. "
                "Requires the lookup toggle above. Stored UNENCRYPTED in your "
                "data dir — prefer a machine you control.[/dim]",
                id="set-lookup-note", markup=True,
            )
            with Horizontal(classes="set-row set-row-ps"):
                yield Label("Brave Search key:")
                yield Input(
                    value=str(_get_setting("brave_search_api_key", "")),
                    id="set-brave-key", password=True,
                )
            with Horizontal(classes="set-row set-row-ps"):
                yield Label("PatentsView key:")
                yield Input(
                    value=str(_get_setting("patentsview_api_key", "")),
                    id="set-pv-key", password=True,
                )
            with Horizontal(classes="set-row"):
                yield Button("Save keys", id="set-lookup-keys-save")
                yield Button("Clear", id="set-lookup-keys-clear")
            yield Static("Advanced", classes="set-group-label")
            with Horizontal(classes="set-row"):
                yield Button(
                    "Cloning grammars", id="set-grammars",
                )
                yield Button(
                    "Entry Vectors", id="set-entry-vectors",
                )
            with Horizontal(classes="set-row"):
                yield Button(
                    "Enzyme collections", id="set-enzyme-collections",
                )
                yield Button(
                    "Codon Tables", id="set-codon-tables",
                )
            with Horizontal(classes="set-row"):
                yield Button(
                    "Restore from backup", id="set-restore",
                )
            yield Static("", id="set-status", markup=True)
            with Horizontal(id="set-btns"):
                yield Button("Close", id="set-close")

    def _set_status(self, markup: str) -> None:
        try:
            self.query_one("#set-status", Static).update(markup)
        except NoMatches:
            pass

    # ── Plasmidsaurus credential handlers ─────────────────────────────────
    @on(Button.Pressed, "#set-ps-save")
    def _ps_save_creds(self, _) -> None:
        """Persist the Plasmidsaurus Client ID + Secret to settings. The
        secret is redacted in the change log (`_SENSITIVE_SETTING_KEYS`) and
        is never exposed via the agent settings allowlist."""
        try:
            cid = self.query_one("#set-ps-id", Input).value.strip()
            sec = self.query_one("#set-ps-secret", Input).value.strip()
        except NoMatches:
            return
        _set_setting("plasmidsaurus_client_id", cid)
        _set_setting("plasmidsaurus_client_secret", sec)
        if cid and sec:
            self._set_status(
                "[green]Plasmidsaurus credentials saved.[/green]")
        else:
            self._set_status(
                "[yellow]Saved — but both Client ID and Secret are needed "
                "to use the API (env vars also work).[/yellow]")

    @on(Button.Pressed, "#set-ps-clear")
    def _ps_clear_creds(self, _) -> None:
        """Wipe the stored Plasmidsaurus credentials (the env vars, if set,
        still take over)."""
        for sel in ("#set-ps-id", "#set-ps-secret"):
            try:
                self.query_one(sel, Input).value = ""
            except NoMatches:
                pass
        _set_setting("plasmidsaurus_client_id", "")
        _set_setting("plasmidsaurus_client_secret", "")
        self._set_status("[green]Plasmidsaurus credentials cleared.[/green]")

    # ── Toggle handlers ───────────────────────────────────────────────────
    #
    # We mirror onto the live app instance + persist via `_set_setting`
    # directly rather than calling `app.action_toggle_<key>()`. The
    # action wrappers fire `self.notify(...)` which is fine, but they
    # also assume "fresh toggle from menu" semantics — calling them
    # from within the modal would race the live state we just read.

    @on(Checkbox.Changed, "#set-tooltips")
    def _on_tooltips(self, event: Checkbox.Changed) -> None:
        app = self.app
        app._show_feature_tooltips = bool(event.value)  # type: ignore[attr-defined]
        _set_setting("show_feature_tooltips", bool(event.value))
        if not event.value:
            # Wipe any tooltip currently shown.
            for sel, cls in (("#plasmid-map", PlasmidMap),
                              ("#seq-panel",   SequencePanel)):
                try:
                    app.query_one(sel, cls).tooltip = None
                except (NoMatches, AttributeError):
                    pass

    @on(Checkbox.Changed, "#set-button-tooltips")
    def _on_button_tooltips(self, event: Checkbox.Changed) -> None:
        """Persist + LIVE-apply the global button-tooltip on/off toggle. Writes
        the setting, flips the app flag, and re-applies to EVERY screen on the
        stack (this Settings modal + the main screen beneath) so the change is
        immediate, not deferred to the next mount. Idempotent + best-effort."""
        app = self.app
        app._show_button_tooltips = bool(event.value)  # type: ignore[attr-defined]
        _set_setting("show_button_tooltips", bool(event.value))
        apply = getattr(app, "_apply_button_tooltip_visibility", None)
        if callable(apply):
            try:
                for scr in list(getattr(app, "screen_stack", []) or []):
                    apply(scr)
            except Exception:
                _log.exception(
                    "settings: live button-tooltip re-apply failed")

    @on(Checkbox.Changed, "#set-ascii-map")
    def _on_ascii_map(self, event: Checkbox.Changed) -> None:
        """Persist + LIVE-apply the braille⇄ASCII map toggle — the escape hatch
        for a terminal whose font can't draw braille (U+2800-U+28FF). Flips the
        module render flag, busts the map draw cache, and repaints at once."""
        _set_ascii_mode(bool(event.value))
        _set_setting("ascii_map", bool(event.value))
        refresh = getattr(self.app, "_refresh_plasmid_map", None)
        if callable(refresh):
            refresh()

    @on(Checkbox.Changed, "#set-click-debug")
    def _on_click_debug(self, event: Checkbox.Changed) -> None:
        # Sweep #26: route through the canonical action so the
        # counter reset + informational toast fire (parity with
        # `Alt+M`). Pre-fix the modal toggle silently set the flag
        # with no UI feedback while Alt+M had a long explanatory
        # toast describing what click-debug does. Mirror with the
        # same value the checkbox now reflects: if the checkbox is
        # going from False → True we want the action to enable,
        # so call action_toggle_click_debug to flip the current
        # value and then resync if needed.
        app = self.app
        target = bool(event.value)
        if (getattr(app, "_click_debug", False)  # type: ignore[attr-defined]
                != target):
            app.action_toggle_click_debug()  # type: ignore[attr-defined]
        # else: state already matches (e.g. event fired from `value=`
        # at modal compose-time hydration), no action.

    @on(Checkbox.Changed, "#set-check-updates")
    def _on_check_updates(self, event: Checkbox.Changed) -> None:
        # Sweep #26: route through the canonical action so the
        # "Update check on launch: enabled/disabled" toast fires.
        # Pre-fix the modal toggle silently set the flag without
        # confirmation; `action_toggle_check_updates` was an orphan
        # method that the modal had supplanted but never replaced.
        app = self.app
        target = bool(event.value)
        if (getattr(app, "_check_updates", False)  # type: ignore[attr-defined]
                != target):
            app.action_toggle_check_updates()  # type: ignore[attr-defined]

    @on(Checkbox.Changed, "#set-constr-filter")
    def _on_constr_filter(self, event: Checkbox.Changed) -> None:
        app = self.app
        app._constructor_filter_by_grammar = bool(event.value)  # type: ignore[attr-defined]
        _set_setting(
            "constructor_filter_by_grammar", bool(event.value),
        )

    @on(Checkbox.Changed, "#set-allow-online")
    def _on_allow_online(self, event: Checkbox.Changed) -> None:
        """Arm / disarm the agent-API online-search egress gate. Persisted
        straight to settings.json (no live app mirror needed — the
        `blast-online` / `hmmer-web` handlers read `_get_setting` at call
        time). This is the HUMAN half of the two-key model: the setting is
        absent from the agent settings allowlist, so an autonomous agent
        can't flip it — only this toggle (or a hand-edited settings.json)
        can. A status note reinforces what arming it means."""
        on = bool(event.value)
        _set_setting("allow_online_search", on)
        if on:
            self._set_status(
                "[yellow]Agent online search ARMED — agents may now send "
                "query sequences to NCBI / EBI. Disarm to keep all search "
                "in-process.[/yellow]")
        else:
            self._set_status(
                "[green]Agent online search disarmed — all agent search "
                "stays in-process (nothing leaves this machine).[/green]")

    @on(Checkbox.Changed, "#set-allow-online-lookups")
    def _on_allow_online_lookups(self, event: Checkbox.Changed) -> None:
        """Arm / disarm the online reference-database LOOKUP gate (FPbase /
        UniProt / literature / GenBank / Wikipedia / web / patents). Persisted
        straight to settings.json — the `*-search` handlers read
        `_get_setting` at call time. Separate from the BLAST/HMMER gate above:
        these lookups send only a query STRING, never a sequence. Human-only
        (absent from the agent settings allowlist), so an agent can't self-arm."""
        on = bool(event.value)
        _set_setting("allow_online_lookups", on)
        if on:
            self._set_status(
                "[yellow]Babs online lookups ARMED — a query string may now be "
                "sent to public databases (FPbase, UniProt, NCBI, patents, the "
                "web). Your sequences never leave the box.[/yellow]")
        else:
            self._set_status(
                "[green]Babs online lookups disarmed — nothing leaves this "
                "machine.[/green]")

    @on(Button.Pressed, "#set-lookup-keys-save")
    def _lookup_keys_save(self, _) -> None:
        """Persist the optional Brave Search + PatentsView API keys. Both are
        redacted in the change log (`_SENSITIVE_SETTING_KEYS`) and never exposed
        via the agent settings allowlist."""
        try:
            brave = self.query_one("#set-brave-key", Input).value.strip()
            pv = self.query_one("#set-pv-key", Input).value.strip()
        except NoMatches:
            return
        _set_setting("brave_search_api_key", brave)
        _set_setting("patentsview_api_key", pv)
        armed = bool(_get_setting("allow_online_lookups", False))
        have = [n for n, v in (("Brave", brave), ("PatentsView", pv)) if v]
        msg = ("Saved " + " + ".join(have) + " key"
               + ("s" if len(have) > 1 else "")) if have else "Keys cleared"
        if have and not armed:
            self._set_status(
                f"[yellow]{msg} — but turn on ‘Allow Babs online database "
                f"lookups’ above to use them.[/yellow]")
        else:
            self._set_status(f"[green]{msg}.[/green]")

    @on(Button.Pressed, "#set-lookup-keys-clear")
    def _lookup_keys_clear(self, _) -> None:
        """Wipe the stored Brave + PatentsView keys (the keyless best-effort
        fallbacks still work)."""
        for sel in ("#set-brave-key", "#set-pv-key"):
            try:
                self.query_one(sel, Input).value = ""
            except NoMatches:
                pass
        _set_setting("brave_search_api_key", "")
        _set_setting("patentsview_api_key", "")
        self._set_status("[green]Online-lookup API keys cleared.[/green]")

    # ── Min primer binding ────────────────────────────────────────────────

    @on(Button.Pressed, "#set-min-primer-apply")
    def _on_min_primer_apply(self, _) -> None:
        try:
            inp = self.query_one("#set-min-primer", Input)
        except NoMatches:
            return
        try:
            val = int((inp.value or "").strip())
        except ValueError:
            self._set_status(
                "[red]Min primer binding must be an integer.[/red]"
            )
            return
        if not (1 <= val <= 60):
            self._set_status(
                "[red]Min primer binding must be 1–60 bp.[/red]"
            )
            return
        app = self.app
        try:
            app._apply_min_primer_binding(val)  # type: ignore[attr-defined]
        except Exception:
            _log.exception("min primer binding apply failed")
            self._set_status(
                "[red]Failed to apply — see log.[/red]"
            )
            return
        self._set_status(
            f"[green]Min primer binding: {val} bp.[/green]"
        )

    # ── Sub-modal launchers ───────────────────────────────────────────────

    @on(Button.Pressed, "#set-grammars")
    def _on_grammars(self, _) -> None:
        self.app.push_screen(GrammarManagerModal())

    @on(Button.Pressed, "#set-entry-vectors")
    def _on_entry_vectors(self, _) -> None:
        self.app.push_screen(EntryVectorsModal())

    @on(Button.Pressed, "#set-enzyme-collections")
    def _on_enzyme_collections(self, _) -> None:
        self.app.push_screen(EnzymeCollectionsModal())

    @on(Button.Pressed, "#set-codon-tables")
    def _on_codon_tables(self, _) -> None:
        # Codon-table collections used to be reachable only through the
        # Domesticator / Synthesis codon picker. This Settings entry opens
        # the same manager (`SpeciesPickerModal`: browse, fetch from Kazusa,
        # import a TSV, delete). "Use Selected" sets the LAUNCH DEFAULT — the
        # persisted `active_codon_table` taxid that SynthesisScreen's
        # `_init_codon_table` honors on open — which previously had no GUI
        # entry point (only the `set-active-codon-table` agent endpoint).
        self.app.push_screen(SpeciesPickerModal(),
                             callback=self._codon_table_default_picked)

    def _codon_table_default_picked(self, entry: "dict | None") -> None:
        # Cancel (None) leaves the default untouched; any fetch / import /
        # delete the user did inside the manager already persisted on its own.
        if not entry:
            return
        taxid = str(entry.get("taxid", "") or "").strip()
        name = str(entry.get("name", "") or "?")
        if not taxid:
            # `active_codon_table` matches by taxid (see `_init_codon_table`),
            # so a taxid-less table can't be the launch default. It's still
            # saved in the registry — just not settable as the default here.
            self._set_status(
                f"[yellow]'{name}' has no taxid, so it can't be the launch "
                f"default — it's still saved in your codon tables.[/yellow]")
            return
        _set_setting("active_codon_table", taxid)
        _log_event("settings.active_codon_table_set", taxid=taxid, name=name)
        self._set_status(
            f"Launch-default codon table set to [bold]{name}[/bold] "
            f"(taxid {taxid}). Synthesis uses it on next open.")

    @on(Button.Pressed, "#set-restore")
    def _on_restore(self, _) -> None:
        self.app.push_screen(RestoreFromBackupModal())

    # ── Close ─────────────────────────────────────────────────────────────

    @on(Button.Pressed, "#set-close")
    def _close_btn(self, _) -> None:
        self.dismiss(None)

    def action_close(self) -> None:
        self.dismiss(None)


class ORFFinderModal(_OneShotDismissScreen, ModalScreen):
    """Find open reading frames in the loaded record.

    Six-frame scan via `_find_orfs`. Default min length is 30 aa
    (≈ 90 bp); the alt-starts checkbox enables GTG / TTG which is
    relevant for bacterial genomes but rare in plasmid CDSes.
    Selecting a row dismisses with the ORF dict so the caller can
    apply a feature-style highlight (cursor + selection range) in
    the seq panel + map.

    Dismiss payload:
      None        — cancelled / closed
      dict (ORF)  — user picked an ORF to highlight
    """

    # Sweep #26: min-aa Input editing — block app-level Ctrl+Z.
    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel",         "Cancel"),
        Binding("tab",    "app.focus_next", "Next",   show=False),
    ]

    def __init__(self, sequence: str, *, circular: bool = True) -> None:
        super().__init__()
        self._seq = sequence
        self._circular = circular
        self._orfs: list[dict] = []

    def compose(self) -> ComposeResult:
        with Vertical(id="orf-box"):
            yield Static(" Find ORFs ", id="orf-title")
            yield Label(f"Sequence: {len(self._seq):,} bp · "
                        f"{'circular' if self._circular else 'linear'}")
            with Horizontal(id="orf-controls"):
                yield Label("Min aa:")
                yield Input(value="30",
                            placeholder="30",
                            id="orf-min-aa", restrict=r"[0-9]*")
                yield Checkbox("GTG / TTG starts",
                               value=False, id="orf-alt-starts")
            with Horizontal(id="orf-btns-top"):
                yield Button("Scan", id="btn-orf-scan", variant="primary")
                yield Button("Close", id="btn-orf-close")
            yield DataTable(id="orf-table", cursor_type="row",
                            zebra_stripes=True)
            yield Static("", id="orf-status", markup=True)

    def on_mount(self) -> None:
        t = self.query_one("#orf-table", DataTable)
        t.add_columns("Start", "End", "Strand", "Length (aa)", "Preview")
        # Initial scan with defaults so the user sees something
        # immediately; rescan via the Scan button after editing controls.
        self._scan()

    def _scan(self) -> None:
        try:
            min_aa = int(
                self.query_one("#orf-min-aa", Input).value or "30"
            )
        except (ValueError, NoMatches):
            min_aa = 30
        try:
            alt = bool(self.query_one("#orf-alt-starts", Checkbox).value)
        except NoMatches:
            alt = False
        try:
            self.query_one("#orf-status", Static).update(
                "[dim]Scanning…[/dim]"
            )
        except NoMatches:
            pass
        # Off-thread: a six-frame scan of a 100 kb+ plasmid is ~50–200 ms
        # and fires on modal open (on_mount), so a synchronous scan
        # stuttered the dialog before the user did anything. Exclusive so
        # rapid Scan clicks / control edits coalesce to the latest.
        # (2026-06-11 audit.)
        self._scan_worker(min_aa, alt)

    @work(thread=True, exclusive=True, group="orf_scan")
    def _scan_worker(self, min_aa: int, alt: bool) -> None:
        orfs = _find_orfs(
            self._seq,
            min_aa=max(1, min_aa),
            include_alt_starts=alt,
            circular=self._circular,
        )
        self.app.call_from_thread(self._apply_orfs, orfs, min_aa)

    def _apply_orfs(self, orfs: "list[dict]", min_aa: int) -> None:
        if not self.is_mounted:
            return
        self._orfs = orfs
        try:
            t = self.query_one("#orf-table", DataTable)
        except NoMatches:
            return
        t.clear()
        for o in self._orfs:
            preview = o["aa_seq"][:24]
            if len(o["aa_seq"]) > 24:
                preview += "…"
            # 1-based bp display matches GenBank coordinates the user
            # reads in features lane / sidebar.
            t.add_row(
                f"{o['start'] + 1:,}",
                f"{o['end']:,}" if o["end"] >= o["start"]
                                else f"{o['end']:,} (wrap)",
                "+" if o["strand"] == 1 else "-",
                str(o["length_aa"]),
                preview,
            )
        try:
            self.query_one("#orf-status", Static).update(
                f"[dim]{len(self._orfs)} ORF(s) ≥ {min_aa} aa[/dim]"
            )
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-orf-scan")
    def _scan_btn(self, _) -> None:
        self._scan()

    @on(DataTable.RowSelected, "#orf-table")
    def _row_selected(self, event: DataTable.RowSelected) -> None:
        idx = event.cursor_row
        if 0 <= idx < len(self._orfs):
            self.dismiss(self._orfs[idx])

    @on(Button.Pressed, "#btn-orf-close")
    def _close_btn(self, _) -> None:
        self.dismiss(None)

    def action_cancel(self) -> None:
        self.dismiss(None)


# ── Bulk-export collection modal ───────────────────────────────────────────────

class BulkExportCollectionModal(ModalScreen):
    """Export every plasmid in a chosen collection to a target folder.

    Three controls:
      * Collection picker — populated from `_load_collections()`.
      * Format picker     — GenBank / EMBL / FASTA / .dna.
      * Folder picker     — DirectoryTree rooted at $HOME.

    Failures are accumulated per-entry, not at the batch level, so a
    single broken plasmid doesn't abort the run. On dismiss, returns
    ``{collection, format, dir, total, written, failures}`` or None
    on cancel.

    `_blocks_undo: True` because the work happens off-thread and we
    don't want undo snapshots interleaving with bulk writes.
    """

    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel",         "Cancel"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    DEFAULT_CSS = """
    #bulkexp-box {
        width: 100; max-width: 95%; min-width: 70;
        height: auto; max-height: 90%;
        background: $surface; border: solid $primary; padding: 1 2;
    }
    #bulkexp-title { background: $primary-darken-2; color: $text;
                     padding: 0 1; margin-bottom: 1; text-align: center; }
    #bulkexp-tree  { height: 14; border: solid $primary-darken-2; }
    #bulkexp-status { height: 3; margin-top: 1; }
    #bulkexp-btns  { height: 3; margin-top: 1; align: right middle; }
    """

    def __init__(self, default_collection: str = "") -> None:
        super().__init__()
        self._default_collection = default_collection
        self._selected_dir = str(Path.home())
        # [INV-50] dismissal guard. Three exit paths: Cancel button,
        # Esc/action_cancel, worker `_ok` callback. Without the flag a
        # quick Cancel+worker race could fire two dismiss calls.
        self._dismissed: bool = False

    def _dismiss_once(self, payload) -> None:
        if self._dismissed:
            return
        self._dismissed = True
        self.dismiss(payload)

    def compose(self) -> ComposeResult:
        with Vertical(id="bulkexp-box"):
            yield Static(" Export collection ", id="bulkexp-title")
            colls = [c.get("name") or "?"
                     for c in _iter_collections_readonly()
                     if isinstance(c, dict)]
            colls = [c for c in colls if c]
            if not colls:
                colls = ["(no collections)"]
            initial_coll = (self._default_collection
                            if self._default_collection in colls
                            else colls[0])
            yield Label("Collection:")
            yield Select(
                [(c, c) for c in colls],
                value=initial_coll, id="bulkexp-collection",
                allow_blank=False,
            )
            yield Label("Format:")
            yield Select(
                [(label, key)
                 for key, (_ext, label) in _BULK_EXPORT_FORMATS.items()],
                value="genbank", id="bulkexp-format",
                allow_blank=False,
            )
            yield Static(
                f"Save in: [b]{self._selected_dir}[/b]",
                id="bulkexp-dir", markup=True,
            )
            yield DirectoryTree(str(Path.home()), id="bulkexp-tree")
            yield Static("", id="bulkexp-status", markup=True)
            with Horizontal(id="bulkexp-btns"):
                yield Button("Export",  id="btn-bulkexp", variant="primary")
                yield Button("Cancel",  id="btn-bulkexp-cancel")

    @on(DirectoryTree.DirectorySelected, "#bulkexp-tree")
    def _on_dir(self, event) -> None:
        self._selected_dir = str(event.path)
        try:
            self.query_one("#bulkexp-dir", Static).update(
                f"Save in: [b]{self._selected_dir}[/b]"
            )
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-bulkexp")
    def _do_export(self, _) -> None:
        try:
            coll_sel = self.query_one("#bulkexp-collection", Select).value
            fmt_sel = self.query_one("#bulkexp-format", Select).value
            status = self.query_one("#bulkexp-status", Static)
        except NoMatches:
            return
        if not isinstance(coll_sel, str) or not isinstance(fmt_sel, str):
            status.update("[red]Pick a collection and a format first.[/red]")
            return
        if fmt_sel not in _BULK_EXPORT_FORMATS:
            status.update(f"[red]Unknown format: {fmt_sel}[/red]")
            return
        try:
            self.query_one("#btn-bulkexp", Button).disabled = True
        except NoMatches:
            pass
        status.update(
            f"[dim]Exporting {coll_sel!r} as {fmt_sel} → "
            f"{self._selected_dir}…[/dim]"
        )
        self._do_worker(coll_sel, fmt_sel, self._selected_dir)

    @work(thread=True, exclusive=True, group="bulk_export")
    def _do_worker(self, coll: str, fmt: str, target_dir: str) -> None:
        # Progress hook: feeds the status line on the UI thread so a
        # 500-plasmid bulk export doesn't look frozen. Throttled to
        # one update per ~8 entries so DataTable / Static churn stays
        # below 33 ms / frame on even very large libraries.
        def _on_progress(i: int, total: int, name: str, ok: bool) -> None:
            if i != total and (i % 8) != 0:
                return
            def _update():
                if not self.is_mounted:
                    return
                try:
                    self.query_one("#bulkexp-status", Static).update(
                        f"[dim]Exporting {i}/{total} ({name})…[/dim]"
                    )
                except NoMatches:
                    pass
            try:
                self.app.call_from_thread(_update)
            except RuntimeError:
                # App tearing down mid-export — drop the update silently;
                # the worker still finishes its current write.
                pass
        try:
            result = _bulk_export_collection(
                coll, fmt, target_dir, progress_cb=_on_progress,
            )
        except (OSError, ValueError) as exc:
            _log.exception("Bulk export failed")
            err_msg = str(exc)
            def _fail():
                if not self.is_mounted:
                    return
                try:
                    self.query_one("#bulkexp-status", Static).update(
                        f"[red]Export failed: {err_msg}[/red]"
                    )
                    self.query_one("#btn-bulkexp", Button).disabled = False
                except NoMatches:
                    pass
            self.app.call_from_thread(_fail)
            return

        def _ok():
            if not self.is_mounted:
                return
            self._dismiss_once({"collection": coll, **result})
        self.app.call_from_thread(_ok)

    @on(Button.Pressed, "#btn-bulkexp-cancel")
    def _cancel(self, _) -> None:
        self._dismiss_once(None)

    def action_cancel(self) -> None:
        self._dismiss_once(None)


# ── Dropdown menu modal ────────────────────────────────────────────────────────



class MigrateExportModal(_OneShotDismissScreen, ModalScreen):
    """Pick the destination folder + filename for the exported data
    archive, and whether to also include the (large, re-downloadable)
    HMM databases. Dismisses with ``{dir, filename, include_hmm}`` or
    ``None``."""

    _blocks_undo: bool = True
    BINDINGS = [Binding("escape", "cancel", "Cancel")]
    DEFAULT_CSS = """
    #migexp-box { width: 96; max-width: 95%; height: auto; max-height: 92%;
        background: $surface; border: solid $primary; padding: 1 2; }
    #migexp-title { background: $primary-darken-2; color: $text;
        padding: 0 1; margin-bottom: 1; text-align: center; }
    #migexp-tree { height: 13; border: solid $primary-darken-2; }
    #migexp-name { margin-top: 0; }
    #migexp-hmm { margin-top: 1; }
    #migexp-status { height: 2; margin-top: 1; }
    #migexp-btns { height: 3; margin-top: 1; align: right middle; }
    #migexp-btns Button { margin-left: 1; }
    """

    def __init__(self, start_path: "str | None" = None) -> None:
        super().__init__()
        start = Path(start_path).expanduser() if start_path else Path.home()
        try:
            if not start.is_dir():
                start = Path.home()
        except OSError:
            start = Path.home()
        self._dir = str(start)
        self._default_name = f"splicecraft-data-{_now().strftime('%Y-%m-%d')}.zip"

    def compose(self) -> ComposeResult:
        with Vertical(id="migexp-box"):
            yield Static(" Export all data → one portable .zip ",
                         id="migexp-title")
            yield Static(f"Save in: [b]{self._dir}[/b]", id="migexp-dir",
                         markup=True)
            yield DirectoryTree(self._dir, id="migexp-tree")
            yield Label("File name:")
            yield Input(value=self._default_name, id="migexp-name")
            yield Checkbox(
                "Also include downloaded HMM databases (large; usually "
                "re-downloadable from the included catalog)",
                id="migexp-hmm", value=False)
            yield Static("", id="migexp-status", markup=True)
            with Horizontal(id="migexp-btns"):
                yield Button("Export", id="btn-migexp", variant="primary")
                yield Button("Cancel", id="btn-migexp-cancel")

    @on(DirectoryTree.DirectorySelected, "#migexp-tree")
    def _on_dir(self, event) -> None:
        self._dir = str(event.path)
        try:
            self.query_one("#migexp-dir", Static).update(
                f"Save in: [b]{self._dir}[/b]")
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-migexp")
    def _go(self, _) -> None:
        try:
            name = self.query_one("#migexp-name", Input).value.strip()
            status = self.query_one("#migexp-status", Static)
            hmm = bool(self.query_one("#migexp-hmm", Checkbox).value)
        except NoMatches:
            return
        if not name:
            status.update("[red]Enter a file name.[/red]")
            return
        if not name.lower().endswith(".zip"):
            name += ".zip"
        self.dismiss({"dir": self._dir, "filename": name, "include_hmm": hmm})

    @on(Button.Pressed, "#btn-migexp-cancel")
    def _cxl(self, _) -> None:
        self.dismiss(None)

    def action_cancel(self) -> None:
        self.dismiss(None)


