class MigrateImportConfirmModal(_OneShotDismissScreen, ModalScreen):
    """Last-chance confirm before an import REPLACES the current data.
    Shows the archive's provenance (read from its marker) and the
    automatic-backup safety net. Dismisses ``True`` / ``False``."""

    _blocks_undo: bool = True
    BINDINGS = [Binding("escape", "cancel", "Cancel")]
    DEFAULT_CSS = """
    #migcfm-box { width: 88; max-width: 95%; height: auto; max-height: 90%;
        background: $surface; border: solid $warning; padding: 1 2; }
    #migcfm-title { background: $warning-darken-2; color: $text;
        padding: 0 1; margin-bottom: 1; text-align: center; }
    #migcfm-prov { margin-bottom: 1; }
    #migcfm-body { color: $text-muted; margin-bottom: 1; }
    #migcfm-btns { height: 3; margin-top: 1; align: right middle; }
    #migcfm-btns Button { margin-left: 1; }
    """

    def __init__(self, zip_path: "str | Path") -> None:
        super().__init__()
        self._zip = str(zip_path)
        self._info = self._peek_marker()

    def _peek_marker(self) -> "dict | None":
        import zipfile as _zf
        try:
            with _zf.ZipFile(self._zip) as z:
                m = json.loads(z.read(_MIGRATE_MARKER_NAME).decode("utf-8"))
            if isinstance(m, dict) and m.get("format") == "splicecraft-migrate":
                return m
        except Exception:
            pass
        return None

    def compose(self) -> ComposeResult:
        with Vertical(id="migcfm-box"):
            yield Static(" Import data — replace current? ", id="migcfm-title")
            if self._info:
                prov = (
                    f"Archive from SpliceCraft "
                    f"v{self._info.get('app_version', '?')}, created "
                    f"{self._info.get('created', '?')}.")
            else:
                prov = ("[red]This file doesn't look like a SpliceCraft data "
                        "archive — the import will refuse it.[/red]")
            yield Static(prov, id="migcfm-prov", markup=True)
            yield Static(
                "Importing REPLACES all of this install's SpliceCraft data "
                "with the archive's contents. Your current data is snapshotted "
                "automatically first, so you can undo with\n"
                "    splicecraft update --restore-pre-update latest\n\n"
                "After importing, restart SpliceCraft to load the new data.",
                id="migcfm-body", markup=False,
            )
            with Horizontal(id="migcfm-btns"):
                yield Button("Import + replace", id="btn-migcfm-go",
                             variant="warning")
                yield Button("Cancel", id="btn-migcfm-cancel")

    @on(Button.Pressed, "#btn-migcfm-go")
    def _go(self, _) -> None:
        self.dismiss(True)

    @on(Button.Pressed, "#btn-migcfm-cancel")
    def _cxl(self, _) -> None:
        self.dismiss(False)

    def action_cancel(self) -> None:
        self.dismiss(False)




