# Online NAME/term lookup as a FIRST-CLASS Babs tool. The `*-search` endpoints
# (INV-145) otherwise sit among ~180 endpoints the local model must discover via
# `list_endpoints`, and small models miss them — they reach for `blast-online`
# (which needs a full sequence, not a name) and give up. Mapping: search
# `source` → the read-only agent endpoint it dispatches to. Every one sends ONLY
# the query string (never the user's sequence) and is gated by the human-armed
# `allow_online_lookups` setting — a disarmed call 403s and Babs relays it.
_BABS_SEARCH_SOURCES = {
    "fpbase":     "fpbase-search",      # fluorescent proteins (GFP: spectra, oligomerization, GenBank xref)
    "genbank":    "genbank-search",     # NCBI nucleotide/protein records by name → accessions (feed `fetch`)
    "uniprot":    "uniprot-search",     # proteins
    "literature": "literature-search",  # papers (Europe PMC)
    "wikipedia":  "wikipedia-search",
    "web":        "web-search",
    "patent":     "patent-search",
}

# Agent endpoints that ALWAYS command PHYSICAL robot motion. Babs always asks a
# human before firing these — even in 'auto' autonomy — because the OT-2 is real
# hardware and the model can self-supply each endpoint's own `confirm` flag (so
# `confirm:true` is NOT an independent human gate). A denied prompt stops the
# motion. Zero-motion robot writes (e.g. ot2-lights) follow normal autonomy;
# ot2-run-control is treated as physical only for resume/play (see
# _dispatch_agent_endpoint) since pause/stop halt the gantry.
_BABS_PHYSICAL_MOTION_ENDPOINTS = frozenset({
    "ot2-run", "ot2-home", "ot2-position-check", "ot2-disengage",
})

_BABS_SEARCH_TOOL = {"type": "function", "function": {
    "name": "splicecraft_search_online",
    "description": (
        "Look a NAME or term up ONLINE. Use this for any 'look up / find X "
        "online' request — NOT blast-online (that needs a full sequence, not a "
        "name). Only your short query string is sent; the user's sequence never "
        "leaves the machine. Choose `source`: fpbase (fluorescent proteins like "
        "GFP — spectra, oligomerization, GenBank xref), genbank (any gene / "
        "plasmid / record by name → accessions you can then `fetch`), uniprot "
        "(proteins), literature (papers), wikipedia, web, patent. If it returns "
        "403, the user must arm Settings → \"Allow Babs online database "
        "lookups\" — relay that."),
    "parameters": {"type": "object", "properties": {
        "source": {"type": "string", "enum": sorted(_BABS_SEARCH_SOURCES),
                   "description": "which database / service to query"},
        "query": {"type": "string",
                  "description": "the name or term to look up"},
        "max_hits": {"type": "integer",
                     "description": "optional cap on results (default 10)"},
    }, "required": ["source", "query"]},
}}


# Open a page and READ it — the companion to `splicecraft_search_online`. Search
# returns titles + URLs + snippets; this fetches ONE result and returns its text
# (HTML stripped, no JavaScript). Dispatches to the read-only `read-url` endpoint
# (same `allow_online_lookups` gate; SSRF-hardened; binary pages refused).
_BABS_READ_URL_TOOL = {"type": "function", "function": {
    "name": "splicecraft_fetch_page",
    "description": (
        "Open ONE web page by URL and read its text (HTML stripped to text; "
        "JavaScript is NOT run). Use this to actually READ a result you got from "
        "splicecraft_search_online — the search only gives titles, URLs and "
        "short snippets; this returns the page body. Only public http(s) pages; "
        "binary files (PDF, images) are refused. If it returns 403, the user "
        "must arm Settings → \"Allow Babs online database lookups\" — relay "
        "that."),
    "parameters": {"type": "object", "properties": {
        "url": {"type": "string", "description": "the http(s) URL to open"},
        "max_chars": {"type": "integer",
                      "description": "optional cap on returned text (default 20000)"},
    }, "required": ["url"]},
}}


# Run SEVERAL endpoints in ONE model step — the multi-call companion to
# splicecraft_call. Lets Babs carry out a whole workflow per turn instead of
# spending a turn per endpoint, so multi-step tasks finish inside the iteration
# budget. Each call still runs through the SAME autonomy gate; in ask-mode the
# batch's writes are approved ONCE (physical robot motion is never bundled — it
# keeps its own per-call confirm).
_BABS_BATCH_MAX_CALLS = 25
_BABS_BATCH_TOOL = {"type": "function", "function": {
    "name": "splicecraft_batch",
    "description": (
        "Run SEVERAL SpliceCraft endpoints IN ORDER in one step — use this to "
        "carry out a multi-step task efficiently instead of one call per turn. "
        "`calls` is a list of {endpoint, arguments} (same endpoint names and "
        "bodies as splicecraft_call). Writes obey the usual policy; in ask-mode "
        "you approve the whole batch once. Returns one result per call, in order; "
        "if one call fails the rest still run. Prefer this whenever you already "
        f"know the next few endpoints you need (max {_BABS_BATCH_MAX_CALLS} per "
        "batch)."),
    "parameters": {"type": "object", "properties": {
        "calls": {
            "type": "array",
            "description": "ordered list of {endpoint, arguments} objects to run",
            "items": {"type": "object", "properties": {
                "endpoint": {"type": "string",
                             "description": "endpoint name (from splicecraft_list_endpoints)"},
                "arguments": {"type": "object",
                              "description": "the request body for that endpoint"},
            }, "required": ["endpoint"]},
        },
    }, "required": ["calls"]},
}}


# Safety cap: how many model→tool→model round-trips one agentic turn may run
# before we stop and summarise (prevents an endless tool loop). Bumped from 12
# to 24 so longer autonomous tasks complete — the batch tool does more per turn,
# but a big multi-step job (discover → describe → several writes → verify) still
# wants headroom.
_BABS_AGENT_MAX_TOOL_ITERS = 24


def _babs_tool_manifest():
    """The Ollama function-tool list Babs hands the model in agentic mode."""
    return _BABS_META_TOOLS + [_BABS_SEARCH_TOOL, _BABS_READ_URL_TOOL,
                               _BABS_BATCH_TOOL]


def _babs_tool_call_name(tc) -> str:
    if not isinstance(tc, dict):
        return "?"
    fn = tc.get("function") or {}
    return str(fn.get("name") or "?")


def _babs_list_endpoints(args) -> dict:
    """Meta-tool: the endpoint catalog (name + write-flag + one-line doc),
    optionally filtered by a keyword."""
    flt = ""
    if isinstance(args, dict):
        flt = str(args.get("filter") or "").strip().lower()
    out = []
    for name, (fn, write) in sorted(_AGENT_HANDLERS.items()):
        if flt and flt not in name.lower():
            continue
        out.append({"name": name, "write": write,
                    "doc": (fn.__doc__ or "").strip().split("\n")[0]})
    return {"endpoints": out, "count": len(out)}


def _babs_describe_endpoint(args) -> dict:
    """Meta-tool: the full docstring (request-body schema, in prose) for one
    endpoint."""
    import inspect
    name = ""
    if isinstance(args, dict):
        name = str(args.get("endpoint") or "").strip()
    entry = _AGENT_HANDLERS.get(name)
    if entry is None:
        return {"error": f"unknown endpoint {name!r}. "
                         f"Call splicecraft_list_endpoints first."}
    fn, write = entry
    return {"name": name, "write": write,
            "method": "POST" if write else "GET",
            "doc_full": inspect.getdoc(fn) or ""}


class BabsToolApprovalModal(ModalScreen[bool]):
    """Ask the user before Babs runs a MUTATING agent endpoint against their
    real data (default autonomy = 'ask'). Default focus is Deny so a stray
    Enter can't fire a write."""

    _blocks_undo: bool = True
    BINDINGS = [Binding("escape", "deny", "Deny")]
    DEFAULT_CSS = """
    BabsToolApprovalModal { align: center middle; }
    #bta-box { width: 72; height: auto; max-height: 80%; padding: 1 2;
        border: solid $warning; background: $surface; }
    #bta-args { height: auto; max-height: 16; margin: 1 0; color: $text-muted; overflow-y: auto; }
    #bta-btns { height: 3; align-horizontal: right; margin-top: 1; }
    #bta-btns Button { margin-left: 1; }
    """

    def __init__(self, endpoint: str, body: "dict | None",
                 *, physical: bool = False) -> None:
        super().__init__()
        self._endpoint = endpoint
        self._body = body if isinstance(body, dict) else {}
        # `physical` marks a real-hardware MOTION command (the OT-2 gantry). These
        # always prompt — even in 'auto' — and get a louder, redder warning.
        self._physical = bool(physical)

    def compose(self) -> ComposeResult:
        with Vertical(id="bta-box"):
            if self._physical:
                yield Static("[b $error]⚠ PHYSICAL ROBOT MOTION[/]  "
                             f"[b]{_esc(self._endpoint)}[/b]", markup=True)
            else:
                yield Static(f"[b $warning]Babs wants to run a write:[/]  "
                             f"[b]{_esc(self._endpoint)}[/b]", markup=True)
            try:
                shown = json.dumps(self._body, indent=2, default=str)[:1500]
            except Exception:
                shown = str(self._body)[:1500]
            yield Static(f"[dim]{_esc(shown)}[/dim]", id="bta-args", markup=True)
            if self._physical:
                yield Static("[b $error]This MOVES the robot.[/] It runs even in "
                             "hands-off ([b]/autonomy auto[/b]) — physical motion "
                             "always asks first. Allow once, or deny.", markup=True)
            else:
                yield Static("[dim]This changes your real data. Allow it once, or "
                             "deny. Switch to hands-off with [b]/autonomy auto[/b].[/dim]",
                             markup=True)
            with Horizontal(id="bta-btns"):
                yield Button("Deny", id="bta-deny")
                yield Button("Allow", id="bta-allow",
                             variant="error" if self._physical else "warning")

    def on_mount(self) -> None:
        self.query_one("#bta-deny", Button).focus()

    @on(Button.Pressed, "#bta-allow")
    def _allow(self, _e: "Button.Pressed") -> None:
        self.dismiss(True)

    @on(Button.Pressed, "#bta-deny")
    def _deny(self, _e: "Button.Pressed") -> None:
        self.dismiss(False)

    def action_deny(self) -> None:
        self.dismiss(False)


class BabsBatchApprovalModal(ModalScreen[bool]):
    """Ask the user ONCE before Babs runs a BATCH of mutating endpoints (the
    `splicecraft_batch` tool, autonomy='ask'). Lists every write so the user sees
    exactly what will change, then approves or denies the whole batch. Default
    focus is Deny so a stray Enter can't fire the writes. Physical robot-motion
    calls are never bundled here — they keep their own per-call confirm."""

    _blocks_undo: bool = True
    BINDINGS = [Binding("escape", "deny", "Deny")]
    DEFAULT_CSS = """
    BabsBatchApprovalModal { align: center middle; }
    #bba-box { width: 80; height: auto; max-height: 80%; padding: 1 2;
        border: solid $warning; background: $surface; }
    #bba-list { height: auto; max-height: 20; margin: 1 0; color: $text-muted; overflow-y: auto; }
    #bba-btns { height: 3; align-horizontal: right; margin-top: 1; }
    #bba-btns Button { margin-left: 1; }
    """

    def __init__(self, writes: "list[tuple[str, dict]]") -> None:
        super().__init__()
        self._writes = list(writes or [])

    def compose(self) -> ComposeResult:
        n = len(self._writes)
        with Vertical(id="bba-box"):
            yield Static(f"[b $warning]Babs wants to run {n} change"
                         f"{'' if n == 1 else 's'} in one batch:[/]", markup=True)
            lines = []
            for i, (ep, body) in enumerate(self._writes[:_BABS_BATCH_MAX_CALLS], 1):
                try:
                    shown = json.dumps(body, default=str)
                except Exception:
                    shown = str(body)
                if len(shown) > 160:
                    shown = shown[:160] + "…"
                lines.append(f"[b]{i}.[/b] {_esc(ep)}  [dim]{_esc(shown)}[/dim]")
            yield Static("\n".join(lines), id="bba-list", markup=True)
            yield Static("[dim]These change your real data (any reads in the batch "
                         "run regardless). Allow the whole batch, or deny. Switch "
                         "to hands-off with [b]/autonomy auto[/b].[/dim]",
                         markup=True)
            with Horizontal(id="bba-btns"):
                yield Button("Deny", id="bba-deny")
                yield Button(f"Allow {n}", id="bba-allow", variant="warning")

    def on_mount(self) -> None:
        self.query_one("#bba-deny", Button).focus()

    @on(Button.Pressed, "#bba-allow")
    def _allow(self, _e: "Button.Pressed") -> None:
        self.dismiss(True)

    @on(Button.Pressed, "#bba-deny")
    def _deny(self, _e: "Button.Pressed") -> None:
        self.dismiss(False)

    def action_deny(self) -> None:
        self.dismiss(False)


class BabsScreen(Screen):
    """The BABS assistant tab. A direct conversation with a local Ollama model
    (no RAG corpus) wearing Babs' chat UX. Hardened: every network call is
    bounded + cancellable, the prompt is length-clamped, the transcript is
    pruned to a sane ceiling, and a missing/oversized/garbled Ollama response
    degrades to a clear message instead of crashing the app."""

    # Hosts Input/TextArea-like widgets → keep app-level Ctrl+Z off the canvas
    # while focused ([INV-41] / [RECIPE] modal-with-input rule, applied to a
    # full Screen the same way SequencingScreen does).
    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "close_or_stop", "Stop / Close", show=True),
        Binding("ctrl+l", "clear_chat", "Clear", show=True),
        Binding("ctrl+e", "export_chat", "Export", show=True),
        Binding("ctrl+r", "retry", "Retry", show=False),
    ]

    # Display / memory ceilings. On-screen bubbles are pruned past _MAX_BUBBLES
    # so the widget count can't grow unbounded; the raw (role, text) transcript
    # kept for export + close→reopen rehydrate is capped at _MAX_TRANSCRIPT
    # (kept ≥ _MAX_BUBBLES so a reopen still restores a full screen of
    # scrollback) — an agentic turn appends a `tool` step per call, so without a
    # cap a long autonomous run would pin arbitrary RAM. Conversational MEMORY
    # is trimmed to fit num_ctx every turn (engine `trim_history`) and
    # additionally capped at _MAX_HISTORY_TURNS pairs so a marathon session
    # can't pin arbitrary RAM.
    _MAX_BUBBLES = 600
    _MAX_TRANSCRIPT = _MAX_BUBBLES * 2
    _MAX_HISTORY_TURNS = 200
    # The auto-created, auto-synced model collection (INV-139): every installed
    # Ollama model not already filed elsewhere lands here, so nothing's invisible.
    _DEFAULT_MODEL_COLL = "My Models"

    DEFAULT_CSS = """
    /* BABS wears the same Header + MenuBar chrome as the main app (added in
       compose) so it reads as part of SpliceCraft, then a full-height
       TabbedContent fills the rest. Panes use `1fr`, NOT `height: 100%` — a
       percentage resolves against the TabPane's default `height: auto`,
       collapses to 0, and blanks the whole tab (no buttons, no table, just a
       black void). `1fr` distributes the real remaining height; the explicit
       `> TabPane` rule pins each pane (mirrors the proven SequencingScreen
       `#seq-tabs > TabPane` pattern). The TabPane padding gives every tab a
       uniform 1-row top + 1-col side inset, so content keeps one char of
       breathing room from the terminal edge on either side. */
    #babs-tabs { width: 100%; height: 1fr; }
    #babs-tabs > TabPane { height: 1fr; padding: 0; }
    /* The 1-col side inset + 1-row top inset live on the content boxes (padding
       here is proven to inset; TabPane padding did not). Keeps content one char
       off the terminal edge on either side. */
    #babs-chat-box, #babs-model-box, #babs-scrape-box {
        width: 100%; height: 1fr; padding: 1 1 0 1;
    }

    /* ── Chat tab ─────────────────────────────────────────────────────── */
    /* Lifebar: each component sizes to its own content and packs left-to-right,
       so the gap between every component is a single consistent separator —
       no fixed fr split leaving a chasm before the jobs status. */
    #babs-bars { height: 1; width: 100%; margin: 0 0 1 0; }
    #babs-ctx-bar { width: 1fr; height: 1; }
    #babs-jobs-bar { width: auto; height: 1; }
    #babs-log {
        width: 100%; height: 1fr; border: solid $primary-darken-2;
        padding: 0 1; background: $surface;
    }
    #babs-log > Static { margin: 0 0 1 0; width: 1fr; }
    .babs-user { color: $text; }
    .babs-asst { color: $text; }
    .babs-sys  { color: $text-muted; }
    .babs-tool { color: $text-muted; margin: 0 0 0 2; }
    /* Input flexes; each button sits one char off the element before it so the
       send/stop pair never crams against the box or each other. */
    #babs-toggle-row { height: 3; width: 100%; margin: 1 0 0 0; }
    #babs-toggle-row Button { width: auto; min-width: 10; margin: 0 1 0 0; }
    #babs-input-row { height: 3; width: 100%; margin: 0; }
    #babs-input { width: 1fr; }
    #babs-input-row Button { width: auto; min-width: 10; margin: 0 0 0 1; }

    /* ── Section headers + control rows (Model / scraper tabs) ─────────── */
    .babs-h { height: 1; margin: 1 0 0 0; color: $text; }
    .babs-row { height: 3; width: 100%; }
    .babs-row Input, .babs-row Select { width: 1fr; }
    .babs-row Button { width: auto; min-width: 10; margin: 0 0 0 1; }

    /* ── Model tab ────────────────────────────────────────────────────── */
    /* Tables get the same round border as the chat log / scraper panes so
       every framed surface in BABS matches the app's panel styling. */
    #babs-coll-select { width: 1fr; }
    #babs-models { height: 10; width: 100%; border: solid $primary-darken-2; }
    #babs-hf { height: 8; width: 100%; border: solid $primary-darken-2; }
    #babs-pull-bar { width: 100%; height: 1; display: none; }
    #babs-pull-status { height: 1; width: 100%; color: $text-muted; margin: 1 0 0 0; }

    /* ── Paper scraper tab ────────────────────────────────────────────── */
    #babs-ingest-indicator { height: 1; width: 100%; content-align: left middle; margin: 0 0 1 0; }
    #babs-scrape-note { height: auto; width: 100%; }
    #babs-jobs { height: 8; width: 100%; border: solid $primary-darken-2; }
    #babs-logtail-scroll { height: 8; width: 100%; border: solid $primary-darken-2; padding: 0 1; }

    /* ── Learn tab (Background Learning) ───────────────────────────────── */
    #babs-learn-note { height: auto; width: 100%; }
    #babs-learn-status { height: auto; width: 100%; margin: 1 0; }
    #babs-learn-results { height: 12; width: 100%; border: solid $primary-darken-2; }
    .babs-narrow { width: 16; }
    """

    def __init__(self) -> None:
        super().__init__()
        # Chat state
        self._history: "list[dict]" = []          # model memory: [{role, content}, ...]
        self._transcript: "list[tuple[str, str]]" = []   # full raw (role, text) for export
        self._model = _babs.DEFAULT_CHAT_MODEL
        self._system = _babs.BABS_SYSTEM
        self._temp = _babs.DEFAULT_TEMP
        self._num_ctx = _babs.DEFAULT_NUM_CTX
        self._show_think = False
        self._generating = False
        self._cancel: "threading.Event | None" = None   # set for the duration of a turn
        self._active_resp = None                    # open Ollama response (for responsive stop)
        self._active_proc = None                    # grounded-mode rag_bot subprocess (for stop)
        self._grounded = False                      # answer from the Babs corpus (rag_bot) vs. plain chat
        # Agentic mode (2026-06-30): the in-process tool-loop + write policy.
        # Hydrated from settings in on_mount; defaults here so the attributes
        # always exist (a worker may read them).
        self._agent_enabled = False                 # Babs may call agent endpoints
        self._autonomy = "ask"                      # write policy: ask | auto | readonly
        self._agent_model = ""                      # model for agent turns; "" = auto (hydrated on_mount)
        self._agent_model_noted = False             # once-per-process "using X for agent turns" note
        self._nudged_agent = False                  # once-per-process "turn on Agent" nudge (plain chat)
        self._approval_modal_open = False
        self._has_mounted_before = False            # persistence: True after first mount
        self._cur_assistant: "Static | None" = None
        self._last_query: "str | None" = None
        # Animated braille "thinking" spinner for a turn in flight — esp. during
        # a hidden <think> phase, where no visible token streams yet so the
        # bubble would otherwise sit dead-still. Timer created paused in
        # on_mount; resumed in _ask, paused in _finalize.
        self._think_timer = None
        self._think_i = 0
        self._got_visible = False     # a visible token has replaced the spinner
        # Model tab — collection-organized model picker (INV-139)
        self._model_refs: "list[str | None]" = []       # row index → model ref
        self._hf_names: "list[str | None]" = []
        self._marked_refs: "set[str]" = set()            # marked rows (bulk move/uninstall)
        self._active_model_coll: str = ""                # active collection name
        self._installed_index: "dict[str, dict]" = {}    # installed model name → live meta
        self._busy_models = False                        # guard re-entrant model mutations
        self._model_tab_loaded = False
        self._pulling = False
        self._pull_cancel: "threading.Event | None" = None
        self._pull_resp = None
        self._pull_meter: "_babs.PullMeter | None" = None
        # Scraper tab
        self._jobs: "list[dict]" = []
        self._jobs_timer = None
        self._indicator_timer = None
        self._spinner_i = 0
        self._indicator_idle_shown = False
        # Learn tab (Background Learning): the topic session whose progress the tab shows.
        self._learn_active_slug: "str | None" = None

    # ── compose ────────────────────────────────────────────────────────────────
    def compose(self) -> ComposeResult:
        yield Header()
        # Carry the SpliceCraft toolbar onto this screen so it stays present
        # across all three BABS tabs — the same Header + MenuBar chrome as the
        # main app, so the assistant reads as part of SpliceCraft rather than a
        # bolted-on screen. Uses the proven _MenuBarScroll-wrapper + plain
        # MenuBar combo (styled by the app-global `#menubar-scroll` rule);
        # `action_open_babs` guards against re-pushing a second BabsScreen when
        # BABS is clicked from here.
        with _MenuBarScroll(id="menubar-scroll"):
            yield MenuBar(id="menubar")
        with TabbedContent(initial="babs-tab-chat", id="babs-tabs"):
            with TabPane("Chat", id="babs-tab-chat"):
                with Vertical(id="babs-chat-box"):
                    with Horizontal(id="babs-bars"):
                        yield Static("", id="babs-ctx-bar", markup=True)
                        yield Static("", id="babs-jobs-bar", markup=True)
                    yield VerticalScroll(id="babs-log")
                    # Corpus + Agent are session TOGGLES, not per-message
                    # actions — keep them OFF the send line so a narrow
                    # terminal doesn't shrink the input to nothing or clip
                    # Send / Stop off-screen (INV-139 family).
                    with Horizontal(id="babs-toggle-row"):
                        # Corpus toggle: ground answers in the Babs corpus (rag_bot)
                        # vs. plain chat. State + enabled-ness set in on_mount /
                        # _refresh_ground_button.
                        yield Button("Corpus", id="babs-ground")
                        yield Button("Agent: off", id="babs-agent")
                    with Horizontal(id="babs-input-row"):
                        yield Input(placeholder="Ask Babs ❯   (/help · Enter to send)",
                                    id="babs-input")
                        yield Button("Send", id="babs-send", variant="primary")
                        yield Button("Stop", id="babs-stop")
            with TabPane("Model", id="babs-tab-model"):
                with VerticalScroll(id="babs-model-box"):
                    # ── collection bar (mirrors the plasmid LibraryPanel) ──
                    with Horizontal(classes="babs-row"):
                        yield Select([], prompt="Collection", id="babs-coll-select",
                                     allow_blank=True)
                        yield Button("New", id="babs-coll-new")
                        yield Button("Rename", id="babs-coll-rename")
                        yield Button("Delete", id="babs-coll-del", variant="error")
                    yield Static("[b]Models[/b] [dim]· Space mark · m move · Del uninstall "
                                 "· u use[/dim]", classes="babs-h", markup=True)
                    yield _BabsModelTable(id="babs-models", cursor_type="row")
                    with Horizontal(classes="babs-row"):
                        yield Button("Use", id="babs-use", variant="success")
                        yield Button("Pull", id="babs-model-pull", variant="primary")
                        yield Button("Move marked", id="babs-move")
                        yield Button("Uninstall marked", id="babs-del", variant="error")
                        yield Button("Refresh", id="babs-refresh")
                    yield Static("", id="babs-pull-status", markup=True)
                    yield ProgressBar(total=100, show_eta=False, id="babs-pull-bar")
                    # ── file a model ref into the active collection ──
                    yield Static("[b]Add a model[/b] [dim]· file a ref into this "
                                 "collection (pull later)[/dim]",
                                 classes="babs-h", markup=True)
                    with Horizontal(classes="babs-row"):
                        yield Input(placeholder="model ref — e.g. llama3.2:3b or hf.co/<repo>",
                                    id="babs-addname")
                        yield Button("Add", id="babs-add", variant="primary")
                    yield Static("[b]Search HuggingFace[/b] [dim]· GGUF models · "
                                 "runs via hf.co/<repo>[/dim]",
                                 classes="babs-h", markup=True)
                    with Horizontal(classes="babs-row"):
                        yield Input(placeholder="search HuggingFace GGUF models…",
                                    id="babs-hfquery")
                        yield Button("Search", id="babs-hfsearch", variant="primary")
                    yield DataTable(id="babs-hf", cursor_type="row")
                    with Horizontal(classes="babs-row"):
                        yield Button("Add selected to collection", id="babs-hf-add",
                                     variant="primary")
            with TabPane("Paper scraper", id="babs-tab-scrape"):
                with VerticalScroll(id="babs-scrape-box"):
                    yield Static("", id="babs-ingest-indicator", markup=True)
                    yield Static("", id="babs-scrape-note", markup=True)
                    with Horizontal(classes="babs-row"):
                        yield Input(placeholder="topic — e.g. rose callus regeneration",
                                    id="babs-scrapeq")
                        yield Button("Launch search", id="babs-scrape-go", variant="primary")
                    yield Static("[b]Background jobs[/b] [dim]· launched this session[/dim]",
                                 classes="babs-h", markup=True)
                    yield DataTable(id="babs-jobs", cursor_type="row")
                    with Horizontal(classes="babs-row"):
                        yield Button("Kill selected", id="babs-kill")
                        yield Button("Refresh", id="babs-jobs-refresh")
                    yield Static("[b]Log[/b] [dim](latest job — tail)[/dim]",
                                 classes="babs-h", markup=True)
                    with VerticalScroll(id="babs-logtail-scroll"):
                        yield Static("", id="babs-logtail", markup=False)
            with TabPane("Learn", id="babs-tab-learn"):
                with VerticalScroll(id="babs-learn-box"):
                    yield Static("", id="babs-learn-note", markup=True)
                    yield Static("[dim]Grow Babs' knowledge about a topic with a focused, "
                                 "drift-resistant crawl of open scientific databases. Each topic "
                                 "gets its own isolated corpus.[/dim]", classes="babs-h", markup=True)
                    with Horizontal(classes="babs-row"):
                        yield Input(placeholder="topic — e.g. T7 expression optimization in E. coli",
                                    id="babs-learnq")
                        yield Input(placeholder="papers (40)", id="babs-learn-docs",
                                    classes="babs-narrow")
                        yield Button("Start learning", id="babs-learn-go", variant="primary")
                    yield Static("", id="babs-learn-status", markup=True)
                    with Horizontal(classes="babs-row"):
                        yield Button("Refresh", id="babs-learn-refresh")
                        yield Button("Show what it learned", id="babs-learn-results-btn")
                        yield Button("Stop", id="babs-learn-stop", variant="error")
                    yield Static("[b]Kept papers[/b] [dim](most on-topic first)[/dim]",
                                 classes="babs-h", markup=True)
                    yield DataTable(id="babs-learn-results", cursor_type="row")
        yield Footer()

    def _rehydrate_transcript(self) -> None:
        """Re-render the persisted transcript into bubbles after a re-mount
        (close → reopen) so the chat scrollback survives the DOM teardown.
        User/assistant turns AND the ⚙ tool steps are restored; only ephemeral
        system notes aren't part of the saved transcript."""
        try:
            self.query_one("#babs-log", VerticalScroll)
        except NoMatches:
            return
        # Only the last _MAX_BUBBLES entries can survive on screen (`_mount_bubble`
        # prunes past that), so mounting the whole capped transcript and then
        # tearing most of it down again is wasted work — restore just the tail.
        for role, text in self._transcript[-self._MAX_BUBBLES:]:
            if role == "you":
                self._mount_bubble(f"[b green]❯[/b green] {_esc(text)}", "babs-user")
            elif role == "tool":
                self._mount_bubble(f"[dim]{_esc(text)}[/dim]", "babs-tool")
            else:
                self._mount_bubble(_babs.md_to_rich(text), "babs-asst")

    def _push_transcript(self, role: str, text: str) -> None:
        """Append a (role, text) turn to the export/rehydrate transcript and
        keep it bounded at `_MAX_TRANSCRIPT`. Unlike `_history` (trimmed to fit
        num_ctx) and the on-screen bubbles (pruned past `_MAX_BUBBLES`), the
        transcript used to grow without limit — an agentic session appends a
        `tool` step per call, so a long autonomous run could pin arbitrary RAM."""
        self._transcript.append((role, text))
        if len(self._transcript) > self._MAX_TRANSCRIPT:
            del self._transcript[: len(self._transcript) - self._MAX_TRANSCRIPT]

    # ── mount / settings ─────────────────────────────────────────────────────────
    def on_mount(self) -> None:
        # Hydrate persisted preferences (empty → engine defaults).
        self._model = (_get_setting("babs_model", "") or "").strip() or _babs.DEFAULT_CHAT_MODEL
        self._system = (_get_setting("babs_system", "") or "").strip() or _babs.BABS_SYSTEM
        try:
            self._temp = float(_get_setting("babs_temp", _babs.DEFAULT_TEMP))
        except (TypeError, ValueError):
            self._temp = _babs.DEFAULT_TEMP
        self._show_think = bool(_get_setting("babs_show_think", False))
        # active model-picker collection (empty → resolved on first load)
        self._active_model_coll = (_get_setting("babs_model_collection", "") or "").strip()
        # Rehydrate the last Background-Learning topic so the Learn tab isn't
        # blank after an app restart — its on-disk corpus + results survive.
        self._learn_active_slug = (
            (_get_setting("babs_learn_slug", "") or "").strip() or None)
        # Persistence (2026-06-30): the Babs instance is reused across close →
        # reopen (see `action_open_babs`), but Textual rebuilds the DOM and
        # cancels the screen's workers on unmount. `resuming` is True on a
        # re-mount; reset the transient turn/pull state so a session interrupted
        # mid-flight reopens clean (input not stuck disabled), then rehydrate the
        # visible transcript below.
        resuming = self._has_mounted_before
        self._generating = False
        self._cancel = None
        self._active_resp = None
        self._active_proc = None
        self._cur_assistant = None
        self._pulling = False
        self._pull_cancel = None
        self._pull_resp = None
        self._approval_modal_open = False
        # Tables
        try:
            self.query_one("#babs-models", _BabsModelTable).add_columns(
                " ", "Model", "Status", "Size", "Params")
            self.query_one("#babs-hf", DataTable).add_columns(
                "HuggingFace repo (GGUF)", "Downloads", "Likes")
            self.query_one("#babs-jobs", DataTable).add_columns(
                "PID", "Kind", "Topic", "Status")
            self.query_one("#babs-learn-results", DataTable).add_columns(
                "Score", "Hop", "Title")
        except NoMatches:
            pass
        if resuming:
            self._rehydrate_transcript()
            self._sys_note("[dim](resumed your Babs session — "
                           f"{len(self._history) // 2} turn(s) in memory)[/dim]")
        else:
            self._sys_note(
                f"[b]Babs ready.[/b] [dim]model[/dim] {_esc(self._model)} "
                f"[dim]· Ask a question, or /help for commands. "
                f"Esc to stop / close.[/dim]")
        self._refresh_scrape_note()
        self._refresh_learn_note()
        self._grounded = False                          # default: plain chat; the Corpus toggle grounds it
        self._refresh_ground_button()
        # Agentic mode: hydrate the persisted tool-loop arm + write policy.
        self._agent_enabled = bool(_get_setting("babs_tools_enabled", False))
        self._autonomy = (_get_setting("babs_autonomy", "ask") or "ask").strip().lower()
        if self._autonomy not in ("ask", "auto", "readonly"):
            self._autonomy = "ask"
        self._agent_model = (_get_setting("babs_agent_model", "") or "").strip()
        self._refresh_agent_button()
        if self._agent_enabled and not resuming:
            self._sys_note(
                f"[dim]Agent mode is [b]on[/b] — Babs can drive SpliceCraft "
                f"(write policy: [b]{self._autonomy}[/b]). Toggle with the "
                f"[b]Agent[/b] button or /autonomy.[/dim]")
        if self._corpus_available() and not resuming:
            self._sys_note("[dim]You have a Babs corpus — turn [b]Corpus[/b] on to ground answers "
                           "in it (with sources).[/dim]")
        self._refresh_bars()
        self._preflight()
        self._refresh_num_ctx()
        # Two cadences: a 2.5 s poll refreshes the (heavier) log tail, and a
        # 0.6 s tick animates the live "ingest running" keep-alive indicator and
        # drives realtime staleguarded job-state updates. Both early-return when
        # no job exists, so they're near-free when idle.
        self._jobs_timer = self.set_interval(2.5, self._poll_jobs, pause=False)
        self._tick_indicator()
        self._indicator_timer = self.set_interval(0.6, self._tick_indicator, pause=False)
        # Fast tick for the chat "thinking" spinner — paused until a turn runs.
        self._think_timer = self.set_interval(0.12, self._tick_thinking, pause=True)
        self._has_mounted_before = True   # subsequent on_mounts are resumes
        try:
            self.query_one("#babs-input", Input).focus()
        except NoMatches:
            pass

    def on_unmount(self) -> None:
        # Never leave a socket read or a download wedged when the tab closes.
        self._stop_generation()
        self._stop_pull()

    @work(thread=True, exclusive=True, group="babs_numctx")
    def _refresh_num_ctx(self) -> None:
        """Size the working context window to the ACTIVE model's REAL window
        (off-thread ``/api/show``), so the ❤ lifebar and chat memory reflect a
        large-context model instead of always assuming 4096. Falls back to the
        default when Ollama is down or the metadata is absent. Clamped to
        ``[DEFAULT_NUM_CTX, MAX_AUTO_NUM_CTX]`` to bound the KV-cache RAM."""
        model = self._model
        try:
            n = _babs.context_length_from_show(_babs.show(model))
        except _babs.BabsError:
            n = None
        if n:
            n = max(_babs.DEFAULT_NUM_CTX, min(int(n), _babs.MAX_AUTO_NUM_CTX))

        def _apply() -> None:
            # Ignore a stale result if the user switched models meanwhile.
            if not self.is_mounted or self._model != model:
                return
            self._num_ctx = n or _babs.DEFAULT_NUM_CTX
            self._refresh_bars()
        self.app.call_from_thread(_apply)

    @work(thread=True, exclusive=True, group="babs_preflight")
    def _preflight(self) -> None:
        """Best-effort readiness check: is Ollama up, and is the active model
        pulled? Warns (never refuses) — the user still gets a usable tab and a
        clear pointer to the Model tab. Runs off-thread so a wedged/absent
        Ollama can't block mount."""
        ollama_up, model_ok, detail = True, True, ""
        try:
            installed = _babs.list_installed()
            model_ok = _babs.model_is_installed(self._model, installed)
        except _babs.OllamaUnavailable as exc:
            ollama_up, detail = False, str(exc)
        except Exception as exc:   # worker-body carve-out ([PIT-01])
            _log.exception("BABS preflight failed")
            ollama_up, detail = False, f"preflight error: {exc}"
        self.app.call_from_thread(self._preflight_done, ollama_up, model_ok, detail)

    def _preflight_done(self, ollama_up: bool, model_ok: bool, detail: str) -> None:
        if not self.is_mounted:
            return
        if not ollama_up:
            self._sys_note(self._setup_checklist(detail))
        elif not model_ok:
            self._sys_note(
                f"[yellow]⚠ model [b]{_esc(self._model)}[/b] isn't pulled yet.[/yellow]\n"
                f"   [dim]Pull it from the [b]Model[/b] tab (or [b]/model <name>[/b]) — or run[/dim] "
                f"[b]ollama pull {_esc(self._model)}[/b]")
        self._refresh_bars()

    def _setup_checklist(self, detail: str) -> str:
        """First-run guidance shown when Ollama isn't reachable — a numbered checklist instead of
        a bare connection error, so a new user knows exactly what to install to make BABS work."""
        return (
            "[yellow]⚠ Can't reach Ollama — the local AI that powers BABS chat.[/yellow]\n"
            f"   [dim]{_esc(detail)}[/dim]\n"
            "[b]First-run setup:[/b]\n"
            "  [b]1.[/b] Install Ollama → [u]https://ollama.com[/u], then start it.\n"
            f"  [b]2.[/b] Pull a model:  [b]ollama pull {_esc(_babs.DEFAULT_CHAT_MODEL)}[/b]\n"
            "  [b]3.[/b] (optional) Grow + query a research corpus:  [b]splicecraft babs-setup[/b]\n"
            "  [dim]Then reopen BABS — the Model tab shows what's installed.[/dim]")

    # ── small UI helpers ─────────────────────────────────────────────────────────
    def _set_static(self, selector: str, markup: str) -> None:
        try:
            self.query_one(selector, Static).update(markup)
        except NoMatches:
            pass

    def _scroll_log(self) -> None:
        try:
            self.query_one("#babs-log", VerticalScroll).scroll_end(animate=False)
        except NoMatches:
            pass

    def _log_pinned(self) -> bool:
        """True if the transcript is scrolled to (within 2 rows of) the bottom —
        so streaming auto-scroll FOLLOWS the answer, but a user who scrolled UP to
        re-read isn't yanked back down on every token."""
        try:
            log = self.query_one("#babs-log", VerticalScroll)
        except NoMatches:
            return True
        return log.scroll_y >= log.max_scroll_y - 2

    def _mount_bubble(self, markup: str, css_class: str) -> "Static | None":
        try:
            log = self.query_one("#babs-log", VerticalScroll)
        except NoMatches:
            return None
        w = Static(markup, markup=True, classes=css_class)
        log.mount(w)
        # Prune oldest so a very long session can't grow widgets without bound.
        kids = list(log.children)
        if len(kids) > self._MAX_BUBBLES:
            for old in kids[: len(kids) - self._MAX_BUBBLES]:
                try:
                    old.remove()
                except Exception:
                    pass
        self.call_after_refresh(self._scroll_log)
        return w

    def _sys_note(self, markup: str) -> None:
        self._mount_bubble(markup, "babs-sys")

    def _refresh_bars(self) -> None:
        self._refresh_ctx_bar()
        self._refresh_jobs_bar()

    def _effective_system(self, ctx: "str | None" = None) -> str:
        """The full system prompt Babs sends THIS turn: persona + persistent
        memory + current-plasmid context + (the agent preamble when Agent mode
        is armed). The live ❤ lifebar reserve and the actual chat call both go
        through here so the bar's 'context left' can't disagree with what
        `trim_history` reserves — it used to reserve the bare persona only, so
        it over-reported whenever a plasmid was open, memory notes existed, or
        Agent mode was on. Pass a precomputed `ctx` to reuse `_plasmid_context()`."""
        base = self._system
        mem = _babs_memory_index()
        if mem:
            base = base + ("\n\n# What you remember (persistent notes about this "
                           "user / project)\n" + mem)
        if ctx is None:
            ctx = self._plasmid_context()
        if ctx:
            base = base + "\n\n# Current SpliceCraft context\n" + ctx
        return base + _BABS_AGENT_PREAMBLE if self._agent_enabled else base

    def _refresh_ctx_bar(self) -> None:
        reserve = _babs.est_tokens(self._effective_system())
        lb = _babs.lifebar(self._history, reserve, self._num_ctx)
        color = _BABS_LEVEL_COLOR[lb["level"]]
        bar = "█" * lb["filled"] + "░" * (lb["width"] - lb["filled"])
        warn = "[dim] · [/dim][red]— /reset[/red]" if lb["level"] == "crit" else ""
        # Elide a long model ref (e.g. an hf.co/… GGUF path) so it can't shove
        # the jobs / "answering… · Esc to stop" indicator off the right edge.
        model_disp = (self._model if len(self._model) <= 28
                      else self._model[:27] + "…")
        self._set_static(
            "#babs-ctx-bar",
            f"[{color}]❤ [{bar}] {lb['pct']}% context left[/{color}]"
            f"[dim] · {lb['turns']} turn(s) · model [/dim]{_esc(model_disp)}"
            f"[dim] · temp {self._temp:g}[/dim]{warn}")

    def _refresh_jobs_bar(self) -> None:
        running = sum(1 for j in self._jobs if j.get("running"))
        # The jobs status is the last component on the lifebar; lead with the
        # same " · " separator the context bar uses internally so the whole row
        # reads as one evenly-spaced line whatever the model name's length.
        sep = "[dim] · [/dim]"
        if self._generating:
            ch = _BABS_SPINNER[self._think_i % len(_BABS_SPINNER)]
            s = f"{sep}[yellow]{ch} answering…[/yellow] [dim]· Esc to stop[/dim]"
        elif running:
            s = (f"{sep}[green]⚙ {running} scraper job(s) running[/green]"
                 f"[dim] · see the Paper scraper tab[/dim]")
        else:
            s = f"{sep}[dim]⚙ no background jobs[/dim]"
        self._set_static("#babs-jobs-bar", s)

    def _set_input_enabled(self, enabled: bool) -> None:
        for sel in ("#babs-input", "#babs-send"):
            try:
                self.query_one(sel).disabled = not enabled
            except NoMatches:
                pass

    # ── chat: send / stream / finalize ───────────────────────────────────────────
    @on(Input.Submitted, "#babs-input")
    def _on_submit(self, event: "Input.Submitted") -> None:
        self._submit_current()

    @on(Button.Pressed, "#babs-send")
    def _on_send(self, _event: "Button.Pressed") -> None:
        self._submit_current()

    def _submit_current(self) -> None:
        try:
            inp = self.query_one("#babs-input", Input)
        except NoMatches:
            return
        raw = inp.value
        if not raw.strip():
            return
        inp.value = ""
        q = raw.strip()
        if q.startswith("/") or q.lower() in ("exit", "quit", "bye", "q"):
            self._handle_command(q)
            return
        if self._generating:
            self.app.notify("Still answering — press Stop (Esc) first.",
                            severity="information")
            return
        self._ask(q)

    def _plasmid_context(self) -> str:
        """A compact one-block summary of the plasmid currently open in SpliceCraft,
        injected into the system prompt each turn so Babs is aware of the construct
        on screen without having to call ``status`` first (plain chat was blind to
        it). Empty when nothing is loaded. Best-effort — runs on the UI thread every
        ask, so it must never raise."""
        try:
            rec = getattr(self.app, "_current_record", None)
            if rec is None:
                return ""
            name = PlasmidApp._record_display_name(rec) or getattr(rec, "id", "") or "unnamed"
            length = _seq_len(rec)
            topo = (rec.annotations.get("topology") or "linear")
            feats = [f for f in (getattr(rec, "features", []) or [])
                     if getattr(f, "type", "") != "source"]

            def _qval(v):
                # First non-empty value, handling both the normal list form and a
                # malformed bare string / [None] / [].
                if isinstance(v, (list, tuple)):
                    return next((str(x) for x in v if x), "")
                return str(v) if v else ""
            labels: "list[str]" = []
            for f in feats:
                q = getattr(f, "qualifiers", {}) or {}
                lab = (_qval(q.get("label")) or _qval(q.get("gene"))
                       or _qval(q.get("product")) or str(getattr(f, "type", "") or ""))
                # SANITIZE: a feature label from an untrusted file is injected into
                # the SYSTEM prompt — strip newlines/control chars + cap length so a
                # crafted qualifier can't smuggle instructions or bloat the budget.
                lab = _sanitize_label(lab, max_len=40)
                if lab:
                    labels.append(lab)
                if len(labels) >= 12:
                    break
            dirty = " (unsaved edits)" if getattr(self.app, "_unsaved", False) else ""
            parts = [f'The user currently has a plasmid open in SpliceCraft: "{name}", '
                     f"{length} bp, {topo}, {len(feats)} annotated features{dirty}."]
            if labels:
                tail = "" if len(labels) >= len(feats) else ", …"
                parts.append("Features include: " + ", ".join(labels) + tail + ".")
            parts.append('When the user says "this plasmid" / "the construct" / "it", '
                         "they mean this one. Use the status, get-sequence, or "
                         "list-features endpoints for exact details.")
            return "\n".join(parts)
        except Exception:      # UI-thread best-effort — never break an ask ([PIT-01])
            return ""

    def _ask(self, query: str) -> None:
        # The FULL system prompt for this turn — persona + persistent memory +
        # plasmid context + the agent preamble when armed — rides ahead of the
        # user's query, so reserve for ALL of it when clamping the query. Built
        # once via the shared helper the ❤ lifebar and trim_history also use, so
        # the bar's reserve, the query clamp, and the history trim can't
        # disagree. Omitting the memory block here (the pre-fix bug) let a
        # near-limit query pass the clamp yet overrun once memory was prepended,
        # evicting the persona on a small context window.
        ctx = self._plasmid_context()
        system = self._effective_system(ctx)
        reserve = _babs.est_tokens(system)
        query, truncated = _babs.clamp_prompt(
            query, num_ctx=self._num_ctx, reserve_tokens=reserve)
        if truncated:
            self._sys_note("[yellow](prompt truncated to fit the model context)[/yellow]")
        self._last_query = query
        self._push_transcript("you", query)
        self._mount_bubble(f"[b green]❯[/b green] {_esc(query)}", "babs-user")
        self._think_i = 0
        self._got_visible = False
        self._cur_assistant = self._mount_bubble(
            f"[yellow]{_BABS_SPINNER[0]}[/yellow] [dim]Babs is thinking…[/dim]",
            "babs-asst")
        self._generating = True
        self._cancel = threading.Event()
        self._active_resp = None
        self._set_input_enabled(False)
        if self._think_timer is not None:
            self._think_timer.resume()
        self._refresh_bars()
        if self._grounded:
            # Grounded mode answers from the corpus via rag_bot (single-shot, cited); it manages
            # its own retrieval context, so the plain-chat history/messages below are skipped.
            if self._agent_enabled:
                # Both toggles on: grounded wins (the corpus path is a separate cited-answer
                # subprocess that can't also run the agentic tool loop), so SURFACE that the
                # Agent toggle is paused this turn rather than silently ignoring it (the same
                # mode-conflict footgun the agent-API guard avoids).
                self._sys_note("[dim]Corpus grounding is on — this answer comes from your "
                               "corpus with sources, and agent actions are paused this turn. "
                               "Turn Corpus off to let Babs drive SpliceCraft.[/dim]")
            self._generate_grounded(query)
            return
        # `system` + `reserve` were computed once at the top and reused here —
        # the query clamp above reserved the SAME string, so the ❤ bar's
        # reserve, the clamp, and this history trim all reckon with the
        # identical prompt (no drift). `system` feeds build_messages below.
        if _babs.trim_history(self._history, reserve, self._num_ctx,
                              query_tokens=_babs.est_tokens(query)):
            self._sys_note("[dim](trimmed oldest turns to fit the context window)[/dim]")
        # Hard memory ceiling independent of num_ctx.
        if len(self._history) > self._MAX_HISTORY_TURNS * 2:
            del self._history[: len(self._history) - self._MAX_HISTORY_TURNS * 2]
        messages = _babs.build_messages(system, self._history, query)
        if self._agent_enabled:
            self._generate_agentic(query, messages)
        else:
            # Discoverability: if a plain-chat message reads like a live lookup,
            # point the user at Agent mode ONCE — without it Babs can only answer
            # from the model's weights (or improvise a "do it yourself" reply).
            if not self._nudged_agent and self._looks_like_online_request(query):
                self._nudged_agent = True
                self._sys_note(
                    "[dim]💡 That looks like a live lookup. Turn on [b]Agent[/b] "
                    "(the button above, or /agent) and Babs can search online and "
                    "act in SpliceCraft for you.[/dim]")
            self._generate(query, messages)

    def _register_resp(self, resp) -> None:
        # Called from the worker thread; a bare attribute set is thread-safe enough
        # for the main thread to later read + close() it on cancel.
        self._active_resp = resp

    @work(thread=True, exclusive=True, group="babs_chat")
    def _generate(self, query: str, messages: "list[dict]") -> None:
        cancel = self._cancel
        stripper = _babs.ThinkStripper()
        display_parts: "list[str]" = []
        content_parts: "list[str]" = []
        last = [time.monotonic()]
        total = [0]      # running display length → re-render less often on a huge answer
        err = None

        def flush(force: bool = False) -> None:
            now = time.monotonic()
            # The transcript Static is re-rendered whole each flush; throttle
            # harder once it's large so a multi-KB answer can't churn the UI.
            interval = 0.08 if total[0] < 12000 else 0.3
            if not force and now - last[0] < interval:
                return
            last[0] = now
            self.app.call_from_thread(self._render_assistant, "".join(display_parts))

        try:
            opts = {"temperature": float(self._temp), "num_ctx": int(self._num_ctx)}
            for chunk in _babs.chat_stream(self._model, messages, options=opts,
                                           cancel=cancel, register=self._register_resp):
                if cancel is not None and cancel.is_set():
                    break
                e = chunk.get("error")
                if e:
                    raise _babs.BabsError(str(e))
                if self._show_think and chunk["thinking"]:
                    display_parts.append(chunk["thinking"])
                    total[0] += len(chunk["thinking"])
                    flush()
                content = chunk["content"]
                if content:
                    content_parts.append(content)
                    vis = content if self._show_think else stripper.feed(content)
                    if vis:
                        display_parts.append(vis)
                        total[0] += len(vis)
                        flush()
                if chunk["done"]:
                    break
            if not self._show_think:
                tail = stripper.flush()
                if tail:
                    display_parts.append(tail)
        except _babs.BabsError as exc:
            err = str(exc)
        except Exception as exc:   # worker-body carve-out ([PIT-01])
            _log.exception("BABS chat worker failed")
            err = f"chat error: {exc}"
        display = "".join(display_parts)
        answer = _babs.strip_think("".join(content_parts)).strip()
        stopped = bool(cancel is not None and cancel.is_set())
        self.app.call_from_thread(self._finalize, query, display, answer, err, stopped)

    # ── corpus grounding (answer FROM the Babs corpus via rag_bot) ────────────────
    def _corpus_available(self) -> bool:
        """True if there's a Babs corpus to ground answers in — the repo resolves AND its
        corpus.jsonl is non-empty. Drives the toggle default + its enabled state."""
        home = self._resolve_babs_home()
        if home is None:
            return False
        try:
            corpus = home / "knowledge_base" / "corpus.jsonl"
            return corpus.is_file() and corpus.stat().st_size > 0
        except OSError:
            return False

    def _refresh_ground_button(self) -> None:
        """Label/variant/enabled-ness of the Corpus toggle. Disabled (and forced off) when no
        corpus is available, so it can't promise grounding it can't deliver."""
        try:
            btn = self.query_one("#babs-ground", Button)
        except NoMatches:
            return
        available = self._corpus_available()
        if not available:
            self._grounded = False
        btn.disabled = not available
        btn.label = f"Corpus: {'on' if self._grounded else 'off'}"
        btn.variant = "success" if self._grounded else "default"

    @on(Button.Pressed, "#babs-ground")
    def _on_ground_toggle(self, _event=None) -> None:
        if not self._corpus_available():
            self.app.notify("No Babs corpus found. Grow one in the Paper scraper tab, or run "
                            "`splicecraft babs-setup`.", severity="information")
            return
        self._grounded = not self._grounded
        self._refresh_ground_button()
        self._sys_note("[dim]Grounded — answers now come from your Babs corpus, with sources.[/dim]"
                       if self._grounded else "[dim]Back to plain model chat (no corpus).[/dim]")

    # ── agentic mode (Babs drives SpliceCraft via the agent endpoints) ───────────
    def _refresh_agent_button(self) -> None:
        """Label/variant of the Agent toggle — shows the write policy when armed."""
        try:
            btn = self.query_one("#babs-agent", Button)
        except NoMatches:
            return
        if self._agent_enabled:
            btn.label = f"Agent: {self._autonomy}"
            btn.variant = "warning" if self._autonomy == "auto" else "success"
        else:
            btn.label = "Agent: off"
            btn.variant = "default"

    def _resolve_agent_model(self) -> "tuple[str, str]":
        """Which model runs THIS agent/tool turn, and why. A big local chat model
        is painfully slow in a multi-step tool loop (a 9B took ~9 min for one
        search), so when the user hasn't pinned an agent model and their chat
        model is something heavier, agent turns fall back to the fast, tool-capable
        ``DEFAULT_CHAT_MODEL`` — their chosen model still handles ordinary prose.

        Returns ``(model, why)`` where ``why`` ∈ {"set", "set-missing", "chat",
        "auto"} drives the one-time status note. Called from the WORKER thread
        (it may hit Ollama via ``model_is_installed``), never the UI thread."""
        explicit = (self._agent_model or "").strip()
        if explicit.lower() in ("chat", "same", "off"):
            return self._model, "chat"
        if explicit:
            if explicit == self._model:
                return explicit, "set"
            try:
                if _babs.model_is_installed(explicit):
                    return explicit, "set"
            except _babs.BabsError:
                return explicit, "set"          # Ollama down — trust the user's pick
            return self._model, "set-missing"   # named model not pulled → fall back
        fast = _babs.DEFAULT_CHAT_MODEL
        if self._model != fast:
            try:
                if _babs.model_is_installed(fast):
                    return fast, "auto"
            except _babs.BabsError:
                pass                             # Ollama down → just use the chat model
        return self._model, "chat"

    # Phrases that signal a LIVE / online lookup (vs. something the model can
    # answer from its own weights). Deliberately conservative — this only drives
    # a one-time "turn on Agent" nudge and a "didn't search" hint, never behavior.
    _ONLINE_INTENT = (
        "search the", "search for", "search online", "look up", "look it up",
        "look this up", "on the internet", "on the web", "google", "browse the",
        "http://", "https://", "www.", "pubmed", "recent papers",
        "recent literature", "find papers", "latest paper", "online",
    )

    @classmethod
    def _looks_like_online_request(cls, query: str) -> bool:
        """True iff a message reads like a request for live/online information."""
        q = (query or "").lower()
        return any(marker in q for marker in cls._ONLINE_INTENT)

    @on(Button.Pressed, "#babs-agent")
    def _on_agent_toggle(self, _event=None) -> None:
        self._agent_enabled = not self._agent_enabled
        _set_setting("babs_tools_enabled", self._agent_enabled)
        _settings_flush_sync()
        self._refresh_agent_button()
        if self._agent_enabled:
            self._sys_note(
                f"[b]Agent mode on[/b] [dim]— Babs can now drive SpliceCraft by "
                f"calling its endpoints. Write policy: [b]{self._autonomy}[/b] "
                f"(change with /autonomy ask|auto|readonly). Anything she does "
                f"updates this app live.[/dim]")
        else:
            self._sys_note("[dim]Agent mode off — plain chat.[/dim]")

    @work(thread=True, exclusive=True, group="babs_chat")
    def _generate_grounded(self, query: str) -> None:
        """Answer grounded in the Babs corpus: shell `rag_bot.py --ask … --plain` in the babs
        repo and stream its cited answer into the bubble. Keeps SpliceCraft free of chromadb —
        retrieval + the corpus live in babs; we just shell + stream (the Paper-scraper pattern).
        Stop works by terminating the subprocess (which unblocks the os.read in _stop_generation)."""
        import codecs
        import subprocess
        cancel = self._cancel
        home = self._resolve_babs_home()
        err = None
        parts: "list[str]" = []
        last = [time.monotonic()]
        proc = None

        def flush(force: bool = False) -> None:
            now = time.monotonic()
            if not force and now - last[0] < 0.08:
                return
            last[0] = now
            self.app.call_from_thread(self._render_assistant, "".join(parts))

        try:
            if home is None:
                raise _babs.BabsError("Babs repo not found — run `splicecraft babs-setup` "
                                      "or set $SPLICECRAFT_BABS_HOME.")
            py = self._babs_python(home)
            proc = subprocess.Popen(
                [py, "rag_bot.py", "--ask", query, "--plain"], cwd=str(home),
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT, stdin=subprocess.DEVNULL,
                env=os.environ.copy())
            self._active_proc = proc
            dec = codecs.getincrementaldecoder("utf-8")("replace")
            out = proc.stdout
            if out is None:               # stdout=PIPE always yields a stream; this narrows the type
                raise _babs.BabsError("rag_bot produced no output stream")
            fd = out.fileno()
            while True:
                if cancel is not None and cancel.is_set():
                    break
                chunk = os.read(fd, 4096)      # blocks for output; b"" at EOF (done/terminated)
                if not chunk:
                    break
                parts.append(dec.decode(chunk))
                flush()
        except _babs.BabsError as exc:
            err = str(exc)
        except Exception as exc:               # worker-body carve-out ([PIT-01])
            _log.exception("BABS grounded chat worker failed")
            err = f"corpus query error: {exc}"
        finally:
            if proc is not None:
                try:
                    if proc.stdout is not None:
                        proc.stdout.close()
                except Exception:
                    pass
                try:
                    proc.wait(timeout=2)
                except Exception:
                    try:
                        proc.kill()
                    except Exception:
                        pass
            self._active_proc = None
        flush(force=True)
        display = "".join(parts).strip()
        if not display and not err:
            display = "[dim](no answer — is the corpus populated?)[/dim]"
        stopped = bool(cancel is not None and cancel.is_set())
        self.app.call_from_thread(self._finalize, query, display, display, err, stopped)

    # ── agentic tool-loop worker ─────────────────────────────────────────────────
    @work(thread=True, exclusive=True, group="babs_chat")
    def _generate_agentic(self, query: str, messages: "list[dict]") -> None:
        """Agentic turn: stream chat WITH the SpliceCraft tool manifest; when the
        model emits a tool call, run it in-process (the SAME `_agent_invoke` path
        + live TUI refresh as the external side-door) and feed the result back,
        looping until the model answers in plain text. Writes obey the autonomy
        policy (ask / auto / readonly)."""
        cancel = self._cancel
        msgs = list(messages)
        tools = _babs_tool_manifest()
        opts = {"temperature": float(self._temp), "num_ctx": int(self._num_ctx)}
        # Agent turns may run on a faster model than chat (see _resolve_agent_model).
        model, why = self._resolve_agent_model()
        if why == "set-missing":
            self.app.call_from_thread(
                self._sys_note,
                f"[dim]agent model [b]{_esc(self._agent_model)}[/b] isn't pulled — "
                f"using [b]{_esc(self._model)}[/b] this turn. /agentmodel to "
                f"change.[/dim]")
        elif model != self._model and not self._agent_model_noted:
            self._agent_model_noted = True
            self.app.call_from_thread(
                self._sys_note,
                f"[dim]running agent turns on [b]{_esc(model)}[/b] (faster for tool "
                f"use); your chat model stays [b]{_esc(self._model)}[/b]. "
                f"/agentmodel to change.[/dim]")
        final_answer = ""
        err = None
        any_tool_called = False
        try:
            for _iter in range(_BABS_AGENT_MAX_TOOL_ITERS):
                if cancel is not None and cancel.is_set():
                    break
                stripper = _babs.ThinkStripper()
                content_parts: "list[str]" = []
                display_parts: "list[str]" = []
                tool_calls: "list[dict]" = []
                last = [time.monotonic()]

                def flush(force: bool = False, _dp=display_parts, _last=last) -> None:
                    now = time.monotonic()
                    if not force and now - _last[0] < 0.08:
                        return
                    _last[0] = now
                    self.app.call_from_thread(self._render_assistant, "".join(_dp))

                for chunk in _babs.chat_stream(model, msgs, tools=tools,
                                               options=opts, cancel=cancel,
                                               register=self._register_resp):
                    if cancel is not None and cancel.is_set():
                        break
                    e = chunk.get("error")
                    if e:
                        raise _babs.BabsError(str(e))
                    if self._show_think and chunk["thinking"]:
                        display_parts.append(chunk["thinking"])
                        flush()
                    content = chunk["content"]
                    if content:
                        content_parts.append(content)
                        vis = content if self._show_think else stripper.feed(content)
                        if vis:
                            display_parts.append(vis)
                            flush()
                    if chunk["tool_calls"]:
                        tool_calls.extend(chunk["tool_calls"])
                    if chunk["done"]:
                        break
                if not self._show_think:
                    tail = stripper.flush()
                    if tail:
                        display_parts.append(tail)
                if cancel is not None and cancel.is_set():
                    break
                content_full = _babs.strip_think("".join(content_parts)).strip()
                if not tool_calls:
                    final_answer = content_full
                    self.app.call_from_thread(self._render_assistant,
                                              "".join(display_parts))
                    break
                # The model called tool(s): record its turn (content + tool_calls)
                # so it sees its own decision, render + run each call, feed results
                # back, then loop for the model's next move.
                any_tool_called = True
                msgs.append({"role": "assistant",
                             "content": "".join(content_parts),
                             "tool_calls": tool_calls})
                for tc in tool_calls:
                    if cancel is not None and cancel.is_set():
                        break
                    result = self._run_tool_call(tc)
                    self.app.call_from_thread(self._mount_tool_bubble, tc, result)
                    try:
                        result_text = json.dumps(result, default=str)[:6000]
                    except Exception:
                        result_text = str(result)[:6000]
                    msgs.append({"role": "tool", "content": result_text,
                                 "tool_name": _babs_tool_call_name(tc)})
                self.app.call_from_thread(self._new_assistant_bubble)
            else:
                final_answer = (final_answer
                                or "[reached the tool-call limit for this turn]")
        except _babs.BabsError as exc:
            err = str(exc)
        except Exception as exc:   # worker-body carve-out ([PIT-01])
            _log.exception("BABS agentic worker failed")
            err = f"agent error: {exc}"
        stopped = bool(cancel is not None and cancel.is_set())
        # Intermittency guard: agent mode is on and the message clearly wanted a
        # live lookup, yet the model answered from memory without calling ANY tool
        # (small/weak tool-callers do this). Nudge toward a reliable model — unless
        # we're already on the fast default, where rephrasing is the better lever.
        if (err is None and not stopped and not any_tool_called
                and self._looks_like_online_request(query)):
            if model == _babs.DEFAULT_CHAT_MODEL:
                tip = "try rephrasing, e.g. \"search online for …\""
            else:
                tip = (f"[b]{_esc(model)}[/b] may not tool-call reliably — try "
                       f"[b]/agentmodel {_esc(_babs.DEFAULT_CHAT_MODEL)}[/b]")
            self.app.call_from_thread(
                self._sys_note,
                f"[dim]💡 Babs answered without searching online this turn; "
                f"{tip}.[/dim]")
        display = final_answer or "[dim](no answer)[/dim]"
        self.app.call_from_thread(self._finalize, query, display, final_answer,
                                  err, stopped)

    def _run_tool_call(self, tc: dict) -> dict:
        """Execute ONE model tool call (worker thread). Returns a JSON-able
        result dict to feed back to the model."""
        fn = tc.get("function") or {}
        name = str(fn.get("name") or "")
        raw_args = fn.get("arguments")
        if isinstance(raw_args, str):
            try:
                raw_args = json.loads(raw_args)
            except ValueError:
                raw_args = {}
        args = raw_args if isinstance(raw_args, dict) else {}
        if name == "splicecraft_list_endpoints":
            return _babs_list_endpoints(args)
        if name == "splicecraft_describe_endpoint":
            return _babs_describe_endpoint(args)
        if name == "splicecraft_call":
            endpoint = str(args.get("endpoint") or "").strip()
            body = args.get("arguments")
            if not isinstance(body, dict):
                alt = args.get("body")
                body = alt if isinstance(alt, dict) else {}
            return self._dispatch_agent_endpoint(endpoint, body)
        if name == "splicecraft_search_online":
            src = str(args.get("source") or "").strip().lower()
            endpoint = _BABS_SEARCH_SOURCES.get(src)
            if endpoint is None:
                return {"error": (f"unknown search source {src!r}. Valid: "
                                  f"{', '.join(sorted(_BABS_SEARCH_SOURCES))}.")}
            body = {"query": args.get("query")}
            if args.get("max_hits") is not None:
                body["max_hits"] = args.get("max_hits")
            return self._dispatch_agent_endpoint(endpoint, body)
        if name == "splicecraft_fetch_page":
            url = str(args.get("url") or "").strip()
            if not url:
                return {"error": "missing 'url'"}
            # max_chars passed through as-is (None → handler uses its default).
            return self._dispatch_agent_endpoint(
                "read-url", {"url": url, "max_chars": args.get("max_chars")})
        if name == "splicecraft_batch":
            return self._dispatch_agent_batch(args.get("calls"))
        return {"error": f"unknown tool {name!r}"}

    def _dispatch_agent_endpoint(self, endpoint: str, body: dict,
                                 *, pre_approved: bool = False) -> dict:
        """Run ONE agent endpoint for Babs, applying the autonomy policy (worker
        thread). Reads + approved writes route through `_agent_invoke`, so the
        live TUI refreshes exactly as it would for the external side-door.

        `pre_approved` skips the ask-mode confirm for a NON-physical write whose
        approval was already collected up front (a batch approved as one). A
        PHYSICAL robot-motion write still ALWAYS prompts, pre_approved or not."""
        if not endpoint:
            return {"error": "missing 'endpoint'"}
        handler = _AGENT_HANDLERS.get(endpoint)
        if handler is None:
            return {"error": f"unknown endpoint {endpoint!r}. "
                             f"Call splicecraft_list_endpoints first."}
        write = handler[1]
        if write:
            mode = self._autonomy
            if mode == "readonly":
                return {"error": "refused: read-only mode. Ask the user to enable "
                                 "writes (/autonomy ask|auto) before changing data."}
            # Physical robot MOTION always needs an explicit human OK — even in
            # 'auto' — because the model can self-supply the endpoint's `confirm`
            # flag, so unattended auto-actuation of real hardware would otherwise
            # slip through. Beyond the always-motion set, ot2-run-control is physical
            # only when it RESTARTS motion (resume/play); pause/stop/cancel HALT the
            # gantry (the safe direction), so they stay instant. Everything else
            # follows the autonomy mode.
            physical = endpoint in _BABS_PHYSICAL_MOTION_ENDPOINTS or (
                endpoint == "ot2-run-control"
                and str((body or {}).get("action", "")).strip().lower()
                in ("resume", "play"))
            if ((mode == "ask" and not pre_approved) or physical) and not \
                    self._ask_tool_approval(endpoint, body, physical=physical):
                return {"error": "declined by the user."}
        try:
            payload, status = _agent_invoke(self.app, endpoint, body, source="babs")
        except Exception as exc:
            _log.exception("BABS tool dispatch failed: %s", endpoint)
            return {"error": f"{type(exc).__name__}: {exc}"}
        return {"status": status, "result": payload}

    def _dispatch_agent_batch(self, calls) -> dict:
        """Run a LIST of agent endpoints in order (the `splicecraft_batch` tool),
        each through `_dispatch_agent_endpoint` so the autonomy policy + live TUI
        refresh apply exactly as for a single call. In ask-mode the batch's
        non-physical writes are approved ONCE up front (physical robot motion
        still confirms per call). An unknown endpoint or a failing call is
        reported and the rest still run; pressing Stop aborts the remainder.
        Returns ``{results: [...], count}`` — one entry per call, in order."""
        if not isinstance(calls, list) or not calls:
            return {"error": "missing 'calls' — a non-empty list of "
                             "{endpoint, arguments} objects."}
        if len(calls) > _BABS_BATCH_MAX_CALLS:
            return {"error": f"too many calls ({len(calls)}); the batch limit is "
                             f"{_BABS_BATCH_MAX_CALLS}. Split it into smaller batches."}
        # Resolve each call up front: (endpoint, body, handler|None, write?, physical?).
        plan: "list[tuple]" = []
        for c in calls:
            if not isinstance(c, dict):
                plan.append((None, {}, None, False, False))
                continue
            ep = str(c.get("endpoint") or "").strip()
            body = c.get("arguments")
            if isinstance(body, str):          # small models sometimes stringify args
                try:
                    body = json.loads(body)
                except ValueError:
                    body = {}
            if not isinstance(body, dict):
                alt = c.get("body")
                body = alt if isinstance(alt, dict) else {}
            handler = _AGENT_HANDLERS.get(ep)
            is_write = bool(handler and handler[1])
            is_physical = ep in _BABS_PHYSICAL_MOTION_ENDPOINTS or (
                ep == "ot2-run-control"
                and str((body or {}).get("action", "")).strip().lower()
                in ("resume", "play"))
            plan.append((ep, body, handler, is_write, is_physical))
        # One approval for ALL non-physical writes (ask-mode only). Physical
        # motion is never bundled — it keeps its own per-call confirm below.
        mode = self._autonomy
        batch_writes = [(ep, body) for (ep, body, h, w, phys) in plan
                        if h is not None and w and not phys]
        batch_ok: "bool | None" = None       # None → no batch approval was needed
        if mode == "ask" and batch_writes:
            batch_ok = self._ask_batch_approval(batch_writes)
        results = []
        for (ep, body, handler, is_write, is_physical) in plan:
            if self._cancel is not None and self._cancel.is_set():
                results.append({"endpoint": ep, "error": "stopped."})
                continue
            if handler is None:
                results.append({"endpoint": ep,
                                "error": f"unknown endpoint {ep!r}."})
                continue
            non_phys_write = is_write and not is_physical
            if non_phys_write and mode == "ask" and batch_ok is False:
                results.append({"endpoint": ep,
                                "error": "declined by the user (batch)."})
                continue
            pre = bool(batch_ok) if (non_phys_write and mode == "ask") else False
            res = self._dispatch_agent_endpoint(ep, body, pre_approved=pre)
            results.append({"endpoint": ep, **res})
        return {"results": results, "count": len(results)}

    def _ask_tool_approval(self, endpoint: str, body: dict,
                           *, physical: bool = False) -> bool:
        """Block the worker on a yes/no approval modal (autonomy='ask', or ALWAYS
        for a ``physical`` robot-motion endpoint). Returns False if the user denies
        OR presses Stop while it's up."""
        decision = {"v": False}
        modal_ref: "dict[str, object]" = {"m": None}
        done = threading.Event()

        def _push() -> None:
            self._approval_modal_open = True
            m = BabsToolApprovalModal(endpoint, body, physical=physical)
            modal_ref["m"] = m

            def _cb(approved) -> None:
                decision["v"] = bool(approved)
                self._approval_modal_open = False
                done.set()

            self.app.push_screen(m, _cb)

        try:
            self.app.call_from_thread(_push)
        except Exception:
            return False
        while not done.wait(timeout=0.2):
            if self._cancel is not None and self._cancel.is_set():
                def _dismiss() -> None:
                    m = modal_ref["m"]
                    if m is not None and getattr(m, "is_mounted", False):
                        try:
                            m.dismiss(False)   # type: ignore[attr-defined]
                        except Exception:
                            pass
                try:
                    self.app.call_from_thread(_dismiss)
                except Exception:
                    pass
                return False
        return decision["v"]

    def _ask_batch_approval(self, writes: "list[tuple[str, dict]]") -> bool:
        """Block the worker on ONE approval modal listing every write in a batch
        (autonomy='ask'). Returns False if the user denies OR presses Stop while
        it's up. Physical robot-motion calls are NOT passed here — they confirm
        individually via `_ask_tool_approval`."""
        decision = {"v": False}
        modal_ref: "dict[str, object]" = {"m": None}
        done = threading.Event()

        def _push() -> None:
            self._approval_modal_open = True
            m = BabsBatchApprovalModal(writes)
            modal_ref["m"] = m

            def _cb(approved) -> None:
                decision["v"] = bool(approved)
                self._approval_modal_open = False
                done.set()

            self.app.push_screen(m, _cb)

        try:
            self.app.call_from_thread(_push)
        except Exception:
            return False
        while not done.wait(timeout=0.2):
            if self._cancel is not None and self._cancel.is_set():
                def _dismiss() -> None:
                    m = modal_ref["m"]
                    if m is not None and getattr(m, "is_mounted", False):
                        try:
                            m.dismiss(False)   # type: ignore[attr-defined]
                        except Exception:
                            pass
                try:
                    self.app.call_from_thread(_dismiss)
                except Exception:
                    pass
                return False
        return decision["v"]

    def _new_assistant_bubble(self) -> None:
        """Close the current assistant bubble (mark it a tool-use step if it
        showed no text) and open a fresh spinner bubble for the model's next
        agentic turn. UI thread."""
        if (self._cur_assistant is not None and self._cur_assistant.is_mounted
                and not self._got_visible):
            self._cur_assistant.update("[dim]⚙ using tools…[/dim]")
        self._got_visible = False
        self._think_i = 0
        self._cur_assistant = self._mount_bubble(
            f"[yellow]{_BABS_SPINNER[0]}[/yellow] [dim]Babs is thinking…[/dim]",
            "babs-asst")

    def _mount_tool_bubble(self, tc: dict, result: dict) -> None:
        """Render a Babs tool call + its outcome as a distinct bubble. UI thread."""
        name = _babs_tool_call_name(tc)
        fn = tc.get("function") or {}
        args = fn.get("arguments")
        if isinstance(args, str):
            try:
                args = json.loads(args)
            except ValueError:
                args = {}
        label = name
        if name == "splicecraft_call" and isinstance(args, dict):
            label = f"call {args.get('endpoint', '?')}"
        elif name == "splicecraft_describe_endpoint" and isinstance(args, dict):
            label = f"describe {args.get('endpoint', '?')}"
        elif name == "splicecraft_search_online" and isinstance(args, dict):
            label = f"search {args.get('source', '?')}"
        elif name == "splicecraft_fetch_page" and isinstance(args, dict):
            label = f"fetch {args.get('url', '?')}"
        elif name == "splicecraft_batch" and isinstance(args, dict):
            label = f"batch ×{len(args.get('calls') or [])}"

        def _failed(r) -> bool:
            return bool(isinstance(r, dict)
                        and (r.get("error")
                             or (isinstance(r.get("status"), int)
                                 and r["status"] >= 400)))
        sub = result.get("results") if isinstance(result, dict) else None
        subs = sub if isinstance(sub, list) else []
        ok = not (_failed(result) or any(_failed(r) for r in subs))
        icon = "[green]✓[/green]" if ok else "[red]✗[/red]"
        summary = self._summarize_tool_result(result)
        self._mount_bubble(
            f"{icon} [b]⚙ {_esc(label)}[/b]  [dim]{_esc(summary)}[/dim]",
            "babs-tool")
        # Record the tool step in the export/rehydrate transcript (display-only —
        # NOT appended to self._history, so it never re-enters the model's
        # memory). An agent-mode session that ran tool calls now exports/reopens
        # WITH its steps instead of reading as plain chat.
        self._push_transcript(
            "tool", f"⚙ {label} — {'ok' if ok else 'FAILED'}: {summary}")

    @staticmethod
    def _summarize_tool_result(result) -> str:
        """One-line outcome for a tool bubble."""
        if not isinstance(result, dict):
            return str(result)[:160]
        if result.get("error"):
            return f"error: {result['error']}"[:200]
        if isinstance(result.get("results"), list):      # splicecraft_batch
            rs = result["results"]
            fails = sum(1 for r in rs if isinstance(r, dict)
                        and (r.get("error")
                             or (isinstance(r.get("status"), int)
                                 and r["status"] >= 400)))
            return (f"{len(rs)} call(s)" if not fails
                    else f"{len(rs)} call(s) · {fails} failed")
        status = result.get("status")
        payload = result.get("result")
        if isinstance(payload, dict):
            for k in ("count", "name", "id", "saved", "ok"):
                if k in payload:
                    return f"{status or 200} · {k}={payload[k]}"
            return f"{status or 200} · ok"
        if "count" in result:                       # list/describe meta-tools
            return f"{result['count']} item(s)"
        return f"{status or 200} · ok"

    def _tick_thinking(self) -> None:
        """Animate the braille 'thinking' spinner (~0.12 s) while a turn is in
        flight. Spins the assistant placeholder bubble until the first visible
        token replaces it, and keeps the jobs-bar 'answering' indicator turning
        for the whole generation — so a long hidden <think> phase reads as live
        work, not a frozen screen."""
        if not self._generating:
            return
        self._think_i = (self._think_i + 1) % len(_BABS_SPINNER)
        self._refresh_jobs_bar()
        if (not self._got_visible and self._cur_assistant is not None
                and self._cur_assistant.is_mounted):
            ch = _BABS_SPINNER[self._think_i]
            self._cur_assistant.update(
                f"[yellow]{ch}[/yellow] [dim]Babs is thinking…[/dim]")

    def _render_assistant(self, raw: str) -> None:
        if self._cur_assistant is None or not self._cur_assistant.is_mounted:
            return
        if raw:
            self._got_visible = True       # a real token streamed → stop spinning
        pinned = self._log_pinned()        # capture BEFORE the update grows the content
        self._cur_assistant.update(_babs.md_to_rich(raw) or " ")
        if pinned:
            self.call_after_refresh(self._scroll_log)

    def _finalize(self, query: str, display: str, answer: str,
                  err: "str | None", stopped: bool) -> None:
        self._generating = False
        if self._think_timer is not None:
            self._think_timer.pause()
        self._cancel = None
        self._active_resp = None
        self._set_input_enabled(True)
        if self._cur_assistant is not None and self._cur_assistant.is_mounted:
            pinned = self._log_pinned()
            self._cur_assistant.update(_babs.md_to_rich(display) or "[dim](no output)[/dim]")
            if pinned:
                self.call_after_refresh(self._scroll_log)
        if err:
            self._sys_note(f"[red]{_esc(err)}[/red]")
        elif stopped:
            self._sys_note("[dim]…stopped.[/dim]")
        # Record the turn ONLY on a clean completion (mirrors Babs: an
        # interrupted/errored turn is not committed to memory).
        if answer and not stopped and not err:
            self._history.append({"role": "user", "content": query})
            self._history.append({"role": "assistant", "content": answer})
            self._push_transcript("babs", answer)
        self._cur_assistant = None
        self._refresh_bars()
        try:
            self.query_one("#babs-input", Input).focus()
        except NoMatches:
            pass

    @on(Button.Pressed, "#babs-stop")
    def _on_stop(self, _event: "Button.Pressed") -> None:
        if self._generating:
            self._stop_generation()
        else:
            self.app.notify("Nothing is generating.", severity="information")

    def _stop_generation(self) -> None:
        c = self._cancel
        if c is not None:
            try:
                c.set()
            except Exception:
                pass
        r = self._active_resp
        if r is not None:
            try:
                r.close()   # unblock a socket read mid-stream
            except Exception:
                pass
        p = self._active_proc
        if p is not None:
            try:
                p.terminate()   # grounded mode: closes the pipe, unblocking the worker's os.read
            except Exception:
                pass

    # ── slash commands ───────────────────────────────────────────────────────────
    def _handle_command(self, raw: str) -> None:
        cmd, rest = _babs.parse_command(raw)
        if cmd in ("exit", "close"):
            self.dismiss()
        elif cmd in ("help", "?", "h"):
            lines = "\n".join(f"  [cyan]{_esc(c)}[/cyan]  [dim]{_esc(d)}[/dim]"
                              for c, d in _babs.HELP_COMMANDS)
            self._sys_note(f"[b]Commands[/b]\n{lines}")
        elif cmd in ("models", "model"):
            if cmd == "model" and rest:
                self._switch_model(rest.strip())
            elif cmd == "model":
                self._sys_note(f"[dim]active model:[/dim] {_esc(self._model)}")
            else:
                self._open_model_tab()
        elif cmd in ("system", "persona"):
            if rest:
                self._system = rest.strip()
                _set_setting("babs_system", self._system)
                _settings_flush_sync()
                self._sys_note("[dim]system prompt updated.[/dim]")
                self._refresh_bars()
            else:
                self._sys_note(f"[dim]system prompt:[/dim]\n{_esc(self._system)}")
        elif cmd in ("remember", "mem"):
            if not rest.strip():
                self._sys_note("[dim]usage: /remember <a fact Babs should keep across sessions>[/dim]")
            else:
                slug = _babs_remember(rest.strip())
                if slug:
                    self._sys_note(f"[dim]remembered [b]{_esc(slug)}[/b] — Babs will recall this in "
                                   "future sessions.[/dim]")
                else:
                    self._sys_note("[yellow]Couldn't save that memory.[/yellow] [dim](No Babs repo? "
                                   "Clone github.com/ATinyGreenCell/babs to ~/babs or set "
                                   "$SPLICECRAFT_BABS_HOME.)[/dim]")
        elif cmd in ("memory", "memories"):
            idx = _babs_memory_index()
            self._sys_note(f"[b]Babs memory[/b]\n{_esc(idx)}" if idx
                           else "[dim]No memories yet — use [b]/remember <fact>[/b] to save one.[/dim]")
        elif cmd in ("temp", "temperature"):
            if rest:
                try:
                    t = max(0.0, min(2.0, float(rest.strip())))
                except ValueError:
                    self._sys_note("[yellow]usage: /temp <0-2>[/yellow]")
                    return
                self._temp = t
                _set_setting("babs_temp", t)
                _settings_flush_sync()
                self._sys_note(f"[dim]temperature = {t:g}[/dim]")
                self._refresh_bars()
            else:
                self._sys_note(f"[dim]temperature = {self._temp:g}[/dim]")
        elif cmd in ("think",):
            self._show_think = _babs.toggle_value(rest, self._show_think)
            _set_setting("babs_show_think", self._show_think)
            _settings_flush_sync()
            self._sys_note(f"[dim]show reasoning = {'ON' if self._show_think else 'off'}[/dim]")
        elif cmd in ("context", "ctx"):
            reserve = _babs.est_tokens(self._effective_system())
            lb = _babs.lifebar(self._history, reserve, self._num_ctx)
            self._sys_note(f"[dim]context: {lb['pct']}% left · {lb['turns']} turn(s) in memory[/dim]")
        elif cmd == "retry":
            if self._generating:
                self.app.notify("Still answering.", severity="information")
            elif self._last_query:
                # Drop the last committed turn so the retry replaces it.
                if len(self._history) >= 2:
                    del self._history[-2:]
                self._ask(self._last_query)
            else:
                self._sys_note("[dim](nothing to retry yet)[/dim]")
        elif cmd in ("reset", "forget"):
            self._history.clear()
            self._sys_note("[dim]context window reset — memory cleared.[/dim]")
            self._refresh_bars()
        elif cmd in ("clear", "cls"):
            try:
                self.query_one("#babs-log", VerticalScroll).remove_children()
            except NoMatches:
                pass
            self._sys_note("[dim](screen cleared — memory kept)[/dim]")
        elif cmd in ("agent", "tools"):
            self._on_agent_toggle()
        elif cmd in ("autonomy", "policy"):
            mode = rest.strip().lower()
            if mode == "off":
                self._agent_enabled = False
                _set_setting("babs_tools_enabled", False)
                _settings_flush_sync()
                self._refresh_agent_button()
                self._sys_note("[dim]Agent mode off.[/dim]")
            elif mode in ("ask", "auto", "readonly"):
                self._autonomy = mode
                self._agent_enabled = True
                _set_setting("babs_autonomy", mode)
                _set_setting("babs_tools_enabled", True)
                _settings_flush_sync()
                self._refresh_agent_button()
                note = {"ask": "Babs confirms each write",
                        "auto": "FULL AUTONOMY — writes run with no prompt",
                        "readonly": "reads only — writes refused"}[mode]
                self._sys_note(f"[dim]Autonomy: [b]{mode}[/b] — {note}.[/dim]")
            else:
                cur = self._autonomy if self._agent_enabled else "off"
                self._sys_note(f"[dim]autonomy = {cur} · usage: "
                               f"/autonomy off|ask|auto|readonly[/dim]")
        elif cmd in ("agentmodel", "agent-model", "toolmodel"):
            arg = rest.strip()
            self._agent_model_noted = False        # re-announce the model next turn
            if not arg:
                eff = self._agent_model or "auto (a fast tool-capable model)"
                self._sys_note(f"[dim]agent-turn model: [b]{_esc(eff)}[/b] · usage: "
                               f"/agentmodel auto|chat|<model-name>[/dim]")
            elif arg.lower() == "auto":
                self._agent_model = ""
                _set_setting("babs_agent_model", "")
                _settings_flush_sync()
                self._sys_note("[dim]agent model: [b]auto[/b] — a fast tool-capable "
                               "model runs agent turns when your chat model is "
                               "heavier.[/dim]")
            elif arg.lower() in ("chat", "same", "off"):
                self._agent_model = "chat"
                _set_setting("babs_agent_model", "chat")
                _settings_flush_sync()
                self._sys_note("[dim]agent model: [b]chat[/b] — agent turns use "
                               "whatever model chat uses.[/dim]")
            else:
                self._agent_model = arg
                _set_setting("babs_agent_model", arg)
                _settings_flush_sync()
                self._sys_note(f"[dim]agent model → [b]{_esc(arg)}[/b] — used for "
                               f"agent/tool turns (falls back to your chat model "
                               f"if it isn't pulled).[/dim]")
        else:
            self._sys_note(f"[dim]unknown command '/{_esc(cmd)}' — try /help[/dim]")

    def action_close_or_stop(self) -> None:
        if self._pulling:
            self._stop_pull()
            self.app.notify("Download cancelled.", severity="information")
            return
        if self._generating:
            self._stop_generation()
            return
        self.dismiss()

    def action_clear_chat(self) -> None:
        self._handle_command("/clear")

    def action_retry(self) -> None:
        self._handle_command("/retry")

    # ── export ───────────────────────────────────────────────────────────────────
    def action_export_chat(self) -> None:
        if not self._transcript:
            self.app.notify("Nothing to export yet.", severity="information")
            return
        import pathlib
        ts = time.strftime("%Y%m%d-%H%M%S")
        # Write to a predictable, writable location (~/Downloads if present, else
        # home) rather than the process cwd — a pipx / `splicecraft` launch can
        # have an arbitrary or read-only cwd, so the export used to land somewhere
        # surprising or fail outright.
        _home = pathlib.Path.home()
        _dest_dir = _home / "Downloads"
        try:
            if not _dest_dir.is_dir():
                _dest_dir = _home
        except OSError:
            _dest_dir = _home
        path = _dest_dir / f"babs-chat-{ts}.md"
        lines = [f"# Babs chat — {ts}", "",
                 f"_model: {self._model} · temp {self._temp:g}_", ""]
        for role, text in self._transcript:
            if role == "tool":
                lines.append(f"> {text}\n")   # agentic tool step, quoted inline
                continue
            who = "You" if role == "you" else "Babs"
            lines.append(f"**{who}:**\n\n{text}\n")
        try:
            path.write_text("\n".join(lines), encoding="utf-8")
        except OSError as exc:
            _log.exception("BABS export failed")
            self.app.notify(f"Export failed: {exc}", severity="error")
            return
        self.app.notify(f"Exported chat → {path}", severity="information", timeout=8)
        self._sys_note(f"[green]exported →[/green] {_esc(str(path))}")

    # ── model tab ────────────────────────────────────────────────────────────────
    def _open_model_tab(self) -> None:
        try:
            self.query_one("#babs-tabs", TabbedContent).active = "babs-tab-model"
        except NoMatches:
            pass

    @on(TabbedContent.TabActivated, "#babs-tabs")
    def _on_tab(self, _event: "TabbedContent.TabActivated") -> None:
        # Read the active PANE id straight off the container — version-stable,
        # unlike the Tab widget's prefixed id.
        try:
            active = self.query_one("#babs-tabs", TabbedContent).active
        except NoMatches:
            return
        # Staleguard: a scrape / learn job may have started or finished while a
        # different tab was showing, so re-poll jobs + refresh the shared
        # ❤ context / ⚙ jobs bars on EVERY tab switch (both cheap).
        self._poll_jobs()
        self._refresh_bars()
        if active == "babs-tab-model" and not self._model_tab_loaded:
            self._model_tab_loaded = True
            self._load_models()
        elif active == "babs-tab-scrape":
            self._refresh_scrape_note()
            self._refresh_jobs_table()
        elif active == "babs-tab-learn":
            # Reflect a Settings online-lookups toggle / a freshly-cloned babs
            # repo without re-opening the whole screen.
            self._refresh_learn_note()
            self._refresh_learn_status()

    @on(Button.Pressed, "#babs-refresh")
    def _on_refresh_models(self, _e: "Button.Pressed") -> None:
        self._load_models()

    # ── load + display the active collection's models ─────────────────────────
    def _ensure_default_model_collection(self, installed_names: "list[str]") -> "list[dict]":
        """Worker-thread: ensure a default 'My Models' collection exists, and
        file any installed model not in ANY collection into it — so nothing
        installed is invisible (mirrors 'the library holds all plasmids').
        Saves through the chokepoint. Returns the collections list. Staleguard:
        with Ollama down, ``installed_names`` is empty → an empty default is
        still created so the picker works."""
        with _cache_lock:
            colls = _load_model_collections()
            changed = False
            if not colls:
                colls = [{"name": self._DEFAULT_MODEL_COLL,
                          "description": "Installed models", "models": [],
                          "saved": _date.today().isoformat()}]
                changed = True
            filed = {m.get("ref") for c in colls if isinstance(c, dict)
                     for m in (c.get("models") or []) if isinstance(m, dict)}
            default = next((c for c in colls if isinstance(c, dict)
                            and c.get("name") == self._DEFAULT_MODEL_COLL), colls[0])
            default.setdefault("models", [])
            for nm in installed_names:
                if nm and nm not in filed:
                    default["models"].append(
                        {"ref": nm, "note": "", "added": _date.today().isoformat()})
                    filed.add(nm)
                    changed = True
            if changed:
                _save_model_collections(colls)
            return colls

    @work(thread=True, exclusive=True, group="babs_models")
    def _load_models(self) -> None:
        installed: "dict[str, dict]" = {}
        err = None
        try:
            for m in _babs.list_installed():
                installed[m["name"]] = m
        except _babs.OllamaUnavailable as exc:
            err = str(exc)          # Ollama down → still show filed refs, no live status
        except Exception as exc:
            _log.exception("BABS installed-list failed")
            err = f"error: {exc}"
        try:
            colls = self._ensure_default_model_collection(list(installed.keys()))
        except Exception as exc:
            _log.exception("BABS model-collection load failed")
            self.app.call_from_thread(self._models_error, f"collections error: {exc}")
            return
        self.app.call_from_thread(self._fill_models, colls, installed, err)

    def _models_error(self, msg: str) -> None:
        if not self.is_mounted:
            return
        self._set_static("#babs-pull-status", f"[red]{_esc(msg[:120])}[/red]")

    def _fill_models(self, colls: "list[dict]", installed: "dict[str, dict]",
                     err: "str | None") -> None:
        if not self.is_mounted:
            return
        self._installed_index = installed or {}
        names = [str(c.get("name")) for c in colls
                 if isinstance(c, dict) and c.get("name")]
        if self._active_model_coll not in names:
            self._active_model_coll = names[0] if names else ""
            if self._active_model_coll:
                _set_setting("babs_model_collection", self._active_model_coll)
                _settings_flush_sync()
        self._refresh_coll_select(names)
        self._repopulate_models(colls)
        if err:
            self._set_static(
                "#babs-pull-status",
                f"[yellow]Ollama: {_esc(err[:70])} — showing filed refs[/yellow]")

    def _refresh_coll_select(self, names: "list[str]") -> None:
        try:
            sel = self.query_one("#babs-coll-select", Select)
        except NoMatches:
            return
        sel.set_options([(n, n) for n in names])
        if self._active_model_coll in names:
            try:
                sel.value = self._active_model_coll
            except Exception:
                pass

    def _repopulate_models(self, colls: "list[dict] | None" = None) -> None:
        if colls is None:
            colls = _iter_model_collections_readonly()
        installed = self._installed_index
        try:
            t = self.query_one("#babs-models", _BabsModelTable)
        except NoMatches:
            return
        t.clear()
        self._model_refs = []
        coll = next((c for c in colls if isinstance(c, dict)
                     and c.get("name") == self._active_model_coll), None)
        models = (coll.get("models") if coll else None) or []
        cur = {(m.get("ref") or "") for m in models if isinstance(m, dict)}
        self._marked_refs &= cur          # drop marks for refs no longer present
        for m in models:
            if not isinstance(m, dict):
                continue
            ref = (m.get("ref") or "").strip()
            if not ref:
                continue
            meta = installed.get(ref) or installed.get(ref + ":latest")
            if ref in self._marked_refs:
                dot = _RText("▶", style="bold magenta")
            elif meta:
                dot = _RText("●", style="green")
            else:
                dot = _RText("·", style="dim")
            if meta:
                status = _RText("installed", style="green")
                size = _babs.fmt_size(meta.get("size") or 0)
                params = meta.get("params") or "—"
            else:
                status = _RText("not pulled", style="yellow")
                size, params = "—", "—"
            t.add_row(dot, ref, status, size, params)
            self._model_refs.append(ref)
        if not self._model_refs:
            t.add_row(_RText("(empty — add a model below)", style="dim"), "", "", "", "")
            self._model_refs.append(None)

    def _repopulate_after_change(self) -> None:
        """Refresh Select + table from the cache (no Ollama round-trip)."""
        colls = _iter_model_collections_readonly()
        names = [str(c.get("name")) for c in colls if isinstance(c, dict) and c.get("name")]
        self._refresh_coll_select(names)
        self._repopulate_models(colls)

    # ── collection bar: switch / new / rename / delete ────────────────────────
    @on(Select.Changed, "#babs-coll-select")
    def _on_coll_select(self, ev: "Select.Changed") -> None:
        val = ev.value
        if val is None or val is Select.BLANK:
            return
        val = str(val)
        if val == self._active_model_coll:
            return
        self._active_model_coll = val
        _set_setting("babs_model_collection", val)
        _settings_flush_sync()
        self._marked_refs.clear()
        self._repopulate_models()

    @on(Button.Pressed, "#babs-coll-new")
    def _on_coll_new(self, _e: "Button.Pressed") -> None:
        self.app.push_screen(CollectionNameModal("New model collection"),
                             self._on_coll_new_name)

    def _on_coll_new_name(self, name: "str | None") -> None:
        name = _sanitize_label(name)        # strip control chars + cap length
        if not name:
            return
        if _model_collection_name_taken(name):
            self.app.notify(f"A collection named “{name}” already exists.",
                            severity="warning")
            return
        with _cache_lock:
            colls = _load_model_collections()
            colls.append({"name": name, "description": "", "models": [],
                          "saved": _date.today().isoformat()})
            _save_model_collections(colls)
        self._active_model_coll = name
        _set_setting("babs_model_collection", name)
        _settings_flush_sync()
        self._marked_refs.clear()
        self._repopulate_after_change()

    @on(Button.Pressed, "#babs-coll-rename")
    def _on_coll_rename(self, _e: "Button.Pressed") -> None:
        if not self._active_model_coll:
            self.app.notify("No collection to rename.", severity="information")
            return
        self.app.push_screen(
            CollectionNameModal("Rename model collection", self._active_model_coll),
            self._on_coll_renamed)

    def _on_coll_renamed(self, name: "str | None") -> None:
        name = _sanitize_label(name)        # strip control chars + cap length
        old = self._active_model_coll
        if not name or name == old:
            return
        if _model_collection_name_taken(name):
            self.app.notify(f"A collection named “{name}” already exists.",
                            severity="warning")
            return
        with _cache_lock:
            colls = _load_model_collections()
            for c in colls:
                if isinstance(c, dict) and c.get("name") == old:
                    c["name"] = name
                    break
            _save_model_collections(colls)
        self._active_model_coll = name
        _set_setting("babs_model_collection", name)
        _settings_flush_sync()
        self._repopulate_after_change()

    @on(Button.Pressed, "#babs-coll-del")
    def _on_coll_del(self, _e: "Button.Pressed") -> None:
        if not self._active_model_coll:
            self.app.notify("No collection to delete.", severity="information")
            return
        coll = _find_model_collection(self._active_model_coll)
        n = len((coll or {}).get("models") or [])
        self.app.push_screen(
            BabsModelCollectionDeleteModal(self._active_model_coll, n),
            self._on_coll_del_confirm)

    def _on_coll_del_confirm(self, ok: "bool | None") -> None:
        if not ok:
            return
        old = self._active_model_coll
        with _cache_lock:
            colls = [c for c in _load_model_collections()
                     if not (isinstance(c, dict) and c.get("name") == old)]
            _save_model_collections(colls)
        names = [str(c.get("name")) for c in colls if isinstance(c, dict) and c.get("name")]
        self._active_model_coll = names[0] if names else ""
        _set_setting("babs_model_collection", self._active_model_coll)
        _settings_flush_sync()
        self._marked_refs.clear()
        self._repopulate_after_change()

    # ── marking + bulk move / uninstall (mirrors LibraryPanel) ────────────────
    @on(_BabsModelTableEvent)
    def _on_model_table_event(self, ev: "_BabsModelTableEvent") -> None:
        {"mark": self._toggle_mark, "move": self._move_marked,
         "uninstall": self._uninstall_marked, "clear_marks": self._clear_marks,
         "pull": self._pull_selected, "use": self._use_selected,
         }.get(ev.action, lambda: None)()

    def _cursor_ref(self) -> "str | None":
        try:
            t = self.query_one("#babs-models", _BabsModelTable)
        except NoMatches:
            return None
        i = t.cursor_row
        if 0 <= i < len(self._model_refs):
            return self._model_refs[i]
        return None

    def _target_refs(self) -> "list[str]":
        """Marked refs (in table order) if any, else the cursor row's ref."""
        if self._marked_refs:
            return [r for r in self._model_refs if r and r in self._marked_refs]
        ref = self._cursor_ref()
        return [ref] if ref else []

    def _toggle_mark(self) -> None:
        ref = self._cursor_ref()
        if not ref:
            return
        self._marked_refs.discard(ref) if ref in self._marked_refs \
            else self._marked_refs.add(ref)
        self._repopulate_models()

    def _clear_marks(self) -> None:
        if self._marked_refs:
            self._marked_refs.clear()
            self._repopulate_models()

    @on(Button.Pressed, "#babs-move")
    def _on_move_btn(self, _e: "Button.Pressed") -> None:
        self._move_marked()

    def _move_marked(self) -> None:
        refs = self._target_refs()
        if not refs:
            self.app.notify("Mark some models (Space) or put the cursor on one.",
                            severity="information")
            return
        others = [str(c.get("name")) for c in _iter_model_collections_readonly()
                  if isinstance(c, dict) and c.get("name")
                  and c.get("name") != self._active_model_coll]
        if not others:
            self.app.notify("No other collection to move to — make one first.",
                            severity="information")
            return
        self.app.push_screen(
            BabsModelCollectionPickerModal(others, len(refs)),
            lambda tgt: self._move_commit(list(refs), tgt))

    def _move_commit(self, refs: "list[str]", target: "str | None") -> None:
        target = (target or "").strip()
        if not target:
            return
        src = self._active_model_coll
        want = set(refs)
        moved = 0
        with _cache_lock:
            colls = _load_model_collections()
            src_c = next((c for c in colls if isinstance(c, dict)
                          and c.get("name") == src), None)
            tgt_c = next((c for c in colls if isinstance(c, dict)
                          and c.get("name") == target), None)
            if src_c is None or tgt_c is None:
                self.app.notify("Collection vanished — refresh.", severity="warning")
                return
            tgt_c.setdefault("models", [])
            tgt_refs = {m.get("ref") for m in tgt_c["models"] if isinstance(m, dict)}
            keep = []
            for m in (src_c.get("models") or []):
                if isinstance(m, dict) and m.get("ref") in want:
                    if m.get("ref") not in tgt_refs:        # dedupe by ref
                        tgt_c["models"].append(m)
                        tgt_refs.add(m.get("ref"))
                    moved += 1
                else:
                    keep.append(m)
            src_c["models"] = keep
            _save_model_collections(colls)
        self._marked_refs.clear()
        self._repopulate_after_change()
        self.app.notify(f"Moved {moved} model(s) → {target}.", severity="information")

    @on(Button.Pressed, "#babs-del")
    def _on_del_btn(self, _e: "Button.Pressed") -> None:
        self._uninstall_marked()

    def _uninstall_marked(self) -> None:
        if self._busy_models:
            self.app.notify("A model operation is already running.",
                            severity="information")
            return
        refs = self._target_refs()
        if not refs:
            self.app.notify("Mark some models (Space) or put the cursor on one.",
                            severity="information")
            return
        self.app.push_screen(BabsUninstallConfirmModal(list(refs)),
                             lambda ok: self._uninstall_confirm(list(refs), ok))

    def _uninstall_confirm(self, refs: "list[str]", ok: "bool | None") -> None:
        if not ok:
            return
        self._busy_models = True
        self._set_static("#babs-pull-status",
                         f"[dim]uninstalling {len(refs)} model(s)…[/dim]")
        self._uninstall_worker(list(refs))

    @work(thread=True, exclusive=True, group="babs_uninstall")
    def _uninstall_worker(self, refs: "list[str]") -> None:
        installed = dict(self._installed_index)        # snapshot (read on worker)
        results = []        # (ref, ok, err)
        for ref in refs:
            meta = installed.get(ref) or installed.get(ref + ":latest")
            if meta is None:
                results.append((ref, True, None))       # not installed → just unfile
                continue
            try:
                _babs.delete_model(ref)
                results.append((ref, True, None))
            except _babs.BabsError as exc:
                results.append((ref, False, str(exc)))
            except Exception as exc:
                _log.exception("BABS uninstall failed")
                results.append((ref, False, f"{exc}"))
        self.app.call_from_thread(self._uninstall_done, results)

    def _uninstall_done(self, results: "list[tuple]") -> None:
        self._busy_models = False
        ok_refs = {r for r, ok, _ in results if ok}
        failed = [(r, e) for r, ok, e in results if not ok]
        # Unfile successfully-removed refs from the ACTIVE collection only.
        with _cache_lock:
            colls = _load_model_collections()
            for c in colls:
                if isinstance(c, dict) and c.get("name") == self._active_model_coll:
                    c["models"] = [m for m in (c.get("models") or [])
                                   if not (isinstance(m, dict) and m.get("ref") in ok_refs)]
                    break
            _save_model_collections(colls)
        self._marked_refs.clear()
        for r in ok_refs:           # flip live status immediately
            self._installed_index.pop(r, None)
            self._installed_index.pop(r + ":latest", None)
        if not self.is_mounted:
            return
        self._repopulate_after_change()
        # If they just uninstalled the model chat is set to, say so — the next
        # turn would otherwise fail with a cryptic Ollama 404.
        if self._model in ok_refs or (self._model + ":latest") in ok_refs:
            self.app.notify(
                f"Uninstalled the active chat model ({self._model}) — pick "
                f"another with Use, or re-pull it.", severity="warning", timeout=8)
        if failed:
            self._set_static("#babs-pull-status",
                             f"[red]{len(failed)} uninstall(s) failed: "
                             f"{_esc(str(failed[0][1])[:60])}[/red]")
            self.app.notify(f"{len(failed)} model(s) couldn't be uninstalled.",
                            severity="error", timeout=8)
        else:
            self._set_static("#babs-pull-status",
                             f"[green]uninstalled {len(ok_refs)} model(s).[/green]")

    # ── add a ref / pull / use ────────────────────────────────────────────────
    def _add_ref_to_active(self, ref: str) -> bool:
        ref = _sanitize_label(ref)        # strip control chars + cap a pathological paste
        if not ref or not self._active_model_coll:
            return False
        with _cache_lock:
            colls = _load_model_collections()
            coll = next((c for c in colls if isinstance(c, dict)
                         and c.get("name") == self._active_model_coll), None)
            if coll is None:
                return False
            coll.setdefault("models", [])
            if any(isinstance(m, dict) and m.get("ref") == ref for m in coll["models"]):
                self.app.notify("Already in this collection.", severity="information")
                return False
            coll["models"].append({"ref": ref, "note": "",
                                   "added": _date.today().isoformat()})
            _save_model_collections(colls)
        return True

    @on(Button.Pressed, "#babs-add")
    @on(Input.Submitted, "#babs-addname")
    def _on_add_by_name(self, _e=None) -> None:
        try:
            inp = self.query_one("#babs-addname", Input)
        except NoMatches:
            return
        ref = inp.value.strip()
        if not ref:
            return
        if not self._active_model_coll:
            self.app.notify("Make a collection first.", severity="information")
            return
        if self._add_ref_to_active(ref):
            inp.value = ""
            self._repopulate_after_change()
            self.app.notify(f"Added {ref} → {self._active_model_coll}.",
                            severity="information")

    @on(Button.Pressed, "#babs-hf-add")
    def _on_hf_add(self, _e: "Button.Pressed") -> None:
        try:
            h = self.query_one("#babs-hf", DataTable)
        except NoMatches:
            return
        i = h.cursor_row
        ref = self._hf_names[i] if 0 <= i < len(self._hf_names) else None
        if not ref:
            self.app.notify("Select a HuggingFace result first.", severity="information")
            return
        if not self._active_model_coll:
            self.app.notify("Make a collection first.", severity="information")
            return
        if self._add_ref_to_active(ref):
            self._repopulate_after_change()
            self.app.notify(f"Added {ref} → {self._active_model_coll}.",
                            severity="information")

    @on(Button.Pressed, "#babs-model-pull")
    def _on_model_pull(self, _e: "Button.Pressed") -> None:
        self._pull_selected()

    def _pull_selected(self) -> None:
        ref = self._cursor_ref()
        if not ref:
            self.app.notify("Select a model row to pull.", severity="information")
            return
        self._begin_pull(ref, switch_on_done=False)

    @on(Button.Pressed, "#babs-use")
    def _on_use(self, _e: "Button.Pressed") -> None:
        self._use_selected()

    def _use_selected(self) -> None:
        ref = self._cursor_ref()
        if not ref:
            self.app.notify("Select a model row first.", severity="information")
            return
        self._switch_model(ref)

    # ── HuggingFace search (engine unchanged; results feed 'Add to collection') ─
    @on(Button.Pressed, "#babs-hfsearch")
    @on(Input.Submitted, "#babs-hfquery")
    def _on_hf_search(self, _e=None) -> None:
        try:
            q = self.query_one("#babs-hfquery", Input).value.strip()
        except NoMatches:
            return
        if not q:
            return
        self._set_static("#babs-pull-status", "[dim]searching HuggingFace…[/dim]")
        self._search_hf(q)

    @work(thread=True, exclusive=True, group="babs_hf")
    def _search_hf(self, q: str) -> None:
        try:
            res = _babs.hf_search_gguf(q)
        except Exception as exc:
            _log.exception("BABS HF search failed")
            self.app.call_from_thread(self._hf_error, str(exc))
            return
        self.app.call_from_thread(self._fill_hf, res)

    def _fill_hf(self, res: "list[dict]") -> None:
        if not self.is_mounted:
            return
        try:
            h = self.query_one("#babs-hf", DataTable)
        except NoMatches:
            return
        h.clear()
        self._hf_names = []
        for m in res:
            h.add_row(m["id"][:60], f"{m['downloads']:,}", str(m["likes"]))
            self._hf_names.append(m["pull"])
        if not res:
            h.add_row(_RText("(no GGUF repos found)", style="dim"), "", "")
            self._hf_names.append(None)
        self._set_static("#babs-pull-status", f"[dim]{len(res)} result(s)[/dim]")

    def _hf_error(self, msg: str) -> None:
        if not self.is_mounted:
            return
        self._set_static("#babs-pull-status", f"[red]{_esc(msg[:120])}[/red]")

    def _switch_model(self, name: str) -> None:
        name = (name or "").strip()
        if not name:
            return
        if name.startswith("hf.co/") or not _babs.model_is_installed(name):
            self._begin_pull(name, switch_on_done=True)
            return
        self._apply_model(name)

    @staticmethod
    def _babs_embed_model() -> str:
        """The embedding model Babs' corpus uses — mirrors bb_config.EMBED_MODEL
        WITHOUT importing babs: env BABS_EMBED_MODEL, else nomic-embed-text."""
        return (os.getenv("BABS_EMBED_MODEL") or "").strip() or "nomic-embed-text"

    def _goto_chat(self) -> None:
        try:
            self.query_one("#babs-tabs", TabbedContent).active = "babs-tab-chat"
            self.query_one("#babs-input", Input).focus()
        except NoMatches:
            pass

    def _apply_model(self, name: str) -> None:
        changed = (name != self._model)
        self._model = name
        _set_setting("babs_model", name)
        _settings_flush_sync()
        self._refresh_bars()
        self._refresh_num_ctx()       # re-size the window to the new model's real ctx
        self._sys_note(f"[green]model →[/green] {_esc(name)}")
        self.app.notify(f"Active model: {name}", severity="information")
        # A model change only NEEDS a re-embed if the EMBEDDING model changed,
        # but offer it (default No) whenever the model genuinely changed AND a
        # Babs corpus exists — so the user is reminded the corpus may need it.
        if changed and self._resolve_babs_home() is not None:
            self.app.push_screen(
                BabsReembedModal(name, self._babs_embed_model()),
                self._on_reembed_choice)
        else:
            self._goto_chat()

    def _on_reembed_choice(self, do_it: "bool | None") -> None:
        if do_it:
            self._launch_reembed()
            try:
                self.query_one("#babs-tabs", TabbedContent).active = "babs-tab-scrape"
            except NoMatches:
                pass
        else:
            self._goto_chat()

    def _launch_reembed(self) -> None:
        """Re-RAG: wipe + rebuild Babs' vector index from corpus.jsonl with the
        current embedding model (`bb_index.py --reset`). Detached background job,
        surfaced in the scraper tab's jobs list + the keep-alive indicator."""
        import subprocess
        import pathlib
        home = self._resolve_babs_home()
        if home is None:
            self.app.notify("Babs repo not found — can't re-ingest.",
                            severity="warning")
            return
        if any(j.get("kind") == "reindex" and self._job_running(j)
               for j in self._jobs):
            self.app.notify("A re-ingest is already running.",
                            severity="information")
            return
        py = self._babs_python(home)
        ts = time.strftime("%Y%m%d-%H%M%S")
        logdir = home / "knowledge_base" / "jobs"
        try:
            logdir.mkdir(parents=True, exist_ok=True)
        except OSError:
            logdir = pathlib.Path(tempfile.gettempdir())
        logf = logdir / f"sc-reindex-{ts}.log"
        try:
            fh = open(logf, "ab")
            proc = subprocess.Popen(
                [py, "bb_index.py", "--reset"], cwd=str(home),
                stdout=fh, stderr=fh, stdin=subprocess.DEVNULL,
                start_new_session=True, env=os.environ.copy())
        except Exception as exc:
            _log.exception("BABS re-index launch failed")
            self.app.notify(f"Couldn't launch re-ingest: {exc}", severity="error")
            return
        self._jobs.insert(0, {"pid": proc.pid, "kind": "reindex",
                              "label": f"re-embed corpus ({self._babs_embed_model()})",
                              "log": str(logf), "started": ts,
                              "started_mono": time.monotonic(),
                              "token": "bb_index.py", "running": True})
        self._indicator_idle_shown = False
        self.app.notify(
            f"Re-ingesting corpus (pid {proc.pid}) — re-embedding every paper.",
            severity="information")
        self._refresh_jobs_table()
        self._refresh_bars()

    # ── pull on demand ───────────────────────────────────────────────────────────
    def _begin_pull(self, name: str, *, switch_on_done: bool) -> None:
        if self._pulling:
            self.app.notify("A download is already in progress.", severity="information")
            return
        self._pulling = True
        self._pull_cancel = threading.Event()
        self._pull_resp = None
        self._pull_meter = _babs.PullMeter()
        try:
            self.query_one("#babs-pull-bar", ProgressBar).display = True
            self.query_one("#babs-pull-bar", ProgressBar).update(total=100, progress=0)
        except NoMatches:
            pass
        self._set_static("#babs-pull-status", f"[dim]pulling[/dim] {_esc(name)} …")
        self._pull(name, switch_on_done)

    @work(thread=True, exclusive=True, group="babs_pull")
    def _pull(self, name: str, switch_on_done: bool) -> None:
        cancel = self._pull_cancel
        meter = self._pull_meter or _babs.PullMeter()
        err = None
        ok = False
        try:
            for obj in _babs.pull_stream(name, cancel=cancel, register=self._register_pull_resp):
                if cancel is not None and cancel.is_set():
                    break
                e = obj.get("error")
                if e:
                    raise _babs.BabsError(str(e))
                info = meter.update(obj, _monotonic())
                self.app.call_from_thread(self._pull_progress, info)
                if info["status"] == "success":
                    ok = True
        except _babs.BabsError as exc:
            err = str(exc)
        except Exception as exc:
            _log.exception("BABS pull failed")
            err = f"pull error: {exc}"
        self.app.call_from_thread(
            self._pull_done, name, ok, err,
            bool(cancel is not None and cancel.is_set()), switch_on_done)

    def _register_pull_resp(self, resp) -> None:
        self._pull_resp = resp

    def _pull_progress(self, info: dict) -> None:
        if not self.is_mounted:
            return
        frac = info.get("fraction")
        if frac is not None:
            try:
                self.query_one("#babs-pull-bar", ProgressBar).update(total=100, progress=frac * 100)
            except NoMatches:
                pass
        # `text` already composes status · bytes-pulled · percent · speed so a
        # user can see a big pull is genuinely moving (PullMeter, INV-139).
        self._set_static("#babs-pull-status", f"[dim]{_esc(info.get('text') or '')}[/dim]")

    def _pull_done(self, name: str, ok: bool, err: "str | None",
                   stopped: bool, switch_on_done: bool) -> None:
        self._pulling = False
        self._pull_cancel = None
        self._pull_resp = None
        if not self.is_mounted:
            return
        try:
            self.query_one("#babs-pull-bar", ProgressBar).display = False
        except NoMatches:
            pass
        if ok and not stopped and not err:
            self._set_static("#babs-pull-status", f"[green]pulled {_esc(name)}[/green]")
            self._load_models()
            if switch_on_done:
                self._apply_model(name)
            return
        if err:
            self._set_static("#babs-pull-status", f"[red]{_esc(err[:120])}[/red]")
            self.app.notify(f"Pull failed: {err}", severity="error", timeout=8)
        elif stopped:
            self._set_static("#babs-pull-status", "[dim]download cancelled.[/dim]")

    def _stop_pull(self) -> None:
        c = self._pull_cancel
        if c is not None:
            try:
                c.set()
            except Exception:
                pass
        r = self._pull_resp
        if r is not None:
            try:
                r.close()
            except Exception:
                pass

    # ── paper-scraper tab (shells to the real Babs repo) ─────────────────────────
    def _resolve_babs_home(self):
        import pathlib
        for cand in (os.getenv("SPLICECRAFT_BABS_HOME"), os.getenv("BABS_HOME"),
                     _get_setting("babs_home", ""), os.path.expanduser("~/babs")):
            if not cand:
                continue
            try:
                p = pathlib.Path(cand).expanduser()
                if (p / "bb_snowball.py").is_file():
                    return p
            except OSError:
                continue
        return None

    def _babs_python(self, home) -> str:
        venv = home / "venv" / "bin" / "python"
        try:
            if venv.is_file():
                return str(venv)
        except OSError:
            pass
        return sys.executable

    def _refresh_scrape_note(self) -> None:
        home = self._resolve_babs_home()
        if home is None:
            self._set_static(
                "#babs-scrape-note",
                "[yellow]Babs corpus tools not found.[/yellow] [dim]Clone "
                "github.com/ATinyGreenCell/babs to ~/babs (or set "
                "$SPLICECRAFT_BABS_HOME) to launch background paper searches "
                "that grow Babs' knowledge corpus.[/dim]")
            try:
                self.query_one("#babs-scrape-go", Button).disabled = True
            except NoMatches:
                pass
        else:
            self._set_static("#babs-scrape-note",
                             f"[dim]Babs home:[/dim] {_esc(str(home))}")
            try:
                self.query_one("#babs-scrape-go", Button).disabled = False
            except NoMatches:
                pass

    @on(Button.Pressed, "#babs-scrape-go")
    @on(Input.Submitted, "#babs-scrapeq")
    def _on_scrape_go(self, _e=None) -> None:
        try:
            topic = self.query_one("#babs-scrapeq", Input).value.strip()
        except NoMatches:
            return
        if not topic:
            return
        self._launch_scrape(topic)

    def _launch_scrape(self, topic: str) -> None:
        import shlex
        import subprocess
        import pathlib
        home = self._resolve_babs_home()
        if home is None:
            self.app.notify("Babs repo not found — see the note above.",
                            severity="warning")
            return
        py = self._babs_python(home)
        # argv-safe: the topic is shell-quoted into the bash chain; nothing the user
        # types can break out (mirrors rag_bot._cmd_get's chain). Three INDEPENDENT
        # steps, ';'-joined so one source being down can't block the others or the
        # re-index: Europe PMC topical search (snowball, deep cursorMark paging) ; the
        # query-capable open-access sources OpenAlex/CORE/CGSpace/DOAJ (bb_ingest
        # --search) ; embed the newly-added chunks (bb_index). bb_ingest --search is
        # what wires the new sources into the scrape — snowball alone is Europe-PMC-only.
        chain = (f"{shlex.quote(py)} bb_snowball.py --search {shlex.quote(topic)} ; "
                 f"{shlex.quote(py)} bb_ingest.py --search {shlex.quote(topic)} ; "
                 f"{shlex.quote(py)} bb_index.py")
        ts = time.strftime("%Y%m%d-%H%M%S")
        logdir = home / "knowledge_base" / "jobs"
        try:
            logdir.mkdir(parents=True, exist_ok=True)
        except OSError:
            logdir = pathlib.Path(tempfile.gettempdir())
        logf = logdir / f"sc-get-paper-{ts}.log"
        try:
            fh = open(logf, "ab")
            proc = subprocess.Popen(
                ["bash", "-c", chain], cwd=str(home),
                stdout=fh, stderr=fh, stdin=subprocess.DEVNULL,
                start_new_session=True, env=os.environ.copy())
        except Exception as exc:
            _log.exception("BABS scrape launch failed")
            self.app.notify(f"Couldn't launch search: {exc}", severity="error")
            return
        self._jobs.insert(0, {"pid": proc.pid, "kind": "get-paper",
                              "label": topic[:60], "log": str(logf),
                              "started": ts, "started_mono": time.monotonic(),
                              "token": "bb_snowball.py", "running": True})
        self._indicator_idle_shown = False
        try:
            self.query_one("#babs-scrapeq", Input).value = ""
        except NoMatches:
            pass
        self.app.notify(f"Launched paper search (pid {proc.pid}) → {topic}",
                        severity="information")
        self._refresh_jobs_table()
        self._refresh_bars()

    @staticmethod
    def _pid_alive(pid) -> bool:
        try:
            pid = int(pid)
            os.kill(pid, 0)
        except (OSError, ValueError, TypeError):
            return False
        # The /proc zombie-reap below is Linux-only — on macOS (no /proc) the
        # open() would FileNotFoundError and wrongly mark a LIVE job dead, so we
        # trust the kill(0) there. On Linux a babs-launched job is our child, so
        # once it exits it lingers as an unreaped zombie that kill(0) still
        # "sees"; reap it so a finished search stops reading as "running".
        if not sys.platform.startswith("linux"):
            return True
        try:
            with open(f"/proc/{pid}/stat", encoding="utf-8") as f:
                state = f.read().split(") ", 1)[1].split(" ", 1)[0]
            if state == "Z":
                try:
                    os.waitpid(pid, os.WNOHANG)
                except OSError:
                    pass
                return False
        except FileNotFoundError:
            return False        # pid vanished between the kill check and here
        except OSError:
            pass
        return True

    @staticmethod
    def _cmdline_has(pid, token) -> bool:
        """PID-reuse staleguard: True if the live pid's cmdline still contains
        the job's token (its script name). Stops a recycled pid from keeping a
        finished job stuck on 'running'. Non-Linux / unreadable /proc → trust
        the liveness check."""
        if not token:
            return True
        if not sys.platform.startswith("linux"):
            return True
        try:
            with open(f"/proc/{int(pid)}/cmdline", "rb") as f:
                blob = f.read().replace(b"\x00", b" ").decode("utf-8", "replace")
            return token in blob
        except OSError:
            return True

    def _job_running(self, job: dict) -> bool:
        """Genuinely running iff the pid is alive AND (staleguard) its cmdline
        still matches the job's token."""
        return self._pid_alive(job.get("pid")) and self._cmdline_has(
            job.get("pid"), job.get("token"))

    def _sync_jobs(self) -> "tuple[bool, list[dict]]":
        """Refresh each job's staleguarded `running` flag in place. Returns
        (changed, running_jobs)."""
        changed = False
        running: "list[dict]" = []
        for j in self._jobs:
            alive = self._job_running(j)
            if alive != j.get("running"):
                j["running"] = alive
                changed = True
            if alive:
                running.append(j)
        return changed, running

    @staticmethod
    def _fmt_elapsed(started_mono) -> str:
        if not started_mono:
            return "0s"
        s = int(max(0, time.monotonic() - started_mono))
        return f"{s // 60}m {s % 60:02d}s" if s >= 60 else f"{s}s"

    def _tick_indicator(self) -> None:
        """Animate the live 'ingest running' keep-alive indicator (~0.6 s) and
        push realtime, staleguarded job-state changes to the table / bars."""
        if not self.is_mounted:
            return
        changed, running = self._sync_jobs()
        if changed:
            self._refresh_jobs_table()
            self._refresh_jobs_bar()
        if running:
            self._spinner_i = (self._spinner_i + 1) % len(_BABS_SPINNER)
            j = running[0]
            more = (f"  [dim](+{len(running) - 1} more)[/dim]"
                    if len(running) > 1 else "")
            self._set_static(
                "#babs-ingest-indicator",
                f"[green]{_BABS_SPINNER[self._spinner_i]} ingest running[/green]"
                f"[dim] · {_esc(str(j.get('kind', '')))}: "
                f"{_esc(str(j.get('label', '')))} · up "
                f"{self._fmt_elapsed(j.get('started_mono'))}[/dim]{more}")
            self._indicator_idle_shown = False
        elif not self._indicator_idle_shown:
            self._set_static("#babs-ingest-indicator",
                             "[dim]○ no active ingest[/dim]")
            self._indicator_idle_shown = True

    def _poll_jobs(self) -> None:
        if not self._jobs:
            return
        changed, _ = self._sync_jobs()
        if changed:
            self._refresh_jobs_table()
            self._refresh_bars()
        self._refresh_logtail()
        if self._learn_active_slug:
            self._refresh_learn_status()

    def _refresh_jobs_table(self) -> None:
        try:
            t = self.query_one("#babs-jobs", DataTable)
        except NoMatches:
            return
        t.clear()
        for j in self._jobs:
            tag = (_RText("running", style="green") if j.get("running")
                   else _RText("exited", style="dim"))
            t.add_row(str(j["pid"]), j["kind"], j["label"], tag)
        if not self._jobs:
            t.add_row(_RText("(no jobs launched yet)", style="dim"), "", "", "")

    def _refresh_logtail(self) -> None:
        if not self._jobs:
            return
        path = self._jobs[0].get("log")
        if not path:
            return
        text = ""
        try:
            with open(path, "rb") as f:
                f.seek(0, os.SEEK_END)
                size = f.tell()
                f.seek(max(0, size - 8192))
                text = f.read().decode("utf-8", "replace")
        except OSError:
            return
        # Keep the last ~40 lines so the box stays bounded, and strip any ANSI
        # colour codes so they don't render as raw escape junk.
        text = _BABS_ANSI_RE.sub("", "\n".join(text.splitlines()[-40:]))
        self._set_static("#babs-logtail", text)

    @on(Button.Pressed, "#babs-jobs-refresh")
    def _on_jobs_refresh(self, _e: "Button.Pressed") -> None:
        self._poll_jobs()
        self._refresh_jobs_table()

    @on(Button.Pressed, "#babs-kill")
    def _on_kill(self, _e: "Button.Pressed") -> None:
        import signal
        try:
            t = self.query_one("#babs-jobs", DataTable)
            i = t.cursor_row
        except NoMatches:
            return
        if not (0 <= i < len(self._jobs)):
            return
        job = self._jobs[i]
        if not self._pid_alive(job["pid"]):
            self.app.notify("That job already exited.", severity="information")
            self._poll_jobs()
            return
        try:
            os.killpg(os.getpgid(job["pid"]), signal.SIGTERM)
        except OSError:
            try:
                os.kill(job["pid"], signal.SIGTERM)
            except OSError as exc:
                self.app.notify(f"Couldn't kill: {exc}", severity="error")
                return
        self.app.notify(f"Sent SIGTERM to pid {job['pid']}.", severity="information")
        self._poll_jobs()
        self._refresh_jobs_table()

    # ── Learn tab (Background Learning) ──────────────────────────────────────────
    def _refresh_learn_note(self) -> None:
        """Babs-home + arming status for the Learn tab; disables the button when no babs repo."""
        home = _learn_resolve_babs_home()
        try:
            go = self.query_one("#babs-learn-go", Button)
        except NoMatches:
            go = None
        if home is None:
            self._set_static("#babs-learn-note",
                "[yellow]Babs corpus tools not found.[/yellow] [dim]Clone "
                "github.com/ATinyGreenCell/babs to ~/babs (or set $SPLICECRAFT_BABS_HOME) to grow "
                "topic corpora.[/dim]")
            if go is not None:
                go.disabled = True
            return
        note = f"[dim]Babs home:[/dim] {_esc(str(home))}"
        if not _get_setting("allow_online_lookups", False):
            note += ("\n[yellow]Online lookups are off.[/yellow] [dim]Enable Settings -> "
                     "'Allow Babs online database lookups' to let a session reach open "
                     "databases.[/dim]")
        self._set_static("#babs-learn-note", note)
        if go is not None:
            go.disabled = False

    @on(Button.Pressed, "#babs-learn-go")
    @on(Input.Submitted, "#babs-learnq")
    def _on_learn_go(self, _e=None) -> None:
        try:
            topic = self.query_one("#babs-learnq", Input).value.strip()
        except NoMatches:
            return
        if not topic:
            return
        if not _get_setting("allow_online_lookups", False):
            self.app.notify("Enable Settings -> 'Allow Babs online database lookups' first.",
                            severity="warning")
            return
        _home = _learn_resolve_babs_home()
        if _home is not None and _learn_session_running(_home, _learn_slug(topic)):
            self.app.notify("A learning session for that topic is already running.",
                            severity="warning")
            return
        max_docs = None
        try:
            raw = self.query_one("#babs-learn-docs", Input).value.strip()
            if raw:
                max_docs = max(1, min(int(raw), 200))
        except (NoMatches, ValueError):
            max_docs = None
        try:
            info = _launch_learning_session(topic, max_docs, None)
        except Exception as exc:
            _log.exception("BABS learn launch failed")
            self.app.notify(f"Couldn't launch learning session: {exc}", severity="error")
            return
        self._learn_active_slug = info["slug"]
        _set_setting("babs_learn_slug", info["slug"])   # survive an app restart
        self._jobs.insert(0, {"pid": info["pid"], "kind": "learn", "label": topic[:60],
                              "log": info["log"], "started": time.strftime("%Y%m%d-%H%M%S"),
                              "started_mono": time.monotonic(), "token": "bb_learn.py",
                              "running": True})
        self._indicator_idle_shown = False
        try:
            self.query_one("#babs-learnq", Input).value = ""
        except NoMatches:
            pass
        self.app.notify(f"Learning about '{topic}' (pid {info['pid']}) - watch progress below.",
                        severity="information")
        self._refresh_jobs_table()
        self._refresh_bars()
        self._refresh_learn_status()

    @on(Button.Pressed, "#babs-learn-stop")
    def _on_learn_stop(self, _e: "Button.Pressed") -> None:
        """SIGTERM the running Background-Learning crawl (kind='learn') right
        from the Learn tab, instead of making the user switch to the
        Paper-scraper tab and hunt for it in the jobs table."""
        import signal
        job = next((j for j in self._jobs
                    if j.get("kind") == "learn"
                    and self._pid_alive(j.get("pid"))), None)
        if job is None:
            self.app.notify("No learning session is running.",
                            severity="information")
            return
        try:
            os.killpg(os.getpgid(job["pid"]), signal.SIGTERM)
        except OSError:
            try:
                os.kill(job["pid"], signal.SIGTERM)
            except OSError as exc:
                self.app.notify(f"Couldn't stop: {exc}", severity="error")
                return
        self.app.notify(f"Stopped the learning session (pid {job['pid']}).",
                        severity="information")
        self._poll_jobs()
        self._refresh_jobs_table()
        self._refresh_learn_status()

    def _refresh_learn_status(self) -> None:
        """Repaint the active session's live counters from its babs-written progress.json."""
        slug = self._learn_active_slug
        if not slug:
            return
        home = _learn_resolve_babs_home()
        if home is None:
            return
        prog = _learn_reconcile_status(
            _learn_read_json_safe(_learn_session_dir(home, slug) / "progress.json"))
        if not prog:
            self._set_static("#babs-learn-status",
                             f"[dim]Starting learning session [b]{_esc(slug)}[/b] ...[/dim]")
            return
        status = str(prog.get("status", "running"))
        colour = {"running": "yellow", "done": "green", "paused-drift": "red",
                  "budget-exhausted": "cyan", "interrupted": "white",
                  "stopped": "red"}.get(status, "white")
        drift = " [red]· drift detected — paused for review[/red]" if prog.get("drift") else ""
        self._set_static("#babs-learn-status",
            f"[{colour}]{_esc(status)}[/{colour}] · kept [b]{prog.get('kept', 0)}[/b] · "
            f"fetched {prog.get('fetched', 0)} · dropped {prog.get('dropped', 0)} · "
            f"frontier {prog.get('frontier', 0)}{drift}")

    @on(Button.Pressed, "#babs-learn-refresh")
    def _on_learn_refresh(self, _e=None) -> None:
        self._refresh_learn_status()
        self._poll_jobs()

    @on(Button.Pressed, "#babs-learn-results-btn")
    def _on_learn_results(self, _e=None) -> None:
        slug = self._learn_active_slug
        if not slug:
            self.app.notify("Start a learning session first.", severity="information")
            return
        home = _learn_resolve_babs_home()
        if home is None:
            return
        try:
            t = self.query_one("#babs-learn-results", DataTable)
        except NoMatches:
            return
        t.clear()
        docs = _learn_kept_docs(home, slug, 200)
        for d in docs:
            score = d.get("relevance_score")
            score_s = f"{score:.2f}" if isinstance(score, (int, float)) else "-"
            hop = d.get("hop")
            t.add_row(score_s, str(hop) if hop is not None else "",
                      (d.get("title") or d.get("doc_id") or "")[:80])
        if not docs:
            t.add_row("-", "", _RText("(nothing kept yet — check back as it runs)", style="dim"))
        self._refresh_learn_status()


# ── Menu bar widget ────────────────────────────────────────────────────────────

class _MenuBarScroll(HorizontalScroll):
    """Horizontal-scroll WRAPPER around MenuBar so a too-narrow terminal can pan
    to items clipped off the right (e.g. BABS at the end). It FLOWS directly below
    the docked Header (compose order, not docked itself — a docked scroll
    container overlaps the Header). Styled here because a widget's DEFAULT_CSS is
    scoped to its own subtree and this is MenuBar's PARENT. The scrollbar is
    hidden (one-row bar); mouse-wheel / drag pans it.

    Why a wrapper, not making MenuBar itself scroll: when MenuBar IS the scroll
    container the app's splash dismissal stalls and the menu becomes
    unclickable. Keeping MenuBar a plain (non-scroll) container preserves the
    original click/splash behaviour while the wrapper supplies the scrolling."""
    DEFAULT_CSS = """
    _MenuBarScroll {
        height: 1;
        width: 100%;
        background: $primary-darken-3;
        overflow-x: auto;
        overflow-y: hidden;
        scrollbar-size-horizontal: 0;
    }
    """


class MenuBar(Horizontal):
    """The top menu bar — a plain Horizontal container (NOT a scroll container,
    which stalls the splash + breaks clicks) that sizes to its CONTENT
    (`width: auto`) and is composed inside a `_MenuBarScroll` (PlasmidApp.compose)
    that scrolls when the items overflow a narrow terminal. Click dispatch is the
    original region hit-test in `on_click`."""

    DEFAULT_CSS = """
    MenuBar {
        height: 1;
        width: auto;
        background: $primary-darken-3;
        layout: horizontal;
    }
    MenuBar Static {
        width: auto;
        padding: 0 2;
        color: $text;
    }
    MenuBar Static:hover {
        background: $primary;
    }
    """

    # "Mutato" is the (whimsical) display label for the mutagenesis tool;
    # the action/modal/worker names stay `mutagenize` internally.
    MENUS = ["File", "Settings", "BLAST", "Enzymes", "Features", "Primers",
             "Mutato", "Synthesis", "Parts", "Constructor", "Simulator",
             "Sequencing", "Experiments", "History", "AUTOLAB", "BABS"]

    def compose(self) -> ComposeResult:
        for name in self.MENUS:
            yield Static(name, classes="menu-item", id=f"menu-{name.lower()}")

    def _activate(self, name: str, region) -> None:
        # "Features"/"Experiments"/"History"/"Settings"/"Enzymes"/"BABS" are
        # direct-open screens (no dropdown); every other menu surfaces items via
        # a positioned DropdownScreen anchored just below the clicked item.
        if name == "Features":
            self.app.push_screen(FeatureLibraryScreen())
        elif name == "Experiments":
            self.app.action_open_experiments()  # type: ignore[attr-defined]
        elif name == "History":
            self.app.action_show_history()  # type: ignore[attr-defined]
        elif name == "Settings":
            self.app.action_open_settings()  # type: ignore[attr-defined]
        elif name == "Enzymes":
            self.app.action_open_enzyme_collections()  # type: ignore[attr-defined]
        elif name == "BABS":
            self.app.action_open_babs()  # type: ignore[attr-defined]
        elif name == "AUTOLAB":
            self.app.action_open_autolab()  # type: ignore[attr-defined]
        else:
            self.app.open_menu(name, region.x, region.y + 1)  # type: ignore[attr-defined]

    def on_click(self, event: Click) -> None:
        for name in self.MENUS:
            try:
                item = self.query_one(f"#menu-{name.lower()}", Static)
            except NoMatches:
                continue
            region = item.region
            if (region.x <= event.screen_x < region.x + region.width and
                    region.y <= event.screen_y < region.y + region.height):
                self._activate(name, region)
                break


class OT2LabwarePickerModal(ModalScreen):
    """Choose the labware for one OT-2 deck slot (or clear it). Dismisses with a
    dict: {"action":"place","labware":<alias|'custom:name'>,"nickname":str} |
    {"action":"remove"} | {"action":"new"} | None (cancel)."""

    _blocks_undo: bool = True
    BINDINGS = [Binding("escape", "cancel", "Cancel", show=True)]
    DEFAULT_CSS = """
    OT2LabwarePickerModal { align: center middle; }
    OT2LabwarePickerModal #ot2lw-dlg {
        width: 64; height: auto; padding: 1 2; border: solid $primary; background: $surface;
    }
    OT2LabwarePickerModal #ot2lw-title { text-style: bold; color: $accent; margin: 0 0 1 0; }
    OT2LabwarePickerModal .ot2lw-row { height: 3; width: 100%; }
    OT2LabwarePickerModal .ot2lw-lbl { width: 11; padding: 1 1 0 0; color: $text-muted; }
    OT2LabwarePickerModal Select, OT2LabwarePickerModal Input { width: 1fr; }
    OT2LabwarePickerModal #ot2lw-btns { height: 3; width: 100%; align: right middle; margin: 1 0 0 0; }
    OT2LabwarePickerModal #ot2lw-btns Button { width: auto; min-width: 10; margin: 0 0 0 1; }
    """

    def __init__(self, slot: int, current: "dict | None" = None) -> None:
        super().__init__()
        self._slot = slot
        self._current = current or {}

    def _options(self) -> "list[tuple[str, str]]":
        opts: "list[tuple[str, str]]" = [(f"tip rack · {a}", a)
                                         for a in ("tiprack_300", "tiprack_20", "tiprack_1000")]
        opts += [(a, a) for a in ("eppi_24", "eppi_24_2ml", "tuberack_15", "tuberack_6x50",
                                  "plate_6", "plate_12", "plate_24", "plate_48", "plate_96",
                                  "plate_96_flat", "plate_96_deep", "reservoir_12", "reservoir_1")]
        try:
            for coll in _load_custom_labware():
                for lw in coll.get("labware", []) or []:
                    if lw.get("name"):
                        opts.append((f"custom · {lw['name']}", f"custom:{lw['name']}"))
        except Exception:
            pass
        return opts

    def compose(self) -> ComposeResult:
        opts = self._options()
        values = {v for _, v in opts}
        cur = self._current.get("labware")
        init = (f"custom:{cur}" if self._current.get("definition") and f"custom:{cur}" in values
                else (cur if cur in values else "plate_24"))
        with Vertical(id="ot2lw-dlg"):
            yield Static(f"Deck slot {self._slot}", id="ot2lw-title")
            with Horizontal(classes="ot2lw-row"):
                yield Static("Labware", classes="ot2lw-lbl")
                yield Select(opts, value=init, id="ot2lw-select", allow_blank=False)
            with Horizontal(classes="ot2lw-row"):
                yield Static("Nickname", classes="ot2lw-lbl")
                yield Input(value=self._current.get("id", ""),
                            placeholder="e.g. src  (blank = auto; ignored for tip racks)",
                            id="ot2lw-nick")
            with Horizontal(id="ot2lw-btns"):
                yield Button("Place", id="ot2lw-place", variant="primary",
                             tooltip="Put this labware in the slot")
                yield Button("New labware", id="ot2lw-new",
                             tooltip="Go to the Labware tab to define custom labware")
                if self._current:
                    yield Button("Remove", id="ot2lw-remove", variant="error",
                                 tooltip="Clear this deck slot")
                yield Button("Cancel", id="ot2lw-cancel", tooltip="Close without changes")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        bid = event.button.id or ""
        if bid == "ot2lw-place":
            self.dismiss({"action": "place",
                          "labware": str(self.query_one("#ot2lw-select", Select).value),
                          "nickname": self.query_one("#ot2lw-nick", Input).value.strip()})
        elif bid == "ot2lw-new":
            self.dismiss({"action": "new"})
        elif bid == "ot2lw-remove":
            self.dismiss({"action": "remove"})
        else:
            self.dismiss(None)

    def action_cancel(self) -> None:
        self.dismiss(None)


class OT2DiscoverModal(ModalScreen):
    """Enumerate the OT-2 robots that discovery found on the network / USB and pick
    one to connect to. Dismisses with the chosen robot dict, ``{"action":"rescan"}``,
    or ``None`` (cancel). The highlighted row defaults to the first (top-ranked)
    robot, so Connect / Enter is a one-key 'connect to the first robot on the list'."""

    _blocks_undo: bool = True
    BINDINGS = [Binding("escape", "cancel", "Cancel", show=True)]
    DEFAULT_CSS = """
    OT2DiscoverModal { align: center middle; }
    OT2DiscoverModal #ot2disc-dlg {
        width: 82; max-width: 96%; height: auto; max-height: 90%; padding: 1 2;
        border: solid $primary; background: $surface;
    }
    OT2DiscoverModal #ot2disc-title { text-style: bold; color: $accent; margin: 0 0 1 0; }
    OT2DiscoverModal #ot2disc-table { height: auto; max-height: 16; margin: 0 0 1 0; }
    OT2DiscoverModal #ot2disc-hint { color: $text-muted; margin: 0 0 1 0; }
    OT2DiscoverModal #ot2disc-btns { height: 3; width: 100%; align: right middle; }
    OT2DiscoverModal #ot2disc-btns Button { width: auto; min-width: 10; margin: 0 0 0 1; }
    """

    # source tag -> friendly "Via" label for the table.
    _VIA = {"known": "saved", "network": "network", "usb": "USB"}

    def __init__(self, robots: "list[dict]", hint: "str | None" = None) -> None:
        super().__init__()
        self._robots = list(robots or [])
        self._hint = hint or ""

    def compose(self) -> ComposeResult:
        n = len(self._robots)
        with Vertical(id="ot2disc-dlg"):
            yield Static(f"Found {n} OT-2 robot{'s' if n != 1 else ''}"
                         if n else "No OT-2 robots found", id="ot2disc-title")
            if n:
                yield DataTable(id="ot2disc-table", zebra_stripes=True, cursor_type="row")
            if self._hint:
                yield Static(_esc(self._hint), id="ot2disc-hint")
            with Horizontal(id="ot2disc-btns"):
                if n:
                    yield Button("Connect", id="ot2disc-connect", variant="primary",
                                 tooltip="Connect to the highlighted robot")
                yield Button("Rescan", id="ot2disc-rescan",
                             tooltip="Search the network again")
                yield Button("Cancel", id="ot2disc-cancel",
                             tooltip="Close without connecting")

    def on_mount(self) -> None:
        if not self._robots:
            return
        try:
            t = self.query_one("#ot2disc-table", DataTable)
            t.add_columns("Name", "Host", "Via", "Model", "Firmware")
            for r in self._robots:
                t.add_row(str(r.get("name") or r.get("host") or "?"),
                          str(r.get("host") or ""),
                          self._VIA.get(str(r.get("source")), str(r.get("source") or "")),
                          str(r.get("model") or "OT-2"),
                          str(r.get("fw_version") or "—"))
            t.focus()
        except Exception:
            pass

    def _selected(self) -> "dict | None":
        try:
            idx = self.query_one("#ot2disc-table", DataTable).cursor_row
            if 0 <= idx < len(self._robots):
                return self._robots[idx]
        except Exception:
            pass
        return self._robots[0] if self._robots else None

    def on_data_table_row_selected(self, event) -> None:
        self.dismiss(self._selected())

    def on_button_pressed(self, event: Button.Pressed) -> None:
        bid = event.button.id or ""
        if bid == "ot2disc-connect":
            self.dismiss(self._selected())
        elif bid == "ot2disc-rescan":
            self.dismiss({"action": "rescan"})
        else:
            self.dismiss(None)

    def action_cancel(self) -> None:
        self.dismiss(None)


class OT2DeckMap(Widget):
    """A drawn, clickable schematic of the OT-2 deck — its 11 slots + the fixed
    trash rendered as ONE connected grid of boxes in the physical layout (10/11/12
    across the top … 1/2/3 along the bottom), like a top-down diagram of the robot.
    Each bay is colour-filled by what sits on it (tips / labware / the library-bound
    plate / empty / trash); click a bay to place or clear its labware.

    Bays are drawn at the real slot's ASPECT RATIO: a slot's physical footprint
    (``_OT2_SLOT_FOOTPRINT_MM``, ~1.49:1 landscape) is reproduced on screen after
    correcting for the terminal cell being ~2× taller than wide — a cols:rows target
    of ~3:1 per bay — so a bay looks like the slot's rectangle instead of a squished
    sliver. The whole deck scales to fit BOTH the terminal width and the parent's
    height budget (``set_height_budget``), then centres horizontally."""

    DEFAULT_CSS = "OT2DeckMap { width: 100%; height: auto; }"

    _COLS = 3
    _ROWS = 4
    # A monospace terminal cell is ~2× taller than wide; 0.5 (width/height) converts
    # the physical slot aspect into a cols:rows target. Tune here if a font is squarer.
    _CELL_ASPECT = 0.5
    _CH_MIN = 2           # inner rows per bay — floor (still legible)
    _CH_MAX = 6           # ceiling (keeps the deck from dwarfing the tab)
    _CW_MIN = 6           # inner cols per bay — floor (fits the slot number + tag)

    def __init__(self, on_bay=None, *, id=None) -> None:
        super().__init__(id=id)
        self._deck: "dict[int, dict]" = {}
        self._bound: "int | None" = None
        self._on_bay = on_bay
        # Max rows the deck may occupy (the parent's height budget). Default → ch 3.
        self._budget = self._ROWS * 3 + (self._ROWS + 1)
        self._ch = 3          # last-computed inner rows per bay
        self._cw = 12         # last-computed inner cols per bay (for click mapping)
        self._pad_left = 0    # left pad that centres the grid (for click mapping)

    def set_state(self, deck, bound_slot) -> None:
        self._deck = deck or {}
        self._bound = bound_slot
        self.refresh()

    def set_height_budget(self, rows: int) -> None:
        """Set the max rows the deck may occupy (the parent sizes this to the
        terminal). The bay height follows, capped by the aspect lock + the width, so
        a taller terminal gives taller (still rectangle-true) bays."""
        floor = self._CH_MIN * self._ROWS + (self._ROWS + 1)
        self._budget = max(floor, int(rows))
        # Recompute now so callers (and tests) see the new _ch immediately.
        self._cw, self._ch, _, self._pad_left = self._geometry(self.size.width)
        self.refresh(layout=True)   # height depends on ch

    def _geometry(self, width) -> "tuple[int, int, int, int]":
        """Aspect-locked bay size for a content ``width``. Picks the largest bay that
        fits both the width and the height budget while holding the slot's real
        cols:rows ratio, then centres the grid. Returns ``(cw, ch, grid_w, pad_left)``."""
        cols, rows = self._COLS, self._ROWS
        w = int(width) if width and width > 0 else 60
        wmm, dmm = _ot2._OT2_SLOT_FOOTPRINT_MM
        # cols:rows per bay so (cw·cell_w):(ch·cell_h) == footprint width:depth.
        k = (wmm / dmm) / self._CELL_ASPECT if (dmm and self._CELL_ASPECT) else 3.0
        ch_by_h = (self._budget - (rows + 1)) / rows            # height budget cap
        ch_by_w = (w - (cols + 1)) / (cols * k) if k > 0 else ch_by_h  # width cap
        ch = int(min(ch_by_h, ch_by_w))
        ch = max(self._CH_MIN, min(self._CH_MAX, ch))
        cw = max(self._CW_MIN, int(round(k * ch)))
        grid_w = cols * cw + (cols + 1)
        pad_left = max(0, (w - grid_w) // 2)
        return cw, ch, grid_w, pad_left

    def get_content_height(self, container, viewport, width) -> int:
        # 1 top border + 4 rows × ch content lines + 3 inner dividers + 1 bottom.
        # Cache the geometry from the authoritative layout width so render matches.
        self._cw, self._ch, _, self._pad_left = self._geometry(width)
        return self._ROWS * self._ch + (self._ROWS + 1)

    def _palette(self) -> dict:
        """Concrete theme colours; the fills are the accent blended toward the
        surface so occupied bays read as tinted, not garish."""
        from textual.color import Color
        tv = getattr(self.app, "theme_variables", {}) or {}

        def c(name, default):
            try:
                return Color.parse(tv.get(name) or default)
            except Exception:
                return Color.parse(default)
        surface = c("surface", "#1e1e1e")
        fg = c("foreground", "#e0e0e0")

        def tint(name, default):
            return c(name, default).blend(surface, 0.80)
        return {
            "line": c("primary-darken-2", "#0053aa"), "fg": fg,
            "dim": fg.blend(surface, 0.55), "empty": surface,
            "occupied": tint("primary", "#0178d4"), "tips": tint("success", "#4ebf71"),
            "bound": tint("warning", "#fea62b"), "trash": c("panel", "#242f38"),
            "a_occupied": c("primary", "#0178d4"), "a_tips": c("success", "#4ebf71"),
            "a_bound": c("warning", "#fea62b"),
        }

    def _bay(self, slot, pal):
        """(bg, fg, accent, tag, name) for a slot's bay."""
        if slot == 12:
            return pal["trash"], pal["dim"], pal["dim"], "trash", "trash"
        e = self._deck.get(slot)
        if not e:
            return pal["empty"], pal["dim"], pal["dim"], "", "empty"
        short = _ot2._ot2_short_labware(_ot2._ot2_resolve_labware(str(e.get("labware", ""))))
        if e.get("kind") == "tips":
            return pal["tips"], pal["fg"], pal["a_tips"], "tips", short
        name = "custom" if e.get("definition") else short
        nick = e.get("id")
        label = f"{nick}·{name}" if nick else name
        if slot == self._bound and e.get("kind") == "labware":
            return pal["bound"], pal["fg"], pal["a_bound"], "bound", label
        return pal["occupied"], pal["fg"], pal["a_occupied"], "", label

    def render(self):
        from rich.style import Style
        from rich.cells import cell_len, set_cell_size
        cols = self._COLS
        layout = _ot2._OT2_DECK_LAYOUT
        pal = self._palette()
        cw, ch, _grid_w, pad_left = self._geometry(self.size.width)
        self._cw, self._ch, self._pad_left = cw, ch, pad_left
        pad = " " * pad_left          # centres the grid in the flexed widget width
        line = Style(color=pal["line"].rich_color)

        def fill(bg, fg=None, bold=False, dim=False):
            return Style(color=(fg.rich_color if fg else None),
                         bgcolor=bg.rich_color, bold=bold, dim=dim)

        def hbar(left, mid, right):
            tt = Text(pad)
            tt.append(left + mid.join("─" * cw for _ in range(cols)) + right, line)
            return tt

        def cell_line(tt, li, slot, bay):
            bg, fg, accent, tag, name = bay
            if li == 0:                                   # slot number (+ state tag)
                left = f" {slot}"
                right = f"{tag} " if tag else ""
                if len(left) + len(right) > cw:
                    tt.append((left + right)[:cw].ljust(cw), fill(bg, accent, bold=True))
                    return
                tt.append(left, fill(bg, accent, bold=True))
                tt.append(" " * (cw - len(left) - len(right)), fill(bg))
                if right:
                    tt.append(right, fill(bg, fg, dim=True))
            elif li == min(1, ch - 1) and name:           # centred labware name
                # Truncate/pad by DISPLAY width (cell_len), so a wide/CJK/emoji char
                # in a labware nickname can't shove the grid columns out of line.
                s = set_cell_size(name, cw) if cell_len(name) > cw else name
                pad = cw - cell_len(s)
                tt.append(" " * (pad // 2), fill(bg))
                tt.append(s, fill(bg, fg))
                tt.append(" " * (pad - pad // 2), fill(bg))
            else:
                tt.append(" " * cw, fill(bg))

        rows_out = [hbar("┌", "┬", "┐")]
        for ri, row in enumerate(layout):
            bays = [(slot, self._bay(slot, pal)) for slot in row]
            for li in range(ch):
                tt = Text(pad)
                tt.append("│", line)
                for slot, bay in bays:
                    cell_line(tt, li, slot, bay)
                    tt.append("│", line)
                rows_out.append(tt)
            rows_out.append(hbar("├", "┼", "┤") if ri < len(layout) - 1
                            else hbar("└", "┴", "┘"))
        result = Text("\n").join(rows_out)
        # Never wrap: on an ultra-narrow terminal the right edge crops (keeping the
        # grid intact) rather than wrapping (which would break every row + the
        # get_content_height contract).
        result.no_wrap = True
        result.overflow = "crop"
        return result

    def _slot_at(self, x, y):
        """Map a click offset to a slot number, or None if the click landed outside
        the drawn grid (the centred grid leaves wide side gutters — a click there must
        NOT clamp to an edge bay and pop a picker from whitespace)."""
        ch, cw = self._ch, self._cw
        layout = _ot2._OT2_DECK_LAYOUT
        grid_w = self._COLS * cw + (self._COLS + 1)
        grid_h = self._ROWS * ch + (self._ROWS + 1)
        xx = x - self._pad_left          # undo the centring offset
        if xx < 0 or xx >= grid_w or y < 0 or y >= grid_h:
            return None
        row = 0 if y <= 0 else (y - 1) // (ch + 1)
        col = 0 if xx <= 0 else (xx - 1) // (cw + 1)
        row = max(0, min(len(layout) - 1, row))
        col = max(0, min(self._COLS - 1, col))
        return layout[row][col]

    def on_click(self, event) -> None:
        try:
            off = event.get_content_offset(self)
        except Exception:
            off = None
        if off is None or self._on_bay is None:
            return
        slot = self._slot_at(off.x, off.y)
        if slot is not None:
            self._on_bay(slot)


class AutolabScreen(Screen):
    """AUTOLAB — drive an Opentrons OT-2 liquid handler for plate prep.

    A front-end over the app-free ``splicecraft_opentrons`` sibling: lay out a
    pipette + labware on deck slots, build a list of well-to-well transfers,
    compile them into an Opentrons protocol, analyse it on the robot (server-side
    simulate — no motion), watch full robot state / sensors for a crash, and —
    only when ARMED — run it. Every network call runs off the UI thread; the
    physical run is gated in the engine on a clean analysis + a pre-flight health
    check, and it halts + reports the instant a fault is detected."""

    _blocks_undo: bool = True   # hosts Input widgets -> keep app Ctrl+Z off the canvas

    # Idle connection-badge heartbeat (seconds). A tiny /health GET — light enough
    # to leave running while the tab is open, paused during a run.
    _PING_INTERVAL: float = 8.0

    BINDINGS = [
        Binding("escape", "close", "Close", show=True),
    ]

    DEFAULT_CSS = """
    /* Wear the app Header + MenuBar chrome (added in compose), then a full-height
       TabbedContent. Panes MUST be 1fr (not %/auto) or they collapse to a void —
       the proven babs / Sequencing pattern. Content boxes carry a uniform 1-char
       inset so nothing crams against the terminal edge. */
    AutolabScreen #autolab-tabs { width: 100%; height: 1fr; }
    AutolabScreen #autolab-tabs > TabPane { height: 1fr; padding: 0; }
    AutolabScreen #autolab-design, AutolabScreen #autolab-robot {
        width: 100%; height: 1fr; padding: 1 1 0 1;
    }
    /* Section headers: one blank row above, the app's own text colour. */
    AutolabScreen .autolab-hdr { height: 1; margin: 1 0 0 0; color: $text; text-style: bold; }
    /* Control rows: uniform height 3, one blank row below each (the single space
       between groups). Every element carries a 1-col right margin, so labels and
       controls sit exactly one space apart, consistently across the whole form. */
    AutolabScreen .autolab-row { height: 3; width: 100%; margin: 0 0 1 0; }
    AutolabScreen .autolab-row Static {
        height: 3; content-align: left middle; margin: 0 1 0 0; color: $text-muted;
    }
    AutolabScreen .autolab-row Input,
    AutolabScreen .autolab-row Select,
    AutolabScreen .autolab-row Button,
    AutolabScreen .autolab-row Checkbox { margin: 0 1 0 0; }
    /* Field sizes. */
    AutolabScreen #autolab-host { width: 32; }
    AutolabScreen .autolab-slot { width: 8; }
    AutolabScreen .autolab-well { width: 10; }
    AutolabScreen .autolab-vol { width: 10; }
    AutolabScreen .autolab-ref { width: 16; }
    AutolabScreen .autolab-text { width: 30; }
    AutolabScreen #autolab-pipette, AutolabScreen #autolab-src,
    AutolabScreen #autolab-dst { width: 24; }
    AutolabScreen #autolab-mount, AutolabScreen #autolab-newtip,
    AutolabScreen #autolab-tips { width: 16; }
    AutolabScreen .autolab-row Button { width: auto; min-width: 10; }
    AutolabScreen #autolab-arm { width: auto; }
    /* Framed surfaces match the app's panel border + surface (same tokens as babs). */
    AutolabScreen #autolab-table {
        height: 11; width: 100%; border: solid $primary-darken-2; margin: 1 0;
    }
    AutolabScreen #autolab-run-progress {
        height: auto; width: 100%; color: $text; text-style: bold; margin: 1 0 0 0;
    }
    AutolabScreen #autolab-log {
        height: 1fr; width: 100%; border: solid $primary-darken-2;
        padding: 0 1; background: $surface; margin: 0 0 1 0;
    }
    AutolabScreen #autolab-proto {
        height: 14; width: 100%; border: solid $primary-darken-2;
    }
    AutolabScreen #autolab-deck-pane, AutolabScreen #autolab-labware {
        width: 100%; height: 1fr; padding: 1 1 0 1;
    }
    /* Deck: a drawn schematic of the physical OT-2 deck (see OT2DeckMap). Bays are
       drawn at the real slot aspect ratio, sized to fit the terminal width + the
       height budget from _scale_deck, and centred. Colour is per-bay in render. */
    AutolabScreen #autolab-deck-map { width: 100%; height: auto; margin: 1 1; }
    AutolabScreen #autolab-steplist { height: auto; width: 100%; margin: 0 1; }
    AutolabScreen #autolab-lw-table {
        height: 8; width: 100%; border: solid $primary-darken-2; margin: 0 1;
    }
    AutolabScreen #autolab-library { width: 100%; height: 1fr; padding: 1 1 0 1; }
    AutolabScreen #autolab-lib-map {
        height: 10; width: 100%; border: solid $primary-darken-2; margin: 0 1;
    }
    AutolabScreen #autolab-lib-conc {
        height: 6; width: 100%; border: solid $primary-darken-2; margin: 0 1 1 1;
    }
    AutolabScreen #autolab-lib-coll, AutolabScreen #autolab-lib-slot,
    AutolabScreen #autolab-lib-dst, AutolabScreen #autolab-lib-mode { width: 22; }
    AutolabScreen #autolab-calib { width: 100%; height: 1fr; padding: 1 1 0 1; }
    AutolabScreen #autolab-calib-status, AutolabScreen #autolab-off-list {
        height: auto; width: 100%; margin: 0 1 1 1; color: $text;
    }
    AutolabScreen #autolab-off-slot { width: 20; }
    /* Live telemetry surfaces (Deck tab). */
    AutolabScreen #autolab-conn {
        width: auto; height: 3; content-align: left middle; margin: 0 0 0 1;
    }
    AutolabScreen #autolab-crash-banner {
        height: auto; width: 100%; display: none; margin: 1 0 0 0; padding: 0 1;
        border: heavy $error; background: $error 25%; color: $text; text-style: bold;
    }
    AutolabScreen #autolab-crash-banner.shown { display: block; }
    AutolabScreen #autolab-progress-bar {
        width: 100%; height: 1; margin: 1 0 0 0; display: none;
    }
    AutolabScreen #autolab-progress-bar.shown { display: block; }
    AutolabScreen #autolab-status-panel {
        height: auto; width: 100%; border: solid $primary-darken-2; padding: 0 1;
        margin: 1 0 0 0; color: $text;
    }
    """

    def __init__(self) -> None:
        super().__init__()
        self._steps: "list[dict]" = []
        self._row_keys: "list" = []
        self._lw_row_keys: "list" = []
        self._proto_text: str = ""
        self._log_lines: "list[str]" = []
        # Run-control state: the live run id (pause/resume/abort target) + its
        # start time, both set while a physical run is in flight.
        self._active_run_id: "str | None" = None
        self._run_started: "float | None" = None
        self._run_progress_text: str = ""
        # Live-telemetry tracking: the analysed command total (progress-bar
        # denominator), last-seen run status + fault set (so the log records only
        # transitions, not a full snapshot every poll tick), and the idle
        # connection-ping guard.
        self._analysis_total: "int | None" = None
        self._last_run_status: "str | None" = None
        self._last_faults: "set[str]" = set()
        self._ping_inflight: bool = False
        self._conn_timer = None
        # Identity-linking: which deck slot is bound to a library collection.
        self._bound_slot: "int | None" = None
        # Deck: slot -> {"kind":"tips"|"labware", "labware":alias|customname,
        #                "definition"?:dict, "id"?:nickname}.
        self._deck: "dict[int, dict]" = {
            8: {"kind": "tips", "labware": "tiprack_300"},
            1: {"kind": "labware", "labware": "eppi_24", "id": "src"},
            2: {"kind": "labware", "labware": "plate_24", "id": "dst"}}
        try:
            self._host0 = _get_setting("ot2_host", "") or ""
        except Exception:
            self._host0 = ""
        try:
            self._autoconnect0 = bool(_get_setting("ot2_autoconnect", False))
        except Exception:
            self._autoconnect0 = False
        # Guard so a double-click can't launch two concurrent robot scans.
        self._discover_inflight = False

    def compose(self) -> ComposeResult:
        yield Header()
        with _MenuBarScroll(id="menubar-scroll"):
            yield MenuBar(id="menubar")
        pip_opts = [(m, m) for m in sorted(_ot2._OT2_PIPETTES)]
        with TabbedContent(initial="autolab-tab-deck", id="autolab-tabs"):
            # ── Deck: interactive deck map + the loaded protocol's steps + run ──
            with TabPane("Deck", id="autolab-tab-deck"):
                with VerticalScroll(id="autolab-deck-pane"):
                    with Horizontal(classes="autolab-row"):
                        yield Static("Host", classes="autolab-label")
                        yield Input(value=self._host0,
                                    placeholder="192.168.1.56   or   opentrons.local",
                                    id="autolab-host")
                        yield Button("Status", id="autolab-status",
                                     tooltip="Query the robot's live state — pipette, "
                                             "calibration, sensors, and any faults")
                        yield Static("○ not checked", id="autolab-conn", markup=True)
                    with Horizontal(classes="autolab-row"):
                        yield Button("Find Robots", id="autolab-discover",
                                     variant="primary",
                                     tooltip="Scan the network (and USB) for OT-2 "
                                             "robots you can connect to")
                        yield Checkbox("Auto-connect to first",
                                       value=self._autoconnect0, id="autolab-autoconnect")
                    with Horizontal(classes="autolab-row"):
                        yield Button("Lights On", id="autolab-lights-on",
                                     tooltip="Turn the robot's rail lights on")
                        yield Button("Lights Off", id="autolab-lights-off",
                                     tooltip="Turn the robot's rail lights off")
                        yield Button("Disengage Motors", id="autolab-disengage",
                                     tooltip="Release the gantry motors so it can be moved "
                                             "by hand — idle only, refused during a run")
                    yield Static("Protocol library", classes="autolab-hdr")
                    with Horizontal(classes="autolab-row"):
                        yield Static("Name", classes="autolab-label")
                        yield Input(placeholder="my protocol", id="autolab-proto-name",
                                    classes="autolab-text")
                        yield Static("Collection", classes="autolab-label")
                        yield Input(value="Default", id="autolab-proto-coll",
                                    classes="autolab-text")
                        yield Button("Save", id="autolab-proto-save", variant="primary",
                                     tooltip="Save the current design as a named protocol")
                    with Horizontal(classes="autolab-row"):
                        yield Static("Load", classes="autolab-label")
                        yield Select([], id="autolab-proto-pick", allow_blank=True,
                                     prompt="(saved protocols)")
                        yield Button("Load", id="autolab-proto-load",
                                     tooltip="Load the selected protocol into the designer")
                        yield Button("Rename", id="autolab-proto-rename",
                                     tooltip="Rename the selected protocol")
                        yield Button("Move", id="autolab-proto-move",
                                     tooltip="Move the selected protocol to the Collection above")
                        yield Button("Delete", id="autolab-proto-delete",
                                     tooltip="Delete the selected protocol")
                    yield Static("Deck  (click a bay to set or clear its labware)",
                                 classes="autolab-hdr")
                    yield OT2DeckMap(on_bay=self._open_slot_picker, id="autolab-deck-map")
                    yield Static("Steps", classes="autolab-hdr")
                    yield Static("", id="autolab-steplist", markup=True)
                    with Horizontal(classes="autolab-row"):
                        yield Button("Compile", id="autolab-compile",
                                     tooltip="Compile into an Opentrons protocol (offline)")
                        yield Button("Analyze (simulate)", id="autolab-analyze",
                                     tooltip="Upload to the robot and run its built-in "
                                             "simulate — validates the deck, no motion")
                        yield Checkbox("Arm — allow physical motion", id="autolab-arm")
                        yield Button("Run", id="autolab-run", variant="warning",
                                     tooltip="Run on the OT-2 — requires Arm, a clean "
                                             "analysis, and a fault-free robot")
                    with Horizontal(classes="autolab-row"):
                        yield Button("Pause", id="autolab-pause",
                                     tooltip="Hold the running protocol — Resume to continue")
                        yield Button("Resume", id="autolab-resume",
                                     tooltip="Resume a paused run")
                        yield Button("Abort", id="autolab-abort", variant="error",
                                     tooltip="Stop the current run immediately")
                    yield Static("", id="autolab-crash-banner", markup=True)
                    yield ProgressBar(id="autolab-progress-bar", total=None,
                                      show_eta=True, show_percentage=True)
                    yield Static("", id="autolab-run-progress", markup=True)
                    yield Static("", id="autolab-status-panel", markup=True)
                    with VerticalScroll(id="autolab-log"):
                        yield Static("", id="autolab-log-body", markup=True)
                    yield Static("Compiled protocol", classes="autolab-hdr")
                    yield TextArea("", id="autolab-proto")
            # ── Designer: pipette + the step builder ──
            with TabPane("Designer", id="autolab-tab-design"):
                with VerticalScroll(id="autolab-design"):
                    with Horizontal(classes="autolab-row"):
                        yield Static("Pipette", classes="autolab-label")
                        yield Select(pip_opts, value="p300_single",
                                     id="autolab-pipette", allow_blank=False)
                        yield Static("Mount", classes="autolab-label")
                        yield Select([("left", "left"), ("right", "right")], value="left",
                                     id="autolab-mount", allow_blank=False)
                        yield Static("New tip", classes="autolab-label")
                        yield Select([("always", "always"), ("once", "once"),
                                      ("never", "never")], value="always",
                                     id="autolab-newtip", allow_blank=False)
                    yield Static("Steps  (well 'A1' uses src/dst; 'nick:A1' targets "
                                 "any slot's labware by its nickname)", classes="autolab-hdr")
                    with Horizontal(classes="autolab-row"):
                        yield Static("Step", classes="autolab-label")
                        yield Select([("Transfer", "transfer"), ("Distribute", "distribute"),
                                      ("Consolidate", "consolidate"), ("Mix", "mix"),
                                      ("Delay", "delay"), ("Pause", "pause"),
                                      ("Comment", "comment")],
                                     value="transfer", id="autolab-step-type", allow_blank=False)
                        yield Static("New tip", classes="autolab-label",
                                     id="autolab-sf-newtip-label")
                        yield Select([("always", "always"), ("once", "once"),
                                      ("never", "never")], value="always",
                                     id="autolab-step-newtip", allow_blank=False)
                    with Horizontal(classes="autolab-row"):
                        yield Static("From", classes="autolab-label", id="autolab-sf-from-label")
                        yield Input(placeholder="A1", id="autolab-step-from", classes="autolab-ref")
                        yield Static("To", classes="autolab-label", id="autolab-sf-to-label")
                        yield Input(placeholder="A1", id="autolab-step-to", classes="autolab-ref")
                        yield Static("uL", classes="autolab-label", id="autolab-sf-vol-label")
                        yield Input(placeholder="50", id="autolab-step-vol", classes="autolab-vol")
                        yield Static("Reps", classes="autolab-label", id="autolab-sf-reps-label")
                        yield Input(placeholder="3", id="autolab-step-reps", classes="autolab-slot")
                        yield Static("Secs", classes="autolab-label", id="autolab-sf-secs-label")
                        yield Input(placeholder="30", id="autolab-step-secs", classes="autolab-slot")
                        yield Static("Text", classes="autolab-label", id="autolab-sf-text-label")
                        yield Input(placeholder="note / message", id="autolab-step-text",
                                    classes="autolab-text")
                    with Horizontal(classes="autolab-row"):
                        yield Button("Add step", id="autolab-add", variant="primary",
                                     tooltip="Add this step to the protocol sequence")
                        yield Button("Remove last", id="autolab-remove",
                                     tooltip="Remove the last step")
                        yield Button("Clear", id="autolab-clear",
                                     tooltip="Remove all steps")
                    yield DataTable(id="autolab-table", zebra_stripes=True)
            # ── Labware: custom labware library + a grid-based designer ──
            with TabPane("Labware", id="autolab-tab-labware"):
                with VerticalScroll(id="autolab-labware"):
                    yield Static("Custom labware library", classes="autolab-hdr")
                    yield DataTable(id="autolab-lw-table", zebra_stripes=True)
                    with Horizontal(classes="autolab-row"):
                        yield Button("Delete selected", id="autolab-lw-delete",
                                     tooltip="Remove the selected custom labware from the library")
                    yield Static("New custom labware  (regular grid)", classes="autolab-hdr")
                    with Horizontal(classes="autolab-row"):
                        yield Static("Name", classes="autolab-label")
                        yield Input(placeholder="My 24-tube rack", id="autolab-lw-name",
                                    classes="autolab-text")
