def _is_group_entry(entry: "dict | None") -> bool:
    """True iff `entry` is a group-style feature library entry —
    i.e. carries `is_group=True` AND a non-empty `members` list.
    Legacy single-feature entries return False (the absence of
    either field is the back-compat signal). Defensive against
    malformed `is_group=True` entries with no members (treats them
    as legacy, NOT as zero-member groups, so the annotate path
    can't silently drop the feature)."""
    if not isinstance(entry, dict):
        return False
    if not entry.get("is_group"):
        return False
    members = entry.get("members")
    return isinstance(members, list) and len(members) > 0


