def _operon_manual_fix_options(seq: str, pos: int, length: int,
                               forbidden: "dict[str, str]") -> "list[dict]":
    """Valid SINGLE-base substitutions that destroy the forbidden recognition at
    ``[pos, pos+length)`` WITHOUT spawning a new forbidden site — the choices
    offered to the user for manually curing a NON-coding site (marking the base
    outside any CDS). Each option is ``{pos, frm, to, label}`` (absolute pos).
    Empty when no single change clears it (the user must pick a different
    operon region)."""
    n = len(seq)
    before = set(_gb_find_forbidden_hits(seq, sites=forbidden))

    def _covers(h: "tuple[str, str, int]") -> bool:   # hit overlaps the site
        hs, hl = h[2], len(h[1])
        return hs < pos + length and hs + hl > pos

    opts: list[dict] = []
    for i in range(length):
        gp = pos + i
        if not (0 <= gp < n):
            continue
        cur = seq[gp]
        for b in "ACGT":
            if b == cur:
                continue
            test = seq[:gp] + b + seq[gp + 1:]
            after = set(_gb_find_forbidden_hits(test, sites=forbidden))
            if any(_covers(h) for h in after):       # this site survived
                continue
            if after - before:                       # spawned a NEW site
                continue
            opts.append({"pos": gp, "frm": cur, "to": b,
                         "label": f"+{gp + 1}: {cur}→{b}"})
    return opts


def _forbidden_sites_label() -> str:
    """Button label showing how many enzyme sites are currently forbidden."""
    names = _get_setting("codon_forbidden_enzymes", ["BsaI"])
    n = len(names) if isinstance(names, list) else 0
    return f"Avoid sites ({n})"


def _open_forbidden_sites_picker(screen, button_id: str) -> None:
    """Open `ForbiddenSitesModal` from `screen`, persist the chosen enzyme
    list to the shared `codon_forbidden_enzymes` setting, and relabel
    `button_id` with the new count. Shared by the Mutagenize + Synthesis
    'Avoid sites' buttons (both surfaces optimize against the same set)."""
    current = _get_setting("codon_forbidden_enzymes", ["BsaI"])
    if not isinstance(current, list):
        current = ["BsaI"]

    def _picked(names: "list | None") -> None:
        if names is None:
            return
        _set_setting("codon_forbidden_enzymes", [str(n) for n in names])
        label = _forbidden_sites_label()
        # [staleguard] Relabel EVERY 'Avoid sites' button on this screen, not
        # just the one that opened the picker — MutagenizeModal mounts both the
        # Optimize (#btn-mut-forbidden) and Scrub (#btn-scrub-enzymes) tabs at
        # once (Synthesis has #btn-syn-forbidden), all showing the same shared
        # count, so a change from one tab must update the siblings too.
        for _bid in (button_id, "#btn-mut-forbidden", "#btn-scrub-enzymes",
                     "#btn-syn-forbidden"):
            try:
                screen.query_one(_bid, Button).label = label
            except NoMatches:
                pass

    screen.app.push_screen(ForbiddenSitesModal(list(current)), callback=_picked)


# Common cloning enzymes for the RE-site dropdown in the cloning primer panel.
# Sorted alphabetically; each tuple is (display_label, enzyme_name).
# Curated cut-site enzymes for the cloning pickers — a workhorse subset of the
# NEB catalog. A few Type IIS (BsaI/BsmBI/BbsI/SapI) are included for VISIBILITY
# (the picker marks them n/a; the add-cut-sites clone flow refuses them).
_CLONING_RE_NAMES: "frozenset[str]" = frozenset({
    "EcoRI", "BamHI", "XhoI", "NdeI", "NcoI", "XbaI", "SpeI", "PstI",
    "HindIII", "SalI", "NotI", "BglII", "KpnI", "SacI", "NheI", "BsaI",
    "BsmBI", "BbsI", "SapI", "AgeI", "EcoRV", "ClaI", "MfeI", "MluI",
    "NruI", "SphI", "SfiI", "AvrII", "BsiWI", "BsrGI", "BstBI",
})
# Suggestion priority — common cloning workhorses first; blunt cutters (EcoRV /
# NruI) and rarer sites last; Type IIS NEVER suggested (can't place via the
# add-cut-sites model). `_suggest_cloning_pair` walks this order.
_CLONING_RE_PRIORITY: "list[str]" = [
    "EcoRI", "HindIII", "BamHI", "XhoI", "SalI", "NotI", "KpnI", "SacI",
    "NheI", "SpeI", "XbaI", "PstI", "BglII", "NcoI", "NdeI", "SphI", "MfeI",
    "MluI", "AvrII", "AgeI", "BsiWI", "BsrGI", "BstBI", "ClaI", "SfiI",
    "EcoRV", "NruI",
]
_CLONING_RE_OPTIONS: list[tuple[str, str]] = sorted(
    [(f"{name}  ({_NEB_ENZYMES[name][0]})", name) for name in _CLONING_RE_NAMES],
    key=lambda t: t[0],
)


def _cloning_re_options() -> "list[tuple[str, str]]":
    """Picker options for the traditional-cloning enzyme select: the curated
    common-cloning subset (`_CLONING_RE_OPTIONS`) followed by any user-added
    custom enzymes, so a custom enzyme is selectable for cloning — not just the
    NEB built-ins. Computed live (not the module const) so enzymes added this
    session appear; the cloning sim already resolves names via `_all_enzymes()`."""
    opts = list(_CLONING_RE_OPTIONS)
    customs = sorted(
        (name, ent[0]) for name, ent in _all_enzymes().items()
        if name not in _NEB_ENZYMES and ent and ent[0]
    )
    opts.extend((f"{name}  ({site})", name) for name, site in customs)
    return opts


def _enzyme_in_region(name: str, insert_seq: str) -> bool:
    """True when ``name``'s recognition site (forward OR reverse-complement)
    occurs INSIDE ``insert_seq`` — cloning with it would cut the amplicon
    internally and the clone dies at the bench. Mirrors the backstop refusal in
    `_clone_region_build`, shared so the picker can mark the same enzymes."""
    ent = _all_enzymes().get(name)
    if not ent or not ent[0]:
        return False
    site = ent[0].upper()
    seq = (insert_seq or "").upper()
    if not seq:
        return False
    if _iupac_pattern(site).search(seq):
        return True
    rc = _rc(site)
    return rc != site and bool(_iupac_pattern(rc).search(seq))


def _vector_has_site(vector_seq: str, name: str) -> bool:
    """True when ``name`` cuts the CIRCULAR ``vector_seq`` at least once (site
    forward OR RC, origin-spanning aware). Used to flag enzymes a chosen
    destination vector can't be opened with."""
    ent = _all_enzymes().get(name)
    if not ent or not ent[0]:
        return False
    site = ent[0].upper()
    seq = (vector_seq or "").upper()
    if not seq:
        return False
    window = seq + seq[:max(0, len(site) - 1)]   # circular wrap
    if _iupac_pattern(site).search(window):
        return True
    rc = _rc(site)
    return rc != site and bool(_iupac_pattern(rc).search(window))


def _classify_cloning_enzymes(insert_seq: str) -> "dict[str, str]":
    """Classify each curated cloning enzyme for ``insert_seq``:
    ``"type_iis"`` (cuts outside its site — unusable by add-cut-sites cloning),
    ``"in_insert"`` (site is inside the region — would self-cut the amplicon),
    or ``"safe"``."""
    out: "dict[str, str]" = {}
    for name in _CLONING_RE_NAMES:
        if _enzyme_is_type_iis(name):
            out[name] = "type_iis"
        elif _enzyme_in_region(name, insert_seq):
            out[name] = "in_insert"
        else:
            out[name] = "safe"
    return out


def _suggest_cloning_pair(insert_seq: str,
                          vector_seq: "str | None" = None,
                          ) -> "tuple[str, str] | None":
    """Suggest a viable ``(enz5, enz3)`` pair for cloning ``insert_seq``:
    insert-safe (not Type IIS, site not in the region) and — when ``vector_seq``
    is given — a pair that cuts the circular vector into EXACTLY 2 fragments
    (the Constructor's own backbone requirement, checked via the same
    `_excise_fragment_pair`). Prefers a DIRECTIONAL pair (distinct enzymes) in
    workhorse-priority order; falls back to the same enzyme at both ends
    (non-directional); ``None`` when nothing is viable."""
    cls = _classify_cloning_enzymes(insert_seq)
    safe = [n for n in _CLONING_RE_PRIORITY if cls.get(n) == "safe"]
    if not safe:
        return None
    vseq = (vector_seq or "").upper()
    if vseq:
        # Restrict to enzymes that actually cut the vector — ONE scan each
        # (not per pair), so the pair loop below is bounded even on a vector cut
        # by many enzymes, and a 2-fragment digest can't sneak through from one
        # enzyme cutting twice while the other is absent.
        safe = [n for n in safe if _vector_has_site(vseq, n)]
        if not safe:
            return None

    def _pair_ok(e5: str, e3: str) -> bool:
        if not vseq:
            return True
        names = [e5] if e5 == e3 else [e5, e3]
        try:
            frags, err = _excise_fragment_pair(
                vseq, names, circular=True, features=[], source_label="")
        except Exception:
            return False
        return err is None and len(frags) == 2

    for i, e5 in enumerate(safe):              # 1) directional, priority order
        for e3 in safe[i + 1:]:
            if _pair_ok(e5, e3):
                return (e5, e3)
    for e in safe:                              # 2) non-directional fallback
        if _pair_ok(e, e):
            return (e, e)
    return None


def _cloning_enzyme_options(insert_seq: str,
                            vector_seq: "str | None" = None,
                            ) -> "list[tuple[str, str]]":
    """Annotated ``(label, value)`` options for the cut-site Selects: each
    curated enzyme tagged ``✗ cuts inside selection`` / ``(Type IIS — n/a)`` /
    ``⚠ not in vector`` (when a vector is given), else plain. Usable enzymes
    sort first (workhorse-priority order), unusable ones after."""
    cls = _classify_cloning_enzymes(insert_seq)
    vseq = (vector_seq or "").upper()
    rank = {n: i for i, n in enumerate(_CLONING_RE_PRIORITY)}
    rows: list = []
    for name in _CLONING_RE_NAMES:
        site = _NEB_ENZYMES[name][0]
        kind = cls.get(name, "safe")
        if kind == "type_iis":
            tag, ok = "  (Type IIS — n/a)", 2
        elif kind == "in_insert":
            tag, ok = "  ✗ cuts inside selection", 2
        elif vseq and not _vector_has_site(vseq, name):
            tag, ok = "  ⚠ not in vector", 1
        else:
            tag, ok = "", 0
        rows.append((ok, rank.get(name, 999), name, f"{name}  ({site}){tag}"))
    rows.sort(key=lambda r: (r[0], r[1], r[2]))
    return [(label, name) for _ok, _rk, name, label in rows]


# ── SOE-PCR mutagenesis primer design ──────────────────────────────────────────
#
# Ported from superfolder_chromo/mutagenesis_primers.py. Designs a 4-primer /
# 3-reaction SOE (Splicing by Overlap Extension) workflow to introduce a
# single-residue point mutation into a CDS and produce a Golden Braid
# B3-B5-compatible amplicon in one pot.
#
# OUTER primers (constant per CDS):
#   FWD:  CCCC-GGTCTC-A-AATG-[CDS body from codon 2] → B3 overhang AATG
#   REV:  CCCC-GGTCTC-A-AACG-[revcomp of CDS end]    → B5 overhang CGTT
# INNER primers (one pair per mutation): mutant codon centered in anneal region,
# REV = revcomp(FWD). Edge cases (mutation < 60 nt from either CDS end) swap the
# inner pair for a single "modified outer" primer and a 2-primer direct PCR.
#
# Codon table is E. coli K12 (Kazusa taxid 83333). This is a single-organism
# convenience; callers designing for other hosts should review mut_codon choice.

_MUT_PREVIEW_DNA_COLOR = "color(118)"   # CDS-green, main-app-like
_MUT_PREVIEW_AA_COLOR  = "color(141)"   # purple (AA-only mode)


def _mut_next_cursor(current: int, protein_len: int, line_width: int,
                     dna_mode: bool, direction: str) -> int:
    """Compute the next cursor position given an arrow-key direction.

    * `current` — current cursor AA index; -1 means no cursor yet.
    * `direction` ∈ {"left", "right", "up", "down"}.
    * Up/Down step by one row's worth of amino acids (`line_width // 3`
      in DNA mode, `line_width` in AA-only mode).
    * Result is clamped to `[0, protein_len)`. -1 is returned for empty
      proteins. First press after no-cursor snaps to index 0 regardless
      of direction so arrow keys "wake up" the cursor intuitively.
    """
    if protein_len <= 0:
        return -1
    if current < 0:
        return 0
    step = max(1, (line_width // 3) if dna_mode else line_width)
    if   direction == "left":  new_idx = current - 1
    elif direction == "right": new_idx = current + 1
    elif direction == "up":    new_idx = current - step
    elif direction == "down":  new_idx = current + step
    else:                      return current
    return max(0, min(protein_len - 1, new_idx))


# ── Feature picker: pick one feature from a chosen plasmid ────────────────────



# ── Add-feature modal ──────────────────────────────────────────────────────────

class AddFeatureModal(ModalScreen):
    """Create or edit a feature-library entry.

    The modal collects: name, feature_type (from `_GENBANK_FEATURE_TYPES`),
    strand, 5'→3' sequence, and a qualifier line (``key=value; key=value``).
    Three terminal actions:

      * **Save to Library** — dismisses with ``{"action": "save", "entry": {...}}``.
      * **Insert at cursor** — dismisses with ``{"action": "insert", "entry": {...}}``.
      * **Cancel** — dismisses with ``None``.

    An **Import from plasmid** button opens the PlasmidPickerModal
    → PlasmidFeaturePickerModal chain and prefills the form.

    Validation (non-empty name, ACGT/IUPAC-only sequence, known feature type)
    lives on the app side; the modal just surfaces the error strings.
    """

    _blocks_undo: bool = True   # sweep #10: Save / Insert mutates record

    BINDINGS = [
        Binding("escape", "cancel",     "Cancel"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    # Class-level "sticky" picks for the category-style form fields
    # (type / strand / color). Populated on every dismiss so the
    # NEXT instance of the modal (no explicit prefill) inherits the
    # user's previous picks rather than reverting to the cold
    # defaults (CDS / Forward / Auto). User-reported 2026-05-26:
    # "make the user added choices persistent so when going back to
    # the modal it doesnt reset to default". Per-feature fields
    # (name, sequence, qualifiers, description) are intentionally
    # NOT sticky — they vary per feature and the user expects a
    # fresh form for those.
    _LAST_USER_PICKS: "dict" = {}

    def __init__(
        self,
        prefill: "dict | None" = None,
        selection_range: "tuple[int, int] | None" = None,
        *,
        total_len: "int | None" = None,
    ) -> None:
        super().__init__()
        # Explicit `prefill` (Import-from-plasmid, programmatic
        # callers like the parts-bin "Add as new" path) wins — the
        # caller asked for specific values to land in the form, so
        # the sticky picks must NOT override them. Only the
        # no-prefill path (the bare "New feature" action) inherits
        # the previous session's picks.
        if prefill:
            self._prefill = dict(prefill)
        else:
            # Read the class-level sticky dict defensively — a future
            # change (or a test that monkey-patches it) could plant
            # values that don't fit the form. Validate per key so a
            # bad strand can't pre-check no radio and a bad type
            # can't trip the Select's allow_blank=False contract.
            sticky = self.__class__._LAST_USER_PICKS or {}
            self._prefill = {}
            ft = sticky.get("feature_type")
            if isinstance(ft, str) and ft.strip():
                self._prefill["feature_type"] = ft.strip()
            st = sticky.get("strand")
            if isinstance(st, int) and st in (-1, 0, 1, 2):
                self._prefill["strand"] = st
            sc_col = sticky.get("color")
            if isinstance(sc_col, str) and sc_col.strip():
                self._prefill["color"] = sc_col.strip()
        # `selection_range` is the seq-panel highlight at the moment
        # the modal opened, captured so the "Insert feature" action
        # always knows the user-intended span even if the seq panel's
        # selection is later cleared. `None` → no selection; the
        # button is disabled. (start, end) is half-open; `end < start`
        # marks an origin-spanning wrap that becomes a CompoundLocation
        # at insert time.
        self._selection_range = selection_range
        # `total_len` lets callers running outside the main app (e.g.
        # SynthesisScreen, which doesn't host `#seq-panel`) supply the
        # length used by the CDS divisibility check. None falls back
        # to the live `#seq-panel` query — the original behaviour for
        # the on-canvas add-feature (Alt+Shift+F) path.
        self._total_len = total_len
        # Current color override for this entry. None = Auto (type default).
        self._color: "str | None" = self._prefill.get("color") or None
        # [INV-50] dismiss-once guard: rapid Save/Insert/Cancel
        # clicks can fire the handler twice before the modal
        # finishes tearing down, which would re-dispatch the
        # entry on the app side. The flag short-circuits any
        # post-first dismiss. See `docs/invariants.md` [INV-50].
        self._dismissed: bool = False
        # Sweep #30: unified members state. The modal always works
        # in terms of a members list (1 row = solo, 2+ row = group)
        # so the save path can build either shape via the shared
        # `_entry_from_members` helper. The form fields above the
        # table bind to whichever row is currently selected; on
        # mount we seed from the prefill (group entries inherit
        # `members` verbatim; solo entries get a synthesized 1-row
        # list via `_solo_row_from_entry`).
        if self._prefill.get("is_group") and isinstance(
            self._prefill.get("members"), list,
        ) and self._prefill["members"]:
            try:
                seq_for_len = (
                    self._prefill.get("sequence") or ""
                ).strip()
                self._members = list(_validate_group_members(
                    [dict(m) for m in self._prefill["members"]],
                    len(seq_for_len) or 1,
                ))
            except ValueError:
                # Malformed prefill members → fall back to a
                # 1-row solo synthesised from the entry's top-
                # level fields. Better than crashing the modal.
                self._members = [_solo_row_from_entry(self._prefill)]
        else:
            self._members = [_solo_row_from_entry(self._prefill)]
        self._selected_idx: int = 0
        # Re-entrancy guard: when we programmatically poke a form
        # field to mirror the selected row, the field's `.Changed`
        # message fires and tries to write back into the row. The
        # flag short-circuits that round-trip so the user-visible
        # state doesn't oscillate.
        self._syncing_form: bool = False
        # Sweep #32 (2026-05-26): set of `id(member_dict)` values
        # for rows the user has marked via the col-0 toggle. See
        # `FeatureEditModal.__init__` for the rationale + lifecycle.
        self._marked_ids: "set[int]" = set()

    def compose(self) -> ComposeResult:
        p = self._prefill
        name        = p.get("name", "")
        feat_type   = p.get("feature_type", "CDS")
        sequence    = p.get("sequence", "")
        strand      = p.get("strand", 1)
        quals_str   = _qualifiers_to_string(p.get("qualifiers") or {})
        description = p.get("description", "")

        type_options = [(t, t) for t in _GENBANK_FEATURE_TYPES]
        if feat_type not in _GENBANK_FEATURE_TYPES:
            type_options.insert(0, (f"{feat_type} (non-standard)", feat_type))

        with Vertical(id="addfeat-dlg"):
            yield Static(" Add Feature ", id="addfeat-title")
            with ScrollableContainer(id="addfeat-body"):
                yield Label("Name:")
                yield Input(value=name, placeholder="e.g. lacZ-alpha",
                            id="addfeat-name")

                with Horizontal(id="addfeat-row1"):
                    with Vertical(id="addfeat-type-col"):
                        yield Label("Feature type:")
                        yield Select(type_options, value=feat_type,
                                     id="addfeat-type", allow_blank=False)
                    with Vertical(id="addfeat-strand-col"):
                        yield Label("Orientation:")
                        with RadioSet(id="addfeat-strand"):
                            yield RadioButton("▶ Top (forward)",
                                              value=(strand == 1),
                                              id="addfeat-strand-fwd")
                            yield RadioButton("◀ Bottom (reverse)",
                                              value=(strand == -1),
                                              id="addfeat-strand-rev")
                            yield RadioButton("▒ None (arrowless)",
                                              value=(strand == 0),
                                              id="addfeat-strand-none")
                            yield RadioButton("↔ Both strands",
                                              value=(strand == 2),
                                              id="addfeat-strand-both")

                with Horizontal(id="addfeat-color-row"):
                    yield Label("Color:", id="addfeat-color-label")
                    yield Static("", id="addfeat-color-swatch", markup=True)
                    yield Button("Pick Color", id="btn-addfeat-color")
                    yield Button("Auto",        id="btn-addfeat-color-clear")

                yield Label("Sequence  (5'→3', ACGT/IUPAC; whitespace ignored):")
                yield TextArea(sequence, id="addfeat-seq")
                # Sweep #30: unified members table replaces the
                # sweep #29 toggle + textarea. Every feature is
                # internally a list of N ≥ 1 sub-features
                # (members); a 1-row table = solo entry, 2+ row
                # table = group entry. The top-level Type / Strand
                # / Color fields above EDIT THE SELECTED ROW —
                # when the user clicks a different row, the form
                # fields repopulate from that row. Split / Merge
                # / Add / Remove buttons act on the table.
                yield Label("Members  (split/merge into sub-features):")
                tbl = _SingleClickDataTable(
                    id="addfeat-members-tbl",
                    # Sweep #30 (2026-05-26): `cursor_type="cell"`
                    # gives cell-level click + selection events.
                    # `_SingleClickDataTable` (subclass) fires
                    # `CellSelected` on the FIRST click instead
                    # of requiring two clicks — the per-row
                    # color / label / strand pickers open
                    # immediately on single-click.
                    cursor_type="cell", zebra_stripes=True,
                )
                tbl.add_columns(
                    "#", "start", "end", "type", "label", "color",
                    "strand",
                )
                yield tbl
                with Horizontal(id="addfeat-members-btns"):
                    yield Button(
                        "+ Add row", id="btn-addfeat-add-row",
                        tooltip=(
                            "Append a new sub-feature row covering "
                            "the tail of the sequence."
                        ),
                    )
                    yield Button(
                        "Split", id="btn-addfeat-split-row",
                        tooltip=(
                            "Split the selected row at a position "
                            "you specify (default: midpoint)."
                        ),
                    )
                    yield Button(
                        "Merge", id="btn-addfeat-merge-rows",
                        disabled=True,
                        tooltip=(
                            "Merge rows. Click col-0 (■/□) on the "
                            "rows you want, then Merge folds them "
                            "in order. With no marks, falls back "
                            "to merging the selected row with the "
                            "next one below."
                        ),
                    )
                    yield Button(
                        "- Remove", id="btn-addfeat-remove-row",
                        disabled=True,
                        tooltip=(
                            "Remove the selected row (disabled "
                            "when only one row remains)."
                        ),
                    )
                # Sweep #30: per-row label input. Visible only when
                # the table has 2+ rows — for solo (1 row), the
                # row's label IS the entry's Name (auto-synced),
                # so a separate input would duplicate the Name
                # field. When the user splits / adds rows, this
                # input lets them label each sub-feature.
                yield Label(
                    "Selected row label:", id="addfeat-row-label-lbl",
                )
                yield Input(
                    "", placeholder="(per-row label for groups)",
                    id="addfeat-row-label",
                )
                yield Label("Qualifiers  (e.g.  gene=lacZ; product=LacZ alpha):")
                yield Input(value=quals_str,
                            placeholder="key=value; key=value",
                            id="addfeat-quals")
                yield Label("Description  (optional):")
                yield Input(value=description, placeholder="free text",
                            id="addfeat-desc")
            yield Static("", id="addfeat-status", markup=True)
            with Horizontal(id="addfeat-btns"):
                yield Button("Import from plasmid",
                             id="btn-addfeat-import")
                yield Button("Save to Library",
                             id="btn-addfeat-save",
                             variant="primary")
                # "Insert feature" annotates the highlighted selection
                # range with a new SeqFeature — does NOT splice new
                # bases. Disabled when there's no selection (the
                # button needs a span to act on).
                yield Button("Insert feature",
                             id="btn-addfeat-insert",
                             variant="success",
                             disabled=self._selection_range is None,
                             tooltip=(
                                 "Annotate the highlighted region "
                                 "with this feature (no DNA inserted)."
                                 if self._selection_range is not None
                                 else "Highlight a region in the seq panel "
                                      "first to enable."
                             ))
                yield Button("Cancel", id="btn-addfeat-cancel")

    def on_mount(self) -> None:
        try:
            self.query_one("#addfeat-name", Input).focus()
        except NoMatches:
            pass
        self._refresh_color_swatch()
        # Sweep #30: populate the members table from the seeded
        # `_members` list. Load row 0 into the form (Type / Strand
        # / Color all reflect the selected row from now on).
        self._refresh_table()
        # If the seeded row is the auto-built solo row from an
        # empty-sequence prefill (rs=0, re=0), the form fields
        # were already populated by compose() from the prefill
        # itself — `_load_row_into_form(0)` would just re-write
        # them with the same values. Still safe + idempotent.
        if self._members:
            self._load_row_into_form(self._selected_idx)

    # ── Helpers ──────────────────────────────────────────────────────────────

    def _current_feature_type(self) -> str:
        """Read the feature-type Select, falling back to the prefill's type
        (or 'misc_feature') if the Select isn't mounted yet. Used so the
        ColorPicker knows which type's default color to show in the preview."""
        try:
            val = self.query_one("#addfeat-type", Select).value
            if isinstance(val, str) and val and val != Select.BLANK:
                return val
        except NoMatches:
            pass
        return self._prefill.get("feature_type", "misc_feature") or "misc_feature"

    def _refresh_color_swatch(self) -> None:
        """Repaint the color preview after _color changes. Always resolves
        through the same precedence chain used at render time, so Auto shows
        the effective default (not an empty box).

        Uses ``Text.append`` rather than markup-string interpolation so
        palette colors like ``color(39)`` render safely — Rich's Style
        parser accepts them, but its markup lexer chokes on the parens
        inside ``[color(39)]...[/]``.
        """
        try:
            swatch = self.query_one("#addfeat-color-swatch", Static)
        except NoMatches:
            return
        ftype = self._current_feature_type()
        synth = {"feature_type": ftype, "color": self._color}
        resolved = _resolve_feature_color(synth)
        t = Text()
        t.append("███ ", style=resolved)
        if self._color:
            t.append(resolved)
        else:
            t.append(f"Auto → {resolved}", style="dim")
        swatch.update(t)

    def _gather(self) -> "dict | None":
        """Read form → entry dict, or write a red error and return
        None. Sweep #30 path: the modal's truth is `self._members`
        (kept in sync with the form via row-binding handlers). On
        save we sync the current selected row one last time, then
        delegate the entry shape to `_entry_from_members`.

        Sweep #30 hardening: every free-text input is sanitised
        before it lands in the entry dict. Name → `_sanitize_label`
        (strips control chars, caps length). Description →
        `_sanitize_note` (same scrub, larger cap for free-form
        notes). Sequence → cap at `_MAX_FEATURE_SEQ_LEN`,
        whitespace-stripped + uppercased + alphabet-validated.
        Qualifiers → `_parse_qualifier_string` (existing
        sanitiser). All on the SAME critical path so a paste of
        terminal escapes / 1 GB sequence can't punch through to
        the library JSON / .gb export. Atomic save: the entry is
        ONLY returned after every validation passes; partial
        validation never leaks a half-built dict."""
        try:
            name_raw = self.query_one("#addfeat-name",  Input).value
            seqraw   = self.query_one("#addfeat-seq",   TextArea).text
            quals    = self.query_one("#addfeat-quals", Input).value
            desc_raw = self.query_one("#addfeat-desc",  Input).value
        except NoMatches:
            return None
        status = self.query_one("#addfeat-status", Static)
        # Sanitise name: control-char scrub + 200-char cap. Empty
        # after scrub → user pasted only control chars → reject.
        name = _sanitize_label(name_raw, max_len=200)
        if not name:
            status.update(
                "[red]Name cannot be empty (after stripping "
                "control characters).[/red]"
            )
            return None
        # Sanitise description: same control-char scrub, larger
        # 8 KB cap for free-form notes.
        desc = _sanitize_note(desc_raw)
        # Normalise + validate sequence with a hard cap before
        # the whitespace strip — a 1 GB paste shouldn't even
        # reach the comprehension below.
        if len(seqraw) > _MAX_FEATURE_SEQ_LEN * 2:
            # 2× cap for the raw-with-whitespace input — generous
            # since `_MAX_FEATURE_SEQ_LEN` already has slack.
            status.update(
                f"[red]Sequence input too long "
                f"({len(seqraw):,} chars > "
                f"{_MAX_FEATURE_SEQ_LEN * 2:,}) — paste a "
                f"smaller fragment.[/red]"
            )
            return None
        seq_clean = "".join(ch for ch in seqraw.upper() if not ch.isspace())
        if not seq_clean:
            status.update("[red]Sequence cannot be empty.[/red]")
            return None
        if len(seq_clean) > _MAX_FEATURE_SEQ_LEN:
            status.update(
                f"[red]Sequence too long ({len(seq_clean):,} bp "
                f"> {_MAX_FEATURE_SEQ_LEN:,}) — features past "
                f"this size belong in the plasmid library, not "
                f"the feature library.[/red]"
            )
            return None
        allowed = set("ACGTRYWSMKBDHVN")
        bad = [ch for ch in seq_clean if ch not in allowed]
        if bad:
            status.update(
                f"[red]Sequence has invalid bases: {''.join(sorted(set(bad)))[:10]}[/red]"
            )
            return None
        # Flush the form's current edit-state into the selected row
        # so the latest Type / Strand / Color change is captured
        # even if the user clicks Save without changing rows.
        self._save_form_into_row(self._selected_idx)
        # Auto-sync rs/re for the 1-row solo case before saving so
        # the user doesn't have to think about row coords.
        self._resync_solo_row_to_sequence(len(seq_clean))
        # Hand the entire entry construction to the shared helper
        # — it splits the solo / group branches, validates the
        # members list, and merges modal-level qualifiers /
        # description with row 0's on the solo path. Atomic: if
        # validator raises, no entry dict is returned (status line
        # surfaces the error instead).
        try:
            entry = _entry_from_members(
                name, seq_clean, self._members,
                qualifiers=_parse_qualifier_string(quals),
                description=desc,
            )
        except ValueError as exc:
            status.update(f"[red]Members: {exc}[/red]")
            return None
        return entry

    @staticmethod
    def _parse_group_members_text(
        text: str, sequence_len: int,
    ) -> "list[dict]":
        """Mirrors `SplitFeatureModal._save`'s parser: each non-
        blank, non-`#`-prefixed line is `<rs>-<re> <label>
        [<color>] [<strand>]`. Returns a validated members list
        (via `_validate_group_members`).

        Sweep #29 hardening: caps total text length + per-line
        length; strips control chars; raises `ValueError` on any
        unrecoverable shape error so the save path can surface
        the message via the modal's status line."""
        if not isinstance(text, str):
            return []
        if len(text) > 32_768:
            raise ValueError(
                f"members text too long ({len(text)} chars > "
                f"32 KB) — shorten the input"
            )
        raw_members: list[dict] = []
        for lineno, raw in enumerate(text.splitlines(), 1):
            cleaned = _CONTROL_CHARS_RE.sub("", raw)
            line = cleaned.strip()
            if not line or line.startswith("#"):
                continue
            if len(line) > 1024:
                raise ValueError(
                    f"line {lineno} too long "
                    f"({len(line)} chars > 1024)"
                )
            parts = line.split()
            if not parts or "-" not in parts[0]:
                raise ValueError(
                    f"line {lineno}: expected "
                    f"`<rel_start>-<rel_end>` first token"
                )
            try:
                rs_str, re_str = parts[0].split("-", 1)
                rs = int(rs_str)
                re_ = int(re_str)
            except ValueError:
                raise ValueError(
                    f"line {lineno}: rel coords must be ints"
                )
            if not (0 <= rs < re_ <= sequence_len):
                raise ValueError(
                    f"line {lineno}: range {rs}-{re_} not in "
                    f"[0, {sequence_len}]"
                )
            tail = parts[1:]
            label = tail[0] if len(tail) >= 1 else ""
            color = tail[1] if len(tail) >= 2 else ""
            strand_str = tail[2] if len(tail) >= 3 else "1"
            try:
                strand = int(strand_str)
            except ValueError:
                strand = 1
            if strand not in (-1, 0, 1, 2):
                strand = 1
            raw_members.append({
                "rel_start": rs,
                "rel_end":   re_,
                "feature_type": "misc_feature",
                "label":     label,
                "color":     color if color else None,
                "strand":    strand,
                "qualifiers": {},
                "description": "",
            })
        if not raw_members:
            # Empty / whitespace-only / comment-only text → return
            # empty list rather than handing the validator an empty
            # list (which raises). Caller (`_gather`) treats `[]` as
            # "no members supplied" and surfaces a friendlier error.
            return []
        # Final validation pass: applies the shared hardening
        # (control char scrub, length caps, member cap).
        return _validate_group_members(raw_members, sequence_len)

    # ── Buttons ──────────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-addfeat-save")
    def _save(self, _) -> None:
        entry = self._gather()
        if entry is None:
            return
        self.dismiss({"action": "save", "entry": entry})

    @on(Button.Pressed, "#btn-addfeat-insert")
    def _insert(self, _) -> None:
        """Annotate the captured selection range with this entry's
        feature definition. The button is disabled when there's no
        selection, so `_selection_range` is guaranteed non-None
        when we reach here — the assertion guards against a future
        refactor enabling the button without setting the range."""
        if self._selection_range is None:
            return
        entry = self._gather()
        if entry is None:
            return
        # CDS divisible-by-3 gate: the highlighted region's length must
        # be a whole number of codons or the resulting CDS would have
        # a partial codon at the end (silent translation bug). The
        # check uses the SELECTION SPAN, not the typed-sequence length
        # — agents and humans can edit the textarea, but the feature
        # is anchored to the bp range. Wrap-aware via `_feat_len`.
        if entry.get("feature_type") == "CDS":
            if self._total_len is not None:
                total = max(0, int(self._total_len))
            else:
                try:
                    sp = self.app.query_one("#seq-panel", SequencePanel)
                    total = len(sp._seq) if sp._seq else 0
                except (NoMatches, AttributeError):
                    total = 0
            s, e = self._selection_range
            span = _feat_len(s, e, total) if total else 0
            if span > 0 and span % 3 != 0:
                try:
                    self.query_one("#addfeat-status", Static).update(
                        f"[red]CDS must span a whole number of codons "
                        f"(highlighted {span} bp; need a multiple of 3). "
                        f"Adjust the selection or pick a different "
                        f"feature type.[/red]"
                    )
                except NoMatches:
                    pass
                return
        self.dismiss({
            "action": "annotate",
            "entry":  entry,
            "range":  self._selection_range,
        })

    @on(Button.Pressed, "#btn-addfeat-cancel")
    def _cancel_btn(self, _) -> None:
        self.dismiss(None)

    @on(Button.Pressed, "#btn-addfeat-color")
    def _open_color_picker(self, _) -> None:
        """Push ColorPickerModal; the dismiss payload updates self._color."""
        ftype = self._current_feature_type()

        def _on_color(result) -> None:
            if not isinstance(result, dict):
                return
            new_col = result.get("color")
            self._color = new_col if isinstance(new_col, str) and new_col else None
            if result.get("set_default") and isinstance(new_col, str) and new_col:
                defaults = _load_feature_colors()
                defaults[ftype] = new_col
                try:
                    _save_feature_colors(defaults)
                except (OSError, RuntimeError) as exc:
                    _notify_save_failure(self.app, "Feature colors", exc)
            self._refresh_color_swatch()
            # Sweep #30: write the new color into the currently-
            # selected row so the table cell repaints.
            self._save_form_into_row(self._selected_idx)

        self.app.push_screen(
            ColorPickerModal(ftype, _safe_color_for_picker(self._color)),
            callback=_on_color,
        )

    @on(Button.Pressed, "#btn-addfeat-color-clear")
    def _clear_color(self, _) -> None:
        self._color = None
        self._refresh_color_swatch()
        # Sweep #30: clearing colour writes None into the selected
        # row (Auto = no `color` qualifier on save).
        self._save_form_into_row(self._selected_idx)

    # ── Sweep #30: members table binding helpers ──────────────────

    def _refresh_table(self) -> None:
        """Repaint `#addfeat-members-tbl` from `self._members`.

        Defensive: silent no-op when the table isn't mounted yet
        (called from `on_mount` itself + every mutation path).
        Bounded by `_MAX_GROUP_MEMBERS` upstream; we never display
        more rows than the data layer accepts so a paste-attack
        can't blow the table widget.

        Sweep #30 bug-fix (2026-05-26): the table's `RowHighlighted`
        event fires transiently as the cursor passes over each
        added row during the clear-then-add-row loop. Without the
        sync guard, every transient event triggered
        `_save_form_into_row(old_idx)` + `_load_row_into_form(new_idx)`
        in a cascade — the user-reported "highlight goes
        absolutely nuts" symptom after split. Wrapping the rebuild
        in `_syncing_form = True` short-circuits the highlight
        handler for the duration of the rebuild.

        Sweep #30 (2026-05-26 second pass): also captures + restores
        the table's scroll position. `DataTable.clear()` snaps the
        scroll back to the top — user-reported "scrolling to the
        top on each row add". Capturing `scroll_y` before clear
        and re-scrolling after preserves the user's scroll context
        across every structural mutation."""
        try:
            tbl = self.query_one("#addfeat-members-tbl", DataTable)
        except NoMatches:
            return
        # Sweep #32: drop marks for rows that no longer exist.
        self._prune_marks()
        prev_scroll_y = float(getattr(tbl, "scroll_y", 0) or 0)
        self._syncing_form = True
        try:
            tbl.clear()
            for i, m in enumerate(self._members, 1):
                rs = int(m.get("rel_start", 0))
                re_ = int(m.get("rel_end", 0))
                ftype = str(m.get("feature_type") or "")[:24]
                label = str(m.get("label") or "")[:24]
                # 2026-05-26 bug-fix: `int(x or 1)` is wrong for
                # strand=0 (arrowless) — 0 is falsy so the `or 1`
                # silently coerces arrowless to forward. The
                # picker writes strand=0 and the table re-renders
                # it as "▶ top" — user reports "nothing happens"
                # when picking Arrowless. Use `int(x)` with a
                # None-only fallback to preserve 0.
                raw_strand = m.get("strand")
                try:
                    strand = (int(raw_strand)
                              if raw_strand is not None else 1)
                except (TypeError, ValueError):
                    strand = 1
                # Sweep #30 (2026-05-26): expand the strand cell
                # to make top/bottom legible at-a-glance rather
                # than just the numeric ±1. Arrowhead glyph keeps
                # the visual identity from the canvas + the
                # `top` / `bot` / `none` / `both` suffix names
                # the strand explicitly.
                strand_str = {
                    -1: "◀ bot",
                     0: "▒ none",
                     1: "▶ top",
                     2: "↔ both",
                }.get(strand, "▶ top")
                # Sweep #32: col-0 combines a mark glyph with
                # the row number — see FeatureEditModal for the
                # full rationale.
                mark_glyph = ("■" if id(m) in self._marked_ids
                              else "□")
                tbl.add_row(
                    f"{mark_glyph} {i}", str(rs), str(re_),
                    ftype, label, _members_color_cell(m), strand_str,
                )
            # Re-select the active row (clamped to len-1 if rows
            # were removed and the cursor's now past the end).
            idx = max(0, min(self._selected_idx,
                             len(self._members) - 1))
            self._selected_idx = idx
            try:
                tbl.move_cursor(row=idx)
            except (IndexError, ValueError):
                pass
            # Restore scroll position so the table stays put
            # rather than snapping to the top after clear+rebuild.
            try:
                tbl.scroll_to(y=prev_scroll_y, animate=False)
            except (AttributeError, TypeError):
                pass
        finally:
            self._syncing_form = False
        self._refresh_row_button_state()

    def _focus_members_table(self) -> None:
        """Return keyboard focus to the members table after a
        structural button is clicked. Keeps the user's hands on
        the keyboard for chained ops (split → split → split).
        Best-effort — defensive try/except so a click during
        tear-down doesn't propagate."""
        try:
            tbl = self.query_one("#addfeat-members-tbl", DataTable)
            tbl.focus(scroll_visible=False)
        except (NoMatches, AttributeError):
            pass

    def _prune_marks(self) -> None:
        """Sweep #32: drop entries from `self._marked_ids` whose
        target row no longer exists in `self._members`. Mirrors
        the FeatureEditModal helper."""
        live = {id(m) for m in self._members}
        self._marked_ids = {mid for mid in self._marked_ids
                            if mid in live}

    def _toggle_mark(self, row_idx: int) -> None:
        """Sweep #32: flip the mark on `self._members[row_idx]`
        via dict identity. Marks survive `_refresh_table` and
        structural ops (id() is stable on dict reuse)."""
        if not (0 <= row_idx < len(self._members)):
            return
        mid = id(self._members[row_idx])
        if mid in self._marked_ids:
            self._marked_ids.discard(mid)
        else:
            self._marked_ids.add(mid)
        self._refresh_table()
        self._focus_members_table()

    def _refresh_row_button_state(self) -> None:
        """Enable / disable Merge + Remove based on table state.
        Merge needs ≥ 2 rows; Remove needs ≥ 2 (so we never delete
        the last row → 0-member entry, invalid)."""
        n = len(self._members)
        # Defensive: bail silently if buttons haven't mounted (the
        # _refresh_table call from on_mount fires before compose
        # finishes in some Textual versions).
        for sel, ok in (
            ("#btn-addfeat-merge-rows",  n >= 2),
            ("#btn-addfeat-remove-row",  n >= 2),
            ("#btn-addfeat-split-row",   n >= 1),
        ):
            try:
                self.query_one(sel, Button).disabled = not ok
            except NoMatches:
                pass
        # Per-row label input visible only for 2+ row groups —
        # solo features use the top-level Name field as the row
        # label (auto-synced at save time).
        self._refresh_row_label_visibility()

    def _refresh_row_label_visibility(self) -> None:
        """Toggle the per-row Label Input visible only when the
        table has 2+ rows. Avoids visual duplication with the
        top-level Name field when there's only the solo row."""
        show = len(self._members) >= 2
        for sel in ("#addfeat-row-label", "#addfeat-row-label-lbl"):
            try:
                self.query_one(sel).display = show
            except NoMatches:
                pass

    def _load_row_into_form(self, idx: int) -> None:
        """Mirror `_members[idx]` into the form fields (type /
        strand / color / `self._color` swatch). The re-entrancy
        guard prevents the resulting `.Changed` events from
        writing back into the row."""
        if not (0 <= idx < len(self._members)):
            return
        m = self._members[idx]
        self._syncing_form = True
        try:
            try:
                sel = self.query_one("#addfeat-type", Select)
                ft = m.get("feature_type") or "misc_feature"
                # Set the value; if the Select doesn't recognise
                # the type (non-standard, e.g. an exotic value
                # loaded from a `.gb` file), Textual raises
                # `InvalidSelectValueError(ValueError)`. The
                # ValueError catch covers it without depending
                # on the private exception class.
                sel.value = ft
            except (NoMatches, ValueError):
                pass
            strand = _coerce_strand(m.get("strand"))
            for sid, want in (
                ("#addfeat-strand-fwd",  strand == 1),
                ("#addfeat-strand-rev",  strand == -1),
                ("#addfeat-strand-none", strand == 0),
                ("#addfeat-strand-both", strand == 2),
            ):
                try:
                    self.query_one(sid, RadioButton).value = want
                except NoMatches:
                    pass
            col_raw = m.get("color")
            self._color = (col_raw.strip()
                           if isinstance(col_raw, str) and col_raw.strip()
                           else None)
            self._refresh_color_swatch()
            # Per-row label binding (only meaningful for 2+ row
            # groups; for solo, the Name field IS the row label).
            try:
                self.query_one(
                    "#addfeat-row-label", Input,
                ).value = str(m.get("label") or "")
            except NoMatches:
                pass
        finally:
            self._syncing_form = False

    def _save_form_into_row(self, idx: int) -> None:
        """Mirror the form fields into `_members[idx]`. Called on
        every form field change so the row state stays in lockstep
        with the visible inputs."""
        if not (0 <= idx < len(self._members)):
            return
        if self._syncing_form:
            return
        try:
            ftype = self.query_one("#addfeat-type", Select).value
            rev_rb  = self.query_one("#addfeat-strand-rev",  RadioButton)
            none_rb = self.query_one("#addfeat-strand-none", RadioButton)
            both_rb = self.query_one("#addfeat-strand-both", RadioButton)
        except NoMatches:
            return
        if ftype is None or ftype == Select.BLANK:
            return
        if   rev_rb.value:  strand = -1
        elif none_rb.value: strand = 0
        elif both_rb.value: strand = 2
        else:               strand = 1
        m = self._members[idx]
        m["feature_type"] = str(ftype)
        m["strand"]       = strand
        m["color"]        = self._color
        # Read the per-row label input (only present when 2+ rows).
        # For solo, the row's label is set from the entry Name at
        # save time via `_solo_row_from_entry` / `_entry_from_members`.
        try:
            row_label_raw = self.query_one(
                "#addfeat-row-label", Input,
            ).value
            m["label"] = _sanitize_label(
                row_label_raw, max_len=_MAX_GROUP_LABEL_LEN,
            )
        except NoMatches:
            pass
        self._refresh_table()

    def _resync_solo_row_to_sequence(self, seq_len: int) -> None:
        """When `_members` has exactly 1 row, keep that row's
        `rel_end` synced to the sequence's current length so the
        user doesn't have to manually edit rs/re for the common
        single-feature case. For 2+ rows the user is in explicit
        control; we clamp re's to ≤ seq_len and DROP rows whose
        rel_start ends up past the new sequence length (rs ≥ re
        post-clamp = invalid → the row no longer fits in the
        truncated sequence).

        Sweep #30 hardening (2026-05-26): the original version
        clamped both rs + re independently which could leave a
        row with rs == re (zero-width, validator-rejected). Now
        we drop unsalvageable rows so the in-memory state stays
        validator-clean as the user types. If ALL rows would
        drop (extreme delete) we synthesise a 1-row solo from
        the first row's metadata to preserve the colour / type /
        label so the user's intent isn't lost."""
        if not self._members:
            return
        if len(self._members) == 1:
            self._members[0]["rel_start"] = 0
            self._members[0]["rel_end"]   = max(0, int(seq_len))
            return
        survivors: list[dict] = []
        for m in self._members:
            rs = int(m.get("rel_start", 0))
            re_ = min(int(m.get("rel_end", 0)), int(seq_len))
            if rs < re_:
                m["rel_end"] = re_
                survivors.append(m)
            # else: row's start is past new seq_len → drop.
        if not survivors:
            # Salvage: synthesise a 1-row solo from the first
            # row's metadata so the modal isn't stuck at 0 rows
            # (validator rejects 0 members; modal would be
            # unsavable without intervention). The new row spans
            # the entire (possibly empty) sequence.
            base = dict(self._members[0])
            base["rel_start"] = 0
            base["rel_end"]   = max(0, int(seq_len))
            survivors = [base]
        self._members = survivors
        # Clamp selected_idx in case rows were dropped — caller
        # (`_refresh_table`) does this too but we double up so
        # any other reader of `_selected_idx` sees a valid value
        # immediately, not after the next refresh.
        self._selected_idx = max(
            0, min(self._selected_idx, len(self._members) - 1),
        )

    @on(DataTable.CellHighlighted, "#addfeat-members-tbl")
    def _on_cell_highlighted(
        self, event: "DataTable.CellHighlighted",
    ) -> None:
        """Cell-cursor changed (sweep #30, was RowHighlighted) —
        extract the row from the coordinate, save the OLD row's
        form state, then load the NEW row's data into the form.

        Skips during `_syncing_form` so the cascade of transient
        events during a table rebuild (clear → add_row × N →
        move_cursor) doesn't shuffle the form fields through
        each intermediate cursor position."""
        if self._syncing_form:
            return
        try:
            new_idx = int(event.coordinate.row)
        except (AttributeError, ValueError, TypeError):
            return
        if new_idx == self._selected_idx:
            return
        self._save_form_into_row(self._selected_idx)
        if 0 <= new_idx < len(self._members):
            self._selected_idx = new_idx
            self._load_row_into_form(new_idx)

    def on_key(self, event) -> None:
        """Space toggles the ★ mark on the highlighted member row — the
        app-wide convention (plasmid + primer libraries already do this).
        Gated on the members table being focused so Space still types a
        space inside the modal's text inputs."""
        if event.key != "space":
            return
        try:
            t = self.query_one("#addfeat-members-tbl", DataTable)
        except NoMatches:
            return
        if self.app.focused is not t or t.row_count == 0:
            return
        row = t.cursor_row
        if 0 <= row < t.row_count:
            self._toggle_mark(row)
            event.stop()

    @on(DataTable.CellSelected, "#addfeat-members-tbl")
    def _on_cell_selected(
        self, event: "DataTable.CellSelected",
    ) -> None:
        """Sweep #30: clicking (or pressing Enter on) a row's
        cells:
          * Color column → opens ColorPickerModal scoped to that
            row only.
          * Label column → opens a rename prompt scoped to that
            row only (per the user's request: "allow the user to
            name and rename each feature segment").
          * Other columns → no-op (cursor move already handled
            by `_on_cell_highlighted`).

        Persistence: the picked colour / new label is written to
        `self._members[row].color` / `.label`. Save dispatches
        them as part of the entry; cancel abandons (modal-local
        state). Pick "Auto" / empty input to clear back to None.

        Sweep #38 (2026-05-27): re-entrancy guard mirroring the
        one in `FeatureEditModal._on_cell_selected` — a single
        click can fire `CellSelected` twice in real terminals,
        which used to stack two pickers; the second one looked
        like a "reverted preview" because it carried the
        pre-pick `current_color`. If we're no longer the topmost
        screen, the duplicate event already pushed something —
        ignore.
        """
        if self._syncing_form:
            return
        if self.app.screen is not self:
            return
        try:
            row_idx = int(event.coordinate.row)
            col_idx = int(event.coordinate.column)
        except (AttributeError, ValueError, TypeError):
            return
        if col_idx == _MEMBERS_TABLE_MARK_COL:
            self._toggle_mark(row_idx)
        elif col_idx == _MEMBERS_TABLE_COLOR_COL:
            self._open_per_row_color_picker(row_idx)
        elif col_idx == _MEMBERS_TABLE_LABEL_COL:
            self._open_per_row_rename(row_idx)
        elif col_idx == _MEMBERS_TABLE_STRAND_COL:
            self._open_per_row_strand_picker(row_idx)

    def _open_per_row_strand_picker(self, row_idx: int) -> None:
        """Push `StrandPickerModal` scoped to row `row_idx`.
        Picker returns `{"strand": <int>}` with strand ∈
        {-1, 0, 1, 2}; we write that to the row's strand,
        refresh the table, and (if the row is currently selected
        in the form-binding) re-sync the strand RadioSet so the
        form reflects the new value. Cancel → no change."""
        if not (0 <= row_idx < len(self._members)):
            return
        current_strand = _coerce_strand(
            self._members[row_idx].get("strand"),
        )

        def _on_picked(result) -> None:
            if not isinstance(result, dict):
                return
            new_strand = result.get("strand")
            if (not isinstance(new_strand, int)
                    or new_strand not in (-1, 0, 1, 2)):
                return
            if not (0 <= row_idx < len(self._members)):
                return
            self._members[row_idx]["strand"] = new_strand
            # Sync radios to the new value if the picked row is
            # the currently-selected one. Wrap in `_syncing_form`
            # so the radio's Changed event doesn't echo back into
            # the row (which would be a no-op write, but cleaner
            # to avoid the round-trip).
            if row_idx == self._selected_idx:
                self._syncing_form = True
                try:
                    for sid, want in (
                        ("#addfeat-strand-fwd",  new_strand == 1),
                        ("#addfeat-strand-rev",  new_strand == -1),
                        ("#addfeat-strand-none", new_strand == 0),
                        ("#addfeat-strand-both", new_strand == 2),
                    ):
                        try:
                            self.query_one(
                                sid, RadioButton,
                            ).value = want
                        except NoMatches:
                            pass
                finally:
                    self._syncing_form = False
            self._refresh_table()
            self._focus_members_table()

        self.app.push_screen(
            StrandPickerModal(
                current_strand=current_strand,
                row_idx=row_idx,
            ),
            callback=_on_picked,
        )

    def _open_per_row_rename(self, row_idx: int) -> None:
        """Push a `GroupNamePromptModal` configured as a rename
        prompt for the row at `row_idx`. Empty label allowed
        (clears the row's label so the type's default render
        kicks in)."""
        if not (0 <= row_idx < len(self._members)):
            return
        current_label = str(
            self._members[row_idx].get("label") or "",
        )

        def _on_named(result) -> None:
            if not isinstance(result, dict):
                return
            new_label = result.get("name")
            if not isinstance(new_label, str):
                return
            if not (0 <= row_idx < len(self._members)):
                return
            # Sanitised by GroupNamePromptModal._save (control-
            # char scrub + cap); safe to write directly.
            self._members[row_idx]["label"] = new_label
            # If the renamed row is the currently-selected one,
            # also reflect the change in the per-row label Input
            # below the table.
            if row_idx == self._selected_idx:
                try:
                    self._syncing_form = True
                    self.query_one(
                        "#addfeat-row-label", Input,
                    ).value = new_label
                finally:
                    self._syncing_form = False
            self._refresh_table()
            self._focus_members_table()

        self.app.push_screen(
            GroupNamePromptModal(
                default_name=current_label,
                title=" Rename feature segment ",
                prompt=(
                    f"New label for row {row_idx + 1} "
                    f"(empty clears the label):"
                ),
                placeholder="e.g. BsaI cut site",
                allow_empty=True,
            ),
            callback=_on_named,
        )

    def _open_per_row_color_picker(self, row_idx: int) -> None:
        """Push the ColorPickerModal for the row at `row_idx`.
        On confirm, the picked color is written ONLY to that
        row's `color` field (not the modal-level `self._color` —
        that's the selected-row binding). Refreshes the table so
        the swatch repaints."""
        if not (0 <= row_idx < len(self._members)):
            return
        m = self._members[row_idx]
        current_col = m.get("color")
        if not isinstance(current_col, str) or not current_col.strip():
            current_col = None
        ftype = (m.get("feature_type") or "misc_feature")

        def _on_picked(result) -> None:
            if not isinstance(result, dict):
                return
            new_col = result.get("color")
            new_col = (new_col
                       if isinstance(new_col, str) and new_col.strip()
                       else None)
            if not (0 <= row_idx < len(self._members)):
                return
            self._members[row_idx]["color"] = new_col
            # If the user also marked it as the new type default,
            # update the persistent feature_colors map (same
            # behavior as the form-bound color picker).
            if result.get("set_default") and new_col:
                defaults = _load_feature_colors()
                defaults[ftype] = new_col
                try:
                    _save_feature_colors(defaults)
                except (OSError, RuntimeError) as exc:
                    _notify_save_failure(
                        self.app, "Feature colors", exc,
                    )
            # If the picked row was the currently selected one,
            # also update `self._color` so the form's swatch
            # repaints to match.
            if row_idx == self._selected_idx:
                self._color = new_col
                self._refresh_color_swatch()
            self._refresh_table()

        self.app.push_screen(
            ColorPickerModal(ftype, _safe_color_for_picker(current_col)),
            callback=_on_picked,
        )

    # ── Sweep #30: split / merge / add / remove handlers ──────────

    @on(Button.Pressed, "#btn-addfeat-add-row")
    def _on_add_row(self, _) -> None:
        """Split the currently-selected row at its midpoint to
        produce two contiguous rows (head.end == tail.start). The
        two rows are ADJACENT — no overlap, no gap. This matches
        the user's expectation that "Add row" creates a structural
        split rather than appending a new row that overlaps the
        existing tail.

        Refuses when the selected row's width is less than 2 bp
        (no interior position to split at — same constraint as the
        Split button) or when at the `_MAX_GROUP_MEMBERS` cap.

        Sweep #30 redesign (2026-05-26): replaced the original
        "append at tail" behaviour after the user reported the
        new row routinely overlapped the existing solo row by 1
        bp when the table tiled the full sequence."""
        if len(self._members) >= _MAX_GROUP_MEMBERS:
            self._set_status(
                f"[red]Cap reached: {_MAX_GROUP_MEMBERS} members "
                f"max per entry.[/red]"
            )
            return
        # Save current form into selected row first so a click
        # mid-edit doesn't lose the in-progress changes.
        self._save_form_into_row(self._selected_idx)
        if not (0 <= self._selected_idx < len(self._members)):
            return
        m = self._members[self._selected_idx]
        rs = int(m["rel_start"])
        re_ = int(m["rel_end"])
        if rs + 1 >= re_:
            self._set_status(
                f"[red]Row width {re_ - rs} too small to split — "
                f"need at least 2 bp.[/red]"
            )
            return
        # Midpoint split: head = [rs, mid), tail = [mid, re].
        # Adjacent (head.end == tail.start), no overlap, no gap.
        # Sweep #30: tail defaults to arrowless (0) — user-
        # requested "default to arrowless" for new segments.
        mid = (rs + re_) // 2
        try:
            self._members = _split_member(
                self._members, self._selected_idx, mid,
                tail_strand=0,
            )
        except ValueError as exc:
            self._set_status(f"[red]Split failed: {exc}[/red]")
            return
        # Keep cursor on the head row so the user can edit it
        # immediately; the tail row sits right below (label=""
        # by `_split_member` convention so the user knows to fill).
        self._refresh_table()
        self._load_row_into_form(self._selected_idx)
        self._set_status("")
        self._focus_members_table()

    @on(Button.Pressed, "#btn-addfeat-split-row")
    def _on_split_row(self, _) -> None:
        """Open `SplitPositionPromptModal` for the selected row;
        on confirm, replace the row with two halves via
        `_split_member`. Refuses to open when the row's width is
        less than 2 (no interior position to split at)."""
        # Save in-progress form edits to the selected row first.
        self._save_form_into_row(self._selected_idx)
        if not (0 <= self._selected_idx < len(self._members)):
            return
        m = self._members[self._selected_idx]
        rs = int(m["rel_start"])
        re_ = int(m["rel_end"])
        if rs + 1 >= re_:
            self._set_status(
                f"[red]Row width {re_ - rs} is too small to "
                f"split (need ≥ 2 bp).[/red]"
            )
            return
        if len(self._members) >= _MAX_GROUP_MEMBERS:
            self._set_status(
                f"[red]Cap reached: {_MAX_GROUP_MEMBERS} members "
                f"max per entry — cannot split further.[/red]"
            )
            return

        def _on_pos(result) -> None:
            if not isinstance(result, dict):
                return
            pos = result.get("pos")
            if not isinstance(pos, int):
                return
            try:
                self._members = _split_member(
                    self._members, self._selected_idx, pos,
                    tail_strand=0,
                )
            except ValueError as exc:
                self._set_status(f"[red]Split failed: {exc}[/red]")
                return
            self._refresh_table()
            self._load_row_into_form(self._selected_idx)
            self._set_status("")
            self._focus_members_table()

        try:
            self.app.push_screen(
                SplitPositionPromptModal(rs, re_),
                callback=_on_pos,
            )
        except ValueError as exc:
            # Defensive — SplitPositionPromptModal's own width
            # check raised. Surface its message in the status
            # line so the user sees why.
            self._set_status(f"[red]{exc}[/red]")

    @on(Button.Pressed, "#btn-addfeat-merge-rows")
    def _on_merge_rows(self, _) -> None:
        """Merge marked rows together (sweep #32), or fall back
        to merging the selected row with the next one (legacy
        pair-merge). Marks set via the col-0 ■/□ toggle; the
        merge folds them all in `rel_start` order.

        Refuses when fewer than 2 rows total, or when no marks
        are set AND the cursor is on the last row (no
        downstream neighbour for the legacy pair-merge)."""
        self._save_form_into_row(self._selected_idx)
        n = len(self._members)
        if n < 2:
            self._set_status(
                "[red]Need at least 2 rows to merge.[/red]"
            )
            return
        marked_idxs = [
            i for i, m in enumerate(self._members)
            if id(m) in self._marked_ids
        ]
        if len(marked_idxs) >= 2:
            idxs = marked_idxs
            using_marks = True
        else:
            # Sort-by-rs ordering: the cursor's row + the next
            # row in display order. If at the last row, refuse
            # (the user needs to either move up or mark the
            # rows they want).
            if self._selected_idx >= n - 1:
                self._set_status(
                    "[red]Cursor is on the last row — move up "
                    "one row, or click col-0 (■/□) on the rows "
                    "you want to merge.[/red]"
                )
                return
            idxs = [self._selected_idx, self._selected_idx + 1]
            using_marks = False
        try:
            self._members = _merge_members(self._members, idxs)
        except ValueError as exc:
            self._set_status(f"[red]Merge failed: {exc}[/red]")
            return
        # The merged row lands at the lowest involved index.
        self._selected_idx = min(idxs)
        # Sweep #32: clear marks after a successful merge.
        self._marked_ids.clear()
        self._refresh_table()
        self._load_row_into_form(self._selected_idx)
        merge_msg = (
            f"Merged {len(idxs)} marked rows."
            if using_marks else ""
        )
        self._set_status(f"[dim]{merge_msg}[/dim]" if merge_msg else "")
        self._focus_members_table()
        # Sweep #30: post-merge rename prompt. The fused row
        # inherits the first row's label by default; this lets
        # the user immediately rename to reflect the new combined
        # meaning ("BsaI" + "AATG" → "BsaI→AATG adapter"). Cancel
        # keeps the inherited label.
        self._open_per_row_rename(self._selected_idx)

    @on(Button.Pressed, "#btn-addfeat-remove-row")
    def _on_remove_row(self, _) -> None:
        """Remove the currently-selected row. Disabled (UI) when
        only 1 row remains; we double-check here too in case the
        button state lags."""
        n = len(self._members)
        if n < 2:
            self._set_status(
                "[red]Cannot remove the last row — every entry "
                "needs at least one member.[/red]"
            )
            return
        if not (0 <= self._selected_idx < n):
            return
        new_members = list(self._members)
        new_members.pop(self._selected_idx)
        self._members = new_members
        # Bump selected idx if we removed the last row's index.
        self._selected_idx = min(self._selected_idx,
                                   len(self._members) - 1)
        self._refresh_table()
        self._load_row_into_form(self._selected_idx)
        self._set_status("")
        self._focus_members_table()

    def _set_status(self, msg: str) -> None:
        """Set the modal's status line. Used by row ops so error
        messages surface in the same place as validation errors."""
        try:
            self.query_one("#addfeat-status", Static).update(msg)
        except NoMatches:
            pass

    @on(Select.Changed, "#addfeat-type")
    def _type_changed(self, _) -> None:
        # Auto-mode swatch tracks the effective default for the chosen type.
        self._refresh_color_swatch()
        # Sweep #30: form change → write back into selected row.
        self._save_form_into_row(self._selected_idx)

    @on(RadioSet.Changed, "#addfeat-strand")
    def _strand_changed(self, _event) -> None:
        """Sweep #30: keep the selected row's strand in sync with
        the orientation radio."""
        self._save_form_into_row(self._selected_idx)

    @on(Input.Changed, "#addfeat-row-label")
    def _row_label_changed(self, _event) -> None:
        """Sweep #30: keep the selected row's `label` in sync
        with the per-row Label input as the user types. Sanitised
        through `_sanitize_label` so a pasted ANSI escape doesn't
        smuggle through to the row dict."""
        if self._syncing_form:
            return
        self._save_form_into_row(self._selected_idx)

    @on(TextArea.Changed, "#addfeat-seq")
    def _seq_changed(self, _event) -> None:
        """Sweep #30: typing in the sequence box auto-resyncs the
        members' rel coords (1-row case clamps row 0 to [0, len],
        2+ rows clamp any over-the-end re's to len). Cheap to
        re-render the table on each keystroke; the table is at
        most `_MAX_GROUP_MEMBERS` (64) rows."""
        if self._syncing_form:
            return
        try:
            raw = _event.text_area.text
        except AttributeError:
            try:
                raw = self.query_one(
                    "#addfeat-seq", TextArea,
                ).text
            except NoMatches:
                return
        seq_clean = "".join(
            ch for ch in raw.upper() if not ch.isspace()
        )
        self._resync_solo_row_to_sequence(len(seq_clean))
        self._refresh_table()

    @on(Button.Pressed, "#btn-addfeat-import")
    def _import(self, _) -> None:
        entries = _load_library()
        if not entries:
            self.query_one("#addfeat-status", Static).update(
                "[yellow]Library is empty — save a plasmid first.[/yellow]"
            )
            return

        def _on_plasmid(entry_id):
            if not entry_id:
                return
            # Sweep #25: helper avoids the full-library deepcopy.
            match = _find_library_entry_by_id(entry_id)
            if not match:
                self.query_one("#addfeat-status", Static).update(
                    "[red]Entry not found.[/red]"
                )
                return
            gb_text = match.get("gb_text", "")
            if not gb_text:
                self.query_one("#addfeat-status", Static).update(
                    "[red]Library entry has no sequence.[/red]"
                )
                return
            try:
                rec = _gb_text_to_record(gb_text)
            except Exception as exc:    # noqa: BLE001
                _log.exception("Feature import: failed to parse library entry")
                self.query_one("#addfeat-status", Static).update(
                    f"[red]Couldn't parse the stored plasmid: {exc}. "
                    f"The library entry may be corrupted — try re-saving "
                    f"that plasmid from its source file.[/red]"
                )
                return
            feat_entries = _extract_feature_entries_from_record(rec)
            if not feat_entries:
                self.query_one("#addfeat-status", Static).update(
                    "[yellow]Plasmid has no non-source features.[/yellow]"
                )
                return

            def _on_feat(picked):
                if not picked:
                    return
                self._apply_prefill(picked)

            self.app.push_screen(
                PlasmidFeaturePickerModal(feat_entries,
                                          plasmid_name=match.get("name", "")),
                callback=_on_feat,
            )

        self.app.push_screen(PlasmidPickerModal(None), callback=_on_plasmid)

    def _apply_prefill(self, entry: dict) -> None:
        """Fill the form fields from a picked feature. Leaves user's current
        name alone if it's non-empty so accidental imports don't clobber
        typed data."""
        try:
            name_inp = self.query_one("#addfeat-name", Input)
            type_sel = self.query_one("#addfeat-type", Select)
            seq_ta   = self.query_one("#addfeat-seq", TextArea)
            quals_in = self.query_one("#addfeat-quals", Input)
            desc_in  = self.query_one("#addfeat-desc", Input)
            fwd_rb   = self.query_one("#addfeat-strand-fwd",  RadioButton)
            rev_rb   = self.query_one("#addfeat-strand-rev",  RadioButton)
            none_rb  = self.query_one("#addfeat-strand-none", RadioButton)
            both_rb  = self.query_one("#addfeat-strand-both", RadioButton)
            status   = self.query_one("#addfeat-status", Static)
        except NoMatches:
            return
        if not name_inp.value.strip():
            name_inp.value = entry.get("name", "")
        ftype = entry.get("feature_type", "misc_feature")
        # Select raises if the value isn't a known option; prepend it if so.
        current_options = [v for _, v in getattr(type_sel, "_options", [])]
        if ftype not in current_options:
            new_opts = [(f"{ftype} (non-standard)", ftype)] + \
                       [(t, t) for t in _GENBANK_FEATURE_TYPES]
            type_sel.set_options(new_opts)
        type_sel.value = ftype
        seq_ta.text = entry.get("sequence", "")
        quals_in.value = _qualifiers_to_string(entry.get("qualifiers") or {})
        desc_in.value = entry.get("description", "") or ""
        strand = entry.get("strand", 1)
        fwd_rb.value  = (strand == 1)
        rev_rb.value  = (strand == -1)
        none_rb.value = (strand == 0)
        both_rb.value = (strand == 2)
        col = entry.get("color")
        self._color = col if isinstance(col, str) and col else None
        self._refresh_color_swatch()
        status.update(
            f"[green]Imported '{entry.get('name', '?')}' — "
            f"review and Save or Insert.[/green]"
        )

    def action_cancel(self) -> None:
        self.dismiss(None)

    # ── Sticky picks across modal instances ──────────────────────────────

    # Set of dismiss `result["action"]` strings that count as a
    # "commit" — i.e., the user actually completed an add. Sticky
    # picks are captured only on commit so cancelling (which
    # dismisses with `None`) doesn't overwrite the previous saved
    # picks with whatever the form happened to show. "annotate" is
    # the dismiss action emitted by the Insert button — same intent
    # as Save (the user committed values), just a different
    # downstream effect.
    _STICKY_CAPTURE_ACTIONS = frozenset({"save", "insert", "annotate"})

    def _capture_sticky_picks(self) -> None:
        """Read the current `feature_type` / `strand` / `color` form
        values and stash them on the class-level `_LAST_USER_PICKS`
        dict so the NEXT instance of this modal inherits them
        instead of falling back to cold defaults. Best-effort: any
        widget that's already been unmounted is silently skipped —
        persistence is a UX nicety, not a correctness requirement,
        and never blocks the dismiss path. Defensive: every value
        is validated before landing in the dict so a degenerate
        form state (e.g. no radio checked, Select.BLANK selected)
        can't plant unusable defaults that the next __init__ would
        try to consume."""
        cls = self.__class__
        try:
            sel = self.query_one("#addfeat-type", Select)
            v = sel.value
            if (isinstance(v, str) and v.strip()
                    and v != Select.BLANK):
                cls._LAST_USER_PICKS["feature_type"] = v.strip()
        except NoMatches:
            pass
        # Strand: scan the four radios, pick the one that's checked.
        # Falls through silently if the modal was dismissed before
        # the RadioSet finished mounting (action_cancel from Esc
        # right after open) or if none happens to be checked (a
        # degenerate state we can hit if a future code path lands
        # an invalid sticky `strand` and the compose pre-checked no
        # radio — defended against in `__init__` but kept here too).
        # Order matches the compose order.
        strand_radios = (
            ("#addfeat-strand-fwd",   1),
            ("#addfeat-strand-rev",  -1),
            ("#addfeat-strand-none",  0),
            ("#addfeat-strand-both",  2),
        )
        for rb_id, val in strand_radios:
            try:
                rb = self.query_one(rb_id, RadioButton)
            except NoMatches:
                continue
            if getattr(rb, "value", False):
                cls._LAST_USER_PICKS["strand"] = val
                break
        # Color: `self._color` is the canonical state — already
        # maintained by `_open_color_picker._on_color` /
        # `_clear_color`. Normalize the value the same way
        # `__init__` will read it back, so a tiny mismatch (e.g.
        # `_color = "  #ff8800  "` from an unexpected source)
        # doesn't bypass the strip-on-read guard.
        col = self._color
        if isinstance(col, str) and col.strip():
            cls._LAST_USER_PICKS["color"] = col.strip()
        elif col is None:
            # Explicit "Auto" — clear any prior color so the next
            # session doesn't silently re-apply the old custom
            # color when the user has just chosen Auto.
            cls._LAST_USER_PICKS.pop("color", None)

    def dismiss(  # type: ignore[override]
        self, result=None,
    ):
        """Wrap `ModalScreen.dismiss` so every COMMIT exit path
        (Save / Insert / Annotate) captures the user's picks for
        the next session. Cancel / Esc paths are intentionally
        skipped — a cancelled session represents picks the user
        DID NOT commit to, and overwriting the previously-saved
        sticky picks with those would lose useful state. The whole
        capture is wrapped in a broad except so persistence can
        never break the dismiss itself.

        [INV-50] double-dismiss guard: rapid Save/Insert clicks
        can fire the handler twice before the modal finishes
        tearing down. The flag short-circuits the second call so
        the app dispatcher (which mutates the canvas record)
        runs exactly once per user-initiated dismiss.

        Return type intentionally widened to allow `None` on the
        early-return path; button handlers don't await dismiss
        so the runtime is fine. `# type: ignore[override]`
        appeases pyright."""
        if self._dismissed:
            return None
        self._dismissed = True
        try:
            if (
                isinstance(result, dict)
                and result.get("action")
                    in self._STICKY_CAPTURE_ACTIONS
            ):
                self._capture_sticky_picks()
        except Exception:
            # Persistence is best-effort — never let it block a
            # dismiss that the user intended to fire.
            pass
        return super().dismiss(result)


class FeatureEditModal(ModalScreen):
    """View / edit an existing feature.

    Opens **read-only** by default — the user can inspect everything
    but every input is `disabled`. Pressing `Edit` flips the form to
    editable; `Save` commits the edits and dismisses with a `dict`
    payload; `Cancel` / `Close` dismiss with `None`.

    Layout: title docked top, action buttons docked bottom (always
    visible regardless of body height), and a vertically-scrolling
    body in between holding the form fields, the feature sequence
    (read-only TextArea), and the notes / references box (Markdown
    in view mode for clickable URLs; TextArea in edit mode for raw
    Markdown editing). The dock-based layout fixes the prior bug
    where buttons could fall below the visible viewport on small
    terminals.

    Position editing is intentionally NOT exposed here — moving a
    feature's bp range collides with the wrap-feature invariants
    documented in CLAUDE.md (sacred invariants #5, #8, #9). Users
    who need to relocate a feature should delete + re-add via the
    seq-panel selection flow. Label / type / strand / color / notes
    are the safe edits that don't risk corrupting circular-wrap
    features.

    Triggers:
      * Enter or double-click on a feature row in the FeatureSidebar.
      * Enter on a highlighted feature in the SequencePanel.
    """

    _blocks_undo: bool = True   # sweep #10: Save mutates feature on canvas

    BINDINGS = [
        Binding("escape", "cancel", "Cancel"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    DEFAULT_CSS = """
    /* `height: auto` lets the dialog shrink to content — the previous
       `height: 90%` always inflated the modal to ~43 rows even when
       the form was 25 rows tall, leaving a big blank gap below the
       notes box. The remaining vertical space is now reclaimed by
       the TextArea / Markdown widgets, which carry their own
       internal scrollbars when content overflows. `max-height: 90%`
       still caps the dialog on small terminals so the buttons stay
       reachable. */
    #featedit-dlg {
        /* Sweep #30 (2026-05-26): full-screen layout matching
           BlastModal/AlignmentScreen — the members table +
           Add/Split/Merge/Remove buttons + abs coord inputs
           (sweep #31) + the existing form rows had grown the
           dialog past comfortable centered-dialog dimensions.
           98% × 96% gives every widget room without crowding
           and leaves space for future additions. */
        width: 98%; height: 96%;
        background: $surface;
        border: solid $accent;
        padding: 1 2;
    }
    #featedit-title {
        height: 1;
        text-style: bold;
        background: $accent;
        color: $text;
        padding: 0 1;
        margin-bottom: 1; text-align: center;
    }
    /* Body fills the remaining space inside the (capped) dialog.
       When the dialog hits its max-height, body scrolls; on a
       roomy terminal the dialog hugs content height (set above
       via `height: auto`) so the body never actually scrolls.
       That's the trade we want — no big vertical gap on average
       terminals, but the buttons remain reachable on tiny ones. */
    #featedit-body { height: 1fr; padding: 0 1; }
    #featedit-body Label { color: $text-muted; margin: 0; height: 1; }
    /* Inline position row — label + value on one line so we don't
       waste a row on the label. */
    #featedit-pos-row { height: 1; margin-top: 1; }
    #featedit-pos-row Label { width: auto; margin-right: 1; }
    #featedit-pos { width: 1fr; color: $text-muted; }
    /* Pin row + cols to a fixed height; without this the cols' default
       `1fr` makes them swallow the body's leftover space and creates a
       ~20-row void between Strand and the Color row. Matches the sister
       AddFeatureModal's #addfeat-row1 pattern. */
    #featedit-row1       { height: 6; }
    #featedit-type-col   { width: 1fr; height: 6; }
    #featedit-strand-col { width: 1fr; height: 6; }
    #featedit-color-row  { height: auto; margin-top: 1; }
    #featedit-color-row Label { width: auto; margin-right: 1; }
    #featedit-color-swatch { width: auto; padding: 0 1; }
    /* Sequence + notes carry their OWN scrollbars — modal doesn't
       scroll, the textboxes do. 4 rows each keeps the dialog under
       the 48-row baseline terminal cap (the modal-boundary check);
       long content scrolls inside the widget. */
    /* Sweep #30: full-screen modal → restore seq + notes to
       comfortable heights (6 each). The modal now has 96% of
       viewport so there's no longer a row-budget squeeze. */
    #featedit-seq { height: 6; border: solid $primary-darken-1; }
    /* Notes: Markdown widget for view-mode (clickable URLs) and
       TextArea for edit-mode. Mounted side-by-side; visibility
       toggled by `_set_editing`. Both share a height so the layout
       doesn't shift when the user clicks Edit. */
    #featedit-notes-md {
        height: 6; border: solid $primary-darken-1;
        padding: 0 1; overflow-y: auto;
    }
    #featedit-notes-edit { height: 6; border: solid $primary-darken-1; }
    #featedit-status { height: 1; padding: 0 1; }
    #featedit-btns { align: right middle;  height: 3; margin-top: 1; }
    #featedit-btns Button { margin-right: 1; min-width: 12; }
    /* Sweep #30: members table + row-op buttons replace the
       sweep #29 group-ops row. Same height conventions so the
       layout feels familiar; the table caps at 6 rows tall so
       a `_MAX_GROUP_MEMBERS`-cap entry scrolls inside the
       widget rather than pushing the bottom button row off-
       screen. */
    /* Sweep #30: full-screen modal → table gets 10 rows of
       visible content (scrolls internally for groups with
       > 10 members, capped at `_MAX_GROUP_MEMBERS = 64`). */
    #featedit-members-tbl    { height: 10; min-height: 6; margin-top: 1; }
    #featedit-members-btns        { height: 3; margin-top: 1; }
    #featedit-members-btns Button { margin-right: 1; min-width: 12; }
    /* Sweep #30: disabled buttons rely on Textual's stock
       `disabled` widget styling (slightly dimmed colour, no
       click response). Tried two rounds of custom :disabled
       CSS (sweep #30 v1: `$surface` bg + `text-style: dim`
       made them invisible; v2: `$boost` + custom border made
       them only-visible-on-hover); both looked worse than
       the default. The `disabled=True` widget attribute already
       blocks click events — that's the gating mechanism the
       user wanted ("just make the buttons not click"). */
    """

    def __init__(self, idx: int, feat: dict, total: int,
                 *,
                 sequence: str = "",
                 notes: str = "",
                 group_members: "list[dict] | None" = None) -> None:
        super().__init__()
        self._idx       = idx
        self._feat      = dict(feat)
        self._total     = total
        # Feature's 5'→3' bases for the read-only sequence box. Caller
        # extracts this with wrap-awareness (`seq[start:] + seq[:end]`
        # for end < start) so the modal doesn't need to know about
        # the record's circularity.
        self._sequence  = str(sequence or "")
        # Notes / references — joined to a single string for the
        # widgets; round-tripped to/from `qualifiers["note"]` (list
        # of strings) by the caller. Markdown is the storage format
        # so URLs / `[text](url)` round-trip through `.gb` files.
        self._notes_md  = str(notes or "")
        self._editing   = False
        self._color: "str | None" = self._feat.get("color")
        # [INV-50] dismiss-once guard: prevents a rapid Save /
        # Cancel double-click from re-dispatching the edit
        # payload (which mutates the canvas record). See
        # `docs/invariants.md` [INV-50].
        self._dismissed: bool = False
        # Sweep #30 (2026-05-26): capture the original feature's
        # identity signature so the save path can verify the
        # feature at `self._idx` STILL matches what the user
        # opened. Async work (agent endpoints, background
        # workers) could insert/remove features between modal
        # open and Save → idx drifts → wrong feature gets edited.
        # See `_verify_idx_still_valid` below.
        self._original_feat_signature = self._make_feat_signature(
            self._feat,
        )
        # Sweep #30: members table state. When the feature is part
        # of a group, the caller supplies `group_members` (a list
        # of dicts already projected to the rel-coord shape) so
        # the table can show all members of the group. For solo
        # features, the caller passes None and we build a 1-row
        # list from this feature's own data. Sacred invariant #4:
        # never mutate the list in place — every state change
        # reassigns `self._members`.
        try:
            if isinstance(group_members, list) and group_members:
                # Sweep #30 fix (2026-05-26): the validator's
                # `sequence_len` arg must be the GROUP's anchor
                # span (leftmost start → rightmost end), NOT this
                # single feature's length. `_members_span_int()`
                # returns the latter and would reject every group
                # member whose `rel_end` exceeds the cursor
                # feature's length → silent fallback to 1-row
                # solo (the bug user reported: "i dont see any
                # grouping behavior nor arrow change per segment"
                # after splitting a feature into 4 sub-features).
                # Derive the group span from the members
                # themselves — `max(rel_end)` == group span by
                # construction (`_collect_group_members_for_modal`
                # projects against the group's leftmost anchor).
                group_span = max(
                    int(m.get("rel_end", 0))
                    for m in group_members
                )
                self._members = list(_validate_group_members(
                    [dict(m) for m in group_members],
                    max(1, group_span),
                ))
            else:
                self._members = [self._feat_to_member_row()]
        except ValueError:
            # Caller passed malformed group_members → fall back
            # to a solo 1-row list.
            self._members = [self._feat_to_member_row()]
        # Default-select the row that corresponds to THIS feature
        # (the one the user clicked to open the modal). Match on
        # label + strand + width, with the leftmost row as fallback.
        self._selected_idx = self._find_self_idx()
        self._syncing_form = False
        # Sweep #32 (2026-05-26): set of `id(member_dict)`
        # values for rows the user has marked via the col-0
        # toggle. Merge folds marked rows together in
        # `rel_start` order when ≥ 2 are marked; falls back to
        # the legacy "selected + next" pair-merge otherwise.
        # `id()` keeps the marks stable across `_refresh_table`
        # (dicts are reused, not rebuilt) and survives
        # selected_idx shifts. `_prune_marks` runs on every
        # table refresh to drop marks for rows that no longer
        # exist (after split / merge / remove).
        self._marked_ids: "set[int]" = set()

    def _members_span_int(self) -> int:
        """Bp length used as the validator's `sequence_len` arg
        when projecting group_members. Defends against zero-span
        features (would trip the validator's `positive int` check)
        by clamping to 1."""
        start = int(self._feat.get("start", 0))
        end   = int(self._feat.get("end",   0))
        span = _feat_len(start, end, self._total) or 0
        return max(1, span)

    def _feat_to_member_row(self) -> dict:
        """Build the 1-row solo shape from this feature's own
        fields. Mirrors `_solo_row_from_entry` but takes from a
        canvas-feature dict (uses `type` not `feature_type`,
        etc.) instead of a library-entry dict."""
        span = self._members_span_int()
        return {
            "rel_start":   0,
            "rel_end":     span,
            "feature_type": self._feat.get("type") or "misc_feature",
            "label":       self._feat.get("label") or "",
            "color":       self._feat.get("color"),
            "strand":      _coerce_strand(self._feat.get("strand")),
            "qualifiers":  {},
            "description": "",
        }

    def _find_self_idx(self) -> int:
        """Find the row in `self._members` that corresponds to
        this feature. Match by (label, strand, width); fall back
        to row 0 if no row matches (defensive — the caller built
        the members list so a mismatch should be impossible)."""
        want_label  = str(self._feat.get("label") or "")
        want_strand = _coerce_strand(self._feat.get("strand"))
        want_width  = self._members_span_int()
        for i, m in enumerate(self._members):
            row_w = int(m.get("rel_end", 0)) - int(m.get("rel_start", 0))
            if (str(m.get("label") or "") == want_label
                    and _coerce_strand(m.get("strand")) == want_strand
                    and row_w == want_width):
                return i
        return 0

    @staticmethod
    def _make_feat_signature(feat: dict) -> tuple:
        """Build an identity signature for a feature dict so we
        can detect if the canvas feature at `self._idx` has been
        swapped for a different one between modal-open and Save
        (e.g., async work from agent endpoints inserts/removes
        features, shifting indices). The signature is
        deterministic + cheap (5 fields, all hashable).

        Sweep #30 (2026-05-26): identity drift defense. Pre-this
        change, a stale idx would silently mutate the wrong
        feature — the user thinks they're editing X, the canvas
        gets feature Y edited."""
        if not isinstance(feat, dict):
            return ()
        return (
            str(feat.get("label") or ""),
            str(feat.get("type")  or ""),
            _coerce_strand(feat.get("strand")),
            int(feat.get("start", 0)  or 0),
            int(feat.get("end",   0)  or 0),
        )

    def _verify_idx_still_valid(self) -> bool:
        """Return True if the canvas feature at `self._idx` STILL
        matches the feature the user opened the modal on. Returns
        False if the index drifted, the feature was deleted, or
        any of the identity fields differ. Caller is expected to
        surface a clear error in the status line.

        Sweep #30 fix (2026-05-26): only applies when the modal
        is editing a CANVAS feature. The synth editor's
        FeatureEditRequested flow also uses this modal but its
        feature lives in `ed._feats` (the synth editor's local
        list), NOT in `pm._feats` — so a canvas-only identity
        check would always refuse the synth save. We detect the
        canvas context at mount (`_on_canvas_at_open`) and skip
        the check otherwise.

        Best-effort: if the app's plasmid map can't be queried,
        OPTIMISTICALLY return True (don't block the save on a
        transient query failure)."""
        if not self._on_canvas_at_open:
            return True
        try:
            pm = self.app.query_one("#plasmid-map", PlasmidMap)
        except (NoMatches, AttributeError):
            return True
        try:
            feats = pm._feats
            if not (0 <= self._idx < len(feats)):
                return False
            current_sig = self._make_feat_signature(feats[self._idx])
            return current_sig == self._original_feat_signature
        except (AttributeError, IndexError, TypeError):
            return True

    def _detect_on_canvas_at_open(self) -> bool:
        """Sweep #30 staleguard: at mount time, check whether
        the feature this modal was opened on lives in the canvas
        plasmid map's `_feats` list at `self._idx`. If yes, the
        identity check applies. If no (e.g., the synth editor
        opened us against its local feat list, or there's no
        plasmid map at all), skip the check.

        Captured ONCE at mount so the check's applicability
        doesn't shift if pm._feats changes mid-modal — we'd want
        to flag that change AS the staleness, not silently switch
        to skip mode."""
        try:
            pm = self.app.query_one("#plasmid-map", PlasmidMap)
        except (NoMatches, AttributeError):
            return False
        try:
            feats = pm._feats
            if not (0 <= self._idx < len(feats)):
                return False
            sig = self._make_feat_signature(feats[self._idx])
            return sig == self._original_feat_signature
        except (AttributeError, IndexError, TypeError):
            return False

    def compose(self) -> ComposeResult:
        # Lazy-import Markdown — same rationale as HelpModal.compose.
        from textual.widgets import Markdown as _Markdown

        f = self._feat
        label    = f.get("label", "")
        ftype    = f.get("type",  "misc_feature")
        strand   = f.get("strand", 0)
        start    = f.get("start", 0)
        end      = f.get("end",   0)

        type_options = [(t, t) for t in _GENBANK_FEATURE_TYPES]
        if ftype not in _GENBANK_FEATURE_TYPES:
            type_options.insert(0, (f"{ftype} (non-standard)", ftype))

        # Position display: 1-indexed, end-inclusive in the human-
        # facing form, with bp count via _feat_len so wrap features
        # render their actual span instead of a negative width.
        bp_len = _feat_len(start, end, self._total) or 0
        pos_str = f"{start + 1:,}..{end:,}  ({bp_len:,} bp)"
        if end < start:
            pos_str += "  · wraps origin"

        with Vertical(id="featedit-dlg"):
            yield Static(f" Feature: {label or '(unnamed)'} ",
                         id="featedit-title")
            # Body wraps in ScrollableContainer only as a fallback
            # for tiny terminals; on a comfortable terminal it sizes
            # itself to content (no scrollbar) thanks to `height: auto`.
            # Long-form content stays inside the sequence + notes
            # widgets, which scroll internally regardless.
            with ScrollableContainer(id="featedit-body"):
                yield Label("Label:")
                yield Input(value=label, id="featedit-name", disabled=True)

                with Horizontal(id="featedit-row1"):
                    with Vertical(id="featedit-type-col"):
                        yield Label("Type:")
                        yield Select(type_options, value=ftype,
                                     id="featedit-type", allow_blank=False,
                                     disabled=True)
                    with Vertical(id="featedit-strand-col"):
                        yield Label("Strand:")
                        with RadioSet(id="featedit-strand", disabled=True):
                            yield RadioButton("▶ Top (forward)",
                                              value=(strand == 1),
                                              id="featedit-strand-fwd")
                            yield RadioButton("◀ Bottom (reverse)",
                                              value=(strand == -1),
                                              id="featedit-strand-rev")
                            yield RadioButton("▒ None (arrowless)",
                                              value=(strand == 0),
                                              id="featedit-strand-none")
                            yield RadioButton("↔ Both strands",
                                              value=(strand == 2),
                                              id="featedit-strand-both")

                with Horizontal(id="featedit-color-row"):
                    yield Label("Color:")
                    yield Static("", id="featedit-color-swatch", markup=True)
                    yield Button("Pick Color",
                                 id="btn-featedit-color", disabled=True)
                    yield Button("Auto",
                                 id="btn-featedit-color-clear", disabled=True)

                # Inline position row — saves a vertical line versus
                # a separate label + value pair.
                with Horizontal(id="featedit-pos-row"):
                    yield Label("Position:")
                    yield Static(pos_str, id="featedit-pos")

                # Sequence (read-only). Title sits on the border so
                # we save a row vs an external Label. TextArea has
                # its own scrollbar — the modal itself stays static.
                seq_ta = TextArea(self._sequence, id="featedit-seq",
                                   read_only=True, soft_wrap=True)
                seq_ta.border_title = (
                    f"Sequence  (5'→3', {len(self._sequence):,} bp)"
                )
                yield seq_ta

                # Notes / references. View mode → Markdown widget
                # (clickable URLs); edit mode → TextArea. Both have
                # internal scrollbars so the modal layout doesn't
                # shift when the user clicks Edit. Markdown widgets
                # accept `border_title` too — same row-saving trick.
                md = _Markdown(self._notes_md or "_(none)_",
                                id="featedit-notes-md")
                md.border_title = (
                    "Notes / references  "
                    "(Markdown — links + [text](url) supported)"
                )
                yield md
                ta = TextArea(self._notes_md, id="featedit-notes-edit",
                               soft_wrap=True)
                ta.border_title = (
                    "Notes / references  (raw Markdown — Edit mode)"
                )
                ta.display = False  # hidden until Edit is pressed
                yield ta

                # Sweep #30: members table for split / merge /
                # add / remove operations on the group structure.
                # When this feature isn't part of a group, the
                # table has 1 row (the feature itself) and the
                # buttons let you promote-to-group via Split / Add.
                # When the feature IS in a group, the table seeds
                # with ALL group members so the user can
                # restructure the whole bundle from any one
                # member's edit view.
                yield Label("Members  (split/merge sub-features):")
                tbl = _SingleClickDataTable(
                    id="featedit-members-tbl",
                    # Sweep #30 (2026-05-26): `cursor_type="cell"`
                    # gives cell-level click events. The
                    # `_SingleClickDataTable` subclass fires
                    # `CellSelected` on first click so the per-
                    # row color / label / strand pickers open
                    # immediately.
                    cursor_type="cell", zebra_stripes=True,
                )
                tbl.add_columns(
                    "#", "start", "end", "type", "label", "color",
                    "strand",
                )
                yield tbl
                with Horizontal(id="featedit-members-btns"):
                    yield Button(
                        "+ Add row", id="btn-featedit-add-row",
                        disabled=True,
                        tooltip=(
                            "Append a new sub-feature row "
                            "(promotes solo → group)."
                        ),
                    )
                    yield Button(
                        "Split", id="btn-featedit-split-row",
                        disabled=True,
                        tooltip=(
                            "Split the selected row at a position "
                            "you specify (default: midpoint)."
                        ),
                    )
                    yield Button(
                        "Merge", id="btn-featedit-merge-rows",
                        disabled=True,
                        tooltip=(
                            "Merge rows. Click col-0 (■/□) on the "
                            "rows you want, then Merge folds them "
                            "in order. With no marks, falls back "
                            "to merging the selected row with the "
                            "next one below."
                        ),
                    )
                    yield Button(
                        "- Remove", id="btn-featedit-remove-row",
                        disabled=True,
                        tooltip=(
                            "Remove the selected row (disabled "
                            "when only one row remains)."
                        ),
                    )
            yield Static("", id="featedit-status", markup=True)
            with Horizontal(id="featedit-btns"):
                yield Button("Edit", id="btn-featedit-edit",
                             variant="primary")
                yield Button("Save", id="btn-featedit-save",
                             variant="success", disabled=True)
                yield Button(
                    "Save to Feature Library",
                    id="btn-featedit-save-as-library",
                    tooltip=(
                        "Persist this feature (or its group, if "
                        "in one) as a reusable feature library "
                        "entry."
                    ),
                )
                yield Button(
                    "Group", id="btn-featedit-group",
                    tooltip=(
                        "Merge this feature into a shared group with "
                        "other features on the canvas (they move / "
                        "delete / save as a unit)."
                    ),
                )
                yield Button(
                    "Ungroup", id="btn-featedit-ungroup",
                    tooltip=(
                        "Drop this feature's group qualifier — just "
                        "this feature, or the whole group."
                    ),
                )
                yield Button("Cancel", id="btn-featedit-cancel")

    def on_mount(self) -> None:
        # Sweep #30 staleguard: capture whether this modal opened
        # on a CANVAS feature (vs a synth-editor-local feat). The
        # identity check on save only applies to the canvas case.
        self._on_canvas_at_open: bool = self._detect_on_canvas_at_open()
        self._refresh_color_swatch()
        self._refresh_table()
        self._refresh_row_button_state()

    def _refresh_table(self) -> None:
        """Repaint the members table from `self._members`. Same
        pattern as AddFeatureModal: defensive (silent no-op if
        the table isn't mounted yet) + clamped selected_idx.

        Sweep #30 fix: wrap in `_syncing_form` so the cursor
        moves fired during clear-then-add-row don't cascade into
        spurious form rebinding. (Even though FeatureEditModal
        doesn't currently wire a RowHighlighted handler, the
        guard is defensive in case a future change adds one.)

        Sweep #30 (2026-05-26 second pass): captures + restores
        `scroll_y` so structural mutations (add / split / merge
        / remove) don't snap the table back to the top —
        user-reported "scrolling to the top on each row add"."""
        try:
            tbl = self.query_one("#featedit-members-tbl", DataTable)
        except NoMatches:
            return
        # Sweep #32: drop marks for rows that no longer exist
        # (e.g. after a split / remove / merge replaced them).
        self._prune_marks()
        prev_scroll_y = float(getattr(tbl, "scroll_y", 0) or 0)
        self._syncing_form = True
        try:
            tbl.clear()
            for i, m in enumerate(self._members, 1):
                rs = int(m.get("rel_start", 0))
                re_ = int(m.get("rel_end", 0))
                ftype = str(m.get("feature_type") or "")[:24]
                label = str(m.get("label") or "")[:24]
                # 2026-05-26 bug-fix: `int(x or 1)` is wrong for
                # strand=0 (arrowless) — 0 is falsy so the `or 1`
                # silently coerces arrowless to forward. The
                # picker writes strand=0 and the table re-renders
                # it as "▶ top" — user reports "nothing happens"
                # when picking Arrowless. Use `int(x)` with a
                # None-only fallback to preserve 0.
                raw_strand = m.get("strand")
                try:
                    strand = (int(raw_strand)
                              if raw_strand is not None else 1)
                except (TypeError, ValueError):
                    strand = 1
                # Sweep #30 (2026-05-26): expand the strand cell
                # to make top/bottom legible at-a-glance rather
                # than just the numeric ±1. Arrowhead glyph keeps
                # the visual identity from the canvas + the
                # `top` / `bot` / `none` / `both` suffix names
                # the strand explicitly.
                strand_str = {
                    -1: "◀ bot",
                     0: "▒ none",
                     1: "▶ top",
                     2: "↔ both",
                }.get(strand, "▶ top")
                # Sweep #32: col-0 combines a mark glyph with
                # the row number. Click it to toggle the mark;
                # Merge then folds all marked rows together.
                mark_glyph = ("■" if id(m) in self._marked_ids
                              else "□")
                tbl.add_row(
                    f"{mark_glyph} {i}", str(rs), str(re_),
                    ftype, label, _members_color_cell(m), strand_str,
                )
            idx = max(0, min(self._selected_idx,
                             len(self._members) - 1))
            self._selected_idx = idx
            try:
                tbl.move_cursor(row=idx)
            except (IndexError, ValueError):
                pass
            try:
                tbl.scroll_to(y=prev_scroll_y, animate=False)
            except (AttributeError, TypeError):
                pass
        finally:
            self._syncing_form = False

    def _focus_members_table(self) -> None:
        """Return keyboard focus to the members table after a
        structural button is clicked. Keeps the user's hands on
        the keyboard for chained ops (split → split → split).
        Best-effort — defensive try/except so a click during
        tear-down doesn't propagate."""
        try:
            tbl = self.query_one("#featedit-members-tbl", DataTable)
            tbl.focus(scroll_visible=False)
        except (NoMatches, AttributeError):
            pass

    def _prune_marks(self) -> None:
        """Sweep #32: drop entries from `self._marked_ids` whose
        target row no longer exists in `self._members`. Called at
        the top of `_refresh_table` so split / merge / remove ops
        can't leave dangling marks (which would then silently
        reappear if a future row's dict happened to land on the
        recycled id())."""
        live = {id(m) for m in self._members}
        self._marked_ids = {mid for mid in self._marked_ids
                            if mid in live}

    def _toggle_mark(self, row_idx: int) -> None:
        """Sweep #32: flip the mark on `self._members[row_idx]`
        via dict identity. Identity-based instead of index-based
        so marks survive `_refresh_table` rebuilds + structural
        ops that may shift `row_idx`."""
        if not (0 <= row_idx < len(self._members)):
            return
        mid = id(self._members[row_idx])
        if mid in self._marked_ids:
            self._marked_ids.discard(mid)
        else:
            self._marked_ids.add(mid)
        self._refresh_table()
        self._focus_members_table()

    def on_key(self, event) -> None:
        """Space toggles the ★ mark on the highlighted member row — the
        app-wide convention. Gated on the members table being focused (so
        Space still types in text inputs) and on the same ops-only state the
        click path checks (`_editing_disabled_for_ops`)."""
        if event.key != "space":
            return
        try:
            t = self.query_one("#featedit-members-tbl", DataTable)
        except NoMatches:
            return
        if self.app.focused is not t or t.row_count == 0:
            return
        if not self._editing_disabled_for_ops():
            return
        row = t.cursor_row
        if 0 <= row < t.row_count:
            self._toggle_mark(row)
            event.stop()

    @on(DataTable.CellSelected, "#featedit-members-tbl")
    def _on_cell_selected(
        self, event: "DataTable.CellSelected",
    ) -> None:
        """Sweep #30: clicking (or pressing Enter on) a row's
        color cell opens the ColorPickerModal scoped to that row;
        clicking the label cell opens a rename prompt scoped to
        that row. Other columns: no-op. Requires Edit mode.

        Sweep #38 (2026-05-27): single physical clicks on a
        members-table cell fired `CellSelected` TWICE in real
        terminals (separate events ~50 ms apart, verified via
        the per-row picker open event log). The duplicate
        dispatch stacked two pickers on top of each other —
        user clicks Save in the top one, color applies, the
        SECOND picker (with the OLD `current_color` it was
        opened with) is still on the stack and looks like
        "the preview reverted to the previous color". User-
        reported repeatedly. Re-entrancy guard: if THIS modal
        is no longer the active screen (because we just pushed
        a picker / rename / strand modal on top), the second
        CellSelected dispatched to us is the duplicate fire —
        ignore it.
        """
        if self._syncing_form:
            return
        if self.app.screen is not self:
            return
        try:
            row_idx = int(event.coordinate.row)
            col_idx = int(event.coordinate.column)
        except (AttributeError, ValueError, TypeError):
            return
        if col_idx == _MEMBERS_TABLE_MARK_COL:
            if not self._editing_disabled_for_ops():
                return
            self._toggle_mark(row_idx)
        elif col_idx == _MEMBERS_TABLE_COLOR_COL:
            if not self._editing_disabled_for_ops():
                return
            self._open_per_row_color_picker(row_idx)
        elif col_idx == _MEMBERS_TABLE_LABEL_COL:
            if not self._editing_disabled_for_ops():
                return
            self._open_per_row_rename(row_idx)
        elif col_idx == _MEMBERS_TABLE_STRAND_COL:
            if not self._editing_disabled_for_ops():
                return
            self._open_per_row_strand_picker(row_idx)

    def _open_per_row_strand_picker(self, row_idx: int) -> None:
        """Push `StrandPickerModal` scoped to row `row_idx`. On
        confirm, the new strand goes to that row only.

        2026-05-26 bug-fix: when the picked row is the SELECTED
        row (the one the form fields bind to on save), also sync
        the form's strand RadioSet so Save's payload-build picks
        up the new strand. Without this sync, the picker writes
        to `self._members[selected_idx].strand` but Save reads
        the form's strand for that row → per-row pick is
        silently overwritten by the form's stale value. User-
        reported: "when i click one of the arrow choices, nothing
        saves or the segment list is stale"."""
        if not (0 <= row_idx < len(self._members)):
            return
        m = self._members[row_idx]
        target_id = id(m)
        current_strand = _coerce_strand(m.get("strand"))

        def _on_picked(result) -> None:
            if not isinstance(result, dict):
                return
            new_strand = result.get("strand")
            if (not isinstance(new_strand, int)
                    or new_strand not in (-1, 0, 1, 2)):
                return
            # 2026-05-26 staleness fix: identity-match the row
            # in case Add Row / Split / Merge / Remove shifted
            # `row_idx` between picker-open and confirm. See
            # `_open_per_row_color_picker` for the same pattern.
            current_idx = next(
                (i for i, mm in enumerate(self._members)
                 if id(mm) == target_id),
                None,
            )
            if current_idx is None:
                self._set_status(
                    "[yellow]Source row was changed before the "
                    "arrow pick confirmed — discarded.[/yellow]"
                )
                return
            self._members[current_idx]["strand"] = new_strand
            # Sync the form's strand RadioSet if the picked row
            # is the one Save's form-edits apply to. Wrap in
            # `_syncing_form` so the radio's Changed event doesn't
            # echo back into the row (defensive — the radio's
            # handler isn't wired in FeatureEditModal but a future
            # change might add one).
            if current_idx == self._selected_idx:
                self._syncing_form = True
                try:
                    for sid, want in (
                        ("#featedit-strand-fwd",  new_strand == 1),
                        ("#featedit-strand-rev",  new_strand == -1),
                        ("#featedit-strand-none", new_strand == 0),
                        ("#featedit-strand-both", new_strand == 2),
                    ):
                        try:
                            self.query_one(
                                sid, RadioButton,
                            ).value = want
                        except NoMatches:
                            pass
                finally:
                    self._syncing_form = False
            self._refresh_table()
            self._focus_members_table()

        self.app.push_screen(
            StrandPickerModal(
                current_strand=current_strand,
                row_idx=row_idx,
            ),
            callback=_on_picked,
        )

    def _open_per_row_rename(self, row_idx: int) -> None:
        """Push a rename prompt for the row at `row_idx`. Empty
        label allowed (clears the row's label).

        2026-05-26 bug-fix: when the renamed row is the SELECTED
        row, also sync the form's Name input so Save's payload-
        build picks up the new label."""
        if not (0 <= row_idx < len(self._members)):
            return
        current_label = str(
            self._members[row_idx].get("label") or "",
        )

        def _on_named(result) -> None:
            if not isinstance(result, dict):
                return
            new_label = result.get("name")
            if not isinstance(new_label, str):
                return
            if not (0 <= row_idx < len(self._members)):
                return
            self._members[row_idx]["label"] = new_label
            # Sync form-level Name input if the renamed row is
            # the one Save's form-edits apply to. Wrap in
            # `_syncing_form` defensively.
            if row_idx == self._selected_idx:
                self._syncing_form = True
                try:
                    self.query_one(
                        "#featedit-name", Input,
                    ).value = new_label
                except NoMatches:
                    pass
                finally:
                    self._syncing_form = False
            self._refresh_table()
            self._focus_members_table()

        self.app.push_screen(
            GroupNamePromptModal(
                default_name=current_label,
                title=" Rename feature segment ",
                prompt=(
                    f"New label for row {row_idx + 1} "
                    f"(empty clears the label):"
                ),
                placeholder="e.g. BsaI cut site",
                allow_empty=True,
            ),
            callback=_on_named,
        )

    def _open_per_row_color_picker(self, row_idx: int) -> None:
        """Push ColorPickerModal scoped to row `row_idx`. On
        confirm the picked colour goes ONLY to that row's
        `color` field. Save dispatches it as part of the
        members payload; cancel abandons it (modal-local). Pick
        "Auto" to clear back to None (palette default).

        2026-05-26 bug-fix: when the picked row is the SELECTED
        row (the one Save's form-edits apply to), also sync
        `self._color` + the form's color swatch. Without this
        sync, the picker writes to `self._members[selected].color`
        but Save reads the form's `self._color` for that row →
        per-row pick silently overwritten by the form's stale
        value.

        2026-05-26 staleness fix: capture the row dict's
        identity (`id(m)`) at picker-open time. On dismiss,
        re-find the row by identity instead of trusting
        `row_idx` blindly. If the user did Remove Row / Split
        / Merge between open and confirm, the captured index
        could now point at a DIFFERENT row — without the
        identity check we'd silently re-colour the wrong
        member. Match-not-found = silent no-op (the row that
        was being edited is gone)."""
        if not (0 <= row_idx < len(self._members)):
            return
        m = self._members[row_idx]
        target_id = id(m)
        current_col = m.get("color")
        if not isinstance(current_col, str) or not current_col.strip():
            current_col = None
        ftype = m.get("feature_type") or "misc_feature"

        def _on_picked(result) -> None:
            if not isinstance(result, dict):
                return
            new_col = result.get("color")
            new_col = (new_col
                       if isinstance(new_col, str) and new_col.strip()
                       else None)
            # Re-find the target row by identity — see docstring.
            current_idx = next(
                (i for i, mm in enumerate(self._members)
                 if id(mm) == target_id),
                None,
            )
            if current_idx is None:
                self._set_status(
                    "[yellow]Source row was changed before the "
                    "colour pick confirmed — discarded.[/yellow]"
                )
                return
            self._members[current_idx]["color"] = new_col
            if result.get("set_default") and new_col:
                defaults = _load_feature_colors()
                defaults[ftype] = new_col
                try:
                    _save_feature_colors(defaults)
                except (OSError, RuntimeError) as exc:
                    _notify_save_failure(
                        self.app, "Feature colors", exc,
                    )
            # Sync form-level color if the picked row is the one
            # Save's form-edits apply to.
            if current_idx == self._selected_idx:
                self._color = new_col
                try:
                    self._refresh_color_swatch()
                except (AttributeError, NoMatches):
                    pass
            self._refresh_table()
            self._focus_members_table()

        self.app.push_screen(
            ColorPickerModal(ftype, _safe_color_for_picker(current_col)),
            callback=_on_picked,
        )

    def _refresh_row_button_state(self) -> None:
        """Enable / disable the table-row buttons.

        Sweep #30 (2026-05-26): all four structural buttons gate
        on Edit mode (`self._editing`) — they're grayed out in
        read-only mode so a stray click can't dismiss the modal +
        mutate the canvas. Additional row-count conditions stack
        on top: Merge / Remove also need ≥ 2 rows (a 1-row solo
        has nothing to merge / nothing safe to remove). Save-as-
        library stays available in read-only mode (it persists
        the current state to the library — non-mutating to the
        canvas)."""
        n = len(self._members)
        editing = bool(self._editing)
        for sel, ok in (
            ("#btn-featedit-add-row",     editing),
            ("#btn-featedit-split-row",   editing and n >= 1),
            ("#btn-featedit-merge-rows",  editing and n >= 2),
            ("#btn-featedit-remove-row",  editing and n >= 2),
        ):
            try:
                self.query_one(sel, Button).disabled = not ok
            except NoMatches:
                pass

    # ── Helpers ─────────────────────────────────────────────────────────────

    def _set_editing(self, on: bool) -> None:
        """Toggle the form between read-only and editable. Disables /
        enables every input + the color buttons, swaps Edit/Save
        button visibility, and switches the notes box between the
        Markdown viewer (clickable URLs) and the TextArea editor.

        Sweep #30: also refresh the members-table buttons since
        they gate on `_editing` for the structural ops (Add /
        Split / Merge / Remove)."""
        self._editing = on
        for sel in ("#featedit-name", "#featedit-type", "#featedit-strand",
                     "#btn-featedit-color", "#btn-featedit-color-clear"):
            try:
                self.query_one(sel).disabled = not on
            except NoMatches:
                pass
        self._refresh_row_button_state()
        # Hide the Edit button once we've entered edit mode; show
        # Save instead. The user can still bail with Cancel.
        try:
            self.query_one("#btn-featedit-edit",
                            Button).display = not on
            self.query_one("#btn-featedit-save",
                            Button).disabled = not on
        except NoMatches:
            pass
        # Notes box: Markdown widget for view, TextArea for edit.
        # Both are mounted in compose() so we just toggle their
        # `.display` property — keeps state consistent without
        # remount thrash.
        try:
            self.query_one("#featedit-notes-md").display = not on
            self.query_one("#featedit-notes-edit").display = on
        except NoMatches:
            pass
        # On entering edit mode, focus the name field so keyboard
        # users can start typing immediately.
        if on:
            try:
                self.query_one("#featedit-name", Input).focus()
            except NoMatches:
                pass

    def _refresh_color_swatch(self) -> None:
        try:
            swatch = self.query_one("#featedit-color-swatch", Static)
        except NoMatches:
            return
        ftype = self._feat.get("type", "misc_feature")
        try:
            sel = self.query_one("#featedit-type", Select)
            if isinstance(sel.value, str) and sel.value:
                ftype = sel.value
        except NoMatches:
            pass
        synth = {"feature_type": ftype, "color": self._color}
        resolved = _resolve_feature_color(synth)
        t = Text()
        t.append("███ ", style=resolved)
        if self._color:
            t.append(resolved)
        else:
            t.append(f"Auto → {resolved}", style="dim")
        swatch.update(t)

    def _read_strand(self) -> int:
        for sid, val in (("#featedit-strand-fwd",  1),
                         ("#featedit-strand-rev",  -1),
                         ("#featedit-strand-none", 0),
                         ("#featedit-strand-both", 2)):
            try:
                if self.query_one(sid, RadioButton).value:
                    return val
            except NoMatches:
                pass
        return self._feat.get("strand", 0)

    # ── Button handlers ─────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-featedit-edit")
    def _on_edit(self) -> None:
        self._set_editing(True)
        try:
            self.query_one("#featedit-status", Static).update(
                "[dim]Edit mode — make changes and press Save.[/dim]"
            )
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-featedit-cancel")
    def _on_cancel(self) -> None:
        self.dismiss(None)

    @on(Button.Pressed, "#btn-featedit-save")
    def _on_save(self) -> None:
        if not self._editing:
            return
        try:
            label = self.query_one("#featedit-name", Input).value
            ftype = self.query_one("#featedit-type", Select).value
            notes = self.query_one("#featedit-notes-edit", TextArea).text
        except NoMatches:
            return
        new_label = _sanitize_label(label, max_len=200)
        new_type  = _sanitize_feat_type(str(ftype) if ftype else "")
        if not new_type:
            try:
                self.query_one("#featedit-status", Static).update(
                    "[red]Invalid feature type.[/red]"
                )
            except NoMatches:
                pass
            return
        new_strand = self._read_strand()
        # Sweep #30: if the user has split / added / removed rows
        # in the table, dispatch a `split` action with the full
        # members list. Otherwise dispatch the legacy `save`
        # action with just the field edits. The split path
        # carries the structural change through the existing
        # `_apply_feature_split` primitive.
        #
        # 2026-05-26 bug-fix: the multi-row branch also fires
        # when the modal opened on an existing GROUP and the
        # user removed rows down to a single member. Without
        # this, "Remove row" → Save falls through to the 1-row
        # legacy "save" path which only mutates the cursor
        # feature in-place — the other (now-removed) group
        # members linger on the canvas. Treat any in-group
        # modal as multi-row at dispatch time so the
        # `edit_group` swap runs and the deleted siblings
        # actually leave the record.
        opened_in_group = bool(
            str(self._feat.get("feature_group") or "").strip()
        )
        if len(self._members) >= 2 or opened_in_group:
            # Sweep #30 hardening (atomic save): build the
            # payload members list WITHOUT mutating `self._members`
            # — apply the form's current field edits to the
            # SELECTED row (the cursor feature, set on init by
            # `_find_self_idx`) inline in the comprehension. If
            # `_validate_group_members` raises (somehow — shouldn't,
            # since the in-modal state is already validated), no
            # state has changed and the user can correct and retry.
            #
            # 2026-05-26 bug-fix: previously hardcoded to row 0,
            # which CLOBBERED per-row strand/color/label picks on
            # row 0 with the form's stale values AND landed form
            # edits on the wrong row when the cursor feature
            # wasn't row 0 of the group (user-reported: "nothing
            # saves or the segment list is stale" after picking
            # a per-row arrow).
            edit_idx = max(0, min(self._selected_idx,
                                    len(self._members) - 1))
            payload_members: list[dict] = []
            for i, m in enumerate(self._members):
                if i == edit_idx:
                    payload_members.append({
                        "rel_start":   m["rel_start"],
                        "rel_end":     m["rel_end"],
                        "feature_type": new_type,
                        "label":       new_label,
                        "color":       self._color,
                        "strand":      new_strand,
                        "qualifiers":  dict(m.get("qualifiers") or {}),
                        "description": m.get("description", ""),
                    })
                else:
                    # 2026-05-26 bug-fix: `int(x or 1)` is wrong
                    # for strand=0 (arrowless) — 0 is falsy so
                    # the `or 1` silently coerces arrowless to
                    # forward on every non-edit-idx row at save.
                    # User reports "Arrowless picker does
                    # nothing" because the row's strand snaps
                    # back to forward when Save reads the row.
                    row_strand_raw = m.get("strand")
                    try:
                        row_strand = (
                            int(row_strand_raw)
                            if row_strand_raw is not None
                            else 1
                        )
                    except (TypeError, ValueError):
                        row_strand = 1
                    if row_strand not in (-1, 0, 1, 2):
                        row_strand = 1
                    payload_members.append({
                        "rel_start":   m["rel_start"],
                        "rel_end":     m["rel_end"],
                        "feature_type": m.get("feature_type",
                                              "misc_feature"),
                        "label":       m.get("label", ""),
                        "color":       m.get("color"),
                        "strand":      row_strand,
                        "qualifiers":  dict(m.get("qualifiers") or {}),
                        "description": m.get("description", ""),
                    })
            # Validate before dispatch so the app side never has
            # to handle a malformed split payload (atomic — no
            # partial save on bad input).
            #
            # 2026-05-26 bug-fix: derive the validator's
            # `sequence_len` from `max(rel_end)` of the current
            # payload, NOT from `_members_span_int()` (the
            # opened-feature's span). Mirrors the __init__
            # pattern. When the modal opened on a feature that's
            # ONE member of a multi-segment group,
            # `_members_span_int()` returns just that feature's
            # length, so every other group member whose
            # `rel_end` exceeds it trips the half-open check →
            # ValueError → Save silently no-ops → the user's
            # per-row colour / strand / label picks evaporate.
            try:
                group_span = max(
                    int(m.get("rel_end", 0))
                    for m in payload_members
                )
                _validate_group_members(
                    payload_members, max(1, group_span),
                )
            except ValueError as exc:
                try:
                    self.query_one(
                        "#featedit-status", Static,
                    ).update(f"[red]{exc}[/red]")
                except NoMatches:
                    pass
                return
            # Sweep #30: if the modal opened on a feature that's
            # already in a group (carries `feature_group=<uuid>`),
            # dispatch `action="edit_group"` so the app's
            # `_apply_group_edit` replaces ALL members of the
            # existing group atomically — preserves the group's
            # identity. Otherwise dispatch the legacy `split`
            # action (1 → N replacement, fresh group id).
            existing_gid = str(
                self._feat.get("feature_group") or "",
            ).strip()
            if existing_gid:
                self.dismiss({
                    "action":   "edit_group",
                    "idx":      self._idx,
                    "group_id": existing_gid,
                    "members":  payload_members,
                })
                return
            self.dismiss({
                "action":  "split",
                "idx":     self._idx,
                "members": payload_members,
            })
            return
        # 1 row → regular field-edit save (legacy path). Sweep #29:
        # explicit action tag so the dispatch callback routes
        # cleanly. Receivers that haven't been updated to dispatch
        # on `action` see the same keys as before plus a harmless
        # extra.
        self.dismiss({
            "action": "save",
            "idx":    self._idx,
            "label":  new_label,
            "type":   new_type,
            "strand": new_strand,
            "color":  self._color,
            # Sanitize notes the same way labels are sanitized — strip
            # dangerous control bytes (preserving \t/\n so paragraphs
            # survive) and cap at 8 KB so adversarial pastes can't
            # bloat the `.gb` export or stall the Markdown parser.
            "notes":  _sanitize_note(notes),
        })

    # ── Sweep #30 unified members operations ────────────────────

    @on(Button.Pressed, "#btn-featedit-split-row")
    def _on_split_row(self) -> None:
        """Open `SplitPositionPromptModal` for the selected row;
        on confirm, mutate `self._members` + refresh the table.
        Sweep #30 (2026-05-26): no longer dismisses the modal —
        structural changes accumulate in-memory and commit ONCE
        on Save. User-reported: "click add row just exits the
        modal. i just want to see the row addition in realtime
        in the same modal without exit"."""
        if not self._editing_disabled_for_ops():
            return
        if not (0 <= self._selected_idx < len(self._members)):
            return
        m = self._members[self._selected_idx]
        rs = int(m["rel_start"])
        re_ = int(m["rel_end"])
        if rs + 1 >= re_:
            self._set_status(
                f"[red]Row width {re_ - rs} too small to split "
                f"(need ≥ 2 bp).[/red]"
            )
            return
        if len(self._members) >= _MAX_GROUP_MEMBERS:
            self._set_status(
                f"[red]Cap reached: {_MAX_GROUP_MEMBERS} members "
                f"max — cannot split further.[/red]"
            )
            return

        def _on_pos(result) -> None:
            if not isinstance(result, dict):
                return
            pos = result.get("pos")
            if not isinstance(pos, int):
                return
            try:
                self._members = _split_member(
                    self._members, self._selected_idx, pos,
                    tail_strand=0,
                )
            except ValueError as exc:
                self._set_status(f"[red]Split failed: {exc}[/red]")
                return
            self._refresh_table()
            self._refresh_row_button_state()
            self._set_status("")
            self._focus_members_table()

        try:
            self.app.push_screen(
                SplitPositionPromptModal(rs, re_),
                callback=_on_pos,
            )
        except ValueError as exc:
            self._set_status(f"[red]{exc}[/red]")

    @on(Button.Pressed, "#btn-featedit-merge-rows")
    def _on_merge_rows(self) -> None:
        """Merge marked rows together (sweep #32), or fall back to
        merging the selected row with the next one (legacy
        pair-merge). Mutates `self._members` in place + refreshes
        the table — Save commits all accumulated changes."""
        if not self._editing_disabled_for_ops():
            return
        n = len(self._members)
        if n < 2:
            self._set_status("[red]Need at least 2 rows.[/red]")
            return
        # Sweep #32: prefer marked-rows merge when ≥ 2 marks
        # are set. `_merge_members` validates adjacency in
        # `rel_start` order; a non-contiguous mark set raises
        # ValueError with a clear message. Idxs are gathered in
        # current-list order; the validator re-sorts by
        # rel_start so the metadata-winner row is the leftmost
        # marked one (predictable, not click-order).
        marked_idxs = [
            i for i, m in enumerate(self._members)
            if id(m) in self._marked_ids
        ]
        if len(marked_idxs) >= 2:
            idxs = marked_idxs
            using_marks = True
        else:
            if self._selected_idx >= n - 1:
                self._set_status(
                    "[red]Move up one row first — cursor is on "
                    "the last row, and no rows are marked. "
                    "Click col-0 (the ■/□ glyph) on the rows "
                    "you want to merge.[/red]"
                )
                return
            idxs = [self._selected_idx, self._selected_idx + 1]
            using_marks = False
        try:
            self._members = _merge_members(self._members, idxs)
        except ValueError as exc:
            self._set_status(f"[red]Merge failed: {exc}[/red]")
            return
        # Merged row lands at the lowest involved index after
        # `_merge_members` re-sorts; marks pointing at consumed
        # rows are dropped by `_prune_marks` on refresh.
        self._selected_idx = min(idxs)
        # Sweep #32: clear marks after a successful merge —
        # the rows they referenced are gone, and chained
        # operations should require an explicit re-mark.
        self._marked_ids.clear()
        self._refresh_table()
        self._refresh_row_button_state()
        merge_msg = (
            f"Merged {len(idxs)} marked rows."
            if using_marks else ""
        )
        self._set_status(f"[dim]{merge_msg}[/dim]" if merge_msg else "")
        self._focus_members_table()
        # Sweep #30: post-merge rename prompt — same UX as
        # AddFeatureModal's merge so the user can immediately
        # rename the fused segment to reflect the combined
        # meaning.
        self._open_per_row_rename(self._selected_idx)

    @on(Button.Pressed, "#btn-featedit-add-row")
    def _on_add_row(self) -> None:
        """Split the selected row at its midpoint → two contiguous
        sub-features (no overlap, no gap). Mutates `self._members`
        in place + refreshes the table; Save commits."""
        if not self._editing_disabled_for_ops():
            return
        if len(self._members) >= _MAX_GROUP_MEMBERS:
            self._set_status(
                f"[red]Cap reached: {_MAX_GROUP_MEMBERS} members.[/red]"
            )
            return
        if not (0 <= self._selected_idx < len(self._members)):
            return
        m = self._members[self._selected_idx]
        rs = int(m["rel_start"])
        re_ = int(m["rel_end"])
        if rs + 1 >= re_:
            self._set_status(
                f"[red]Row width {re_ - rs} too small to split — "
                f"need at least 2 bp.[/red]"
            )
            return
        # Sweep #30: tail defaults to arrowless on new segment.
        mid = (rs + re_) // 2
        try:
            self._members = _split_member(
                self._members, self._selected_idx, mid,
                tail_strand=0,
            )
        except ValueError as exc:
            self._set_status(f"[red]Split failed: {exc}[/red]")
            return
        self._refresh_table()
        self._refresh_row_button_state()
        self._set_status("")
        self._focus_members_table()

    @on(Button.Pressed, "#btn-featedit-remove-row")
    def _on_remove_row(self) -> None:
        """Remove the selected row. Mutates `self._members` in
        place + refreshes the table; Save commits."""
        if not self._editing_disabled_for_ops():
            return
        n = len(self._members)
        if n < 2:
            self._set_status(
                "[red]Cannot remove the last row.[/red]"
            )
            return
        if not (0 <= self._selected_idx < n):
            return
        new_members = list(self._members)
        new_members.pop(self._selected_idx)
        self._members = new_members
        self._selected_idx = min(
            self._selected_idx, len(self._members) - 1,
        )
        self._refresh_table()
        self._refresh_row_button_state()
        self._set_status("")
        self._focus_members_table()

    @on(Button.Pressed, "#btn-featedit-save-as-library")
    def _on_save_as_library(self) -> None:
        """Persist the current feature (or its group, if it has
        one) as a reusable feature library entry. Dismisses with
        `action="save_group_as_entry"` so the existing app
        dispatcher handles the persist."""
        if self._editing:
            self._set_status(
                "[yellow]Press Save (or Cancel) before persisting "
                "to library.[/yellow]"
            )
            return
        gid = str(self._feat.get("feature_group") or "")
        default_name = (
            f"group-{gid[:8]}" if gid
            else (self._feat.get("label")
                  or self._feat.get("type")
                  or "feature")
        )

        def _on_name(result) -> None:
            if not isinstance(result, dict):
                return
            name = result.get("name")
            if not isinstance(name, str) or not name.strip():
                return
            self.dismiss({
                "action": "save_group_as_entry",
                "idx":    self._idx,
                "group_id": gid,
                "name":   name.strip(),
            })

        self.app.push_screen(
            GroupNamePromptModal(default_name=str(default_name)),
            callback=_on_name,
        )

    @on(Button.Pressed, "#btn-featedit-group")
    def _on_group_with(self) -> None:
        """Push the multi-select picker; on confirm, dismiss with
        action="group" so the app stamps a shared feature_group on this
        feature + the picked others (groups merge — see
        `_apply_feature_group_with`)."""
        if self._editing:
            self._set_status(
                "[yellow]Press Save (or Cancel) before grouping.[/yellow]"
            )
            return

        def _on_picked(result) -> None:
            if not isinstance(result, dict):
                return
            other_idxs = result.get("other_idxs") or []
            if not other_idxs:
                return
            self.dismiss({
                "action":     "group",
                "idx":        self._idx,
                "other_idxs": other_idxs,
            })

        self.app.push_screen(
            GroupFeaturePickerModal(self._idx),
            callback=_on_picked,
        )

    @on(Button.Pressed, "#btn-featedit-ungroup")
    def _on_ungroup(self) -> None:
        """If this feature is in a group, ask the scope (just this vs the
        whole group) via UngroupScopeModal, then dismiss with
        action="ungroup" for `_apply_feature_ungroup`."""
        if self._editing:
            self._set_status(
                "[yellow]Press Save (or Cancel) before ungrouping.[/yellow]"
            )
            return
        gid = str(self._feat.get("feature_group") or "")
        if not gid:
            self._set_status(
                "[yellow]This feature isn't in a group.[/yellow]"
            )
            return

        def _on_scope(result) -> None:
            if not isinstance(result, dict):
                return
            scope = result.get("scope")
            if scope not in ("this", "whole"):
                return
            self.dismiss({
                "action":   "ungroup",
                "idx":      self._idx,
                "scope":    scope,
                "group_id": gid,
            })

        self.app.push_screen(
            UngroupScopeModal(gid),
            callback=_on_scope,
        )

    def _editing_disabled_for_ops(self) -> bool:
        """Structural ops (split/merge/add/remove) gate on Edit
        mode — the user must explicitly press **Edit** before any
        canvas-mutating button does anything. This matches the
        existing convention for the form fields (name / type /
        strand / color / notes also require Edit), and prevents
        an accidental click on Add / Split / Merge from
        immediately dismissing the modal + mutating the record.

        Sweep #30 fix (2026-05-26): inverted from the original
        "refuse when editing" → "refuse when NOT editing" after
        user-report ("buttons are available without pressing
        edit and takes user to an escape sequence")."""
        if not self._editing:
            self._set_status(
                "[yellow]Press Edit first to enable structural "
                "changes.[/yellow]"
            )
            return False
        return True

    def _members_span(self) -> int:
        """Bp length of the underlying feature span (for solo) or
        group anchor (for group). Used by add-row to compute the
        new row's max rel_end."""
        start = int(self._feat.get("start", 0))
        end   = int(self._feat.get("end",   0))
        return _feat_len(start, end, self._total) or 0

    def _set_status(self, msg: str) -> None:
        try:
            self.query_one("#featedit-status", Static).update(msg)
        except NoMatches:
            pass

    def dismiss(  # type: ignore[override]
        self, result=None,
    ):
        """[INV-50] dismiss-once guard. A rapid Save / Cancel
        double-click can fire the dispatch twice before the modal
        finishes tearing down — re-applying the edit to the
        canvas (or re-running the split primitive). The flag
        short-circuits the second call so each modal-open
        results in at most ONE commit.

        Sweep #30 (2026-05-26) also adds a feature-identity
        check on COMMIT paths: if the canvas feature at
        `self._idx` has been swapped (async work) between modal
        open and Save, refuse the dispatch and surface a status-
        line error rather than silently editing the wrong
        feature."""
        if self._dismissed:
            return None
        # Identity check applies only to COMMIT paths (those that
        # carry an `action` payload that will mutate the canvas).
        # Cancel / Esc dismiss with `None` — no canvas mutation,
        # so skip the check.
        if isinstance(result, dict) and result.get("action"):
            if not self._verify_idx_still_valid():
                self._set_status(
                    "[red]Feature changed under the modal "
                    "(possibly via background work or a sibling "
                    "session). Re-open the feature and re-edit "
                    "to be safe.[/red]"
                )
                return None
        self._dismissed = True
        return super().dismiss(result)

    @on(Button.Pressed, "#btn-featedit-color")
    def _on_pick_color(self) -> None:
        if not self._editing:
            return
        ftype = self._feat.get("type", "misc_feature")
        try:
            sel = self.query_one("#featedit-type", Select)
            if isinstance(sel.value, str) and sel.value:
                ftype = sel.value
        except NoMatches:
            pass

        def _on_picked(result) -> None:
            # ColorPickerModal dismisses with either `None` (the
            # user cancelled) or `{"color": "#xxxxxx",
            # "set_default": False}` (Save) / `{"color":
            # "#xxxxxx", "set_default": True}` (Save & set as
            # default). Pre-2026-05-26 this callback expected a
            # bare hex string and treated the WHOLE DICT as the
            # color, so the swatch + save payload stored a dict
            # ("color: {'color': '#xxx', 'set_default': False}")
            # which the renderer then couldn't parse — the user's
            # color pick visibly did nothing. Mirrors
            # AddFeatureModal._on_color so create + edit can't
            # drift.
            if not isinstance(result, dict):
                return
            new_col = result.get("color")
            self._color = (new_col
                           if isinstance(new_col, str) and new_col
                           else None)
            if (result.get("set_default")
                    and isinstance(new_col, str) and new_col):
                defaults = _load_feature_colors()
                defaults[ftype] = new_col
                try:
                    _save_feature_colors(defaults)
                except (OSError, RuntimeError) as exc:
                    _notify_save_failure(
                        self.app, "Feature colors", exc,
                    )
            self._refresh_color_swatch()

        # Pass the user's EXPLICIT color (hex) only — for features
        # without a `/ApEinfo_*color` qualifier, `PlasmidMap._parse`
        # falls back to `_FEATURE_PALETTE[idx % …]`, which is
        # `color(N)` format. Rich's preview render in the picker
        # blows up on `color(N)` (the parens collide with the
        # markup lexer), so collapse to None — the picker then
        # opens with Auto preselected, exactly like AddFeatureModal
        # when there's no prior pick.
        current = (self._color
                   if (isinstance(self._color, str)
                       and self._color.startswith("#"))
                   else None)
        self.app.push_screen(ColorPickerModal(ftype, current),
                              _on_picked)

    @on(Button.Pressed, "#btn-featedit-color-clear")
    def _on_color_auto(self) -> None:
        if not self._editing:
            return
        self._color = None
        self._refresh_color_swatch()

    @on(Select.Changed, "#featedit-type")
    def _on_type_changed(self, _event: Select.Changed) -> None:
        self._refresh_color_swatch()

    def action_cancel(self) -> None:
        self.dismiss(None)


# ── New plasmid modal ─────────────────────────────────────────────────────────

_DEFAULT_LIB_ANNOT_MAX_HITS = 5_000


def _annotate_seq_from_feature_library(
    sequence: str,
    *,
    circular: bool = False,
    min_overlap: int = 12,
    max_hits: int = _DEFAULT_LIB_ANNOT_MAX_HITS,
) -> "list[dict]":
    """Scan ``sequence`` for substring matches against the feature library
    on both strands. Returns a list of feature dicts with keys
    ``{name, feature_type, start, end, strand, sequence, color, qualifiers,
       description}`` ready for ``SeqFeature`` construction.

    Pure substring match (no mismatches, no gaps). Library entries shorter
    than ``min_overlap`` are skipped — short hits balloon false-positive
    counts on a multi-kb paste. Wrap detection on circular templates is
    handled by appending ``seq[:max_lib_len]`` so a hit straddling 0 lands
    once with ``end > total`` and the caller can lower it back into the
    canonical range.

    The library is loaded once per call (caller's job to debounce); the
    forward/reverse-complement of each library entry is computed once and
    re-used across all positions.

    ``max_hits`` caps the result list so a chromosome-sized paste with a
    short common library entry can't blow up memory or render time.
    Returning **early** (rather than truncating after the fact) means
    the inner loops also short-circuit. Default 5,000 hits is roughly
    "every common gene matched ~5× across a 100 kb plasmid" — well past
    any realistic interactive use, but still bounded.
    """
    seq_u = (sequence or "").upper()
    n = len(seq_u)
    if n == 0:
        return []
    entries = _load_features()
    if not entries:
        return []
    # Pre-compute forward + RC for every library entry so the inner loop
    # is just `str.find`.
    prepared: list[tuple[str, str, str, int, str, str, dict, str, str]] = []
    for e in entries:
        s = (e.get("sequence", "") or "").upper()
        if len(s) < min_overlap:
            continue
        prepared.append((
            s,
            _rc(s),
            str(e.get("name", "") or "feat"),
            int(e.get("strand", 1) or 1),
            str(e.get("feature_type", "") or "misc_feature"),
            str(e.get("color", "") or ""),
            dict(e.get("qualifiers") or {}),
            str(e.get("description", "") or ""),
            s,  # original sequence for stamping on the new feature dict
        ))
    if not prepared:
        return []
    # On circular templates, allow hits to span the origin: scan against
    # `seq + seq[:longest_entry-1]` so a 200 bp feature crossing 0/end
    # finds a single contiguous hit. Trim back to canonical range later.
    longest = max(len(p[0]) for p in prepared)
    scan_seq = seq_u + (seq_u[: longest - 1] if circular and longest > 1 else "")
    found: list[dict] = []
    seen_keys: set[tuple[str, int, int, int]] = set()
    for entry in prepared:
        if len(found) >= max_hits:
            break
        s_fwd, s_rev, nm, lib_strand, ftype, col, quals, desc, raw = entry
        slen = len(s_fwd)
        # Forward strand hits.
        i = scan_seq.find(s_fwd)
        while i != -1:
            start = i % n
            end = (i + slen)
            # Wrapped hit: store as compound (start..n) + (0..end-n) is
            # the SeqFeature concern; here we just record (start, end)
            # with end possibly > n so callers know to wrap it.
            key = (nm, start, end, 1)
            if key not in seen_keys:
                seen_keys.add(key)
                found.append({
                    "name": nm,
                    "feature_type": ftype,
                    "start": start,
                    "end": end,
                    "strand": 1 if lib_strand >= 0 else -1,
                    "sequence": raw,
                    "color": col,
                    "qualifiers": dict(quals),
                    "description": desc,
                })
                if len(found) >= max_hits:
                    return found
            i = scan_seq.find(s_fwd, i + 1)
        # Reverse-complement hits (different strand).
        if s_rev == s_fwd:
            # palindromic library entry — already counted on the fwd scan.
            continue
        i = scan_seq.find(s_rev)
        while i != -1:
            start = i % n
            end = (i + slen)
            key = (nm, start, end, -1)
            if key not in seen_keys:
                seen_keys.add(key)
                found.append({
                    "name": nm,
                    "feature_type": ftype,
                    "start": start,
                    "end": end,
                    "strand": -1,
                    "sequence": raw,
                    "color": col,
                    "qualifiers": dict(quals),
                    "description": desc,
                })
                if len(found) >= max_hits:
                    return found
            i = scan_seq.find(s_rev, i + 1)
    return found


# Pre-compiled — `_on_apply_prefix` re-runs this on every Apply
# click and the primer-save path also validates against the same
# alphabet. Module-level keeps the compilation cost off the hot
# path (Python's regex cache amortises this anyway, but explicit
# is clearer).
_PRIMER_IUPAC_RE = re.compile(r"[ACGTRYWSMKBDHVN]+")

# Defensive caps on primer-modal text inputs. The 5'-add-on prefix
# is a 6-7 bp restriction site plus an optional spacer — anything
# beyond ~60 bp doesn't fit a realistic cloning primer; 100 gives
# users headroom for a long Gibson overhang while still rejecting
# adversarial / accidental large pastes before the regex even
# runs. The full-sequence cap matches the longest commercial
# oligo synthesis (Twist's 300-mer service) with comfortable
# headroom; a primer longer than this is almost certainly a gene
# fragment pasted into the wrong field.
_PRIMER_PREFIX_MAX_LEN = 100
_PRIMER_SEQ_MAX_LEN    = 500




_PRIMER_5P_RE_SITES: list[tuple[str, str]] = [
    # (display label, recognition site to prepend). Curated subset
    # of common cloning enzymes — full NEB catalog (~200) is too
    # cluttered for a dropdown. The leading entry is the "no site"
    # sentinel so the user can clear a previous selection.
    ("(none)",                       ""),
    ("EcoRI    · GAATTC",            "GAATTC"),
    ("BamHI    · GGATCC",            "GGATCC"),
    ("HindIII  · AAGCTT",            "AAGCTT"),
    ("XhoI     · CTCGAG",            "CTCGAG"),
    ("SacI     · GAGCTC",            "GAGCTC"),
    ("KpnI     · GGTACC",            "GGTACC"),
    ("SalI     · GTCGAC",            "GTCGAC"),
    ("PstI     · CTGCAG",            "CTGCAG"),
    ("NotI     · GCGGCCGC",          "GCGGCCGC"),
    ("SpeI     · ACTAGT",            "ACTAGT"),
    ("XbaI     · TCTAGA",            "TCTAGA"),
    ("NcoI     · CCATGG",            "CCATGG"),
    ("NdeI     · CATATG",            "CATATG"),
    ("BsaI     · GGTCTC (Type IIS)", "GGTCTC"),
    ("BsmBI    · CGTCTC (Type IIS)", "CGTCTC"),
    ("BbsI     · GAAGAC (Type IIS)", "GAAGAC"),
    ("SapI     · GCTCTTC (Type IIS)", "GCTCTTC"),
]


# Hard ceiling on the preview window width. The CSS scrollbar
# handles real-world overruns (long flap + context) gracefully,
# but a malformed feat with bound_len in the hundreds of kb would
# otherwise allocate a massive per-cell list on every keystroke.
# 2000 cells covers a 500-bp primer + 500-bp bound region with
# ample context on both sides — well past any biologically
# meaningful preview.
_PRIMER_PREVIEW_MAX_WIDTH = 2000


def _build_primer_preview(template: str, primer_seq: str,
                            bound_start: int, bound_end: int,
                            strand: int, color: str,
                            context_bp: int = 12) -> Text:
    """Build a 4-row mini-rendering of a primer (flap + bound)
    aligned to its template binding site, mirroring the seq panel's
    bound-bar + flap-row visualisation.

    Forward primer (strand >= 0):
      row 0: flap bases (right-justified to bound start, primer bg)
      row 1: bound bases + ► arrow (primer bg)
      row 2: top strand window
      row 3: bottom strand (complement, dim)

    Reverse primer mirrors: top/bottom strand on top, then the bound
    bar (◄ on the LEFT) drawn in the BOTTOM-strand frame so its bases
    line up with the bottom strand row directly above it, then the
    flap underneath.

    `context_bp` extends the strand window past the primer's
    footprint so the user sees flanking bases. Wrap-binding
    primers fall back to a "(wrap primer — preview not supported)"
    note since the seq-panel split-half rendering is overkill for
    an in-modal preview.
    """
    if not primer_seq:
        return Text("(no primer sequence)", style="dim italic")
    if bound_end < bound_start:
        return Text("(wrap primer — preview not supported)",
                    style="dim italic")
    bound_len = bound_end - bound_start
    flap_len  = max(0, len(primer_seq) - bound_len)
    if not template:
        return Text("(no template loaded — open a plasmid to preview)",
                    style="dim italic")

    # Window calculation: cover the bound region + the flap range
    # (which lives outside the template for a 5'-extension primer).
    # We extend `win_end` past the template's actual length when
    # the flap dangles off the end — the strand display below is
    # padded with spaces in that range so the flap row stays
    # visually aligned to its column.
    if strand >= 0:
        win_start = max(0, bound_start - flap_len - context_bp)
        win_end_unclamped = bound_end + context_bp
    else:
        win_start = max(0, bound_start - context_bp)
        win_end_unclamped = bound_end + flap_len + context_bp
    win_end = win_end_unclamped
    if win_end <= win_start:
        return Text("(no overlap with template)", style="dim italic")
    if win_end - win_start > _PRIMER_PREVIEW_MAX_WIDTH:
        # Malformed feat coords or an absurdly long primer — bail
        # before allocating a giant per-cell list every keystroke.
        return Text("(preview window too wide — primer / binding "
                    "coordinates out of range)", style="dim italic")

    # Top strand: clamp to template length, pad with spaces past
    # the end so the flap can render at its full column range
    # without an out-of-template tail clipping the row.
    template_end = min(len(template), win_end)
    top_strand_real = template[win_start:template_end]
    pad_right = max(0, win_end - template_end)
    top_strand = top_strand_real + (" " * pad_right)
    bot_strand = _rc(top_strand_real)[::-1] + (" " * pad_right)

    if strand >= 0:
        flap_bases  = primer_seq[:flap_len]
        bound_bases = primer_seq[flap_len:]
        flap_col    = bound_start - flap_len - win_start
        bound_col   = bound_start - win_start
        arrow_col   = bound_col + len(bound_bases)
    else:
        # Bottom-strand frame (see `_paint_primer_bound_bar`): the
        # plain reverse of the primer slices, so the bound bar matches
        # the bottom strand row and reads 5'→3' right-to-left toward ◄.
        flap_bases  = primer_seq[:flap_len][::-1]
        bound_bases = primer_seq[flap_len:][::-1]
        flap_col    = bound_end - win_start
        bound_col   = bound_start - win_start
        arrow_col   = bound_col - 1

    line_w    = win_end - win_start
    flap_row  = [(" ", "")] * line_w
    bound_row = [(" ", "")] * line_w

    bg = f"black on {color}"
    for i, c in enumerate(flap_bases):
        col = flap_col + i
        if 0 <= col < line_w:
            flap_row[col] = (c, bg)
    for i, c in enumerate(bound_bases):
        col = bound_col + i
        if 0 <= col < line_w:
            bound_row[col] = (c, bg)
    if 0 <= arrow_col < line_w:
        bound_row[arrow_col] = ("▶" if strand >= 0 else "◀", bg)

    def _row_to_text(row) -> Text:
        t = Text(no_wrap=True)
        for c, sty in row:
            t.append(c, style=sty)
        return t

    out = Text(no_wrap=True, overflow="crop")
    if strand >= 0:
        out.append(_row_to_text(flap_row));  out.append("\n")
        out.append(_row_to_text(bound_row)); out.append("\n")
        out.append(top_strand, style="color(252)"); out.append("\n")
        out.append(bot_strand, style="color(244)")
    else:
        out.append(top_strand, style="color(252)"); out.append("\n")
        out.append(bot_strand, style="color(244)"); out.append("\n")
        out.append(_row_to_text(bound_row)); out.append("\n")
        out.append(_row_to_text(flap_row))
    return out


