# ── Feature library workbench (full-screen) ───────────────────────────────────

class _FeatureSnippetPanel(Widget):
    """Visualization of a single library entry: header line (name/type/
    strand/length/color swatch), a double-stranded DNA block rendered via
    the shared ``_build_seq_text`` pipeline (so the preview exactly matches
    the main SequencePanel — dithered ▒ bar + directional arrowhead), and
    a qualifiers list.

    The DNA line width tracks the panel's actual width (minus scrollbar
    + line-number prefix) on mount and on every resize. Pre-fix used a
    hardcoded ``line_width=60`` so the lane art never expanded past the
    leftmost 60 cols of the modal regardless of terminal size.

    Not interactive — re-render by calling ``show(entry)``.
    """

    DEFAULT_CSS = """
    _FeatureSnippetPanel {
        height: 1fr;
        overflow-y: auto;
        padding: 1 2;
    }
    _FeatureSnippetPanel > #snippet-header,
    _FeatureSnippetPanel > #snippet-quals {
        width: 100%;
        height: auto;
    }
    _FeatureSnippetPanel > #snippet-dna {
        width: 100%;
        height: auto;
        margin: 1 0;
    }
    """

    def __init__(self) -> None:
        super().__init__()
        self._entry: "dict | None" = None
        self._line_width: int = 60

    def compose(self) -> ComposeResult:
        yield Static("", id="snippet-header", markup=True)
        yield Static("", id="snippet-dna", markup=False)
        yield Static("", id="snippet-quals", markup=True)

    def on_mount(self) -> None:
        self._refresh_line_width()

    def on_resize(self, _event) -> None:
        if self._refresh_line_width():
            self.show(self._entry)

    def _refresh_line_width(self) -> bool:
        """Recompute line_width from the current widget width. Returns
        True if the value actually changed (so callers can re-render).

        Pre-mount / zero-sized: returns False so a cold panel doesn't
        clobber its constructor default with the floor — the real width
        gets read once ``on_mount`` fires."""
        try:
            w = int(self.size.width or 0)
        except (AttributeError, TypeError, ValueError):
            w = 0
        if w <= 0:
            return False
        # padding 1 2 → -4 horizontal; line-number prefix in
        # _build_seq_text consumes ~num_w + 2 cols (≤8 for 5-digit
        # entries). Reserve 12 cols of overhead and clamp into a
        # [20, 500] band so a very narrow terminal still renders
        # something AND a pathological super-wide widget doesn't blow
        # up `_build_seq_text`'s per-row arrays.
        new_lw = max(20, min(500, w - 12))
        if new_lw != self._line_width:
            self._line_width = new_lw
            return True
        return False

    def show(self, entry: "dict | None") -> None:
        self._entry = entry
        try:
            hdr  = self.query_one("#snippet-header", Static)
            dna  = self.query_one("#snippet-dna",    Static)
            qual = self.query_one("#snippet-quals",  Static)
        except NoMatches:
            return
        if entry is None:
            hdr.update("[dim]Select a feature on the left to view it.[/]")
            dna.update("")
            qual.update("")
            return
        hdr.update(self._format_header(entry))
        dna.update(self._render_dna(entry, self._line_width))
        qual.update(self._format_qualifiers(entry))

    @staticmethod
    def _format_header(entry: dict) -> str:
        name   = entry.get("name", "?") or "?"
        ftype  = entry.get("feature_type", "?") or "?"
        seq    = (entry.get("sequence", "") or "").upper()
        strand = entry.get("strand", 1)
        desc   = entry.get("description", "") or ""
        color  = _resolve_feature_color(entry)
        length = len(seq)
        strand_tag = {1: "→ forward", -1: "← reverse",
                      0: "· arrowless", 2: "↔ double"}.get(strand, "→ forward")
        lines: list[str] = [
            f"[bold {color}]{name}[/]   "
            f"[dim]type:[/] [{color}]{ftype}[/]   "
            f"[dim]strand:[/] {strand_tag}   "
            f"[dim]length:[/] {length} bp   "
            f"[dim]color:[/] [{color}]███[/] {color}",
        ]
        if desc:
            lines.append(f"[dim]{desc}[/]")
        return "\n".join(lines)

    @staticmethod
    def _render_dna(entry: "dict", line_width: int = 60) -> "Text":
        """Build a full double-stranded DNA visualization by synthesizing a
        single full-span feature and running it through ``_build_seq_text`` —
        the exact same pipeline the main SequencePanel uses. The feature's
        ``strand`` decides which arrowhead (if any) is drawn.

        ``line_width`` controls how many bp render per line; the panel
        keeps it in sync with its own width via ``on_resize``. Floored at
        20 so a very narrow terminal still renders something; capped at
        500 so a caller passing an unbounded width can't blow up
        ``_build_seq_text``'s per-row arrays."""
        seq = (entry.get("sequence", "") or "").upper()
        if not seq:
            return Text("(no sequence)", style="dim")
        name   = entry.get("name", "") or ""
        ftype  = entry.get("feature_type", "misc_feature") or "misc_feature"
        strand = entry.get("strand", 1)
        color  = _resolve_feature_color(entry)
        synth = [{
            "type":   ftype,
            "start":  0,
            "end":    len(seq),
            "strand": strand,
            "color":  color,
            "label":  name,
        }]
        return _build_seq_text(seq, synth,
                               line_width=max(20, min(500, line_width)))

    @staticmethod
    def _format_qualifiers(entry: dict) -> str:
        quals = entry.get("qualifiers") or {}
        if not quals:
            return "[dim]No qualifiers.[/]"
        lines = ["[bold]Qualifiers[/]"]
        for k in sorted(quals.keys()):
            vals = quals.get(k) or []
            if isinstance(vals, list):
                val_s = "; ".join(str(v) for v in vals)
            else:
                val_s = str(vals)
            lines.append(f"  [cyan]{k}[/] = {val_s}")
        return "\n".join(lines)


class FeatureLibraryScreen(_OneShotDismissScreen, Screen):
    """Full-screen library browser for persistent feature entries.

    Left column: DataTable listing every entry (Name / Type / Strand / bp
    / Color swatch). Right column: ``_FeatureSnippetPanel`` visualizing the
    selected entry. Bottom buttons handle CRUD + styling.

    Edits are buffered in ``self._entries`` and only written to disk by
    ``action_save`` (Save button or Ctrl+S). Dirty entries get an
    ``*`` prefix in the table; the title bar shows ``*`` when there's
    anything pending (covers deletions that leave no row to flag).
    Closing with pending changes triggers ``UnsavedQuitModal`` so the
    user can choose Save/Abandon/Cancel rather than silently losing
    work. Routes through ``_load_features`` / ``_save_features`` which
    enforce the schema envelope (sacred invariant #7).
    """

    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "close",     "Close"),
        Binding("a",      "add",       "Add"),
        Binding("e",      "edit",      "Edit"),
        Binding("r",      "rename",    "Rename"),
        Binding("d",      "duplicate", "Duplicate"),
        Binding("delete", "remove",    "Remove"),
        Binding("c",      "color",     "Color"),
        Binding("s",      "strand",    "Cycle Strand"),
        Binding("ctrl+s", "save",      "Save"),
    ]

    def check_action(self, action: str, parameters: tuple) -> bool | None:
        return True

    def __init__(self) -> None:
        super().__init__()
        self._entries: list[dict] = list(_load_features())
        self._selected_index: int = 0 if self._entries else -1
        # Dirty tracking. `_dirty_indices` flags entries with unsaved
        # field changes (asterisk prefix in the table). It can't cover
        # deletions because the row no longer exists, so
        # `_has_pending_changes` is the umbrella signal used by
        # `action_close` to decide whether to prompt.
        self._dirty_indices: set[int] = set()
        self._has_pending_changes: bool = False
        # Display-row → entry-index mapping for the natural-sort
        # rendering. Rebuilt on every ``_repopulate_table``; cursor
        # events translate visual rows back to entry indices through
        # this list. ``self._entries`` itself stays in on-disk order
        # so ``_selected_index`` / ``_dirty_indices`` keep their
        # entry-index semantics across edits.
        self._row_to_entry_idx: list[int] = []
        # Reverse mapping (entry-idx → row) so cursor restoration after
        # `_repopulate_table` is O(1) instead of O(N) `.index()` lookup.
        # For libraries with hundreds of entries this avoids per-edit
        # latency on the cursor-restore path.
        self._entry_idx_to_row: dict[int, int] = {}

    def compose(self) -> ComposeResult:
        yield Header()
        with Vertical(id="flib-box"):
            yield Static(" Feature Library ", id="flib-title")
            with Horizontal(id="flib-main"):
                with Vertical(id="flib-left"):
                    yield Static("Entries", classes="flib-section-hdr")
                    yield DataTable(id="flib-table",
                                    cursor_type="row", zebra_stripes=True)
                with Vertical(id="flib-right"):
                    yield Static("Preview", classes="flib-section-hdr")
                    yield _FeatureSnippetPanel()
            with Horizontal(id="flib-btns"):
                yield Button("Add",             id="btn-flib-add")
                yield Button("Edit",            id="btn-flib-edit")
                yield Button("Rename",          id="btn-flib-rename")
                yield Button("Duplicate",       id="btn-flib-dup")
                yield Button("Delete",          id="btn-flib-remove",
                             variant="error")
                yield Button("Color",           id="btn-flib-color")
                yield Button("Cycle Strand",    id="btn-flib-strand")
                yield Button("Export FASTA",    id="btn-flib-export-fasta")
                yield Button("Save",            id="btn-flib-save",
                             variant="primary")
                yield Button("Close  [Esc]",    id="btn-flib-close")
        yield Footer()

    def on_mount(self) -> None:
        tbl = self.query_one("#flib-table", DataTable)
        tbl.add_columns("Name", "Type", "±", "bp", "Color")
        self._repopulate_table()

    def on_screen_resume(self) -> None:
        """Re-fetch the feature library when the screen is brought
        back to focus (e.g. after a child modal closed, or after an
        agent mutation underneath). Without this, screens that read
        their backing list once at `on_mount` show stale rows for
        the lifetime of the screen.

        Skips the reload when there are pending edits — overwriting
        the in-memory entries would discard the user's unsaved work.
        The trade-off: in the rare case where an agent adds a feature
        while the user has unsaved edits open, the new agent entry
        won't appear until the user saves + the screen is re-entered.
        That's safer than silently losing edits.

        Audit fix 2026-05-14: extends invariant #17's spirit to the
        Screen-resume lifecycle.

        Sweep #26 (2026-05-25): also bail when `_has_pending_changes`
        is set even without dirty indices. The remove path
        (`action_remove`) sets pending without dirty (deletes don't
        get asterisks since the row is gone) and the resume reload
        used to silently undo the deletion when the
        `LibraryDeleteConfirmModal` popped — the in-memory delete was
        clobbered before the next `action_save` could persist it.
        """
        if self._dirty_indices or self._has_pending_changes:
            return
        try:
            self._entries = _load_features()
        except Exception:
            _log.exception("FeatureLibraryScreen: resume reload failed")
            return
        self._repopulate_table()

    # ── rendering ────────────────────────────────────────────────────────────

    def _repopulate_table(self) -> None:
        try:
            tbl = self.query_one("#flib-table", DataTable)
        except NoMatches:
            return
        tbl.clear(columns=False)
        # Natural sort by name (``pBin2`` before ``pBin10``). The
        # backing ``self._entries`` list stays in its on-disk order so
        # ``_selected_index`` / ``_dirty_indices`` keep their existing
        # entry-index semantics; we build a row→entry mapping for the
        # display and translate cursor events through it. Mirrors the
        # ``FeatureSidebar._row_to_feat_idx`` pattern.
        self._row_to_entry_idx: list[int] = sorted(
            range(len(self._entries)),
            key=lambda i: _natural_sort_key(
                (self._entries[i].get("name") or "")
            ),
        )
        # Reverse map for O(1) cursor-restore lookup (vs `.index()`
        # which is O(N) and walked once per repopulate).
        self._entry_idx_to_row = {
            entry_idx: row_idx
            for row_idx, entry_idx in enumerate(self._row_to_entry_idx)
        }
        for row_idx, entry_idx in enumerate(self._row_to_entry_idx):
            entry = self._entries[entry_idx]
            color = _resolve_feature_color(entry)
            strand = entry.get("strand", 1)
            strand_tag = {1: "+", -1: "−", 0: "·", 2: "↔"}.get(strand, "+")
            bp = len((entry.get("sequence") or ""))
            # Use Rich Text for the Color cell so the swatch actually tints
            swatch = Text("███ ", style=color)
            swatch.append(color, style="dim")
            base_name = entry.get("name", "?")
            name_cell = (("*" + base_name)
                         if entry_idx in self._dirty_indices
                         else base_name)
            tbl.add_row(
                name_cell,
                entry.get("feature_type", "?"),
                strand_tag,
                str(bp),
                swatch,
            )
        # Keep the selection in range and place the cursor on the row
        # whose entry-idx matches `_selected_index`. O(1) via the
        # reverse map.
        if self._entries:
            if self._selected_index < 0 or self._selected_index >= len(self._entries):
                self._selected_index = self._row_to_entry_idx[0]
            row_idx = self._entry_idx_to_row.get(self._selected_index)
            if row_idx is None:
                # Selection drifted outside the current row mapping —
                # log so the underlying drift surfaces in dev mode
                # rather than silently snapping to row 0.
                _log.warning(
                    "FeatureLibraryScreen: selected_index %d not in "
                    "row map (n=%d); snapping to row 0",
                    self._selected_index, len(self._row_to_entry_idx),
                )
                row_idx = 0
                self._selected_index = self._row_to_entry_idx[0]
            tbl.move_cursor(row=row_idx)
        else:
            self._selected_index = -1
        self._refresh_title()
        self._refresh_preview()

    def _refresh_title(self) -> None:
        try:
            title = self.query_one("#flib-title", Static)
        except NoMatches:
            return
        title.update(
            " Feature Library *" if self._has_pending_changes
            else " Feature Library "
        )

    def _refresh_preview(self) -> None:
        try:
            snip = self.query_one(_FeatureSnippetPanel)
        except NoMatches:
            return
        if 0 <= self._selected_index < len(self._entries):
            snip.show(self._entries[self._selected_index])
        else:
            snip.show(None)

    # ── events ───────────────────────────────────────────────────────────────

    @on(DataTable.RowHighlighted, "#flib-table")
    def _row_highlighted(self, event: DataTable.RowHighlighted) -> None:
        try:
            tbl = self.query_one("#flib-table", DataTable)
        except NoMatches:
            return
        # Translate the visual row index through the natural-sort
        # row→entry mapping built in `_repopulate_table`. Pre-fix
        # `cursor_row` was directly used as the entry index — fine when
        # entries rendered in their on-disk order, broken once the
        # natural sort started reshuffling rows.
        row = tbl.cursor_row
        if (row is None
                or not getattr(self, "_row_to_entry_idx", None)
                or row < 0 or row >= len(self._row_to_entry_idx)):
            return
        self._selected_index = self._row_to_entry_idx[row]
        self._refresh_preview()

    @on(Button.Pressed, "#btn-flib-export-fasta")
    def _export_fasta_btn(self, _) -> None: self.action_export_fasta()

    @_action_log("app.feature_library.export_fasta")
    def action_export_fasta(self) -> None:
        """Export the highlighted library entry as single-record FASTA."""
        if _demo_web_refuse(self.app, "Exporting files"):
            return
        entry = self._current()
        if entry is None:
            self.app.notify("Select a feature first.", severity="warning")
            return
        seq = entry.get("sequence") or ""
        if not seq:
            self.app.notify(
                "This entry has no sequence to export.",
                severity="warning",
            )
            return
        name = entry.get("name") or "feature"
        ftype = entry.get("feature_type") or "?"
        safe = re.sub(r"[^A-Za-z0-9._-]", "_", name) or "feature"
        default_path = str(Path.home() / f"{safe}.fa")

        def _on_done(summary):
            if not summary:
                return
            self.app.notify(
                f"Exported '{summary['name']}' to {summary['path']} "
                f"({summary['bp']} bp).",
            )

        self.app.push_screen(
            FastaExportModal(
                name=name,
                sequence=seq,
                default_path=default_path,
                subtitle=f"[{name}]  [{ftype}]  {len(seq)} bp",
            ),
            callback=_on_done,
        )

    @on(Button.Pressed, "#btn-flib-close")
    def _close_btn(self, _) -> None:
        self.action_close()

    @_action_log("app.feature_library.close")
    def action_close(self) -> None:
        """Pop back to the main app, prompting on unsaved changes.

        With pending edits, push ``UnsavedQuitModal`` (the same dialog
        the main quit path uses) and wait for the user's choice:
        ``"save"`` → persist + pop, ``"abandon"`` → pop without saving,
        ``None`` → stay open. Without changes, pop immediately.
        """
        if not self._has_pending_changes:
            self.app.pop_screen()
            return

        def _cb(result):
            if result == "save":
                if self._persist_all():
                    self.app.pop_screen()
                # On save failure stay open so the user can retry.
            elif result == "abandon":
                self.app.pop_screen()
            # None → cancel; do nothing.

        self.app.push_screen(UnsavedQuitModal(), callback=_cb)

    @on(Button.Pressed, "#btn-flib-save")
    def _save_btn(self, _) -> None: self.action_save()

    @_action_log("app.feature_library.save")
    def action_save(self) -> None:
        """Persist self._entries → features.json. No-op if nothing pending."""
        if not self._has_pending_changes:
            self.app.notify("No changes to save.", severity="information")
            return
        if self._persist_all():
            self.app.notify(
                f"Saved {len(self._entries)} feature(s) to library."
            )

    # ── persistence helpers ──────────────────────────────────────────────────

    def _persist_all(self) -> bool:
        """Write self._entries → features.json and clear the dirty marks.
        Returns True on success."""
        try:
            _save_features(self._entries)
        except (OSError, ValueError) as exc:
            _notify_save_failure(self.app, "Feature library", exc)
            return False
        self._dirty_indices.clear()
        self._has_pending_changes = False
        self._repopulate_table()
        return True

    def _mark_dirty(self, idx: int) -> None:
        """Tag an entry as having unsaved field changes (asterisk in the
        table) and set the umbrella pending-changes flag.
        """
        if 0 <= idx < len(self._entries):
            self._dirty_indices.add(idx)
        self._has_pending_changes = True

    def _shift_dirty_after_remove(self, removed_idx: int) -> None:
        """Rewrite ``_dirty_indices`` after deleting entry ``removed_idx``.

        Drops ``removed_idx`` itself, shifts every higher index down by
        one. Without this, asterisks would stick to the wrong row after
        a delete (or, worse, point past the end of the list).
        """
        new_dirty: set[int] = set()
        for i in self._dirty_indices:
            if i < removed_idx:
                new_dirty.add(i)
            elif i > removed_idx:
                new_dirty.add(i - 1)
        self._dirty_indices = new_dirty

    def _current(self) -> "dict | None":
        if 0 <= self._selected_index < len(self._entries):
            return self._entries[self._selected_index]
        return None

    # ── actions ──────────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-flib-add")
    def _add_btn(self, _) -> None: self.action_add()

    @_action_log("app.feature_library.add")
    def action_add(self) -> None:
        def _cb(result):
            if not result:
                return
            entry = result.get("entry") if isinstance(result, dict) else None
            if not entry:
                return
            self._upsert_entry(entry, notice="Added")
        self.app.push_screen(AddFeatureModal(), callback=_cb)

    @on(Button.Pressed, "#btn-flib-edit")
    def _edit_btn(self, _) -> None: self.action_edit()

    @_action_log("app.feature_library.edit")
    def action_edit(self) -> None:
        """Open AddFeatureModal pre-filled with the current entry. The
        modal already round-trips its prefill (`_apply_prefill` mirrors
        `_gather`) so editing is just "Add with the existing dict."
        Replaces the entry at the current index on save and marks it
        dirty; doesn't write to disk until Save.
        """
        entry = self._current()
        if entry is None:
            self.app.notify("Select a feature first.", severity="warning")
            return
        target_idx = self._selected_index

        def _cb(result):
            if not result:
                return
            new_entry = result.get("entry") if isinstance(result, dict) else None
            if not new_entry:
                return
            # If the user kept the same (name, feature_type), this is a
            # plain edit-in-place. If they changed the name/type to one
            # that already exists at a different index, dedup that one
            # too (Add-style "latest write wins").
            self._replace_entry(target_idx, new_entry)

        self.app.push_screen(
            AddFeatureModal(prefill=entry),
            callback=_cb,
        )

    def _upsert_entry(self, entry: dict, notice: str) -> None:
        """Append ``entry`` (or replace the entry with the same
        (name, feature_type) key — "latest write wins"). Marks the new
        index dirty and updates the selection.
        """
        key = (entry.get("name"), entry.get("feature_type"))
        existing_idx = next(
            (i for i, e in enumerate(self._entries)
             if (e.get("name"), e.get("feature_type")) == key),
            -1,
        )
        if existing_idx >= 0:
            self._entries[existing_idx] = entry
            self._selected_index = existing_idx
            self._mark_dirty(existing_idx)
        else:
            self._entries.append(entry)
            self._selected_index = len(self._entries) - 1
            self._mark_dirty(self._selected_index)
        self._repopulate_table()
        self.app.notify(f"{notice} '{entry.get('name')}' (unsaved).",
                        markup=False)

    def _replace_entry(self, target_idx: int, new_entry: dict) -> None:
        """Replace entry at ``target_idx``, deduping any other entry that
        ends up sharing the new (name, feature_type) key.
        """
        if not (0 <= target_idx < len(self._entries)):
            return
        new_key = (new_entry.get("name"), new_entry.get("feature_type"))
        # Drop any OTHER entry that now collides with the new key.
        for i in range(len(self._entries) - 1, -1, -1):
            if i == target_idx:
                continue
            e = self._entries[i]
            if (e.get("name"), e.get("feature_type")) == new_key:
                del self._entries[i]
                self._shift_dirty_after_remove(i)
                if i < target_idx:
                    target_idx -= 1
        self._entries[target_idx] = new_entry
        self._selected_index = target_idx
        self._mark_dirty(target_idx)
        self._repopulate_table()
        self.app.notify(f"Edited '{new_entry.get('name')}' (unsaved).",
                        markup=False)

    @on(Button.Pressed, "#btn-flib-rename")
    def _rename_btn(self, _) -> None: self.action_rename()

    @_action_log("app.feature_library.rename")
    def action_rename(self) -> None:
        entry = self._current()
        if entry is None:
            self.app.notify("Select a feature first.", severity="warning")
            return
        old = entry.get("name", "")
        idx = self._selected_index

        def _cb(new_name):
            if not new_name:
                return
            if new_name == old:
                return
            entry["name"] = str(new_name)
            self._mark_dirty(idx)
            self._repopulate_table()
            self.app.notify(f"Renamed '{old}' → '{new_name}' (unsaved).",
                            markup=False)

        self.app.push_screen(RenamePlasmidModal(old, ""), callback=_cb)

    @on(Button.Pressed, "#btn-flib-dup")
    def _dup_btn(self, _) -> None: self.action_duplicate()

    def action_duplicate(self) -> None:
        entry = self._current()
        if entry is None:
            self.app.notify("Select a feature first.", severity="warning")
            return
        import copy as _copy
        dup = _copy.deepcopy(entry)
        # Suffix a unique "(copy)" / "(copy N)" name so we don't dedup it out.
        base = dup.get("name", "feature")
        existing_names = {e.get("name") for e in self._entries}
        cand = f"{base} (copy)"
        n = 2
        while cand in existing_names:
            cand = f"{base} (copy {n})"
            n += 1
        dup["name"] = cand
        self._entries.append(dup)
        self._selected_index = len(self._entries) - 1
        self._mark_dirty(self._selected_index)
        self._repopulate_table()
        self.app.notify(f"Duplicated as '{cand}' (unsaved).",
                        markup=False)

    @on(Button.Pressed, "#btn-flib-remove")
    def _remove_btn(self, _) -> None: self.action_remove()

    @_action_log("app.feature_library.remove")
    def action_remove(self) -> None:
        entry = self._current()
        if entry is None:
            return
        # Sweep #26 (2026-05-25): push a confirmation before deleting
        # the row. Pre-fix the plain Delete keybinding wiped the
        # current row with zero confirmation while every other delete
        # path in the app (parts bin, plasmid library, primer library,
        # collections, experiments, gels) prompts first. The "(unsaved)"
        # notify hinted that the user could recover by closing without
        # saving, but they had to discover that — and the delete was
        # mid-flow with no obvious bail-out.
        name = entry.get("name", "?")
        seq_len = len(entry.get("sequence", "") or "")
        removed_idx = self._selected_index

        def _on_confirm(go: "bool | None") -> None:
            if not go:
                return
            # Re-check the row state — between the modal push and the
            # callback the user could have moved the cursor, but for
            # this action_remove call we captured `entry` + index at
            # push time so we still delete the originally-selected
            # row. This matches Experiments / Primer rename behavior.
            if (removed_idx < 0
                    or removed_idx >= len(self._entries)):
                return
            del self._entries[removed_idx]
            self._shift_dirty_after_remove(removed_idx)
            self._has_pending_changes = True
            if self._selected_index >= len(self._entries):
                self._selected_index = len(self._entries) - 1
            self._repopulate_table()
            self.app.notify(f"Removed '{name}' (unsaved).",
                            markup=False)

        self.app.push_screen(
            LibraryDeleteConfirmModal(
                name=name, size=seq_len, entry_id=name,
            ),
            callback=_on_confirm,
        )

    @on(Button.Pressed, "#btn-flib-color")
    def _color_btn(self, _) -> None: self.action_color()

    def action_color(self) -> None:
        entry = self._current()
        if entry is None:
            self.app.notify("Select a feature first.", severity="warning")
            return
        ftype = entry.get("feature_type", "")
        current = entry.get("color")
        idx = self._selected_index

        def _cb(result):
            if not result:
                return
            new_color = result.get("color")
            set_default = bool(result.get("set_default"))
            entry["color"] = new_color   # None → auto
            # User-defaults map (feature_colors.json) is a separate
            # file from the per-entry feature library — saving it
            # immediately is correct; the deferred-save model only
            # applies to features.json itself.
            if set_default and isinstance(new_color, str) and new_color:
                defaults = _load_feature_colors()
                defaults[ftype] = new_color
                try:
                    _save_feature_colors(defaults)
                except (OSError, ValueError) as exc:
                    _log.exception("Feature color default save failed")
                    self.app.notify(f"Save default failed: {exc}",
                                    severity="error")
            self._mark_dirty(idx)
            self._repopulate_table()
            shown = new_color if new_color else "auto"
            self.app.notify(f"Color set to {shown} (unsaved).",
                            markup=False)

        self.app.push_screen(
            ColorPickerModal(ftype, _safe_color_for_picker(current)),
            callback=_cb,
        )

    @on(Button.Pressed, "#btn-flib-strand")
    def _strand_btn(self, _) -> None: self.action_strand()

    def action_strand(self) -> None:
        """Cycle strand direction: +1 (▶) → -1 (◀) → 0 (arrowless ▒) →
        2 (double ◀▒▶) → +1."""
        entry = self._current()
        if entry is None:
            self.app.notify("Select a feature first.", severity="warning")
            return
        cur = entry.get("strand", 1)
        nxt = {1: -1, -1: 0, 0: 2, 2: 1}.get(cur, 1)
        entry["strand"] = nxt
        self._mark_dirty(self._selected_index)
        self._repopulate_table()
        tag = {1:  "forward (→)",
               -1: "reverse (←)",
               0:  "arrowless (·)",
               2:  "double (↔)"}.get(nxt, "+")
        self.app.notify(f"Strand → {tag} (unsaved).")


# ── Cloning grammar editor ─────────────────────────────────────────────────────

class GrammarEditorModal(_OneShotDismissScreen, ModalScreen):
    """View or edit a cloning grammar (overhang table + enzyme + tail).

    Built-in grammars (``gb_l0``, ``moclo_plant``) open here in
    read-only mode — every input is disabled and Save/Delete are
    greyed out so the canonical references can't be corrupted. To
    modify a built-in, use Duplicate in the Parts Bin to fork it
    into an editable custom grammar first.

    Custom grammars open editable. Save validates IUPAC bases on
    every overhang field, requires at least one position, and writes
    the result to ``cloning_grammars.json``. Delete (only enabled
    for custom grammars) drops the entry permanently.

    Dismisses with:
      - ``"saved"`` — grammar persisted (caller should refresh).
      - ``"deleted"`` — grammar removed (caller should flip active
        back to ``gb_l0`` if this was the active one).
      - ``None`` — user cancelled, no changes.
    """

    _blocks_undo: bool = True   # sweep #10: grammars file mutation

    BINDINGS = [
        Binding("escape", "cancel", "Cancel"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    def __init__(self, grammar_id: str = "") -> None:
        super().__init__()
        # `grammar_id == ""` is the sentinel for "create new". The
        # actual id gets slugged from the user-typed name on Save —
        # see `_save`. Empty-id mode is fully editable, has no entry
        # vector pre-bound, and never touches `_BUILTIN_GRAMMARS`.
        self._grammar_id = grammar_id
        self._create_mode = (grammar_id == "")
        self._is_builtin = (
            (not self._create_mode) and grammar_id in _BUILTIN_GRAMMARS
        )
        if self._create_mode:
            # Blank-but-typed scaffold so the form's IUPAC validators
            # have something concrete to push back on. Saner defaults
            # than empty strings — the user gets a structured starting
            # point even for a brand-new grammar.
            self._grammar = {
                "id":              "",
                "name":            "",
                "enzyme":          "",
                "level_up_enzyme": "",
                "site":            "",
                "spacer":          "",
                "pad":             "",
                "forbidden_sites": {},
                "positions":       [],
                "coding_types":    [],
                "type_to_insdc":   {},
                "catalog":         [],
                "editable":        True,
            }
        else:
            # Snapshot the grammar dict so cancel discards in-flight edits.
            grammars = _all_grammars()
            self._grammar = deepcopy(
                grammars.get(grammar_id, _BUILTIN_GRAMMARS["gb_l0"])
            )
        # Entry vector is editable for ALL grammars (built-in or
        # custom). Stored separately from the grammar dict in
        # `entry_vectors.json` so the canonical built-in grammar
        # definitions stay immutable. Create-mode starts with no bound
        # vector — the user binds one after the grammar exists on disk
        # (entry_vectors.json keys by grammar_id, so the binding only
        # makes sense post-Save).
        self._entry_vector = (
            None if self._create_mode else _get_entry_vector(grammar_id)
        )

    def compose(self) -> ComposeResult:
        g = self._grammar
        editable = not self._is_builtin
        with Vertical(id="ged-dlg"):
            if self._create_mode:
                title = " New Grammar"
            else:
                title = f" Grammar: {g.get('name', '?')}"
            if self._is_builtin:
                title += "   [built-in, read-only]"
            yield Static(title, id="ged-title")

            if self._is_builtin:
                yield Static(
                    "  Built-in grammars are read-only. "
                    "Duplicate from the Parts Bin to fork an editable copy.",
                    id="ged-builtin-banner",
                )
            elif self._create_mode:
                yield Static(
                    "  Pick a unique name, an enzyme + recognition site, "
                    "and at least one position. The grammar's id is "
                    "slugged from the name on Save.",
                    id="ged-builtin-banner",
                )

            with ScrollableContainer(id="ged-body"):
                # ── Entry vector ─────────────────────────────────────
                # Always editable for existing grammars (built-in or
                # custom) — the entry vector is grammar-scoped meta,
                # not part of the canonical grammar definition. Stored
                # in `entry_vectors.json` and persisted *immediately*
                # on pick (no need to hit Save), so users can
                # configure even read-only built-ins. Disabled in
                # create-mode because entry_vectors.json keys by
                # grammar_id, which doesn't exist until first Save.
                yield Label("Entry vector  (the destination plasmid for assemblies):")
                with Horizontal(id="ged-entry-row"):
                    if self._create_mode:
                        yield Static(
                            "[dim](bind a vector after Save — "
                            "the grammar id is needed to key the binding)[/dim]",
                            id="ged-entry-info", markup=True,
                        )
                    else:
                        yield Static(self._entry_vector_summary(),
                                     id="ged-entry-info", markup=True)
                with Horizontal(id="ged-entry-btns"):
                    yield Button("Pick from library",
                                 id="btn-ged-entry-lib",
                                 disabled=self._create_mode)
                    yield Button("Open file",
                                 id="btn-ged-entry-file",
                                 disabled=self._create_mode)
                    yield Button("Clear",
                                 id="btn-ged-entry-clear",
                                 variant="error",
                                 disabled=(self._create_mode
                                            or self._entry_vector is None))

                yield Label("Name:")
                yield Input(value=g.get("name", ""),
                            id="ged-name", disabled=not editable)

                with Horizontal(id="ged-enzyme-row"):
                    yield Label("Enzyme:", classes="ged-inline-label")
                    yield Input(value=g.get("enzyme", ""),
                                id="ged-enzyme", disabled=not editable)
                    yield Label("Recognition:", classes="ged-inline-label")
                    yield Input(value=g.get("site", ""),
                                id="ged-site", disabled=not editable)

                # Level-up enzyme is the Type IIS used at the NEXT
                # cycle step (TU→MOD, MOD→next). Empty / blank →
                # `_enzyme_for_level_up` falls back to the primary
                # enzyme so single-level grammars still work. For
                # iterative cycles (Golden Braid, MoClo) the user
                # picks a second enzyme that survives the L0 dropout
                # so the assembled plasmid can be re-digested.
                with Horizontal(id="ged-lvlup-row"):
                    yield Label("Level-up enzyme:", classes="ged-inline-label")
                    yield Input(value=g.get("level_up_enzyme", ""),
                                id="ged-level-up-enzyme",
                                placeholder="(optional — for iterative cycles)",
                                disabled=not editable)

                with Horizontal(id="ged-tail-row"):
                    yield Label("Spacer:", classes="ged-inline-label")
                    yield Input(value=g.get("spacer", ""),
                                id="ged-spacer", disabled=not editable)
                    yield Label("Pad:", classes="ged-inline-label")
                    yield Input(value=g.get("pad", ""),
                                id="ged-pad", disabled=not editable)

                yield Label("Forbidden sites (one per line, NAME=SITE):")
                forbidden = g.get("forbidden_sites", {}) or {}
                if isinstance(forbidden, dict):
                    forb_text = "\n".join(
                        f"{k}={v}" for k, v in forbidden.items()
                    )
                else:
                    forb_text = ""
                yield TextArea(forb_text, id="ged-forbidden",
                               read_only=not editable, soft_wrap=False,
                               show_line_numbers=False)

                yield Label(
                    "Positions (one per line: name | type | 5'OH | 3'OH | color):"
                )
                pos_lines = []
                for p in g.get("positions", []) or []:
                    if not isinstance(p, dict):
                        continue
                    color_field = p.get("color") or ""
                    pos_lines.append(
                        f"{p.get('name','')} | {p.get('type','')} | "
                        f"{p.get('oh5','')} | {p.get('oh3','')} | {color_field}"
                    )
                yield TextArea("\n".join(pos_lines), id="ged-positions",
                               read_only=not editable, soft_wrap=False,
                               show_line_numbers=False)

                yield Label("Coding types (comma-separated, eligible for codon repair):")
                coding = g.get("coding_types", []) or []
                yield Input(value=", ".join(coding),
                            id="ged-coding", disabled=not editable)

            yield Static("", id="ged-status", markup=True)

            with Horizontal(id="ged-btns"):
                yield Button("Save",   id="btn-ged-save",
                             variant="primary", disabled=not editable)
                yield Button("Cancel", id="btn-ged-cancel")
                yield Button("Delete", id="btn-ged-delete",
                             variant="error", disabled=not editable)

    @on(Button.Pressed, "#btn-ged-cancel")
    def _cancel(self, _) -> None:
        self.dismiss(None)

    def action_cancel(self) -> None:
        self.dismiss(None)

    # ── Entry-vector handlers ────────────────────────────────────────────────

    def _entry_vector_summary(self) -> str:
        """Markup string summarising the current entry vector. Used to
        populate `#ged-entry-info` both at compose time and after a
        pick. Empty / unset → `(none assigned)` in dim style.
        User-controlled strings (file paths, plasmid names) are run
        through `rich.markup.escape` so a name like `pUC[18]` can't
        accidentally trip Rich's markup parser."""
        from rich.markup import escape as _esc
        v = self._entry_vector
        if not isinstance(v, dict) or not v.get("name"):
            return "[dim](none assigned)[/dim]"
        size = int(v.get("size") or 0)
        src  = str(v.get("source") or "")
        src_tag = ""
        if src.startswith("library:"):
            src_tag = "from library"
        elif src.startswith("file:"):
            tail = src.split(":", 1)[1]
            src_tag = f"from file: [italic]{_esc(tail)}[/italic]"
        nm = _esc(str(v.get("name") or "?"))
        return (f"[green]{nm}[/green]  ({size:,} bp)"
                + (f"  · {src_tag}" if src_tag else ""))

    def _refresh_entry_row(self) -> None:
        try:
            info = self.query_one("#ged-entry-info", Static)
            clr  = self.query_one("#btn-ged-entry-clear", Button)
        except NoMatches:
            return
        info.update(self._entry_vector_summary())
        clr.disabled = self._entry_vector is None

    def _commit_entry_vector(self, vector: "dict | None") -> None:
        """Persist + refresh the entry-vector row. Persisting via
        `_set_entry_vector` immediately means the choice survives a
        Cancel on the rest of the grammar editor — entry vectors are
        a separate concern from the (mutable) grammar definition.

        Audit fix 2026-05-14: wraps the bare `_set_entry_vector` call
        so a disk-full / RO-mount / EACCES surfaces as a friendly
        toast via `_notify_save_failure` (invariant #7) rather than
        bubbling up as an uncaught OSError into Textual's crash dialog.
        """
        self._entry_vector = vector
        try:
            _set_entry_vector(self._grammar_id, vector)
        except (OSError, RuntimeError) as exc:
            _notify_save_failure(self.app, "Entry vectors", exc)
            return
        self._refresh_entry_row()

    @on(Button.Pressed, "#btn-ged-entry-lib")
    def _ged_entry_lib(self, _: Button.Pressed) -> None:
        """Pick the entry vector from the plasmid library — pushes
        `PlasmidPickerModal` and on dismiss assembles the vector
        dict from the matching library entry."""
        def _picked(plasmid_id: "str | None") -> None:
            if not plasmid_id:
                return
            # Sweep #26: helper avoids the full-library deepcopy.
            entry = _find_library_entry_by_id(plasmid_id)
            if entry is not None:
                self._commit_entry_vector({
                    "name":    str(entry.get("name") or plasmid_id),
                    "size":    int(entry.get("size") or 0),
                    "source":  f"library:{plasmid_id}",
                    "gb_text": str(entry.get("gb_text") or ""),
                })
        self.app.push_screen(PlasmidPickerModal(), _picked)

    @on(Button.Pressed, "#btn-ged-entry-file")
    def _ged_entry_file(self, _: Button.Pressed) -> None:
        """Pick the entry vector from a `.gb` / `.gbk` / `.dna` file
        on disk — pushes `OpenFileModal` and on dismiss converts the
        loaded record to a stored vector."""
        def _picked(record) -> None:
            if record is None:
                return
            try:
                gb_text = _record_to_gb_text(record)
            except Exception:
                _log.exception("Entry vector: GenBank serialisation failed")
                self.app.notify(
                    "Could not serialise the file as GenBank text.",
                    severity="error",
                )
                return
            self._commit_entry_vector({
                "name":    str(getattr(record, "name", "") or
                                 getattr(record, "id", "") or "vector"),
                "size":    int(len(record.seq) if getattr(record, "seq", None)
                                else 0),
                "source":  f"file:{getattr(record, '_tui_source', '?')}",
                "gb_text": gb_text,
            })
        if _demo_web_refuse(self.app, "Opening files from disk"):
            return
        self.app.push_screen(OpenFileModal(), _picked)

    @on(Button.Pressed, "#btn-ged-entry-clear")
    def _ged_entry_clear(self, _: Button.Pressed) -> None:
        self._commit_entry_vector(None)

    @on(Button.Pressed, "#btn-ged-save")
    def _save(self, _) -> None:
        if self._is_builtin:
            return
        parsed = self._gather()
        if parsed is None:
            return
        entries = _load_custom_grammars()
        new_id_for_create: str = ""
        if self._create_mode:
            # Slug a unique grammar id from the user-typed name. Avoid
            # collisions against both built-in IDs and any existing
            # custom grammar so the new entry gets its own row in
            # `cloning_grammars.json` (rather than overwriting an
            # unrelated grammar that happens to share a slug).
            base = re.sub(
                r"[^A-Za-z0-9_]+", "_",
                parsed.get("name", "") or "custom_grammar",
            ).strip("_") or "custom_grammar"
            taken = {gid for gid in _BUILTIN_GRAMMARS}
            taken.update(e.get("id") or "" for e in entries)
            new_id_for_create = base
            suffix = 2
            while new_id_for_create in taken:
                new_id_for_create = f"{base}_{suffix}"
                suffix += 1
            parsed["id"] = new_id_for_create
            entries.append(parsed)
        else:
            for i, e in enumerate(entries):
                if e.get("id") == self._grammar_id:
                    entries[i] = parsed
                    break
            else:
                entries.append(parsed)
        try:
            _save_custom_grammars(entries)
        except (OSError, ValueError) as exc:
            # Defer the in-memory id flip until AFTER the save
            # commits — a disk-full / RO-mount failure shouldn't
            # leave the modal half-committed (its `_grammar_id` set
            # to a slug that doesn't exist on disk; a retry would
            # re-slug from scratch and pick a different id, leaving
            # both the orphan slug AND the new attempt visible to
            # the user).
            _notify_save_failure(self.app, "Cloning grammar", exc)
            return
        # Save committed — now safe to flip the modal's view of the
        # grammar id. Done here, post-save, so the failure path
        # above leaves `_grammar_id` and `_create_mode` exactly as
        # they were on entry to the modal session.
        if self._create_mode:
            self._grammar_id = new_id_for_create
            self._create_mode = False
        # Dismiss with the new (or existing) id so the caller's
        # callback (e.g. `GrammarManagerModal._refresh_table`) can
        # focus the just-saved row instead of resetting the cursor
        # to the top of the table.
        self.app.notify(f"Saved grammar '{parsed.get('name')}'.",
                        severity="success",  # type: ignore[arg-type]
                        markup=False)
        self.dismiss(self._grammar_id)

    @on(Button.Pressed, "#btn-ged-delete")
    def _delete(self, _) -> None:
        if self._is_builtin:
            return
        entries = _load_custom_grammars()
        new_entries = [e for e in entries if e.get("id") != self._grammar_id]
        if len(new_entries) == len(entries):
            self.app.notify(
                "Grammar not found in custom grammars file.",
                severity="warning",
            )
            return
        try:
            _save_custom_grammars(new_entries)
        except (OSError, RuntimeError) as exc:
            _notify_save_failure(self.app, "Custom grammars", exc)
            return
        # Clear EVERY entry-vector binding for the deleted grammar
        # (Constructor's Alpha1/Alpha2/Omega1/Omega2 + the default
        # role) so a future custom grammar that slugs to the same
        # id doesn't inherit ghost bindings. The legacy
        # `_set_entry_vector(gid, None)` only cleared the default
        # role and left every Constructor binding orphan.
        try:
            _clear_entry_vectors_for_grammar(self._grammar_id)
        except Exception:
            _log.exception(
                "Grammar delete: entry-vector cleanup failed",
            )
        # Drop the deleted grammar from active_grammar so the rest
        # of the app keeps a valid handle.
        if _get_setting("active_grammar") == self._grammar_id:
            _set_setting("active_grammar", "gb_l0")
        self.app.notify(
            f"Deleted grammar '{self._grammar.get('name', self._grammar_id)}'."
        )
        self.dismiss("deleted")

    # ── Parsing ──────────────────────────────────────────────────────────────

    def _gather(self) -> "dict | None":
        """Form → grammar dict. Returns None and writes a red status
        line on validation failure; never raises."""
        try:
            name      = self.query_one("#ged-name",      Input).value.strip()
            enzyme    = self.query_one("#ged-enzyme",    Input).value.strip()
            level_up  = self.query_one("#ged-level-up-enzyme", Input).value.strip()
            site      = self.query_one("#ged-site",      Input).value.strip().upper()
            spacer    = self.query_one("#ged-spacer",    Input).value.strip().upper()
            pad       = self.query_one("#ged-pad",       Input).value.strip().upper()
            forb_text = self.query_one("#ged-forbidden", TextArea).text
            pos_text  = self.query_one("#ged-positions", TextArea).text
            coding    = self.query_one("#ged-coding",    Input).value
        except NoMatches:
            return None
        status = self.query_one("#ged-status", Static)
        valid_iupac = set("ACGTRYWSMKBDHVN")

        if not name:
            status.update("[red]Name cannot be empty.[/red]")
            return None
        if not enzyme:
            status.update("[red]Enzyme cannot be empty.[/red]")
            return None
        if enzyme not in _all_enzymes():
            # Casing matters in the enzyme catalog (`BsaI`, not `bsai`),
            # so we don't auto-coerce — surface the error so the
            # user fixes the casing themselves rather than saving a
            # silently-broken grammar that fails every digest at
            # runtime with cryptic "no clean digest" messages. Accepts
            # user-added custom enzymes too (via `_all_enzymes()`).
            status.update(
                f"[red]Enzyme {enzyme!r} not in the enzyme catalog "
                f"(built-in or custom). Examples: BsaI, Esp3I, BpiI, BbsI.[/red]"
            )
            return None
        # `level_up` is optional (single-step grammars leave it
        # blank) but if provided it MUST resolve to a real enzyme,
        # otherwise iterative cycles silently degrade — the user
        # would build a TU thinking it can chain into a MOD, hit
        # Save To Library, and get an opaque "no clean digest"
        # error from the assembly simulator.
        if level_up and level_up not in _NEB_ENZYMES:
            status.update(
                f"[red]Level-up enzyme {level_up!r} not in NEB "
                f"catalog. Leave blank for single-step grammars, or "
                f"pick from NEB names (Esp3I, BsaI, BpiI, …).[/red]"
            )
            return None
        for label, val in (
            ("Recognition site", site),
            ("Spacer", spacer),
            ("Pad",   pad),
        ):
            if not val:
                status.update(f"[red]{label} cannot be empty.[/red]")
                return None
            bad = [c for c in val if c not in valid_iupac]
            if bad:
                status.update(
                    f"[red]{label} contains invalid bases: "
                    f"{''.join(sorted(set(bad)))[:10]}[/red]"
                )
                return None

        # Forbidden sites: NAME=SITE per line.
        forbidden: dict[str, str] = {}
        for raw in forb_text.splitlines():
            line = raw.strip()
            if not line:
                continue
            if "=" not in line:
                status.update(
                    f"[red]Forbidden line must be NAME=SITE: {line!r}[/red]"
                )
                return None
            k, v = line.split("=", 1)
            k, v = k.strip(), v.strip().upper()
            if not k or not v:
                continue
            bad = [c for c in v if c not in valid_iupac]
            if bad:
                status.update(
                    f"[red]Forbidden site {k!r} has invalid bases: "
                    f"{''.join(sorted(set(bad)))[:10]}[/red]"
                )
                return None
            forbidden[k] = v

        # Positions: name | type | oh5 | oh3 [| color]
        positions: list[dict] = []
        for raw in pos_text.splitlines():
            line = raw.strip()
            if not line:
                continue
            parts = [p.strip() for p in line.split("|")]
            if len(parts) < 4:
                status.update(
                    f"[red]Position line needs ≥4 fields "
                    f"(name | type | 5'OH | 3'OH): {line!r}[/red]"
                )
                return None
            pname, ptype = parts[0], parts[1]
            poh5, poh3 = parts[2].upper(), parts[3].upper()
            if not pname or not ptype:
                status.update(
                    f"[red]Position name and type cannot be empty: {line!r}[/red]"
                )
                return None
            for label, val in (("5'OH", poh5), ("3'OH", poh3)):
                # Sweep #33 (2026-05-26): tighter overhang
                # validation. Type IIS digest produces fixed
                # 4-nt sticky ends — accept ONLY 4-bp ACGT
                # strings here. Pre-fix the IUPAC alphabet +
                # absent length check meant empty strings,
                # 1-bp anchors, and ambiguity codes (N/W)
                # silently passed → downstream junction
                # validators compared empty strings as a
                # match → wrong-assembly with no error.
                if len(val) != 4:
                    status.update(
                        f"[red]Position {pname!r} {label} must "
                        f"be exactly 4 bp (got {len(val)}): "
                        f"{val!r}[/red]"
                    )
                    return None
                bad = [c for c in val if c not in "ACGT"]
                if bad:
                    status.update(
                        f"[red]Position {pname!r} {label} must "
                        f"use ACGT only (Type IIS overhangs are "
                        f"fixed sticky ends — IUPAC ambiguity "
                        f"like N/W never matches a real cut): "
                        f"{''.join(sorted(set(bad)))[:10]}[/red]"
                    )
                    return None
            color = parts[4] if len(parts) >= 5 and parts[4] else None
            entry: dict = {
                "name": pname, "type": ptype, "oh5": poh5, "oh3": poh3,
            }
            if color:
                entry["color"] = color
            positions.append(entry)

        if not positions:
            status.update("[red]Need at least one position.[/red]")
            return None

        # Sweep #33: collision + self-cycle detection across
        # the grammar's position table. Two positions sharing
        # the same `oh5` (or same `oh3`) silently produced
        # ambiguous chains; a position whose `oh5 == oh3`
        # self-loops in the overhang digraph and breaks
        # assembly enumeration.
        seen_5: dict[str, str] = {}
        seen_3: dict[str, str] = {}
        for pos in positions:
            pname = pos["name"]
            poh5, poh3 = pos["oh5"], pos["oh3"]
            if poh5 == poh3:
                status.update(
                    f"[red]Position {pname!r} has identical "
                    f"5' and 3' overhangs ({poh5!r}) — would "
                    f"self-cycle in assembly. Use distinct "
                    f"overhangs per side.[/red]"
                )
                return None
            if poh5 in seen_5:
                status.update(
                    f"[red]Position {pname!r} reuses 5' "
                    f"overhang {poh5!r} from position "
                    f"{seen_5[poh5]!r}. Each 5' overhang must "
                    f"be unique to keep assembly "
                    f"deterministic.[/red]"
                )
                return None
            if poh3 in seen_3:
                status.update(
                    f"[red]Position {pname!r} reuses 3' "
                    f"overhang {poh3!r} from position "
                    f"{seen_3[poh3]!r}.[/red]"
                )
                return None
            seen_5[poh5] = pname
            seen_3[poh3] = pname

        coding_types = [t.strip() for t in coding.split(",") if t.strip()]

        # Auto-derive type_to_insdc — best-effort heuristic so Save As
        # Feature works without forcing the user to hand-edit JSON.
        # Coding types collapse to "CDS"; obvious labels (Promoter,
        # Terminator, 5'UTR/3'UTR) get their INSDC analogue; everything
        # else falls back to "misc_feature".
        type_to_insdc: dict[str, str] = {}
        for pos in positions:
            ptype = pos["type"]
            lower = ptype.lower()
            if ptype in coding_types:
                type_to_insdc[ptype] = "CDS"
            elif lower == "promoter":
                type_to_insdc[ptype] = "promoter"
            elif "terminator" in lower:
                type_to_insdc[ptype] = "terminator"
            elif lower.startswith("5") and "utr" in lower:
                type_to_insdc[ptype] = "5'UTR"
            elif lower.startswith("3") and "utr" in lower:
                type_to_insdc[ptype] = "3'UTR"
            else:
                type_to_insdc[ptype] = "misc_feature"

        return {
            "id":              self._grammar_id,
            "name":            name,
            "enzyme":          enzyme,
            "level_up_enzyme": level_up,
            "site":            site,
            "spacer":          spacer,
            "pad":             pad,
            "forbidden_sites": forbidden,
            "positions":       positions,
            "coding_types":    coding_types,
            "type_to_insdc":   type_to_insdc,
            "catalog":         self._grammar.get("catalog", []) or [],
            "editable":        True,
        }







class GrammarManagerModal(_OneShotDismissScreen, ModalScreen):
    """List all cloning grammars and let the user create / edit /
    delete custom ones. Built-in grammars (gb_l0, moclo_plant) appear
    in the list as read-only — Edit opens them in `GrammarEditorModal`
    in built-in / read-only mode, Delete is disabled.

    Custom grammars get the full lifecycle:

      * **+ New** — opens `GrammarEditorModal` in create-mode
        (``grammar_id=""``); on Save the editor slugs the user-typed
        name into a unique id and persists to ``cloning_grammars.json``.
      * **Edit** — wraps the editor launch with
        `EditGrammarConfirmModal` so the user knows the edit can
        cascade into already-saved TUs/MODs.
      * **Delete** — confirmation through a small inline notify; the
        actual remove goes through the editor's existing Delete path
        for symmetry.

    Dismisses with ``None`` (caller doesn't need a return value — the
    modal mutates the underlying ``cloning_grammars.json`` directly).
    """

    BINDINGS = [
        Binding("escape", "cancel", "Cancel"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    def compose(self) -> ComposeResult:
        with Vertical(id="gmgr-dlg"):
            yield Static(" Cloning grammars ", id="gmgr-title")
            yield DataTable(id="gmgr-table",
                              cursor_type="row",
                              zebra_stripes=True)
            with Horizontal(id="gmgr-btns"):
                yield Button("+ New",  id="btn-gmgr-new",  variant="primary")
                yield Button("Edit",   id="btn-gmgr-edit", variant="default")
                yield Button("Delete", id="btn-gmgr-del",  variant="error")
                yield Button("Close",  id="btn-gmgr-close")

    def on_mount(self) -> None:
        t = self.query_one("#gmgr-table", DataTable)
        t.add_columns("Name", "Type", "Enzyme", "Level-up", "Positions")
        self._refresh_table()

    def _refresh_table(self) -> None:
        try:
            t = self.query_one("#gmgr-table", DataTable)
        except NoMatches:
            return
        t.clear()
        # Built-ins first (canonical reference order), then custom
        # grammars sorted alphanumerically by display name so the
        # user's custom set scans naturally.
        rows: list[tuple[str, str, dict]] = []
        for gid in _BUILTIN_GRAMMARS:
            g = _BUILTIN_GRAMMARS[gid]
            rows.append((gid, "built-in", g))
        custom = [(g.get("id") or "", "custom", g)
                   for g in _load_custom_grammars()
                   if g.get("id")]
        custom.sort(key=lambda r: _natural_sort_key(
            str(r[2].get("name") or "")))
        rows.extend(custom)
        for gid, kind, g in rows:
            level_up = g.get("level_up_enzyme") or g.get("enzyme") or ""
            t.add_row(
                str(g.get("name") or "?"),
                kind,
                str(g.get("enzyme") or "?"),
                str(level_up),
                str(len(g.get("positions") or [])),
                key=gid,
            )

    def _selected_gid(self) -> str:
        try:
            t = self.query_one("#gmgr-table", DataTable)
        except NoMatches:
            return ""
        return _cursor_row_key(t) or ""

    def _focus_gid(self, gid: str) -> None:
        """Move the manager's table cursor to the row whose key
        matches ``gid``. Used after Save / Delete / New so the user
        doesn't lose their place. Best-effort: no-ops if the table
        isn't mounted or the gid isn't in the current rows."""
        if not gid:
            return
        try:
            t = self.query_one("#gmgr-table", DataTable)
        except NoMatches:
            return
        for i, row_key in enumerate(t.rows.keys()):
            if getattr(row_key, "value", None) == gid:
                try:
                    t.move_cursor(row=i)
                except Exception:
                    pass
                return

    @on(Button.Pressed, "#btn-gmgr-new")
    def _new(self, _) -> None:
        def _on_done(result):
            self._refresh_table()
            # `GrammarEditorModal._save` dismisses with the new id
            # (or the existing id for an in-place edit). Focus the
            # row so the user lands on their freshly-created grammar
            # instead of bouncing back to row 0 (the gb_l0 built-in).
            if isinstance(result, str) and result:
                self._focus_gid(result)
        self.app.push_screen(GrammarEditorModal(""), _on_done)

    @on(Button.Pressed, "#btn-gmgr-edit")
    def _edit(self, _) -> None:
        gid = self._selected_gid()
        if not gid:
            self.app.notify("Select a grammar first.", severity="warning")
            return
        # Built-ins skip the warning — they're read-only anyway, so
        # the editor just shows the canonical fields and the user can
        # bind / clear an entry vector. Custom grammars get the
        # cascade-warning so the user knows mid-flight edits can
        # invalidate already-saved TUs.
        if gid in _BUILTIN_GRAMMARS:
            def _on_done_builtin(result):
                self._refresh_table()
                if isinstance(result, str) and result:
                    self._focus_gid(result)
                else:
                    self._focus_gid(gid)
            self.app.push_screen(GrammarEditorModal(gid), _on_done_builtin)
            return
        all_grammars = _all_grammars()
        g = all_grammars.get(gid, {})
        nm = str(g.get("name") or gid)
        # Count parts that reference this grammar so the warning can
        # mention concrete impact ("3 saved TUs use this grammar").
        # Sweep #26: readonly iter — count-only.
        n_dependents = 0
        try:
            for p in _iter_parts_bin_readonly():
                if (p.get("grammar") or "gb_l0") == gid:
                    n_dependents += 1
        except Exception:
            n_dependents = 0

        def _open_editor() -> None:
            def _on_done(result):
                self._refresh_table()
                if isinstance(result, str) and result:
                    self._focus_gid(result)
                else:
                    # Fall back to the original gid when the editor
                    # dismisses with None (cancel) or "deleted".
                    self._focus_gid(gid)
            self.app.push_screen(GrammarEditorModal(gid), _on_done)

        # Skip the warning when there's nothing to warn about: a
        # grammar with zero saved dependents can't break anything
        # downstream, so the friction-vs-safety trade falls on the
        # friction side. The user still sees the editor's own
        # built-in/read-only banner if applicable.
        if n_dependents == 0:
            _open_editor()
            return

        def _confirmed(go: "bool | None") -> None:
            if go:
                _open_editor()

        self.app.push_screen(
            EditGrammarConfirmModal(nm, n_dependents),
            _confirmed,
        )

    @on(Button.Pressed, "#btn-gmgr-del")
    def _delete(self, _) -> None:
        gid = self._selected_gid()
        if not gid:
            self.app.notify("Select a grammar first.", severity="warning")
            return
        if gid in _BUILTIN_GRAMMARS:
            self.app.notify(
                "Built-in grammars can't be deleted.",
                severity="warning",
            )
            return
        entries = _load_custom_grammars()
        target = next((e for e in entries if e.get("id") == gid), None)
        if target is None:
            self.app.notify("Grammar not found.", severity="warning")
            return
        nm = str(target.get("name") or gid)
        # Count dependent parts so the confirmation surfaces the
        # actual blast radius. Cheap O(n_parts); the bin is small.
        # Sweep #26: readonly iter — count-only.
        n_dependents = 0
        try:
            for p in _iter_parts_bin_readonly():
                if (p.get("grammar") or "gb_l0") == gid:
                    n_dependents += 1
        except Exception:
            n_dependents = 0
        # Capture cursor position now so we can restore focus near
        # the deleted row after the table rebuild — without this,
        # the cursor jumps back to row 0 (the gb_l0 built-in) on
        # every delete, forcing the user to re-scroll for their
        # next custom grammar.
        try:
            t = self.query_one("#gmgr-table", DataTable)
            cursor_idx = t.cursor_row
        except (NoMatches, AttributeError):
            cursor_idx = -1

        def _confirmed(go: "bool | None") -> None:
            if not go:
                return
            entries_now = _load_custom_grammars()
            target_now = next(
                (e for e in entries_now if e.get("id") == gid), None,
            )
            if target_now is None:
                # Got deleted underneath us (parallel session, manual
                # edit). Surface so the user knows the action no-op'd
                # but isn't a bug.
                self.app.notify(
                    f"Grammar '{nm}' was already removed.",
                    severity="warning",
                )
                self._refresh_table()
                return
            new_entries = [e for e in entries_now if e.get("id") != gid]
            try:
                _save_custom_grammars(new_entries)
            except (OSError, RuntimeError) as exc:
                _notify_save_failure(self.app, "Custom grammars", exc)
                return
            # Clear EVERY entry-vector binding (Alpha1/Alpha2/Omega1/
            # Omega2 / etc.) keyed to this grammar id so a stale
            # binding doesn't ghost back when a future grammar
            # slugs to the same id. The default-role path on the old
            # `_set_entry_vector(gid, None)` only cleared one of N.
            try:
                _clear_entry_vectors_for_grammar(gid)
            except Exception:
                _log.exception(
                    "Grammar delete: entry-vector cleanup failed",
                )
            # If the just-deleted grammar was the active one, fall
            # back to gb_l0 so the rest of the app keeps a valid
            # handle.
            if _get_setting("active_grammar") == gid:
                _set_setting("active_grammar", "gb_l0")
            self.app.notify(f"Deleted grammar '{nm}'.")
            self._refresh_table()
            # Restore cursor to whichever row now sits where the
            # deleted one used to be (or the previous row if we
            # nuked the last one). Built-ins occupy the head of the
            # table; custom grammars start after them, so we never
            # let the cursor land on a built-in by accident.
            try:
                t2 = self.query_one("#gmgr-table", DataTable)
                row_count = t2.row_count
                if row_count > 0 and cursor_idx >= 0:
                    new_idx = min(cursor_idx, row_count - 1)
                    t2.move_cursor(row=new_idx)
            except (NoMatches, AttributeError):
                pass

        # Confirmation modal — built on the same shape as
        # `EditGrammarConfirmModal` but framed for delete (red
        # button, blast-radius copy). One mis-click on the bare
        # Delete button used to wipe the grammar plus all of its
        # entry-vector bindings without any prompt.
        msg = (
            f"  About to delete custom grammar [bold]{nm}[/bold].\n"
        )
        if n_dependents > 0:
            msg += (
                f"  [yellow]{n_dependents}[/yellow] saved "
                f"part{'s' if n_dependents != 1 else ''} "
                f"reference{'' if n_dependents != 1 else 's'} "
                f"this grammar — they'll keep their gb_text but "
                f"may stop chaining at the next cycle.\n"
            )
        msg += "  Entry-vector bindings for this grammar will also be removed."
        self.app.push_screen(
            _ConfirmDeleteGrammarModal(nm, msg),
            _confirmed,
        )

    @on(Button.Pressed, "#btn-gmgr-close")
    def _close(self, _) -> None:
        self.dismiss(None)

    def action_cancel(self) -> None:
        self.dismiss(None)


class EntryVectorsModal(_OneShotDismissScreen, ModalScreen):
    """All-roles entry-vector configuration screen.

    Replaces the single-slot widget that used to live inside
    `GrammarEditorModal`. Shows every role for the active grammar
    (UPD/Alpha1/Alpha2/Omega1/Omega2 for gb_l0; Acceptor1/Acceptor2
    for moclo_plant; user-defined for custom grammars) in one table.

    Two ways to fill the slots:

      * **Per-row Pick** — click a row's "Pick…" button to launch
        `PlasmidPickerModal` filtered to library entries that
        plausibly fit this role. Persists via `_set_entry_vector`
        immediately.
      * **Auto-detect from active collection** — runs
        `_detect_entry_vector_role` on every plasmid in the active
        collection and proposes role bindings. User confirms once
        to apply all.

    `_blocks_undo = True` because the modal mutates persistent
    state (entry_vectors.json) and the Constructor / Parts Bin
    / classifier all read from that file — a stray Ctrl+Z firing
    on the canvas underneath would race the save.

    Dismisses ``None`` always. The persistent state changes are
    saved on each interaction (Pick / Auto-detect / Clear), so the
    dismiss payload doesn't carry data.
    """

    _blocks_undo: bool = True
    # Re-entrancy / double-click guard for the off-thread auto-detect
    # worker. Set True when `_auto_btn` dispatches, cleared in the
    # worker's `finally` (mirrors `[INV-41]`'s `_state._settings_flush_running`
    # pattern so an exception can't permanently wedge the button).
    _auto_running: bool = False

    BINDINGS = [
        Binding("escape", "close",         "Close"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    DEFAULT_CSS = """
    #ev-dlg {
        width: 96; height: auto; max-height: 92%;
        background: $surface; border: solid $primary; padding: 1 2;
    }
    #ev-title {
        background: $primary-darken-2; color: $text;
        padding: 0 1; margin-bottom: 1; text-align: center;
    }
    #ev-grammar-row { height: 3; margin-bottom: 1; }
    #ev-grammar-row Label { padding: 1 1 0 0; }
    #ev-grammar-select { width: 60; }
    #ev-table { height: 14; margin-bottom: 1; }
    #ev-status { margin-bottom: 1; min-height: 1; }
    #ev-btns { align: right middle;  height: 3; margin-top: 1; }
    #ev-btns Button { margin-right: 1; }
    """

    def __init__(self, grammar_id: "str | None" = None) -> None:
        super().__init__()
        # Empty / None defaults to the active grammar from settings —
        # the most common path is "user is configuring the grammar
        # they're actively assembling with".
        self._grammar_id = grammar_id or _get_setting(
            "active_grammar", "gb_l0",
        ) or "gb_l0"

    # Per-grammar role list + display labels. For `gb_l0` we surface
    # all five canonical roles. For other grammars we fall back to
    # whatever's in `_CONSTRUCTOR_BACKBONES` plus the empty "" role
    # (singleton L0 donor) so the user can always bind a UPD-style
    # vector even on a custom grammar.
    @staticmethod
    def _roles_for_grammar(gid: str) -> "list[tuple[str, str, str]]":
        """Return ``[(role_key, display_label, hint), ...]`` for the
        given grammar. ``role_key`` matches the persisted ``role``
        field; ``hint`` is a short user-facing description (e.g.
        "L0 acceptor / donor")."""
        out: list[tuple[str, str, str]] = [
            ("", "UPD / L0 donor", "Singleton L0 acceptor")
        ]
        backbones = _CONSTRUCTOR_BACKBONES.get(gid, {})
        for role_key, meta in backbones.items():
            note = (meta.get("note") or "").strip()
            sel = (meta.get("selection") or "").strip()
            hint = note
            if sel:
                hint = f"{note} · {sel}" if note else sel
            display = role_key
            # Pretty Greek letter display for the canonical pDGB3 roles.
            # The "1/2" suffix is a slot (overhang-pair) distinction,
            # NOT a strand orientation — TUs cloned alone into α1 vs α2
            # land in the same direction; the slot only affects relative
            # orientation in multipartite Ω assemblies.
            if role_key == "Alpha1":  display = "α1 — L1 slot 1"
            elif role_key == "Alpha2":  display = "α2 — L1 slot 2"
            elif role_key == "Omega1":  display = "Ω1 — L2 slot 1"
            elif role_key == "Omega2":  display = "Ω2 — L2 slot 2"
            out.append((role_key, display, hint))
        return out

    def compose(self) -> ComposeResult:
        with Vertical(id="ev-dlg"):
            yield Static(" Entry Vectors ", id="ev-title")
            with Horizontal(id="ev-grammar-row"):
                yield Label("Grammar:")
                opts = [
                    (g.get("name", gid), gid)
                    for gid, g in _all_grammars().items()
                ]
                yield Select(
                    options=opts, value=self._grammar_id,
                    id="ev-grammar-select",
                    allow_blank=False,
                )
            yield DataTable(
                id="ev-table",
                cursor_type="row",
                zebra_stripes=True,
            )
            yield Static("", id="ev-status", markup=True)
            with Horizontal(id="ev-btns"):
                yield Button(
                    "Pick / Change", id="btn-ev-pick",
                    variant="primary",
                )
                yield Button("Clear row", id="btn-ev-clear")
                yield Button(
                    "Auto-detect from active collection",
                    id="btn-ev-auto",
                    variant="success",
                )
                yield Button("Close", id="btn-ev-close")

    def on_mount(self) -> None:
        try:
            t = self.query_one("#ev-table", DataTable)
        except NoMatches:
            return
        t.add_columns("Role", "Vector", "Hint")
        self._refresh_table()
        # Focus on the table so arrow keys + Enter drive the picks.
        try:
            t.focus()
        except Exception:
            pass

    def _refresh_table(self) -> None:
        try:
            t = self.query_one("#ev-table", DataTable)
            status = self.query_one("#ev-status", Static)
        except NoMatches:
            return
        t.clear()
        roles = self._roles_for_grammar(self._grammar_id)
        n_bound = 0
        backbones = _CONSTRUCTOR_BACKBONES.get(self._grammar_id, {})
        # `family_markers[family]` → list of (role_key, detected_marker)
        # for every BOUND role with a detectable marker. Drives the
        # intra-pair-mismatch + cross-family-collision warnings below.
        family_markers: dict[str, list[tuple[str, str]]] = {}
        for role_key, display, hint in roles:
            ev = _get_entry_vector(self._grammar_id, role_key)
            detected: "str | None" = None
            if ev:
                n_bound += 1
                name = ev.get("name") or "(unnamed)"
                size = ev.get("size") or 0
                vector_text = Text(
                    f"{name}  ·  {size:,} bp", style="bold green",
                )
                detected = _detect_selection_marker(
                    str(ev.get("gb_text", "") or "")
                )
                note = (
                    backbones.get(role_key, {}).get("note") or ""
                ).strip()
                marker_label = detected or "(no marker detected)"
                hint = (
                    f"{note} · {marker_label}" if note else marker_label
                )
            else:
                vector_text = Text("(not set)", style="dim italic")
            t.add_row(
                Text(display, style="bold"),
                vector_text,
                Text(hint, style="dim"),
                key=role_key or "_upd_",
            )
            # Bucket bound + detected entries by family prefix
            # (Alpha1/Alpha2 → "Alpha", Omega1/Omega2 → "Omega",
            # Acceptor1/Acceptor2 → "Acceptor"). The trailing digit
            # is the slot index — strip it to get the family.
            if role_key and detected:
                fam_match = re.match(r"^(.*?)(\d+)$", role_key)
                if fam_match:
                    family = fam_match.group(1)
                    family_markers.setdefault(family, []).append(
                        (role_key, detected),
                    )
        grammar_name = _all_grammars().get(
            self._grammar_id, {},
        ).get("name", self._grammar_id)
        warnings = self._marker_warnings(family_markers)
        status_lines = [
            f"  [dim]{grammar_name}: {n_bound}/{len(roles)} "
            f"role(s) bound.[/dim]"
        ]
        for w in warnings:
            status_lines.append(f"  [yellow]⚠ {w}[/yellow]")
        status.update("\n".join(status_lines))

    @staticmethod
    def _marker_warnings(
        family_markers: "dict[str, list[tuple[str, str]]]",
    ) -> "list[str]":
        """Return user-facing warnings for selection-marker
        inconsistencies across the bound entry vectors.

        Two rules, both per the Golden Braid iteration protocol:

          1. **Intra-pair**: roles within a family (α1+α2, Ω1+Ω2,
             Acceptor1+Acceptor2) must carry the SAME marker, since
             the bench-side selection is per-iteration-level, not
             per-slot.
          2. **Cross-family**: distinct families (α vs Ω) MUST carry
             DIFFERENT markers, otherwise the iteration cycle's
             selection step can't tell which level just assembled.

        Partial bindings (fewer than 2 bound + detected per family,
        or only one family bound) skip the corresponding check —
        the user is mid-config, not in a final inconsistent state.
        """
        warnings: list[str] = []
        # Intra-family pair mismatch.
        for family, members in family_markers.items():
            if len(members) < 2:
                continue
            uniq = {m[1] for m in members}
            if len(uniq) > 1:
                detail = ", ".join(
                    f"{rk}={mk}" for rk, mk in members
                )
                warnings.append(
                    f"{family} pair mismatch ({detail}) — both slots "
                    f"should carry the same antibiotic"
                )
        # Cross-family collision.
        families = list(family_markers.keys())
        for i, fam1 in enumerate(families):
            for fam2 in families[i + 1:]:
                m1 = {m[1] for m in family_markers[fam1]}
                m2 = {m[1] for m in family_markers[fam2]}
                shared = m1 & m2
                for marker in sorted(shared):
                    warnings.append(
                        f"{fam1} and {fam2} both carry {marker} — "
                        f"iteration cycles won't be distinguishable by "
                        f"selection"
                    )
        return warnings

    def _selected_role(self) -> "str | None":
        try:
            t = self.query_one("#ev-table", DataTable)
        except NoMatches:
            return None
        if t.cursor_row is None:
            return None
        roles = self._roles_for_grammar(self._grammar_id)
        if not (0 <= t.cursor_row < len(roles)):
            return None
        return roles[t.cursor_row][0]

    @on(Select.Changed, "#ev-grammar-select")
    def _on_grammar_changed(self, event: Select.Changed) -> None:
        if isinstance(event.value, str) and event.value:
            self._grammar_id = event.value
            self._refresh_table()

    @on(Button.Pressed, "#btn-ev-pick")
    def _pick_btn(self, _) -> None:
        role = self._selected_role()
        if role is None:
            try:
                self.query_one("#ev-status", Static).update(
                    "[yellow]Select a role row first.[/yellow]"
                )
            except NoMatches:
                pass
            return
        current = _get_entry_vector(self._grammar_id, role)
        current_id = (current or {}).get("id")

        def _on_picked(picked_id) -> None:
            if not picked_id:
                return
            # Locate the library entry by id.
            # Sweep #25: helper avoids the full-library deepcopy.
            entry = _find_library_entry_by_id(picked_id)
            if entry is None:
                try:
                    self.query_one("#ev-status", Static).update(
                        "[red]Picked entry not found in library.[/red]"
                    )
                except NoMatches:
                    pass
                return
            ev_payload = {
                "name":     entry.get("name") or picked_id,
                "size":     entry.get("size") or 0,
                "source":   "library",
                "id":       picked_id,
                "gb_text":  entry.get("gb_text") or "",
            }
            try:
                _set_entry_vector(self._grammar_id, ev_payload, role)
            except (OSError, RuntimeError) as exc:
                # `_save_entry_vectors` → `_safe_save_json` re-raises on
                # failure (invariant #7); surface a friendly toast instead of
                # an uncaught crash, and don't log a bind that didn't persist.
                _notify_save_failure(self.app, "Entry vectors", exc)
                return
            _log_event(
                "entry_vector.bound",
                grammar=self._grammar_id, role=role,
                source="library", entry_id=picked_id,
            )
            self._refresh_table()

        self.app.push_screen(
            PlasmidPickerModal(current_id=current_id), _on_picked,
        )

    @on(Button.Pressed, "#btn-ev-clear")
    def _clear_btn(self, _) -> None:
        role = self._selected_role()
        if role is None:
            return
        if _get_entry_vector(self._grammar_id, role) is None:
            return
        try:
            _set_entry_vector(self._grammar_id, None, role)
        except (OSError, RuntimeError) as exc:
            _notify_save_failure(self.app, "Entry vectors", exc)
            return
        _log_event(
            "entry_vector.cleared",
            grammar=self._grammar_id, role=role,
        )
        self._refresh_table()

    @on(Button.Pressed, "#btn-ev-auto")
    def _auto_btn(self, _) -> None:
        try:
            status = self.query_one("#ev-status", Static)
        except NoMatches:
            return
        if self._auto_running:
            return
        active = _get_active_collection_name()
        if not active:
            status.update(
                "[yellow]No active collection — set one via "
                "Library panel first.[/yellow]"
            )
            return
        grammar = _all_grammars().get(self._grammar_id)
        if not isinstance(grammar, dict):
            status.update("[red]Grammar not found.[/red]")
            return
        coll = _find_collection(active) or {}
        coll_entries = [
            e for e in (coll.get("plasmids") or [])
            if isinstance(e, dict)
        ]
        if not coll_entries:
            status.update(
                "[yellow]Active collection is empty.[/yellow]"
            )
            return
        # Heavy work — parse N gb_texts + N×enzyme digests + 1 batched
        # save — moves to a worker so the terminal doesn't freeze.
        # `_record_load_counter` doesn't apply here (modal isn't tied
        # to a canvas record); staleness guards instead check the
        # captured grammar_id against the current one before applying,
        # and `is_mounted` before touching widgets.
        self._auto_running = True
        try:
            btn = self.query_one("#btn-ev-auto", Button)
            btn.disabled = True
        except NoMatches:
            pass
        status.update(
            f"[dim]Auto-detecting across {len(coll_entries)} "
            f"plasmid(s)…[/dim]"
        )
        self._auto_detect_worker(
            list(coll_entries), self._grammar_id, dict(grammar),
        )

    @work(thread=True, exclusive=True, group="ev-auto-detect")
    def _auto_detect_worker(
        self,
        coll_entries: "list[dict]",
        grammar_id: str,
        grammar: dict,
    ) -> None:
        """Off-thread entry-vector detection across an active collection.

        Three reasons this moved off the UI thread (see [PIT-28] +
        [CONV] worker pattern):
          1. `_gb_text_to_record` runs BioPython GenBank parse per
             entry (~5–50 ms each, LRU-cached). Cold first click on
             a 200–500 plasmid collection was 4–30 s of frozen UI.
          2. `_detect_entry_vector_role` runs two `_excise_fragment_pair`
             passes per plasmid (full restriction scan + feature split
             + backbone-marker scan). Same pitfall #28 cost model as
             pairwise alignment / restriction scan.
          3. The N×`_set_entry_vector` save loop pre-fix did N
             `_safe_save_json` round-trips (`.bak` + fsync each).
             Now collapsed to ONE `_set_entry_vectors_batch` call.

        Staleness: captures `grammar_id` at entry. On completion checks
        `self._grammar_id` against capture before applying — if the
        user changed the grammar dropdown mid-flight, the worker still
        binds to the grammar the user actually requested when they
        clicked the button. UI updates check `self.is_mounted` so a
        worker that finishes after the modal closes is a no-op.
        """
        try:
            proposals: dict[str, tuple[dict, str]] = {}
            n_total = len(coll_entries)
            progress_step = max(1, n_total // 20)  # ~20 updates max
            for idx, entry in enumerate(coll_entries):
                gb_text = entry.get("gb_text") or ""
                if not gb_text:
                    continue
                # Cached wrapper — re-clicks Auto-detect or re-opens
                # the modal on the same collection skip the expensive
                # dual-enzyme digest. Cache invalidated by
                # `_save_custom_grammars` when enzymes shift.
                result = _detect_entry_vector_role_cached(gb_text, grammar)
                if result:
                    role, conf = result
                    existing = proposals.get(role)
                    if existing is None or (
                        existing[1] == "weak" and conf == "strict"
                    ):
                        proposals[role] = (entry, conf)
                if (idx + 1) % progress_step == 0:
                    self.app.call_from_thread(
                        self._update_auto_progress,
                        idx + 1, n_total,
                    )
            # Build update list now so `_set_entry_vectors_batch` is
            # ONE save instead of N. Existing bindings survive —
            # user-set bindings take precedence.
            applied: list[tuple[str, str, str]] = []  # (role_key, label, conf)
            skipped: list[str] = []
            updates: "list[tuple[str, str, dict | None]]" = []
            for role_key, (entry, conf) in proposals.items():
                if _get_entry_vector(grammar_id, role_key) is not None:
                    skipped.append(role_key or "UPD")
                    continue
                payload = {
                    "name":    entry.get("name") or entry.get("id", "?"),
                    "size":    entry.get("size") or 0,
                    "source":  "auto-detect",
                    "id":      entry.get("id", ""),
                    "gb_text": entry.get("gb_text") or "",
                }
                updates.append((grammar_id, role_key, payload))
                applied.append(
                    (role_key, role_key or "UPD", conf),
                )
            if updates:
                _set_entry_vectors_batch(updates)
                for role_key, _label, conf in applied:
                    _log_event(
                        "entry_vector.auto_bound",
                        grammar=grammar_id, role=role_key,
                        confidence=conf,
                    )
        except Exception as exc:
            _log.exception("EV auto-detect worker failed")
            self.app.call_from_thread(
                self._finish_auto_detect,
                grammar_id, [], [], str(exc),
            )
            return
        finally:
            # Clear the in-flight flag even on exception so a future
            # click isn't permanently blocked ([INV-41] try/finally).
            self._auto_running = False
        applied_labels = [label for _r, label, _c in applied]
        self.app.call_from_thread(
            self._finish_auto_detect,
            grammar_id, applied_labels, skipped, "",
        )

    def _update_auto_progress(self, done: int, total: int) -> None:
        """UI-thread callback for periodic progress."""
        if not self.is_mounted:
            return
        try:
            status = self.query_one("#ev-status", Static)
        except NoMatches:
            return
        status.update(
            f"[dim]Auto-detecting ({done}/{total})…[/dim]"
        )

    def _finish_auto_detect(
        self,
        scanned_grammar_id: str,
        applied: "list[str]",
        skipped: "list[str]",
        error: str,
    ) -> None:
        """UI-thread completion callback. No-op if the modal has
        unmounted between dispatch and finish."""
        # Re-enable the button regardless of mount state — but the
        # widget query can fail if the modal closed.
        if self.is_mounted:
            try:
                self.query_one("#btn-ev-auto", Button).disabled = False
            except NoMatches:
                pass
        if not self.is_mounted:
            return
        try:
            status = self.query_one("#ev-status", Static)
        except NoMatches:
            return
        if error:
            status.update(
                f"[red]Auto-detect failed: {error}[/red]"
            )
            return
        if not applied and not skipped:
            status.update(
                "[yellow]No acceptors detected in active "
                "collection.[/yellow]"
            )
            return
        # If the user switched grammars mid-flight, tell them the
        # bindings landed on the grammar they originally clicked from.
        grammar_note = ""
        if scanned_grammar_id != self._grammar_id:
            scanned_name = _all_grammars().get(
                scanned_grammar_id, {},
            ).get("name", scanned_grammar_id)
            grammar_note = (
                f"  [dim](bound to {scanned_name})[/dim]"
            )
        msg = (
            f"[green]Auto-detected {len(applied)} role(s):[/green] "
            f"{', '.join(applied) if applied else '(none new)'}"
            f"{grammar_note}"
        )
        if skipped:
            msg += (
                f"  [dim](skipped {len(skipped)}: "
                f"{', '.join(skipped)} — already bound)[/dim]"
            )
        status.update(msg)
        self._refresh_table()

    @on(Button.Pressed, "#btn-ev-close")
    def _close_btn(self, _) -> None:
        self.dismiss(None)

    @_action_log("app.entry_vectors.close")
    def action_close(self) -> None:
        self.dismiss(None)


# ── Parts bin modal ────────────────────────────────────────────────────────────


# ── More modals moved to splicecraft_modals (Phase D) ───────────────────────
from splicecraft_modals import (  # noqa: E402
    PartEditModal as PartEditModal,
)


class PartsBinPickerModal(_OneShotDismissScreen, ModalScreen):
    """Browse, create, rename, delete, and duplicate parts bins.

    Mirrors `CollectionsModal` for the parts-bin side of the
    multi-bin architecture. Each entry in the table is a named bin
    from `parts_bin_collections.json`; selecting one sets it active
    and dismisses with the bin name so the caller can open
    `PartsBinModal` against the freshly-active bin.

    Refuses to delete the last remaining bin — empty parts state is
    fine, but a bin-less state would orphan the `_save_parts_bin`
    mirror and the migration would re-create "Main Parts Bin" on
    next launch anyway. The cleaner UX is to nudge the user.

    Dismiss payload:
      ``None``  — cancelled (Esc / Close / no selection on Open)
      ``str``   — name of the bin to open; caller pushes
                  `PartsBinModal` after switching the active pointer.
    """

    # Sweep #26: CRUD on parts-bin disk state — block app-level
    # Ctrl+Z so a misclick can't roll back the canvas while the
    # user is navigating the bins picker.
    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel",         "Close"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    def compose(self) -> ComposeResult:
        with Vertical(id="binpick-dlg"):
            yield Static(" Parts Bins ", id="binpick-title")
            yield Label(
                "Pick a bin to open, or use the buttons to "
                "create / rename / delete / duplicate one.",
                id="binpick-help",
            )
            yield DataTable(id="binpick-table", cursor_type="row",
                            zebra_stripes=True)
            yield Static("", id="binpick-status", markup=True)
            with Horizontal(id="binpick-btns"):
                yield Button("Open", id="btn-binpick-open",
                             variant="primary")
                yield Button("New", id="btn-binpick-new")
                yield Button("Rename", id="btn-binpick-rename")
                yield Button("Duplicate", id="btn-binpick-dup")
                yield Button("Delete", id="btn-binpick-del",
                             variant="error")
                yield Button("Close", id="btn-binpick-close")

    def on_mount(self) -> None:
        t = self.query_one("#binpick-table", DataTable)
        t.add_columns("Name", "# Parts", "Description", "Saved")
        self._repopulate()
        t.focus()

    def _repopulate(self) -> None:
        """Rebuild the bin table from disk and cursor onto the active
        bin (so the user's most-recent context is highlighted by
        default). Natural-sort by name so `bin2` lands before `bin10`.
        """
        t = self.query_one("#binpick-table", DataTable)
        t.clear()
        bins = sorted(
            _load_parts_bin_collections(),
            key=lambda b: _natural_sort_key(b.get("name") or ""),
        )
        active = _get_active_parts_bin_name()
        cursor = 0
        for i, b in enumerate(bins):
            name = b.get("name") or "?"
            n_parts = len(b.get("parts", []) or [])
            desc = (b.get("description") or "")[:50]
            saved = _history_human_dt(b.get("saved") or "")
            t.add_row(name, str(n_parts), desc, saved, key=name)
            if active and name == active:
                cursor = i
        if bins:
            t.move_cursor(row=cursor)

    def _selected_bin_name(self) -> "str | None":
        return _cursor_row_key(self.query_one("#binpick-table", DataTable))

    def _set_status(self, msg: str) -> None:
        try:
            self.query_one("#binpick-status", Static).update(msg)
        except NoMatches:
            pass

    # ── Open ──────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-binpick-open")
    def _open(self, _) -> None:
        name = self._selected_bin_name()
        if not name:
            self._set_status("[red]No bin selected.[/red]")
            return
        # Switch + mirror via the shared helper (single source of truth
        # for the [INV-83] mirror-swap). Returns False only when the bin
        # vanished between populate and Open.
        try:
            switched = _switch_active_parts_bin(name)
        except (OSError, RuntimeError) as exc:
            _notify_save_failure(self.app, "Parts bin", exc)
            return
        if not switched:
            self._set_status(f"[red]Bin '{name}' not found.[/red]")
            self._repopulate()
            return
        self.dismiss(name)

    @on(DataTable.RowSelected, "#binpick-table")
    def _row_selected(self, event) -> None:
        # Enter on a row = Open. Mirrors PlasmidPickerModal so the
        # picker behaves consistently across the app.
        self._open(None)

    # ── New ───────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-binpick-new")
    def _new(self, _) -> None:
        def _on_named(name):
            if not name:
                return
            if _parts_bin_name_taken(name):
                self._set_status(
                    f"[red]A bin named '{name}' already exists.[/red]"
                )
                return
            bins = _load_parts_bin_collections()
            bins.append({
                "name":        name,
                "description": "New parts bin",
                "parts":       [],
                "saved":       _date.today().isoformat(),
            })
            try:
                _save_parts_bin_collections(bins)
            except (OSError, RuntimeError) as exc:
                _notify_save_failure(self.app, "Parts-bin collections", exc)
                return
            self._set_status(f"[green]Created bin '{name}'.[/green]")
            self._repopulate()
        self.app.push_screen(
            CollectionNameModal(
                title="New parts bin",
                placeholder="Parts bin name",
            ),
            callback=_on_named,
        )

    # ── Rename ────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-binpick-rename")
    def _rename(self, _) -> None:
        old = self._selected_bin_name()
        if not old:
            self._set_status("[red]No bin selected.[/red]")
            return

        def _on_named(new_name):
            if not new_name or new_name == old:
                return
            if _parts_bin_name_taken(new_name):
                self._set_status(
                    f"[red]A bin named '{new_name}' already exists.[/red]"
                )
                return
            bins = _load_parts_bin_collections()
            for b in bins:
                if b.get("name") == old:
                    b["name"] = new_name
                    break
            else:
                self._set_status(
                    f"[red]Bin '{old}' has vanished — refresh.[/red]"
                )
                self._repopulate()
                return
            try:
                _save_parts_bin_collections(bins)
            except (OSError, RuntimeError) as exc:
                _notify_save_failure(self.app, "Parts-bin collections", exc)
                return
            # Carry the active-bin pointer if we just renamed it.
            if _get_active_parts_bin_name() == old:
                _set_active_parts_bin_name(new_name)
            self._set_status(
                f"[green]Renamed '{old}' → '{new_name}'.[/green]"
            )
            self._repopulate()
        self.app.push_screen(
            CollectionNameModal(
                title=f"Rename parts bin '{old}'",
                current=old,
                placeholder="New name",
            ),
            callback=_on_named,
        )

    # ── Duplicate ─────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-binpick-dup")
    def _duplicate(self, _) -> None:
        source = self._selected_bin_name()
        if not source:
            self._set_status("[red]No bin selected.[/red]")
            return

        def _on_named(new_name):
            if not new_name or new_name == source:
                return
            if _parts_bin_name_taken(new_name):
                self._set_status(
                    f"[red]A bin named '{new_name}' already exists.[/red]"
                )
                return
            src = _find_parts_bin(source)
            if src is None:
                self._set_status(
                    f"[red]Source bin '{source}' has vanished.[/red]"
                )
                self._repopulate()
                return
            bins = _load_parts_bin_collections()
            bins.append({
                "name":        new_name,
                "description": (
                    f"Duplicated from '{source}'"
                ),
                # Deep-copy so subsequent edits to either bin don't
                # touch the other (the loader deepcopies on read, but
                # explicit here makes the intent obvious).
                "parts":       _typed_clone(src.get("parts", []) or []),
                "saved":       _date.today().isoformat(),
            })
            try:
                _save_parts_bin_collections(bins)
            except (OSError, RuntimeError) as exc:
                _notify_save_failure(self.app, "Parts-bin collections", exc)
                return
            self._set_status(
                f"[green]Duplicated '{source}' → '{new_name}'.[/green]"
            )
            self._repopulate()
        self.app.push_screen(
            CollectionNameModal(
                title=f"Duplicate parts bin '{source}'",
                current=f"{source} copy",
                placeholder="New bin name",
            ),
            callback=_on_named,
        )

    # ── Delete ────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-binpick-del")
    def _delete(self, _) -> None:
        name = self._selected_bin_name()
        if not name:
            self._set_status("[red]No bin selected.[/red]")
            return
        bins = _load_parts_bin_collections()
        # Refuse to delete the last remaining bin — a bin-less state
        # would orphan the `_save_parts_bin` mirror, and migration
        # would re-create "Main Parts Bin" on next launch anyway.
        if len(bins) <= 1:
            self._set_status(
                "[red]Can't delete the last remaining bin — "
                "create another first.[/red]"
            )
            return
        remaining = [b for b in bins if b.get("name") != name]
        try:
            _save_parts_bin_collections(remaining)
        except (OSError, RuntimeError) as exc:
            _notify_save_failure(self.app, "Parts-bin collections", exc)
            return
        # If the user deleted the active bin, promote the first
        # remaining one to active so subsequent `_save_parts_bin`
        # mirror writes land somewhere valid.
        if _get_active_parts_bin_name() == name:
            promoted = remaining[0].get("name")
            if promoted:
                # Sweep #11 (2026-05-20): force-flush settings pointer
                # before the parts_bin.json re-seed so a power loss
                # between the two writes can't leave settings.json
                # saying OLD while parts_bin.json holds the promoted
                # bin's parts. Same fix sweep #9 applied to project
                # delete-promote.
                _set_active_parts_bin_name(promoted)
                _settings_flush_sync()
                # Re-seed `parts_bin.json` with the promoted bin's
                # parts so the next `_load_parts_bin` doesn't return
                # the deleted bin's contents.
                try:
                    _safe_save_json(
                        _state._PARTS_BIN_FILE,
                        list(remaining[0].get("parts", []) or []),
                        "Parts bin",
                    )
                    _state._parts_bin_cache = None
                    _clear_assembly_fragment_cache()
                except (OSError, RuntimeError) as exc:
                    # Surface so the user knows the success toast
                    # below is misleading: cache is invalidated but
                    # disk wasn't re-seeded → next launch reads
                    # stale data from the deleted bin.
                    _notify_save_failure(
                        self.app,
                        f"Re-seed Parts bin after delete '{name}'",
                        exc,
                    )
                    return
        self._set_status(f"[dim]Deleted bin '{name}'.[/dim]")
        self._repopulate()

    # ── Close ─────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-binpick-close")
    def _close_btn(self, _) -> None:
        self.dismiss(None)

    def action_cancel(self) -> None:
        self.dismiss(None)


class PartsBinModal(_OneShotDismissScreen, Screen):
    """Modular cloning parts library — full-screen view.

    Uses Screen (not ModalScreen) so it fills the terminal cleanly instead
    of floating a fixed-size box on a dark overlay. Escape or the Close
    button pops back to the main app.

    The active **grammar** (Golden Braid L0, MoClo Plant, or any
    user-defined custom) gates what's visible: only catalog and
    user-saved parts tagged with the active grammar's id show up.
    The Grammar dropdown at the top of the modal switches grammars
    (persisted in `settings.json` as ``active_grammar``); the
    overhang table beneath it is the canonical Position / Type / 5'OH
    / 3'OH map for the active grammar so the user always knows which
    sticky ends apply. ``Edit`` and ``Duplicate`` open the grammar
    editor; built-in grammars are read-only there, but
    "Duplicate as Custom" forks them into a new editable grammar.

    The "Feat Lib" column flags parts already registered in the
    persistent feature library. We build a single
    ``{(name, feature_type): sequence_upper}`` index on first
    populate and reuse it across renders. The cache is gated on
    ``_state._features_generation`` — bumped by every ``_save_features``
    call — so the column stays in sync with edits made by Save As
    Feature, Alt+Shift+C capture, or the Feature Library workbench
    without paying the scan cost on every populate.
    """

    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel", "Cancel"),
        Binding("tab",    "app.focus_next", "Next", show=False),
        # Delete key fires the same multi-select-aware delete flow as
        # the Delete button; lets the user bulk-delete a Ctrl+click
        # selection without reaching for the mouse. `priority=True`
        # keeps DataTable from swallowing the keystroke for its own
        # cursor-based "delete row" handling (which would otherwise
        # bypass the confirm modal).
        Binding("delete", "delete_selected_parts", "Delete part(s)",
                show=False, priority=True),
        # Ctrl+A selects every row in the active tab so a Delete /
        # Del keypress can wipe the whole filtered slice (e.g. clean
        # out every TU before re-running an assembly batch). Best-
        # effort: many terminals intercept Ctrl+A for tmux / line-
        # editing, so we register at priority and silently no-op
        # when the keystroke never reaches Textual.
        Binding("ctrl+a", "select_all_parts", "Select all",
                show=False, priority=True),
    ]

    # IDs of every action button in the parts-row except the
    # save-to-collection one — populated once on the class so
    # `_refresh_multi_select_visuals` can dim them in bulk when the
    # user enters multi-select mode. Listed explicitly (not via a
    # widget walk) so adding a new button is a single-line change in
    # both `compose` and here.
    _OTHER_BTN_IDS: tuple[str, ...] = (
        "#btn-parts-copy-primed",
        "#btn-parts-copy-cloned",
        "#btn-parts-edit",
        "#btn-new-part",
        "#btn-load-part",
        "#btn-parts-save-as-feature",
        "#btn-parts-export-fasta",
    )

    def __init__(self, *, auto_trigger_new_part: bool = False,
                 clone_prefill_seq: str = "",
                 clone_prefill_name: str = "",
                 clone_prefill_feats: "list[dict] | None" = None) -> None:
        super().__init__()
        # Pre-built feature-library index for the "Feat Lib" column.
        # Re-derived only when `_state._features_generation` differs from the
        # snapshot we last saw, so opening the parts bin from a
        # session where the feature library hasn't changed avoids the
        # whole scan.
        self._feat_lib_index: dict[tuple[str, str], str] = {}
        self._feat_lib_gen_seen: int = -1
        # Sweep #14 (2026-05-20) — Synthesis "Clone Fragment" entry
        # point. The Synthesis screen pushes ``PartsBinModal(
        # auto_trigger_new_part=True, clone_prefill_seq=seq)`` after
        # auto-saving + loading its fragment as the canvas record;
        # on_mount fires ``_new_part(None)`` after the first paint so
        # the user lands directly in the Domesticator with no extra
        # clicks. ``clone_prefill_seq`` carries the full fragment seq
        # straight into the Domesticator's direct-input TextArea on
        # the first auto-trigger; it self-clears after firing so a
        # subsequent manual "New Part" click opens an empty form.
        self._auto_trigger_new_part: bool = bool(auto_trigger_new_part)
        self._clone_prefill_seq: str = (clone_prefill_seq or "").upper()
        # 2026-06-05 — carry the fragment NAME alongside the seq so the
        # Domesticator's part-name field is pre-filled. One-shot, mirrors
        # `_clone_prefill_seq` (cleared after the auto-trigger fires).
        self._clone_prefill_name: str = (clone_prefill_name or "").strip()
        # Source features (CDS etc.) to carry onto the cloned part's insert so
        # the primed FRAG shows its feature bar. One-shot like the seq / name;
        # consumed + cleared in `_new_part`.
        self._clone_prefill_feats: list[dict] = [
            dict(f) for f in (clone_prefill_feats or []) if isinstance(f, dict)]
        # Multi-select state for bulk save-to-collection / delete.
        # Set of row indices into `self._rows`. A non-empty set dims
        # the non-bulk action buttons so Save-to-Collection + Delete
        # become the only forward paths.
        #
        # Two entry paths populate this set:
        #
        #   1. Drag-select. `on_mouse_down` records the start row,
        #      `on_mouse_move` updates the range as the user drags
        #      across rows. Works in every terminal (no modifier
        #      needed) — the most reliable multi-select gesture.
        #
        #   2. Modifier+click toggle. The user holds any of
        #      Ctrl / Shift / Alt and clicks rows one by one to
        #      build a non-contiguous selection. We accept all three
        #      modifiers because gnome-terminal eats Ctrl+click for
        #      URL handling, so Shift / Alt are the practical
        #      fallbacks; whichever the terminal transmits flips the
        #      `_click_with_modifier` flag we read in `on_mouse_up`.
        self._selected_rows: set[int] = set()
        # Drag-select bookkeeping. `_drag_active` flips True between
        # MouseDown and MouseUp; `_drag_changed` flips True the first
        # time MouseMove crosses a row boundary so MouseUp can tell
        # a real drag from a stray pointer wiggle and decide whether
        # to commit the range or fall back to the click path.
        # `_drag_initial` snapshots the multi-select set at drag-start
        # so on_mouse_move UNIONs the dragged range with the user's
        # prior selection — pre-2026-05-07 the move handler REPLACED
        # the set, which wiped earlier modifier+click toggles the
        # moment a subsequent click had any pointer wiggle.
        # `_click_with_modifier` is captured on MouseDown rather than
        # MouseUp / Click because the Click event isn't reliably
        # delivered from DataTable cells in every terminal — MouseUp
        # is, and reading the modifier off MouseDown sidesteps the
        # cases where the terminal reports the modifier on press but
        # drops it on release.
        self._drag_start_row: int = -1
        self._drag_active: bool = False
        self._drag_changed: bool = False
        self._drag_initial: "set[int]" = set()
        self._click_with_modifier: bool = False
        # Active level tab — drives `_all_rows` filtering. Default L0
        # so the bin opens to the same view it always has. The Tabs
        # widget mirrors this in its UI state. ``2`` is "MOD" (any
        # plasmid with `level >= 2`).
        self._active_level: int = 0

    def compose(self) -> ComposeResult:
        """Single-pane loadout: parts table dominates, detail + sequence
        peek out at the bottom, all buttons live on a single bottom row.
        A `Tabs` strip at the top filters by part level (L0 / TU / MOD)
        so domesticated parts, single transcription units, and modules
        live in their own slices of the bin without mixing.
        """
        yield Header()
        with Vertical(id="parts-box"):
            # Show the active bin in the banner so the user knows which
            # parts bin they're working in at a glance (matches the
            # " Synthesis — … " title style).
            _bin = _get_active_parts_bin_name() or _DEFAULT_PARTS_BIN_NAME
            yield Static(f" Parts Bin — {_bin} ", id="parts-title")
            yield Tabs(
                Tab("L0 parts",   id="tab-parts-l0"),
                Tab("TUs",        id="tab-parts-tu"),
                Tab("Modules",    id="tab-parts-mod"),
                id="parts-level-tabs",
            )
            yield DataTable(id="parts-table", cursor_type="row", zebra_stripes=True)
            yield Static("", id="parts-detail")
            # Read-only TextArea so the full sequence is visible with a
            # scrollbar and selectable/copyable with the standard terminal
            # gestures (click inside to focus → Ctrl+A → Ctrl+C). Click
            # anywhere in the area auto-selects the whole sequence so
            # single-click → Ctrl+C is enough.
            yield TextArea(
                "", id="parts-seq-view",
                read_only=True, soft_wrap=True, show_line_numbers=False,
            )
            with Horizontal(id="parts-btns"):
                yield Button("Copy Primed",     id="btn-parts-copy-primed")
                yield Button("Copy Cloned",     id="btn-parts-copy-cloned")
                yield Button("Edit",            id="btn-parts-edit")
                yield Button("New Part",        id="btn-new-part",    variant="primary")
                yield Button("Load Part",       id="btn-load-part",   variant="primary")
                yield Button("Save As Feature", id="btn-parts-save-as-feature")
                yield Button("Save to Collection",
                              id="btn-parts-save-to-coll", variant="primary")
                yield Button("Move",            id="btn-parts-move-bin")
                yield Button("Export FASTA",    id="btn-parts-export-fasta")
                yield Button("Delete",          id="btn-parts-delete",
                              variant="error")
                yield Button("Close",           id="btn-parts-close")
        yield Footer()

    def _active_grammar_id(self) -> str:
        """Currently-active grammar id, defaulting to gb_l0 when the
        setting hasn't been written yet. Used by ``_new_part`` to tag
        freshly-saved parts with whichever grammar the New Part modal
        was set to."""
        return _get_setting("active_grammar", "gb_l0")

    # ── Row data ─────────────────────────────────────────────────────────────

    def _all_rows(self) -> list[dict]:
        """User parts from the parts-bin file, filtered to the active
        level tab. Legacy user parts (no ``grammar`` field) default to
        ``gb_l0``; legacy parts without a ``level`` field default to
        L0 (the only level that existed pre-2026-05-10) so they show
        up under the L0 tab without a migration step.

        Level filter (per `_level_matches_tab`):
          * tab L0  → ``_part_level(p) == 0`` (strict)
          * tab TU  → ``_part_level(p) >= 1`` (TUs + MODs + L3 + …)
          * tab MOD → ``_part_level(p) >= 2`` (MODs + L3 + …)

        Higher-level entries appear in lower-level tabs because
        the same plasmid can serve as a source for the next cycle
        regardless of its labelled level — the bench reaction
        only cares that the released overhangs match the
        destination dropout, which the assembly simulator + the
        constructor's compatibility check both verify.
        """
        rows: list[dict] = []
        active = self._active_level
        # Sweep #26 (2026-05-23): readonly iter — the loop body only
        # `.get()`s fields then builds a fresh row dict. Pre-sweep
        # `_load_parts_bin()` deep-cloned every entry per palette
        # repop (every grammar / level tab switch).
        for p in _iter_parts_bin_readonly():
            lvl = _part_level(p)
            if not _level_matches_tab(lvl, active):
                continue
            rows.append({
                "name":     p.get("name", "?"),
                "type":     p.get("type", "?"),
                "position": p.get("position", "?"),
                "oh5":      p.get("oh5", ""),
                "oh3":      p.get("oh3", ""),
                "backbone": p.get("backbone", "pUPD2"),
                "marker":   p.get("marker", "Spectinomycin"),
                "sequence": p.get("sequence", ""),
                "fwd_primer": p.get("fwd_primer", ""),
                "rev_primer": p.get("rev_primer", ""),
                "fwd_tm":   p.get("fwd_tm", 0.0),
                "rev_tm":   p.get("rev_tm", 0.0),
                "user":     True,
                "grammar":  p.get("grammar", "gb_l0"),
                "level":    lvl,
                # Carry the part's stored source features (the lifted
                # operon's genes, in INSERT coords) onto the row so the
                # Save-to-Collection / Copy-Cloned clone paths — which
                # clone straight from `self._rows[idx]`, NOT from disk —
                # carry the genes into the finished plasmid instead of a
                # single fused block. This projection rebuilds a FRESH row
                # dict per part, so a field absent here is silently dropped
                # from every row-driven action (the operon-features-fused
                # bug: `_stamp_insert_feats_on_part` wrote them to disk, but
                # the table row never carried them to `_part_to_cloned_seqrecord`).
                "insert_feats": list(p.get("insert_feats") or []),
                # Carry the FULL run-primer set (flank pair + internal SOE cure
                # primers) so the row-driven Save-to-Collection clone shows
                # every primer, not just the two flanks (same drop-on-projection
                # trap as insert_feats).
                "run_primers": list(p.get("run_primers") or []),
                # Carry gb_text + source-parts on the row so the L1+
                # constructor mode (and future actions like "open in
                # main viewer") can pull them off without re-loading
                # parts_bin.json.
                "gb_text":      p.get("gb_text", ""),
                "source_parts": list(p.get("source_parts") or []),
                "source_role":  p.get("source_role", ""),
            })
        return rows

    def _type_color_map(self) -> dict[str, str]:
        """Return ``{type_name: rich_color}`` merged across every
        grammar's positions. Used by ``_populate`` to colour the Type
        cell for any row regardless of which grammar it belongs to —
        legacy GB types fall through to ``_GB_TYPE_COLORS``."""
        out = dict(_GB_TYPE_COLORS)
        for grammar in _all_grammars().values():
            for pos in grammar.get("positions", []):
                ptype = pos.get("type")
                color = pos.get("color")
                if isinstance(ptype, str) and ptype and isinstance(color, str) and color:
                    out[ptype] = color
        return out

    def on_mount(self) -> None:
        t = self.query_one("#parts-table", DataTable)
        t.add_columns(
            "Name", "Type", "Pos", "5'OH", "3'OH", "Sequence",
            "Feat Lib", "Grammar",
        )
        self._populate()
        if self._auto_trigger_new_part:
            # Drop the flag immediately so a screen-resume can't fire
            # the modal twice. ``call_after_refresh`` waits for the
            # first paint so the user sees the bin briefly before the
            # Domesticator stacks on top — keeps the workflow legible
            # ("you're here now, here's the next step").
            self._auto_trigger_new_part = False
            self.call_after_refresh(lambda: self._new_part(None))

    def on_screen_resume(self) -> None:
        """Re-populate when the screen comes back to focus so agent
        mutations (`delete-part`, classify-and-save flows) are
        reflected. Audit fix 2026-05-14.
        """
        try:
            self._populate()
        except Exception:
            _log.exception("PartsBinModal: resume repopulate failed")

    @on(Tabs.TabActivated, "#parts-level-tabs")
    def _on_level_tab_changed(self, event: Tabs.TabActivated) -> None:
        """Switch the active part-level filter when the user clicks
        a tab. ``_populate`` re-renders the table for the new level."""
        tab_id = event.tab.id or ""
        new_level = (
            0 if tab_id == "tab-parts-l0" else
            1 if tab_id == "tab-parts-tu" else
            2 if tab_id == "tab-parts-mod" else
            self._active_level
        )
        if new_level == self._active_level:
            return
        self._active_level = new_level
        self._populate()

    def _populate(self) -> None:
        t = self.query_one("#parts-table", DataTable)
        t.clear()
        # Drop the multi-select set: row indices captured before
        # repopulate may now point at different parts (a New Part
        # save inserts at index 0). Clearing here keeps the bulk-
        # save action from operating on stale targets.
        #
        # IMPORTANT (sacred invariant #33 — natural-sort row mapping):
        # ``self._rows`` IS the display order — we sort it in-place
        # immediately below, and every cursor / multi-select handler
        # in this modal indexes ``self._rows[idx]`` directly without a
        # row→entry mapping. That works ONLY because (a) display order
        # equals backing-list order (we sort `_rows` itself, not a
        # separate render list) AND (b) `_selected_rows` is cleared
        # on every populate. If you ever add a code path that mutates
        # `self._rows` mid-flight without re-sorting + clearing
        # selection, you MUST introduce a `_row_to_part_idx` mapping
        # alongside (mirroring `FeatureLibraryScreen._row_to_entry_idx`
        # / `PrimerDesignScreen._row_to_primer_idx`) — otherwise
        # cursor-row lookups will resolve to stale entries.
        self._selected_rows.clear()
        self._rows = self._all_rows()
        # Natural sort by name (`pBin2` before `pBin10`) — see
        # `_natural_sort_key`. Parts bin saves preserve insertion
        # order; sort at populate time so a user adding "BsaI_part_2"
        # after "BsaI_part_10" doesn't see the lex-sorted "_2 _10"
        # ordering.
        self._rows.sort(key=lambda r: _natural_sort_key(r.get("name") or ""))
        # Refresh the feature-library index up-front so every row's
        # cell render is an O(1) dict lookup. Without this each row
        # would call `_feature_library_match`, which itself calls
        # `_load_features()` and walks the entire library list — O(N×M)
        # per populate.
        self._refresh_feat_lib_index()
        type_colors = self._type_color_map()
        # Pre-resolve grammar display names so the Grammar column
        # shows human-readable labels instead of raw ids.
        grammars = _all_grammars()
        grammar_label = {
            gid: g.get("name", gid) for gid, g in grammars.items()
        }
        for r in self._rows:
            color = type_colors.get(r["type"], "white")
            seq_preview = r["sequence"][:28] + "…" if len(r["sequence"]) > 28 else r["sequence"]
            if not seq_preview:
                seq_preview = "—"
            gid = r.get("grammar", "gb_l0")
            grammar_cell = Text(
                grammar_label.get(gid, gid),
                style="dim",
            )
            t.add_row(
                Text(r["name"], style=color),
                Text(r["type"], style=f"dim {color}"),
                r["position"],
                Text(r["oh5"], style="bold cyan"),
                Text(r["oh3"], style="bold cyan"),
                Text(seq_preview, style="dim color(252)"),
                self._lib_status_cell(r),
                grammar_cell,
            )
        # Refresh the detail / seq panels to match the current
        # cursor row — or clear them when the table is empty so a
        # bulk-delete that wipes everything doesn't leave the just-
        # deleted part's sequence stuck on screen. RowHighlighted
        # doesn't fire reliably after a clear+rebuild (the cursor
        # may land on the same numeric row, so the event is
        # suppressed), so we drive the render explicitly here.
        if self._rows:
            cursor = t.cursor_row
            if cursor is None or cursor < 0 or cursor >= len(self._rows):
                cursor = 0
            self._render_part_detail(cursor)
        else:
            self._clear_part_detail()

    def _refresh_feat_lib_index(self) -> None:
        """Rebuild the feature-library index iff the global
        ``_state._features_generation`` advanced since the last build. Reused
        across every ``_populate`` so a no-op repaint (e.g., the
        parts table re-rendering for an unrelated reason) doesn't
        re-scan the whole feature library. The first call after mount
        always rebuilds since `_feat_lib_gen_seen` defaults to -1.
        """
        current = _state._features_generation
        if current == self._feat_lib_gen_seen:
            return
        self._feat_lib_index = _build_feature_library_index()
        self._feat_lib_gen_seen = current

    def _lib_status_cell(self, row: dict) -> Text:
        """Render the "Feat Lib" column cell for a parts-bin row.

        - User part with exact match in feature library → green ✓.
        - User part with same (name, type) but a different sequence
          (so a Save would replace) → yellow ✓ as a "stale" marker.
        - Anything else (built-in catalog, unsaved part) → empty.

        Built-in rows have no `sequence`, so they always render empty;
        comparing their type/name to library entries would surface
        false positives if a user happened to give a feature library
        entry the same name as a catalog row.

        Lookup goes through the pre-built `_feat_lib_index` (refreshed
        in `_populate` only when `_state._features_generation` advances), so
        this method is O(1) per row.
        """
        if not row.get("user") or not row.get("sequence"):
            return Text("")
        insdc = _GB_PART_TYPE_TO_INSDC.get(row["type"], "misc_feature")
        match = _classify_feature_library_match(
            self._feat_lib_index,
            row.get("name", ""), insdc, row.get("sequence", ""),
        )
        if match == "exact":
            return Text("✓", style="bold green")
        if match == "name":
            return Text("✓", style="bold yellow")
        return Text("")

    def _render_part_detail(self, idx: int) -> None:
        """Paint the detail panel + sequence TextArea for the row at
        `idx` in `self._rows`. Out-of-range indices clear the panels
        — used by `_populate` after a delete so a now-deleted row's
        data doesn't linger on screen.
        """
        if idx < 0 or not hasattr(self, "_rows") or idx >= len(self._rows):
            self._clear_part_detail()
            return
        r = self._rows[idx]
        color = _GB_TYPE_COLORS.get(r["type"], "white")
        detail = Text()
        detail.append(r["name"], style=f"bold {color}")
        detail.append(f"  [{r['type']}]", style=f"dim {color}")
        detail.append("\n")
        detail.append(f"Position: {r['position']}   ", style="white")
        detail.append("5′ OH: ", style="dim")
        detail.append(r["oh5"], style="bold cyan")
        detail.append("   3′ OH: ", style="dim")
        detail.append(r["oh3"], style="bold cyan")
        detail.append(f"   Backbone: {r['backbone']}   Sel: {r['marker']}", style="dim")
        if r["fwd_primer"]:
            detail.append("\n")
            detail.append("Fwd: ", style="dim green")
            detail.append(r["fwd_primer"], style="green")
            detail.append(f"  Tm {r['fwd_tm']:.1f}°C", style="dim")
        if r["rev_primer"]:
            detail.append("   Rev: ", style="dim red")
            detail.append(r["rev_primer"], style="red")
            detail.append(f"  Tm {r['rev_tm']:.1f}°C", style="dim")
        try:
            self.query_one("#parts-detail", Static).update(detail)
        except NoMatches:
            return

        seq_view = self.query_one("#parts-seq-view", TextArea)
        # On-demand recovery for legacy L1+ entries (saved pre-2026-
        # 05-24) where `sequence` was hardcoded to "" because the
        # bin entry kept `gb_text` as the source of truth. Re-digest
        # via `_assembly_fragment_from_source` so the user sees the
        # released body without having to re-build the assembly.
        # The helper is LRU-cached on `(gb_text_hash, grammar_id,
        # source_level, primary_enzyme, level_up_enzyme)` so the
        # second highlight on the same row is free.
        body_seq = r.get("sequence") or ""
        if (not body_seq
                and r.get("gb_text")
                and int(r.get("level") or 0) >= 1):
            try:
                grammar_id = r.get("grammar") or "gb_l0"
                grammar = (
                    _all_grammars().get(grammar_id)
                    or _BUILTIN_GRAMMARS.get("gb_l0", {})
                )
                # Bin entries record the part's OWN level (e.g.
                # `level=1` for a TU). The digest probe needs the
                # SOURCE level — i.e. the part's level minus 1
                # is the level at which it was assembled, so to
                # release it again we treat the part as a source
                # at `level - 1` and ask for its next-level fragment.
                # In practice `_assembly_fragment_from_source` takes
                # `source_level` = the part's own level when probing
                # a stored plasmid for re-release (same convention
                # `_persist_assembly` uses with `target_level`).
                src_level = int(r.get("level") or 1)
                level_up = _assembly_fragment_from_source(
                    {"gb_text": r["gb_text"],
                     "name": r.get("name") or ""},
                    grammar, source_level=src_level,
                )
                if isinstance(level_up, dict):
                    body_seq = str(level_up.get("sequence") or "")
            except (ValueError, TypeError, KeyError):
                _log.exception(
                    "parts-bin: on-demand body recovery failed for %r",
                    r.get("name"),
                )
        if body_seq:
            header = (
                f"> {r['name']} | {r['type']} | pos {r['position']} | "
                f"{r['oh5']}…{r['oh3']} | {len(body_seq)} bp\n"
            )
            seq_view.text = header + body_seq
        else:
            # Empty-sequence user part (rare — only via a hand-edited
            # parts_bin.json since the built-in catalog rows are gone
            # as of 2026-05-07).
            seq_view.text = "(No sequence attached to this part.)"

    def _clear_part_detail(self) -> None:
        """Wipe the detail panel + sequence view. Called after delete
        when the row the user was viewing no longer exists, so stale
        data from the just-deleted part doesn't linger on screen."""
        try:
            self.query_one("#parts-detail", Static).update("")
        except NoMatches:
            pass
        try:
            self.query_one("#parts-seq-view", TextArea).text = ""
        except NoMatches:
            pass

    @on(DataTable.RowHighlighted, "#parts-table")
    def _row_highlighted(self, event: DataTable.RowHighlighted) -> None:
        # Delegates to the shared painter so `_populate` can re-fire
        # the same render path without synthesising a fake event.
        self._render_part_detail(event.cursor_row)

    # Clicking the sequence area primes it for copy-all: first focus it,
    # then select every character so the user can Ctrl+C immediately.
    @on(TextArea.SelectionChanged, "#parts-seq-view")
    def _seq_selection_changed(self, event) -> None:
        # No-op — Textual wants the handler registered but we drive
        # selection explicitly via _select_sequence below. Kept to suppress
        # "unhandled message" noise on terminals that emit it.
        pass

    def on_click(self, event) -> None:
        """Click in the sequence view → select all (existing
        behaviour). All multi-select logic lives in
        on_mouse_down / on_mouse_move / on_mouse_up because Click
        events aren't reliably delivered through DataTable cells
        in every terminal — see those handlers for the full story."""
        widget = getattr(event, "widget", None)
        try:
            seq_view = self.query_one("#parts-seq-view", TextArea)
        except NoMatches:
            return
        if widget is seq_view or (
            widget is not None and seq_view in widget.ancestors
        ):
            self._select_sequence_in_view(seq_view)

    def _select_sequence_in_view(self, seq_view: TextArea) -> None:
        """Select the entire TextArea content so Ctrl+C in the terminal
        copies everything. TextArea.select_all is the supported API."""
        try:
            seq_view.focus()
            seq_view.select_all()
        except Exception:
            _log.exception("parts-bin: failed to select sequence text")

    # ── Multi-select (drag + modifier+click) ──────────────────────────────

    def _row_under_mouse(self) -> int:
        """Return the row index in `self._rows` directly under the
        mouse pointer, or -1 if the pointer isn't on a data row.

        Reads `DataTable.hover_coordinate` which Textual updates as
        the mouse moves over the table (independent of click state),
        so this works during a drag too. The header row + non-table
        regions return -1 so callers don't have to second-guess the
        coordinate.
        """
        try:
            t = self.query_one("#parts-table", DataTable)
        except NoMatches:
            return -1
        coord = t.hover_coordinate
        if coord is None:
            return -1
        row = getattr(coord, "row", -1)
        rows = getattr(self, "_rows", []) or []
        if 0 <= row < len(rows):
            return row
        return -1

    def on_mouse_down(self, event) -> None:
        """Begin a drag-or-click gesture. Captures the row under the
        pointer, the modifier state, and a SNAPSHOT of `_selected_rows`.

        Gates on the click's screen coordinates falling INSIDE the
        parts table's region. Without this gate, clicking a button
        (Delete, Save to Collection) would trigger my mouse handlers
        because `DataTable.hover_coordinate` is sticky after the
        pointer leaves the table — a button click then looked like a
        bare click on the last-hovered row and ran the clear path
        BEFORE the button's Pressed handler could read
        `_selected_rows`. Region.contains is the only reliable
        widget-vs-elsewhere test; `event.widget` / `.ancestors` are
        unreliable on screen-level handlers.

        The snapshot lets `on_mouse_move` UNION the dragged range
        with the user's prior modifier+click selections instead of
        replacing them. Modifier flag is consumed by `on_mouse_up`
        to decide between toggle (modifier held) and clear (bare
        click).
        """
        if getattr(event, "button", 1) != 1:
            return
        try:
            table = self.query_one("#parts-table", DataTable)
        except NoMatches:
            return
        region = getattr(table, "region", None)
        sx = getattr(event, "screen_x", None)
        sy = getattr(event, "screen_y", None)
        if (region is None or sx is None or sy is None
                or not region.contains(sx, sy)):
            # Click landed outside the parts table — leave drag /
            # selection state alone so the action handler that runs
            # next (e.g. Delete button's Pressed) reads the
            # user's intended `_selected_rows`.
            return
        row = self._row_under_mouse()
        if row < 0:
            # Click landed in the header or a non-row area — reset
            # drag state so a later MouseMove over the table can't
            # mistake us for mid-drag.
            self._drag_active = False
            self._drag_start_row = -1
            return
        self._drag_start_row = row
        self._drag_active = True
        self._drag_changed = False
        self._drag_initial = set(self._selected_rows)
        # Accept any of Ctrl / Shift / Alt because terminals vary
        # in which modifiers they forward on mouse events;
        # gnome-terminal eats Ctrl+click for URL handling, so
        # Shift / Alt are the practical fallbacks.
        self._click_with_modifier = bool(
            getattr(event, "ctrl",  False)
            or getattr(event, "shift", False)
            or getattr(event, "meta",  False)
        )

    def on_mouse_move(self, event) -> None:
        """Extend the drag selection to the row currently under the
        pointer. Only fires while button 1 is held (after MouseDown
        flipped `_drag_active` True). The new selection is the UNION
        of the snapshot taken at drag-start and the contiguous range
        from drag-start to the current row — so a drag adds to the
        existing modifier-toggle picks rather than replacing them.

        Selection rule: any user part is eligible. Pre-2026-05-10
        we also required `sequence` to be non-empty, but TU/MOD
        plasmids legitimately store their bases in `gb_text` rather
        than `sequence`, so the empty-seq filter would have hidden
        them from drag-select once the L1+ tabs landed."""
        if not self._drag_active:
            return
        row = self._row_under_mouse()
        if row < 0 or row == self._drag_start_row:
            return
        start = min(self._drag_start_row, row)
        end   = max(self._drag_start_row, row)
        new_sel: set[int] = set(self._drag_initial)
        rows = getattr(self, "_rows", []) or []
        for r_idx in range(start, end + 1):
            if 0 <= r_idx < len(rows):
                rd = rows[r_idx]
                if rd.get("user"):
                    new_sel.add(r_idx)
        if new_sel != self._selected_rows:
            self._selected_rows = new_sel
            self._drag_changed = True
            self._refresh_multi_select_visuals()

    def on_mouse_up(self, event) -> None:
        """Finalise a click or drag.

        Branches:
          - Drag actually changed selection (`_drag_changed` set by
            on_mouse_move): keep what move produced, do nothing.
          - Modifier held + no drag: toggle the start row in
            `_selected_rows`. Modifier was captured on MouseDown
            (`_click_with_modifier`); we OR with the MouseUp event's
            modifier as belt-and-braces in case the terminal only
            reported it on release.
          - Bare click: clear the multi-select so the click feels
            like "back to single-row mode".
        """
        if not self._drag_active:
            return
        self._drag_active = False
        if self._drag_changed:
            return
        # OR with MouseUp's modifier — some terminals report it on
        # release but not press, others vice-versa; either flag
        # being True triggers the toggle path.
        modifier = self._click_with_modifier or bool(
            getattr(event, "ctrl",  False)
            or getattr(event, "shift", False)
            or getattr(event, "meta",  False)
        )
        if modifier and self._drag_start_row >= 0:
            self._toggle_row_in_selection(self._drag_start_row)
            return
        if self._selected_rows:
            self._clear_multi_select()

    def _toggle_row_in_selection(self, row: int) -> None:
        """Add / remove `row` from `_selected_rows`. Any user part is
        eligible; pre-2026-05-10 we also required `sequence`, but
        TU/MOD plasmids store their bases in `gb_text` instead, so
        the empty-seq filter hid every L1+ row from multi-select."""
        rows = getattr(self, "_rows", []) or []
        if not (0 <= row < len(rows)):
            return
        r = rows[row]
        if not r.get("user"):
            return
        if row in self._selected_rows:
            self._selected_rows.remove(row)
        else:
            self._selected_rows.add(row)
        self._refresh_multi_select_visuals()

    def _clear_multi_select(self) -> None:
        """Drop every selected row + restore the standard button
        layout. Called on bare clicks, after a successful save, and
        when the parts table is repopulated."""
        if not self._selected_rows:
            return
        self._selected_rows.clear()
        self._refresh_multi_select_visuals()

    def _refresh_multi_select_visuals(self) -> None:
        """Sync the table + button row to the current `_selected_rows`.

        Selected rows get a `● ` prefix on the Name cell rendered in
        bold + the row's type colour so the eye finds them immediately.
        While the selection is non-empty every action button except
        "Save to Collection" is disabled, so the only path forward is
        the bulk-save action (or clicking back into the table to
        de-select via another Ctrl+click, or anywhere outside to
        clear).

        Cell updates use `DataTable.update_cell_at` so we touch only
        the Name column instead of repopulating — repopulating would
        reset the cursor + move the user's focus, which feels jarring
        mid-selection.
        """
        try:
            t = self.query_one("#parts-table", DataTable)
        except NoMatches:
            return
        type_colors = self._type_color_map()
        from textual.coordinate import Coordinate
        rows = getattr(self, "_rows", []) or []
        for row_idx, r in enumerate(rows):
            color = type_colors.get(r["type"], "white")
            name  = r.get("name", "?")
            if row_idx in self._selected_rows:
                cell = Text("● " + name, style=f"bold {color}")
            else:
                cell = Text(name, style=color)
            try:
                t.update_cell_at(Coordinate(row_idx, 0), cell)
            except Exception:
                # update_cell_at can raise if the row index is stale
                # (e.g., a populate ran after we captured _rows). Log
                # and continue — the next populate will re-sync.
                _log.exception("parts-bin: row %d cell update failed",
                                row_idx)
        n_sel = len(self._selected_rows)
        for sel in self._OTHER_BTN_IDS:
            try:
                self.query_one(sel, Button).disabled = (n_sel > 0)
            except NoMatches:
                pass
        # Save-to-Collection stays enabled at all times — the handler
        # validates the cursor row + warns if the user picks an
        # unsaveable built-in catalog row. Tying the disabled state
        # to cursor position would require a refresh on every cursor
        # move; the warning toast is a cheaper UX cue.

    # ── Copy helpers ──────────────────────────────────────────────────────

    def _selected_user_row(self) -> dict | None:
        """Return the currently-highlighted row IF it's a user part with a
        sequence, else notify and return None. Built-in catalog rows
        don't carry sequence/primer data, so every Copy action needs the
        same guard."""
        try:
            t = self.query_one("#parts-table", DataTable)
        except NoMatches:
            return None
        idx = t.cursor_row
        if (idx is None or idx < 0
                or not hasattr(self, "_rows") or idx >= len(self._rows)):
            self.app.notify("Select a part first.", severity="warning")
            return None
        r = self._rows[idx]
        if not r.get("sequence"):
            self.app.notify(
                "Built-in catalog parts have no sequence to copy. "
                "Create a new part first.",
                severity="warning",
            )
            return None
        return r

    def _copy_and_notify(self, text: str, label: str, bp_note: str) -> None:
        """Push `text` to the terminal clipboard via OSC 52 and notify the
        user. Falls back to a notification-only path if the terminal
        refused the escape sequence."""
        ok = _copy_to_clipboard_osc52(text)
        if ok:
            self.app.notify(f"Copied {label} to clipboard ({bp_note}).",
                            severity="success",  # type: ignore[arg-type]
                            markup=False)
        else:
            self.app.notify(
                f"Could not access clipboard — select the sequence "
                f"panel and press Ctrl+C instead ({label}, {bp_note}).",
                severity="warning", markup=False,
            )

    @on(Button.Pressed, "#btn-parts-copy-primed")
    def _copy_primed(self, _) -> None:
        """Copy the PCR amplicon the user would actually run with the
        part's stored primers + template sequence.

        Prefers reconstruction from the stored `fwd_primer` / `rev_primer`
        / `sequence` fields via `_amplicon_from_stored_primers` — that
        gives the EXACT amplicon their primers would produce, including
        any silent mutations baked into the primer tails and the correct
        fwd_skip for AATG-CDS parts (where the AATG overhang encodes the
        start codon and the primer binds at codon 2, not the original
        ATG). Pre-fix this used `r.get("primed_seq") or
        _simulate_primed_amplicon(...)`, which produced the canonical
        formula — fine for vanilla parts but 3 bp too long for AATG-CDS
        parts that store the original ATG in `sequence`.

        Falls back to the canonical simulation when primers aren't
        stored or don't bind cleanly to the template (legacy parts
        from before the Domesticator stored primers, manually-entered
        parts where the user blanked the primer fields, etc.). Uses
        the part's stored grammar so a copy of an old MoClo part uses
        BsaI tails even after the user has flipped the active grammar
        to GB; legacy parts (no grammar field) fall back to gb_l0.

        Mirrors the Copy Cloned fix pattern: prefer the most accurate
        stored representation, with a deterministic canonical fallback.
        """
        r = self._selected_user_row()
        if r is None:
            return
        seq = _amplicon_from_stored_primers(
            r.get("fwd_primer", ""), r.get("rev_primer", ""),
            r["sequence"], r.get("oh5", ""), r.get("type", ""),
        )
        if seq is None:
            part_grammar = _all_grammars().get(
                r.get("grammar", "gb_l0"), _BUILTIN_GRAMMARS["gb_l0"],
            )
            seq = _simulate_primed_amplicon(
                r["sequence"], r.get("oh5", ""), r.get("oh3", ""),
                grammar=part_grammar, part_type=r.get("type", ""),
            )
        self._copy_and_notify(seq, "primed amplicon", f"{len(seq)} bp")

    @on(Button.Pressed, "#btn-parts-copy-cloned")
    def _copy_cloned(self, _) -> None:
        """Copy the cloned plasmid sequence — the same sequence that
        lands in the plasmid library when this part is saved.

        Routes through `_part_to_cloned_seqrecord` so the result goes
        through the full tiered cloning model (tier-1 IIS digest into
        the configured entry vector → tier-2 overhang splice → tier-3
        stub-backbone fallback). The old code called
        `_simulate_cloned_plasmid` directly, which always produced the
        420-bp stub form — for any part whose grammar has a real entry
        vector configured (e.g. pUPD2-shaped GB L0 parts) that
        disagreed with the library entry's size by ~1300 bp.
        """
        r = self._selected_user_row()
        if r is None:
            return
        try:
            rec = _part_to_cloned_seqrecord(r)
            if rec is None:                 # never None in practice (it raises
                raise ValueError("no record")   # on no-sequence) — guard for
            seq = str(rec.seq)                   # the type-checker + safety
        except Exception as exc:
            # `_part_to_cloned_seqrecord` raises ValueError for parts
            # with no sequence; BioPython parsing can also fail on a
            # malformed gb_text. Fall back to the stub form so the
            # button stays useful (matches the pre-fix behaviour),
            # but log the cause for post-mortem.
            _log.warning(
                "Copy Cloned: falling back to stub backbone for %r: %s",
                r.get("name"), exc,
            )
            seq = _simulate_cloned_plasmid(
                r.get("sequence", "") or "",
                r.get("oh5", ""), r.get("oh3", ""), r.get("type", ""),
            )
        self._copy_and_notify(
            seq, "cloned plasmid", f"{len(seq)} bp circular",
        )

    @on(Button.Pressed, "#btn-parts-edit")
    def _edit_part(self, _) -> None:
        """Open `PartEditModal` on the cursor row. The modal returns
        ``{"idx": <display row>, "entry": <new dict>}`` on save (or
        ``None`` on cancel / no-op save). We rewrite the matching
        parts-bin entry by ``(name, sequence)`` identity (same match
        as `_delete_selected`) so a `_populate` between push and
        dismiss can't overwrite the wrong row.

        Built-in catalog rows (no sequence) are filtered out by
        `_selected_user_row` — same guard as the Copy buttons.
        """
        original = self._selected_user_row()
        if original is None:
            return
        # `_selected_user_row` already validated the cursor row + that
        # the row carries a sequence; re-read the cursor here purely
        # for the modal's idx payload (purely informational).
        try:
            idx = self.query_one("#parts-table", DataTable).cursor_row
        except NoMatches:
            idx = -1
        idx = idx if isinstance(idx, int) else -1
        # Snapshot the identity at click time so the callback finds
        # the entry even if `_populate` runs in between.
        identity = (original.get("name", ""), original.get("sequence", ""))

        def _on_result(payload):
            if not isinstance(payload, dict):
                # None → cancel or no-op save; nothing to commit.
                return
            new_entry = payload.get("entry")
            if not isinstance(new_entry, dict):
                return
            entries = _load_parts_bin()
            replaced = False
            updated: list[dict] = []
            for e in entries:
                if (not replaced
                        and (e.get("name", ""), e.get("sequence", ""))
                            == identity):
                    updated.append(new_entry)
                    replaced = True
                else:
                    updated.append(e)
            if not replaced:
                # File changed between push + dismiss (concurrent edit,
                # hand-edited parts_bin.json). Refuse to commit rather
                # than silently appending a duplicate — the user can
                # reopen the edit on the now-current row.
                _log.warning(
                    "parts-bin: edit identity %r not found in file; "
                    "refusing to overwrite", identity,
                )
                self.app.notify(
                    "Couldn't save edit: the part was modified or "
                    "removed by another writer. Re-open Edit on the "
                    "refreshed row.",
                    severity="warning", markup=False,
                )
                self._populate()
                return
            try:
                _save_parts_bin(updated)
            except (OSError, RuntimeError) as exc:
                _notify_save_failure(self.app, "Parts bin", exc)
                return
            self._populate()
            self.app.notify(
                f"Updated '{new_entry.get('name', '?')}'",
                severity="success",  # type: ignore[arg-type]
                markup=False,
            )

        self.app.push_screen(
            PartEditModal(idx, original),
            callback=_on_result,
        )

    @on(Button.Pressed, "#btn-new-part")
    def _new_part(self, _) -> None:
        # Opens the domesticator modal. When the Parts Bin was pushed from
        # the Synthesis "Clone Fragment" handoff, a one-shot prefill carries
        # the composed fragment's full sequence + name straight into the
        # Domesticator's direct-input source — so the fragment is
        # domesticated as-is, byte-for-byte, WITHOUT first being saved to
        # the library or applied to the canvas (no premature unprimed save,
        # no clobbering the user's open plasmid). Consumed one-shot here so
        # a later manual "New Part" opens an empty form. Otherwise the
        # current canvas record seeds the "Feature from plasmid" source.
        prefill_seq = self._clone_prefill_seq
        prefill_name = self._clone_prefill_name
        prefill_feats = list(getattr(self, "_clone_prefill_feats", []) or [])
        self._clone_prefill_seq = ""
        self._clone_prefill_name = ""
        self._clone_prefill_feats = []
        if prefill_seq:
            seq = prefill_seq
            # Carry the Synthesis editor's features (the CDS from Optimize, any
            # the user added) so the primed FRAG shows its feature bar — pre-fix
            # this was `[]` and the clone handoff dropped every annotation.
            feats = prefill_feats
            current_name = prefill_name
        else:
            rec = getattr(self.app, "_current_record", None)
            seq = str(rec.seq) if rec else ""
            feats = []
            try:
                pm = self.app.query_one("#plasmid-map", PlasmidMap)
                feats = pm._feats
            except NoMatches:
                pass
            # Clean display name (spaces preserved), NOT the underscored
            # LOCUS `rec.name` — so a fragment cloned out of Synthesis
            # doesn't seed the Domesticator with "BATCH_57_CDS_Demo"
            # (feedback_no_underscores_in_names).
            current_name = (
                self.app._record_display_name(rec)  # type: ignore[attr-defined]
                if rec else ""
            )

        def _on_result(part_dict):
            if part_dict is None:
                return
            # Tag the part with the active grammar so the parts bin
            # filter can route it to the right tab next time. Legacy
            # parts (saved before grammars existed) default to gb_l0
            # in `_all_rows`. Level defaults to 0 (L0 part) since the
            # Domesticator only ever produces single-part L0 entries.
            part_dict.setdefault("grammar", self._active_grammar_id())
            part_dict.setdefault("level", 0)
            # Stamp the source features (CDS etc.) onto the part in INSERT
            # coordinates so the primed fragment shows its feature bar. `feats`
            # is the editor (clone-handoff) or canvas feature list; the helper
            # drops restriction overlays + primer binds and anchors the rest to
            # the part's insert BY SEQUENCE (skip, never mis-place).
            try:
                _stamp_insert_feats_on_part(part_dict, seq, feats)
            except Exception:
                _log.exception("insert feats: stamp failed for %r",
                               part_dict.get("name"))

            # Route through collision resolution so a Domesticator
            # save that lands on an existing part name (re-domesticating
            # the same fragment with tweaked overhangs, or an honest
            # name clash) surfaces the same exact-copy / name-collision
            # prompt the bulk Load path uses. Pre-2026-05-20 fix this
            # appended silently and tripped the (name, sequence) delete
            # bug when the user later removed the original.
            def _content_fn(p: dict) -> str:
                return (
                    f"{(p.get('sequence') or '').upper()}|"
                    f"{(p.get('oh5') or '').upper()}|"
                    f"{(p.get('oh3') or '').upper()}"
                )

            display_name = part_dict.get("name") or "(unnamed)"

            # Dual-save store dialog FIRST (one prompt): cloned-plasmid
            # name + its collection AND the parts bin for the part. The
            # bin choice routes the PART before it's written, so the
            # collision check + save target the chosen bin; the clone is
            # then mirrored to the chosen collection. Cancel = nothing
            # saved (no orphan bin row).
            def _store(res: "dict | None") -> None:
                if not isinstance(res, dict):
                    self.app.notify(
                        "Cloning cancelled — nothing saved.",
                        severity="information",
                    )
                    return
                clone_name = (res.get("name") or "").strip() or display_name
                collection = (res.get("collection") or "").strip()
                chosen_bin = (res.get("bin") or "").strip()
                frag_name = (res.get("frag_name") or "").strip()
                frag_collection = (res.get("frag_collection") or "").strip()
                # Route the PART to the chosen bin (switch active if the
                # user picked a different one — same mirror-swap the bins
                # picker uses, via the shared helper).
                if chosen_bin and chosen_bin != (
                        _get_active_parts_bin_name() or ""):
                    try:
                        _switch_active_parts_bin(chosen_bin)
                    except (OSError, RuntimeError) as exc:
                        _notify_save_failure(self.app, "Parts bin", exc)
                        return
                existing = _load_parts_bin()

                def _on_cancelled() -> None:
                    self.app.notify(
                        f"Save cancelled. '{display_name}' not added to "
                        f"Parts Bin.", severity="warning",
                    )

                def _on_resolved(items_to_save: "list[dict]",
                                 replace_names: "set[str]") -> None:
                    if not items_to_save and not replace_names:
                        self.app.notify(
                            f"Skipped duplicate. '{display_name}' already "
                            f"in the Parts Bin.", severity="warning",
                        )
                        return
                    try:
                        # RMW under `_cache_lock` so a concurrent parts-bin
                        # writer can't read the same pre-state + drop this row.
                        with _cache_lock:
                            entries = _load_parts_bin()
                            if replace_names:
                                entries = [
                                    e for e in entries
                                    if (e.get("name") or "") not in replace_names
                                ]
                            entries = items_to_save + entries
                            _save_parts_bin(entries)
                    except (OSError, RuntimeError) as exc:
                        _notify_save_failure(self.app, "Parts bin", exc)
                        return
                    self._populate()
                    # `items_to_save[0]` carries the (possibly COPY-renamed)
                    # name so the mirrored plasmid matches the bin row.
                    final_part = (items_to_save[0] if items_to_save
                                  else part_dict)
                    final_name = final_part.get("name") or "(unnamed)"
                    self.app.notify(
                        f"Saved '{final_name}' to Parts Bin "
                        f"({len(final_part.get('sequence', ''))} bp).",
                    )
                    # Mirror the cloned plasmid + primed fragment off-thread
                    # under the names + collections picked up-front in the
                    # store dialog (each independent of the parts-bin row).
                    from copy import deepcopy as _deepcopy
                    self._domesticator_library_mirror_worker(
                        _deepcopy(final_part),
                        clone_name=clone_name,
                        target_collection=collection,
                        frag_name=frag_name,
                        frag_collection=frag_collection,
                    )

                _resolve_load_collisions(
                    self.app, "part", [part_dict], existing,
                    name_key="name",
                    content_fn=_content_fn,
                    on_resolved=_on_resolved,
                    on_cancelled=_on_cancelled,
                )

            try:
                _coll_names = [
                    str(c.get("name") or "")
                    for c in _iter_collections_readonly()
                    if isinstance(c, dict) and (c.get("name") or "")
                ]
            except Exception:  # noqa: BLE001
                _coll_names = []
            try:
                _bin_names = [
                    str(b.get("name") or "")
                    for b in _load_parts_bin_collections()
                    if isinstance(b, dict) and (b.get("name") or "")
                ]
            except Exception:  # noqa: BLE001
                _bin_names = []
            # Default the fragment name to the user's "FRAG-" synthesis-
            # order convention (editable / clearable in the dialog). The
            # fragment can land in any collection too — seed the same list
            # as the clone, defaulting to the active collection.
            self.app.push_screen(
                AmpliconSaveModal(
                    default_name=display_name,
                    collections=_coll_names,
                    active_collection=_get_active_collection_name(),
                    title="Store cloned part + fragment",
                    name_label="Cloned plasmid name",
                    parts_bins=_bin_names,
                    active_bin=_get_active_parts_bin_name(),
                    fragment_default_name=f"FRAG-{display_name}",
                    fragment_collections=_coll_names,
                    fragment_active_collection=_get_active_collection_name(),
                    fragment_label="Fragment name (for synthesis orders)",
                ),
                callback=_store,
            )

        # The one-shot Clone-Fragment prefill was consumed at the top of
        # this method, so `seq` / `current_name` already reflect it when
        # present. Hand the verbatim sequence to the Domesticator's
        # direct-input source (its default), pre-filling the part name.
        self.app.push_screen(
            DomesticatorModal(
                seq, feats, current_plasmid_name=current_name,
                prefill_direct_seq=prefill_seq,
                prefill_name=prefill_name,
            ),
            callback=_on_result,
        )

    @work(thread=True, exclusive=True, group="dom_library_mirror")
    def _domesticator_library_mirror_worker(
        self, part_dict: dict, *,
        clone_name: "str | None" = None,
        target_collection: "str | None" = None,
        frag_name: "str | None" = None,
        frag_collection: "str | None" = None,
    ) -> None:
        """Off-thread Domesticator → cloned-plasmid + primed-fragment save.

        ``clone_name`` / ``target_collection`` (dual-save) name the clone
        + pick its destination collection independently of the parts-bin
        row; both default to the part name / active collection so an
        un-prompted call matches the prior behaviour.

        ``frag_name`` / ``frag_collection`` (2026-06-02) ALSO save the
        LINEAR primed fragment — the orderable amplicon (insert + the
        primers' enzyme-site/overhang 5' tails) with both domestication
        primers attached — under its OWN name + collection, named
        independently of the clone (the user's "FRAG-…" synthesis-order
        convention). Gated on ``frag_name`` so an un-prompted call saves
        the clone only, exactly as before.

        Mirrors the L0 part as a full part-in-entry-vector plasmid
        in the library. Runs after the parts-bin save (which is sync
        on the UI thread); failure here logs + notifies but does NOT
        roll back the bin row. Exclusive ``dom_library_mirror`` group
        coalesces back-to-back Domesticator saves so two clicks in
        rapid succession don't race the same library write.

        Structured events: `domesticator.library_mirror.ok` on
        success, `domesticator.library_mirror.failed` on either
        clone or save failure (with `stage` field for routing).
        """
        display_name = part_dict.get("name") or "(unnamed)"
        try:
            lib_rec = _part_to_cloned_seqrecord(part_dict)
        except Exception as exc:
            _log.exception(
                "Domesticator: library-mirror clone failed for %r",
                display_name,
            )
            _log_event(
                "domesticator.library_mirror.failed",
                name=display_name, stage="clone",
                error=str(exc)[:120],
            )
            self.app.call_from_thread(
                self.app.notify,
                f"Library mirror skipped: clone failed ({exc}).",
                severity="warning",
            )
            return
        # Dual-save routing (2026-06-02): the cloned plasmid is named +
        # placed independently of the parts-bin row. ``target_collection``
        # defaults to the active collection — exactly where the prior
        # `_save_library` mirror landed it — so an un-prompted call stays
        # behaviour-compatible; a user-chosen collection routes there
        # instead. Goes through the SAME `_commit_library_entry_to_collection`
        # helper every assembly save uses (`_cache_lock` + atomic .bak +
        # id/name collision-rename + active-library re-mirror), so the
        # Domesticator no longer hand-rolls its own library write.
        if lib_rec is None:             # never None in practice (the clone
            self.app.call_from_thread(  # raises, caught above) — guard the
                self.app.notify,        # type-checker + skip a degenerate save
                "Library mirror skipped: clone produced no record.",
                severity="warning")
            return
        clone_disp = (clone_name or "").strip() or display_name
        target = ((target_collection or "").strip()
                  or _get_active_collection_name() or "Default")
        base_id = (re.sub(r"[^A-Za-z0-9_]+", "_",
                          (lib_rec.id or clone_disp)) or "part")
        lib_entry = {
            "id":      base_id,
            "name":    clone_disp,
            "size":    _seq_len(lib_rec),
            "n_feats": len(lib_rec.features or []),
            "source":  "domesticator:l0",
            "added":   _date.today().isoformat(),
            "gb_text": _record_to_gb_text(lib_rec),
        }
        # Construction-history auto-record (INV-93 parity with the
        # Constructor / Traditional panes). A Domesticator clone is a
        # single-part L0 assembly — the part's amplicon ligated into its
        # entry vector — but pre-fix it carried NO history_xml, so the
        # save chokepoint stamped the bare `createDocument` origin stub
        # ("domesticator:l0" matched no rich builder) and a
        # synthesis→parts→clone plasmid showed an empty lineage. Build
        # the insert + entry-vector tree here so its History reads like a
        # Constructor build. L0 only (the Domesticator's product); an L1+
        # part short-circuits in _part_to_cloned_seqrecord and keeps its
        # own gb_text lineage. Best-effort — never blocks the save.
        try:
            if _part_level(part_dict) < 1:
                _grammar_id = part_dict.get("grammar") or "gb_l0"
                _grammar = (_all_grammars().get(_grammar_id)
                            or _BUILTIN_GRAMMARS.get("gb_l0") or {})
                _entry_vec = _get_entry_vector(_grammar_id)
                if isinstance(_entry_vec, dict) and _entry_vec.get("gb_text"):
                    _hist = _build_history_for_l0_clone(
                        name=clone_disp, seq_len=_seq_len(lib_rec),
                        grammar_id=_grammar_id, grammar=_grammar,
                        entry_vector=_entry_vec, part=part_dict,
                    )
                    if _hist:
                        lib_entry["history_xml"] = _hist
        except Exception:
            _log.debug(
                "domesticator: clone history build failed for %r",
                clone_disp, exc_info=True,
            )
        # Defensive (2026-06-09): the cloned plasmid is only a REAL
        # part-in-vector when a valid entry vector (≥2 of the grammar's
        # enzyme sites) is bound — otherwise `_part_to_cloned_seqrecord`
        # falls back to the pUPD2 stub. The Clone-Fragment chooser guards
        # this up front, but the grammar can still be switched inside the
        # Domesticator to one with no bound vector. Tell the user when
        # that happened instead of silently filing a placeholder.
        try:
            _gid = part_dict.get("grammar") or "gb_l0"
            _g = (_all_grammars().get(_gid)
                  or _BUILTIN_GRAMMARS.get("gb_l0") or {})
            if (_part_level(part_dict) < 1
                    and not _entry_vector_is_valid_acceptor(
                        _get_entry_vector(_gid), _g)):
                self.app.call_from_thread(
                    self.app.notify,
                    f"'{clone_disp}' was saved with a PLACEHOLDER backbone — "
                    f"no valid entry vector is bound for "
                    f"{_g.get('name', _gid)}. Bind an acceptor "
                    f"(Settings ▸ Entry Vectors) and re-clone for the real "
                    f"plasmid.",
                    severity="warning",
                )
        except Exception:
            _log.debug("clone stub-check failed", exc_info=True)
        try:
            final_name = _commit_library_entry_to_collection(lib_entry, target)
        except (OSError, RuntimeError) as exc:
            _log.exception(
                "Domesticator: cloned-plasmid save failed for %r", clone_disp,
            )
            _log_event(
                "domesticator.library_mirror.failed",
                name=clone_disp, stage="save", error=str(exc)[:120],
            )
            self.app.call_from_thread(
                self.app.notify,
                f"Cloned-plasmid save failed for '{clone_disp}' "
                f"({exc}). Parts bin row is intact.",
                severity="error",
            )
            return
        _log_event(
            "domesticator.library_mirror.ok",
            name=final_name, collection=target,
            bp=lib_entry["size"], n_feats=lib_entry["n_feats"],
        )
        # Primed-fragment dual-save (2026-06-02): in addition to the
        # circular clone, save the LINEAR primed fragment — the amplicon
        # the designed domestication primers produce (insert + each
        # primer's 5' enzyme-site/overhang tail), with both primers
        # attached — under its OWN name + collection. This is the
        # orderable synthesis fragment the user names independently
        # (e.g. "FRAG-…"). Fully independent of the clone that just
        # saved: its own try/except so a fragment failure never disturbs
        # the clone or the parts-bin row. Gated on frag_name + L0 (the
        # Domesticator's product) so an un-prompted call is unchanged.
        frag_disp = (frag_name or "").strip()
        if frag_disp and _part_level(part_dict) < 1:
            try:
                frag_rec = _part_to_primed_fragment_seqrecord(
                    part_dict, name=frag_disp,
                )
                frag_target = ((frag_collection or "").strip()
                               or target or "Default")
                frag_id = (re.sub(r"[^A-Za-z0-9_]+", "_",
                                  (frag_rec.id or frag_disp)).strip("_")
                           or "fragment")
                frag_entry = {
                    "id":      frag_id,
                    "name":    frag_disp,
                    "size":    _seq_len(frag_rec),
                    "n_feats": len(frag_rec.features or []),
                    "kind":    "fragment",          # linear synthesis order
                    "source":  "domesticator:fragment",
                    "added":   _date.today().isoformat(),
                    "gb_text": _record_to_gb_text(frag_rec),
                }
                # The fragment IS a PCR amplicon — give it amplicon
                # construction history (primers as <Oligo> children +
                # amplified region) so its History matches a de-novo
                # amplicon's, INV-93-style. Best-effort.
                try:
                    _f_oligo, _r_oligo = _part_primer_labels(part_dict)
                    _fh = _build_amplicon_history_xml(
                        name=frag_disp, seq_len=frag_entry["size"],
                        fwd_seq=str(part_dict.get("fwd_primer") or ""),
                        rev_seq=str(part_dict.get("rev_primer") or ""),
                        start_1based=1, end_1based=frag_entry["size"],
                        fwd_name=_f_oligo,
                        rev_name=_r_oligo,
                    )
                    if _fh:
                        frag_entry["history_xml"] = _fh
                except Exception:
                    _log.debug("fragment history build failed for %r",
                               frag_disp, exc_info=True)
                frag_final = _commit_library_entry_to_collection(
                    frag_entry, frag_target,
                )
                _log_event(
                    "domesticator.fragment_mirror.ok",
                    name=frag_final, collection=frag_target,
                    bp=frag_entry["size"], n_feats=frag_entry["n_feats"],
                )
            except Exception as exc:
                _log.exception(
                    "Domesticator: primed-fragment save failed for %r",
                    frag_name,
                )
                _log_event(
                    "domesticator.fragment_mirror.failed",
                    name=str(frag_name), error=str(exc)[:120],
                )
                self.app.call_from_thread(
                    self.app.notify,
                    f"Fragment save failed ({exc}). The clone + parts-bin "
                    f"row are intact.",
                    severity="warning",
                )
        # Best-effort reveal — resolves when the clone landed in the
        # active collection (mirrored to the library file); a clone routed
        # to a non-active collection just isn't in the current view yet.
        def _on_mirror_done() -> None:
            try:
                lib = self.app.query_one("#library", LibraryPanel)
                lib.reveal_entry_id(base_id)
            except (NoMatches, AttributeError):
                pass
            self.app.notify(
                f"Cloned plasmid '{final_name}' → collection '{target}' "
                f"({lib_entry['size']:,} bp, {lib_entry['n_feats']} features).",
            )
        self.app.call_from_thread(_on_mirror_done)

    @on(Button.Pressed, "#btn-load-part")
    def _load_part(self, _) -> None:
        """Open the source picker; on dismiss with a list of SeqRecords,
        classify each against every cloning grammar via Type IIS digest
        and save the matched insert(s) as Parts Bin rows tagged with
        the detected grammar / position / marker.

        Pre-2026-05-13 this took a single SeqRecord; the picker now
        supports multi-select (space / click toggles each row) and
        dismisses with a list, so a user importing a stack of MoClo
        plasmids no longer has to re-open the picker N times.

        Pre-flight (empty seq, circular topology) ran per-record inside
        the picker so anything reaching here is already classifier-
        ready. The digest + serialise + save runs in a ``@work``
        thread so a batch of 20 plasmids × N grammars doesn't freeze
        the modal.
        """
        def _on_picked(records) -> None:
            if not records:
                return
            # Defensive: PartsBin may have unmounted between the
            # picker's dismiss and this callback firing (rare, but
            # possible if app.exit() interleaves). Bail without
            # spawning a worker against a dead screen.
            if not self.is_mounted:
                return
            payloads: "list[tuple[str, list, str, str]]" = []
            for record in records:
                seq_len = len(getattr(record, "seq", "") or "")
                if seq_len == 0:
                    continue
                circular = (
                    (record.annotations or {}).get("topology", "").lower()
                    == "circular"
                )
                if not circular:
                    continue
                seq = str(record.seq).upper()
                # Prefer the library entry's display name (stashed by
                # `LoadPartSourceModal._resolve_match_to_record`) so
                # parts-bin entries carry "DEMO 32 + Test" instead of
                # the sanitised LOCUS form. Falls back to record.name
                # for Open-file… records where no library entry name
                # exists.
                plasmid_name = (
                    getattr(record, "_tui_display_name", None)
                    or getattr(record, "name", "")
                    or getattr(record, "id", "")
                    or "imported"
                )
                gb_text = getattr(record, "_tui_gb_text", None)
                if not gb_text:
                    try:
                        gb_text = _record_to_gb_text(record)
                    except Exception:
                        _log.exception(
                            "Load Part: GenBank serialise failed",
                        )
                        gb_text = ""
                payloads.append((seq, [], plasmid_name, gb_text))
            if not payloads:
                self.app.notify(
                    "No classifiable records in the batch.",
                    severity="warning",
                )
                return
            # Single-item batch goes through the legacy single worker
            # (preserves the existing notify copy + active-grammar
            # auto-flip behaviour). Multi-item batches use the bulk
            # worker so we save once at the end instead of N times.
            if len(payloads) == 1:
                seq, feats, plasmid_name, gb_text = payloads[0]
                self._load_part_worker(seq, feats, plasmid_name, gb_text)
            else:
                self._load_parts_bulk_worker(payloads)

        self.app.push_screen(LoadPartSourceModal(), callback=_on_picked)

    @work(thread=True, exclusive=True, group="parts_bin_load")
    def _load_parts_bulk_worker(
        self,
        payloads: "list[tuple[str, list, str, str]]",
    ) -> None:
        """Worker body for the multi-select Load path. Classifies each
        plasmid against every grammar, accumulates the matched inserts,
        and writes them to the active parts bin in ONE save call at
        the end (avoids N round-trips through `_save_parts_bin` for a
        20-item batch).

        Per-record failures are logged + tallied; the batch always
        continues so a single unclassifiable plasmid doesn't drop
        siblings. Summary toast fires from the UI thread on completion.
        """
        new_parts: list[dict] = []
        unclassified: list[str] = []
        failed:       list[str] = []
        last_grammar = ""
        for seq, feats, plasmid_name, gb_text in payloads:
            try:
                match = _classify_part_from_plasmid(
                    seq, circular=True, features=feats,
                )
            except Exception as exc:
                _log.exception(
                    "Load Parts (bulk): classify failed for %r",
                    plasmid_name,
                )
                failed.append(f"{plasmid_name}: classify error ({exc})")
                continue
            if match is None:
                unclassified.append(plasmid_name)
                continue
            insert = match["insert"]
            position = match["position"]
            grammar_id = match["grammar_id"]
            last_grammar = grammar_id
            marker = _detect_selection_marker(gb_text) or "—"
            backbone_label = plasmid_name
            insert_seq = (insert.get("top_seq") or "").upper()
            oh5 = str(
                (insert.get("left")  or {}).get("overhang_seq", ""),
            ).upper()
            oh3 = str(
                (insert.get("right") or {}).get("overhang_seq", ""),
            ).upper()
            if oh5 and insert_seq.startswith(oh5):
                insert_seq = insert_seq[len(oh5):]
            level_int = int(match.get("level", 0) or 0)
            part_entry = {
                "name":       plasmid_name,
                "type":       position.get("type") or "?",
                "position":   position.get("name") or "?",
                "oh5":        oh5,
                "oh3":        oh3,
                "backbone":   backbone_label,
                "marker":     marker,
                "sequence":   insert_seq,
                "fwd_primer": "",
                "rev_primer": "",
                "fwd_tm":     0.0,
                "rev_tm":     0.0,
                "grammar":    grammar_id,
                "level":      level_int,
            }
            # L1+ parts need gb_text for `_assembly_fragment_from_source`
            # to re-digest them in the Constructor's next cycle (TU →
            # MOD, MOD → next-MOD). See the single-pick worker's
            # equivalent guard for the rationale.
            if level_int >= 1 and gb_text:
                part_entry["gb_text"] = gb_text
            new_parts.append(part_entry)
        # Resolution + save runs on the UI thread because the collision
        # modals push screens (only safe from the UI thread). The
        # finalizer also handles unclassified / failed tallies so the
        # user always sees a single coherent summary toast.
        self.app.call_from_thread(
            self._finalize_parts_load,
            new_parts, unclassified, failed, last_grammar,
            "Load Parts (batch)",
        )

    def _finalize_parts_load(
        self,
        new_parts: "list[dict]",
        unclassified: "list[str]",
        failed: "list[str]",
        last_grammar: str,
        title: str,
        extra_info: str = "",
    ) -> None:
        """UI-thread continuation for the Load Parts workers.

        Resolves any (name, sequence + overhangs) collisions against the
        existing parts bin via ``_resolve_load_collisions``. The user
        sees an ``ExactCopyConfirmModal`` if any new parts duplicate
        existing entries exactly, then a ``NameCollisionModal`` if any
        new parts share a name with existing entries but the body
        differs. After the user resolves both prompts (or cancels), the
        final list is written via ``_save_parts_bin``; a single
        summary toast surfaces the counts (loaded / overwritten /
        skipped / unclassified / failed).

        Regression guard for 2026-05-20 — pre-fix the load path saved
        verbatim, so a repeated import double-added parts silently and
        a later delete-one nuked both copies via the (name, sequence)
        set-based filter in ``_delete_selected``.
        """
        n_unc  = len(unclassified)
        n_fail = len(failed)
        if not new_parts:
            self._emit_parts_load_summary(
                0, n_unc, n_fail, 0, 0, title,
                unclassified, failed,
            )
            return

        existing = _load_parts_bin()

        def _content_fn(p: dict) -> str:
            # Identity: sequence body + both overhangs. Two parts with
            # the same name but different overhangs (e.g. a B3a vs B3b
            # variant) classify as "name collision (different content)"
            # rather than "exact copy", so the user gets the overwrite /
            # keep-original / cancel prompt instead of the silent
            # COPY-rename. Upper-cased so case quirks in legacy data
            # don't surface false collisions.
            return (
                f"{(p.get('sequence') or '').upper()}|"
                f"{(p.get('oh5') or '').upper()}|"
                f"{(p.get('oh3') or '').upper()}"
            )

        def _on_cancelled() -> None:
            self.app.notify(
                f"{title}: load cancelled. Existing parts unchanged.",
                severity="warning",
            )
            _log_event(
                "parts_bin.load.cancelled",
                title=title, n_new=len(new_parts),
            )

        def _on_resolved(items_to_save: "list[dict]",
                         replace_names: "set[str]") -> None:
            n_skipped = len(new_parts) - len(items_to_save)
            if not items_to_save and not replace_names:
                self._emit_parts_load_summary(
                    0, n_unc, n_fail, 0, n_skipped, title,
                    unclassified, failed,
                )
                return
            n_overwritten = 0
            try:
                # RMW under `_cache_lock` so a concurrent parts-bin writer
                # (agent create/delete-part, constructor save) can't read
                # the same pre-state and drop these rows.
                with _cache_lock:
                    entries = _load_parts_bin()
                    if replace_names:
                        before = len(entries)
                        entries = [
                            e for e in entries
                            if (e.get("name") or "") not in replace_names
                        ]
                        n_overwritten = before - len(entries)
                    # Insert newest-first at the top so the user sees them
                    # at the head of the table after the modal refreshes.
                    entries = items_to_save + entries
                    _save_parts_bin(entries)
            except (OSError, RuntimeError) as exc:
                _log.exception("Load Parts: parts bin save failed")
                _notify_save_failure(self.app, "Parts bin", exc)
                return
            if last_grammar:
                try:
                    _set_setting("active_grammar", last_grammar)
                except OSError:
                    _log.debug(
                        "Load Parts: active_grammar persist failed",
                    )
            if self.is_mounted:
                try:
                    self._populate()
                except Exception:
                    _log.debug("Load Parts: repopulate failed")
            n_added = len(items_to_save) - n_overwritten
            _log_event(
                "parts_bin.load.ok",
                title=title, n_added=n_added,
                n_overwritten=n_overwritten, n_skipped=n_skipped,
                n_unclassified=n_unc, n_failed=n_fail,
            )
            self._emit_parts_load_summary(
                n_added, n_unc, n_fail, n_overwritten, n_skipped,
                title, unclassified, failed, extra_info,
            )

        _resolve_load_collisions(
            self.app, "part", new_parts, existing,
            name_key="name",
            content_fn=_content_fn,
            on_resolved=_on_resolved,
            on_cancelled=_on_cancelled,
        )

    def _emit_parts_load_summary(
        self,
        n_added: int,
        n_unc: int,
        n_fail: int,
        n_overwritten: int,
        n_skipped: int,
        title: str,
        unclassified: "list[str]",
        failed: "list[str]",
        extra_info: str = "",
    ) -> None:
        """Compose + fire the single post-load summary toast and log
        per-record fallout from unclassified / failed payloads. Always
        called once per load via ``_finalize_parts_load`` so the user
        sees one coherent message regardless of which collision path
        the modals routed through.
        """
        sev = (
            "information"
            if (n_added or n_overwritten) and not (n_unc or n_fail)
            else "warning" if (n_added or n_overwritten or n_skipped)
            else "error" if n_fail
            else "warning"
        )
        bits: list[str] = []
        if n_added:
            bits.append(
                f"Loaded {n_added} part{'s' if n_added != 1 else ''}"
            )
        if n_overwritten:
            bits.append(
                f"overwrote {n_overwritten} existing"
            )
        if n_skipped:
            bits.append(
                f"skipped {n_skipped} duplicate"
                f"{'s' if n_skipped != 1 else ''}"
            )
        if not bits:
            bits.append("No parts added")
        msg = ". ".join(bits) + "."
        if n_unc:
            msg += (
                f" {n_unc} couldn't classify "
                f"(overhangs didn't match a grammar position)."
            )
        if n_fail:
            msg += f" {n_fail} failed (see log)."
        if extra_info and (n_added or n_overwritten):
            # Append the single-load classifier detail (grammar, level,
            # marker, entry-vector match) only when something actually
            # landed. Suppressing on skip / cancel keeps the toast
            # honest — no stale "Loaded as X" copy when nothing did.
            msg += " " + extra_info
        self.app.notify(msg, title=title, severity=sev, timeout=8)
        for name in unclassified:
            _log.info("Load Parts: unclassified plasmid %r", name)
        for entry in failed:
            _log.warning("Load Parts: %s", entry)

    @work(thread=True, exclusive=True, group="parts_bin_load")
    def _load_part_worker(self, seq: str, feats: list,
                          plasmid_name: str, gb_text: str) -> None:
        """Worker body for `_load_part`. Classifies the plasmid against
        every grammar (the slow step — N digests in series), saves to
        the parts bin, and bounces back to the UI thread for the

        Shares the `parts_bin_load` group with `_load_parts_bulk_worker`
        so a click+bulk-click race coalesces into the latest dispatch;
        without `exclusive=True` both workers could race the same
        `_save_parts_bin` write and leave the in-memory cache
        reflecting the loser's snapshot (audit fix 2026-05-14).
        repopulate + notify."""
        try:
            match = _classify_part_from_plasmid(
                seq, circular=True, features=feats,
            )
        except Exception:
            _log.exception("Load Part: classify failed")
            self.app.call_from_thread(
                self.app.notify,
                "Load Part: digest failed (see log for details).",
                severity="error",
            )
            return
        if match is None:
            self.app.call_from_thread(
                self.app.notify,
                "Couldn't classify this plasmid against any grammar. "
                "Either the Type IIS sites don't release a recognised "
                "fragment, or the overhangs don't match a known position. "
                "Use New Part to set type / position manually.",
                severity="warning",
            )
            return
        insert = match["insert"]
        position = match["position"]
        grammar_id = match["grammar_id"]
        marker = _detect_selection_marker(gb_text) or "—"
        backbone_label = plasmid_name
        insert_seq = (insert.get("top_seq") or "").upper()
        oh5 = str((insert.get("left")  or {}).get("overhang_seq", "")).upper()
        oh3 = str((insert.get("right") or {}).get("overhang_seq", "")).upper()
        # Strip the leading 5' overhang off the insert top-strand so
        # the saved ``sequence`` matches the convention used by every
        # other Parts Bin save path (the New Part / Domesticator flow
        # stores the designed insert WITHOUT the 4-nt overhangs —
        # those live in ``oh5`` / ``oh3``).
        #
        # For 5' overhang Type IIS enzymes (BsaI / Esp3I / BsmBI / BpiI
        # — all the cloning grammars currently care about) the LEFT
        # overhang sits inside ``top_seq`` (first 4 bases) but the
        # RIGHT overhang lives in the OTHER fragment (between this
        # cut's top position and its bottom position, both past
        # top_seq's end). Stripping ``oh3`` from the right via
        # ``endswith`` would incorrectly trim 4 legitimate bases off a
        # part whose insert happens to end in the same 4-mer as the
        # downstream overhang — so we don't try.
        if oh5 and insert_seq.startswith(oh5):
            insert_seq = insert_seq[len(oh5):]
        # `level` comes from the classifier — a TU plasmid (BsaI-flanked
        # body with TU boundary overhangs) lands at level=1, a MOD at
        # level=2, and an L0 part (with either primary or secondary
        # release enzyme) at level=0. Pre-2026-05-10 this was hardcoded
        # 0, which mis-tabbed every TU/MOD plasmid into the L0 tab.
        level_int = int(match.get("level", 0) or 0)
        part = {
            "name":       plasmid_name,
            "type":       position.get("type") or "?",
            "position":   position.get("name") or "?",
            "oh5":        oh5,
            "oh3":        oh3,
            "backbone":   backbone_label,
            "marker":     marker,
            "sequence":   insert_seq,
            "fwd_primer": "",
            "rev_primer": "",
            "fwd_tm":     0.0,
            "rev_tm":     0.0,
            "grammar":    grammar_id,
            "level":      level_int,
        }
        # L1+ parts need the full plasmid `gb_text` so
        # `_assembly_fragment_from_source` can digest with the level-up
        # enzyme when chaining TUs into a MOD (or further). Pre-2026-
        # 05-13 the Load Part flow only stashed `sequence` (the
        # released body) — which is enough for L0 chaining but the
        # Constructor's L1→L2 path needs to re-digest the full assembled
        # plasmid. Constructor's own save path already carried gb_text;
        # this matches the contract so TUs loaded via the picker are
        # also assembly-ready. (Bug surfaced by DEMO-25-in-Omega1
        # rejections, 2026-05-13.)
        if level_int >= 1 and gb_text:
            part["gb_text"] = gb_text
        # Compose the classifier detail string the single-load toast
        # used to carry verbatim. `_finalize_parts_load` appends it
        # only when the save actually lands (so a user-cancelled or
        # skipped-duplicate run doesn't show a misleading "Loaded as
        # X" trailer).
        ev = match.get("entry_vector") or {}
        ev_msg = ""
        if ev.get("matches"):
            role = ev.get("role") or ""
            role_str = f" / {role}" if role else ""
            ev_msg = f" Vector: {ev.get('name', '?')}{role_str}."
        level_label = _part_level_label(int(match.get("level", 0) or 0))
        extra_info = (
            f"'{plasmid_name}' classified as {match['grammar_name']} → "
            f"{position.get('name')} ({position.get('type')}). "
            f"Level: {level_label}. Marker: {marker}.{ev_msg}"
        )
        # Route through `_finalize_parts_load` so exact-copy and name-
        # collision prompts fire for single loads the same way they do
        # for bulk. The single-load contract used to save unconditionally;
        # post-2026-05-20 fix it now prompts the user when an existing
        # part matches by name (regression guard in test_parts_bin_dedupe).
        self.app.call_from_thread(
            self._finalize_parts_load,
            [part], [], [], grammar_id,
            "Load Part", extra_info,
        )

    @on(Button.Pressed, "#btn-parts-export-fasta")
    def _export_fasta(self, _) -> None:
        """Export the highlighted row's sequence as single-record FASTA.

        Built-in catalog parts have no sequence attached, so we bail
        with a friendly notify rather than pushing an empty modal."""
        try:
            t = self.query_one("#parts-table", DataTable)
        except NoMatches:
            return
        idx = t.cursor_row
        if (idx is None or idx < 0
                or not hasattr(self, "_rows") or idx >= len(self._rows)):
            self.app.notify("Select a part first.", severity="warning")
            return
        r = self._rows[idx]
        seq = r.get("sequence", "") or ""
        if not seq:
            self.app.notify(
                "Built-in catalog parts have no sequence to export. "
                "Create a new part first.",
                severity="warning",
            )
            return
        name = r.get("name", "part")
        safe = re.sub(r"[^A-Za-z0-9._-]", "_", name) or "part"
        default_path = str(Path.home() / f"{safe}.fa")

        def _on_done(summary):
            if not summary:
                return
            self.app.notify(
                f"Exported '{summary['name']}' to {summary['path']} "
                f"({summary['bp']} bp).",
            )

        self.app.push_screen(
            FastaExportModal(
                name=name,
                sequence=seq,
                default_path=default_path,
                subtitle=f"[{name}]  [{r.get('type', '?')}]  {len(seq)} bp",
            ),
            callback=_on_done,
        )

    @on(Button.Pressed, "#btn-parts-save-as-feature")
    def _save_as_feature(self, _) -> None:
        """Register the highlighted user part as a feature-library entry.

        Built-in catalog rows have no sequence — they're descriptive
        position/overhang bookkeeping with no insert — so they're
        rejected. For real user parts, build a prefill dict mapping
        the GB part shape onto INSDC feature vocabulary
        (`_GB_PART_TYPE_TO_INSDC`) and open `AddFeatureModal` so the
        user can adjust the name / qualifiers before committing.
        Saving routes through ``app._persist_feature_entry`` (the same
        helper Alt+Shift+C capture uses) so the latest write wins on
        (name, feature_type) collisions.

        Before opening the modal, ``_feature_library_match`` is
        consulted: if the (name, INSDC type) pair is already in the
        library the user gets a yellow warning notify so a silent
        replace doesn't surprise them. The modal opens in either case
        — the user retains the option to cancel.

        Insert-at-cursor is disabled here even when a record is open —
        the parts bin is a different mental model (registering the
        part's *idea* into the library), and inserting from a modal
        layered on top of another modal would leave the parts bin
        stranded over the freshly-edited record.
        """
        r = self._selected_user_row()
        if r is None:
            return

        ftype = _GB_PART_TYPE_TO_INSDC.get(r["type"], "misc_feature")
        sequence = r.get("sequence", "")
        oh5, oh3 = r.get("oh5", ""), r.get("oh3", "")
        pos = r.get("position", "")
        backbone = r.get("backbone", "")
        bits: list[str] = ["Golden Braid L0 part"]
        if pos:
            bits.append(f"Position {pos}")
        if oh5 or oh3:
            bits.append(f"5' OH {oh5} / 3' OH {oh3}")
        if backbone:
            bits.append(f"backbone {backbone}")
        # CDS-NS / C-tag both collapse to plain "CDS" in INSDC. The
        # NS / C-tag distinction is meaningful (NS = no stop codon,
        # C-tag = C-terminal fusion fragment), so preserve it in the
        # description rather than losing it on the round-trip.
        if r["type"] in {"CDS-NS", "C-tag"}:
            bits.append(f"GB type: {r['type']}")
        description = "; ".join(bits)

        # Warn before opening so the user can spot a collision they
        # didn't intend. `_feature_library_match` distinguishes exact
        # (no-op save) from name-only (Save will replace the stored
        # sequence) — the wording differs because the consequences do.
        name = r.get("name", "")
        match = _feature_library_match(name, ftype, sequence)
        if match == "exact":
            self.app.notify(
                f"'{name}' is already in the feature library "
                f"(exact match). Saving again is a no-op.",
                severity="warning",
            )
        elif match == "name":
            self.app.notify(
                f"A feature named '{name}' (type {ftype}) is already "
                f"in the feature library with a different sequence. "
                f"Saving will replace it.",
                severity="warning",
            )

        prefill = {
            "name":         name,
            "feature_type": ftype,
            "sequence":     sequence,
            "strand":       1,
            "color":        None,
            "qualifiers":   {},
            "description":  description,
        }

        def _on_done(result):
            if not result:
                return
            entry = result.get("entry") if isinstance(result, dict) else None
            if not entry or result.get("action") != "save":
                return
            persist = getattr(self.app, "_persist_feature_entry", None)
            if persist is None or not persist(entry):
                return
            self.app.notify(
                f"Saved '{entry.get('name')}' as a "
                f"{entry.get('feature_type')} feature."
            )
            # Refresh so the "Feat Lib" column flips to ✓ for the row
            # we just registered.
            self._populate()

        self.app.push_screen(
            AddFeatureModal(prefill=prefill),
            callback=_on_done,
        )

    @on(Button.Pressed, "#btn-parts-save-to-coll")
    def _save_to_collection(self, _) -> None:
        """Save the multi-selected user parts (or the cursor row when
        nothing is selected) to the active collection in the library.

        Each part lands as a fresh library entry whose sequence is the
        part's cloned plasmid form (insert + 5'/3' overhangs + the
        pUPD2 backbone stub from `_simulate_cloned_plasmid`) so the
        downstream library / map / sequence panels see a normal
        circular plasmid. The insert is annotated as a single feature
        so the user can still see where the part starts in the cloned
        product.

        Built-in catalog rows (no sequence) are filtered out and
        reported as 'skipped'. With no active collection at all, the
        action notifies and bails — the user has to pick or create
        one in the Library panel first.

        After a successful save the multi-select clears so the next
        Ctrl+click starts a fresh batch.
        """
        coll_name = _get_active_collection_name()
        if not coll_name:
            self.app.notify(
                "No active collection. Pick or create one from the "
                "Library panel before saving parts.",
                severity="warning",
            )
            return

        # Pick which rows to save: the multi-select set if non-empty,
        # otherwise the single cursor row (so the button works as
        # "save the current part" too without forcing a Ctrl+click).
        if self._selected_rows:
            target_rows = sorted(self._selected_rows)
        else:
            try:
                t = self.query_one("#parts-table", DataTable)
                cursor_row = t.cursor_row
            except NoMatches:
                cursor_row = None
            if (cursor_row is None or cursor_row < 0
                    or cursor_row >= len(self._rows)):
                self.app.notify(
                    "Select a part first.", severity="warning",
                )
                return
            target_rows = [cursor_row]

        valid: list[dict] = []
        skipped: int = 0
        for row_idx in target_rows:
            if 0 <= row_idx < len(self._rows):
                r = self._rows[row_idx]
                # L0 parts carry `sequence` (insert body); L1+ parts
                # (TU / MOD) carry the full plasmid as `gb_text` with
                # `sequence: ""` (see `_persist_assembly`). Accept
                # either so the button works for every user-saved row,
                # not just L0.
                if r.get("user") and (r.get("sequence") or r.get("gb_text")):
                    valid.append(r)
                else:
                    skipped += 1

        if not valid:
            self.app.notify(
                "No saveable parts in selection — built-in catalog "
                "parts have no sequence to save.",
                severity="warning",
            )
            return

        try:
            lib = self.app.query_one("#library", LibraryPanel)
        except NoMatches:
            self.app.notify(
                "Library panel not available.", severity="error",
            )
            return

        # Build the records up-front so collision detection runs once
        # for the whole batch rather than N times via N stacked modals.
        # Sweep #10 (2026-05-20): pre-fix the loop called
        # `lib.add_entry(rec)` per part, each colliding rec queueing a
        # modal, while the post-loop toast claimed success before any
        # modal resolved. Now the batch routes through a single
        # `add_entries_batch` collision flow and the toast fires from
        # the resolved callback.
        records: list = []
        record_to_diag: dict[str, str] = {}
        failed: list[str] = []
        for r in valid:
            try:
                reason = _diagnose_part_cloning(r)
                rec = _part_to_cloned_seqrecord(r)
                records.append(rec)
                if reason:
                    record_to_diag[r.get("name", "?")] = reason
            except Exception as exc:
                _log.exception(
                    "parts-bin: save-to-collection failed for %r: %s",
                    r.get("name"), exc,
                )
                failed.append(r.get("name", "?"))

        if not records:
            extras: list[str] = []
            if skipped:
                extras.append(f"{skipped} catalog row(s) skipped")
            if failed:
                extras.append(f"{len(failed)} failed")
            suffix = f" ({'; '.join(extras)})" if extras else ""
            self.app.notify(
                f"Save to '{coll_name}' failed — see log{suffix}",
                severity="error", markup=False,
            )
            return

        def _on_done(
            saved_names: "list[str]",
            replaced_names: "set[str]",
            cancelled: bool,
        ) -> None:
            if cancelled:
                self.app.notify(
                    f"Save to '{coll_name}' cancelled. "
                    f"Library unchanged.",
                    severity="warning", markup=False,
                )
                return
            tail = ", ".join(saved_names[:3])
            if len(saved_names) > 3:
                tail += f" (+{len(saved_names) - 3} more)"
            extras: list[str] = []
            if skipped:
                extras.append(f"{skipped} catalog row(s) skipped")
            if failed:
                extras.append(f"{len(failed)} failed")
            if replaced_names:
                extras.append(
                    f"{len(replaced_names)} overwritten"
                )
            suffix = f" ({'; '.join(extras)})" if extras else ""
            n = len(saved_names)
            if n:
                self.app.notify(
                    f"Saved {n} part(s) to '{coll_name}': "
                    f"{tail}{suffix}",
                    severity="success",  # type: ignore[arg-type]
                    markup=False,
                )
            else:
                self.app.notify(
                    f"No parts saved to '{coll_name}'{suffix}",
                    severity="warning", markup=False,
                )
            # Surface a separate, persistent warning per part that
            # fell back to the stub backbone. Long timeout because
            # the diagnostic is the user's only clue their saved
            # plasmid isn't in their configured entry vector. Only
            # fires for parts that actually landed (the on-cancel /
            # all-skipped branches short-circuit above).
            for nm in saved_names:
                reason = record_to_diag.get(nm)
                if reason:
                    self.app.notify(
                        f"'{nm}': {reason}",
                        title="Part saved with stub backbone",
                        severity="warning", markup=False, timeout=12,
                    )

        lib.add_entries_batch(records, on_done=_on_done)

        # Clear the multi-select so the next Ctrl+click sequence
        # starts fresh. Repopulating refreshes the "Feat Lib" column
        # too in case any part is now also a feature-library entry.
        self._clear_multi_select()

    @_action_log("app.parts_bin.delete")
    def action_delete_selected_parts(self) -> None:
        """Keyboard binding entry point for Delete — forwards to the
        same handler the Delete button uses so the keypress and the
        click share semantics (incl. confirm modal + multi-select
        awareness)."""
        self._delete_selected(None)

    def action_select_all_parts(self) -> None:
        """Ctrl+A handler: add every user row in the active tab to
        the multi-select. Subsequent Delete / Del fires the same
        confirm-modal flow as a manual multi-select would.

        No-op when the table is empty (no rows to select) — quiet
        rather than a notify because Ctrl+A is a fast power-user
        gesture and a toast on every empty press would be noise."""
        rows = getattr(self, "_rows", []) or []
        new_sel: set[int] = set()
        for idx, r in enumerate(rows):
            if r.get("user"):
                new_sel.add(idx)
        if not new_sel:
            return
        if new_sel == self._selected_rows:
            # Already at full-select; second Ctrl+A toggles back to
            # an empty selection, mirroring the typical text-editor
            # gesture (Ctrl+A then Ctrl+A again deselects).
            self._clear_multi_select()
            return
        self._selected_rows = new_sel
        self._refresh_multi_select_visuals()
        self.app.notify(
            f"Selected {len(new_sel)} part{'s' if len(new_sel) != 1 else ''} "
            f"— Delete to remove, Esc to cancel.",
            severity="information", markup=False, timeout=4,
        )

    @on(Button.Pressed, "#btn-parts-delete")
    def _delete_selected(self, _) -> None:
        """Delete the multi-selected user parts from the parts bin (or
        the cursor row when nothing is selected). Always prompts for
        confirmation via `PartsBinDeleteConfirmModal`, which adapts
        its message to the count: "Remove [name]?" for single,
        "Remove N parts? (preview…)" for multi.

        Built-in catalog rows can't be removed (they live in the
        grammar module, not the user's parts-bin file). Selected
        catalog rows are silently skipped from the delete set; if
        every selected row is built-in, the action notifies and
        bails before opening the confirm modal.
        """
        if self._selected_rows:
            target_rows = sorted(self._selected_rows)
        else:
            try:
                t = self.query_one("#parts-table", DataTable)
                cursor_row = t.cursor_row
            except NoMatches:
                cursor_row = None
            if (cursor_row is None or cursor_row < 0
                    or cursor_row >= len(self._rows)):
                self.app.notify("Select a part first.", severity="warning")
                return
            target_rows = [cursor_row]

        valid: list[dict] = []
        skipped: int = 0
        for row_idx in target_rows:
            if 0 <= row_idx < len(self._rows):
                r = self._rows[row_idx]
                if r.get("user"):
                    valid.append(r)
                else:
                    skipped += 1

        if not valid:
            self.app.notify(
                "Built-in catalog parts can't be removed from the "
                "parts bin. Multi-select skipped catalog rows; "
                "nothing left to delete.",
                severity="warning",
            )
            return

        names = [r.get("name", "?") for r in valid]
        # Snapshot the (name, sequence) tuples NOW with a count, not a
        # set: legacy duplicates (same name + sequence × N) used to
        # collapse into one set element and delete ALL N entries on a
        # single-row delete. Switching to ``Counter`` makes the delete
        # count-aware — selecting one of two duplicates removes one,
        # not both. Regression guard for 2026-05-20 fix.
        targets: "Counter[tuple[str, str]]" = Counter(
            (r.get("name", ""), r.get("sequence", "")) for r in valid
        )
        # Track skipped count for the post-delete toast (closure capture).
        skipped_for_toast = skipped

        def _on_confirm(ok: "bool | None") -> None:
            if not ok:
                return
            entries = _load_parts_bin()
            # Counter-driven removal: each entry consumes one unit of
            # the matching key; once depleted, subsequent entries with
            # the same key are KEPT. Preserves entry order.
            remaining = targets.copy()
            kept: list[dict] = []
            for e in entries:
                key = (e.get("name", ""), e.get("sequence", ""))
                if remaining.get(key, 0) > 0:
                    remaining[key] -= 1
                else:
                    kept.append(e)
            n_removed = len(entries) - len(kept)
            try:
                _save_parts_bin(kept)
            except (OSError, RuntimeError) as exc:
                _notify_save_failure(self.app, "Parts bin", exc)
                return
            extras: list[str] = []
            if skipped_for_toast:
                extras.append(
                    f"{skipped_for_toast} catalog row(s) skipped"
                )
            suffix = f" ({'; '.join(extras)})" if extras else ""
            self.app.notify(
                f"Removed {n_removed} part(s) from bin{suffix}",
                severity="success",  # type: ignore[arg-type]
                markup=False,
            )
            self._populate()

        self.app.push_screen(
            PartsBinDeleteConfirmModal(names),
            callback=_on_confirm,
        )

    @on(Button.Pressed, "#btn-parts-move-bin")
    def _move_selected_to_bin(self, _) -> None:
        """Move the selected user part(s) to another parts bin — the parts
        analog of the primer-library MOVE button (and the GUI side of the
        `move-part` endpoint). Catalog rows can't be moved (they live in
        the grammar module, not the user's bin) and are skipped; nothing
        else selected falls back to the cursor row. Opens a destination-bin
        picker, then moves the parts out of the active bin (re-mirroring
        `parts_bin.json` so they drop out of the live view) into the chosen
        bin — count-aware, so one of two duplicates moves just one."""
        if self._selected_rows:
            target_rows = sorted(self._selected_rows)
        else:
            try:
                t = self.query_one("#parts-table", DataTable)
                cursor_row = t.cursor_row
            except NoMatches:
                cursor_row = None
            if (cursor_row is None or cursor_row < 0
                    or cursor_row >= len(self._rows)):
                self.app.notify("Select a part first.", severity="warning")
                return
            target_rows = [cursor_row]
        valid = [self._rows[i] for i in target_rows
                 if 0 <= i < len(self._rows) and self._rows[i].get("user")]
        if not valid:
            self.app.notify(
                "Built-in catalog parts can't be moved — they live in the "
                "grammar module, not your bin.", severity="warning")
            return
        src = _get_active_parts_bin_name()
        dests = [n for b in _load_parts_bin_collections()
                 if (n := (b.get("name") or "")) and n != src]
        if not dests:
            self.app.notify(
                "No other bin to move into — make one in the bin picker first.",
                severity="warning")
            return
        targets: "Counter[tuple[str, str]]" = Counter(
            (r.get("name", ""), r.get("sequence", "")) for r in valid)
        n_sel = len(valid)

        def _picked(dest) -> None:
            if not isinstance(dest, str) or not dest:
                return
            n = self._commit_part_move_to_bin(targets, dest)
            if n:
                self._clear_multi_select()
                self._populate()
                self.app.notify(
                    f"Moved {n} part{'s' if n != 1 else ''} to '{dest}'.",
                    severity="information")
        self.app.push_screen(
            _PrimerMoveCopyModal("move", dests, n_sel,
                                 item_singular="part", item_plural="parts",
                                 dest_label="bin"),
            callback=_picked)

    def _commit_part_move_to_bin(
            self, targets: "Counter[tuple[str, str]]", dest: str) -> int:
        """Move the active bin's user parts whose ``(name, sequence)`` is in
        ``targets`` (count-aware) into ``dest``. Removes them from the active
        bin AND re-mirrors `parts_bin.json` so they vanish from the live view;
        deduped at the destination by ``(name, sequence)``. One atomic
        `_save_parts_bin_collections` writes both bins, then the mirror-swap
        ([INV-83]) shrinks the live file. Returns the count moved; 0 (+ a
        toast) on any save failure."""
        try:
            bins = _load_parts_bin_collections()
            src = _get_active_parts_bin_name()
            src_b = next((b for b in bins
                          if (b.get("name") or "") == src), None)
            dst_b = next((b for b in bins
                          if (b.get("name") or "") == dest), None)
            if src_b is None or dst_b is None:
                return 0
            remaining = targets.copy()
            moving: list[dict] = []
            kept: list[dict] = []
            for e in (src_b.get("parts") or []):
                key = (e.get("name", ""), e.get("sequence", ""))
                if remaining.get(key, 0) > 0:
                    remaining[key] -= 1
                    moving.append(e)
                else:
                    kept.append(e)
            if not moving:
                return 0
            src_b["parts"] = kept
            dst_parts = dst_b.setdefault("parts", [])
            dst_keys = {(p.get("name", ""), p.get("sequence", ""))
                        for p in dst_parts}
            for e in moving:
                k = (e.get("name", ""), e.get("sequence", ""))
                if k in dst_keys:
                    continue            # dedup by (name, sequence) at the dest
                dst_keys.add(k)
                dst_parts.append(_typed_clone(e))
            _save_parts_bin_collections(bins)
            # Source IS the active bin — re-mirror the live parts_bin.json so
            # moved rows drop out of the view + cache. Mirror-swap (not
            # `_save_parts_bin`) so the shrink can't trip the L3 guard.
            _safe_save_json_mirror(
                _state._PARTS_BIN_FILE,
                [p for p in kept if isinstance(p, dict)], "Parts bin")
            _state._parts_bin_cache = None
            _clear_assembly_fragment_cache()
            return len(moving)
        except (OSError, RuntimeError) as exc:
            _notify_save_failure(self.app, "Parts bin", exc)
            return 0

    @on(Button.Pressed, "#btn-parts-close")
    def _close(self, _) -> None:
        self.dismiss(None)

    def action_cancel(self) -> None:
        self.dismiss(None)


# ── FASTA file picker ──────────────────────────────────────────────────────────
#
# Used by DomesticatorModal's "Open FASTA" source. The picker is a standard
# DirectoryTree wrapped in a modal, but with custom label rendering that
# paints FASTA files lime green and everything else white so the user can
# scan a mixed directory quickly. Returns an absolute path string on
# dismiss, or None on cancel.

# Lowercased extensions (including the leading dot) that count as FASTA
# for the picker's highlight rule. Kept broad so GenBank-style FASTA
# dumps (.fna for nucleotide, .faa for amino acid, .ffn for coding,
# etc.) all light up.

# Hot pink and plain white — high contrast so the eye finds FASTA files
# immediately in a mixed directory listing. 2026-05-06: switched from
# lime green to pink so FASTA carries the same colour signal across
# every picker in the app (the Open modal also renders FASTA pink + .dna
# orange so users can distinguish file types at a glance).




# ── Demo plasmid for default no-arg launch ────────────────────────────────────
#
# A 1000-bp synthetic circular plasmid used as the default canvas content
# when `splicecraft` launches without an accession / file argument. The
# sequence is deterministic — same bytes on every launch — so screenshots,
# bug reports, and CLI demos all reproduce the same view. Layout:
#
#   bp 0..200   — ori-like spacer (pseudo-random)
#   bp 200..250 — MCS with embedded EcoRI/HindIII/BamHI/XbaI sites
#                 (so the Simulator gel sub-tab has cuts to demonstrate)
#   bp 250..550 — synthetic 300-bp ORF (ATG…TAA, no internal stops)
#   bp 550..700 — terminator-like region (pseudo-random)
#   bp 700..1000 — backbone spacer (pseudo-random)
#
# Generated once via `random.Random(0xC57A1)` and embedded as a literal
# below — no runtime randomness, no `random` import, no surprises.
_DEMO_PLASMID_NAME = "demo_1kb"
_DEMO_PLASMID_SEQ = (
    "CTGAGCCCGTCCCCTTAATAATCAGTGGGTAGTTTCTTTCAATCGGAGACAGGCCCTATC"
    "CGGAACTCCCGGCGAATAGTGGTTGGCGGTATTGCTCACTGCTGTCTCGTAACCTTAACC"
    "CCCCAGATTGAAATTAGGCGTTGGTCCGGGACACAAGTAGCGTTAGCTTTTTCATCAAGG"
    "CTGCTAGCTTCCCATTTGGCCCTCTCGAATTCCAGTTAAGCTTTATACGGATCCCGGCAT"
    "CTAGAGGTAAATGGAAGTAATCTTTCAATTCGATCCCGAACTGTCGTATACACTACTCGT"
    "GACGCGGGTAATAGAGGTTTCAGGCTGTGTCGGATACCGTGCTAAGTCATCTGAGTGGGT"
    "GGGCGGTAACCATGAAGTCTCGACGTTGGAAACATTTCAAAAAATTCTCGTTATTTCACT"
    "CAGACGACTACGAGGCAATAACAGGTGTATTGTTAAGTGGCTCTGGTCGTTGTATCGTGT"
    "CTCCGGCGTCGCTTTAAAACTCATATGTATGAGAATAGGGTCCGTTCATGAAGCAAAACG"
    "TCAATCGTAATAAGTGGTCCACGAAATTGTCAAACATGGCACTCTCGCCGGATCAGGGTA"
    "AGTGAGAGTTCCGAGTATCTTCCTATCTCCCTCATGTTCACCTGGATTACGGAAGAACAA"
    "CACTGCACCTAATCGTCTAAGTCGGAGGGTAAGTAACACGACTTGTGTCATGACAATCAG"
    "GAAAAATCGCGGTGGCGATGAATTGAACTGCGCCTCATTGACTTGGTCAAGTAAGCTAAG"
    "AGCGCTATTTTGGTATACTTCACCGATGCCGGCCGTGAAAATCGTAAATCTCTCCACTGG"
    "TTGTCTCTGATGACGTGGTTCTAAGCTTGAGCAGCTTTAGTATACAACCGGACAGAGCGT"
    "ACGGGTTTACGCATCGATGCTCAATTCCCGAGGGCACAGGCAATATGGCTACGATGACCA"
    "AGTTATAGCGCTGTGTTGATCTCTCAGCGAGATAAGTGTG"
)


def _make_demo_record():
    """Build the 1000-bp synthetic circular plasmid used as the default
    no-arg launch canvas. Pure constructor — no I/O, no randomness, no
    library write. The caller is expected to load this through
    `_apply_record` (not `_import_and_persist`) so the demo doesn't
    pollute the user's library on every cold launch."""
    from Bio.Seq            import Seq
    from Bio.SeqRecord       import SeqRecord
    from Bio.SeqFeature      import SeqFeature, FeatureLocation
    if len(_DEMO_PLASMID_SEQ) != 1000:
        # Defensive: editing the literal above and breaking the length
        # invariant would silently desync the documented layout from
        # the feature coordinates below.
        raise RuntimeError(
            f"_DEMO_PLASMID_SEQ length is {len(_DEMO_PLASMID_SEQ)} bp, "
            f"expected 1000"
        )
    rec = SeqRecord(
        Seq(_DEMO_PLASMID_SEQ),
        id=_DEMO_PLASMID_NAME, name=_DEMO_PLASMID_NAME,
        description=("SpliceCraft demo · 1 kb synthetic circular plasmid "
                      "with embedded EcoRI / HindIII / BamHI / XbaI sites"),
    )
    rec.annotations["molecule_type"] = "DNA"
    rec.annotations["topology"]      = "circular"
    rec.features = [
        SeqFeature(FeatureLocation(0, 200, strand=1),
                    type="rep_origin",
                    qualifiers={"label": ["demo_ori"],
                                  "note":  ["synthetic origin-of-replication "
                                             "placeholder"]}),
        SeqFeature(FeatureLocation(200, 250, strand=1),
                    type="misc_feature",
                    qualifiers={"label": ["MCS"],
                                  "note":  ["EcoRI / HindIII / BamHI / XbaI"]}),
        SeqFeature(FeatureLocation(250, 550, strand=1),
                    type="CDS",
                    qualifiers={"label": ["demo_CDS"],
                                  "translation": [
                                      "MKSRGFETLGYHFISLPTLATEGVSEPVISLFTRDIQ"
                                      "DSLYRGFETPLLGHTRSAYNDYDPCEYLLTPGSGNTI"
                                      "SDLGGSTTGTQRQEHHGGCYDFENMRRPCNRGR"],
                                  "note":  ["synthetic ORF, ATG→TAA, "
                                             "no internal stop"]}),
        SeqFeature(FeatureLocation(550, 700, strand=1),
                    type="terminator",
                    qualifiers={"label": ["demo_term"],
                                  "note":  ["transcriptional terminator "
                                             "placeholder"]}),
    ]
    return rec


def _make_demo_scrub_plasmid():
    """Offline demo plasmid for the Scrub tool: a circular plasmid whose CDS
    carries a BsaI (`GGTCTC`) AND an Esp3I (`CGTCTC`) site, both at codon
    boundaries so a synonymous (silent) cure removes them. Verified to
    Golden-Braid-scrub clean. Pure constructor — no I/O, no library write."""
    from Bio.Seq          import Seq
    from Bio.SeqRecord     import SeqRecord
    from Bio.SeqFeature    import SeqFeature, FeatureLocation
    cds = "ATGAAAGAAGATGGTCTCAAAGGGCCCCGTCTCGACTTTTAA"   # MKEDGLKGPRLDF*
    seq = (cds + "GATCATGCAACTAGCATCAG" * 60)[:1200]
    rec = SeqRecord(
        Seq(seq), id="demo_scrub", name="demo_scrub",
        description=("SpliceCraft demo · circular plasmid with BsaI + Esp3I "
                     "sites inside a CDS — try Mutato ▸ Scrub"),
        annotations={"molecule_type": "DNA", "topology": "circular"})
    rec.features = [
        SeqFeature(FeatureLocation(0, len(cds), strand=1), type="CDS",
                   qualifiers={"label": ["demoReporter"]}),
    ]
    return rec


def _make_demo_operon_plasmid():
    """Offline demo plasmid for the Synthesis / operon-domestication tools: a
    circular plasmid with two adjacent CDS 'genes' + a Shine-Dalgarno-ish
    spacer, so the user can lift + domesticate a multi-gene operon. Pure
    constructor — no I/O, no library write."""
    from Bio.Seq          import Seq
    from Bio.SeqRecord     import SeqRecord
    from Bio.SeqFeature    import SeqFeature, FeatureLocation
    cds_a  = "ATG" + "AAAGAAGATCTGTTTGCA" * 3 + "TAA"     # 60 bp · MKEDLFA…*
    spacer = "GATCAATAACAGGAGGTAAA"
    cds_b  = "ATG" + "GGTGCAGACTTTAAACAG" * 3 + "TAA"     # 60 bp · MGADFKQ…*
    op = cds_a + spacer + cds_b
    seq = (op + "GATCATGCAACTAGCATCAG" * 40)[:1500]
    b0 = len(cds_a) + len(spacer)
    rec = SeqRecord(
        Seq(seq), id="demo_operon", name="demo_operon",
        description=("SpliceCraft demo · two-gene operon — try Synthesis ▸ "
                     "lift selection + domesticate"),
        annotations={"molecule_type": "DNA", "topology": "circular"})
    rec.features = [
        SeqFeature(FeatureLocation(0, len(cds_a), strand=1), type="CDS",
                   qualifiers={"label": ["geneA"]}),
        SeqFeature(FeatureLocation(b0, b0 + len(cds_b), strand=1), type="CDS",
                   qualifiers={"label": ["geneB"]}),
    ]
    return rec


# ── Multi-record FASTA → collection helpers ───────────────────────────────
# A multi-record FASTA (e.g. a sequencing-data dump or a plasmid set
# distributed as a single file) lands in SpliceCraft as a NEW collection
# instead of forcing the user to split the file by hand. Topology is
# detected per-record from the FASTA description; explicit "circular"
# / "plasmid" hints flip it on, otherwise we default to linear (the
# safer assumption — chromosome chunks are common in FASTA dumps and
# rendering a 10 Mb linear genome as a circle is far worse than the
# reverse).

# Tokens whose presence in a FASTA description flips topology to
# circular. Conservative — protein-coding "plasmid-like" mentions
# without a positive circular signal stay linear.
_FASTA_CIRCULAR_HINTS: tuple[str, ...] = ("circular", "plasmid")


def _detect_fasta_topology(rec) -> str:
    """Return ``"circular"`` when the FASTA description contains a
    `_FASTA_CIRCULAR_HINTS` token (case-insensitive), else
    ``"linear"``. FASTA carries no topology field, so callers should
    default to linear and only flip on a positive signal — assuming
    circular by default would mis-orient chromosome chunks."""
    desc = (getattr(rec, "description", "") or "").lower()
    return "circular" if any(h in desc for h in _FASTA_CIRCULAR_HINTS) \
        else "linear"


def _fasta_records_to_seqrecords(parsed_records, file_path: str) -> list:
    """Turn a list of Bio.SeqIO FASTA records into SeqRecords ready for
    library import. Per-record:

      - sequence upper-cased + IUPAC-validated (skipped on failure)
      - topology auto-detected via `_detect_fasta_topology`
      - id deduplicated by suffixing ``_2`` / ``_3`` / etc. so the
        library-add dedup-by-id doesn't silently swallow duplicates
        (FASTA files in the wild often have all records named ``seq``)

    Returns only the records that parsed cleanly; empty / non-IUPAC
    records are logged at WARNING and skipped so a single bad entry
    doesn't kill the whole import. Callers should check the returned
    list length against the input length and surface a notice when
    records were dropped.
    """
    from Bio.Seq import Seq
    from Bio.SeqRecord import SeqRecord
    seen_ids: set = set()
    out: list = []
    valid_chars = set("ACGTURYMKSWBDHVN-X*")
    file_name = Path(file_path).name
    for i, rec in enumerate(parsed_records):
        seq = str(rec.seq).upper()
        if not seq:
            _log.warning(
                "FASTA record %d (%r): empty sequence, skipping",
                i, rec.id,
            )
            continue
        if set(seq) - valid_chars:
            _log.warning(
                "FASTA record %d (%r): non-IUPAC characters, skipping",
                i, rec.id,
            )
            continue
        # Dedupe id — append `_2`, `_3`, etc. on collision.
        base = (str(rec.id or "").strip()) or f"fasta_{i + 1}"
        cand = base
        n = 2
        while cand in seen_ids:
            cand = f"{base}_{n}"
            n += 1
        seen_ids.add(cand)
        topology = _detect_fasta_topology(rec)
        new_rec = SeqRecord(
            Seq(seq), id=cand, name=cand,
            description=(rec.description
                         or f"Imported from FASTA: {file_name}"),
        )
        new_rec.annotations["molecule_type"] = "DNA"
        new_rec.annotations["topology"]      = topology
        out.append(new_rec)
    return out


def _genbank_records_to_seqrecords(parsed_records: list,
                                       file_path: str) -> list:
    """GenBank-flavoured sibling of `_fasta_records_to_seqrecords`.
    Preserves features, annotations, qualifiers, and the original
    record id; only deduplicates ids on collision (multi-record .gb
    files sometimes carry duplicate LOCUS lines).

    Skipped per-record on: empty sequence, non-IUPAC characters in
    the sequence (rare for GenBank but possible from a corrupted
    file). Returns the surviving records.
    """
    seen_ids: set = set()
    out: list = []
    valid_chars = set("ACGTURYMKSWBDHVN-X*")
    file_name = Path(file_path).name
    for i, rec in enumerate(parsed_records):
        seq = str(getattr(rec, "seq", "") or "").upper()
        if not seq:
            _log.warning(
                "GenBank record %d (%r): empty sequence, skipping",
                i, getattr(rec, "id", "?"),
            )
            continue
        if set(seq) - valid_chars:
            _log.warning(
                "GenBank record %d (%r): non-IUPAC characters, "
                "skipping", i, getattr(rec, "id", "?"),
            )
            continue
        base = (str(rec.id or "").strip()) or f"genbank_{i + 1}"
        cand = base
        n = 2
        while cand in seen_ids:
            cand = f"{base}_{n}"
            n += 1
        seen_ids.add(cand)
        if cand != rec.id:
            rec.id = cand
        if not rec.name or rec.name == "<unknown name>":
            rec.name = cand[:_GB_LOCUS_NAME_MAX]
        if not rec.description:
            rec.description = f"Imported from GenBank: {file_name}"
        out.append(rec)
    return out


def _create_genbank_collection(name: str, records: list,
                                 file_path: str) -> None:
    """Persist a new collection containing GenBank `records` as
    library entries and switch the active collection to it. Mirror
    of `_create_fasta_collection` but uses the GenBank-aware
    `_record_to_library_entry` so features round-trip cleanly.
    """
    if not records:
        raise ValueError("No valid records to import.")
    if _collection_name_taken(name):
        raise ValueError(f"A collection named {name!r} already exists.")
    src_path = Path(file_path)
    plasmids = [_record_to_library_entry(rec, src_path) for rec in records]
    existing = _load_collections()
    existing.append({
        "name":        name,
        "description": (
            f"Imported from {src_path.name} ({len(records)} GenBank records)"
        ),
        "plasmids":    [],
        "saved":       _date.today().isoformat(),
    })
    _save_collections(existing)
    _set_active_collection_name(name)
    _switch_active_collection_library(plasmids)


def _create_fasta_collection(name: str, records: list, file_path: str) -> None:
    """Persist a new collection containing `records` as library entries
    and switch the active collection to it. Raises `ValueError` on
    name collision (caller should pre-check via `_collection_name_taken`
    so the modal can show the error inline before the disk write).

    Routes through `_save_collections` + `_save_library` so the
    4-layer data-safety net (atomic write, rotating backups, daily
    snapshot, lost-entry spillover — see CLAUDE.md invariant #31)
    rides along with the import.
    """
    if not records:
        raise ValueError("No valid records to import.")
    if _collection_name_taken(name):
        raise ValueError(f"A collection named {name!r} already exists.")
    src_path = Path(file_path)
    plasmids = [_record_to_library_entry(rec, src_path) for rec in records]
    # Append the empty-shell collection first; the active-collection
    # mirror in `_save_library` then fills its `plasmids` array.
    existing = _load_collections()
    existing.append({
        "name":        name,
        "description": (
            f"Imported from {src_path.name} ({len(records)} FASTA records)"
        ),
        "plasmids":    [],
        "saved":       _date.today().isoformat(),
    })
    _save_collections(existing)
    _set_active_collection_name(name)
    # Triggers `_sync_active_collection_plasmids` which mirrors the
    # plasmids into the collection we just created.
    _switch_active_collection_library(plasmids)


