def _project_name_taken(name: str) -> bool:
    """Dup-name guard for create / rename. Pure check, no side effects."""
    return _find_project(name) is not None


def _ensure_default_project() -> None:
    """Idempotent: guarantee at least one experiment project exists
    AND that the active-project pointer names a real project.

    First-run users have a (possibly empty) `experiments.json` but no
    `experiment_projects.json` — migrate by wrapping their existing
    entries in "Main Project" and marking it active. Empty entries on
    first run still produces an empty Main Project so the screen
    always has something to show.

    Like `_ensure_default_collection` / `_ensure_default_parts_bin`,
    this MUST run in `PlasmidApp.compose()` (NOT `on_mount`) —
    Textual mounts leaves→root, so a child reading the active project
    during mount sees stale state if the migration hasn't run.

    Edge sweep 2026-05-18: also repairs an *orphaned* active pointer
    — if `settings.json::active_project` names a project that no
    longer exists (renamed/deleted by hand, or never existed), the
    mirror in `_sync_active_project_experiments` would silently skip
    on every save. Reset to the first existing project so the mirror
    re-engages.
    """
    projs = _load_experiment_projects()
    if projs:
        active = _get_active_project_name()
        names = {p.get("name") for p in projs if p.get("name")}
        if not active or active not in names:
            first = projs[0].get("name")
            if first:
                _set_active_project_name(first)
        return
    existing = _load_experiments()
    _save_experiment_projects([{
        "name":        _DEFAULT_PROJECT_NAME,
        "description": "Default project",
        "experiments": existing,
        "saved":       _date.today().isoformat(),
    }])
    _set_active_project_name(_DEFAULT_PROJECT_NAME)


def _sync_active_project_experiments(entries: "list[dict]") -> None:
    """Mirror the live `experiments.json` contents into the active
    project's `experiments` list inside `experiment_projects.json`.
    Silent no-op if no active project (first-launch race) or if the
    active name has been deleted by the user via the modal.

    Synchronous: projects carry Markdown text (no plasmid feature
    dicts), so the async coalescing pattern that
    `_sync_active_collection_plasmids` uses for 100+ MB libraries
    isn't worth the thread overhead. Revisit if a user surfaces a
    project with thousands of long-body entries.
    """
    name = _get_active_project_name()
    if not name:
        return
    snapshot = [_typed_clone(e) for e in entries if isinstance(e, dict)]
    projs = _load_experiment_projects()
    for p in projs:
        if p.get("name") == name:
            p["experiments"] = snapshot
            try:
                _save_experiment_projects(projs)
            except (OSError, RuntimeError) as exc:
                _bg_notify_save_failure(
                    f"Active-project mirror ({name})", exc,
                )
            return


def _restore_experiments_from_active_project() -> None:
    """Refresh `experiments.json` with the active project's entries on startup —
    the experiments twin of `_restore_primers_from_active_primer_collection`
    ([INV-83]). `experiment_projects.json` is the source of truth; the live file
    is the mirror. Self-heals a pointer/mirror desync left by an interrupted
    project switch (`set-active-experiment-project` /
    `ExperimentProjectsPickerModal`) or a `move-experiment` whose live re-sync
    failed — experiments had NO launch restore before, so such a desync used to
    survive relaunch and get clobbered by the next `_save_experiments`. Silent
    no-op when no active project exists."""
    name = _get_active_project_name()
    if not name:
        return
    target = _find_project(name)
    if target is None:
        return
    raw = target.get("experiments", [])
    entries = [e for e in raw if isinstance(e, dict)] if isinstance(raw, list) else []
    # Only rewrite on an actual desync (see _restore_parts_bin_from_active_bin):
    # a consistent launch must NOT touch experiments.json.
    try:
        if _load_experiments() == entries:
            return
    except (OSError, RuntimeError):
        pass
    _safe_save_json_mirror(_state._EXPERIMENTS_FILE, entries, "Experiments")
    _state._experiments_cache = None


# ── Register the experiments hooks the dataaccess sibling fires ──────────────
# `_migrate_legacy_tag_format` (shared with the editor body-readers) and the
# synchronous active-project mirror `_sync_active_project_experiments` (whose
# own `_save_experiment_projects` is a sibling re-export — RLock re-entry) stay
# hub-side; the sibling's `_load_experiments`/`_save_experiments` reach them
# through these. None until here → a sibling load/save in the import window
# skips the side-effect (none runs before registration).
_state._migrate_experiment_body_hook = _migrate_legacy_tag_format
_state._sync_active_project_experiments_hook = _sync_active_project_experiments


def _delete_experiment_attach_dir(entry_id: str) -> None:
    """Remove all attachment files for `entry_id` and the dir itself.
    Used when an entry is deleted from the notebook. Refuses
    transparently if the dir is a symlink (handled in
    `_experiment_attach_dir`)."""
    d = _experiment_attach_dir(entry_id, create=False)
    if d is None or not d.exists():
        return
    _refuse_unauthorized_delete(d, "experiment attach dir")
    try:
        for p in d.iterdir():
            if p.is_file() and not p.is_symlink():
                try:
                    p.unlink()
                except OSError:
                    pass
        try:
            d.rmdir()
        except OSError:
            pass
    except OSError as exc:
        _log.warning("Could not clean experiment attach dir %s: %s",
                     d, exc)


_IMAGE_EXTS = (".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp",
               ".tiff", ".tif")


def _save_experiment_image(entry_id: str, data: bytes,
                              suggested_name: "str | None" = None,
                              ) -> "Path | None":
    """Atomically write image bytes into `_EXPERIMENTS_DIR/<entry_id>/`.
    Returns the saved Path on success, or `None` on cap-exceeded /
    sanitisation-fail / write-fail.

    Enforces both the per-image cap (`_EXPERIMENT_IMAGE_MAX_BYTES`) and
    the per-entry cumulative cap (`_EXPERIMENT_DIR_MAX_BYTES`).

    `suggested_name` provides the file extension hint only; the on-disk
    name is `img-<ts>-<rand>.<ext>` so concurrent attaches can't
    collide. Defaults to `.png` if no recognised extension is supplied.
    """
    if not isinstance(data, (bytes, bytearray)):
        return None
    if len(data) > _EXPERIMENT_IMAGE_MAX_BYTES:
        _log.warning(
            "Refusing image attach: %d bytes > %d byte cap",
            len(data), _EXPERIMENT_IMAGE_MAX_BYTES,
        )
        return None
    existing = _experiment_dir_size_bytes(entry_id)
    if existing + len(data) > _EXPERIMENT_DIR_MAX_BYTES:
        _log.warning(
            "Refusing image attach: entry %s dir would exceed %d "
            "(existing=%d + new=%d)",
            entry_id, _EXPERIMENT_DIR_MAX_BYTES, existing, len(data),
        )
        return None
    d = _experiment_attach_dir(entry_id, create=True)
    if d is None:
        return None
    suffix = ".png"
    if suggested_name:
        try:
            sn = Path(suggested_name).name
            if sn and "." in sn:
                cand = "." + sn.rsplit(".", 1)[1].lower()
                if cand in _IMAGE_EXTS:
                    suffix = cand
        except (ValueError, IndexError):
            pass
    ts = _datetime.now().strftime("%Y%m%dT%H%M%S")
    name = f"img-{ts}-{_uuid.uuid4().hex[:6]}{suffix}"
    out = d / name
    # [INV-66 extension] L2 chokepoint covers experiment image bytes too.
    # Per-entry images can be 10 MB each up to 100 MB total; an
    # unsandboxed probe with the right entry_id could write garbage
    # into the user's real experiments attach dir.
    _refuse_unauthorized_write(out, "experiment image")
    try:
        _atomic_write_bytes(out, bytes(data))
    except OSError as exc:
        _log.warning("Image atomic-write failed for %s: %s", out, exc)
        return None
    return out


def _render_plasmid_refs(body_md: str) -> str:
    """Pre-process `body_md` for Markdown rendering: replace
    `@<id>` plasmid tokens with markdown links carrying a custom
    `splicecraft://plasmid/<id>` href. The `ExperimentsScreen`
    `LinkClicked` handler intercepts that scheme to load the referenced
    plasmid; unknown schemes fall through to Textual's default.

    Accepts the legacy `@plasmid:<id>` format defensively by routing
    through `_migrate_legacy_tag_format` first — callers reading from
    disk normally hit the migration in `_load_experiments`, but
    export paths and external callers may pass bodies that never
    went through that loader."""
    if not body_md or "@" not in body_md:
        return body_md
    body_md = _migrate_legacy_tag_format(body_md)
    return _PLASMID_REF_RE.sub(
        lambda m: f"[`@{m.group(1)}`]({_PLASMID_LINK_SCHEME}{m.group(1)})",
        body_md,
    )


