# ── Spellcheck primitives (pyspellchecker-backed) ────────────────────────────
#
# Pure-Python English spellcheck for the Compose pane. `pyspellchecker`
# bundles its wordlist so there's no per-launch network or external
# corpus fetch. A user-maintained custom dictionary is persisted via
# `_get_setting("experiments_custom_dict")` — words the user explicitly
# "added to dictionary" survive across sessions and load alongside the
# stock corpus.
#
# Non-prose markdown regions (code spans, fenced blocks, hyperlinks,
# image refs, plasmid xrefs, raw URLs) are masked with spaces BEFORE
# tokenisation so they don't pollute the misspelling list. Tokens are
# alphabetic-and-apostrophe sequences ≥ 2 chars.

_SPELLCHECK_WORD_RE = re.compile(r"\b[A-Za-z][A-Za-z'\-]{1,}\b")
_SPELLCHECK_SKIP_PATTERNS = (
    re.compile(r"```[\s\S]*?```"),      # fenced code blocks
    re.compile(r"`[^`]+`"),               # inline code
    re.compile(r"!\[[^\]\[]*\]\([^)(]+\)"),  # image links — must come
                                          # before the `!<id>` action
                                          # pattern so `![alt](url)`
                                          # isn't mis-tagged.
    # The two link patterns EXCLUDE `[`/`(` from their inner classes (not
    # just `]`/`)`): a long run of unmatched `[` would otherwise make the
    # engine restart an unbounded `[^\]]+` scan at every position — O(n²).
    # A pathological notebook body fed to F7 spellcheck used to hang the
    # (background) worker for seconds; this keeps both patterns O(n).
    re.compile(r"\[[^\]\[]+\]\([^)(]+\)"),   # markdown links
    re.compile(r"https?://\S+"),          # raw URLs
    re.compile(r"@plasmid:\S+"),          # legacy plasmid cross-refs
    re.compile(r"@actions:\S+"),          # legacy action cross-refs
    re.compile(                            # new single-sigil plasmid
        r"(?<![\w@])@[A-Za-z][\w.\-]{0,63}"
    ),
    re.compile(                            # new single-sigil action
        r"(?<![\w!])![A-Za-z][\w.\-]{0,63}"
    ),
    re.compile(                            # new single-sigil gel
        r"(?<![\w&])&[A-Za-z][\w.\-]{0,63}"
    ),
)



def _spellcheck_strip_code(text: str) -> str:
    """Mask non-prose markdown regions with spaces (same length as
    matched substring) so character offsets stay aligned but the
    masked content doesn't tokenise. Cheap O(n) regex sweep."""
    out = text
    for pat in _SPELLCHECK_SKIP_PATTERNS:
        out = pat.sub(lambda m: " " * len(m.group(0)), out)
    return out


def _get_spellcheck_engine():
    """Return a cached pyspellchecker instance with the user's custom
    dictionary loaded. Returns `None` if pyspellchecker is unavailable
    so callers can degrade gracefully (the import is a hard dep but
    defensive in case a user did a custom install)."""
    if _state._SPELLCHECK_ENGINE is not None:
        return _state._SPELLCHECK_ENGINE
    try:
        from spellchecker import SpellChecker  # type: ignore
    except ImportError:
        return None
    try:
        spell = SpellChecker()
    except Exception:
        _log.exception("Spellcheck: SpellChecker() init failed")
        return None
    custom = _get_setting("experiments_custom_dict", []) or []
    if isinstance(custom, list):
        try:
            spell.word_frequency.load_words(
                [w for w in custom if isinstance(w, str)]
            )
        except Exception:
            _log.exception("Spellcheck: custom-dict load_words failed")
    _state._SPELLCHECK_ENGINE = spell
    return spell


def _clear_spellcheck_engine() -> None:
    """Invalidate the cached engine so the next request reloads the
    custom dictionary. Called after `add-to-dict` modifies settings."""
    _state._SPELLCHECK_ENGINE = None


def _spellcheck_body(body_md: str) -> "list[tuple[str, list[str]]]":
    """Return `[(word, top_suggestions), ...]` for misspellings in
    `body_md`, preserving first-appearance order. Empty list if the
    spellcheck engine isn't available OR the body has no prose tokens.
    """
    spell = _get_spellcheck_engine()
    if spell is None:
        return []
    stripped = _spellcheck_strip_code(body_md or "")
    words = _SPELLCHECK_WORD_RE.findall(stripped)
    seen: "dict[str, str]" = {}
    for w in words:
        lw = w.lower()
        if lw not in seen:
            seen[lw] = w
    if not seen:
        return []
    try:
        misspelled = spell.unknown(seen.keys())
    except Exception:
        _log.exception("Spellcheck: unknown() lookup failed")
        return []
    out: "list[tuple[str, list[str]]]" = []
    for lw in seen:
        if lw in misspelled:
            try:
                cands = list(spell.candidates(lw) or [])[:5]
            except Exception:
                cands = []
            out.append((seen[lw], cands))
    return out


# ── Plasmidsaurus API fetch modal ────────────────────────────────────────────
#
# Download a Plasmidsaurus run by item code over the official OAuth2 REST API
# (sweep #29) and import its .gbk samples straight into the library. The
# headless core (`_plasmidsaurus_fetch_item_zip` + `_plasmidsaurus_zip_to_
# entries`, in the search/fileio siblings) is shared byte-for-byte with the
# `download-plasmidsaurus` agent endpoint, so a GUI fetch and an agent fetch
# land identical entries. Credentials resolve env-first
# (PLASMIDSAURUS_CLIENT_ID / _SECRET) then Settings; the disk write goes
# through the L2 chokepoint; the temp zip is deleted after import.

class PlasmidsaurusFetchModal(ModalScreen):
    """Fetch a Plasmidsaurus run by item code and import its samples.

    Self-contained: enter the 6-character item code, Download & Import, and
    the run's .gbk assemblies are added to the library as new entries
    (tagged ``source: plasmidsaurus:<code>:<sample>``, never overwriting
    existing entries). The actual download + parse happen on a worker thread
    with live progress; closing the modal cancels an in-flight download.
    Dismisses with ``None`` (it mutates the library directly rather than
    returning a value)."""

    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel", "Close", show=True),
    ]

    DEFAULT_CSS = """
    PlasmidsaurusFetchModal {
        align: center middle;
    }
    #ps-fetch-box {
        width: 72; height: auto; max-height: 80%;
        background: $surface; border: thick $primary;
        padding: 1 2;
    }
    #ps-fetch-title {
        text-align: center; text-style: bold;
        color: $text; background: $primary-darken-2;
        padding: 0 1; margin-bottom: 1;
    }
    #ps-fetch-creds { margin-bottom: 1; }
    #ps-fetch-code { margin-bottom: 1; }
    #ps-fetch-btns { height: auto; margin-bottom: 1; }
    #ps-fetch-btns Button { margin-right: 2; }
    #ps-fetch-status { height: auto; }
    """

    def __init__(self) -> None:
        super().__init__()
        self._busy = False

    def compose(self) -> ComposeResult:
        with Vertical(id="ps-fetch-box"):
            yield Static("Fetch from Plasmidsaurus", id="ps-fetch-title")
            yield Static("", id="ps-fetch-creds", markup=True)
            yield Input(
                placeholder="Item code (6 chars, e.g. ABC123)",
                id="ps-fetch-code",
            )
            with Horizontal(id="ps-fetch-btns"):
                yield Button("Download & Import",
                             id="btn-ps-fetch-go", variant="primary")
                yield Button("Close  [Esc]", id="btn-ps-fetch-close")
            yield Static(
                "[dim]Enter an item code and import its samples.[/dim]",
                id="ps-fetch-status", markup=True,
            )

    def on_mount(self) -> None:
        cid, sec = _plasmidsaurus_credentials()
        creds = self.query_one("#ps-fetch-creds", Static)
        if cid and sec:
            creds.update("[dim]Using your saved Plasmidsaurus API "
                         "credentials.[/dim]")
        else:
            creds.update(
                "[yellow]No API credentials found. Set "
                "PLASMIDSAURUS_CLIENT_ID / PLASMIDSAURUS_CLIENT_SECRET, "
                "or add them under Settings → Plasmidsaurus.[/yellow]")
        try:
            self.query_one("#ps-fetch-code", Input).focus()
        except NoMatches:
            pass

    def action_cancel(self) -> None:
        # The worker treats an unmounted modal as the cancel signal, so
        # closing mid-download aborts the stream cleanly.
        if not self._busy:
            self.dismiss(None)

    @on(Button.Pressed, "#btn-ps-fetch-close")
    def _close(self, _) -> None:
        self.action_cancel()

    @on(Button.Pressed, "#btn-ps-fetch-go")
    def _go(self, _) -> None:
        self._start()

    @on(Input.Submitted, "#ps-fetch-code")
    def _submit(self, _) -> None:
        self._start()

    def _set_status(self, msg: str) -> None:
        try:
            self.query_one("#ps-fetch-status", Static).update(msg)
        except NoMatches:
            pass

    def _start(self) -> None:
        if self._busy:
            return
        try:
            raw = self.query_one("#ps-fetch-code", Input).value
        except NoMatches:
            return
        code = _sanitize_plasmidsaurus_item_code(raw)
        if code is None:
            self._set_status("[red]Enter a valid 6-character item code "
                             "(A-Z / 0-9).[/red]")
            return
        cid, sec = _plasmidsaurus_credentials()
        if not cid or not sec:
            self._set_status("[red]No API credentials — set the env vars or "
                             "add them in Settings first.[/red]")
            return
        self._busy = True
        try:
            self.query_one("#btn-ps-fetch-go", Button).disabled = True
        except NoMatches:
            pass
        self._set_status(
            f"[yellow]Connecting to Plasmidsaurus for {code}…[/yellow]")
        self._fetch_worker(code, cid, sec)

    @work(thread=True, exclusive=True, group="plasmidsaurus_fetch")
    def _fetch_worker(self, code: str, cid: str, sec: str) -> None:
        import shutil
        import tempfile
        tmpdir = tempfile.mkdtemp(prefix="splicecraft-ps-")
        outcome: "tuple[str, object, list] | None" = None
        try:
            def _prog(done: int, total: "int | None") -> None:
                mb = done // (1024 * 1024)
                if total:
                    pct = int(100 * done / max(1, total))
                    m = (f"[yellow]Downloading {code}: {mb} / "
                         f"{total // (1024 * 1024)} MB ({pct}%)…[/yellow]")
                else:
                    m = f"[yellow]Downloading {code}: {mb} MB…[/yellow]"
                if self.is_mounted:
                    try:
                        self.app.call_from_thread(self._set_status, m)
                    except Exception:
                        pass

            def _cancelled() -> bool:
                return not self.is_mounted

            try:
                zip_path = _plasmidsaurus_fetch_item_zip(
                    code, tmpdir, kind="results",
                    client_id=cid, client_secret=sec,
                    progress_cb=_prog, cancel_check_cb=_cancelled)
                entries, warnings = _plasmidsaurus_zip_to_entries(
                    zip_path, run_id=code)
                if not entries:
                    outcome = ("err",
                               "No .gbk samples found in the results zip.",
                               warnings)
                else:
                    lib = _load_library()
                    seen = {e.get("id") for e in lib if isinstance(e, dict)}
                    for e in entries:
                        base = e["id"]
                        n = 1
                        while e["id"] in seen:
                            n += 1
                            e["id"] = f"{base}_{n}"
                        seen.add(e["id"])
                        lib.append(e)
                    _save_library(lib)
                    outcome = ("ok", entries, warnings)
            except (OSError, ValueError, RuntimeError) as exc:
                outcome = ("err", str(exc), [])
        finally:
            shutil.rmtree(tmpdir, ignore_errors=True)
        if self.is_mounted:
            try:
                self.app.call_from_thread(self._fetch_done, outcome)
            except Exception:
                _log.exception("Plasmidsaurus fetch: done callback failed")

    def _fetch_done(self, outcome: "tuple | None") -> None:
        self._busy = False
        try:
            self.query_one("#btn-ps-fetch-go", Button).disabled = False
        except NoMatches:
            pass
        if not outcome:
            self._set_status("[red]Fetch failed (see splicecraft log).[/red]")
            return
        if outcome[0] == "err":
            self._set_status(f"[red]{_esc_md(str(outcome[1]))}[/red]")
            return
        entries, warnings = outcome[1], outcome[2]
        try:
            lib = self.app.query_one("#library", LibraryPanel)
            lib._view_mode = "plasmids"
            lib._apply_view_mode()
            lib._repopulate_plasmids()
        except NoMatches:
            pass
        names = ", ".join(e["name"] for e in entries[:5])
        if len(entries) > 5:
            names += ", …"
        warn = f" ({len(warnings)} skipped)" if warnings else ""
        self.app.notify(
            f"Imported {len(entries)} sample(s) from Plasmidsaurus.",
            severity="information", timeout=5)
        self._set_status(
            f"[green]Imported {len(entries)} sample(s){warn}: "
            f"{_esc_md(names)}[/green]")


# ── Sequencing toolbar screen ────────────────────────────────────────────────
#
# `SequencingScreen` is the user-facing entry for sequencing-data
# workflows. Currently hosts one tab — Plasmidsaurus pairwise alignment
# of a .zip result against a library plasmid — and is designed to grow
# additional tabs (direct Plasmidsaurus API ingestion, nanopore consensus
# tools, sequencing-report diffs) without disturbing the alignment path.
#
# Plasmidsaurus tab flow:
#   1. Pick a .zip from the file tree (lime-green = .zip files).
#   2. Tab lists .gbk members; click one.
#   3. Target plasmid (from the active library) is auto-selected to the
#      currently-loaded record; user can change to any library entry.
#   4. Run → pairwise alignment posts onto the linear-map overlay band
#      on the main screen, and the target's library entry is tagged
#      `map_mode: "linear"` so re-opens default to linear view.
#
# `PlasmidsaurusAlignModal` is preserved as a module-level alias for
# back-compat with test fixtures and any agent-API call sites that
# referenced the old class name.

class SequencingScreen(Screen):
    """Full-screen Sequencing toolbar — tabbed workbench for
    sequencing-data ingestion + alignment.

    Currently a single Plasmidsaurus tab; designed to absorb future
    tabs without rewriting the alignment pipeline downstream.

    Dismisses with ``None`` on Esc / Close. On a successful alignment
    the worker pushes the result onto the main map's overlay band
    (`PlasmidApp._register_alignment`) and dismisses with the
    alignment dict so legacy callers chaining the result still work.
    """

    # App-level Ctrl+Z must not undo edits while the user is staging
    # an alignment (invariant #41 — modal Ctrl+Z opts out).
    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel",         "Close",  show=True),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    DEFAULT_CSS = """
    /* ── Frame ──────────────────────────────────────────────── */
    #seq-box {
        width: 100%; height: 1fr;
        background: $surface; padding: 0 1;
    }
    #seq-title {
        background: $primary-darken-2; color: $text;
        padding: 0 1; height: 1; text-align: center;
    }
    /* Top-level tab strip ("Plasmidsaurus" + future siblings). */
    #seq-tabs { width: 100%; height: 1fr; }
    #seq-tabs > TabPane { padding: 0 1; }

    /* ── Plasmidsaurus pane (parent of the sub-sub-tabs) ────── */
    #sequencing-plasmidsaurus { width: 100%; height: 1fr; }
    #plasmidsaurus-subtabs { width: 100%; height: 1fr; }
    /* `padding: 0 1` leaves 1-cell horizontal breathing room either
       side of every sub-tab's body without burning a row at top/
       bottom. Looser spacing (`padding: 1`) costs ~10% of the
       baseline 48-row terminal across two TabbedContent layers. */
    #plasmidsaurus-subtabs > TabPane { padding: 0 1; }

    /* Plain-text labels in any sub-tab get a 1-row top margin so
       they don't crash into the widget above. Bare `Label` rule
       only — Static rows with `margin-top: 1` set explicitly
       below stay independent. */
    #sequencing-plasmidsaurus Label { color: $text-muted; margin-top: 1; }

    /* INV-74 (2026-05-25): bulk-align progress widgets — hidden until
       the worker fires, then surfaced as a status line + bar so the
       user can see per-sample progress instead of a UI-hang silence. */
    .bulk-align-progress { display: none; }
    .bulk-align-progress.-active { display: block; }
    #bulk-align-progress { margin-top: 1; color: $text; }
    #bulk-align-bar { width: 100%; margin-top: 1; }

    /* ── General sub-tab ───────────────────────────────────────
       Zip-picker tree on top (fixed 12 rows — enough to scroll
       through ~10 entries before scrolling kicks in) and the run
       summary below (flexes into remaining height with a 4-row
       floor so even short terminals show the headline counts). */
    #align-zip-tree {
        height: 12; min-height: 8;
        border: solid $primary-darken-2;
    }
    #align-selected-zip {
        height: 1; color: $text-muted; margin-top: 1;
    }
    #plasmidsaurus-run-meta {
        height: 1fr; min-height: 4;
        color: $text; margin-top: 1;
    }

    /* ── Samples sub-tab ───────────────────────────────────────
       Single DataTable flexed into the pane. Hint above (1 row,
       no top margin so it tucks under the tab header). */
    #plasmidsaurus-sample-hint { height: 1; color: $text-muted; }
    #align-members  {
        height: 1fr; min-height: 6;
        border: solid $primary-darken-2;
        margin-top: 1;
    }

    /* ── Quality sub-tab ───────────────────────────────────────
       Two stacked tables (per-sample QC metrics on top, run-level
       files below). The QC table flexes to fill available rows;
       the run-files table is fixed-height (8 rows is enough for
       the typical ≤3 run-level files; scrolls otherwise). */
    #plasmidsaurus-quality-hint { height: 1; color: $text-muted; }
    #plasmidsaurus-quality-table {
        height: 1fr; min-height: 6;
        border: solid $primary-darken-2;
        margin-top: 1;
    }
    #plasmidsaurus-runfiles-table {
        height: 8; min-height: 4;
        border: solid $primary-darken-2;
        margin-top: 1;
    }

    /* ── Align sub-tab ─────────────────────────────────────────
       Query indicator (1 row, accent-colored), target dropdown,
       status line, and the run button. Compact stack because
       this pane is short on content. */
    #plasmidsaurus-align-query {
        height: 1; color: $accent;
    }
    #align-target {
        width: 100%; margin-top: 1;
    }
    #align-status {
        height: 1; color: $text-muted; margin-top: 1;
    }
    #align-btns {
        height: 3; margin-top: 1; align: left middle;
    }
    #align-btns Button { margin-right: 1; min-width: 14; }

    /* ── Sanger pane ────────────────────────────────────────── */
    #sequencing-sanger { width: 100%; height: 1fr; }
    #sanger-tree {
        height: 12; min-height: 8;
        border: solid $primary-darken-2;
    }
    #sanger-selected {
        height: 1; color: $text-muted; margin-top: 1;
    }
    #sanger-preview {
        height: 1fr; min-height: 6;
        color: $text; margin-top: 1;
    }
    #sanger-btns {
        height: 3; margin-top: 1; align: left middle;
    }
    #sanger-btns Button { margin-right: 1; min-width: 16; }

    /* ── Screen-level footer with the Close button ──────────── */
    #seq-bottom {
        height: 3; margin-top: 1; align: left middle;
    }
    #seq-bottom Button { margin-right: 1; min-width: 14; }
    """

    def __init__(self, start_path: "str | None" = None,
                  initial_tab: str = "plasmidsaurus") -> None:
        super().__init__()
        # Tree starts at the user's home dir by default. A custom
        # start_path lets future entry points (e.g. an agent-API
        # wrapper) jump straight to a known downloads folder.
        start = Path(start_path).expanduser() if start_path else Path.home()
        try:
            if not start.is_dir():
                start = Path.home()
        except OSError:
            start = Path.home()
        self._tree_start: str = str(start)
        self._zip_path: "Path | None" = None
        # Sweep #9 (2026-05-19): mtime+size of the loaded zip so the
        # same-path short-circuit invalidates on content drift (user
        # re-runs Plasmidsaurus and overwrites the local zip with
        # new data). `None` means no zip loaded yet.
        self._zip_signature: "tuple[int, int] | None" = None
        # `_members` retained for back-compat with tests / agent paths
        # that scrape the flat .gbk member list off the screen state.
        # New code reads `_parsed_run["samples"]` instead.
        self._members: list[dict] = []
        self._selected_member: "str | None" = None
        # 1-based index of the selected sample in `_parsed_run["samples"]`
        # plus its `.gbk` leaf filename (no extension) — used to build
        # the alignment label `f"{order} {basename}"` so the overlay
        # band shows e.g. `1 RUN42_1_DEMO34` instead of the full
        # `RUN42_genbank-files/RUN42_1_DEMO34.gbk` zip path.
        self._selected_order_num: "int | None" = None
        self._selected_gbk_basename: "str | None" = None
        # Structured parse of the loaded zip — populated by
        # `_on_zip_picked` via `_parse_plasmidsaurus_zip`. Empty dict
        # until a valid zip lands, which is also how the sub-tab
        # gating (`_apply_subtab_gating`) detects "data loaded?".
        self._parsed_run: dict = {}
        # Cancel flag for the alignment worker. The PairwiseAligner
        # C-loop can't be interrupted (invariant #28), so cancel is
        # cooperative — the worker checks this before registering on
        # the overlay band, otherwise the user closes the screen and
        # a stale alignment still surfaces seconds later.
        self._cancelled: bool = False
        # INV-74 (2026-05-25): one-shot dismiss flag — guards against
        # the double-dismiss `ScreenStackError` user-reported crash.
        self._dismissed: bool = False
        self._initial_tab: str = initial_tab or "plasmidsaurus"

    def check_action(self, action: str, parameters: tuple) -> bool | None:
        """Allow Screen-level actions (mirrors `SimulatorScreen`)."""
        return True

    def compose(self) -> ComposeResult:
        yield Header()
        with Vertical(id="seq-box"):
            yield Static(" Sequencing toolbar ", id="seq-title")
            with TabbedContent(
                initial=f"seq-tab-{self._initial_tab}", id="seq-tabs",
            ):
                with TabPane("Plasmidsaurus", id="seq-tab-plasmidsaurus"):
                    yield from self._compose_plasmidsaurus_pane()
                with TabPane("Sanger (.ab1)", id="seq-tab-sanger"):
                    yield from self._compose_sanger_pane()
            with Horizontal(id="seq-bottom"):
                yield Button("Close  [Esc]", id="btn-sequencing-close")
        yield Footer()

    def _compose_plasmidsaurus_pane(self) -> ComposeResult:
        with Vertical(id="sequencing-plasmidsaurus"):
            with TabbedContent(
                initial="psaurus-sub-general",
                id="plasmidsaurus-subtabs",
            ):
                # Tab labels carry step numbers so the workflow is
                # obvious from the tab bar itself: 1 → 2 → 3, with
                # Quality as optional QC inspection in between. The
                # numeric prefix replaces the more polished but
                # less self-explanatory bare names ("General",
                # "Samples", "Align") that left users tab-bouncing
                # to figure out what each step did.
                with TabPane("1. Pick zip", id="psaurus-sub-general"):
                    yield from self._compose_general_subtab()
                with TabPane("2. Pick sample", id="psaurus-sub-samples",
                              disabled=True):
                    yield from self._compose_samples_subtab()
                with TabPane("QC (optional)", id="psaurus-sub-quality",
                              disabled=True):
                    yield from self._compose_quality_subtab()
                with TabPane("3. Pick target + align",
                              id="psaurus-sub-align",
                              disabled=True):
                    yield from self._compose_align_subtab()

    def _compose_general_subtab(self) -> ComposeResult:
        """General sub-sub-tab: zip file picker + run-level overview.
        The only tab enabled before a zip is loaded."""
        yield Static(
            "[b]Step 1 of 3:[/b] pick the Plasmidsaurus results [b].zip[/b] "
            "for this run.\n"
            "[dim]The next two tabs unlock once the zip parses.[/dim]",
            markup=True, id="plasmidsaurus-general-hint",
        )
        with Horizontal(id="psaurus-api-fetch-row"):
            yield Button(
                "Fetch by item code from Plasmidsaurus API",
                id="btn-psaurus-fetch-api", variant="primary",
            )
        yield Static(
            "[dim]Fetches a run straight from your Plasmidsaurus account "
            "and imports its samples — or browse for a downloaded "
            ".zip below.[/dim]",
            markup=True, id="psaurus-api-fetch-hint",
        )
        yield Label("Browse for the run .zip "
                    "(highlighted lime-green):")
        yield _ZipAwareDirectoryTree(
            self._tree_start, id="align-zip-tree",
        )
        yield Static(
            "[dim]No zip selected.[/dim]",
            id="align-selected-zip", markup=True,
        )
        yield Static(
            "[dim]Load a Plasmidsaurus results zip to unlock the "
            "Samples / Quality / Align tabs.[/dim]",
            id="plasmidsaurus-run-meta", markup=True,
        )
        with Horizontal(id="general-report-btns"):
            yield Button(
                "View verification report",
                id="btn-view-report", variant="default",
            )

    def _compose_samples_subtab(self) -> ComposeResult:
        """Samples sub-sub-tab: per-sample DataTable. Clicking a row
        marks that sample as the alignment query — the Align tab
        reads `_selected_member` to know which .gbk to pipe through
        the aligner."""
        yield Static(
            "[b]Step 2 of 3:[/b] click the sample row whose read you "
            "want to align.\n"
            "[dim]Then move to the [b]3. Pick target + align[/b] tab "
            "— it will use this sample's .gbk consensus as the "
            "query. Or use [b]Bulk auto-align[/b] below to match "
            "every sample to its library entry in one batch.[/dim]",
            id="plasmidsaurus-sample-hint", markup=True,
        )
        yield DataTable(id="align-members", cursor_type="row",
                          zebra_stripes=True)
        with Horizontal(id="bulk-align-btns"):
            yield Button(
                "Bulk auto-align all samples",
                id="btn-bulk-align", variant="primary",
            )
        # INV-74 (2026-05-25): per-sample progress text + bar so the
        # bulk-align batch doesn't look like a UI hang. Hidden by
        # default; shown when the worker fires and reset when done.
        # Pre-fix a 10-sample × 18 kb plasmid bulk-align stalled the
        # UI for ~2 minutes with no indication anything was happening.
        yield Static(
            "", id="bulk-align-progress", markup=True,
            classes="bulk-align-progress",
        )
        yield ProgressBar(
            id="bulk-align-bar", show_eta=False,
            classes="bulk-align-progress",
        )

    def _compose_quality_subtab(self) -> ComposeResult:
        """Quality sub-sub-tab: contamination / k-mer / coverage
        per sample, plus the run-level extras (gel.png etc.)."""
        yield Static(
            "[b]Optional:[/b] inspect QC metrics for each sample "
            "(contamination, k-mer profile, per-base coverage). "
            "Doesn't affect the alignment — purely informational.",
            id="plasmidsaurus-quality-hint", markup=True,
        )
        yield DataTable(id="plasmidsaurus-quality-table",
                         cursor_type="row", zebra_stripes=True)
        yield Label("Run-level files:")
        yield DataTable(id="plasmidsaurus-runfiles-table",
                         cursor_type="row", zebra_stripes=True)

    def _compose_align_subtab(self) -> ComposeResult:
        """Align sub-sub-tab: pick a target + run pairwise alignment
        against the sample chosen on the Samples tab."""
        yield Static(
            "[b]Step 3 of 3:[/b] pick the library plasmid this "
            "sample should align to, then press Align.\n"
            "[dim]On Align: the picked library plasmid loads onto "
            "the canvas, and this sample appears as a blue overlay "
            "bar on its linear view. The alignment persists onto "
            "the library entry — re-loading the plasmid restores "
            "the bar.[/dim]",
            id="plasmidsaurus-align-help", markup=True,
        )
        yield Static(
            "[dim]No sample picked yet — go back to the "
            "[b]2. Pick sample[/b] tab and click a row.[/dim]",
            id="plasmidsaurus-align-query", markup=True,
        )
        yield Label("Target plasmid (from active collection):")
        yield Select(
            self._target_options(),
            id="align-target",
            allow_blank=False,
        )
        yield Static("", id="align-status", markup=True)
        with Horizontal(id="align-btns"):
            yield Button("Align & open target on canvas",
                          id="btn-align-go",
                          variant="primary", disabled=True)

    def _compose_sanger_pane(self) -> ComposeResult:
        """Sanger tab: pick an .ab1 / .abi trace, preview it, and
        either load it onto the canvas or use it as the alignment
        query (handed to the Plasmidsaurus → Align sub-tab)."""
        with Vertical(id="sequencing-sanger"):
            yield Label(
                "Browse for an .ab1 / .abi Sanger trace "
                "(highlighted sky-blue):"
            )
            yield _AbiAwareDirectoryTree(
                self._tree_start, id="sanger-tree",
            )
            yield Static(
                "[dim]No trace selected.[/dim]",
                id="sanger-selected", markup=True,
            )
            yield Static(
                "[dim]Pick a trace to see its base-called length, "
                "mean Phred quality, and a preview of the first 200 "
                "bases.[/dim]",
                id="sanger-preview", markup=True,
            )
            with Horizontal(id="sanger-btns"):
                yield Button("Load into canvas",
                              id="btn-sanger-load",
                              variant="primary", disabled=True)
                yield Button("Add to library",
                              id="btn-sanger-add", disabled=True)

    @on(DirectoryTree.FileSelected, "#sanger-tree")
    def _on_sanger_picked(self, event) -> None:
        path = Path(str(event.path))
        if not _is_ab1_path(path):
            try:
                self.query_one("#sanger-selected", Static).update(
                    f"[yellow]Not an AB1 trace: {path.name}[/yellow]"
                )
            except NoMatches:
                pass
            return
        # Skip work if the user re-clicked the same file. AB1 parse is
        # ~50–200 ms per trace; without this guard, double-clicks
        # pay the parse cost twice. `_sanger_record` survives the
        # first successful pick so the buttons stay armed.
        if (path == getattr(self, "_sanger_path", None)
                and getattr(self, "_sanger_record", None) is not None):
            return
        self._sanger_path = path
        try:
            self.query_one("#sanger-selected", Static).update(
                f"Selected: [b]{path.name}[/b]"
            )
        except NoMatches:
            pass
        try:
            rec = _ab1_path_to_record(str(path))
        except ValueError as exc:
            try:
                self.query_one("#sanger-preview", Static).update(
                    f"[red]Could not read trace: {exc}[/red]"
                )
            except NoMatches:
                pass
            return
        bp = len(rec.seq)
        quals = rec.letter_annotations.get("phred_quality", []) or []
        mean_q = (sum(quals) / len(quals)) if quals else 0
        head = str(rec.seq)[:200]
        preview = (
            f"[b]{rec.name or rec.id}[/b]   {bp} bp   "
            f"mean Phred ≈ {mean_q:.1f}\n"
            f"[dim]First 200 bases:[/dim]\n{head}"
        )
        try:
            self.query_one("#sanger-preview", Static).update(preview)
        except NoMatches:
            pass
        try:
            self.query_one("#btn-sanger-load", Button).disabled = False
            self.query_one("#btn-sanger-add", Button).disabled = False
        except NoMatches:
            pass
        self._sanger_record = rec

    @on(Button.Pressed, "#btn-sanger-load")
    def _sanger_load(self, _) -> None:
        rec = getattr(self, "_sanger_record", None)
        if rec is None:
            return
        try:
            self.app._apply_record(rec)   # type: ignore[attr-defined]
        except Exception as exc:
            _log.exception("Sanger load_into_canvas failed: %s", exc)
            return
        self.dismiss(None)

    @on(Button.Pressed, "#btn-sanger-add")
    def _sanger_add_to_library(self, _) -> None:
        rec = getattr(self, "_sanger_record", None)
        path = getattr(self, "_sanger_path", None)
        if rec is None or path is None:
            return
        try:
            entry = _record_to_library_entry(rec, path)
            entries = _load_library()
            seen = {e.get("id") for e in entries if isinstance(e, dict)}
            base_id = entry["id"]
            n = 1
            while entry["id"] in seen:
                n += 1
                entry["id"] = f"{base_id}_{n}"
            entries.append(entry)
            _save_library(entries)
        except (OSError, ValueError) as exc:
            self.app.notify(
                f"Add to library failed: {exc}",
                severity="error", timeout=8,
            )
            return
        self.app.notify(
            f"Added {entry.get('name') or entry['id']} to library.",
            severity="information", timeout=4,
        )
        try:
            self.query_one("#sanger-preview", Static).update(
                f"[green]Added {entry.get('name') or entry['id']} "
                f"to library.[/green]"
            )
        except NoMatches:
            pass
        # Disable the Add button so re-clicking can't silently create
        # a duplicate entry (the pre-fix `_<N>` suffix-collision loop
        # would happily mint `DEMO_38_2`, `DEMO_38_3`, ... on each
        # click). User has to pick a different trace to re-arm.
        try:
            self.query_one("#btn-sanger-add", Button).disabled = True
        except NoMatches:
            pass
        # Refresh the main LibraryPanel so the new entry shows up
        # without the user having to navigate away + back. Mirrors the
        # pattern used by the primer-goto + collection-switch paths.
        try:
            lib = self.app.query_one("#library", LibraryPanel)
            lib._view_mode = "plasmids"
            lib._apply_view_mode()
            lib._repopulate_plasmids()
        except NoMatches:
            pass

    # Sentinel value the Select shows when the library is empty.
    # `_go` checks for this string before kicking off the align so
    # the user is told to add a plasmid first instead of crashing on
    # a missing target. NUL-prefixed to make collision with a real
    # library `id` impossible (NCBI/locus ids never carry NUL).
    _EMPTY_LIBRARY_SENTINEL = "\x00no-library\x00"

    def _target_options(self) -> list[tuple[str, str]]:
        """Build the (label, value) list for the target dropdown.
        Pulls from the library so the user can align against any
        plasmid in the active collection. Each value is the entry's
        `id` (LOCUS-safe), label is the display name + size.

        Library load errors degrade to an empty-library sentinel row
        so the Select stays mountable; the user sees an explicit
        hint instead of a crash. Narrow except per invariant #1:
        `_load_library` only surfaces through `_safe_load_json`'s
        contract, which logs internally — so the failures we'd see
        here are typed JSON / encoding / OSError paths.
        """
        opts: list[tuple[str, str]] = []
        try:
            # Sweep #25: readonly iterator — only `.get()` reads, never
            # mutates. `sorted` builds a fresh list of references for
            # downstream loop which only reads fields.
            entries = sorted(
                (e for e in _iter_library_readonly() if e.get("id")),
                key=lambda e: _natural_sort_key(
                    e.get("name") or e.get("id") or ""
                ),
            )
            for e in entries:
                eid = e.get("id") or ""
                # Defence: a library entry whose id happens to be our
                # sentinel would alias to the "no library" row. Refuse
                # to surface it.
                if eid == self._EMPTY_LIBRARY_SENTINEL:
                    continue
                name = e.get("name") or eid
                size = e.get("size", 0)
                opts.append((f"{name}  ({size:,} bp)", eid))
        except (OSError, ValueError, TypeError) as exc:
            _log.exception(
                "SequencingScreen: library load failed (%s)",
                type(exc).__name__,
            )
        if not opts:
            opts.append(
                ("(no plasmids in library — save one first)",
                 self._EMPTY_LIBRARY_SENTINEL),
            )
        return opts

    def on_mount(self) -> None:
        # Samples sub-tab: per-sample summary table.
        try:
            t = self.query_one("#align-members", DataTable)
            t.add_columns("Sample", "bp", "Feats",
                            "Cov mean", "Contam %", "AB1")
        except NoMatches:
            pass
        # Quality sub-tab: contamination / k-mer / coverage detail.
        try:
            q = self.query_one(
                "#plasmidsaurus-quality-table", DataTable,
            )
            q.add_columns(
                "Sample", "1-mer moles %", "1-mer mass %",
                "Contam %", "Source",
                "Cov mean", "Cov min", "≥ 20×",
            )
        except NoMatches:
            pass
        try:
            rf = self.query_one(
                "#plasmidsaurus-runfiles-table", DataTable,
            )
            rf.add_columns("File", "Size", "Category")
        except NoMatches:
            pass
        # Pre-select the currently-loaded record on the target dropdown
        # so the user doesn't have to re-pick it in the common case
        # where they want to diff the run against the loaded plasmid.
        # Skips the empty-library sentinel so a `cur.id` collision
        # against it (extremely unlikely — sentinel is NUL-anchored)
        # can't accidentally activate the "no library" placeholder.
        # Library is cached after first `_target_options()` call so
        # the second invocation here is microseconds, not a re-load.
        try:
            cur = getattr(self.app, "_current_record", None)
            cur_id = getattr(cur, "id", None) if cur is not None else None
            if cur_id and cur_id != self._EMPTY_LIBRARY_SENTINEL:
                sel = self.query_one("#align-target", Select)
                for _label, val in self._target_options():
                    if val == cur_id and val != self._EMPTY_LIBRARY_SENTINEL:
                        sel.value = val
                        break
        except (NoMatches, AttributeError):
            pass

    @on(Button.Pressed, "#btn-psaurus-fetch-api")
    def _open_plasmidsaurus_fetch(self, _) -> None:
        """Open the Plasmidsaurus API fetch modal — download a run by item
        code and import its samples without leaving the app. Self-contained
        (imports straight to the library); the file-tree path below stays the
        route for the interactive align-against-target flow."""
        self.app.push_screen(PlasmidsaurusFetchModal())

    @on(DirectoryTree.FileSelected, "#align-zip-tree")
    def _on_zip_picked(self, event) -> None:
        """User clicked a file in the directory tree. If it's a .zip,
        parse the structured run; if not, surface a helpful warning
        without disabling anything that's already in a good state.

        Skips re-parse when the same path is clicked twice in a row
        AND the file content hasn't changed — a Plasmidsaurus zip
        parse takes ~50-300 ms per sample (zip seeks + .gbk +
        per-base TSV scan), so the user double-clicking shouldn't
        pay the cost twice. Sweep #9 (2026-05-19): the short-
        circuit ALSO compares `(mtime_ns, size)` so a re-run that
        overwrites the same path with new data invalidates the
        cached parse instead of silently showing stale samples."""
        path = Path(str(event.path))
        # Same-path short-circuit: nothing to re-do if state is intact
        # AND the file's mtime+size matches the cached signature.
        try:
            st = path.stat()
            cur_sig: "tuple[int, int] | None" = (
                int(st.st_mtime_ns), int(st.st_size),
            )
        except OSError:
            cur_sig = None
        if (self._zip_path is not None
                and Path(self._zip_path) == path
                and self._parsed_run
                and cur_sig is not None
                and self._zip_signature == cur_sig):
            return
        try:
            sel  = self.query_one("#align-selected-zip", Static)
            meta = self.query_one("#plasmidsaurus-run-meta", Static)
        except NoMatches:
            return
        # Reset downstream state on every pick — even one we'll reject.
        self._reset_zip_state()
        if not _is_seq_zip_path(path):
            sel.update(
                f"[yellow]Not a .zip: {_esc_md(path.name)}[/yellow]"
            )
            meta.update(
                "[dim]Load a Plasmidsaurus results zip to unlock the "
                "Samples / Quality / Align tabs.[/dim]"
            )
            return
        try:
            parsed = _parse_plasmidsaurus_zip(path)
        except ValueError as exc:
            sel.update(f"[dim]Picked:[/dim] {_esc_md(str(path))}")
            meta.update(f"[red]{_esc_md(str(exc))}[/red]")
            return
        except (OSError, RuntimeError, MemoryError) as exc:
            # OSError covers filesystem hiccups during stat / open;
            # RuntimeError is what `_safe_xml_parse`-style helpers
            # raise from inside `_parse_plasmidsaurus_zip` on unsafe
            # input shapes; MemoryError caps an oversize per-base read
            # that slipped past the size guard. Narrow per invariant
            # #1 — defensive catches must enumerate the expected
            # exception types so a real bug isn't silently swallowed.
            _log.exception(
                "SequencingScreen: unexpected zip parse failure",
            )
            sel.update(f"[dim]Picked:[/dim] {_esc_md(str(path))}")
            meta.update(
                f"[red]Could not parse zip: "
                f"{_esc_md(type(exc).__name__)}[/red]"
            )
            return
        self._zip_path = path
        self._zip_signature = cur_sig
        self._parsed_run = parsed
        # Flat back-compat list of .gbk members for any caller still
        # reading `_members` (currently only legacy tests).
        self._members = [
            {"name": s["gbk"], "size": 0}
            for s in parsed.get("samples", [])
            if s.get("gbk")
        ]
        sel.update(f"[dim]Picked:[/dim] {_esc_md(str(path))}")
        self._populate_general_meta(parsed)
        self._populate_samples_table(parsed)
        self._populate_quality_tables(parsed)
        self._apply_subtab_gating(enabled=bool(parsed.get("samples")))

    def _reset_zip_state(self) -> None:
        """Clear every cached / displayed artefact from a previous
        zip so a fresh pick can't show stale rows. Called from
        `_on_zip_picked` at the top of every pick attempt."""
        self._zip_path = None
        self._zip_signature = None
        self._parsed_run = {}
        self._members = []
        self._selected_member = None
        self._selected_order_num = None
        self._selected_gbk_basename = None
        # Tables clear silently if they're not mounted yet (e.g.
        # an early `_on_zip_picked` fired during compose race).
        for tid in (
            "#align-members",
            "#plasmidsaurus-quality-table",
            "#plasmidsaurus-runfiles-table",
        ):
            try:
                self.query_one(tid, DataTable).clear()
            except NoMatches:
                pass
        try:
            self.query_one("#btn-align-go", Button).disabled = True
        except NoMatches:
            pass
        try:
            self.query_one(
                "#plasmidsaurus-align-query", Static,
            ).update(
                "[dim]No sample picked yet — switch to the Samples tab "
                "and click a row.[/dim]"
            )
        except NoMatches:
            pass
        try:
            self.query_one("#align-status", Static).update("")
        except NoMatches:
            pass
        self._apply_subtab_gating(enabled=False)

    _DEPENDENT_SUBTABS = (
        "psaurus-sub-samples",
        "psaurus-sub-quality",
        "psaurus-sub-align",
    )

    def _apply_subtab_gating(self, *, enabled: bool) -> None:
        """Toggle the `disabled` state on the Samples / Quality /
        Align sub-tabs. General stays enabled either way (it owns
        the zip picker). When disabling, also redirect the active
        sub-tab back to General so the user doesn't end up staring
        at a disabled-and-empty pane."""
        for tab_id in self._DEPENDENT_SUBTABS:
            try:
                pane = self.query_one(f"#{tab_id}", TabPane)
                pane.disabled = not enabled
            except NoMatches:
                continue
        if not enabled:
            # Force focus back to General so a previously-active
            # Samples / Quality / Align sub-tab can't strand the
            # user on a now-disabled pane. Wrapped in a broad except
            # because Textual's `TabbedContent.active` setter raises
            # `LookupError` if the target id isn't mounted yet (the
            # mount race lands here when the screen is composed +
            # `_reset_zip_state` fires before children settle).
            try:
                tabs = self.query_one(
                    "#plasmidsaurus-subtabs", TabbedContent,
                )
                if tabs.active in self._DEPENDENT_SUBTABS:
                    tabs.active = "psaurus-sub-general"
            except (NoMatches, LookupError, AttributeError):
                pass

    def _populate_general_meta(self, parsed: dict) -> None:
        """Write the General sub-tab's run-overview text from the
        parsed-zip dict. Empty / missing parsed → graceful hint."""
        try:
            meta = self.query_one(
                "#plasmidsaurus-run-meta", Static,
            )
        except NoMatches:
            return
        samples = parsed.get("samples") or []
        if not samples:
            meta.update(
                "[yellow]No samples found in this zip — no "
                "`<run>_genbank-files/` folder or standalone .gbk "
                "files detected.[/yellow]"
            )
            return
        run_id    = parsed.get("run_id", "") or "(unknown)"
        n_files   = parsed.get("total_files", 0)
        total_b   = parsed.get("total_size", 0)
        size_mb   = total_b / (1024 * 1024)
        n_samp    = len(samples)
        n_with_gbk    = sum(1 for s in samples if s.get("gbk"))
        n_with_perbase = sum(1 for s in samples if s.get("perbase"))
        run_files = parsed.get("run_files") or []
        meta.update(
            f"[bold]Run:[/bold] {_esc_md(run_id)}  ·  "
            f"[bold]{n_samp}[/bold] sample"
            f"{'s' if n_samp != 1 else ''}  ·  "
            f"{n_files} file{'s' if n_files != 1 else ''} "
            f"({size_mb:.2f} MB)\n"
            f"[dim]GenBank:[/dim] {n_with_gbk}/{n_samp}  ·  "
            f"[dim]per-base coverage:[/dim] {n_with_perbase}/{n_samp}"
            f"  ·  [dim]run-level files:[/dim] {len(run_files)}\n"
            f"\n[dim]→ Open the Samples tab to pick an alignment "
            f"query.[/dim]"
        )

    # Distinctive sentinel for rows whose sample has no .gbk consensus
    # — `_on_member_selected` checks this prefix to refuse the align
    # advance. The leading `\x00` makes it impossible for a real zip
    # member name (rejected by `_is_safe_zip_member_name`) to collide.
    _NO_GBK_KEY_PREFIX = "\x00no-gbk\x00"

    def _populate_samples_table(self, parsed: dict) -> None:
        """Fill the Samples sub-tab's per-sample table. One row per
        sample; cells show bp + feature count for the consensus .gbk,
        mean coverage, contamination %, and AB1 trace count.

        Opens the run zip ONCE for the whole walk rather than per
        sample. Pre-fix a 50-sample run incurred 50 `ZipFile.__init__`
        calls (~50 × 50 ms central-directory scan = 2-3 s frozen UI
        on the picker). The single-open variant amortises the cost.
        """
        try:
            t = self.query_one("#align-members", DataTable)
        except NoMatches:
            return
        t.clear()
        samples = parsed.get("samples") or []
        # Pre-pass: read every sample's gbk in one zip-open so the
        # table-render loop below doesn't pay the per-sample open cost.
        # On a malformed zip we bail to the per-row "—" placeholders;
        # the table still renders, just without bp/feats counts.
        gbk_meta: dict[str, tuple[str, str]] = {}
        if self._zip_path is not None and samples:
            gbk_meta = self._batch_extract_gbk_meta(samples)
        for s in samples:
            name = s.get("name") or s.get("base") or "?"
            gbk_member = s.get("gbk")
            bp, feats = gbk_meta.get(gbk_member or "", ("—", "—"))
            cov = s.get("perbase_coverage") or {}
            cov_mean_val = cov.get("mean")
            cov_mean = (
                f"{cov_mean_val:.1f}×"
                if isinstance(cov_mean_val, (int, float))
                else "—"
            )
            summary_parsed = _parse_plasmidsaurus_summary(
                s.get("summary_text", "") or "",
            )
            cp = summary_parsed.get("contamination_pct")
            contam = f"{cp:.1f}%" if isinstance(cp, (int, float)) else "—"
            ab1_count = len(s.get("ab1_files") or [])
            t.add_row(
                name, bp, feats, cov_mean, contam,
                str(ab1_count) if ab1_count else "—",
                # Row key: the gbk member name so `_on_member_selected`
                # can look up the .gbk straight out of the zip without
                # re-walking the parsed dict. Samples without a .gbk
                # carry the NUL-anchored sentinel — guaranteed not to
                # collide with any real zip member name (the safe-name
                # check refuses NUL).
                key=gbk_member or f"{self._NO_GBK_KEY_PREFIX}{name}",
            )

    def _batch_extract_gbk_meta(
        self, samples: "list[dict]",
    ) -> "dict[str, tuple[str, str]]":
        """Return ``{gbk_member_name: (bp_str, feats_str)}`` for every
        sample carrying a .gbk consensus, parsing each one inside a
        single ``ZipFile`` open.

        Failures (oversize member, decode error, bad GenBank) land in
        the dict as ``("[red]err[/red]", "—")`` so the table still
        gets a row per sample. Samples without a gbk member are
        skipped — the caller's `.get()` falls back to ``("—", "—")``.
        """
        import zipfile
        out: dict[str, tuple[str, str]] = {}
        if self._zip_path is None:
            return out
        try:
            zf = zipfile.ZipFile(str(self._zip_path), "r")
        except (zipfile.BadZipFile, OSError):
            _log.exception(
                "Sequencing: could not reopen zip for batch gbk parse"
            )
            return out
        try:
            cap = _PLASMIDSAURUS_MEMBER_MAX_BYTES
            for s in samples:
                gbk_member = s.get("gbk")
                if not gbk_member:
                    continue
                # Defense in depth — `_is_safe_zip_member_name` was
                # checked during parse, but skipping again here means
                # an in-process mutator of `_parsed_run` can't smuggle
                # a traversal name back in between parse and render.
                if not _is_safe_zip_member_name(gbk_member):
                    out[gbk_member] = ("[red]err[/red]", "—")
                    continue
                try:
                    info = _zf_get_member_info(zf, gbk_member)
                except KeyError:
                    out[gbk_member] = ("[red]err[/red]", "—")
                    continue
                if info.file_size > cap:
                    out[gbk_member] = ("[red]too big[/red]", "—")
                    continue
                try:
                    with zf.open(info, "r") as fh:
                        raw = fh.read(cap + 1)
                    if len(raw) > cap:
                        out[gbk_member] = ("[red]too big[/red]", "—")
                        continue
                    try:
                        txt = raw.decode("utf-8")
                    except UnicodeDecodeError:
                        txt = raw.decode("latin-1", errors="replace")
                    # Sweep #26: `cache=False` — batch parses across
                    # 50+ samples × multi-MB assemblies would absorb
                    # the entire batch into `_GB_PARSE_CACHE` (~250 MB
                    # in one click). One-shot reads here; no cache
                    # benefit on subsequent calls.
                    rec = _gb_text_to_record(txt, cache=False)
                    bp = f"{len(rec.seq):,}"
                    feats = str(
                        len([f for f in rec.features
                             if f.type != "source"])
                    )
                    out[gbk_member] = (bp, feats)
                except (ValueError, OSError, RuntimeError,
                        zipfile.BadZipFile):
                    _log.exception(
                        "Sequencing: gbk parse failed for %s",
                        gbk_member,
                    )
                    out[gbk_member] = ("[red]err[/red]", "—")
        finally:
            zf.close()
        return out

    def _populate_quality_tables(self, parsed: dict) -> None:
        """Fill the Quality sub-tab with parsed summary metrics +
        the run-level files block."""
        try:
            q = self.query_one(
                "#plasmidsaurus-quality-table", DataTable,
            )
        except NoMatches:
            q = None
        if q is not None:
            q.clear()
            for s in parsed.get("samples") or []:
                name = s.get("name") or s.get("base") or "?"
                parsed_s = _parse_plasmidsaurus_summary(
                    s.get("summary_text", "") or "",
                )
                def _fmt_pct(v):
                    return (
                        f"{v:.1f}%"
                        if isinstance(v, (int, float)) else "—"
                    )
                cov = s.get("perbase_coverage") or {}
                cov_mean_val = cov.get("mean")
                cov_min_val  = cov.get("min")
                n_pos        = cov.get("n_pos") or 0
                above        = cov.get("above_20x") or 0
                pct_20x = (
                    f"{(100 * above / n_pos):.1f}%"
                    if n_pos else "—"
                )
                q.add_row(
                    name,
                    _fmt_pct(parsed_s.get("kmer_moles_pct")),
                    _fmt_pct(parsed_s.get("kmer_mass_pct")),
                    _fmt_pct(parsed_s.get("contamination_pct")),
                    parsed_s.get("contamination_source") or "—",
                    (f"{cov_mean_val:.1f}×"
                      if isinstance(cov_mean_val, (int, float))
                      else "—"),
                    (str(int(cov_min_val))
                      if isinstance(cov_min_val, (int, float))
                      else "—"),
                    pct_20x,
                    key=name,
                )
        try:
            rf = self.query_one(
                "#plasmidsaurus-runfiles-table", DataTable,
            )
        except NoMatches:
            rf = None
        if rf is not None:
            rf.clear()
            for entry in parsed.get("run_files") or []:
                size = int(entry.get("size", 0))
                if size >= 1024 * 1024:
                    size_s = f"{size / (1024 * 1024):.2f} MB"
                elif size >= 1024:
                    size_s = f"{size / 1024:.1f} KB"
                else:
                    size_s = f"{size} B"
                rf.add_row(
                    entry.get("name", "?"),
                    size_s,
                    entry.get("category", "—"),
                    key=entry.get("name", ""),
                )

    @on(DataTable.RowSelected, "#align-members")
    def _on_member_selected(self, event: DataTable.RowSelected) -> None:
        """User clicked a sample row. Mark that sample's .gbk as the
        alignment query (read from the row key, which was set to the
        gbk member name in `_populate_samples_table`). Updates the
        Align tab's query indicator + enables the Align button."""
        try:
            row_key = (
                event.row_key.value if event.row_key is not None else ""
            )
        except AttributeError:
            row_key = ""
        # Rows for samples without a .gbk carry a NUL-anchored
        # synthetic key; refuse to advance the workflow (an empty
        # or synthetic key would crash `_extract_gbk_member`). NUL
        # makes the prefix non-collidable with real member names
        # (rejected by `_is_safe_zip_member_name`).
        if not row_key or row_key.startswith(self._NO_GBK_KEY_PREFIX):
            self._selected_member = None
            self._selected_order_num = None
            self._selected_gbk_basename = None
            try:
                self.query_one("#btn-align-go", Button).disabled = True
            except NoMatches:
                pass
            try:
                self.query_one(
                    "#plasmidsaurus-align-query", Static,
                ).update(
                    "[yellow]This sample has no .gbk consensus — "
                    "pick another row.[/yellow]"
                )
            except NoMatches:
                pass
            return
        self._selected_member = str(row_key)
        # Derive the 1-based order number (row index in the sorted
        # samples list) and the .gbk leaf filename (no extension).
        # `_parsed_run["samples"]` mirrors the table's natural-sort
        # order so the index here matches what the user sees.
        self._selected_order_num = None
        self._selected_gbk_basename = None
        samples = self._parsed_run.get("samples") or []
        for idx, s in enumerate(samples, start=1):
            if s.get("gbk") == self._selected_member:
                self._selected_order_num = idx
                break
        # INV-73 (2026-05-25): use `_display_label_for_gbk` so the
        # Plasmidsaurus run+order prefix is stripped and remaining
        # underscores become spaces — keeps the alignment-row label
        # free of TUI-unfriendly punctuation per user feedback.
        self._selected_gbk_basename = _display_label_for_gbk(
            self._selected_member,
        )
        try:
            self.query_one("#btn-align-go", Button).disabled = False
        except NoMatches:
            pass
        try:
            label_prefix = (
                f"#{self._selected_order_num} "
                if self._selected_order_num is not None else ""
            )
            display_basename = (
                self._selected_gbk_basename
                if self._selected_gbk_basename
                else self._selected_member
            )
            self.query_one(
                "#plasmidsaurus-align-query", Static,
            ).update(
                f"[b]Sample picked:[/b] {label_prefix}"
                f"{_esc_md(display_basename)}\n"
                f"[dim]Pick a target plasmid below and press "
                f"Align.[/dim]"
            )
        except NoMatches:
            pass
        try:
            self.query_one("#align-status", Static).update(
                f"[dim]Selected: {_esc_md(self._selected_member)}"
                f" — open the [b]3. Pick target + align[/b] tab "
                f"to run the pairwise alignment.[/dim]"
            )
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-align-go")
    def _go(self, _) -> None:
        if self._zip_path is None or not self._selected_member:
            return
        sel = self.query_one("#align-target", Select)
        target_id = sel.value
        # `_target_options` swaps to the NUL-anchored
        # `_EMPTY_LIBRARY_SENTINEL` when no library entries are
        # available; refuse to advance in that case. Empty-string
        # check belt-and-braces against a future Select API quirk.
        if (not target_id
                or target_id == self._EMPTY_LIBRARY_SENTINEL):
            self.query_one("#align-status", Static).update(
                "[red]Pick a target plasmid first.[/red]"
            )
            return
        # Read the .gbk text out of the zip and parse to a record.
        try:
            gbk_text = _extract_gbk_member(self._zip_path,
                                              self._selected_member)
            query_rec = _gb_text_to_record(gbk_text)
        except (ValueError, OSError, RuntimeError) as exc:
            _log.exception("PlasmidsaurusAlignModal: extract / parse failed")
            self.query_one("#align-status", Static).update(
                f"[red]{_esc_md(str(exc))}[/red]"
            )
            return
        # Resolve the target plasmid from the library.
        target_entry = _find_library_entry_by_id(
            str(target_id) if target_id else "",
        )
        if target_entry is None:
            self.query_one("#align-status", Static).update(
                "[red]Target plasmid not found in library.[/red]"
            )
            return
        try:
            target_rec = _gb_text_to_record(target_entry.get("gb_text", ""))
        except (ValueError, RuntimeError) as exc:
            _log.exception("PlasmidsaurusAlignModal: target parse failed")
            self.query_one("#align-status", Static).update(
                f"[red]Target parse failed: {_esc_md(str(exc))}[/red]"
            )
            return
        # Dispatch alignment to a worker — the C-loop dominates for
        # 100+ kbp sequences (1–2 s frozen UI on a 200 kbp x 200 kbp
        # pair, uncancellable per CLAUDE.md invariant 28). Pre-fix the
        # synchronous call here hitched the modal while the load
        # counter ticked; the worker captures it at entry so a later
        # plasmid swap discards the result rather than painting an
        # alignment for a record the canvas no longer shows.
        self.query_one("#align-status", Static).update(
            "[dim]Aligning… (may take a few seconds for big plasmids)[/dim]"
        )
        target_label = target_entry.get("name") or target_id
        # Carry the library entry's DISPLAY name onto the parsed record so
        # loading the target onto the canvas (`_apply_record` below) — and
        # any later Ctrl+S / the alignment flush — keeps the clean typed
        # name instead of the underscored GenBank LOCUS. gb_text only
        # round-trips the LOCUS, so a record parsed from it has no display
        # name unless we stamp it here ([INV-98] — never let the LOCUS
        # become the library name).
        if isinstance(target_label, str) and target_label.strip():
            try:
                target_rec._tui_display_name = target_label.strip()  # type: ignore[attr-defined]
            except Exception:
                _log.debug("plasmidsaurus align: display-name stamp failed")
        target_is_circular = (
            (target_rec.annotations or {}).get("topology", "").lower()
            == "circular"
        )
        # Build the display label: `<order> <gbk_basename>`. Falls back
        # to the raw zip member path if state is missing (defensive —
        # `_on_member_selected` always populates these alongside
        # `_selected_member`).
        if (self._selected_order_num is not None
                and self._selected_gbk_basename):
            display_label = (
                f"{self._selected_order_num} {self._selected_gbk_basename}"
            )
        else:
            display_label = self._selected_member
        self._align_worker(
            query_seq=str(query_rec.seq),
            target_seq=str(target_rec.seq),
            query_label=display_label,
            target_label=target_label,
            target_record=target_rec,
            target_is_circular=target_is_circular,
            entry_counter=getattr(self.app, "_record_load_counter", 0),
        )

    @work(thread=True, exclusive=True, group="plasmidsaurus_align")
    def _align_worker(self, *, query_seq: str, target_seq: str,
                       query_label: str, target_label: str,
                       target_record, target_is_circular: bool,
                       entry_counter: int) -> None:
        """Worker: run `_pairwise_align` off the UI thread, then load
        the target into the canvas and register the alignment as a
        blue overlay bar on its linear view. Inputs captured at entry;
        stale-load guard on the load counter (mirrors `_restr_scan_worker`).

        Circular-target rotation (GH #16, 2026-05-14): when the target
        is circular, the Plasmidsaurus virtual plasmid and the GenBank
        reference almost never share an origin. Pre-fix the global
        aligner pairs bp 1 of each, paying gaps to slide the smaller
        offset back into register — visibly broken vs. CommercialSaaS.
        Original fix rotated the *target*, but that put the alignment
        result in a rotated coordinate frame that no longer matched
        the canvas plasmid (which displays the library's original
        origin). Now we rotate the *query* instead: bp 0 of the
        rotated read aligns with bp 0 of the (unrotated) target, so
        `aligned_t` positions land in the canvas plasmid's native
        coordinate frame — the overlay bars sit at the right bp.

        Also captures `_alignments_generation` so a user who hits
        Clear Alignments while the C-loop ran doesn't see this stale
        result reappear on the overlay band when the worker lands.
        """
        gen_at_entry = getattr(self.app, "_alignments_generation", 0)
        try:
            # `_pick_best_rotation` tries plain first; only attempts
            # query-rot + target-rot when target is circular AND
            # plain alignment is poor (< 80% identity). The chosen
            # candidate's aligned_q/aligned_t are pre-shifted to the
            # ORIGINAL target frame when target-rotation wins, so the
            # caller can pass the unrotated `target_record` to
            # `_register_alignment` and the segments still land at
            # the right bp on the canvas.
            result = _pick_best_rotation(
                query_seq, target_seq,
                is_circular=target_is_circular,
                mode="global",
            )
        except ValueError as exc:
            # PEP 3110 clears `exc` once the except scope exits, and
            # `_err` runs later on the UI thread via call_from_thread.
            # Snapshot the message into a closure-safe local.
            err_msg = _esc_md(str(exc))
            def _err():
                try:
                    self.query_one("#align-status", Static).update(
                        f"[red]Alignment failed: {err_msg}[/red]"
                    )
                except NoMatches:
                    pass
            self.app.call_from_thread(_err)
            return
        except Exception as exc:
            # INV-73 (2026-05-25): add sequence-length context so a
            # "alignment failed" bug report tells us whether to look
            # at the C-loop, the input normalisation, or the wrapper.
            _log.exception(
                "PlasmidsaurusAlignModal worker failed: "
                "query_len=%d target_len=%d query_label=%r "
                "target_label=%r circular=%r",
                len(query_seq) if query_seq else -1,
                len(target_seq) if target_seq else -1,
                query_label, target_label, target_is_circular,
            )
            err_msg = _esc_md(str(exc))
            def _err():
                try:
                    self.query_one("#align-status", Static).update(
                        f"[red]Alignment failed: {err_msg}[/red]"
                    )
                except NoMatches:
                    pass
            self.app.call_from_thread(_err)
            return

        def _show():
            # Stale-load guard: discard if user swapped plasmids while
            # the C-loop ran. Pre-fix the worker's push_screen happily
            # painted an alignment for the OLD record. NOTE: we may
            # ourselves swap the canvas to the picked target below,
            # which would bump the counter — so the check has to
            # happen FIRST, before our own load.
            if (getattr(self.app, "_record_load_counter", 0)
                    != entry_counter):
                return
            # Cancel guard: the C-loop can't be cancelled mid-flight,
            # so if the user clicked Cancel while it ran, the result
            # is still here. Don't surface it — registering an alignment
            # for a modal the user has dismissed would surprise them.
            if self._cancelled:
                return
            # Clear-alignments guard: if the user hit Alt+Shift+A while
            # the worker ran, the generation counter advanced; resurrect-
            # ing this result would surprise them.
            if (getattr(self.app, "_alignments_generation", 0)
                    != gen_at_entry):
                return
            # Mirror the Alt+A flow: the picked library plasmid plays
            # the role of the canvas reference, and the plasmidsaurus
            # virtual plasmid (query) lands as an overlay bar on its
            # linear view. If the target isn't already loaded, swap
            # to it now so the alignment + the persisted-alignment
            # flush both land on the right library entry.
            current = getattr(self.app, "_current_record", None)
            cur_id = getattr(current, "id", None) if current else None
            tgt_id = getattr(target_record, "id", None)
            if tgt_id and cur_id != tgt_id:
                try:
                    self.app._apply_record(target_record)  # type: ignore[attr-defined]
                except Exception:
                    _log.exception(
                        "Plasmidsaurus: loading target into canvas "
                        "failed for %r", tgt_id,
                    )
                    return
            # Register on the linear-map overlay band instead of pushing
            # AlignmentScreen — clicking the lane jumps the seq panel to
            # that region (centered + highlighted); the full-screen
            # detail viewer is kept for base-level review on Alt+L → Enter.
            # `target_record` is the library's original (unrotated)
            # record, matching what the canvas now displays; segments
            # come out in that frame because the query was rotated to
            # match it, not the other way around.
            try:
                registered_entry = self.app._register_alignment(  # type: ignore[attr-defined]
                    name=query_label,
                    query_label=query_label,
                    target_label=target_label,
                    target_record=target_record,
                    result=result,
                )
                # Persist the read alignment onto the target's library
                # entry so re-loading restores the band. Tagged
                # source="sequencing" so the manager modal can
                # mass-delete a sequencing batch later. The canvas is
                # now the target (loaded above) so the flush lands on
                # the right entry. Use the register return value
                # rather than `_alignments[-1]` so a register-refused
                # case (malformed strings) doesn't tag the previous
                # entry.
                if registered_entry is not None:
                    registered_entry["_stored_source"] = "sequencing"
                flush = getattr(
                    self.app, "_flush_active_alignments", None,
                )
                if callable(flush):
                    flush()
            except Exception:
                _log.exception(
                    "PlasmidsaurusAlignModal: _register_alignment failed"
                )
            # Sequencing-aligned targets default to linear view on every
            # subsequent reload. `_register_alignment` already pins
            # linear on first overlay; persist explicitly here so the
            # preference sticks even when the target was already linear
            # (no auto-switch path) or when the user later clears the
            # overlay band.
            try:
                persist = getattr(
                    self.app, "_persist_map_mode_for_active", None,
                )
                if callable(persist):
                    persist("linear")
            except Exception:
                _log.exception(
                    "PlasmidsaurusAlignModal: persist map_mode failed"
                )
            ident_total = result.get("identity_pct", 0.0)
            ident_ungap = result.get("ungapped_identity_pct", ident_total)
            # Coverage metrics: how much of the target the read
            # actually aligned to. Pre-fix the toast surfaced only
            # `ungapped_identity_pct` ("99.9% identity (aligned
            # region)"), which read as "the alignment is nearly
            # perfect" — but for length-mismatched plasmids the bulk
            # of the target was unaligned (gray on the overlay band)
            # and the user couldn't tell from the toast why the band
            # had so much gray. New toast leads with aligned-bp /
            # target-bp + coverage% + overall identity (the
            # gap-inclusive metric that actually predicts how much
            # blue/red the band shows) and only mentions ungapped
            # identity as a parenthetical for the matched region.
            n_match    = int(result.get("n_matches", 0) or 0)
            n_mismatch = int(result.get("n_mismatches", 0) or 0)
            aligned_bp = n_match + n_mismatch
            tgt_bp = (
                int(result.get("t_len", 0) or 0)
                or len(str(target_record.seq))
            )
            # INV-73 (2026-05-25): coverage clamp routed through
            # `_coverage_pct_from_result` so the rule lives in one
            # place (mirrors the VerificationReportModal site).
            coverage_pct = _coverage_pct_from_result(result, tgt_bp)
            picked = result.get("picked_rotation", "none")
            rot_note = ""
            if picked == "query":
                rot_note = (
                    f" · read rotated by "
                    f"{int(result.get('query_rotation') or 0):,} bp"
                )
            elif picked == "target":
                rot_note = (
                    f" · target frame shifted by "
                    f"{int(result.get('target_rotation') or 0):,} bp"
                )
            try:
                self.app.notify(
                    f"Aligned {query_label} → {target_label} · "
                    f"{aligned_bp:,}/{tgt_bp:,} bp "
                    f"({coverage_pct:.0f}% coverage) at "
                    f"{_format_identity_pct(ident_total)} identity "
                    f"({_format_identity_pct(ident_ungap)} in matched region)"
                    f"{rot_note} · "
                    f"click read on map to inspect.",
                    title="Alignment added",
                    severity="information", timeout=8,
                )
            except Exception:
                pass
            # Keep the screen OPEN after a per-sample align so the user can
            # process the next sample without reopening + re-picking the zip
            # (matching the bulk-align + Sanger-add flows on this same screen).
            # The overlay band + the target's library entry are already persisted
            # above, so staying open re-aligns nothing; `action_cancel` (Esc /
            # Close) stays the explicit exit.
            if self.is_mounted:
                try:
                    self.query_one("#align-status", Static).update(
                        f"[green]✓ aligned {_esc_md(query_label)} → "
                        f"{_esc_md(target_label)}[/green][dim] · pick the next "
                        f"sample and Align again, or Close when done.[/dim]"
                    )
                except NoMatches:
                    pass
        self.app.call_from_thread(_show)

    @on(Button.Pressed, "#btn-view-report")
    def _view_report(self, _) -> None:
        """Open the cross-library verification report. Click a row in
        the report to load that plasmid + scroll the cursor to its
        first stored variant. Dismisses the Sequencing screen so the
        user lands on the canvas with the picked plasmid loaded."""
        def _on_picked(result):
            if not result or not isinstance(result, tuple):
                return
            if result[0] != "open":
                return
            _kind, entry_id, pos = result
            entry = _find_library_entry_by_id(entry_id or "")
            if entry is None:
                try:
                    self.app.notify(
                        "Picked plasmid not found in library — was "
                        "it deleted while the report was open?",
                        severity="warning", timeout=5,
                    )
                except Exception:
                    pass
                return
            # Load the picked plasmid into the canvas via the same
            # path LibraryPanel uses (`_apply_record` + display-name
            # stash + map-mode stash + alignment hydrate).
            self._jump_to_library_entry_at_pos(entry, int(pos or 0))

        self.app.push_screen(
            VerificationReportModal(only_with_alignments=True),
            callback=_on_picked,
        )

    def _jump_to_library_entry_at_pos(
        self, entry: dict, target_bp: int,
    ) -> None:
        """Load the library entry into the canvas and (after the
        load completes) scroll the seq-panel cursor to ``target_bp``.
        Called from the verification report's "Open in canvas"
        action — the user wants to inspect the first variant of the
        picked alignment, so dropping them on bp 0 is unhelpful.

        Dismisses the SequencingScreen as a side effect so the
        canvas is fully visible after the load.
        """
        gb_text = entry.get("gb_text", "")
        if not gb_text:
            try:
                self.app.notify(
                    "Library entry has no embedded sequence — can't "
                    "open in canvas.", severity="warning", timeout=5,
                )
            except Exception:
                pass
            return
        try:
            record = _gb_text_to_record(gb_text)
        except Exception as exc:
            _log.exception(
                "VerificationReport: gb parse failed for %r",
                entry.get("id"),
            )
            try:
                self.app.notify(
                    f"Failed to load plasmid: {exc}",
                    severity="error", timeout=6,
                )
            except Exception:
                pass
            return
        display = entry.get("name")
        if isinstance(display, str) and display.strip():
            try:
                record._tui_display_name = display.strip()
            except Exception:
                pass
        try:
            self.app._apply_record(record)  # type: ignore[attr-defined]
        except Exception:
            _log.exception(
                "VerificationReport: _apply_record failed for %r",
                entry.get("id"),
            )
            return
        # Capture the record-load generation right after our load so a
        # fast navigation (agent API or the user) to ANOTHER plasmid
        # inside the 0.2 s timer window can't park the cursor on the
        # wrong molecule. `_apply_record` bumps `_record_load_counter`;
        # if it shifts before `_scroll` fires, abort the jump. (The
        # align workers use this same guard; `focus_span` already clamps
        # out-of-range, so this is correctness-of-target, not a crash.)
        _jump_counter = getattr(self.app, "_record_load_counter", None)
        # Schedule a cursor jump after the screen-pop + canvas paint
        # settle. `set_timer` on the App side hops to the next tick;
        # by then `_current_record` is the loaded entry and the
        # seq panel is mounted.
        def _scroll():
            try:
                if (_jump_counter is not None
                        and getattr(self.app, "_record_load_counter", None)
                            != _jump_counter):
                    return                      # canvas changed under us
                sp = self.app.query_one("#seq-panel", SequencePanel)
                # Shared jump-to-bp primitive (added 2026-06-01).
                # center=False preserves this caller's original
                # ensure-visible behaviour; select=False parks the
                # cursor on the first variant without selecting a span.
                sp.focus_span(target_bp, target_bp + 1,
                              center=False, select=False)
            except (NoMatches, AttributeError):
                pass
            except Exception:
                _log.exception(
                    "VerificationReport: cursor jump failed",
                )
        try:
            self.app.set_timer(0.2, _scroll)
        except Exception:
            _log.exception(
                "VerificationReport: set_timer for cursor jump failed",
            )
        if self.is_mounted:
            self.dismiss(None)

    @on(Button.Pressed, "#btn-bulk-align")
    def _bulk_align(self, _) -> None:
        """Dispatch the bulk-align flow. INV-74 (2026-05-25): the
        matcher runs on a worker thread so a large library (DemoColl ≈ 90
        entries × 18 kb plasmids = ~5–30 s of k-mer build) doesn't
        freeze the UI before the confirm modal opens. Pre-fix the
        click-handler ran `_match_samples_to_library` synchronously
        on the UI thread and looked like a complete hang.
        """
        samples = (self._parsed_run or {}).get("samples") or []
        if not samples:
            try:
                self.app.notify(
                    "No samples loaded — pick a Plasmidsaurus zip "
                    "on the [b]1. Pick zip[/b] tab first.",
                    severity="warning", timeout=4,
                )
            except Exception:
                pass
            return
        try:
            library = list(_iter_library_readonly())
        except Exception:
            _log.exception("BulkAlign: _iter_library_readonly failed")
            library = []
        if not library:
            try:
                self.app.notify(
                    "Active library is empty — add at least one "
                    "plasmid before bulk-aligning.",
                    severity="warning", timeout=4,
                )
            except Exception:
                pass
            return
        # Disable the button + show "matching..." status immediately so
        # the user sees the click registered. Re-enable in the worker's
        # completion callback (both success + failure paths).
        try:
            btn = self.query_one("#btn-bulk-align", Button)
            btn.disabled = True
        except NoMatches:
            pass
        try:
            from textual.widgets import ProgressBar
            txt = self.query_one("#bulk-align-progress", Static)
            bar = self.query_one("#bulk-align-bar", ProgressBar)
            txt.add_class("-active")
            bar.add_class("-active")
            txt.update(
                f"[b]Matching {len(samples)} sample(s) to {len(library)} "
                f"library entr{'y' if len(library) == 1 else 'ies'} "
                f"by name + k-mer…[/b]"
            )
            # Indeterminate-style: total=None makes Textual render a
            # rolling animation rather than a fixed-progress bar — fits
            # the "we don't know how long this takes" matcher phase.
            bar.update(total=None)
        except (NoMatches, AttributeError):
            pass
        self._match_samples_worker(samples, library)

    @work(thread=True, exclusive=True, group="plasmidsaurus_matcher")
    def _match_samples_worker(
        self, samples: "list[dict]", library: "list[dict]",
    ) -> None:
        """INV-74 (2026-05-25): off-thread matcher. Returns to the UI
        thread to push the confirm modal (and re-enable the Bulk-align
        button). All UI mutations route through `call_from_thread`."""
        try:
            matches = _match_samples_to_library(
                samples, library,
                sequence_fallback=True,
                extract_gbk_fn=_extract_gbk_member,
                zip_path=self._zip_path,
            )
        except Exception:
            _log.exception(
                "BulkAlign: matcher raised (n_samples=%d, n_library=%d)",
                len(samples), len(library),
            )

            def _err():
                try:
                    self.app.notify(
                        "Bulk-align matcher failed — see splicecraft log.",
                        severity="error", timeout=6,
                    )
                except Exception:
                    pass
                self._reset_bulk_align_button()
            self.app.call_from_thread(_err)
            return

        # 2026-05-31: align each target-bearing sample NOW, on this same
        # button-press worker (with progress), so the confirm modal opens
        # with real Identity/Mism/Gaps already shown AND the commit can
        # reuse the result. Pre-fix the modal re-aligned on open (slow,
        # felt like a hang) and the commit aligned a THIRD time — the
        # same ~18 kb pairwise twice over. Now it runs exactly once here.
        self._compute_bulk_quality(matches)

        # If this worker was cancelled mid-prealign (an exclusive restart
        # from a second Bulk-align click, or the screen unmounted), do
        # NOT push its now-stale confirm modal — otherwise a double-click
        # stacks two modals over the same run.
        from textual.worker import get_current_worker
        if get_current_worker().is_cancelled:
            return

        def _ok():
            self._reset_bulk_align_button()
            self._push_bulk_confirm_modal(matches)
        self.app.call_from_thread(_ok)

    def _compute_bulk_quality(self, matches: "list[dict]") -> None:
        """Align each target-bearing sample against its proposed match,
        on the matcher worker thread, stashing the display summary
        (`_aln` = ``{ident, mism, gaps}``) AND the full
        `_pick_best_rotation` result (`_aln_result`, reused verbatim by
        `_bulk_align_worker` so the commit never re-aligns) on each match
        dict. Progress ticks the bar the matcher phase already raised.
        Rows with no target / no consensus member get ``_aln = False``
        (rendered "?"). Runs the SAME `_pick_best_rotation(...,
        canvas_axis="target")` call the commit used to run, so the cached
        result is byte-for-byte what the commit would have computed.

        Polls `get_current_worker().is_cancelled` each iteration so a
        long run (every sample is a ~18 kb pairwise) stops promptly when
        the user re-launches bulk-align or leaves the screen, instead of
        grinding through every remaining sample first."""
        from textual.worker import get_current_worker
        worker = get_current_worker()
        n = len(matches)
        for i, m in enumerate(matches, 1):
            if worker.is_cancelled:
                return
            target_entry = m.get("target_entry") or {}
            tgt_gb = target_entry.get("gb_text") or ""
            sample = m.get("sample") or {}
            gbk_member = sample.get("gbk")
            if not tgt_gb or not gbk_member or not self._zip_path:
                m["_aln"] = False
                continue
            sample_name = sample.get("name") or sample.get("base") or "?"

            def _tick(i=i, nm=sample_name):
                try:
                    from textual.widgets import ProgressBar
                    txt = self.query_one("#bulk-align-progress", Static)
                    bar = self.query_one("#bulk-align-bar", ProgressBar)
                    txt.update(
                        f"[b]Aligning {i}/{n}:[/b] {nm}…"
                    )
                    bar.update(total=max(1, n), progress=i - 1)
                except (NoMatches, AttributeError):
                    pass
            self.app.call_from_thread(_tick)
            try:
                query_rec = _gb_text_to_record(
                    _extract_gbk_member(self._zip_path, gbk_member))
                target_rec = _gb_text_to_record(tgt_gb)
                is_circular = (
                    (target_rec.annotations or {})
                    .get("topology", "").lower() == "circular"
                )
                result = _pick_best_rotation(
                    str(query_rec.seq), str(target_rec.seq),
                    is_circular=is_circular,
                    mode="global", canvas_axis="target",
                )
                m["_aln"] = {
                    "ident": float(result.get("identity_pct") or 0.0),
                    "mism":  int(result.get("n_mismatches") or 0),
                    # Indel EVENTS (gap runs), matching the Verification
                    # Report's "Indels" — not gapped bp.
                    "gaps":  _alignment_indel_events(result),
                }
                m["_aln_result"] = result
            except Exception:
                _log.exception(
                    "BulkAlign: quality pre-align failed for %r",
                    gbk_member,
                )
                m["_aln"] = False

    def _reset_bulk_align_button(self) -> None:
        """Re-enable the Bulk-align button + hide the progress
        widgets. Called from the matcher worker's completion path."""
        try:
            btn = self.query_one("#btn-bulk-align", Button)
            btn.disabled = False
        except NoMatches:
            pass
        try:
            from textual.widgets import ProgressBar
            txt = self.query_one("#bulk-align-progress", Static)
            bar = self.query_one("#bulk-align-bar", ProgressBar)
            txt.remove_class("-active")
            bar.remove_class("-active")
            txt.update("")
        except (NoMatches, AttributeError):
            pass

    def _push_bulk_confirm_modal(self, matches: "list[dict]") -> None:
        """Open BulkAlignConfirmModal + wire its callback to the
        worker. Extracted from `_bulk_align` so the matcher worker
        can defer back to the UI thread for the modal push."""
        def _on_confirmed(committed) -> None:
            if not committed:
                return
            n_align = sum(1 for m in committed if m.get("action") == "align")
            n_add   = sum(1 for m in committed if m.get("action") == "add")
            try:
                self.app.notify(
                    f"Bulk run: aligning {n_align}, adding {n_add} as "
                    f"new library entries…",
                    timeout=4,
                )
            except Exception:
                pass
            # INV-74 (2026-05-25): paint the progress widgets BEFORE the
            # worker spawns. User-reported symptom: "after pressing Run,
            # thread hangs before toast / progress shows up". The hang
            # is the window between modal dismiss and the worker's
            # first `call_from_thread(_progress_show)` — for the first
            # sample's C-loop align, that can be 1–30 s of silence.
            # Doing the show here (synchronously on the UI thread,
            # which is where _on_confirmed runs) gives the user an
            # immediate "Preparing batch…" cue.
            try:
                from textual.widgets import ProgressBar
                txt = self.query_one(
                    "#bulk-align-progress", Static,
                )
                bar = self.query_one(
                    "#bulk-align-bar", ProgressBar,
                )
                txt.add_class("-active")
                bar.add_class("-active")
                n_total = len(committed)
                txt.update(
                    f"[b]Preparing batch:[/b] {n_align} alignment(s), "
                    f"{n_add} add-as-new… ({n_total} total)"
                )
                bar.update(total=max(1, n_total), progress=0)
            except (NoMatches, AttributeError):
                pass
            entry_counter = getattr(self.app, "_record_load_counter", 0)
            self._bulk_align_worker(committed, entry_counter)
        self.app.push_screen(
            BulkAlignConfirmModal(matches),
            callback=_on_confirmed,
        )

    @work(thread=True, exclusive=True, group="plasmidsaurus_bulk_align")
    def _bulk_align_worker(self, committed: "list[dict]",
                            entry_counter: int) -> None:
        """Batch worker: walk the user-confirmed action list and
        execute each row. Aligns matched samples (routes through
        `_pick_best_rotation` like the per-sample worker); adds
        unmatched samples as new library entries with provenance
        metadata (`source: plasmidsaurus:<run_id>:<sample_name>`).

        Stale-load guard captures `entry_counter` at modal-confirm
        time; if the user swaps the active plasmid mid-batch the
        worker terminates (the in-flight registrations would land
        on the wrong canvas record).
        """
        run_id = (self._parsed_run or {}).get("run_id") or ""
        zip_path = self._zip_path
        if zip_path is None:
            self.app.call_from_thread(
                self.app.notify,
                "Bulk-align cancelled — zip path is no longer available.",
                severity="warning", timeout=4,
            )
            return
        # INV-74 (2026-05-25): show + reset the progress widgets. Pre-fix
        # the worker ran silently for 30s–5min depending on sample count
        # × plasmid size and looked like a UI hang. Now the user sees
        # "Aligning N/M: <sample> → <target>…" per iteration plus a
        # filling progress bar.
        n_total = len(committed)

        def _progress_show():
            try:
                from textual.widgets import ProgressBar
                bar = self.query_one("#bulk-align-bar", ProgressBar)
                txt = self.query_one("#bulk-align-progress", Static)
                bar.add_class("-active")
                txt.add_class("-active")
                # Reset the bar to 0/total so a re-run after a previous
                # batch starts clean. `update(total=N, progress=0)` is
                # the documented one-shot reset for Textual ProgressBar.
                bar.update(total=max(1, n_total), progress=0)
                txt.update(
                    f"[b]Bulk-align starting[/b] · {n_total} sample(s)…"
                )
            except (NoMatches, AttributeError):
                pass
        self.app.call_from_thread(_progress_show)
        n_aligned = 0
        n_failed = 0
        # INV-75 (2026-05-25): batch-flush accumulators. All
        # successful alignments + add-as-new entries are collected
        # in memory and written in ONE library save at end of loop.
        # `pending_alignments[target_id]` is the list of stored-
        # alignment dicts to append to that target's `alignments`
        # field. `pending_adds` is the list of new library entries
        # to append wholesale. See INV-75 in docs/invariants.md for
        # the perf rationale (N saves × 1-2 s each → 1 save).
        pending_alignments: "dict[str, list[dict]]" = {}
        pending_adds: "list[dict]" = []
        # INV-72 (2026-05-25): track add-as-new save successes /
        # failures separately so the summary toast doesn't claim N
        # entries were added when disk-full / permission-denied
        # silently dropped some on the floor. `add_counters["ok"]` is
        # the source of truth for "actually persisted"; the cancel /
        # summary readouts read it. call_from_thread(_add) is
        # synchronous so the counter is current at every iteration
        # boundary.
        add_counters = {"ok": 0, "err": 0}
        # INV-73 (2026-05-25): track the load counter we EXPECT the
        # app to be at. Bulk-align's `_register` callback intentionally
        # swaps the canvas via `_apply_record(target_rec)` (each sample
        # may target a different library entry), which bumps
        # `_record_load_counter`. Pre-fix the guard treated those
        # intentional swaps as a stale load and aborted the batch
        # after the FIRST sample — so the user saw only ONE plasmid
        # get its alignment + status change applied, even though they
        # confirmed N rows in the modal. Now we absorb each
        # _register-driven swap into `expected_counter`; an
        # *external* swap (user clicks another plasmid mid-batch)
        # advances the counter past expected and triggers the abort.
        expected_counter = entry_counter
        for m in committed:
            if (getattr(self.app, "_record_load_counter", 0)
                    != expected_counter):
                self.app.call_from_thread(
                    self.app.notify,
                    f"Bulk-align cancelled — active plasmid changed "
                    f"(aligned {n_aligned}, added {add_counters['ok']}, "
                    f"add-failed {add_counters['err']}, "
                    f"failed {n_failed} so far).",
                    severity="warning", timeout=6,
                )
                return
            sample = m.get("sample") or {}
            gbk_member = sample.get("gbk")
            sample_name = (sample.get("name") or sample.get("base")
                           or "?")
            # INV-74 (2026-05-25): per-iteration progress update so
            # the user sees "Aligning 3/10: DEMO34 → DEMO_38…" and the
            # bar fills. Hidden-by-default class is removed up front
            # in `_progress_show`. Defensive — if the widget isn't
            # mounted (raced screen close), we skip rather than crash.
            i_one_based = n_aligned + n_failed + add_counters["ok"] \
                          + add_counters["err"] + 1
            target_entry_pre = m.get("target_entry") or {}
            tgt_name_pre = (
                target_entry_pre.get("name")
                or target_entry_pre.get("id") or "?"
            )
            action_pre = m.get("action") or "?"
            verb = (
                "Aligning" if action_pre == "align"
                else "Adding" if action_pre == "add"
                else "Skipping"
            )
            disp_sample = _display_label_for_gbk(
                gbk_member or sample_name,
            ) or sample_name
            progress_msg = (
                f"[b]{verb} {i_one_based}/{n_total}:[/b] "
                f"{disp_sample}"
                + (f" → {tgt_name_pre}" if action_pre == "align" else "")
                + "…"
            )

            def _tick(msg=progress_msg, i=i_one_based):
                try:
                    from textual.widgets import ProgressBar
                    txt = self.query_one(
                        "#bulk-align-progress", Static,
                    )
                    bar = self.query_one(
                        "#bulk-align-bar", ProgressBar,
                    )
                    txt.update(msg)
                    bar.update(total=max(1, n_total), progress=i - 1)
                except (NoMatches, AttributeError):
                    pass
            self.app.call_from_thread(_tick)
            if not gbk_member:
                # INV-72 (2026-05-25): pre-fix this skip was silent —
                # a Plasmidsaurus zip with a malformed manifest would
                # report "failed N" in the summary with no clue why.
                # Log so the diagnostic bundle captures the cause.
                _log.warning(
                    "BulkAlign: skipping sample %r — no .gbk member "
                    "field (malformed manifest or missing consensus)",
                    sample_name,
                )
                n_failed += 1
                continue
            # 2026-05-31 (optimisation): only extract + parse the read's
            # ~38 KB consensus when we actually need its sequence — to
            # align it (no cached result) or to add it as a new entry.
            # When the matcher-phase `_compute_bulk_quality` already
            # produced the alignment (`_aln_result`), the commit reuses it
            # verbatim and never re-touches the GenBank.
            action = m.get("action")
            cached = m.get("_aln_result")
            align_reuse = (
                action == "align"
                and isinstance(cached, dict)
                and bool(cached.get("aligned_q"))
                and bool(cached.get("aligned_t"))
            )
            query_rec = None
            if not align_reuse:
                try:
                    query_rec = _gb_text_to_record(
                        _extract_gbk_member(zip_path, gbk_member))
                except Exception:
                    _log.exception(
                        "BulkAlign: extract/parse failed for %r",
                        gbk_member,
                    )
                    n_failed += 1
                    continue
            if action == "align":
                target_entry = m.get("target_entry") or {}
                tgt_gb = target_entry.get("gb_text", "")
                if not tgt_gb:
                    n_failed += 1
                    continue
                try:
                    target_rec = _gb_text_to_record(tgt_gb)
                except Exception:
                    _log.exception(
                        "BulkAlign: target parse failed for %r",
                        target_entry.get("id"),
                    )
                    n_failed += 1
                    continue
                target_is_circular = (
                    (target_rec.annotations or {}).get("topology", "")
                    .lower() == "circular"
                )
                # Reuse the matcher-phase alignment (cached as
                # `_aln_result`) so the same ~18 kb pairwise isn't run
                # twice. Fall back to a fresh align only when the cache is
                # missing (pre-align failed, or a row reached "align" by a
                # path that skipped the pre-pass).
                if align_reuse:
                    result = cached
                elif query_rec is None:
                    # Unreachable (not align_reuse ⇒ query_rec extracted
                    # above or the row already `continue`d) — narrows the
                    # Optional for the type-checker + a belt-and-braces
                    # guard against a future refactor.
                    n_failed += 1
                    continue
                else:
                    try:
                        result = _pick_best_rotation(
                            str(query_rec.seq), str(target_rec.seq),
                            is_circular=target_is_circular,
                            mode="global", canvas_axis="target",
                        )
                    except Exception:
                        _log.exception(
                            "BulkAlign: alignment failed for %r vs %r",
                            gbk_member, target_entry.get("id"),
                        )
                        n_failed += 1
                        continue
                # Pre-compute the bulk-align display label off the UI
                # thread: `<order_num> <basename_no_ext>` matches the
                # per-sample flow.
                idx_1based = 0
                for i, s in enumerate((self._parsed_run or {})
                                       .get("samples") or [], 1):
                    if s.get("gbk") == gbk_member:
                        idx_1based = i
                        break
                # INV-73 (2026-05-25): strip Plasmidsaurus prefix +
                # convert underscores to spaces so the alignment-row
                # label is TUI-friendly (per user request).
                basename = _display_label_for_gbk(gbk_member)
                display_label = (
                    f"{idx_1based} {basename}" if idx_1based
                    else basename
                )
                target_label = (
                    target_entry.get("name")
                    or target_entry.get("id") or "?"
                )
                target_id = target_entry.get("id")

                # INV-75 (2026-05-25): accumulate the stored alignment
                # dict in `pending_alignments` keyed by target_id. The
                # batch commit at end-of-loop writes ALL targets in
                # ONE library save — pre-fix each successful align
                # triggered a per-target `_flush_active_alignments`
                # which loaded the cached library, modified one
                # entry, and wrote 156 MB to disk via the collection
                # mirror. For a 10-sample bulk-align that's ~10-20 s
                # of wasted save time. Also drops the canvas-swap
                # (`_apply_record`) per sample — bulk-align's user
                # value is "make these alignments stick on the right
                # library entries", not "flash through every target
                # in 5 seconds". The canvas stays on the user's
                # original plasmid; alignments materialise at end.
                tgt_seq = str(target_rec.seq)
                stored_align = {
                    "id":              _uuid.uuid4().hex,
                    "label":           display_label,
                    "query_label":     display_label,
                    "target_label":    target_label,
                    "target_id":       target_id or "",
                    "target_gb_text":  tgt_gb,
                    "target_seq_hash": _alignment_target_hash(tgt_seq),
                    "axis":            "target",
                    "result":          result,
                    "visible":         True,
                    "added":           _date.today().isoformat(),
                    "source":          "sequencing",
                }
                if target_id:
                    pending_alignments.setdefault(
                        target_id, [],
                    ).append(stored_align)
                n_aligned += 1
            elif action == "add":
                # Build the new-entry dict (no save here — accumulated
                # for batch commit). Counters bumped in the commit
                # step so failures bubble correctly.
                if query_rec is None:
                    # Unreachable for "add" (align_reuse is align-only, so
                    # the read was extracted above) — narrows the Optional
                    # for the type-checker and guards a future refactor.
                    n_failed += 1
                    continue
                try:
                    gb_text_q = _record_to_gb_text(query_rec)
                    display_name = (
                        sample_name or query_rec.name
                        or query_rec.id or "plasmid"
                    ).strip()
                    display_name = "".join(
                        c if c.isprintable() else "_"
                        for c in display_name
                    )[:_BULK_IMPORT_MAX_NAME_LEN]
                    new_entry = {
                        "name":    display_name,
                        "id":      str(query_rec.id or display_name).strip(),
                        "size":    len(query_rec.seq),
                        "n_feats": len([
                            f for f in query_rec.features
                            if f.type != "source"
                        ]),
                        "source":  (f"plasmidsaurus:{run_id}:{sample_name}"
                                    if run_id
                                    else f"plasmidsaurus:{sample_name}"),
                        "added":   _date.today().isoformat(),
                        "gb_text": gb_text_q,
                        "status":  "",
                    }
                    pending_adds.append(new_entry)
                except (OSError, ValueError, RuntimeError):
                    _log.exception(
                        "BulkAlign: add-as-new build failed for %r",
                        gbk_member,
                    )
                    add_counters["err"] += 1
            else:
                # Unknown action — skip.
                continue

        # INV-75 (2026-05-25): batch commit. One library load + one
        # save covers every successful alignment + every add-as-new
        # entry. Runs on the UI thread (via call_from_thread) so the
        # cache write + LibraryPanel refresh stay consistent. Holds
        # `_cache_lock` for the full RMW per INV-73.
        def _commit_batch(
            pa=pending_alignments, padds=pending_adds,
            counters=add_counters,
        ):
            try:
                with _cache_lock:
                    entries = _load_library()
                    id_to_idx = {
                        e.get("id"): i
                        for i, e in enumerate(entries)
                        if isinstance(e, dict) and e.get("id")
                    }
                    touched_target_ids: "set[str]" = set()
                    # Apply pending alignments: append to each target
                    # entry's `alignments` list. Auto-tag SEQUENCING
                    # if the target's status was empty, and set
                    # map_mode=linear (alignment overlay needs the
                    # linear view per INV-67).
                    for tid, aligns in pa.items():
                        idx = id_to_idx.get(tid)
                        if idx is None:
                            # Target was deleted between matcher and
                            # commit — drop the alignment, log it.
                            _log.warning(
                                "BulkAlign: target %r vanished mid-"
                                "batch; dropping %d alignment(s)",
                                tid, len(aligns),
                            )
                            continue
                        existing = list(
                            entries[idx].get("alignments") or [],
                        )
                        existing.extend(aligns)
                        entries[idx]["alignments"] = existing
                        if not _sanitize_plasmid_status(
                            entries[idx].get("status"),
                        ):
                            entries[idx]["status"] = "SEQUENCING"
                        entries[idx]["map_mode"] = "linear"
                        touched_target_ids.add(tid)
                    # Apply pending adds: append with id-collision
                    # disambiguation against the post-merge id space.
                    seen_ids = {
                        e.get("id") for e in entries
                        if isinstance(e, dict)
                    }
                    added_ids: "list[str]" = []
                    for new_entry in padds:
                        try:
                            base_id = new_entry["id"]
                            n = 1
                            while new_entry["id"] in seen_ids:
                                n += 1
                                new_entry["id"] = f"{base_id}_{n}"
                            seen_ids.add(new_entry["id"])
                            entries.append(new_entry)
                            added_ids.append(new_entry["id"])
                            counters["ok"] += 1
                        except (KeyError, TypeError):
                            _log.exception(
                                "BulkAlign: add-as-new commit failed "
                                "for entry %r",
                                new_entry.get("name", "?"),
                            )
                            counters["err"] += 1
                    if not touched_target_ids and not added_ids:
                        return  # nothing to save
                    _save_library(entries, async_sync=True)
            except (OSError, RuntimeError) as exc:
                _log.exception(
                    "BulkAlign: batch commit failed (n_targets=%d, "
                    "n_adds=%d)",
                    len(pa), len(padds),
                )
                _notify_save_failure(
                    self.app, "Plasmid library", exc,
                )
                counters["err"] += len(padds)
                return
            # Refresh LibraryPanel for every touched entry so the
            # Seq + Status cells reflect the new alignments without
            # a full repopulate.
            try:
                lib = self.app.query_one("#library", LibraryPanel)
                for tid in touched_target_ids:
                    lib.refresh_seq_cell(tid)
                    lib.refresh_status_cell(tid)
                if added_ids:
                    # Switch to plasmids view + repopulate so the new
                    # entries show up. (Adds aren't a single-cell
                    # update; the row didn't exist before.)
                    lib._view_mode = "plasmids"
                    lib._apply_view_mode()
                    lib._repopulate_plasmids()
            except NoMatches:
                pass
            # If the currently-active record is in the touched set,
            # re-hydrate its alignment band so the new overlay shows
            # up without requiring a manual switch-away-and-back.
            try:
                cur = getattr(self.app, "_current_record", None)
                cur_id = getattr(cur, "id", None) if cur else None
                if cur_id in touched_target_ids:
                    hydrate = getattr(
                        self.app,
                        "_hydrate_alignments_for_active", None,
                    )
                    if callable(hydrate):
                        hydrate()
            except Exception:
                _log.exception(
                    "BulkAlign: post-commit re-hydration failed",
                )
        self.app.call_from_thread(_commit_batch)
        # Materialise the add success/failure counts after the
        # batch commit so the summary reflects actually-persisted
        # add-as-new totals.
        n_added_local = add_counters["ok"]
        n_add_failed_local = add_counters["err"]

        def _summary(n_added=n_added_local, n_add_failed=n_add_failed_local):
            # Refresh the LibraryPanel after add-as-new entries land
            # (alignments already trigger refresh per flush).
            if n_added:
                try:
                    lib = self.app.query_one(
                        "#library", LibraryPanel,
                    )
                    lib._view_mode = "plasmids"
                    lib._apply_view_mode()
                    lib._repopulate_plasmids()
                except NoMatches:
                    pass
            try:
                # Surface add-save failures distinctly. Pre-fix
                # `n_added` was the count of "tried to add", not
                # "saved successfully" — a disk-full or
                # permission-denied OSError was caught + logged but
                # the toast still claimed N new entries.
                parts = [
                    f"aligned {n_aligned}",
                    f"added {n_added} new",
                ]
                if n_add_failed:
                    parts.append(f"add failed {n_add_failed}")
                if n_failed:
                    parts.append(f"failed {n_failed}")
                self.app.notify(
                    "Bulk-align complete · " + " · ".join(parts),
                    title="Bulk alignment",
                    severity=(
                        "warning"
                        if (n_add_failed or n_failed)
                        else "information"
                    ),
                    timeout=8,
                )
            except Exception:
                pass
        self.app.call_from_thread(_summary)
        # INV-73 (2026-05-25): batch summary as a structured event so
        # the diagnostic bundle's events_summary.json captures the
        # bulk-align outcome. Pre-fix the toast was the only record;
        # if the user dismissed it (or pressed F9 after a session
        # restart) the bulk-align outcome was unrecoverable from the
        # bundle. Logged in the worker thread (`_log_event` is
        # thread-safe).
        try:
            _log_event(
                "alignment.bulk.summary",
                n_aligned=int(n_aligned),
                n_added=int(n_added_local),
                n_add_failed=int(n_add_failed_local),
                n_failed=int(n_failed),
                n_committed=len(committed),
            )
        except Exception:  # noqa: BLE001 — logging must never raise
            pass
        # INV-74 (2026-05-25): hide the progress widgets when the
        # batch completes (success OR cancel). Fill the bar before
        # hide so the final state is visually correct for a beat.
        def _progress_done():
            try:
                from textual.widgets import ProgressBar
                bar = self.query_one("#bulk-align-bar", ProgressBar)
                txt = self.query_one("#bulk-align-progress", Static)
                bar.update(total=max(1, n_total), progress=n_total)
                txt.update(
                    f"[b]Bulk-align complete:[/b] {n_aligned} aligned · "
                    f"{add_counters['ok']} added · "
                    f"{add_counters['err']} add-failed · "
                    f"{n_failed} failed"
                )
                # Leave the final message visible for ~6 s, then hide.
                self.set_timer(6.0, lambda: (
                    bar.remove_class("-active"),
                    txt.remove_class("-active"),
                    txt.update(""),
                ))
            except (NoMatches, AttributeError):
                pass
        self.app.call_from_thread(_progress_done)

    @on(Button.Pressed, "#btn-sequencing-close")
    def _close_btn(self, _) -> None:
        self.action_cancel()

    def action_cancel(self) -> None:
        # Cooperative cancel: a running alignment worker checks this
        # before registering its result so the user doesn't see a
        # stale overlay paint after closing the screen.
        self._cancelled = True
        # INV-74 (2026-05-25): guard against double-dismiss.
        # Pre-fix the close-button + Esc keybinding could fire both,
        # OR a `_dismiss_once` modal already popped us, OR the
        # callback chain re-entered cancel — second `dismiss(None)`
        # raises `ScreenStackError: Can't pop screen` because the
        # screen is no longer on the stack. User-reported crash on
        # 0.9.22 with that exact traceback.
        if getattr(self, "_dismissed", False):
            return
        self._dismissed = True
        try:
            if not self.is_mounted:
                return
            if len(self.app._screen_stack) <= 1:
                return
            self.dismiss(None)
        except Exception:  # noqa: BLE001 — dismiss must not crash app
            _log.exception(
                "SequencingScreen.action_cancel: dismiss failed; "
                "screen state may be inconsistent",
            )


# Back-compat alias. `PlasmidsaurusAlignModal` is the legacy class name
# from before the Sequencing toolbar refactor (2026-05-18). Tests and
# agent-API call sites still reference it by name; aliasing here keeps
# them working without churning the test fixtures.
PlasmidsaurusAlignModal = SequencingScreen




# ── Experiments lab-notebook screen ──────────────────────────────────────────
#
# `ExperimentsScreen` is the top-level toolbar entry for the lab-
# notebook workbench. Full-screen, mirrors `SequencingScreen`'s shape:
# outer TabbedContent with three sub-tabs (Entries / Compose /
# Attachments). Compose + Attachments are gated until the user selects
# or creates an entry — same gating pattern as Plasmidsaurus's
# Samples / Quality / Align panes.
#
# Persistence is through `_load_experiments` / `_save_experiments`
# (full data-safety net per invariant #31). Cross-references to
# library plasmids are written as `@plasmid:<id>` tokens; the
# Markdown preview pane renders them as styled links with a
# `splicecraft://plasmid/<id>` href that `on_markdown_link_clicked`
# intercepts to load the referenced plasmid through the main canvas.
#
# Pure-Python toolchain: Textual `TextArea` for the markdown source,
# Textual `Markdown` widget for the live preview (debounced 250 ms on
# every body change). Optional deps (`rich-pixels`, `Pillow`,
# `pyspellchecker`) are try-imported so the screen degrades
# gracefully if they're not installed.


class ExperimentProjectsPickerModal(_OneShotDismissScreen, ModalScreen):
    """Browse, create, rename, delete, and duplicate experiment projects.

    Mirrors `PartsBinPickerModal` for the projects side of the multi-
    project architecture. Each entry in the table is a named project
    from `experiment_projects.json`; selecting one sets it active and
    dismisses with the project name so the caller can refresh the
    `ExperimentsScreen` entries list against the freshly-active
    project's experiments.

    Refuses to delete the last remaining project — empty experiments
    state is fine, but a project-less state would orphan the
    `_save_experiments` mirror and the migration would re-create
    "Main Project" on next launch anyway. The cleaner UX is to nudge
    the user to create another first.

    Dismiss payload:
      ``None``  — cancelled (Esc / Close / no selection on Open)
      ``str``   — name of the project to open; caller refreshes the
                  entries table after switching the active pointer.
    """

    # Sweep #9 (2026-05-19): block app-level Ctrl+Z while the picker
    # is open so a user fat-fingering the shortcut can't unwind plasmid
    # edits underneath. Attr must come AFTER docstring per invariant #41.
    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel",         "Close"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    def compose(self) -> ComposeResult:
        with Vertical(id="projpick-dlg"):
            yield Static(
                "  Experiment projects  ", id="projpick-title",
            )
            yield Label(
                "Pick a project to open its lab-notebook entries. "
                "[b]★[/b] marks the currently-active project.",
                id="projpick-help", markup=True,
            )
            yield DataTable(id="projpick-table", cursor_type="row",
                            zebra_stripes=True)
            yield Static("", id="projpick-status", markup=True)
            with Horizontal(id="projpick-btns"):
                yield Button("Open", id="btn-projpick-open",
                             variant="primary")
                yield Button("New", id="btn-projpick-new")
                yield Button("Rename", id="btn-projpick-rename")
                yield Button("Duplicate", id="btn-projpick-dup")
                yield Button("Delete", id="btn-projpick-del",
                             variant="error")
                yield Button("Close", id="btn-projpick-close")

    def on_mount(self) -> None:
        t = self.query_one("#projpick-table", DataTable)
        t.add_columns("", "Project", "Entries", "Last activity")
        self._repopulate()
        t.focus()

    def _repopulate(self) -> None:
        """Rebuild the project table from disk and cursor onto the
        active project (so the user's most-recent context is
        highlighted by default). Natural-sort by name so `Proj2`
        lands before `Proj10`. The first column is an active-project
        marker (★) so the user can see at a glance which project is
        currently loaded.
        """
        t = self.query_one("#projpick-table", DataTable)
        t.clear()
        projs = sorted(
            _load_experiment_projects(),
            key=lambda p: _natural_sort_key(p.get("name") or ""),
        )
        active = _get_active_project_name()
        cursor = 0
        for i, p in enumerate(projs):
            name = p.get("name") or "?"
            n_entries = len(p.get("experiments", []) or [])
            # Pick the freshest entry's updated_at — more useful than
            # the project's `saved` field, which only updates on
            # rename/duplicate/manual saves of the project list.
            last_activity = ""
            for e in (p.get("experiments") or []):
                if not isinstance(e, dict):
                    continue
                up = e.get("updated_at") or ""
                if up and up > last_activity:
                    last_activity = up
            last_activity = _history_human_dt(last_activity[:10]) or "—"
            is_active = (active and name == active)
            marker = "[b yellow]★[/b yellow]" if is_active else " "
            t.add_row(
                Text.from_markup(marker),
                Text(name, no_wrap=True),
                str(n_entries),
                last_activity,
                key=name,
            )
            if is_active:
                cursor = i
        if projs:
            t.move_cursor(row=cursor)

    def _selected_project_name(self) -> "str | None":
        return _cursor_row_key(
            self.query_one("#projpick-table", DataTable),
        )

    def _set_status(self, msg: str) -> None:
        try:
            self.query_one("#projpick-status", Static).update(msg)
        except NoMatches:
            pass

    # ── Open ──────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-projpick-open")
    def _open(self, _) -> None:
        name = self._selected_project_name()
        if not name:
            self._set_status("[red]No project selected.[/red]")
            return
        if _find_project(name) is None:
            self._set_status(f"[red]Project '{name}' not found.[/red]")
            self._repopulate()
            return
        # Sweep #9 (2026-05-19): atomic project switch. Pre-fix
        # ordering was `_set_active_project_name` (async daemon
        # flush) THEN sync `_safe_save_json(_state._EXPERIMENTS_FILE)` —
        # power loss in the window between the two writes left
        # settings.json saying OLD project + experiments.json
        # holding NEW project's entries. The next UI save would
        # then mirror NEW entries into OLD project, silently
        # overwriting OLD's data.
        #
        # New ordering: update active-pointer in memory, FORCE
        # synchronous flush so disk-settings reflects the new
        # active project, then write experiments. A crash between
        # the flush and the experiments write self-heals on the
        # NEXT LAUNCH: `_restore_experiments_from_active_project`
        # rebuilds experiments.json from the active (NEW) project,
        # so the stale OLD entries can't be mirrored back over NEW
        # by the next `_save_experiments`. (A same-session mirror
        # failure is reverted in the `except` below.)
        target = _find_project(name)
        raw_entries = (target or {}).get("experiments", [])
        if not isinstance(raw_entries, list):
            raw_entries = []
        target_entries = [e for e in raw_entries if isinstance(e, dict)]
        prev = _get_active_project_name()
        _set_active_project_name(name)
        _settings_flush_sync()
        try:
            # Bypass `_save_experiments` here because that would
            # re-mirror back into the project we just switched to
            # (the project IS the source of truth in this
            # direction). [INV-83, sweep #27]: mirror-swap helper
            # exempts the write from the L3 shrink guard (the
            # outgoing project's entries are intact in
            # experiment_projects.json).
            _safe_save_json_mirror(
                _state._EXPERIMENTS_FILE, target_entries, "Experiments",
            )
        except (OSError, RuntimeError) as exc:
            # Revert the pointer so active-name and experiments.json stay
            # consistent — the desync would clobber the target project on the
            # next save. [INV-161]
            _set_active_project_name(prev)
            _settings_flush_sync()
            _notify_save_failure(self.app, "Experiments", exc)
            return
        # Invalidate the experiments in-memory cache so the next
        # reader sees the new project's entries (file just changed
        # underneath).
        _state._experiments_cache = None
        self.dismiss(name)

    @on(DataTable.RowSelected, "#projpick-table")
    def _row_selected(self, event) -> None:
        # Enter on a row = Open. Mirrors PartsBinPickerModal /
        # PlasmidPickerModal so the picker behaves consistently
        # across the app.
        self._open(None)

    # ── New ───────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-projpick-new")
    def _new(self, _) -> None:
        def _on_named(name):
            if not name:
                return
            if _project_name_taken(name):
                self._set_status(
                    f"[red]A project named '{name}' already exists.[/red]"
                )
                return
            projs = _load_experiment_projects()
            projs.append({
                "name":        name,
                "description": "New project",
                "experiments": [],
                "saved":       _date.today().isoformat(),
            })
            try:
                _save_experiment_projects(projs)
            except (OSError, RuntimeError) as exc:
                _notify_save_failure(
                    self.app, "Experiment projects", exc,
                )
                return
            _log_event("project.created", name=name)
            self._set_status(f"[green]Created project '{name}'.[/green]")
            self._repopulate()
        self.app.push_screen(
            CollectionNameModal(
                title="New project",
                placeholder="Project name",
            ),
            callback=_on_named,
        )

    # ── Rename ────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-projpick-rename")
    def _rename(self, _) -> None:
        old = self._selected_project_name()
        if not old:
            self._set_status("[red]No project selected.[/red]")
            return

        def _on_named(new_name):
            if not new_name or new_name == old:
                return
            if _project_name_taken(new_name):
                self._set_status(
                    f"[red]A project named '{new_name}' already "
                    f"exists.[/red]"
                )
                return
            projs = _load_experiment_projects()
            for p in projs:
                if p.get("name") == old:
                    p["name"] = new_name
                    break
            else:
                self._set_status(
                    f"[red]Project '{old}' has vanished — refresh.[/red]"
                )
                self._repopulate()
                return
            try:
                _save_experiment_projects(projs)
            except (OSError, RuntimeError) as exc:
                _notify_save_failure(
                    self.app, "Experiment projects", exc,
                )
                return
            # Carry the active-project pointer if we just renamed it.
            if _get_active_project_name() == old:
                _set_active_project_name(new_name)
            _log_event("project.renamed", old=old, new=new_name)
            self._set_status(
                f"[green]Renamed '{old}' → '{new_name}'.[/green]"
            )
            self._repopulate()
        self.app.push_screen(
            CollectionNameModal(
                title=f"Rename project '{old}'",
                current=old,
                placeholder="New name",
            ),
            callback=_on_named,
        )

    # ── Duplicate ─────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-projpick-dup")
    def _duplicate(self, _) -> None:
        source = self._selected_project_name()
        if not source:
            self._set_status("[red]No project selected.[/red]")
            return

        def _on_named(new_name):
            if not new_name or new_name == source:
                return
            if _project_name_taken(new_name):
                self._set_status(
                    f"[red]A project named '{new_name}' already "
                    f"exists.[/red]"
                )
                return
            src = _find_project(source)
            if src is None:
                self._set_status(
                    f"[red]Source project '{source}' has vanished.[/red]"
                )
                self._repopulate()
                return
            projs = _load_experiment_projects()
            projs.append({
                "name":        new_name,
                "description": f"Duplicated from '{source}'",
                # Deep-copy via _typed_clone so subsequent edits to
                # either project don't touch the other.
                "experiments": _typed_clone(
                    src.get("experiments", []) or []
                ),
                "saved":       _date.today().isoformat(),
            })
            try:
                _save_experiment_projects(projs)
            except (OSError, RuntimeError) as exc:
                _notify_save_failure(
                    self.app, "Experiment projects", exc,
                )
                return
            _log_event(
                "project.duplicated", source=source, new=new_name,
                n_entries=len(src.get("experiments") or []),
            )
            self._set_status(
                f"[green]Duplicated '{source}' → '{new_name}'.[/green]"
            )
            self._repopulate()
        self.app.push_screen(
            CollectionNameModal(
                title=f"Duplicate project '{source}'",
                current=f"{source} copy",
                placeholder="New project name",
            ),
            callback=_on_named,
        )

    # ── Delete ────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-projpick-del")
    def _delete(self, _) -> None:
        """Open a warning modal before destroying a project + all its
        entries. Default focus is on No (a stray Enter cannot delete).
        Reuses `ExperimentDeleteConfirmModal` — same UX as entry
        deletion so the user gets consistent behaviour across both
        delete paths (2026-05-18)."""
        name = self._selected_project_name()
        if not name:
            self._set_status("[red]No project selected.[/red]")
            return
        projs = _load_experiment_projects()
        if len(projs) <= 1:
            self._set_status(
                "[red]Can't delete the last remaining project — "
                "create another first.[/red]"
            )
            return
        proj = _find_project(name)
        n_entries = len(
            (proj or {}).get("experiments") or []
        )
        body = (
            f"Delete project [b]{name}[/b] and "
            f"[b]{n_entries}[/b] entrie"
            f"{'s' if n_entries != 1 else ''} it contains?\n\n"
            "[dim]This cannot be undone. The on-disk JSON gets a "
            "timestamped `.bak` rotation, but image attachments "
            "for the deleted entries stay on disk until manually "
            "removed.[/dim]"
        )

        def _on_confirm(yes) -> None:
            if not yes:
                return
            self._do_delete(name)
        self.app.push_screen(
            ExperimentDeleteConfirmModal(
                title="Delete project?", body=body,
            ),
            callback=_on_confirm,
        )

    def _do_delete(self, name: str) -> None:
        """Actual project deletion + active-pointer promotion.
        Factored out of `_delete` so the confirm modal can call it
        on Yes. Re-checks the last-project guard (defence against a
        concurrent delete shrinking the list between the modal open
        and the user's confirm — single-user app + lock file makes
        this rare but still worth catching).

        Sweep #35 (2026-05-26): the full read→save→promote→mirror
        sequence runs under `_cache_lock`. Pre-fix, each helper
        (`_load_experiment_projects`, `_save_experiment_projects`,
        `_set_active_project_name → _set_setting`,
        `_safe_save_json_mirror`) took the lock individually and
        released between steps. A concurrent agent endpoint adding a
        new project between our load and save would have its
        addition silently overwritten by the `remaining` list (which
        was computed pre-add). `_cache_lock` is an RLock so the
        re-entry from inner helpers is free."""
        with _cache_lock:
            projs = _load_experiment_projects()
            if len(projs) <= 1:
                self._set_status(
                    "[red]Project list shrank during confirm — "
                    "can't delete the last remaining project.[/red]"
                )
                self._repopulate()
                return
            if _find_project(name) is None:
                self._set_status(
                    f"[red]Project '{name}' has vanished — refresh.[/red]"
                )
                self._repopulate()
                return
            remaining = [p for p in projs if p.get("name") != name]
            try:
                _save_experiment_projects(remaining)
            except (OSError, RuntimeError) as exc:
                _notify_save_failure(
                    self.app, "Experiment projects", exc,
                )
                return
            # If the user deleted the active project, promote the first
            # remaining one to active so subsequent `_save_experiments`
            # mirror writes land somewhere valid. Sweep #9 (2026-05-19):
            # the active-pointer flip MUST land on disk via
            # `_settings_flush_sync` BEFORE writing the promoted
            # project's entries to experiments.json — see the matching
            # comment in `_open` for the corruption window this closes.
            was_active = _get_active_project_name() == name
            if was_active and remaining:
                promoted = remaining[0].get("name")
                if promoted:
                    promoted_proj = _find_project(promoted)
                    promoted_entries = (
                        (promoted_proj or {}).get("experiments") or []
                    )
                    promoted_entries = [
                        e for e in promoted_entries if isinstance(e, dict)
                    ]
                    _set_active_project_name(promoted)
                    _settings_flush_sync()
                    try:
                        # [INV-83, sweep #27] Project delete auto-
                        # promotes another project to active and
                        # mirrors its entries. Mirror-swap; the
                        # promoted project's entries are intact in
                        # experiment_projects.json.
                        _safe_save_json_mirror(
                            _state._EXPERIMENTS_FILE, promoted_entries,
                            "Experiments",
                        )
                        _state._experiments_cache = None
                    except (OSError, RuntimeError) as exc:
                        _notify_save_failure(
                            self.app, "Experiments", exc,
                        )
            _log_event(
                "project.deleted", name=name,
                was_active=bool(was_active),
            )
        self._set_status(f"[dim]Deleted project '{name}'.[/dim]")
        self._repopulate()

    # ── Cancel / Close ────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-projpick-close")
    def _close(self, _) -> None:
        self.dismiss(None)

    def action_cancel(self) -> None:
        self.dismiss(None)






class ExperimentRenameModal(ModalScreen):
    """Rename modal for the entry title. Wraps a single Input — used
    by both the Entries sub-tab's Rename button and any future agent
    path that wants to mutate the title without re-saving the body."""

    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel", "Cancel"),
        Binding("enter",  "submit", "Save"),
    ]

    def __init__(self, current_title: str) -> None:
        super().__init__()
        self._current = current_title or ""
        # Sweep #26: [INV-50] dismiss-once guard. Cancel button + Esc
        # + Save button + Enter binding = four exit paths.
        self._dismissed: bool = False

    def compose(self) -> ComposeResult:
        with Vertical(id="exprn-dlg"):
            yield Static(" Rename entry ", id="exprn-title")
            yield Input(value=self._current,
                         placeholder="entry title",
                         id="exprn-input")
            with Horizontal(id="exprn-btns"):
                yield Button("Save", id="btn-exprn-save",
                              variant="primary")
                yield Button("Cancel", id="btn-exprn-cancel")

    DEFAULT_CSS = """
    #exprn-dlg {
        width: 70; height: auto;
        background: $surface; border: solid $primary-darken-2;
        padding: 1 2; layout: vertical;
    }
    #exprn-title {
        background: $primary-darken-2; color: $text;
        padding: 0 1; height: 1; text-align: center;
    }
    #exprn-input { margin-top: 1; }
    #exprn-btns { height: 3; margin-top: 1; align: center middle; }
    #exprn-btns Button { margin: 0 1; min-width: 14; }
    """

    def on_mount(self) -> None:
        try:
            self.query_one("#exprn-input", Input).focus()
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-exprn-cancel")
    def _cancel(self, _ev) -> None:
        self._dismiss_once(None)

    @on(Button.Pressed, "#btn-exprn-save")
    def _save(self, _ev) -> None:
        self.action_submit()

    def action_cancel(self) -> None:
        self._dismiss_once(None)

    @_action_log("app.experiments.rename.submit")
    def action_submit(self) -> None:
        try:
            val = self.query_one("#exprn-input", Input).value
        except NoMatches:
            self._dismiss_once(None)
            return
        self._dismiss_once((val or "").strip()
                            [:_EXPERIMENT_TITLE_MAX_LEN] or None)

    def _dismiss_once(self, payload) -> None:
        """[INV-50] Dispatch the dismiss exactly once. Pre-fix four
        exit paths each called `self.dismiss(...)` — a fast double-
        tap could fire two dismisses and trip Textual's screen-stack
        underflow check."""
        if self._dismissed:
            return
        self._dismissed = True
        self.dismiss(payload)


# Image extensions the file picker exposes. Matches the writer's
# accept-list (`_IMAGE_EXTS`) so a user picking through the tree only
# sees what `_save_experiment_image` will actually accept.
_IMAGE_FILE_FILTER = set(_IMAGE_EXTS)


class _ImagePickerTree(DirectoryTree):
    """DirectoryTree variant that hides non-image files. Inheriting
    Textual's filter API (`filter_paths`) keeps the navigation native;
    only the leaf filenames get filtered."""

    def filter_paths(self, paths):
        out = []
        for p in paths:
            try:
                if p.is_dir():
                    out.append(p)
                    continue
                if p.suffix.lower() in _IMAGE_FILE_FILTER:
                    out.append(p)
            except OSError:
                continue
        return out


class GelLibraryModal(_OneShotDismissScreen, ModalScreen):
    """Browse, save, rename, load, and delete agarose-gel snapshots.

    Two-context modal — caller decides what the dismiss payload
    means:
      * `SimulatorScreen` opens it with `current_lanes` +
        `current_agarose_pct` so the user can save the current gel.
        On dismiss-with-id the caller restores those values into
        the live simulator.
      * `ExperimentsScreen` opens it WITHOUT a current snapshot
        (Save button stays disabled). On dismiss-with-id the
        caller inserts `&<id>` into the body.

    Dismiss payload:
      ``None``  — cancelled (Esc / Close / no selection)
      ``str``   — gel id the user picked.
    """

    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel",         "Close"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    def __init__(
        self,
        *,
        current_lanes: "list[dict] | None" = None,
        current_agarose_pct: "float | None" = None,
        current_name: "str | None" = None,
        initial_gel_id: "str | None" = None,
        inspect_only: bool = False,
    ) -> None:
        super().__init__()
        # Defensive deepcopy of lanes — `SimulatorScreen._lanes` may
        # carry widget-id `_suffix` fields the user doesn't want
        # mirrored to disk. We strip them on save (`_take_snapshot`)
        # rather than mutating the caller's list.
        self._current_lanes = current_lanes
        self._current_agarose_pct = current_agarose_pct
        # Pre-fill the Save dialog with the Simulator's gel name (the
        # "Demo Gel" / user-set name from the gel pane). "Demo Gel" is
        # offered as-is — the user can rename in the prompt.
        self._current_name = current_name
        self._initial_gel_id = initial_gel_id
        # Sweep #9 (2026-05-19): inspect_only flag for the click-through
        # path (`Ctrl+G` on a `&<id>` tag). In that mode the modal has
        # no callback target for Load — pre-fix Load was a silent
        # no-op. Now Load + Save are disabled (Rename / Delete still
        # work — they mutate gels.json directly without needing a
        # caller-side restore).
        self._inspect_only = inspect_only

    def compose(self) -> ComposeResult:
        with Vertical(id="gellib-dlg"):
            yield Static("  Gel library  ", id="gellib-title")
            if self._inspect_only:
                yield Label(
                    "[dim]Inspect-only view — opened from a "
                    "[b]&<id>[/b] tag click. Use [b]Rename[/b] / "
                    "[b]Delete[/b] to manage the gel; to load it "
                    "back into the Simulator, close this modal and "
                    "open the Simulator's Gel pane → Library.[/]",
                    id="gellib-help", markup=True,
                )
            else:
                yield Label(
                    "Saved gel snapshots — load one back into the "
                    "Simulator, or pick one to insert as an "
                    "[b]&<id>[/b] tag in an experiment.",
                    id="gellib-help", markup=True,
                )
            yield DataTable(id="gellib-table", cursor_type="row",
                            zebra_stripes=True)
            yield Static("", id="gellib-status", markup=True)
            with Horizontal(id="gellib-btns"):
                yield Button("Load", id="btn-gellib-load",
                             variant="primary",
                             disabled=self._inspect_only)
                yield Button("Save current",
                             id="btn-gellib-save",
                             disabled=(self._current_lanes is None
                                       or self._inspect_only))
                yield Button("Rename", id="btn-gellib-rename")
                yield Button("Delete", id="btn-gellib-del",
                             variant="error")
                yield Button("Close", id="btn-gellib-close")

    def on_mount(self) -> None:
        t = self.query_one("#gellib-table", DataTable)
        t.add_columns("Name", "Lanes", "Agarose %", "Last updated")
        self._repopulate()
        t.focus()

    # ── Table population ──────────────────────────────────────────────

    def _repopulate(self) -> None:
        """Rebuild the gel table. Natural-sort by name so `Gel 2`
        lands before `Gel 10`. Cursor onto `initial_gel_id` if
        provided (used by the click-to-open path) so the user lands
        directly on the gel they came from."""
        t = self.query_one("#gellib-table", DataTable)
        t.clear()
        gels = sorted(
            _load_gels(),
            key=lambda g: _natural_sort_key(g.get("name") or ""),
        )
        cursor_row = 0
        for i, g in enumerate(gels):
            gid = g.get("id") or ""
            name = g.get("name") or "?"
            n_lanes = len(g.get("lanes") or [])
            agar = g.get("agarose_pct")
            if isinstance(agar, (int, float)) and not (
                agar != agar or agar in (float("inf"), float("-inf"))
            ):
                agar_str = f"{float(agar):.1f}"
            else:
                agar_str = "—"
            updated = _history_human_dt((g.get("updated_at") or "")[:10]) or "—"
            t.add_row(
                Text(name, no_wrap=True),
                str(n_lanes),
                agar_str,
                updated,
                key=gid,
            )
            if self._initial_gel_id and gid == self._initial_gel_id:
                cursor_row = i
        if gels:
            t.move_cursor(row=cursor_row)

    def _selected_gel_id(self) -> "str | None":
        return _cursor_row_key(
            self.query_one("#gellib-table", DataTable),
        )

    def _set_status(self, msg: str) -> None:
        try:
            self.query_one("#gellib-status", Static).update(msg)
        except NoMatches:
            pass

    def _take_snapshot(self) -> "dict | None":
        """Build a normalised entry from the caller's current state.
        Returns None if no current state was passed (the
        ExperimentsScreen tag-picker case)."""
        if self._current_lanes is None:
            return None
        clean_lanes: "list[dict]" = []
        for ln in self._current_lanes:
            if not isinstance(ln, dict):
                continue
            # Strip widget-id `_suffix` and any other private fields
            # so the on-disk snapshot is clean.
            clean_lanes.append({
                "name":   ln.get("name") or "",
                "source": ln.get("source") or "empty",
                "detail": ln.get("detail") or "",
            })
        return {
            "lanes": clean_lanes,
            "agarose_pct": (
                self._current_agarose_pct
                if self._current_agarose_pct is not None
                else 1.0
            ),
            "notes": "",
        }

    # ── Load ──────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-gellib-load")
    def _load(self, _) -> None:
        gid = self._selected_gel_id()
        if not gid:
            self._set_status("[red]No gel selected.[/red]")
            return
        if _find_gel(gid) is None:
            self._set_status(f"[red]Gel '{gid}' has vanished.[/red]")
            self._repopulate()
            return
        self.dismiss(gid)

    @on(DataTable.RowSelected, "#gellib-table")
    def _row_selected(self, event) -> None:
        # Enter on a row → Load. Same convention as the other
        # pickers (parts-bin, experiment projects).
        self._load(None)

    # ── Save current ──────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-gellib-save")
    def _save(self, _) -> None:
        snap = self._take_snapshot()
        if snap is None:
            self._set_status(
                "[red]No current gel to save — open this modal "
                "from the Simulator to save.[/red]"
            )
            return
        if not snap.get("lanes"):
            self._set_status(
                "[red]Current gel has no lanes — add at least one "
                "lane in the Simulator before saving.[/red]"
            )
            return

        def _on_named(name) -> None:
            if not name:
                return
            if _gel_name_taken(name):
                self._set_status(
                    f"[red]A gel named '{name}' already exists.[/red]"
                )
                return
            entry = dict(snap)
            entry["name"] = name
            entry = _normalise_gel_entry(entry, fresh=True)
            gels = _load_gels()
            gels.append(entry)
            try:
                _save_gels(gels)
            except (OSError, RuntimeError) as exc:
                _notify_save_failure(self.app, "Gels", exc)
                return
            _log_event(
                "gel.created", gid=entry["id"], name=name,
                n_lanes=len(entry["lanes"]),
            )
            self._set_status(
                f"[green]Saved gel '{name}' "
                f"({len(entry['lanes'])} lane"
                f"{'s' if len(entry['lanes']) != 1 else ''}).[/green]"
            )
            self._repopulate()
        self.app.push_screen(
            CollectionNameModal(
                title="Save gel",
                current=(self._current_name or ""),
                placeholder="Gel name",
            ),
            callback=_on_named,
        )

    # ── Rename ────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-gellib-rename")
    def _rename(self, _) -> None:
        gid = self._selected_gel_id()
        if not gid:
            self._set_status("[red]No gel selected.[/red]")
            return
        target = _find_gel(gid)
        if target is None:
            self._set_status(f"[red]Gel '{gid}' has vanished.[/red]")
            self._repopulate()
            return
        old_name = target.get("name") or ""

        def _on_named(new_name) -> None:
            if not new_name or new_name == old_name:
                return
            if _gel_name_taken(new_name):
                self._set_status(
                    f"[red]A gel named '{new_name}' already "
                    f"exists.[/red]"
                )
                return
            gels = _load_gels()
            for g in gels:
                if g.get("id") == gid:
                    g["name"] = new_name[:_GEL_NAME_MAX_LEN]
                    g["updated_at"] = _now_iso()
                    break
            else:
                self._set_status(
                    f"[red]Gel '{old_name}' has vanished "
                    f"— refresh.[/red]"
                )
                self._repopulate()
                return
            try:
                _save_gels(gels)
            except (OSError, RuntimeError) as exc:
                _notify_save_failure(self.app, "Gels", exc)
                return
            _log_event(
                "gel.renamed", gid=gid,
                old=old_name, new=new_name,
            )
            self._set_status(
                f"[green]Renamed '{old_name}' → '{new_name}'.[/green]"
            )
            self._repopulate()
        self.app.push_screen(
            CollectionNameModal(
                title=f"Rename gel '{old_name}'",
                current=old_name,
                placeholder="New name",
            ),
            callback=_on_named,
        )

    # ── Delete ────────────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-gellib-del")
    def _delete(self, _) -> None:
        """Confirm-then-delete via `ExperimentDeleteConfirmModal`
        (default focus on No). Unlike projects, deleting the last
        gel is allowed — there's no "active gel" concept that an
        empty list would orphan."""
        gid = self._selected_gel_id()
        if not gid:
            self._set_status("[red]No gel selected.[/red]")
            return
        target = _find_gel(gid)
        if target is None:
            self._set_status(f"[red]Gel '{gid}' has vanished.[/red]")
            self._repopulate()
            return
        name = target.get("name") or gid
        body = (
            f"Delete gel [b]{name}[/b]?\n\n"
            "[dim]This cannot be undone. The on-disk JSON gets a "
            "timestamped `.bak` rotation, but the snapshot itself "
            "is gone.[/dim]"
        )

        def _on_confirm(yes) -> None:
            if not yes:
                return
            self._do_delete(gid, name)
        self.app.push_screen(
            ExperimentDeleteConfirmModal(
                title="Delete gel?", body=body,
            ),
            callback=_on_confirm,
        )

    def _do_delete(self, gid: str, name: str) -> None:
        gels = _load_gels()
        if _find_gel(gid) is None:
            # Vanished between confirm-open and confirm-yes.
            self._set_status(
                f"[red]Gel '{name}' has vanished — refresh.[/red]"
            )
            self._repopulate()
            return
        remaining = [g for g in gels if g.get("id") != gid]
        try:
            _save_gels(remaining)
        except (OSError, RuntimeError) as exc:
            _notify_save_failure(self.app, "Gels", exc)
            return
        _log_event("gel.deleted", gid=gid, name=name)
        self._set_status(f"[dim]Deleted gel '{name}'.[/dim]")
        self._repopulate()

    # ── Cancel / Close ────────────────────────────────────────────────

    @on(Button.Pressed, "#btn-gellib-close")
    def _close(self, _) -> None:
        self.dismiss(None)

    def action_cancel(self) -> None:
        self.dismiss(None)


class ActionsPickerModal(_OneShotDismissScreen, ModalScreen):
    """Pick a common cloning / PCR / assembly action to insert as
    `!<id>` into the experiment body.

    The catalog (`_EXPERIMENT_ACTIONS`) is curated for typical
    molecular-cloning workflows but is not enforced — users can also
    type free-form `!my-custom` directly into the body.

    `initial_action` (optional) — used by the click-through path:
    when the user opens a `!<id>` tag, the picker scrolls to that
    row so the relevant action is highlighted on open.

    Dismiss payload:
      ``None``  — cancelled (Esc / Cancel)
      ``str``   — action id to insert into the body.
    """

    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel",         "Cancel"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    def __init__(self, initial_action: "str | None" = None,
                  *, inspect_only: bool = False) -> None:
        super().__init__()
        self._initial_action = initial_action
        # Sweep #9 (2026-05-19): inspect_only flag for click-through
        # path. Same rationale as `GelLibraryModal._inspect_only` —
        # pre-fix the Insert button was a silent no-op because no
        # callback was wired.
        self._inspect_only = inspect_only

    def compose(self) -> ComposeResult:
        with Vertical(id="actpick-dlg"):
            yield Static(
                "  Insert action tag  ", id="actpick-title",
            )
            if self._inspect_only:
                yield Label(
                    "[dim]Inspect-only view — opened from a "
                    "[b]!<id>[/b] tag click. Close and use the "
                    "[b]Action ref[/b] button in an experiment to "
                    "insert a tag.[/]",
                    id="actpick-help", markup=True,
                )
            else:
                yield Label(
                    "Pick an action to insert as [b]!<id>[/b] into "
                    "the body.",
                    id="actpick-help", markup=True,
                )
            yield DataTable(id="actpick-table", cursor_type="row",
                            zebra_stripes=True)
            with Horizontal(id="actpick-btns"):
                yield Button("Insert", id="btn-actpick-ok",
                             variant="primary",
                             disabled=self._inspect_only)
                yield Button("Cancel", id="btn-actpick-cancel")

    def on_mount(self) -> None:
        t = self.query_one("#actpick-table", DataTable)
        t.add_columns("Category", "Action", "Description")
        cursor_row = 0
        for i, (category, action, desc) in enumerate(
            _EXPERIMENT_ACTIONS,
        ):
            t.add_row(category, action, desc, key=action)
            if self._initial_action and action == self._initial_action:
                cursor_row = i
        if t.row_count:
            t.move_cursor(row=cursor_row)
        t.focus()

    @on(Button.Pressed, "#btn-actpick-ok")
    def _ok(self, _) -> None:
        action = _cursor_row_key(
            self.query_one("#actpick-table", DataTable),
        )
        if not action:
            return
        self.dismiss(action)

    @on(DataTable.RowSelected, "#actpick-table")
    def _row_selected(self, event) -> None:
        self._ok(None)

    @on(Button.Pressed, "#btn-actpick-cancel")
    def _cancel(self, _) -> None:
        self.dismiss(None)

    def action_cancel(self) -> None:
        self.dismiss(None)


class ImageAttachModal(_OneShotDismissScreen, ModalScreen):
    """Pick an image file off disk OR (on Win/Mac) opportunistically
    grab from the system clipboard via Pillow's ImageGrab.

    Dismiss payload:
      None     — cancelled / nothing picked
      str path — local file picked OR (on clipboard-paste) a tmp file
                 the caller is responsible for treating as the source.

    Linux/WSL: clipboard-image read shells out to xclip / wl-paste,
    which our 'pure-Python' rule forbids. The Clipboard button is
    disabled on Linux. File-picker route works everywhere.
    """

    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel", "Cancel"),
        Binding("tab",    "app.focus_next", "Next", show=False),
    ]

    DEFAULT_CSS = """
    #imgatt-dlg {
        width: 100; height: 40;
        background: $surface; border: solid $primary-darken-2;
        padding: 1 2; layout: vertical;
    }
    #imgatt-title {
        background: $primary-darken-2; color: $text;
        padding: 0 1; height: 1; text-align: center;
    }
    #imgatt-hint { height: 2; color: $text-muted; margin-top: 1; }
    #imgatt-tree {
        height: 1fr; min-height: 10;
        border: solid $primary-darken-2; margin-top: 1;
    }
    #imgatt-selected { height: 1; color: $accent; margin-top: 1; }
    #imgatt-btns { height: 3; margin-top: 1; align: right middle; }
    #imgatt-btns Button { margin-right: 1; min-width: 14; }
    """

    def __init__(self, start_path: "str | None" = None) -> None:
        super().__init__()
        start = Path(start_path).expanduser() if start_path else Path.home()
        try:
            if not start.is_dir():
                start = Path.home()
        except OSError:
            start = Path.home()
        self._start = str(start)
        self._picked: "str | None" = None

    def compose(self) -> ComposeResult:
        with Vertical(id="imgatt-dlg"):
            yield Static(" Attach image ", id="imgatt-title")
            yield Static(
                "[dim]Pick an image (PNG / JPG / GIF / BMP / WebP / "
                "TIFF). Cap: 10 MB per file, 100 MB per entry.[/dim]",
                id="imgatt-hint", markup=True,
            )
            yield _ImagePickerTree(self._start, id="imgatt-tree")
            yield Static("[dim]no file selected[/dim]",
                          id="imgatt-selected", markup=True)
            with Horizontal(id="imgatt-btns"):
                yield Button("Attach", id="btn-imgatt-ok",
                              variant="primary", disabled=True)
                yield Button("Paste from clipboard",
                              id="btn-imgatt-clip")
                yield Button("Cancel", id="btn-imgatt-cancel")

    def on_mount(self) -> None:
        # Disable clipboard button on Linux/WSL — no pure-Python path
        # for reading a bitmap off the system clipboard there.
        if sys.platform not in ("win32", "darwin"):
            try:
                btn = self.query_one("#btn-imgatt-clip", Button)
                btn.disabled = True
                btn.tooltip = (
                    "Clipboard images require Windows or macOS "
                    "(Linux/WSL has no pure-Python clipboard image API). "
                    "Save the screenshot to disk first, then pick it."
                )
            except NoMatches:
                pass
        try:
            self.query_one("#imgatt-tree", _ImagePickerTree).focus()
        except NoMatches:
            pass

    @on(DirectoryTree.FileSelected, "#imgatt-tree")
    def _file_selected(self, event) -> None:
        try:
            p = Path(event.path)
        except (TypeError, ValueError):
            return
        if p.suffix.lower() not in _IMAGE_FILE_FILTER:
            return
        self._picked = str(p)
        try:
            self.query_one("#imgatt-selected", Static).update(
                f"[accent]Selected:[/] {p.name}",
            )
            self.query_one("#btn-imgatt-ok", Button).disabled = False
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-imgatt-ok")
    def _ok(self, _ev) -> None:
        if self._picked:
            self.dismiss(self._picked)

    @on(Button.Pressed, "#btn-imgatt-cancel")
    def _cancel(self, _ev) -> None:
        self.dismiss(None)

    @on(Button.Pressed, "#btn-imgatt-clip")
    def _clip(self, _ev) -> None:
        """Opportunistic Pillow ImageGrab on Win/Mac. On Linux/WSL the
        button is disabled, so this won't fire there."""
        try:
            from PIL import ImageGrab  # type: ignore
        except ImportError:
            self.app.notify(
                "Pillow not installed — clipboard paste unavailable.",
                severity="warning",
            )
            return
        try:
            img = ImageGrab.grabclipboard()
        except Exception as exc:
            self.app.notify(
                f"Clipboard read failed: {exc}", severity="error",
            )
            return
        if img is None or isinstance(img, list):
            # `list` return = file paths in clipboard (Win/Mac). Treat
            # the first entry as the file pick.
            if isinstance(img, list) and img:
                first = img[0]
                try:
                    p = Path(str(first))
                    if p.is_file() and p.suffix.lower() in _IMAGE_FILE_FILTER:
                        self.dismiss(str(p))
                        return
                except OSError:
                    pass
            self.app.notify(
                "No image on clipboard. Copy a screenshot first.",
                severity="warning",
            )
            return
        # An actual PIL image — sanity-check dimensions BEFORE save
        # so a hostile / accidental multi-monitor screenshot can't
        # bloat /tmp with a multi-GB PNG (sweep #9, 2026-05-19).
        try:
            w, h = int(img.width), int(img.height)
        except (AttributeError, TypeError, ValueError):
            w, h = 0, 0
        if w <= 0 or h <= 0 or w * h > _EXPERIMENT_CLIP_MAX_PIXELS:
            self.app.notify(
                f"Clipboard image too large "
                f"({w}×{h} = {w * h:,} pixels; cap "
                f"{_EXPERIMENT_CLIP_MAX_PIXELS:,}). Resize first.",
                severity="warning",
            )
            return
        # Write to a tmp file the modal returns via the dismiss str
        # path. Sweep #9 (2026-05-19): the prior `img.save` was bare
        # — on a failed write (disk-full, permission, decoder error)
        # the empty tmpfile leaked forever. Wrap in try/finally to
        # unlink on failure.
        import tempfile
        fd, tmp = tempfile.mkstemp(
            suffix=".png", prefix=_EXPERIMENT_CLIP_TMP_PREFIX,
        )
        os.close(fd)
        save_ok = False
        try:
            img.save(tmp, "PNG")
            save_ok = True
            self.dismiss(tmp)
        except Exception as exc:
            self.app.notify(
                f"Failed to save clipboard image: {exc}",
                severity="error",
            )
        finally:
            if not save_ok:
                try:
                    os.unlink(tmp)
                except OSError:
                    pass

    def action_cancel(self) -> None:
        self.dismiss(None)




# ── Experiment body TextArea (regex-highlighted cross-refs) ──────────────────
#
# Textual's `TextArea` does syntax highlighting through tree-sitter
# grammars; for SpliceCraft's two cross-ref tokens that's overkill, so
# we subclass and hook `_build_highlight_map` to inject regex-based
# highlights for `@plasmid:<id>` (lime) and `@actions:<id>` (purple).
#
# Mechanics:
#   1. `_build_highlight_map` is called by Textual after every edit
#      and after `language=` is set. We call super() to let the
#      markdown tree-sitter grammar populate its highlights first,
#      then append our own `(byte_start, byte_end, name)` tuples to
#      `self._highlights[line_index]`.
#   2. Highlight column indices in `self._highlights` are *byte*
#      offsets (Textual encodes the line as UTF-8 in `render_line`,
#      then maps byte→codepoint via `build_byte_to_codepoint_dict`).
#      `re.finditer` returns codepoint offsets, so we convert via
#      `len(line[:idx].encode("utf-8"))`. Pure-ASCII bodies skip the
#      conversion cost; the encoding only runs when a non-ASCII char
#      precedes a token.
#   3. The Rich styles for our highlight names are injected into the
#      live theme's `syntax_styles` on every build (idempotent via
#      `setdefault`). Re-injection on every build handles user theme
#      swaps gracefully.

class _ExperimentMarkdownTextArea(TextArea):
    """Markdown TextArea with regex-based in-editor highlighting for
    SpliceCraft's `@<id>` (plasmid), `!<id>` (action), and `&<id>`
    (gel) cross-ref tokens. Double-click on a tag posts a
    `TagOpenRequested` message that the parent screen wires to the
    relevant object-modal."""

    _PLASMID_HL_NAME = "splicecraft.plasmid_ref"
    _ACTIONS_HL_NAME = "splicecraft.action_ref"
    _GEL_HL_NAME     = "splicecraft.gel_ref"

    # Sweep #9 (2026-05-19) — per-line caps for the highlight
    # builder. Pasted tag-dense content (a 1 MB body of
    # `@a @a @a ...`) would otherwise rebuild ~750k regex
    # matches per keystroke and saturate the editor. Lines
    # longer than the length cap skip highlight injection
    # entirely; lines within length cap stop at the tag cap.
    # Body cap of 1 MB still applies — these only affect the
    # visual coloring on pathological lines.
    _HIGHLIGHT_LINE_LEN_CAP = 50_000
    _HIGHLIGHT_PER_LINE_TAG_CAP = 500

    class TagOpenRequested(Message):
        """Posted on double-click anywhere in the body. The parent
        screen reads the cursor position to determine which tag (if
        any) is under the cursor and opens the matching modal."""

    def _ensure_splice_styles(self) -> None:
        from rich.style import Style as _RichStyle
        theme = getattr(self, "_theme", None)
        if theme is None:
            return
        styles = theme.syntax_styles
        styles.setdefault(
            self._PLASMID_HL_NAME,
            _RichStyle(color=_PLASMID_CHIP_COLOR, bold=True),
        )
        styles.setdefault(
            self._ACTIONS_HL_NAME,
            _RichStyle(color=_ACTIONS_CHIP_COLOR, bold=True),
        )
        styles.setdefault(
            self._GEL_HL_NAME,
            _RichStyle(color=_GEL_CHIP_COLOR, bold=True),
        )

    def _build_highlight_map(self) -> None:
        super()._build_highlight_map()
        self._ensure_splice_styles()
        # `self.document` exists post-mount, but if `super()` is
        # called via a tree-sitter refresh before the document
        # attribute is wired (very rare in init order), bail out
        # silently. Narrow exception types per the bare-except ban.
        try:
            doc = self.document
            n_lines = doc.line_count
        except (AttributeError, ValueError):
            return
        for line_index in range(n_lines):
            try:
                line_text = doc.get_line(line_index)
            except (IndexError, ValueError):
                continue
            # Fast path: most lines have no sigil.
            if (
                "@" not in line_text
                and "!" not in line_text
                and "&" not in line_text
            ):
                continue
            # Sweep #9 (2026-05-19): line-length cap. Pasted tag-dense
            # content (a 1 MB body of `@a @a @a ...`) would otherwise
            # rebuild ~750k regex matches per keystroke and saturate
            # the editor. Lines longer than this skip highlight
            # injection entirely (the body cap of 1 MB still applies;
            # this only loses the visual coloring on the abusive line).
            if len(line_text) > self._HIGHLIGHT_LINE_LEN_CAP:
                continue
            # ASCII fast path: byte offsets == character offsets, so
            # we can skip the per-match UTF-8 encoding (which was
            # O(K × L) for K matches with average prefix length L —
            # the common case is many tags per line, all ASCII).
            line_tag_cap = self._HIGHLIGHT_PER_LINE_TAG_CAP
            if line_text.isascii():
                added = 0
                for m in _PLASMID_REF_RE.finditer(line_text):
                    if added >= line_tag_cap:
                        break
                    self._highlights[line_index].append((
                        m.start(), m.end(), self._PLASMID_HL_NAME,
                    ))
                    added += 1
                for m in _ACTIONS_REF_RE.finditer(line_text):
                    if added >= line_tag_cap:
                        break
                    self._highlights[line_index].append((
                        m.start(), m.end(), self._ACTIONS_HL_NAME,
                    ))
                    added += 1
                for m in _GEL_REF_RE.finditer(line_text):
                    if added >= line_tag_cap:
                        break
                    self._highlights[line_index].append((
                        m.start(), m.end(), self._GEL_HL_NAME,
                    ))
                    added += 1
                continue
            # Non-ASCII path: build a codepoint→byte position table
            # once for the whole line, then do O(1) lookups per
            # match. Drops the per-match `len(prefix.encode())`
            # cost from O(L) to O(1). Same per-line cap as the
            # ASCII fast path (sweep #9).
            positions = [0]
            cur = 0
            for ch in line_text:
                cur += len(ch.encode("utf-8"))
                positions.append(cur)
            added = 0
            for m in _PLASMID_REF_RE.finditer(line_text):
                if added >= line_tag_cap:
                    break
                self._highlights[line_index].append((
                    positions[m.start()],
                    positions[m.end()],
                    self._PLASMID_HL_NAME,
                ))
                added += 1
            for m in _ACTIONS_REF_RE.finditer(line_text):
                if added >= line_tag_cap:
                    break
                self._highlights[line_index].append((
                    positions[m.start()],
                    positions[m.end()],
                    self._ACTIONS_HL_NAME,
                ))
                added += 1
            for m in _GEL_REF_RE.finditer(line_text):
                if added >= line_tag_cap:
                    break
                self._highlights[line_index].append((
                    positions[m.start()],
                    positions[m.end()],
                    self._GEL_HL_NAME,
                ))
                added += 1

    def on_click(self, event) -> None:
        """Double-click anywhere in the body posts `TagOpenRequested`
        so the parent screen can open the modal for whichever tag
        (if any) lives under the cursor. Single-click is left
        untouched — Textual's default handler positions the cursor.
        """
        # `event.chain` is the consecutive-click count. Only fire on
        # the second click of a double-click; otherwise leave alone.
        if getattr(event, "chain", 1) >= 2:
            self.post_message(self.TagOpenRequested())

    def action_delete_left(self) -> None:
        """Backspace handler with tag-aware behaviour (2026-05-18):
        when the cursor sits at the end of a `@<id>` or `!<id>` token,
        the whole tag is deleted instead of just the last character.
        Anywhere else (mid-tag, prose, selection), default behaviour.
        """
        if self.read_only:
            return
        selection = self.selection
        if not selection.is_empty:
            super().action_delete_left()
            return
        try:
            row, col = self.cursor_location
            line_text = self.document.get_line(row)
        except (AttributeError, IndexError, ValueError):
            super().action_delete_left()
            return
        prefix = line_text[:col]
        m = (
            _PLASMID_REF_TAIL_RE.search(prefix)
            or _ACTIONS_REF_TAIL_RE.search(prefix)
            or _GEL_REF_TAIL_RE.search(prefix)
        )
        if m is None:
            super().action_delete_left()
            return
        tag_start_col = m.start()
        # Delete the entire matched tag span via the same underlying
        # path that `action_delete_left` uses for selections.
        self._delete_via_keyboard(
            (row, tag_start_col), (row, col),
        )


# ── ExperimentsScreen ────────────────────────────────────────────────────────

class ExperimentsScreen(_OneShotDismissScreen, Screen):
    """Full-screen Experiments toolbar — lab-notebook workbench.

    Split-pane layout: project switcher (top row) + always-visible
    entries list on the left + TabbedContent[Compose | Attachments]
    on the right. Each project (managed via
    `ExperimentProjectsPickerModal`) groups its own set of entries —
    projects are to experiments as collections are to plasmids
    (refactor 2026-05-18).

    Dismisses with ``None`` on Esc / Close; auto-saves the dirty
    compose buffer first so an accidental close never loses notes.
    """

    # App-level Ctrl+Z must not unwind plasmid edits while the user is
    # composing notebook entries (invariant #41 — modal Ctrl+Z opts out).
    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel",         "Close",        show=True),
        Binding("tab",    "app.focus_next", "Next",         show=False),
        Binding("ctrl+n", "new_entry",      "New",          show=True),
        Binding("ctrl+s", "save_entry",     "Save",         show=True),
        # Alt+I (not Ctrl+I): the Ctrl+I byte IS Tab (0x09), which Textual
        # delivers as "tab" — so `ctrl+i` never fired here and just moved
        # focus. [PIT-14] terminal-safe-shortcut rule.
        Binding("alt+i", "attach_image",   "Attach image", show=True),
        Binding("ctrl+r", "insert_plasmid", "Plasmid ref",  show=True),
        Binding("ctrl+p", "open_projects",  "Projects",     show=True),
        Binding("ctrl+g", "go_to_tag",      "Open tag",     show=True),
        Binding("f7",     "spellcheck",     "Spellcheck",   show=True),
    ]

    DEFAULT_CSS = """
    /* ── Frame ──────────────────────────────────────────────── */
    #exp-box {
        width: 100%; height: 1fr;
        background: $surface; padding: 0 1;
    }
    #exp-title {
        background: $primary-darken-2; color: $text;
        padding: 0 1; height: 1; text-align: center;
    }

    /* ── Project row (top) ──────────────────────────────────── */
    #exp-project-row {
        height: 3; margin-top: 0; align: left middle;
    }
    #exp-project-name {
        width: 1fr; padding: 1 1; color: $accent;
    }
    #btn-exp-projects {
        min-width: 18; margin: 0 1 0 0;
    }

    /* ── Body split (entries left, details right) ───────────── */
    #exp-body-split {
        width: 100%; height: 1fr; margin-top: 1;
    }
    #exp-entries-pane {
        width: 1fr; min-width: 24; height: 1fr; padding: 0 1 0 0;
    }
    #exp-details-pane {
        width: 4fr; height: 1fr;
    }

    #exp-tabs { width: 100%; height: 1fr; }
    #exp-tabs > TabPane { padding: 0 1; }

    /* ── Entries pane (permanent left side) ─────────────────── */
    #exp-entries-table {
        height: 1fr; min-height: 6;
        border: solid $primary-darken-2;
    }
    #exp-entries-btns-row1, #exp-entries-btns-row2,
    #exp-entries-btns-row3 {
        height: 3; margin: 1 0; align: left middle;
    }
    #exp-entries-btns-row1 Button,
    #exp-entries-btns-row2 Button,
    #exp-entries-btns-row3 Button {
        margin: 0 1; min-width: 10; width: 1fr;
    }

    /* ── Compose tab (in right pane) ──────────────────────────
       Title + tags inputs above, full-width TextArea below.
       Preview pane was removed 2026-05-18 — the narrow right pane
       made the side-by-side source/preview split too cramped. The
       writing area now takes the full right-pane width. */
    #exp-compose-pane { width: 100%; height: 1fr; }
    #exp-meta-row { height: 3; margin-top: 0; }
    #exp-tags-row { height: 3; margin-top: 0; }
    .exp-meta-label {
        width: 8; height: 3; padding: 1 1 0 1;
        color: $text-muted;
    }
    #exp-title-input { width: 1fr; }
    #exp-tags-input  { width: 1fr; }
    #exp-compose-hint { height: 1; color: $text-muted; margin-top: 1; }
    #exp-body {
        width: 100%; height: 1fr; min-height: 10; margin-top: 1;
        border: solid $primary-darken-2;
    }
    #exp-compose-btns { height: 3; margin-top: 1; align: left middle; }
    #exp-compose-btns Button { margin-right: 1; min-width: 14; }
    #exp-dirty-flag {
        width: auto; height: 3; padding: 1 1; color: $warning;
    }

    /* ── Attachments tab (in right pane) ─────────────────────── */
    #exp-attach-pane { width: 100%; height: 1fr; }
    #exp-attach-hint { height: 1; color: $text-muted; }
    #exp-attach-table {
        height: 1fr; min-height: 6;
        border: solid $primary-darken-2; margin-top: 1;
    }
    #exp-attach-preview {
        height: 16; min-height: 6; border: solid $primary-darken-2;
        margin-top: 1; content-align: center middle; overflow: hidden;
    }
    #exp-attach-btns { height: 3; margin-top: 1; align: left middle; }
    #exp-attach-btns Button { margin-right: 1; min-width: 14; }

    /* ── Screen footer with the Close button ──────────────────── */
    #exp-bottom {
        height: 3; margin-top: 1; align: left middle;
    }
    #exp-bottom Button { margin-right: 1; min-width: 14; }
    """

    _DEPENDENT_SUBTABS = ("exp-sub-compose", "exp-sub-attachments")

    def __init__(self, initial_entry_id: "str | None" = None) -> None:
        super().__init__()
        self._initial_entry_id = initial_entry_id
        self._current_entry: "dict | None" = None
        self._dirty: bool = False

    def check_action(self, action: str, parameters: tuple) -> bool | None:
        return True

    def compose(self) -> ComposeResult:
        yield Header()
        with Vertical(id="exp-box"):
            yield Static(
                " Experiments — lab notebook ", id="exp-title",
            )
            with Horizontal(id="exp-project-row"):
                yield Static(
                    self._format_project_label(),
                    id="exp-project-name", markup=True,
                )
                yield Button(
                    "Projects", id="btn-exp-projects",
                )
            with Horizontal(id="exp-body-split"):
                yield from self._compose_entries_pane()
                with Vertical(id="exp-details-pane"):
                    with TabbedContent(
                        initial="exp-sub-compose", id="exp-tabs",
                    ):
                        with TabPane("Compose", id="exp-sub-compose",
                                      disabled=True):
                            yield from self._compose_compose_pane()
                        with TabPane("Attachments",
                                      id="exp-sub-attachments",
                                      disabled=True):
                            yield from self._compose_attachments_pane()
            with Horizontal(id="exp-bottom"):
                yield Button("Close", id="btn-exp-close")
        yield Footer()

    def _format_project_label(self) -> str:
        """Human-readable header text showing the active project name.
        Truncates the displayed name to 60 chars so a hand-edited
        500-char project name can't push the Projects button
        off-screen on narrow terminals (edge sweep 2026-05-18)."""
        name = _get_active_project_name() or _DEFAULT_PROJECT_NAME
        if len(name) > 60:
            name = name[:57] + "…"
        return f"[bold]Project:[/bold] [accent]{name}[/accent]"

    def _compose_entries_pane(self) -> ComposeResult:
        with Vertical(id="exp-entries-pane"):
            yield DataTable(id="exp-entries-table",
                              cursor_type="row",
                              zebra_stripes=True)
            # 2 rows × 2 buttons so all four fit on a narrow left
            # pane (min-width: 24 — a single row of 4 × min-width-10
            # buttons overflowed and clipped Delete off-screen).
            with Horizontal(id="exp-entries-btns-row1"):
                yield Button("New",
                              id="btn-exp-new",
                              variant="primary")
                yield Button("Open", id="btn-exp-open")
            with Horizontal(id="exp-entries-btns-row2"):
                yield Button("Rename", id="btn-exp-rename")
                yield Button("Delete", id="btn-exp-delete",
                              variant="error")
            with Horizontal(id="exp-entries-btns-row3"):
                yield Button("Move", id="btn-exp-move")

    def _compose_compose_pane(self) -> ComposeResult:
        with Vertical(id="exp-compose-pane"):
            with Horizontal(id="exp-meta-row"):
                yield Static("Title:", classes="exp-meta-label")
                yield Input(placeholder="entry title",
                             id="exp-title-input")
            with Horizontal(id="exp-tags-row"):
                yield Static("Tags:", classes="exp-meta-label")
                yield Input(
                    placeholder="comma-separated, e.g. cloning, gibson",
                    id="exp-tags-input",
                )
            yield Static(
                "[dim]Markdown source. Cross-refs: "
                "[b]`@<id>`[/b] plasmid, [b]`!<id>`[/b] action, "
                "[b]`&<id>`[/b] gel. Insert via the "
                "[b]Plasmid ref[/b] / [b]Action ref[/b] / "
                "[b]Gel ref[/b] buttons or [b]^R[/b]. "
                "[b]^G[/b] (or double-click) jumps to the tag's source.[/]",
                id="exp-compose-hint", markup=True,
            )
            yield _ExperimentMarkdownTextArea(
                "", language="markdown", id="exp-body",
            )
            with Horizontal(id="exp-compose-btns"):
                yield Button("Save", id="btn-exp-save",
                              variant="primary")
                yield Button("Attach image",
                              id="btn-exp-attach")
                yield Button("Plasmid ref",
                              id="btn-exp-plasmid")
                yield Button("Action ref",
                              id="btn-exp-actions")
                yield Button("Gel ref",
                              id="btn-exp-gel")
                yield Button("Spellcheck",
                              id="btn-exp-spellcheck")
                yield Static("", id="exp-dirty-flag")

    def _compose_attachments_pane(self) -> ComposeResult:
        with Vertical(id="exp-attach-pane"):
            yield Static(
                "[dim]Attached images for the selected entry. Cap: "
                "10 MB per image, 100 MB per entry.[/]",
                id="exp-attach-hint", markup=True,
            )
            yield DataTable(id="exp-attach-table",
                              cursor_type="row",
                              zebra_stripes=True)
            yield Static(
                "[dim]Select an image above to preview it here.[/]",
                id="exp-attach-preview", markup=True,
            )
            with Horizontal(id="exp-attach-btns"):
                yield Button("Attach", id="btn-exp-attach-grid",
                              variant="primary")
                yield Button("Insert into body",
                              id="btn-exp-insert-attach")
                yield Button("Delete", id="btn-exp-remove-attach",
                              variant="error")

    def on_mount(self) -> None:
        try:
            t = self.query_one("#exp-entries-table", DataTable)
            t.add_columns("Updated", "Title")
        except NoMatches:
            return
        try:
            tat = self.query_one("#exp-attach-table", DataTable)
            tat.add_columns("Filename", "Size", "Inserted?")
        except NoMatches:
            pass
        self._refresh_entries_table()
        if self._initial_entry_id:
            entries = _load_experiments()
            for e in entries:
                if e.get("id") == self._initial_entry_id:
                    self._load_into_compose(e)
                    return

    # ─── Sub-tab gating ──────────────────────────────────────────────────

    def _apply_subtab_gating(self, *, enabled: bool) -> None:
        """Enable / disable the Compose + Attachments tabs depending
        on whether an entry is currently loaded. With the split-pane
        layout (2026-05-18) the entries list is always visible — no
        'Entries' tab to fall back to — so when disabling we leave
        `tabs.active` alone; Textual renders disabled tabs greyed
        out, which is the right visual cue that the user needs to
        pick or create an entry from the left pane first.
        """
        for tab_id in self._DEPENDENT_SUBTABS:
            try:
                pane = self.query_one(f"#{tab_id}", TabPane)
                pane.disabled = not enabled
            except NoMatches:
                continue

    # ─── Entries population ──────────────────────────────────────────────

    def _sorted_entries(self) -> "list[dict]":
        """Newest-first by `updated_at`, with natural-sort by title as
        tie-breaker. Mirrors the invariant #33 sort/lookup symmetry
        pattern — `_on_entry_selected` resolves the row key against
        the same sorted list."""
        entries = _load_experiments()

        def _key(e: dict) -> tuple:
            updated = e.get("updated_at") or ""
            title   = e.get("title") or ""
            return (updated, _natural_sort_key(title))
        return sorted(entries, key=_key, reverse=True)

    def _refresh_entries_table(self) -> None:
        """Repopulate the entries list. Trimmed 2026-05-18 to two
        columns (Updated, Title) so a narrow left pane stays readable;
        long titles overflow into a horizontal scrollbar on the
        DataTable rather than truncating with ellipsis."""
        try:
            t = self.query_one("#exp-entries-table", DataTable)
        except NoMatches:
            return
        t.clear()
        entries = self._sorted_entries()
        for e in entries:
            eid = e.get("id") or ""
            title = e.get("title") or "(untitled)"
            # Universal slash-free date ("JUL 11 2026"), date-only (pass the
            # first 10 chars so the time is dropped) — never ISO in the UI.
            updated = _history_human_dt((e.get("updated_at") or "")[:10])
            t.add_row(
                updated,
                Text(title, no_wrap=True),
                key=eid,
            )

    # ─── Compose loading / persistence ───────────────────────────────────

    def _load_into_compose(self, entry: dict) -> None:
        self._current_entry = dict(entry)
        try:
            self.query_one(
                "#exp-title-input", Input,
            ).value = entry.get("title", "")
            self.query_one(
                "#exp-tags-input", Input,
            ).value = ", ".join(entry.get("tags") or [])
            ta = self.query_one("#exp-body", TextArea)
            ta.text = entry.get("body_md", "")
        except NoMatches:
            pass
        self._apply_subtab_gating(enabled=True)
        try:
            tabs = self.query_one("#exp-tabs", TabbedContent)
            tabs.active = "exp-sub-compose"
        except (NoMatches, LookupError):
            pass
        self._refresh_attachments()
        self._mark_dirty(False)
        try:
            self.query_one("#exp-body", TextArea).focus()
        except NoMatches:
            pass

    def _mark_dirty(self, dirty: bool) -> None:
        self._dirty = dirty
        try:
            flag = self.query_one("#exp-dirty-flag", Static)
            flag.update(
                "[yellow]● unsaved[/yellow]" if dirty else "",
            )
        except NoMatches:
            pass

    def _clear_compose(self) -> None:
        """[staleguard] Drop the loaded entry + blank the Compose widgets and
        Attachments after a delete / move, so a greyed-out Compose /
        Attachments tab never keeps showing a removed entry — and, with
        `_current_entry` already None, a stray save can't write stale text
        over a different row (the rename-corruption class)."""
        self._current_entry = None
        self._apply_subtab_gating(enabled=False)
        self._mark_dirty(False)
        try:
            self.query_one("#exp-title-input", Input).value = ""
            self.query_one("#exp-tags-input", Input).value = ""
            self.query_one("#exp-body", TextArea).text = ""
        except NoMatches:
            pass
        self._refresh_attachments()

    def _collect_compose_state(self) -> "dict | None":
        if self._current_entry is None:
            return None
        try:
            title = self.query_one("#exp-title-input", Input).value
            tags_raw = self.query_one("#exp-tags-input", Input).value
            body = self.query_one("#exp-body", TextArea).text
        except NoMatches:
            return None
        tags = [t.strip() for t in (tags_raw or "").split(",")
                if t.strip()]
        entry = dict(self._current_entry)
        entry["title"] = title
        entry["body_md"] = body
        entry["tags"] = tags
        return _normalise_experiment_entry(entry, fresh=False)

    def _persist_current(self) -> bool:
        """Persist the live compose buffer back to disk. Returns True on
        success. No-op (False) if nothing to save.

        Pre-save: detects body-over-cap (1 MB) and notifies the user so
        a silent truncation in `_normalise_experiment_entry` isn't a
        surprise data-loss. Audit sweep 2026-05-18.

        Save path: dedup-by-id replaces ALL matches (not just the first
        one) so a duplicate-id entry — theoretically impossible but
        defensive against hand-edited JSON — can't survive a save.
        """
        if self._current_entry is None:
            return False
        try:
            raw_body = self.query_one("#exp-body", TextArea).text or ""
        except NoMatches:
            raw_body = ""
        if (len(raw_body.encode("utf-8", errors="replace"))
                > _EXPERIMENT_BODY_MAX_BYTES):
            try:
                self.app.notify(
                    f"Body exceeded {_EXPERIMENT_BODY_MAX_BYTES // 1000} "
                    f"KB cap — truncated on save. Split long sections "
                    f"into separate entries or move content to "
                    f"attachments.",
                    severity="warning", timeout=8,
                )
            except Exception:
                pass
        upd = self._collect_compose_state()
        if upd is None:
            return False
        entries = _load_experiments()
        target_id = upd.get("id")
        # Dedup-by-id: filter out ALL entries matching the current id
        # (defensive against a hand-edited JSON with duplicate ids;
        # pre-fix `for i, e in enumerate(...): if matched: break`
        # only replaced the first match, leaving stale duplicates on
        # disk).
        entries = [e for e in entries if e.get("id") != target_id]
        entries.append(upd)
        try:
            _save_experiments(entries)
        except OSError as exc:
            _notify_save_failure(self.app, "Experiments", exc)
            return False
        self._current_entry = upd
        _log_event(
            "experiments.save",
            eid=upd.get("id"),
            title=upd.get("title"),
            body_len=len(upd.get("body_md") or ""),
            n_tags=len(upd.get("tags") or []),
            n_refs=len(upd.get("attached_plasmid_ids") or []),
        )
        # Sweep #9 (2026-05-19): re-sync the TextArea to the
        # normalised body. If the save path truncated the body
        # (>1 MB cap), the on-screen text would otherwise still
        # show the pre-truncation content while the disk holds
        # the truncated version — every next keystroke marks
        # "dirty" and the user thinks save didn't work. Comparing
        # `raw_body` vs the normalised `body_md` tells us if a
        # mutation happened; if so, replace the TextArea contents
        # and (since `load_text` will fire an edit event) reset
        # the dirty flag.
        normalised_body = upd.get("body_md") or ""
        if normalised_body != raw_body:
            try:
                ta = self.query_one("#exp-body", TextArea)
                ta.load_text(normalised_body)
            except NoMatches:
                pass
        self._mark_dirty(False)
        self._refresh_entries_table()
        return True

    # ─── Preview render ──────────────────────────────────────────────────
    # Preview pane removed 2026-05-18 — the narrow right pane made the
    # side-by-side source/preview split too cramped (`_render_plasmid_refs`
    # is preserved for export / future re-add). Token coloring is now
    # done in-editor via `_ExperimentMarkdownTextArea` (subclass that
    # injects regex-based highlights into `_build_highlight_map`), so
    # the previously-attempted chip-strip below the TextArea is gone.
    # ─── Attachments ─────────────────────────────────────────────────────

    def _refresh_attachments(self) -> None:
        try:
            t = self.query_one("#exp-attach-table", DataTable)
        except NoMatches:
            return
        t.clear()
        # Reset the inline preview; RowHighlighted repaints it with the
        # actual image once the cursor lands on a populated row.
        self._preview_attachment(None)
        # [staleguard] clear FIRST, then bail if no entry — otherwise a
        # deselect (delete / move / project-switch) left the PREVIOUS entry's
        # attachment rows + preview on screen.
        if self._current_entry is None:
            return
        eid = self._current_entry.get("id") or ""
        d = _experiment_attach_dir(eid, create=False)
        if d is None or not d.is_dir():
            return
        body = ""
        try:
            body = self.query_one("#exp-body", TextArea).text or ""
        except NoMatches:
            pass
        try:
            files = sorted(
                d.iterdir(),
                key=lambda p: _natural_sort_key(p.name),
            )
        except OSError:
            files = []
        for p in files:
            if not p.is_file() or p.is_symlink():
                continue
            try:
                sz = p.stat().st_size
            except OSError:
                sz = 0
            inserted = "yes" if (f"]({p.name})" in body) else "no"
            t.add_row(p.name, f"{sz:,}", inserted, key=p.name)

    def _preview_attachment(self, filename: "str | None") -> None:
        """Render the highlighted image attachment inline as rich_pixels
        half-blocks (works in any terminal — no kitty/sixel/iTerm graphics
        protocol). Non-image files and render failures show a short note.
        Best-effort: never raises into the UI."""
        from rich.markup import escape as _esc
        try:
            preview = self.query_one("#exp-attach-preview", Static)
        except NoMatches:
            return
        if not filename or self._current_entry is None:
            preview.update("[dim]Select an image above to preview it here.[/]")
            return
        if os.path.splitext(str(filename))[1].lower() not in (
            ".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp",
        ):
            preview.update(
                f"[dim]{_esc(str(filename))} — not an image; no preview.[/]")
            return
        eid = self._current_entry.get("id") or ""
        d = _experiment_attach_dir(eid, create=False)
        path = (d / filename) if d is not None else None
        if path is None or not path.is_file():
            preview.update("[dim](attachment file missing)[/]")
            return
        try:
            from rich_pixels import Pixels
            size = preview.size
            cols = max(8, min(int(size.width) - 2, 100))
            rows = max(4, min(int(size.height) - 2, 14))
            # rich_pixels packs 2 image rows into each character row (upper /
            # lower half-block), so request rows*2 pixels of height.
            px = Pixels.from_image_path(str(path), resize=(cols, rows * 2))
            preview.update(px)
        except Exception as exc:
            _log.debug("attachment preview failed for %r", filename,
                       exc_info=True)
            preview.update(
                f"[dim]Can't preview {_esc(str(filename))}: "
                f"{_esc(str(exc))}[/]")

    @on(DataTable.RowHighlighted, "#exp-attach-table")
    def _on_attach_highlighted(self, event: "DataTable.RowHighlighted") -> None:
        key = event.row_key.value if event.row_key else None
        self._preview_attachment(key)

    @on(TabbedContent.TabActivated, "#exp-tabs")
    def _on_exp_tab(self, _event: "TabbedContent.TabActivated") -> None:
        # [staleguard] the Attachments "Inserted?" flag is derived from the
        # live body text; recompute it when the Attachments pane becomes
        # active so a body edit / save on the Compose tab is reflected.
        try:
            active = self.query_one("#exp-tabs", TabbedContent).active
        except NoMatches:
            return
        if active == "exp-sub-attachments":
            self._refresh_attachments()

    # ─── Event handlers ──────────────────────────────────────────────────

    @on(DataTable.RowSelected, "#exp-entries-table")
    def _on_entry_selected(self, event) -> None:
        eid = event.row_key.value if event.row_key else None
        if eid is None:
            return
        entries = _load_experiments()
        for e in entries:
            if e.get("id") == eid:
                if self._dirty and self._current_entry is not None:
                    self._persist_current()
                self._load_into_compose(e)
                return

    @on(Button.Pressed, "#btn-exp-new")
    def _on_btn_new(self, _ev) -> None:
        self.action_new_entry()

    @on(Button.Pressed, "#btn-exp-open")
    def _on_btn_open(self, _ev) -> None:
        try:
            t = self.query_one("#exp-entries-table", DataTable)
        except NoMatches:
            return
        if t.cursor_row < 0 or t.row_count == 0:
            self.app.notify("Pick a row first.", severity="warning")
            return
        # Same lookup as RowSelected
        try:
            row_key = t.coordinate_to_cell_key(_Coordinate(t.cursor_row, 0)).row_key
            eid = row_key.value
        except Exception:
            return
        if not eid:
            return
        for e in _load_experiments():
            if e.get("id") == eid:
                if self._dirty and self._current_entry is not None:
                    self._persist_current()
                self._load_into_compose(e)
                return

    @on(Button.Pressed, "#btn-exp-rename")
    def _on_btn_rename(self, _ev) -> None:
        self._rename_current()

    @on(Button.Pressed, "#btn-exp-delete")
    def _on_btn_delete(self, _ev) -> None:
        self._confirm_delete()

    @on(Button.Pressed, "#btn-exp-move")
    def _on_btn_move(self, _ev) -> None:
        self._move_current_to_project()

    @on(Button.Pressed, "#btn-exp-save")
    def _on_btn_save(self, _ev) -> None:
        self.action_save_entry()

    @on(Button.Pressed, "#btn-exp-attach")
    def _on_btn_attach(self, _ev) -> None:
        self.action_attach_image()

    @on(Button.Pressed, "#btn-exp-attach-grid")
    def _on_btn_attach_grid(self, _ev) -> None:
        self.action_attach_image()

    @on(Button.Pressed, "#btn-exp-plasmid")
    def _on_btn_plasmid(self, _ev) -> None:
        self.action_insert_plasmid()

    @on(Button.Pressed, "#btn-exp-actions")
    def _on_btn_actions(self, _ev) -> None:
        self.action_insert_action()

    @on(Button.Pressed, "#btn-exp-gel")
    def _on_btn_gel(self, _ev) -> None:
        self.action_insert_gel()

    @on(Button.Pressed, "#btn-exp-spellcheck")
    def _on_btn_spellcheck(self, _ev) -> None:
        self.action_spellcheck()

    @on(Button.Pressed, "#btn-exp-remove-attach")
    def _on_btn_remove_attach(self, _ev) -> None:
        self._remove_selected_attachment()

    @on(Button.Pressed, "#btn-exp-insert-attach")
    def _on_btn_insert_attach(self, _ev) -> None:
        self._insert_selected_attachment_into_body()

    @on(Button.Pressed, "#btn-exp-close")
    def _on_btn_close(self, _ev) -> None:
        self.action_cancel()

    @on(Button.Pressed, "#btn-exp-projects")
    def _on_btn_projects(self, _ev) -> None:
        self.action_open_projects()

    @on(TextArea.Changed, "#exp-body")
    def _on_body_changed(self, _ev) -> None:
        self._mark_dirty(True)

    @on(Input.Changed, "#exp-title-input")
    def _on_title_changed(self, _ev) -> None:
        self._mark_dirty(True)

    @on(Input.Changed, "#exp-tags-input")
    def _on_tags_changed(self, _ev) -> None:
        self._mark_dirty(True)

    # ─── Actions ─────────────────────────────────────────────────────────

    def action_cancel(self) -> None:
        """Esc / Close handler. When the compose buffer is dirty,
        opens `ExperimentUnsavedChangesModal` and routes through the
        user's choice (save / abandon / cancel). Default focus on
        Cancel so a stray Enter cannot lose work. Pre-refactor this
        auto-saved silently — surprising for users who hit Esc to
        discard an edit (2026-05-18)."""
        if not (self._dirty and self._current_entry is not None):
            self.dismiss(None)
            return

        def _on_choice(choice) -> None:
            if choice == "save":
                # Stay on screen if the save itself fails so the user
                # can fix the underlying disk error before losing
                # their work. `_persist_current` already routed the
                # OSError through `_notify_save_failure` (toast); the
                # screen survives until they pick Save again, Abandon,
                # or fix the disk.
                if self._persist_current():
                    self.dismiss(None)
            elif choice == "abandon":
                self.dismiss(None)
            # "cancel" / None → stay on screen
        self.app.push_screen(
            ExperimentUnsavedChangesModal(), callback=_on_choice,
        )

    @_action_log("app.experiments.open_projects")
    def action_open_projects(self) -> None:
        """Open the experiment-projects picker. Auto-saves the dirty
        compose buffer first so a project switch never loses notes.
        On return: refreshes the entries list (the picker mirrored
        the newly-active project's experiments into experiments.json
        before dismissing) and the project label."""
        if self._dirty and self._current_entry is not None:
            self._persist_current()
        # Capture the active project BEFORE the picker opens. The picker
        # can rename or delete the active project IN PLACE (mutate +
        # _repopulate, no dismiss) and then be closed with Close/Esc,
        # which dismisses None. Comparing against this on return lets us
        # refresh even when no explicit switch (truthy `name`) happened.
        # (2026-06-11 audit fix — the project label + entries list went
        # stale after rename/delete-of-active followed by Close/Esc,
        # because the old early-return on `not name` skipped the
        # refresh entirely.)
        prev_active = _get_active_project_name()

        def _on_picked(name) -> None:
            # The active project after the picker closed. An explicit
            # switch (truthy `name`), a rename of the active project, or
            # a delete that promoted another all change it; a pure cancel
            # leaves it equal to `prev_active`.
            new_active = name or _get_active_project_name()
            if new_active != prev_active:
                # Project identity / name changed — the compose buffer
                # belonged to the old project's set (already persisted
                # above), so drop it and rebuild the left pane against
                # the now-active project.
                self._current_entry = None
                self._apply_subtab_gating(enabled=False)
                try:
                    self.query_one(
                        "#exp-title-input", Input,
                    ).value = ""
                    self.query_one(
                        "#exp-tags-input", Input,
                    ).value = ""
                    self.query_one("#exp-body", TextArea).text = ""
                except NoMatches:
                    pass
                self._refresh_entries_table()
                self._refresh_attachments()
            # ALWAYS re-sync the label — even a pure cancel can follow a
            # rename of the active project (handled above), and this is
            # idempotent / cheap.
            try:
                self.query_one(
                    "#exp-project-name", Static,
                ).update(self._format_project_label())
            except NoMatches:
                pass
        self.app.push_screen(
            ExperimentProjectsPickerModal(), callback=_on_picked,
        )

    @_action_log("app.experiments.new_entry")
    def action_new_entry(self) -> None:
        if self._dirty and self._current_entry is not None:
            self._persist_current()
        entries = _load_experiments()
        existing_ids: set[str] = {
            e.get("id") for e in entries if e.get("id")  # type: ignore[misc]
        }
        new_id = _new_experiment_id(existing_ids)
        new_entry = _normalise_experiment_entry({
            "id": new_id,
            "title": "Untitled entry",
            "body_md": "",
            "tags": [],
        }, fresh=True)
        entries.append(new_entry)
        try:
            _save_experiments(entries)
        except OSError as exc:
            _notify_save_failure(self.app, "Experiments", exc)
            return
        _log_event("experiments.new", eid=new_id)
        self._refresh_entries_table()
        self._load_into_compose(new_entry)
        try:
            self.query_one("#exp-title-input", Input).focus()
        except NoMatches:
            pass

    @_action_log("app.experiments.save_entry")
    def action_save_entry(self) -> None:
        if self._current_entry is None:
            self.app.notify("No entry selected.", severity="warning")
            return
        if self._persist_current():
            self.app.notify("Entry saved.", timeout=3)

    def action_attach_image(self) -> None:
        if self._current_entry is None:
            self.app.notify(
                "Select or create an entry first.", severity="warning",
            )
            return

        def _on_picked(path) -> None:
            if not path:
                return
            self._attach_image_from_path(str(path))
        if _demo_web_refuse(self.app, "Attaching files"):
            return
        self.app.push_screen(ImageAttachModal(), callback=_on_picked)

    def _attach_image_from_path(self, src_path: str) -> None:
        if self._current_entry is None:
            return
        try:
            p = Path(src_path).expanduser()
        except (TypeError, ValueError):
            self.app.notify("Bad image path.", severity="error")
            return
        ok, reason = _safe_file_size_check(
            p, _EXPERIMENT_IMAGE_MAX_BYTES, "experiment image",
        )
        if not ok:
            self.app.notify(
                reason or "Image attach refused.", severity="error",
            )
            return
        try:
            data = p.read_bytes()
        except OSError as exc:
            self.app.notify(
                f"Could not read image: {exc}", severity="error",
            )
            return
        eid = self._current_entry.get("id")
        if not eid:
            return
        saved = _save_experiment_image(eid, data, p.name)
        if saved is None:
            self.app.notify(
                "Image attach failed — see logs.", severity="error",
            )
            return
        # Clipboard-paste tmp cleanup (audit sweep 2026-05-18). The
        # ImageAttachModal clipboard route writes via tempfile.mkstemp
        # with prefix `_EXPERIMENT_CLIP_TMP_PREFIX`; once the bytes
        # are copied into the entry dir the source tmp file is
        # orphaned. Unlink it best-effort. Skipped for user-picked
        # files (no prefix match), so a real file the user named
        # "exp-clip-foo.png" outside /tmp survives untouched.
        if p.name.startswith(_EXPERIMENT_CLIP_TMP_PREFIX):
            import tempfile
            try:
                if (p.is_file()
                        and str(p.parent.resolve())
                        == str(Path(tempfile.gettempdir()).resolve())):
                    p.unlink(missing_ok=True)
            except OSError:
                pass
        rel = saved.name
        try:
            ta = self.query_one("#exp-body", TextArea)
            current = ta.text
            insert = f"\n\n![{rel}]({rel})\n"
            ta.text = current + insert
        except NoMatches:
            pass
        self._mark_dirty(True)
        self._refresh_attachments()
        _log_event(
            "experiments.attach.image",
            eid=eid, filename=rel, size=len(data),
        )
        self.app.notify(f"Attached {rel}.", timeout=4)

    def action_insert_plasmid(self) -> None:
        if self._current_entry is None:
            self.app.notify("No entry selected.", severity="warning")
            return

        def _on_picked(payload) -> None:
            if payload is None:
                return
            try:
                _coll, entry_id = payload
            except (TypeError, ValueError):
                return
            if not entry_id:
                return
            try:
                ta = self.query_one("#exp-body", TextArea)
            except NoMatches:
                return
            # Single-sigil tag format (2026-05-18): `@<id>` not
            # `@plasmid:<id>`. Trailing space + refocus so the user
            # can keep typing without clicking back into the body.
            ta.insert(f"@{entry_id} ")
            ta.focus()
            self._mark_dirty(True)
            _log_event("experiments.insert.plasmid_ref",
                         eid=self._current_entry.get("id")
                              if self._current_entry else None,
                         ref=entry_id)
        self.app.push_screen(LibrarySearchModal(), callback=_on_picked)

    def action_go_to_tag(self) -> None:
        """Open the object modal for whichever tag lives under the
        cursor. Plasmid → switch active collection + load plasmid
        onto the main canvas. Gel → open `GelLibraryModal` scrolled
        to that entry. Action → open `ActionsPickerModal` scrolled
        to that catalog entry. No tag under cursor → notify.

        Cursor placement is a "containing-or-touching" test: a
        cursor immediately after the last char of a tag still
        counts as being on that tag (so the user can finish typing
        a tag, then hit Ctrl+G to inspect)."""
        try:
            ta = self.query_one(
                "#exp-body", _ExperimentMarkdownTextArea,
            )
        except NoMatches:
            return
        try:
            row, col = ta.cursor_location
            line_text = ta.document.get_line(row)
        except (AttributeError, IndexError, ValueError):
            self.app.notify(
                "No tag under cursor.", severity="warning", timeout=3,
            )
            return
        for regex, kind in (
            (_PLASMID_REF_RE, "plasmid"),
            (_ACTIONS_REF_RE, "action"),
            (_GEL_REF_RE,     "gel"),
        ):
            for m in regex.finditer(line_text):
                # Touching-end inclusive so cursor immediately after
                # the tag still counts.
                if m.start() <= col <= m.end():
                    self._open_tag(kind, m.group(1))
                    return
        self.app.notify(
            "No tag under cursor.", severity="warning", timeout=3,
        )

    @on(_ExperimentMarkdownTextArea.TagOpenRequested)
    def _on_tag_double_clicked(self, _ev) -> None:
        """Double-click in the body → same handler as Ctrl+G."""
        self.action_go_to_tag()

    def _open_tag(self, kind: str, tag_id: str) -> None:
        """Dispatch on tag kind. Auto-saves the dirty compose buffer
        first so an open-tag click can't lose user notes."""
        if not tag_id:
            return
        if self._dirty and self._current_entry is not None:
            self._persist_current()
        if kind == "plasmid":
            self._open_plasmid_ref(tag_id)
        elif kind == "gel":
            self._open_gel_ref(tag_id)
        elif kind == "action":
            self._open_action_ref(tag_id)

    def _open_plasmid_ref(self, target_id: str) -> None:
        """Resolve `target_id` across every collection on disk,
        switch the active collection if needed, dismiss the
        Experiments screen, then load the plasmid onto the main
        canvas via `_apply_record`. Notifies and stays put if the
        plasmid isn't found anywhere.

        Sweep #9 (2026-05-19): if the main canvas has unsaved
        edits, prompt before navigating away. Without this guard
        a click-through tag silently discarded the user's
        in-progress plasmid work (data loss). Same
        `UnsavedNavigateModal` pattern the `LibraryPanel._btn_back`
        path uses (line 13900).
        """
        matches = _search_collections_library(target_id, limit=10)
        chosen = None
        for m in matches:
            if m.get("id") == target_id:
                chosen = m
                break
        if chosen is None:
            self.app.notify(
                f"No plasmid `{target_id}` in any collection.",
                severity="warning",
            )
            return
        coll_name = chosen.get("collection") or ""
        entry_id = chosen.get("id") or ""

        def _do_switch_and_load() -> None:
            # Dismiss BEFORE switch+load so the user sees the loaded
            # plasmid behind the (now-gone) screen rather than us
            # trying to redraw a half-disposed widget tree.
            self.dismiss(None)
            try:
                self._switch_and_load_plasmid(coll_name, entry_id)
            except (OSError, ValueError, AttributeError):
                _log.exception(
                    "ExperimentsScreen: switch_and_load failed for %r",
                    target_id,
                )

        app = self.app
        if not getattr(app, "_unsaved", False):
            _do_switch_and_load()
            return

        def _on_unsaved_response(result: "str | None") -> None:
            if result == "save":
                do_save = getattr(app, "_do_save", None)
                if callable(do_save) and do_save():
                    _do_switch_and_load()
                # Save failed → user stays in Experiments to retry.
            elif result == "discard":
                discard = getattr(app, "_discard_changes", None)
                if callable(discard):
                    discard()
                _do_switch_and_load()
            # None → cancel; user stays in Experiments.

        app.push_screen(
            UnsavedNavigateModal(f"open plasmid `{target_id}`"),
            callback=_on_unsaved_response,
        )

    def _switch_and_load_plasmid(
        self, coll_name: str, entry_id: str,
    ) -> None:
        """Switch active collection if needed, then load the entry's
        embedded `gb_text` onto the main canvas via `_apply_record`.
        Mirrors the agent-API `set-active-collection` + `load-entry`
        pair but stays inline for the click-through fast path."""
        if (coll_name
                and coll_name != _get_active_collection_name()):
            coll = _find_collection(coll_name)
            if coll is None:
                self.app.notify(
                    f"Collection '{coll_name}' is gone.",
                    severity="warning",
                )
                return
            _set_active_collection_name(coll_name)
            plasmids = [
                dict(p) for p in (coll.get("plasmids") or [])
                if isinstance(p, dict)
            ]
            try:
                _switch_active_collection_library(plasmids)
            except (OSError, ValueError) as exc:
                _notify_save_failure(
                    self.app, "Plasmid library", exc,
                )
                return
            try:
                lib = self.app.query_one("#library", LibraryPanel)
                lib._view_mode = "plasmids"
                lib._apply_view_mode()
                lib._repopulate_plasmids()
            except NoMatches:
                pass
        # Sweep #25: helper avoids the full-library deepcopy for
        # single-id lookup.
        e = _find_library_entry_by_id(entry_id)
        if e is not None:
            gb_text = e.get("gb_text", "")
            if not gb_text:
                self.app.notify(
                    "Library entry has no embedded sequence.",
                    severity="warning",
                )
                return
            try:
                record = _gb_text_to_record(gb_text)
            except (ValueError, RuntimeError) as exc:
                _log.exception(
                    "Plasmid-ref load: parse failed for %r",
                    entry_id,
                )
                self.app.notify(
                    f"Could not load plasmid: {exc}",
                    severity="error",
                )
                return
            self.app._apply_record(record)  # type: ignore[attr-defined]
            _log_event("plasmid.ref.opened", id=entry_id)
            return
        self.app.notify(
            f"Plasmid {entry_id} not found in {coll_name}.",
            severity="warning",
        )

    def _open_gel_ref(self, gel_id: str) -> None:
        """Open `GelLibraryModal` scrolled to `gel_id`. Refuses if
        the id fails sanitisation or the gel doesn't exist."""
        safe = _sanitize_gel_id(gel_id)
        if safe is None:
            self.app.notify(
                f"`&{gel_id}` is not a valid gel id.",
                severity="warning",
            )
            return
        if _find_gel(safe) is None:
            self.app.notify(
                f"No gel with id `{safe}`. Save one from the "
                "Simulator first.",
                severity="warning",
            )
            return
        _log_event("gel.ref.opened", id=safe)
        # Sweep #9 (2026-05-19): inspect_only=True so the Load /
        # Save buttons are disabled — pre-fix Load was a silent
        # no-op because no callback was wired to consume the
        # dismiss payload.
        self.app.push_screen(
            GelLibraryModal(initial_gel_id=safe, inspect_only=True),
            callback=None,
        )

    def _open_action_ref(self, action_id: str) -> None:
        """Open `ActionsPickerModal` scrolled to `action_id`. The
        catalog accepts free-form ids so an action that isn't in
        the curated catalog just lands cursor at row 0."""
        _log_event("action.ref.opened", id=action_id)
        # Sweep #9 (2026-05-19): inspect_only=True so Insert is
        # disabled — pre-fix Insert was a silent no-op.
        self.app.push_screen(
            ActionsPickerModal(
                initial_action=action_id, inspect_only=True,
            ),
            callback=None,
        )

    def action_insert_gel(self) -> None:
        """Open `GelLibraryModal` (no current snapshot — Save button
        is disabled) and insert the picked gel as `&<id>` at the
        cursor. Mirrors the plasmid / action insert pattern: trailing
        space + refocus so the user keeps typing without clicking
        back into the body."""
        if self._current_entry is None:
            self.app.notify("No entry selected.", severity="warning")
            return

        def _on_picked(gel_id) -> None:
            if not gel_id:
                return
            try:
                ta = self.query_one(
                    "#exp-body", _ExperimentMarkdownTextArea,
                )
            except NoMatches:
                return
            ta.insert(f"&{gel_id} ")
            ta.focus()
            self._mark_dirty(True)
            _log_event("experiments.insert.gel_ref",
                         eid=self._current_entry.get("id")
                              if self._current_entry else None,
                         ref=gel_id)
        # Pass NO `current_lanes` — that disables the Save button
        # (the user opened from Experiments, not Simulator).
        self.app.push_screen(GelLibraryModal(), callback=_on_picked)

    def action_insert_action(self) -> None:
        """Open `ActionsPickerModal` and insert the picked action as
        `@actions:<id>` at the current cursor position. The catalog
        is curated but not enforced — `@actions:<custom>` typed by
        hand is just as valid (the regex `_ACTIONS_REF_RE` accepts
        any matching id).
        """
        if self._current_entry is None:
            self.app.notify("No entry selected.", severity="warning")
            return

        def _on_picked(action_id) -> None:
            if not action_id:
                return
            try:
                ta = self.query_one("#exp-body", TextArea)
            except NoMatches:
                return
            # Single-sigil tag format `!<id>` — mirrors the plasmid
            # `@<id>` flow but with `!` so the two tag kinds stay
            # visually distinct in the editor (purple vs lime).
            ta.insert(f"!{action_id} ")
            ta.focus()
            self._mark_dirty(True)
            _log_event("experiments.insert.action_ref",
                         eid=self._current_entry.get("id")
                              if self._current_entry else None,
                         ref=action_id)
        self.app.push_screen(ActionsPickerModal(), callback=_on_picked)

    def action_spellcheck(self) -> None:
        """Pyspellchecker-backed spellcheck for the active body. Masks
        non-prose markdown regions, tokenises, lists misspellings in a
        side modal; user picks Replace / Add-to-dict / Skip per row.

        Replacements are applied as whole-word substitutions; the user's
        custom dictionary persists across sessions via the
        `experiments_custom_dict` settings key.

        Sweep #26 (2026-05-25): `_spellcheck_body` runs on a worker
        thread. Pre-fix the pure-Python pyspellchecker walk over a
        500 kB body froze the UI 5–15 s with no progress indicator —
        users assumed a crash. The worker pattern shows an immediate
        "Spellchecking…" toast and posts the modal from
        `call_from_thread` when ready.
        """
        if self._current_entry is None:
            self.app.notify("No entry selected.", severity="warning")
            return
        try:
            body = self.query_one("#exp-body", TextArea).text or ""
        except NoMatches:
            return
        if not body.strip():
            self.app.notify("Nothing to spellcheck.", severity="warning")
            return
        if _get_spellcheck_engine() is None:
            self.app.notify(
                "Spellcheck engine not available "
                "(pyspellchecker missing?).",
                severity="error",
            )
            return
        # Defer the actual scan to a worker. The UI shows progress
        # feedback so the user knows the keypress registered.
        self.app.notify("Spellchecking…", timeout=2)
        self._spellcheck_worker(body)

    @work(thread=True, exclusive=True, group="spellcheck")
    def _spellcheck_worker(self, body: str) -> None:
        """Worker: pure-CPU spellcheck, post modal on UI thread."""
        try:
            misspellings = _spellcheck_body(body)
        except Exception:
            _log.exception("spellcheck worker failed")
            self.app.call_from_thread(
                self.app.notify,
                "Spellcheck failed (see splicecraft log).",
                severity="error",
            )
            return
        # Re-marshal to the UI thread for both the empty-result toast
        # and the SpellcheckModal push.
        self.app.call_from_thread(self._spellcheck_post, misspellings)

    def _spellcheck_post(
        self, misspellings: "list[tuple[str, list[str]]]",
    ) -> None:
        """UI-thread continuation after `_spellcheck_worker` finishes.
        Either notifies "no misspellings" or pushes the picker modal.
        """
        if not misspellings:
            self.app.notify("No misspellings found.", timeout=3)
            return

        def _on_done(payload) -> None:
            if not payload:
                return
            try:
                replacements, dict_additions = payload
            except (TypeError, ValueError):
                return
            if replacements:
                try:
                    ta = self.query_one("#exp-body", TextArea)
                except NoMatches:
                    return
                text = ta.text
                for orig, new in replacements.items():
                    if not orig or not new:
                        continue
                    text = re.sub(
                        rf"\b{re.escape(orig)}\b", new, text,
                    )
                ta.text = text
                self._mark_dirty(True)
            if dict_additions:
                cur = _get_setting("experiments_custom_dict", []) or []
                if not isinstance(cur, list):
                    cur = []
                added = 0
                for w in dict_additions:
                    if isinstance(w, str) and w and w not in cur:
                        cur.append(w)
                        added += 1
                if added:
                    _set_setting("experiments_custom_dict", cur)
                    _clear_spellcheck_engine()
            n_repl = len(replacements or {})
            n_add  = len(dict_additions or [])
            if n_repl or n_add:
                parts: "list[str]" = []
                if n_repl:
                    parts.append(f"{n_repl} replaced")
                if n_add:
                    parts.append(f"{n_add} added to dictionary")
                _log_event(
                    "experiments.spellcheck.applied",
                    eid=self._current_entry.get("id")
                          if self._current_entry else None,
                    n_replaced=n_repl, n_added=n_add,
                )
                self.app.notify(", ".join(parts), timeout=4)
        self.app.push_screen(
            SpellcheckModal(misspellings), callback=_on_done,
        )

    # ─── Rename + delete + attachments helpers ───────────────────────────

    def _rename_current(self) -> None:
        if self._current_entry is None:
            try:
                t = self.query_one("#exp-entries-table", DataTable)
            except NoMatches:
                return
            if t.cursor_row < 0 or t.row_count == 0:
                self.app.notify(
                    "Pick a row first.", severity="warning",
                )
                return
            try:
                row_key = t.coordinate_to_cell_key(_Coordinate(t.cursor_row, 0)).row_key
                eid = row_key.value
            except Exception:
                return
            for e in _load_experiments():
                if e.get("id") == eid:
                    # Load the FULL entry into the compose widgets — not just
                    # `_current_entry` — so the subsequent _persist_current
                    # rebuilds body + tags from the real record instead of the
                    # EMPTY widgets, which silently wiped them. [staleguard]
                    self._load_into_compose(e)
                    break
        if self._current_entry is None:
            return
        current_title = self._current_entry.get("title") or ""

        def _on_new_title(new_title) -> None:
            if not new_title:
                return
            if self._current_entry is None:
                return
            self._current_entry["title"] = new_title
            # If the compose view is loaded, mirror the title input.
            try:
                self.query_one(
                    "#exp-title-input", Input,
                ).value = new_title
            except NoMatches:
                pass
            self._persist_current()
        self.app.push_screen(
            ExperimentRenameModal(current_title),
            callback=_on_new_title,
        )

    def _move_current_to_project(self) -> None:
        """Move the selected entry to another project — the GUI side of the
        `move-experiment` endpoint. Resolves the entry cursor-first (matching
        Delete), opens a destination-project picker, then relocates the entry
        out of the active project's mirror into the chosen project. Unsaved
        edits to the entry are persisted first so the moved copy carries the
        latest body (the move reads from disk)."""
        eid: "str | None" = None
        try:
            t = self.query_one("#exp-entries-table", DataTable)
            if t.row_count > 0 and t.cursor_row >= 0:
                try:
                    row_key = t.coordinate_to_cell_key(
                        _Coordinate(t.cursor_row, 0)).row_key
                    eid = row_key.value
                except Exception:
                    eid = None
        except NoMatches:
            eid = None
        if not eid and self._current_entry is not None:
            eid = self._current_entry.get("id")
        if not eid:
            self.app.notify("Pick an entry first.", severity="warning")
            return
        active = _get_active_project_name() or ""
        dests = [n for p in _load_experiment_projects()
                 if (n := (p.get("name") or "")) and n != active]
        if not dests:
            self.app.notify(
                "No other project to move into — make one via Projects first.",
                severity="warning")
            return

        def _picked(dest) -> None:
            if not isinstance(dest, str) or not dest:
                return
            if (self._dirty and self._current_entry is not None
                    and self._current_entry.get("id") == eid):
                self._persist_current()
            if self._commit_move_entry_to_project(eid, dest):
                if (self._current_entry is not None
                        and self._current_entry.get("id") == eid):
                    self._clear_compose()
                self._refresh_entries_table()
                self.app.notify(f"Moved entry to '{dest}'.",
                                severity="information")
            else:
                self.app.notify(
                    "Move failed — entry not found in the active project.",
                    severity="warning")
        self.app.push_screen(
            _PrimerMoveCopyModal("move", dests, 1, item_singular="entry",
                                 item_plural="entries", dest_label="project"),
            callback=_picked)

    def _commit_move_entry_to_project(self, eid: str, dest: str) -> bool:
        """Relocate notebook entry ``eid`` from the active project to ``dest``,
        atomically. One `_save_experiment_projects` writes both projects, then
        `_save_experiments` re-mirrors the live `experiments.json` to the
        active project (now minus the entry). The attachment dir is id-keyed
        and project-independent, so it needs no move. Returns False (no disk
        change) if the entry or a project is missing, or on save failure."""
        try:
            projs = _load_experiment_projects()
            active = _get_active_project_name() or ""
            src_p = next((p for p in projs
                          if (p.get("name") or "") == active), None)
            dst_p = next((p for p in projs
                          if (p.get("name") or "") == dest), None)
            if src_p is None or dst_p is None:
                return False
            src_entries = src_p.get("experiments") or []
            idx = next((i for i, e in enumerate(src_entries)
                        if e.get("id") == eid), None)
            if idx is None:
                return False
            dst_entries = dst_p.setdefault("experiments", [])
            if any(e.get("id") == eid for e in dst_entries):
                return False            # already there (shouldn't happen)
            entry = src_entries.pop(idx)
            dst_entries.append(entry)
            _save_experiment_projects(projs)
            # Source IS the active project — re-mirror the live experiments.json
            # to its now-smaller entry list so the moved row drops out of view.
            _save_experiments([e for e in src_entries if isinstance(e, dict)])
            _log_event("experiments.move", eid=eid, to=dest, via="gui")
            return True
        except (OSError, RuntimeError) as exc:
            _notify_save_failure(self.app, "Experiments", exc)
            return False

    def _confirm_delete(self) -> None:
        # Sweep #9 (2026-05-19): cursor-first resolution. Pre-fix this
        # preferred `_current_entry` (= loaded into compose) over the
        # entries-table cursor, which surfaced a user-visible bug:
        # cursor on row A, loaded B, click Delete → deleted B.
        # Arrow-key cursor moves don't fire `_on_entry_selected`
        # (that's RowSelected = Enter), so the two states drift
        # apart. Now the cursor wins; only when there's no cursor
        # at all do we fall back to the loaded entry.
        eid: "str | None" = None
        title: str = "(untitled)"
        try:
            t = self.query_one("#exp-entries-table", DataTable)
            cur_eid: "str | None" = None
            if t.row_count > 0 and t.cursor_row >= 0:
                try:
                    row_key = t.coordinate_to_cell_key(
                        _Coordinate(t.cursor_row, 0),
                    ).row_key
                    cur_eid = row_key.value
                except Exception:
                    cur_eid = None
            if cur_eid:
                eid = cur_eid
                for e in _load_experiments():
                    if e.get("id") == eid:
                        title = e.get("title") or title
                        break
            elif self._current_entry is not None:
                eid = self._current_entry.get("id")
                title = self._current_entry.get("title") or title
            else:
                self.app.notify(
                    "Pick a row first.", severity="warning",
                )
                return
        except NoMatches:
            # No entries table visible (shouldn't happen on this
            # screen, but fall through to loaded-entry just in case).
            if self._current_entry is not None:
                eid = self._current_entry.get("id")
                title = self._current_entry.get("title") or title
            else:
                return
        if not eid:
            return
        # Sweep #9 (2026-05-19): capture cursor row BEFORE the confirm
        # modal pushes (similar pattern to LibraryPanel's sticky delete
        # cursor, line ~13997). The confirm modal holds focus, so this
        # row index is still authoritative when the callback fires.
        cur_row_before = -1
        try:
            t = self.query_one("#exp-entries-table", DataTable)
            cur_row_before = (
                t.cursor_row if t.cursor_row is not None else -1
            )
        except NoMatches:
            pass

        def _on_confirmed(yes) -> None:
            if not yes:
                return
            entries = [
                e for e in _load_experiments() if e.get("id") != eid
            ]
            try:
                _save_experiments(entries)
            except OSError as exc:
                _notify_save_failure(self.app, "Experiments", exc)
                return
            _delete_experiment_attach_dir(eid)
            _log_event("experiments.delete", eid=eid)
            if (self._current_entry is not None
                    and self._current_entry.get("id") == eid):
                self._clear_compose()
            self._refresh_entries_table()
            # Restore cursor onto the row just below the deleted one
            # (or the new last row if we deleted from the bottom).
            # Pre-fix the table re-populate jumped cursor to row 0.
            try:
                t = self.query_one("#exp-entries-table", DataTable)
                if t.row_count > 0:
                    new_row = max(0, min(
                        cur_row_before, t.row_count - 1,
                    ))
                    t.move_cursor(row=new_row)
            except NoMatches:
                pass
            self.app.notify(f"Deleted: {title}", timeout=4)
        self.app.push_screen(
            ExperimentDeleteConfirmModal(
                title=f"Delete: {title}?",
                body=(
                    "  This removes the entry and all its attached "
                    "images.\n\n"
                    "  [dim]A backup of experiments.json is kept; "
                    "image files are deleted from disk.[/dim]"
                ),
            ),
            callback=_on_confirmed,
        )

    def _insert_selected_attachment_into_body(self) -> None:
        if self._current_entry is None:
            return
        try:
            t = self.query_one("#exp-attach-table", DataTable)
        except NoMatches:
            return
        if t.row_count == 0 or t.cursor_row < 0:
            self.app.notify("Pick an attachment.", severity="warning")
            return
        try:
            row_key = t.coordinate_to_cell_key(_Coordinate(t.cursor_row, 0)).row_key
            name = row_key.value
        except Exception:
            return
        if not name:
            return
        try:
            ta = self.query_one("#exp-body", TextArea)
        except NoMatches:
            return
        ta.text = ta.text + f"\n\n![{name}]({name})\n"
        self._mark_dirty(True)
        self._refresh_attachments()
        try:
            tabs = self.query_one("#exp-tabs", TabbedContent)
            tabs.active = "exp-sub-compose"
        except (NoMatches, LookupError):
            pass

    def _remove_selected_attachment(self) -> None:
        if self._current_entry is None:
            return
        try:
            t = self.query_one("#exp-attach-table", DataTable)
        except NoMatches:
            return
        if t.row_count == 0 or t.cursor_row < 0:
            self.app.notify("Pick an attachment.", severity="warning")
            return
        try:
            row_key = t.coordinate_to_cell_key(_Coordinate(t.cursor_row, 0)).row_key
            name = row_key.value
        except Exception:
            return
        if not name:
            return
        eid = self._current_entry.get("id") or ""
        d = _experiment_attach_dir(eid, create=False)
        if d is None:
            return
        p = d / name
        # Symlink refusal: never follow a symlink to delete.
        if p.is_symlink() or not p.is_file():
            self.app.notify(
                "Refused: attachment is missing or unsafe.",
                severity="error",
            )
            return

        def _on_confirmed(yes) -> None:
            if not yes:
                return
            try:
                p.unlink()
            except OSError as exc:
                self.app.notify(
                    f"Could not remove {name}: {exc}",
                    severity="error",
                )
                return
            _log_event(
                "experiments.remove.image", eid=eid, filename=name,
            )
            self._refresh_attachments()
            self.app.notify(f"Removed {name}", timeout=3)
        self.app.push_screen(
            ExperimentDeleteConfirmModal(
                title=f"Remove {name}?",
                body=(
                    "  Deletes the image file from disk.\n\n"
                    "  [dim]Markdown references in the body are NOT "
                    "auto-removed — clean them up manually.[/dim]"
                ),
            ),
            callback=_on_confirmed,
        )


# ── Synthesis composer (linear gene-synthesis workbench) ──────────────────────
#
# A full-screen workbench for penning a linear DNA fragment ready for
# commercial gene synthesis. Linear, single-row, horizontally-scrolling
# editor — same per-base style as SequencePanel (feature stripes +
# restriction overlay + AA translation) but with cursor-based editing
# instead of EditSeqDialog (direct typing, click-to-place-cursor,
# Backspace / Delete). Saves as a linear plasmid into the active
# collection via the standard `LibraryPanel.add_entry` flow.
#
# Document model: load a linear entry, edit, Save → silent replace by
# id. Save As / Rename / New available from the toolbar.

# Cap chosen so synthesis stays interactive on a single render pass —
# commercial gene synthesis tops out at ~10 kb for most vendors, with
# extreme cases up to ~30 kb. 50 kb is generous headroom that still
# keeps `_build_seq_text` snappy on a single chunk.
_SYNTHESIS_MAX_BP: int = 50_000

# Allowed bases for programmatic insertion at the cursor — the broader
# set that includes IUPAC ambiguity codes. Restriction sites (AvaI =
# CYCGRG, DraI = TTTAAA, etc.) and feature-library sequences may
# legitimately carry IUPAC, so the Ctrl+R / featlib-Insert paths use
# this lenient set. Matches the AddFeatureModal validation set so a
# fragment composed here round-trips through the feature library
# without surprises.
_SYNTHESIS_TYPEABLE_BASES: frozenset[str] = frozenset("ACGTRYWSMKBDHVN")

# Bases the user can type DIRECTLY on the keyboard. Restricted to
# A/C/G/T/N — the only bases a commercial gene-synthesis vendor will
# universally accept as-is. IUPAC ambiguity codes are still permitted
# via restriction-site / feature-library inserts (where the ambiguity
# is part of an established biological convention), but typing them
# at the cursor is gated off to prevent accidental ambiguity slipping
# into a fragment that's about to ship for synthesis.
_SYNTHESIS_KEYBOARD_BASES: frozenset[str] = frozenset("ACGTN")

# 20 standard amino acids + '*' for stop. The ProteinEditor's
# keyboard typing path filters against this set; non-AA letters
# (B, J, O, U, X, Z) and any other character are rejected.
_PROTEIN_AA_ALPHABET: frozenset[str] = frozenset("ACDEFGHIKLMNPQRSTVWY*")

# Cap on protein length so the eventual back-translated DNA stays
# under _SYNTHESIS_MAX_BP. Each AA → 3 DNA bases plus a TAA stop
# elsewhere, so divide by 3.
_PROTEIN_MAX_AA: int = _SYNTHESIS_MAX_BP // 3

# Feature stamped on a restriction site inserted via Synthesis ▸ Insert
# Site. Hot pink so the added site pops against the regular feature
# palette; `protein_bind` type + a directional arrow (feature strand)
# match how the user annotates cut sites by hand. Full 6-digit hex —
# Rich rejects `#RGB` shorthand (`rich.errors.MissingStyle`).
_RESTR_SITE_FEATURE_COLOR: str = "#FF69B4"

# Sweep #15 (2026-05-20) — color palette for protein motif feature
# types. The DNA feature library uses `_GB_TYPE_COLORS` keyed on the
# GenBank type vocabulary; protein motifs have their own type
# ontology (Tag, Signal, Linker, …) that wouldn't match GenBank, so
# they get a dedicated map. Colors picked to be distinguishable on
# the muted-grey AA-row background and read OK against the bold-
# white AA letters above. Sweep #16 (2026-05-21): the keys here are
# the FALLBACK for any user-added motif that doesn't carry its own
# `color` field — built-in motifs each get their own distinct
# `color` in `_PROTEIN_MOTIFS` below. Key spelling matches the
# `feature_type` strings in `_PROTEIN_MOTIFS` (the pre-sweep #16
# "2A peptide" key never matched the "2A" data, so every 2A motif
# silently fell back to the Motif default; fix the key spelling and
# the fallback works).
_PROTEIN_FEATURE_TYPE_COLORS: dict[str, str] = {
    "Tag":      "#3B82F6",  # blue — affinity / epitope tags
    "Signal":   "#F59E0B",  # amber — NLS / NES / signal peptides
    "Linker":   "#6B7280",  # grey — flexible / rigid linkers
    "Cleavage": "#DC2626",  # red — protease sites
    "2A":       "#10B981",  # green — self-cleaving 2A
    "Motif":    "#A855F7",  # purple — start codon / stop / other
}

class SynthesisEditor(Widget):
    """Linear horizontal-scroll DNA editor with per-base feature /
    restriction-site / AA-translation overlays.

    State model (mirrors SequencePanel's vocabulary for grep symmetry):
      * ``_seq``       — the bases.
      * ``_feats``     — feature dicts (start, end, label, type, color, …).
      * ``_cursor_pos``— 0..len(seq) — sits *between* bases (text-editor
                         convention). 0 = before the first base; n = after
                         the last base.
      * ``_user_sel``  — drag-or-Shift+arrow selection range, half-open
                         (start, end). None when nothing is selected.

    Rendering: passes ``line_width = len(seq) + 1`` to ``_build_seq_text``
    so the whole sequence renders as a single chunk on one row group
    (feature lanes above + DNA row + AA lanes below). The resulting
    Text is dropped into a ``Static`` inside a ``ScrollableContainer`` —
    the wide content surfaces a native horizontal scrollbar.

    Editing semantics:
      * Insert at cursor — bases right of cursor shift right; features
        whose start ≥ cursor shift; features whose end > cursor shift.
        A feature whose end == cursor extends to include the new base
        (the typical "extend the feature I'm appending to" behaviour).
      * Backspace — deletes one base left of cursor; cursor moves left.
        Features clip to the surviving span; zero-length features drop.
      * Delete — deletes one base right of cursor; cursor stays put.
      * Selection delete — Backspace / Delete with a non-empty
        selection deletes the selected range.

    Click model:
      * Click on DNA → place cursor at that bp.
      * Drag → build selection from anchor → cursor.
      * Shift+click → extend selection from cursor to click.

    Messages emitted:
      * ``SynthesisEditor.Changed`` — fires after any mutation (insert,
        delete, replace) so the parent screen can mark the buffer dirty
        and refresh the bp-count label. NOT fired on cursor-only moves.
    """

    DEFAULT_CSS = """
    SynthesisEditor {
        height: 1fr;
        background: #0a0a0a;
    }
    SynthesisEditor:focus-within { background: #0c0c0c; }
    /* `overflow-x: auto` surfaces a horizontal scrollbar when the
       rendered Static is wider than the viewport (the
       `line_width = len(seq) + 1` render produces a single-line
       chunk that grows with the fragment); `overflow-y: hidden`
       suppresses the vertical scrollbar because the editor
       pre-pads the Text top/bottom for vertical centering, so
       there's no off-viewport content above or below to scroll to.
       Without `overflow-y: hidden` Textual would draw a vertical
       scrollbar that does nothing — the inserted blank-line pad
       inflates the content height past the viewport.
       Sweep-on-this-feature: `scrollbar-gutter: stable` reserves
       the column even when the bar disappears, so the centered
       layout doesn't jitter as the user pans. */
    #syn-scroll {
        height: 1fr;
        overflow-x: auto;
        overflow-y: hidden;
        scrollbar-gutter: stable;
    }
    /* `width: auto` lets the Static size to its rendered content
       (the no-wrap Rich Text). Without this the Static would
       inherit the parent width (`1fr`) and the no-wrap renderer
       would just clip the right edge instead of letting the
       container scroll. */
    #syn-view {
        width: auto;
        height: auto;
    }
    """

    class Changed(Message):
        """Sent on any sequence / feature mutation."""

    class Loaded(Message):
        """Sent by `load()` on a wholesale buffer replacement (new /
        load fragment, optimize output, etc.). The SynthesisScreen uses
        it to reset the DNA undo/redo history so Ctrl+Z can't reach
        across a document boundary into a different fragment's edits."""

    class CursorMoved(Message):
        """Sent on cursor or selection change (no dirty side-effect)."""

    class FeatureEditRequested(Message):
        """Sweep #29 (2026-05-26): Enter on the synth editor while
        the cursor sits inside a feature posts this up so the
        SynthesisScreen can push `FeatureEditModal` for that
        feature. `idx` indexes into `self._feats` at post time —
        the screen handler MUST re-validate the index against
        the current `_feats` length before consuming it (a Changed
        event could have fired between post and dispatch)."""
        def __init__(self, idx: int):
            self.idx = int(idx)
            super().__init__()

    def __init__(self, **kwargs) -> None:
        super().__init__(**kwargs)
        self._seq: str = ""
        self._feats: list[dict] = []
        self._cursor_pos: int = 0
        self._user_sel: "tuple[int, int] | None" = None
        self._sel_anchor: int = -1
        # Zoom-out overview: bases per column. 1 = normal 1:1 editor;
        # >1 = compressed structural view (features/sites as blocks) so
        # the whole linear fragment fits on screen, mirroring the main
        # app's linear-view −/+/0 zoom. View state only (not persisted).
        self._zoom_bp_per_col: int = 1
        # Per-base overlays mirror the SequencePanel toggles.
        self._re_highlight: "dict | None" = None
        self._aa_highlight: "dict | None" = None
        # Restriction-enzyme-name click → recognition+spacer+cut highlight
        # (mirrors SequencePanel). `_last_resite_click` is stamped by
        # `_lane_feature_at` when a click lands on a resite bar/label;
        # `_mouse_down_resite` carries it from mouse-down to the click so
        # the highlight is built once, on click (not mid-drag).
        self._last_resite_click: "dict | None" = None
        self._mouse_down_resite: "dict | None" = None
        # Drag-to-select state — pattern lifted from SequencePanel.
        self._drag_start_bp: int = -1
        self._has_dragged: bool = False
        self._mouse_button_held: bool = False
        self._last_was_drag: bool = False
        # Rows of blank-line padding currently prepended to the
        # rendered Text for DNA-strand vertical centring. Set by
        # `_refresh_view`; consulted by future hover/AA-resolution code
        # that needs to translate viewport-y → DNA-row.
        self._pad_above_rows: int = 0
        # Cells of left padding currently prepended to each line for
        # horizontal centring of short sequences. Set by
        # `_apply_horizontal_centering`; consulted by `_click_to_bp`
        # and `_ensure_cursor_visible` so cursor / click math lands at
        # the right bp under any centring offset.
        self._pad_left_cols: int = 0
        # ── Restriction-site overlay (R key) ─────────────────────────
        # Mirrors the main SequencePanel's `show_restr` toggle: pressing
        # R scans `self._seq` and lays resite/recut lane art over the
        # fragment. `_restr_feats` is the scanned overlay (reassigned,
        # never mutated in place, so the render caches invalidate);
        # `_restr_scan_seq` is the sequence that overlay was scanned from
        # so `_refresh_view` re-scans lazily only when the bases change.
        self._show_restr_overlay: bool = False
        self._restr_feats: list[dict] = []
        self._restr_scan_seq: "str | None" = None
        # Merged (user + restriction) feature list handed to the
        # renderer + click resolver. Rebuilt only when either input list
        # is reassigned (id changes) so `_build_seq_text`'s id-keyed
        # caches keep hitting while the overlay is on. See `_display_feats`.
        self._merged_feats: list[dict] = []
        self._merged_sig: "tuple[int, int] | None" = None
        # Feature index picked at mouse-down on a feature's lane art, so
        # `on_click` can highlight it (single click) or open its editor
        # (double click) without re-resolving the geometry. -1 = the
        # press did not land on lane art (plain DNA-row / marker click).
        self._mouse_down_lane_idx: int = -1

    def compose(self) -> ComposeResult:
        with ScrollableContainer(id="syn-scroll"):
            yield Static("", id="syn-view", markup=False)

    def on_mount(self) -> None:
        self._refresh_view()
        try:
            self.query_one("#syn-scroll", ScrollableContainer).can_focus = True
        except NoMatches:
            pass

    # ── Public API ─────────────────────────────────────────────────────────

    def load(self, seq: str, feats: "list[dict] | None" = None) -> None:
        """Replace the buffer with `seq` + `feats`. Resets cursor + sel."""
        self._seq = str(seq or "")
        self._feats = [dict(f) for f in (feats or [])]
        self._cursor_pos = 0
        self._user_sel = None
        self._sel_anchor = -1
        self._zoom_bp_per_col = 1     # a fresh buffer returns to 1:1
        self._re_highlight = None
        self._aa_highlight = None
        self._last_resite_click = None
        self._mouse_down_resite = None
        # A wholesale replacement must re-scan the restriction overlay
        # (if on) against the new bases and drop the stale merged list.
        self._restr_scan_seq = None
        self._merged_sig = None
        self._refresh_view()
        # Tell the screen to reset undo/redo — a loaded fragment starts
        # a fresh edit history (Ctrl+Z must not reach the prior buffer).
        self.post_message(self.Loaded())

    def get_state(self) -> "tuple[str, list[dict]]":
        """Return a deep-ish copy of (seq, feats) for snapshotting /
        comparison. The seq is immutable; feats are dict-copied so
        downstream mutation can't leak into the live state."""
        return self._seq, [dict(f) for f in self._feats]

    def snapshot(self) -> dict:
        """Full editor state for the undo/redo stack — bases, features
        (deep-copied), cursor, and selection. `feats` are copied so a
        later in-editor mutation can't retroactively rewrite history."""
        return {
            "seq": self._seq,
            "feats": [dict(f) for f in self._feats],
            "cursor": self._cursor_pos,
            "user_sel": self._user_sel,
        }

    def apply_snapshot(self, snap: dict) -> None:
        """Restore a snapshot from `snapshot()` WITHOUT emitting Changed
        / Loaded (so an undo/redo doesn't itself push a history entry or
        reset the stack). Reassigns `_feats` so the id-keyed render
        caches invalidate."""
        if not isinstance(snap, dict):
            return
        self._seq = str(snap.get("seq", ""))
        self._feats = [dict(f) for f in (snap.get("feats") or [])]
        n = len(self._seq)
        cur = int(snap.get("cursor", 0))
        # Keep the marker "hop-on" positions (-1 / n+1) valid.
        self._cursor_pos = max(-1, min(n + 1, cur))
        sel = snap.get("user_sel")
        if (isinstance(sel, tuple) and len(sel) == 2
                and 0 <= sel[0] < sel[1] <= n):
            self._user_sel = (int(sel[0]), int(sel[1]))
        else:
            self._user_sel = None
        self._sel_anchor = -1
        self._zoom_bp_per_col = 1     # undo/restore lands you at 1:1
        self._re_highlight = None
        self._restr_scan_seq = None
        self._merged_sig = None
        self._refresh_view()
        self._ensure_cursor_visible()

    # ── Render ─────────────────────────────────────────────────────────────

    # Visual flank markers — reflect anti-parallel DNA polarity. Top
    # strand reads 5'→3' left-to-right, bottom strand reads 3'→5'
    # left-to-right (it's the reverse complement, drawn under the
    # top strand). Width is 3 chars on each side. Stored as constants
    # so `_click_to_bp` / `_ensure_cursor_visible` /
    # `_wrap_with_53_markers` all agree on the same offset.
    _FLANK_MARKER_TOP_LEFT:    str = "5'-"
    _FLANK_MARKER_TOP_RIGHT:   str = "-3'"
    _FLANK_MARKER_BOT_LEFT:    str = "3'-"
    _FLANK_MARKER_BOT_RIGHT:   str = "-5'"
    _FLANK_MARKER_WIDTH:       int = 3
    _FLANK_MARKER_STYLE:       str = "bold #4CC4FF"
    # Back-compat aliases (older test fixtures reference these names).
    _FLANK_MARKER_5: str = "5'-"
    _FLANK_MARKER_3: str = "-3'"

    def _wrap_with_53_markers(self, txt: Text) -> Text:
        """Strip the line-number gutter from the rendered Text and
        inject DNA polarity markers on BOTH strand rows; pad every
        non-DNA row with equivalent-width whitespace at the same
        column so feature-lane / AA-row glyphs stay column-aligned
        with the bases.

        The line-number gutter (`num_w + 2` chars of ` 1 ` etc.) is
        dropped because the synthesis editor always renders ONE chunk
        — one row group of bases — and the leading "1" gutter adds
        no information at that single-chunk granularity.

        Anti-parallel DNA — top strand 5'→3', bottom strand 3'→5'
        when read left-to-right under standard orientation:

            5'-ATGCATGC-3'
            3'-TACGTACG-5'

        Markers are visual-only — they NEVER enter ``self._seq``.
        ``_user_sel = (0, n)`` (Ctrl+A) leaves them untouched because
        the renderer paints highlight on bp coordinates, and the
        markers sit OUTSIDE that range. Clicks on the markers
        collapse to bp 0 / bp n by `_click_to_bp`'s clamp.
        """
        if not self._seq:
            return txt
        n = len(self._seq)
        num_w = len(str(n)) if n else 1
        gutter = num_w + 2   # column where the bases start in each line
        dna_row = self._dna_top_row_offset()
        # The bottom strand sits directly below the top strand. Per
        # `_chunk_layout`'s "+2" in the prefix arithmetic, the DNA
        # pair occupies (above_rows, above_rows + 1) — the
        # complement bases get drawn under the top strand bases at
        # row index `dna_row + 1`.
        bot_row = dna_row + 1
        try:
            lines = txt.split("\n")
        except (AttributeError, TypeError):
            return txt
        if dna_row >= len(lines):
            return txt
        # Sweep #28 (extended 2026-05-26): paint the matching hyphen
        # with reverse-video whenever the cursor sits at the sequence
        # boundary — both the natural end-of-sequence position
        # (`cur == 0` / `cur == n`, reachable by ← / → / End / Home)
        # AND the explicit "hop-on" position (`cur == -1` / `cur == n+1`,
        # reachable by Home/End-from-boundary). Before this change the
        # natural past-last-base position rendered an invisible cursor:
        # the per-base reverse loop in `_build_seq_text` iterates
        # [0, n) so `cur == n` skipped every base, and the hyphen
        # highlight only fired for the hop-on positions. The user
        # then saw the cursor "vanish" pressing → off the last base.
        # By also highlighting the hyphen at the natural boundary,
        # the cursor visually mounts the hyphen any time the user is
        # at the very start or very end. At `cur == 0` the per-base
        # reverse still paints base[0] in addition (the cursor
        # visually straddles the hyphen→base boundary — a clearer
        # cue than either alone); at `cur == n` only the hyphen
        # reverses because there is no base[n].
        cur = self._cursor_pos
        cursor_on_5p = (cur <= 0)
        cursor_on_3p = (cur >= n)

        def _marker_with_cursor(marker_text: str, cursor_char_idx: int
                                 ) -> Text:
            """Render the marker with reverse-video on the cursor
            character. `cursor_char_idx` is the index within
            `marker_text` to highlight (the hyphen).

            Defensive: clamps `cursor_char_idx` into `[0, len-1]`
            and short-circuits on empty `marker_text`. The constants
            are hardcoded to 3-char strings (`5'-`, `-3'`), but a
            subclass / test fixture could legitimately override them
            and we'd rather degrade to "no reverse" than raise on a
            render-path slice."""
            if not marker_text:
                return Text("", style=self._FLANK_MARKER_STYLE,
                             no_wrap=True)
            t = Text(marker_text, style=self._FLANK_MARKER_STYLE,
                     no_wrap=True)
            idx = max(0, min(int(cursor_char_idx),
                              len(marker_text) - 1))
            # Apply reverse video on the hyphen so it pops as the
            # cursor. The base style is preserved underneath via
            # Textual's style composition.
            t.stylize("reverse", idx, idx + 1)
            return t

        if cursor_on_5p:
            # 5'- : cursor is on the trailing `-` (index 2).
            top_l = _marker_with_cursor(self._FLANK_MARKER_TOP_LEFT, 2)
        else:
            top_l = Text(self._FLANK_MARKER_TOP_LEFT,
                          style=self._FLANK_MARKER_STYLE, no_wrap=True)
        if cursor_on_3p:
            # -3' : cursor is on the leading `-` (index 0).
            top_r = _marker_with_cursor(self._FLANK_MARKER_TOP_RIGHT, 0)
        else:
            top_r = Text(self._FLANK_MARKER_TOP_RIGHT,
                          style=self._FLANK_MARKER_STYLE, no_wrap=True)
        bot_l = Text(self._FLANK_MARKER_BOT_LEFT,
                      style=self._FLANK_MARKER_STYLE, no_wrap=True)
        bot_r = Text(self._FLANK_MARKER_BOT_RIGHT,
                      style=self._FLANK_MARKER_STYLE, no_wrap=True)
        marker_w   = self._FLANK_MARKER_WIDTH
        blank_pre  = Text(" " * marker_w, no_wrap=True)
        blank_post = Text(" " * marker_w, no_wrap=True)
        new_lines: list[Text] = []
        for i, line in enumerate(lines):
            if len(line) < gutter:
                # Short / blank line (the inter-chunk gap row at the
                # end of a chunk renders as empty) — keep as-is so
                # we don't manufacture spurious markers.
                new_lines.append(line)
                continue
            # Drop the line-number gutter — `line[gutter:]` is the
            # bases (DNA row) / lane glyphs (lane rows) / AA letters
            # (AA rows), all column-aligned with one another.
            stripped = line[gutter:]
            if i == dna_row:
                new_lines.append(top_l + stripped + top_r)
            elif i == bot_row:
                new_lines.append(bot_l + stripped + bot_r)
            else:
                new_lines.append(blank_pre + stripped + blank_post)
        return Text("\n", no_wrap=True).join(new_lines)

    def _viewport_width(self) -> int:
        """Current `#syn-scroll` width in cells, or 0 if not mounted /
        sized yet. Used by `_horizontal_center_pad` to decide whether
        to centre or left-anchor the rendered Text."""
        try:
            scroll = self.query_one("#syn-scroll", ScrollableContainer)
            return max(0, int(scroll.size.width))
        except (NoMatches, AttributeError):
            return 0

    def _content_width(self) -> int:
        """Natural width of the marker-wrapped render: ``marker_w + n
        + marker_w``. Used by `_horizontal_center_pad`."""
        if not self._seq:
            # Placeholder text varies in length; use its display width
            # so the centring pad lands the placeholder mid-viewport.
            return 64
        return 2 * self._FLANK_MARKER_WIDTH + len(self._seq)

    def _horizontal_center_pad(self) -> int:
        """Cells of left padding to prepend to each line so that
        content narrower than the viewport sits at the horizontal
        centre. Returns 0 when content is at least as wide as the
        viewport (the natural left-anchored layout — the user pans
        right via the horizontal scrollbar)."""
        vp_w = self._viewport_width()
        c_w  = self._content_width()
        if vp_w <= 0 or c_w >= vp_w:
            return 0
        return (vp_w - c_w) // 2

    def _apply_horizontal_centering(self, txt: Text) -> Text:
        """Prepend `_horizontal_center_pad` spaces to every line of
        ``txt`` so a short fragment sits centred in the viewport.
        Long fragments fall through unchanged (the natural left-
        anchored layout enables horizontal scrolling). Stashes the
        applied pad in ``_pad_left_cols`` so click resolution can
        subtract it to land cursors at the right bp."""
        pad = self._horizontal_center_pad()
        self._pad_left_cols = pad
        if pad <= 0:
            return txt
        try:
            lines = txt.split("\n")
        except (AttributeError, TypeError):
            return txt
        pad_text = Text(" " * pad, no_wrap=True)
        return Text("\n", no_wrap=True).join(
            pad_text + line for line in lines
        )

    def _viewport_height(self) -> int:
        """Current `#syn-scroll` height in rows, or 0 if not mounted /
        sized yet. Used by `_refresh_view` to decide how many blank
        lines to pre-pend so the DNA strand lands at viewport
        vertical center."""
        try:
            scroll = self.query_one("#syn-scroll", ScrollableContainer)
            return max(0, int(scroll.size.height))
        except (NoMatches, AttributeError):
            return 0

    def _display_feats(self) -> list[dict]:
        """The feature list actually handed to the renderer + click
        resolver: user features, plus the restriction-site overlay when
        the R toggle is on. The merged list is rebuilt only when either
        input's identity changes (both are reassigned-not-mutated per
        sacred invariant #4), so `_build_seq_text`'s id-keyed caches keep
        hitting across cursor moves while the overlay is displayed."""
        if not (self._show_restr_overlay and self._restr_feats):
            return self._feats
        sig = (id(self._feats), id(self._restr_feats))
        if sig != self._merged_sig:
            # User features first so `_pack_features_2d`'s newest-on-top
            # walk keeps the user's own annotations closest to the DNA;
            # the resite/recut overlay stacks above them.
            self._merged_feats = self._feats + self._restr_feats
            self._merged_sig = sig
        return self._merged_feats

    def _feat_index(self, feat: dict) -> int:
        """Index of `feat` (by identity) in the user feature list, or -1.
        Restriction-overlay dicts live in `_restr_feats`, not `_feats`, so
        a click on a resite bar resolves to -1 (not an editable feature)."""
        for i, f in enumerate(self._feats):
            if f is feat:
                return i
        return -1

    def _dna_top_row_offset(self) -> int:
        """Row index of the DNA top strand within the rendered
        `_build_seq_text` output (chunk 0). Per `_chunk_layout`, the
        per-chunk row layout is:
            above_rows  -- feature lanes above
            2           -- DNA top + bottom strand
            below_rows  -- feature lanes below
            1           -- inter-chunk gap
        So the DNA top strand sits at row index `above_rows` within
        the chunk. With a single-chunk render (our `line_width = n + 1`
        configuration) that's the absolute row index inside the
        rendered Text. Returns 0 on empty / failure.
        """
        if not self._seq:
            return 0
        try:
            chunks_layout, _pf_dna2, _pf_lanes = _chunk_layout(
                self._seq, self._display_feats(), len(self._seq) + 1,
            )
        except (TypeError, ValueError, IndexError):
            return 0
        if not chunks_layout:
            return 0
        # chunks_layout[i] = (chunk_start, chunk_end, groups,
        #                     above_rows, below_rows)
        _cs, _ce, _grp, above_rows, _below = chunks_layout[0]
        return int(above_rows)

    def _pad_above_for_centering(self, *, base_row: int) -> int:
        """Blank-line count to prepend to the rendered Text so that
        ``base_row`` lands at the viewport's vertical centre. Returns
        0 if the viewport isn't sized yet (first paint before
        layout) — the Text falls back to top-anchored which still
        renders correctly; a subsequent `on_resize` re-render fills
        in the centring once Textual has a real height."""
        vp_h = self._viewport_height()
        if vp_h <= 0:
            return 0
        return max(0, vp_h // 2 - int(base_row))

    # ── Zoom-out overview (bp / column) ───────────────────────────────────
    #
    # Mirrors the main app's linear-view −/+/0 zoom, but for the DNA
    # editor (always linear for now). At `_zoom_bp_per_col > 1` the editor
    # renders a compressed structural strip — features + restriction sites
    # as coloured blocks with names where they fit, a DNA baseline, and a
    # bp ruler — so the whole fragment fits without scrolling. Clicking a
    # column jumps back to 1:1 at that base (`_compressed_click`).

    def _zoom_max(self) -> int:
        """Largest useful bp/col — the smallest power of 2 at which the
        whole fragment fits the viewport width. Floors at 1 (already
        fits)."""
        n = len(self._seq)
        vp = self._viewport_width()
        if n <= 0 or vp <= 2:
            return 1
        z = 1
        # Double until the column count (ceil(n/z)) fits the viewport.
        while (n + z - 1) // z > vp:
            z *= 2
            if z >= n:            # one column holds everything — stop
                break
        return max(1, z)

    def _set_zoom(self, z: int) -> None:
        """Set bp/col, clamped to [1, _zoom_max()], and re-render."""
        z = max(1, min(int(z), self._zoom_max()))
        if z == self._zoom_bp_per_col:
            return
        self._zoom_bp_per_col = z
        # Leaving zoom-out clears any drag state; entering it drops the
        # resite viz (it's a 1:1-only per-base highlight).
        self._re_highlight = None
        self._refresh_view()
        self.post_message(self.CursorMoved())

    def _zoom_step(self, factor: float) -> None:
        """`factor > 1` zooms OUT (more bp/col), `< 1` zooms IN. Steps in
        powers of 2 so levels are 1, 2, 4, 8, …."""
        cur = self._zoom_bp_per_col
        if factor > 1:
            self._set_zoom(max(2, cur * 2))
        else:
            self._set_zoom(max(1, cur // 2))

    def _build_compressed_text(self) -> "tuple[Text, int]":
        """Render the compressed zoom-out overview. Returns
        ``(text, dna_row_index)`` where ``dna_row_index`` is the row (in
        the returned Text, before any centring pad) holding the DNA
        baseline — used for vertical centring. Each column spans
        ``_zoom_bp_per_col`` bases."""
        from rich.text import Text as _Text
        seq = self._seq
        n = len(seq)
        z = max(1, self._zoom_bp_per_col)
        ncols = max(1, (n + z - 1) // z)
        feats = self._display_feats()

        def _col_span(f):
            s = max(0, int(f.get("start", 0)))
            e = min(n, int(f.get("end", 0)))
            if e <= s:
                return None
            return (s // z, max(s // z, (e - 1) // z))   # inclusive cols

        fwd, rev = [], []
        for f in feats:
            cs = _col_span(f)
            if cs is None:
                continue
            (rev if int(f.get("strand", 1) or 0) < 0 else fwd).append((f, cs))

        def _pack(items):
            # Greedy lane packing by start column; newest-added feature
            # (later in list) prefers a higher lane, so user feats (which
            # come first) sit closest to the DNA — same intent as the 1:1
            # view's `_pack_features_2d`.
            lanes: "list[list]" = []
            for f, (c0, c1) in sorted(items, key=lambda t: t[1][0]):
                for lane in lanes:
                    if lane[-1][2] < c0:
                        lane.append((f, c0, c1))
                        break
                else:
                    lanes.append([(f, c0, c1)])
            return lanes

        fwd_lanes = _pack(fwd)
        rev_lanes = _pack(rev)

        def _lane_row(lane) -> "_Text":
            cells = [(" ", "")] * ncols
            for f, c0, c1 in lane:
                col = _safe_feature_color(str(f.get("color") or ""),
                                          "color(244)")
                block_style = f"black on {col}"
                for c in range(max(0, c0), min(ncols, c1 + 1)):
                    cells[c] = ("█", col)
                # Overlay the name on the block when it fits.
                label = str(f.get("label") or f.get("type") or "")
                width = c1 - c0 + 1
                if label and width >= 3:
                    show = label[:width]
                    off = c0 + (width - len(show)) // 2
                    for i, ch in enumerate(show):
                        if 0 <= off + i < ncols:
                            cells[off + i] = (ch, block_style)
            row = _Text(no_wrap=True, overflow="crop")
            for ch, style in cells:
                row.append(ch, style=style or None)
            return row

        rows: "list[_Text]" = []
        # A one-line hint header so the controls are discoverable.
        hint = _Text(
            f"zoom {z} bp/col   ·   -/+ zoom · 0 reset · click a "
            f"column to edit there",
            style="dim italic", no_wrap=True, overflow="crop")
        rows.append(hint)
        # Forward lanes: topmost (farthest from DNA) first.
        for lane in reversed(fwd_lanes):
            rows.append(_lane_row(lane))
        dna_row_index = len(rows)
        # DNA baseline — dim rule, cursor column marked.
        cur_col = (max(0, min(n, self._cursor_pos))) // z
        base = _Text(no_wrap=True, overflow="crop")
        for c in range(ncols):
            if c == cur_col:
                base.append("┃", style="bold")
            else:
                base.append("─", style="dim")
        rows.append(base)
        # Reverse lanes: closest to DNA first.
        for lane in rev_lanes:
            rows.append(_lane_row(lane))
        # Ruler: bp positions at spaced ticks.
        ruler_cells = [" "] * ncols
        tick = max(8, ncols // 8)
        c = 0
        while c < ncols:
            lbl = str(c * z)
            for i, ch in enumerate(lbl):
                if c + i < ncols:
                    ruler_cells[c + i] = ch
            c += max(tick, len(lbl) + 1)
        rows.append(_Text("".join(ruler_cells), style="dim", no_wrap=True,
                          overflow="crop"))
        out = _Text("\n", no_wrap=True).join(rows)
        return out, dna_row_index

    def _compressed_click(self, screen_x: int) -> None:
        """A click in zoom-out mode jumps back to 1:1 at the clicked
        column's first base (mirrors the preview's 'click a block → edit
        there')."""
        try:
            view = self.query_one("#syn-view", Static)
        except NoMatches:
            return
        col = (screen_x - view.region.x) - self._pad_left_cols
        if col < 0:
            return
        bp = max(0, min(len(self._seq), col * self._zoom_bp_per_col))
        self._zoom_bp_per_col = 1
        self._user_sel = None
        self._sel_anchor = -1
        self._re_highlight = None
        self.set_cursor(bp)     # refreshes + posts CursorMoved

    def _refresh_view(self) -> None:
        try:
            view = self.query_one("#syn-view", Static)
        except NoMatches:
            return
        n = len(self._seq)
        if n == 0:
            placeholder = (
                "(empty fragment — start typing bases, "
                "Ctrl+V (or your terminal's paste) to paste, "
                "or use Insert site)"
            )
            empty = Text(
                placeholder,
                style="dim italic",
                no_wrap=True,
                overflow="crop",
            )
            # Horizontal centring of the placeholder: prepend spaces
            # so it lands mid-viewport. Same `_pad_left_cols` plumbing
            # as the with-seq case but using the placeholder's own
            # width.
            vp_w = self._viewport_width()
            if vp_w > 0 and len(placeholder) < vp_w:
                pad_left = (vp_w - len(placeholder)) // 2
                empty = Text(" " * pad_left, no_wrap=True) + empty
                self._pad_left_cols = pad_left
            else:
                self._pad_left_cols = 0
            pad_above = self._pad_above_for_centering(base_row=0)
            if pad_above > 0:
                empty = Text("\n" * pad_above, no_wrap=True) + empty
            view.update(empty)
            return
        # Restriction overlay (R toggle): re-scan only when the bases
        # changed since the last scan (cursor-only refreshes skip it).
        # The scanner is LRU-cached so a re-scan of an unchanged
        # sequence is ~O(1); this keeps the overlay current as the user
        # edits without hooking every mutation site.
        if self._show_restr_overlay and self._restr_scan_seq != self._seq:
            self._rescan_restr()
        # Zoom-out overview (bp/col > 1): render the compressed structural
        # strip instead of the per-base view so the whole fragment fits.
        if self._zoom_bp_per_col > 1:
            try:
                ztxt, dna_row = self._build_compressed_text()
            except (TypeError, ValueError, IndexError):
                _log.exception("SynthesisEditor: compressed render failed; "
                                "reverting to 1:1")
                self._zoom_bp_per_col = 1
            else:
                # Centre on the COMPRESSED column count (not len(seq)) —
                # `_apply_horizontal_centering` keys off `_content_width`
                # which is the 1:1 width, so it's inlined here.
                z = self._zoom_bp_per_col
                ncols = max(1, (n + z - 1) // z)
                vp_w = self._viewport_width()
                pad_left = (vp_w - ncols) // 2 if vp_w > ncols else 0
                self._pad_left_cols = pad_left
                if pad_left > 0:
                    lines = ztxt.split("\n")
                    pt = Text(" " * pad_left, no_wrap=True)
                    ztxt = Text("\n", no_wrap=True).join(
                        pt + ln for ln in lines)
                # `dna_row` already counts the hint header + fwd lanes.
                pad = self._pad_above_for_centering(base_row=dna_row)
                if pad > 0:
                    ztxt = Text("\n" * pad, no_wrap=True) + ztxt
                self._pad_above_rows = pad
                view.update(ztxt)
                return
        display_feats = self._display_feats()
        # One chunk = one row group, no wrap. `_build_seq_text` produces
        # the feature lanes + DNA + AA lanes for the whole sequence.
        try:
            txt = _build_seq_text(
                self._seq, display_feats,
                line_width=n + 1,
                user_sel=self._user_sel,
                cursor_pos=self._cursor_pos,
                re_highlight=self._re_highlight,
                aa_highlight=self._aa_highlight,
                viewport_y_range=None,
            )
        except (TypeError, ValueError, IndexError):
            # Defence-in-depth: a malformed feature dict from a
            # hostile .gb load shouldn't kill the editor. Surface a
            # plain-text fallback so the user can still see + fix it.
            _log.exception("SynthesisEditor: _build_seq_text failed; "
                            "rendering plain seq")
            txt = Text(self._seq, no_wrap=True, overflow="crop")
        # Inject 5'-/-3' (top) and 3'-/-5' (bottom) flanking markers
        # on the DNA strand rows; pad every other row with equivalent
        # whitespace at the same column so feature-lane / AA-row
        # glyph alignment with the bases survives. `_user_sel = (0, n)`
        # (Ctrl+A) doesn't touch the markers because the renderer
        # paints highlights on bp coordinates, and the markers sit
        # OUTSIDE that range — the selection visual covers DNA bases
        # only by construction.
        txt = self._wrap_with_53_markers(txt)
        # Horizontally centre sequences narrower than the viewport;
        # wider sequences fall through to the natural left-anchored
        # layout that pairs with horizontal scrolling. Pad value is
        # stashed on `_pad_left_cols` so cursor / click resolution
        # below subtracts the same offset.
        txt = self._apply_horizontal_centering(txt)
        # Vertical centring of the DNA strand: prepend blank lines so
        # the DNA top-strand row lands at the viewport's vertical
        # centre. Padding is recomputed each refresh because feature
        # density (`above_rows`) and viewport height both vary over
        # the editor's lifetime. The horizontal scrollbar is unaffected
        # — blank lines are width-0, so the rendered content's natural
        # width is still the no-wrap one-line render.
        dna_row = self._dna_top_row_offset()
        pad = self._pad_above_for_centering(base_row=dna_row)
        if pad > 0:
            txt = Text("\n" * pad, no_wrap=True) + txt
        # Stash the pad value so `_click_to_bp` can subtract it from
        # the click's content-y before resolving — without this, a
        # click on the DNA row would compute the wrong column because
        # the viewport-x→content-x mapping is unaffected by padding
        # (vertical pad doesn't shift columns) but the Y-anchor used
        # by future hover/AA features would be wrong. Click resolution
        # only uses X today so the stash is forward-compat.
        self._pad_above_rows = pad
        view.update(txt)

    def on_resize(self, _event) -> None:
        """Re-render on container resize so the centring padding is
        recomputed against the new viewport height. Cheap — the chunk
        layout cache hits on the same (seq, feats, line_width) key."""
        # A narrower terminal shrinks the max useful zoom-out; clamp so
        # the overview always fits rather than overflowing into a scroll.
        if self._zoom_bp_per_col > 1:
            self._zoom_bp_per_col = min(self._zoom_bp_per_col,
                                        self._zoom_max())
        self._refresh_view()

    # ── Cursor + selection arithmetic ─────────────────────────────────────

    def _clamp_cursor(self) -> None:
        self._cursor_pos = max(0, min(len(self._seq), self._cursor_pos))

    def _feature_at_cursor(self) -> int:
        """Return index of the smallest enclosing feature at the
        current cursor position, or -1 if no feature contains the
        cursor.

        Smallest-enclosing rule matches the main-canvas
        `_smallest_enclosing_feature` convention — a tiny annotation
        inside a parent CDS wins focus over the surrounding CDS so
        the user can click into the inner feature without the outer
        one stealing the open-edit affordance. Ties (equal span)
        are broken by insertion order (first match wins) so the
        behaviour is deterministic across re-renders.

        Cursor at the marker boundaries (`-1` / `n+1` from sweep
        #28's hop-on cursor) returns -1: those positions sit
        OUTSIDE any feature span by construction. Same for the
        natural end-of-sequence position (`cur == n`) since the
        feature half-open interval `[start, end)` excludes `end`.
        """
        cur = self._cursor_pos
        n = len(self._seq)
        if not (0 <= cur < n):
            return -1
        # Smallest-enclosing search — sort candidates by span then
        # by original index for stable ordering.
        best_idx = -1
        best_span = -1
        for i, f in enumerate(self._feats):
            try:
                s = int(f.get("start", 0))
                e = int(f.get("end",   0))
            except (TypeError, ValueError):
                continue
            if not (s <= cur < e):
                continue
            span = e - s
            if best_idx < 0 or span < best_span:
                best_idx = i
                best_span = span
        return best_idx

    def set_cursor(self, pos: int, *, extend_sel: bool = False) -> None:
        n = len(self._seq)
        # Any keyboard cursor move / selection-extend reverts the
        # restriction-site highlight (mirrors SequencePanel: an arrow key
        # clears the RE viz). Cheap no-op when nothing is highlighted.
        self._re_highlight = None
        # Sweep #28: extended cursor range [-1, n+1] to allow the
        # cursor to "hop onto" the 5'- / -3' hyphen markers. -1 means
        # "on the 5' hyphen, about to prepend"; n+1 means "on the 3'
        # hyphen, about to append". Typing at -1 inserts at position
        # 0; typing at n+1 inserts at position n. The renderer
        # (`_wrap_with_53_markers`) paints the cursor on the
        # appropriate hyphen when pos is on the boundary. The legacy
        # in-range [0, n] semantics are preserved for every existing
        # caller — the new boundary positions are opt-in by passing
        # -1 / n+1 explicitly (arrow keys reach them naturally).
        #
        # IMPORTANT exception: when `extend_sel=True`, clamp to
        # [0, n] so a selection can't extend onto a marker. Markers
        # aren't selectable (they're rendering chrome, not part of
        # the sequence); shift+arrow at the boundary should be a
        # no-op, not "select the hyphen".
        if extend_sel:
            pos = max(0, min(n, int(pos)))
        else:
            pos = max(-1, min(n + 1, int(pos)))
        if extend_sel:
            # Direction-aware anchor pinning for a FRESH extension
            # (no active user_sel yet). The cursor visually OCCUPIES
            # base[cursor_pos] — `_build_seq_text` paints reverse-
            # video on that base index — so a naïve anchor at
            # cursor_pos for a shift+left gives
            # half-open (pos, anchor) = (cursor_pos - 1, cursor_pos),
            # which highlights ONLY base[cursor_pos - 1], skipping
            # the base the user thinks they're on. Pinning anchor
            # at cursor_pos + 1 for left-extension fixes that: the
            # range (cursor_pos - 1, cursor_pos + 1) covers BOTH
            # base[cursor_pos - 1] AND base[cursor_pos]. Shift+right
            # works as-is with anchor = cursor_pos because the
            # natural (cursor_pos, cursor_pos + 1) already covers
            # base[cursor_pos]. Subsequent shift-arrows leave the
            # anchor alone — only the FIRST extension in a fresh
            # cursor position picks the anchor.
            if self._user_sel is None:
                if pos < self._cursor_pos:
                    # Extending LEFT — anchor at the right edge of
                    # the cursor base so the half-open coord
                    # includes base[cursor_pos].
                    self._sel_anchor = min(n, self._cursor_pos + 1)
                else:
                    # Extending RIGHT (or no movement) — anchor at
                    # cursor_pos; half-open (cursor_pos, pos)
                    # naturally covers base[cursor_pos] when
                    # pos > cursor_pos.
                    self._sel_anchor = self._cursor_pos
            elif self._sel_anchor < 0:
                # Defensive — user_sel is set but anchor isn't.
                # Shouldn't normally happen, but fall back to cursor.
                self._sel_anchor = self._cursor_pos
            anchor = self._sel_anchor
            lo, hi = sorted((anchor, pos))
            self._user_sel = (lo, hi) if lo != hi else None
        else:
            self._user_sel = None
            self._sel_anchor = -1
        self._cursor_pos = pos
        self._refresh_view()
        self._ensure_cursor_visible()
        self.post_message(self.CursorMoved())

    def _ensure_cursor_visible(self) -> None:
        """Scroll the container horizontally so the cursor column is
        in view. Mirrors SequencePanel._ensure_cursor_visible's intent
        but for the horizontal axis (since we never wrap).

        Column origin after the row-marker drop + 5'- marker insert +
        horizontal-centring pad:
            target_col = pad_left + FLANK_MARKER_WIDTH + cursor_pos
        When the content is wider than the viewport the centring pad
        is 0 (the natural left-anchored layout), so the formula
        collapses to ``FLANK_MARKER_WIDTH + cursor_pos``.
        """
        if self._zoom_bp_per_col > 1:
            return   # zoom-out fits the whole fragment; nothing to scroll
        try:
            scroll = self.query_one("#syn-scroll", ScrollableContainer)
        except NoMatches:
            return
        target_col = (self._pad_left_cols
                       + self._FLANK_MARKER_WIDTH
                       + self._cursor_pos)
        try:
            vp_w = max(1, int(scroll.size.width))
            cur_x = int(scroll.scroll_x)
        except (AttributeError, TypeError):
            return
        margin = max(4, vp_w // 6)
        if target_col < cur_x + margin:
            scroll.scroll_to(x=max(0, target_col - margin), animate=False)
        elif target_col > cur_x + vp_w - margin:
            scroll.scroll_to(
                x=max(0, target_col - vp_w + margin), animate=False,
            )

    # ── Click → bp ────────────────────────────────────────────────────────

    def _click_to_bp(self, screen_x: int, screen_y: int) -> int:
        """Map a screen click to a base position. Returns the bp index
        (0..len(seq)) — the column-within-sequence is interpreted as a
        cursor *position* (between bases), so a click on column 0 lands
        cursor at bp 0 (before the first base) and a click past the
        last base lands cursor at len(seq)."""
        if not self._seq:
            return 0
        try:
            view = self.query_one("#syn-view", Static)
        except NoMatches:
            return -1
        view_region = view.region
        if view_region.width == 0:
            return -1
        # Column within the rendered Text. `view.region.x` is the
        # screen-x of the content's column 0, and Textual reports it
        # ALREADY OFFSET by the horizontal scroll (it goes negative as
        # you pan right — e.g. region.x = viewport_left - scroll_x), so
        # `screen_x - region.x` is the content-local column directly.
        # (A prior `+ scroll_x` here double-counted the scroll, so a
        # click after panning right resolved past the sequence end and
        # missed — reported 2026-07-08.)
        col = screen_x - view_region.x
        n = len(self._seq)
        # Subtract horizontal-centring pad AND the 5'- marker (3 chars)
        # so a click on the very first base lands at bp 0. Clicks on
        # the centring pad / 5'- marker collapse to bp 0; clicks past
        # the -3' marker collapse to bp n. The line-number gutter was
        # stripped by `_wrap_with_53_markers` so no `num_w + 2` term.
        bp_col = col - (self._pad_left_cols + self._FLANK_MARKER_WIDTH)
        if bp_col < 0:
            return 0
        if bp_col >= n:
            return n
        return bp_col

    def _lane_feature_at(self, screen_x: int, screen_y: int
                         ) -> "tuple[int, int]":
        """If (screen_x, screen_y) lands on a feature's lane art — the
        bar / label rows drawn above (fwd) or below (rev) the DNA
        strand — return ``(feat_idx, bp)`` where ``feat_idx`` indexes
        ``self._feats`` and ``bp`` is the clicked base. Returns
        ``(-1, -1)`` when the click is on the DNA strand, a marker, or
        empty space (so the caller falls back to plain cursor placement).

        Single-chunk geometry (the editor renders with
        ``line_width = n + 1``), so there is no wrap / rotation to undo —
        the click maps straight onto `_chunk_layout`'s chunk-0 lane
        stack. Mirrors the main SequencePanel's `_chunk_glyph_owners`
        rectangle-fill: a feature owns the full
        ``(footprint_rows × bp_range)`` box, so a click on its bar,
        label, or CDS AA-row all resolve to it. A click on a restriction
        overlay cell (`type == "resite"`) stamps `_last_resite_click` (for
        the enzyme-name highlight) and returns -1 — those live in
        `_restr_feats`, not `_feats`."""
        n = len(self._seq)
        if n == 0:
            return -1, -1
        # Includes the restriction overlay when it's on, so enzyme names
        # are clickable even when the fragment has no real features.
        display = self._display_feats()
        if not display:
            return -1, -1
        try:
            view = self.query_one("#syn-view", Static)
        except NoMatches:
            return -1, -1
        reg = view.region
        if reg.width == 0 or reg.height == 0:
            return -1, -1
        # Column within the sequence content (drop the left-centring pad
        # + the 3-char 5'- marker), matching `_click_to_bp`. `reg.x` /
        # `reg.y` are the content's on-screen origin, ALREADY offset by
        # the scroll (they go negative as you pan right), so we must NOT
        # add `scroll_x` again — doing so double-counted the pan and made
        # a click after scrolling right miss every feature (reported
        # 2026-07-08). `overflow-y` is hidden, so there's no vertical
        # scroll term to add either.
        bp_col = (screen_x - reg.x) - (
            self._pad_left_cols + self._FLANK_MARKER_WIDTH)
        if bp_col < 0 or bp_col >= n:
            return -1, -1
        # Row within the marker-wrapped, vertically-centred Text (drop
        # the blank-line vertical-centring pad). `_wrap_with_53_markers`
        # preserves the row count, so this indexes straight into
        # `_build_seq_text`'s chunk-0 output.
        render_row = (screen_y - reg.y) - self._pad_above_rows
        if render_row < 0:
            return -1, -1
        try:
            chunks_layout, _p2, _pl = _chunk_layout(
                self._seq, display, n + 1)
        except (TypeError, ValueError, IndexError):
            return -1, -1
        if not chunks_layout:
            return -1, -1
        _cs, _ce, groups, above_rows, below_rows = chunks_layout[0]
        above_p, below_p, _ar, _br = groups
        # Row dispatch (top → bottom): above lanes, DNA pair, below lanes.
        if render_row < above_rows:
            # Above stack is emitted highest-first; packed_row counts
            # from the DNA strand upward (0 = closest to DNA).
            packed_row = above_rows - 1 - render_row
            placements = above_p
        elif render_row < above_rows + 2:
            return -1, -1   # the two DNA-strand rows are not lane art
        elif render_row < above_rows + 2 + below_rows:
            packed_row = render_row - (above_rows + 2)
            placements = below_p
        else:
            return -1, -1
        # Which placed feature's (rows × bp) rectangle covers this cell?
        for f, bottom_row in placements:
            height = _feat_stack_height(f)
            if not (bottom_row <= packed_row < bottom_row + height):
                continue
            fs = int(f.get("start", 0))
            fe = int(f.get("end", 0))
            if f.get("type") == "resite":
                # Restriction site: clickable across the recognition bar
                # AND the (often wider) `(EnzymeName)` label span, so
                # clicking the name highlights the site — mirrors the main
                # SequencePanel's `_chunk_glyph_owners` label widening.
                # `_resite_label_abs_span` returns INCLUSIVE columns.
                lo, hi = fs, fe
                ls, le = _resite_label_abs_span(f, 0, n + 1)
                lo = min(lo, ls)
                hi = max(hi, le + 1)
                if lo <= bp_col < hi:
                    self._last_resite_click = f
                    return -1, -1   # handled as a resite, not a feature
                continue
            if fs <= bp_col < fe:
                idx = self._feat_index(f)
                if idx >= 0:
                    return idx, bp_col
        return -1, -1

    def _select_feature_span(self, idx: int, cursor_bp: int = -1) -> None:
        """Highlight the whole feature at `idx` as a copyable selection
        (``_user_sel = (start, end)``) and park the cursor inside it, so
        Enter opens its editor and Ctrl+C copies its bases. Mirrors the
        main SequencePanel's `select_feature_range` from a lane click."""
        if not (0 <= idx < len(self._feats)):
            return
        f = self._feats[idx]
        s = max(0, int(f.get("start", 0)))
        e = min(len(self._seq), int(f.get("end", 0)))
        if e <= s:
            return
        self._user_sel = (s, e)
        self._sel_anchor = s
        # Cursor on the clicked base when it's inside the span, else the
        # feature's first base — either way inside [s, e) so
        # `_feature_at_cursor` (Enter) resolves to this feature.
        if s <= cursor_bp < e:
            self._cursor_pos = cursor_bp
        else:
            self._cursor_pos = s
        self._refresh_view()
        self.post_message(self.CursorMoved())

    def _dna_row_bp(self, screen_x: int, screen_y: int) -> int:
        """bp for a click that lands ON a DNA-strand row (top or bottom),
        else -1. The 5'/-3' markers sit on those rows (so a marker click
        still resolves to bp 0 / n). Marker-free rows — the feature
        lanes, the AA-translation lane, and the vertical-centring blank
        pad above/below the strands — return -1 so a click OR a drag
        there can't move the cursor or start a phantom selection. Only
        the sequence itself is a valid cursor/selection surface; feature
        lanes are handled by `_lane_feature_at` (whole-feature highlight)."""
        if not self._seq:
            return 0
        try:
            view = self.query_one("#syn-view", Static)
        except NoMatches:
            return -1
        reg = view.region
        if reg.width == 0 or reg.height == 0:
            return -1
        render_row = (screen_y - reg.y) - self._pad_above_rows
        above = self._dna_top_row_offset()
        # The DNA pair occupies rows `above` (top strand) + `above + 1`
        # (bottom strand). Anything else is lane art / markless padding.
        if render_row not in (above, above + 1):
            return -1
        return self._click_to_bp(screen_x, screen_y)

    # ── Mouse handlers ────────────────────────────────────────────────────

    def on_mouse_down(self, event: MouseDown) -> None:
        if event.button != 1:
            return
        # Zoom-out overview: a click jumps back to 1:1 at that column
        # (handled in `on_click` after the button release so a double-fire
        # is avoided). Suppress all 1:1 selection machinery here.
        if self._zoom_bp_per_col > 1:
            return
        # Ctrl = cross-terminal alias for Shift (many terminals eat
        # shift+click) — mirrors SequencePanel's `ext = shift or ctrl`.
        # `getattr` so a synthetic test event without `.ctrl` still works.
        ext = bool(getattr(event, "shift", False)
                   or getattr(event, "ctrl", False))
        self._mouse_down_lane_idx = -1
        self._mouse_down_resite = None
        self._last_resite_click = None
        # Feature lane-art / resite click. `_lane_feature_at` returns the
        # feature index for a real feature and (as a side effect) stamps
        # `_last_resite_click` when the cell is a restriction-site
        # bar/name. Resolve BEFORE the plain bp mapping so a click on lane
        # art doesn't collapse to a bare cursor. A drag is suppressed for
        # lane/resite clicks; `on_click` finishes the job.
        lane_idx, lane_bp = self._lane_feature_at(
            event.screen_x, event.screen_y)
        # Restriction-enzyme-name click → highlight recognition+spacer+cut
        # (built in `on_click`, like SequencePanel: leave cursor/selection
        # untouched here so a plain click owns the result). Not on extend.
        if self._last_resite_click is not None and not ext:
            self._mouse_down_resite = self._last_resite_click
            self._mouse_button_held = True
            self._drag_start_bp = -1
            self._has_dragged = False
            return
        if lane_idx >= 0 and not ext:
            self._mouse_down_lane_idx = lane_idx
            self._mouse_button_held = True
            self._drag_start_bp = -1
            self._has_dragged = False
            self._select_feature_span(lane_idx, lane_bp)
            return
        # Row-aware: only a click on the DNA strand starts a cursor move /
        # drag. A click on a marker-free lane / blank pad returns -1 and
        # is ignored — no phantom selection (reported 2026-07-08).
        bp = self._dna_row_bp(event.screen_x, event.screen_y)
        if bp < 0:
            return
        self._mouse_button_held = True
        self._drag_start_bp = bp
        self._has_dragged = False
        self._re_highlight = None      # a base click clears the resite viz
        # Shift/Ctrl+down extends selection from the current anchor.
        if ext and self._cursor_pos >= 0:
            if self._sel_anchor < 0:
                self._sel_anchor = self._cursor_pos
            lo, hi = sorted((self._sel_anchor, bp))
            self._user_sel = (lo, hi) if lo != hi else None
        else:
            self._user_sel = None
            self._sel_anchor = bp
        self._cursor_pos = bp
        self._refresh_view()
        self.post_message(self.CursorMoved())

    def on_mouse_move(self, event: MouseMove) -> None:
        if not self._mouse_button_held or self._drag_start_bp < 0:
            return
        bp = self._click_to_bp(event.screen_x, event.screen_y)
        if bp < 0:
            return
        if bp != self._drag_start_bp:
            self._has_dragged = True
            self._re_highlight = None      # a drag-select clears the viz
            lo, hi = sorted((self._drag_start_bp, bp))
            self._user_sel = (lo, hi) if lo != hi else None
            self._cursor_pos = bp
            self._refresh_view()
            self.post_message(self.CursorMoved())

    def on_mouse_up(self, event: MouseUp) -> None:
        if event.button != 1:
            return
        self._last_was_drag = self._has_dragged
        self._mouse_button_held = False
        self._drag_start_bp = -1
        self._has_dragged = False

    def on_click(self, event: Click) -> None:
        # Zoom-out overview: click a column → jump to 1:1 there.
        if self._zoom_bp_per_col > 1:
            self._compressed_click(event.screen_x)
            return
        if self._last_was_drag:
            self._last_was_drag = False
            self._mouse_down_lane_idx = -1
            self._mouse_down_resite = None
            return
        # Restriction-enzyme-name click → highlight recognition + spacer +
        # cut, computed from the sequence adjacent to the cut (the shared
        # `_build_resite_highlight` handles Type IIS spacer/overhang). The
        # renderer already paints `_re_highlight`. A pure visualization —
        # not a copyable selection (matches SequencePanel).
        resite = self._mouse_down_resite
        self._mouse_down_resite = None
        if resite is not None:
            self._re_highlight = _build_resite_highlight(
                len(self._seq), resite)
            self._user_sel = None
            self._sel_anchor = -1
            self._refresh_view()
            self.post_message(self.CursorMoved())
            return
        # Feature lane-art click resolved at mouse-down. The whole
        # feature is already highlighted; a double-click additionally
        # opens its editor (mirrors the main canvas' click-to-select +
        # Enter-to-edit, folded into a double-click here since the synth
        # editor has no sidebar to Enter from).
        lane_idx = self._mouse_down_lane_idx
        self._mouse_down_lane_idx = -1
        if lane_idx >= 0:
            if event.chain >= 2 and 0 <= lane_idx < len(self._feats):
                self.post_message(self.FeatureEditRequested(lane_idx))
            return
        # Row-aware (see on_mouse_down): a click off the DNA strand does
        # not move the cursor.
        bp = self._dna_row_bp(event.screen_x, event.screen_y)
        if bp < 0:
            return
        # Plain click — place cursor, clear selection + resite viz
        # (mouse_down already handled shift/ctrl+click extend).
        if not (getattr(event, "shift", False)
                or getattr(event, "ctrl", False)):
            self._re_highlight = None
            self._cursor_pos = bp
            self._user_sel = None
            self._sel_anchor = bp
            self._refresh_view()
            self.post_message(self.CursorMoved())

    # ── Editing primitives ────────────────────────────────────────────────

    def insert_at_cursor(self, bases: str,
                         *, extend_adjacent_feats: bool = True,
                         feats: "list[dict] | None" = None) -> bool:
        """Insert `bases` at cursor. Returns True if anything landed.

        ``feats`` (2026-06-09, feature-rich paste): a list of feature dicts
        rebased to ``[0, len(bases))`` — laid over the just-inserted bases so
        a region copied WITH its annotations carries them into the editor.
        Bases are upper-cased; non-IUPAC chars are silently dropped
        (with a notify warning so a paste of garbage doesn't go
        unnoticed). Total length capped at ``_SYNTHESIS_MAX_BP``.

        ``extend_adjacent_feats`` (sweep #17, 2026-05-21): when True
        (default), a feature whose end == cursor extends to include
        the inserted bases — the "I'm typing into the tail of this
        feature" case. When False, the boundary feature stays at its
        original end; useful for callers inserting a SEPARATE
        annotated unit (feature-library Insert, etc.) where the new
        annotation needs to land cleanly downstream without
        overlapping the upstream feature.
        """
        if not bases:
            return False
        # Replace selection if any.
        if self._user_sel is not None:
            self._delete_range(*self._user_sel)
        clean = "".join(
            c for c in bases.upper()
            if c in _SYNTHESIS_TYPEABLE_BASES
        )
        if not clean:
            self.app.notify(
                "No valid bases in input (ACGT/IUPAC only).",
                severity="warning",
            )
            return False
        if len(clean) != len(bases):
            self.app.notify(
                f"Dropped {len(bases) - len(clean)} non-IUPAC char(s); "
                "kept the valid bases.",
                severity="information",
            )
        if len(self._seq) + len(clean) > _SYNTHESIS_MAX_BP:
            remaining = max(0, _SYNTHESIS_MAX_BP - len(self._seq))
            if remaining == 0:
                self.app.notify(
                    f"Fragment cap reached ({_SYNTHESIS_MAX_BP:,} bp). "
                    "Delete some bases or split the fragment.",
                    severity="warning",
                )
                return False
            clean = clean[:remaining]
            self.app.notify(
                f"Truncated to fit {_SYNTHESIS_MAX_BP:,} bp cap "
                f"(kept {len(clean):,} bp).",
                severity="warning",
            )
        # Sweep #28: record marker-state BEFORE the in-range clamp
        # so the post-insert cursor can stay on the 3' marker after
        # an append.
        cur_raw = self._cursor_pos
        n_before = len(self._seq)
        was_on_3p_marker = (cur_raw > n_before)
        self._clamp_cursor()  # defence-in-depth before mutating state
        cur = max(0, min(n_before, cur_raw))
        n_ins = len(clean)
        self._seq = self._seq[:cur] + clean + self._seq[cur:]
        # Feature shift: half-open [s, e). Bases at-or-after cur shift
        # by n_ins. With `extend_adjacent_feats=True` a feature whose
        # end == cur extends to include the inserted bases (typical
        # "extend the feature I'm appending to" behaviour). With
        # False, only features strictly past the cursor extend; the
        # boundary feature stays put so a separate library entry can
        # land cleanly downstream. A feature whose start == cur
        # always shifts (the insert sits BEFORE the feature's first
        # base) — regardless of the kwarg.
        new_feats: list[dict] = []
        for f in self._feats:
            s = int(f.get("start", 0))
            e = int(f.get("end", 0))
            new_f = dict(f)
            if s >= cur:
                new_f["start"] = s + n_ins
            if extend_adjacent_feats:
                if e >= cur and not (e == cur and s == cur):
                    new_f["end"] = e + n_ins
            else:
                if e > cur:
                    new_f["end"] = e + n_ins
            new_feats.append(new_f)
        self._feats = new_feats
        # Feature-rich paste: lay the copied region's features over the
        # just-inserted bases (caller passes them rebased to [0, n_ins)).
        # They land at [cur + start, cur + end), clipped to the inserted span,
        # in the gap the shift above just opened — so no overlap with existing
        # features.
        if feats:
            for _cf in feats:
                _cs = cur + max(0, int(_cf.get("start", 0)))
                _ce = cur + min(n_ins, int(_cf.get("end", 0)))
                if _ce > _cs:
                    _nf = dict(_cf)
                    _nf["start"] = _cs
                    _nf["end"]   = _ce
                    self._feats.append(_nf)
        # Sweep #28: if cursor was on the 3' marker (n_before+1),
        # keep it on the 3' marker post-insert ((n_before+n_ins)+1)
        # so the user can keep typing more bases at the 3' end.
        # Otherwise, cursor moves past the inserted bases.
        new_n = len(self._seq)
        if was_on_3p_marker:
            self._cursor_pos = new_n + 1
        else:
            self._cursor_pos = cur + n_ins
        self._user_sel = None
        self._sel_anchor = -1
        self._re_highlight = None   # edit invalidates the resite viz
        self._refresh_view()
        self._ensure_cursor_visible()
        self.post_message(self.Changed())
        return True

    def _delete_range(self, start: int, end: int) -> None:
        """Delete the half-open [start, end) range. Internal — assumes
        a sanitised range; callers handle clamping."""
        if start >= end:
            return
        n_del = end - start
        self._seq = self._seq[:start] + self._seq[end:]
        new_feats: list[dict] = []
        for f in self._feats:
            s = int(f.get("start", 0))
            e = int(f.get("end", 0))
            new_f = dict(f)
            if e <= start:
                # entirely left of deletion — unchanged
                new_feats.append(new_f)
                continue
            if s >= end:
                # entirely right — shift left
                new_f["start"] = s - n_del
                new_f["end"]   = e - n_del
                new_feats.append(new_f)
                continue
            # overlap: clip
            new_s = min(s, start)
            new_e = max(start, e - n_del)
            if new_e <= new_s:
                # feature disappeared
                continue
            new_f["start"] = new_s
            new_f["end"]   = new_e
            new_feats.append(new_f)
        self._feats = new_feats
        self._cursor_pos = start
        self._user_sel = None
        self._sel_anchor = -1
        self._re_highlight = None   # edit invalidates the resite viz

    def _feature_matching_selection(self) -> int:
        """Index of a user feature whose span EXACTLY equals the current
        selection, or -1. A lane-click highlight sets `_user_sel` to
        exactly the feature's `(start, end)` (see `_select_feature_span`),
        so this identifies "a whole feature is highlighted" for the
        two-step delete: first Delete removes the annotation (keeping the
        bases + the highlight), a second Delete then removes the bases."""
        if self._user_sel is None:
            return -1
        n = len(self._seq)
        for i, f in enumerate(self._feats):
            try:
                fs = max(0, int(f.get("start", 0)))
                fe = min(n, int(f.get("end", 0)))
            except (TypeError, ValueError):
                continue
            if (fs, fe) == self._user_sel:
                return i
        return -1

    def delete_at_cursor(self, *, forward: bool = False) -> bool:
        """Backspace (forward=False) or Delete (forward=True). Returns
        True if anything was deleted.

        Feature-first delete (2026-07-08): when the selection is a
        whole-feature highlight (a lane click), the FIRST Delete removes
        only the feature annotation and LEAVES the DNA + the highlight in
        place, so a SECOND Delete removes the highlighted bases. Deleting
        a feature you clicked shouldn't nuke the sequence it labels.

        Sweep #28: at the 5'/3' marker boundary positions, the
        delete actions hop the cursor back into-range FIRST, then
        delete naturally. Backspace at the 3' marker deletes the
        last base (most useful); Delete at the 5' marker deletes
        the first base. Both keep the cursor at the new end / start
        so the user can keep editing without re-positioning."""
        fidx = self._feature_matching_selection()
        if fidx >= 0:
            # Delete the annotation only; keep the bases + the highlight
            # (reassign `_feats` so the id-keyed render caches invalidate,
            # sacred invariant #4). `_user_sel` is untouched so the exact
            # same DNA stays highlighted for a follow-up base delete.
            self._feats = self._feats[:fidx] + self._feats[fidx + 1:]
            self._merged_sig = None
            self._refresh_view()
            self.post_message(self.Changed())
            return True
        if self._user_sel is not None:
            s, e = self._user_sel
            self._delete_range(s, e)
            self._refresh_view()
            self._ensure_cursor_visible()
            self.post_message(self.Changed())
            return True
        cur = self._cursor_pos
        n = len(self._seq)
        # Marker-boundary hop: clamp the cursor before the
        # bounds-check so the delete proceeds against an in-range
        # position.
        if cur > n:
            cur = n
            self._cursor_pos = cur
        elif cur < 0:
            cur = 0
            self._cursor_pos = cur
        if forward:
            if cur >= len(self._seq):
                return False
            self._delete_range(cur, cur + 1)
        else:
            if cur <= 0:
                return False
            self._delete_range(cur - 1, cur)
        self._refresh_view()
        self._ensure_cursor_visible()
        self.post_message(self.Changed())
        return True

    def replace_selection_or_insert(self, bases: str) -> bool:
        """Convenience: if there's a selection, delete + insert at the
        same anchor. Otherwise just insert at cursor."""
        if self._user_sel is not None:
            s, _e = self._user_sel
            self._delete_range(*self._user_sel)
            self._cursor_pos = s
        return self.insert_at_cursor(bases)

    def add_feature(self, feat: dict) -> None:
        """Append a feature dict to the buffer. Caller supplies start,
        end, label, type, color, qualifiers, strand. Coordinates are
        in absolute bp; no validation here — the AddFeatureModal
        already gated them.

        Pre-2026-05-26 this method did `self._feats.append(...)`,
        mutating the list in place. The `_CHUNK_STATIC_CACHE`'s key
        is `(hash(seq), id(feats), line_width, show_connectors)` —
        notably WITHOUT `len(feats)`, so an in-place append HIT the
        stale cache entry (built before the new feature was added)
        and the next `_refresh_view` returned a Text WITHOUT the
        new feature's lane art. User-reported symptom: insert from
        the feature library produced a "weird" DNA visualization
        (no feature bar, no flank markers) until an arrow key
        moved the cursor — that triggered the lazy overlay path,
        which uses a different cache key keyed on the cursor
        position, and the cache miss rebuilt with the up-to-date
        feature list. CLAUDE.md sacred invariant #4: "lists are
        reassigned on load, not mutated in place" — reassigning to
        a fresh list bumps `id(feats)` so every downstream cache
        invalidates cleanly. The cost is one list-copy per
        add_feature call; negligible against the alternative of a
        stale render."""
        if not isinstance(feat, dict):
            return
        self._feats = self._feats + [dict(feat)]
        self._refresh_view()
        self.post_message(self.Changed())

    def select_all(self) -> None:
        if not self._seq:
            return
        self._user_sel = (0, len(self._seq))
        self._sel_anchor = 0
        self._cursor_pos = len(self._seq)
        self._refresh_view()

    def current_selection(self) -> "tuple[int, int] | None":
        return self._user_sel

    # ── Restriction-site overlay (R key) ──────────────────────────────────

    def _rescan_restr(self) -> None:
        """(Re)scan `self._seq` for restriction sites and store the
        resite/recut overlay in `self._restr_feats`. Uses the SAME scan
        parameters as the main SequencePanel — the active enzyme
        collection (if any) plus the persisted min-recognition-length /
        unique-only settings — so R here reveals the same cut sites the
        canvas would. The fragment is linear, so `circular=False` (never
        joins the 3' tail to the 5' head). Reassigns `_restr_feats`
        (never mutates in place) so `_display_feats` rebuilds the merged
        list and the id-keyed render caches invalidate cleanly."""
        seq = self._seq
        if not seq:
            self._restr_feats = []
            self._restr_scan_seq = seq
            self._merged_sig = None
            return
        try:
            allowed = _active_enzyme_allowed_set()
            min_len = _get_setting("restr_min_len", 6)
            if min_len not in (4, 6):
                min_len = 6
            unique_only = bool(_get_setting("restr_unique_only", True))
            self._restr_feats = _scan_restriction_sites(
                seq,
                min_recognition_len=min_len,
                unique_only=unique_only,
                circular=False,
                allowed_enzymes=allowed,
            )
        except (TypeError, ValueError, KeyError, AttributeError):
            # A malformed enzyme catalog / setting must not kill the
            # editor — degrade to "no overlay" and log for diagnosis.
            # Narrow types per invariant #1 (no bare/broad except in the
            # editor render path).
            _log.exception("SynthesisEditor: restriction scan failed")
            self._restr_feats = []
        self._restr_scan_seq = seq
        self._merged_sig = None

    def toggle_restr_overlay(self) -> bool:
        """Flip the restriction-site overlay on/off (the R key). Returns
        the new state. Scans on turn-on; drops the overlay on turn-off."""
        self._show_restr_overlay = not self._show_restr_overlay
        if self._show_restr_overlay:
            self._rescan_restr()
        else:
            self._restr_feats = []
            self._restr_scan_seq = None
            self._merged_sig = None
            self._re_highlight = None   # no overlay → no site highlight
        self._refresh_view()
        return self._show_restr_overlay

    def restr_site_count(self) -> int:
        """Number of recognition sites in the current overlay (resite
        pieces only — recut markers + wrap-head halves excluded), for
        the toggle's status toast."""
        return sum(1 for f in self._restr_feats
                   if f.get("type") == "resite" and f.get("label"))

    # ── Paste handler (sweep #28) ─────────────────────────────────────────
    #
    # Terminal native-paste (Ctrl+V, Cmd+V, Ctrl+Shift+V, right-click,
    # middle-click, depending on terminal) sends bracketed-paste
    # sequences that Textual converts into `events.Paste` messages.
    # We route the payload through `insert_at_cursor`, which already
    # IUPAC-filters + caps length + handles the selection-replace
    # case. Pre-sweep the empty-fragment placeholder said "Ctrl+E to
    # insert from clipboard" but Ctrl+E opens the Edit Sequence
    # dialog, NOT a paste — the user pasted with their terminal's
    # native shortcut and nothing happened because no on_paste
    # handler was registered.

    def on_paste(self, event: Paste) -> None:
        """Insert bracketed-paste payload at the cursor. IUPAC
        filtering + size-cap + selection-replace handled by
        `insert_at_cursor`. Feature-rich: when the payload matches the
        region the app just copied (Ctrl+C of a selection), the copied
        features ride along into the editor."""
        text = getattr(event, "text", None)
        if not isinstance(text, str) or not text:
            return
        event.stop()
        feats = None
        cr = getattr(self.app, "_copied_region", None)
        if cr:
            cleaned = "".join(c for c in text.upper()
                              if c in "ACGTRYWSMKBDHVN")
            if cleaned and cleaned == (cr.get("seq") or "").upper():
                feats = cr.get("feats") or None
        # `extend_adjacent_feats=False`: a paste is a NEW chunk, not a
        # continuation of whatever it lands after — so a feature ending
        # exactly at the cursor (e.g. the sequence you pasted a moment
        # ago) must NOT grow to swallow the new bases. Without this,
        # pasting one annotated region after another extended the
        # upstream feature beneath the new one (2026-07-08). Pasting
        # INSIDE a feature still extends it (that path keys off `e > cur`,
        # independent of this flag).
        self.insert_at_cursor(text, feats=feats, extend_adjacent_feats=False)

    def _slide_selection(self, delta: int) -> None:
        """Ctrl+←/→ — slide the whole (fixed-length) selection by `delta`
        bases, clamped to the linear fragment. Mirrors the main
        SequencePanel's ctrl+arrow (linear-clamped, no wrap). No-op with
        no selection or a whole-molecule selection."""
        if self._user_sel is None:
            return
        s, e = self._user_sel
        n = len(self._seq)
        length = e - s
        if length <= 0 or length >= n:
            return
        new_s = max(0, min(n - length, s + delta))
        if new_s == s:
            return
        self._user_sel = (new_s, new_s + length)
        self._sel_anchor = new_s
        self._cursor_pos = new_s
        self._re_highlight = None
        self._refresh_view()
        self.post_message(self.CursorMoved())

    # ── Key handler ───────────────────────────────────────────────────────

    def on_key(self, event) -> None:
        """Capture base-typing + cursor navigation. We don't use Textual
        ``Binding`` here because the editor needs to consume *every*
        letter as a base, and Binding sets a tighter contract (one
        action per key). The handler also covers arrow keys,
        Backspace, Delete, Home, End so the parent screen's bindings
        don't have to."""
        k = event.key
        # Modifier-bearing keys flow up to the screen (Ctrl+F, Ctrl+S,
        # etc. — we never want to swallow them).
        if k in ("ctrl+f", "alt+shift+f", "ctrl+s", "ctrl+n", "ctrl+o", "ctrl+r",
                  "ctrl+l", "ctrl+a", "ctrl+e", "ctrl+z", "ctrl+y",
                  "escape", "tab", "shift+tab"):
            return
        # Zoom-out overview controls (mirror the main app's linear view):
        # − zoom out · + / = zoom in · 0 reset. Handled at ANY zoom level
        # (and before base-typing, so these non-base keys aren't dropped).
        if k in ("minus", "underscore"):
            event.stop()
            self._zoom_step(2)
            return
        if k in ("plus", "equals_sign"):
            event.stop()
            self._zoom_step(0.5)
            return
        if k == "0":
            event.stop()
            self._set_zoom(1)
            return
        # In zoom-out mode the editor is a read/navigate overview: arrows
        # step the cursor by one column (bp/col), Home/End jump to the
        # ends, everything else (typing, backspace, …) is swallowed — the
        # user clicks a column or presses 0/+ to return to 1:1 editing.
        if self._zoom_bp_per_col > 1:
            z = self._zoom_bp_per_col
            if k == "left":
                event.stop(); self.set_cursor(self._cursor_pos - z); return
            if k == "right":
                event.stop(); self.set_cursor(self._cursor_pos + z); return
            if k == "home":
                event.stop(); self.set_cursor(0); return
            if k == "end":
                event.stop(); self.set_cursor(len(self._seq)); return
            # Swallow all other keys so no editing happens while zoomed out.
            event.stop()
            return
        # Cursor navigation.
        if k == "left":
            event.stop()
            self.set_cursor(self._cursor_pos - 1)
            return
        if k == "right":
            event.stop()
            self.set_cursor(self._cursor_pos + 1)
            return
        if k == "shift+left":
            event.stop()
            self.set_cursor(self._cursor_pos - 1, extend_sel=True)
            return
        if k == "shift+right":
            event.stop()
            self.set_cursor(self._cursor_pos + 1, extend_sel=True)
            return
        # Ctrl+←/→ — slide the whole (fixed-length) selection by one base,
        # mirroring the main SequencePanel's ctrl+arrow. No-op without a
        # selection. (Ctrl+↑/↓ line-slide isn't meaningful in the
        # single-row synth editor, so only left/right are handled.)
        if k == "ctrl+left":
            event.stop()
            self._slide_selection(-1)
            return
        if k == "ctrl+right":
            event.stop()
            self._slide_selection(1)
            return
        if k == "home":
            event.stop()
            # Sweep #28: Home goes to position 0 (before first base).
            # Press Home twice (or Left from 0) to hop onto the
            # 5' marker at position -1.
            if self._cursor_pos == 0:
                self.set_cursor(-1)
            else:
                self.set_cursor(0)
            return
        if k == "end":
            event.stop()
            n = len(self._seq)
            # Sweep #28: End first lands at position n (after last
            # base). Press End again (or Right from n) to hop onto
            # the 3' marker at position n+1 for visual confirmation
            # that any further typing appends.
            if self._cursor_pos == n:
                self.set_cursor(n + 1)
            else:
                self.set_cursor(n)
            return
        if k == "shift+home":
            event.stop()
            self.set_cursor(0, extend_sel=True)
            return
        if k == "shift+end":
            event.stop()
            self.set_cursor(len(self._seq), extend_sel=True)
            return
        if k == "pageup":
            event.stop()
            self.set_cursor(self._cursor_pos - 60)
            return
        if k == "pagedown":
            event.stop()
            self.set_cursor(self._cursor_pos + 60)
            return
        if k == "backspace":
            event.stop()
            self.delete_at_cursor(forward=False)
            return
        if k == "delete":
            event.stop()
            self.delete_at_cursor(forward=True)
            return
        # Sweep #29 (2026-05-26): Enter on a base inside a feature
        # span opens FeatureEditModal for that feature. Matches the
        # main-canvas seq panel's `action_open_selected_feature` UX.
        # Outside a feature, surface a gentle notify rather than
        # silently no-op — the user pressed Enter expecting
        # SOMETHING to happen. Both "enter" and "return" keys are
        # accepted so the binding survives Textual / terminal
        # variation in how Return is reported.
        if k in ("enter", "return"):
            # Only handle Enter when the scroll container (the
            # focusable widget inside the editor) actually has
            # focus. `on_key` on a parent widget fires when ANY
            # descendant is focused, but it can also fire from
            # bubbled events — defensive check ensures the
            # feature-edit dispatch is scoped to the editor
            # textbox and can never trigger from a sibling pane
            # (library table, search input, etc.).
            try:
                scroll = self.query_one(
                    "#syn-scroll", ScrollableContainer,
                )
                if not scroll.has_focus:
                    return
            except NoMatches:
                return
            event.stop()
            idx = self._feature_at_cursor()
            if idx >= 0:
                self.post_message(self.FeatureEditRequested(idx))
            else:
                try:
                    self.app.notify(
                        "Place the cursor inside a feature first "
                        "to open the edit dialog.",
                        severity="information",
                        timeout=3,
                    )
                except (AttributeError, NoMatches):
                    # Editor mounted outside a running App (e.g. a
                    # unit test that instantiated the widget but
                    # didn't push it onto a screen). The notify is
                    # a UX nicety — silently skip in that case
                    # rather than crash the keypress handler.
                    pass
            return
        # Base typing — only A/C/G/T/N. Restricted to the keyboard set
        # (not the broader IUPAC set used for programmatic insert) so
        # accidental ambiguity codes can't slip into a fragment via a
        # keystroke; vendors universally accept ACGTN only. IUPAC
        # bases still flow in via restriction-site / feature-library
        # paths, where the ambiguity is intentional.
        ch = event.character
        if ch and len(ch) == 1 and ch.upper() in _SYNTHESIS_KEYBOARD_BASES:
            event.stop()
            self.insert_at_cursor(ch.upper())
            return
        # Anything else (modifier keys, function keys, IUPAC codes
        # like Y/R/W, …) bubbles up.


class ProteinEditor(Widget):
    """Linear horizontal-scroll PROTEIN editor — sibling of
    SynthesisEditor for the Protein tab of the synthesis composer.

    Two render modes:
      * **Codon-translated** (default): each amino acid letter sits
        centred over its 3-bp DNA codon, sourced from the active
        codon table's most-frequent codon for that amino acid. This
        is the design surface where a user can SEE the eventual
        synthesis-ready DNA while composing the protein.
      * **AA-only**: just the amino acid letters, one cell per
        residue, no DNA below. Useful for fast typing when the user
        doesn't care about codon choice yet.

      Toggle with Ctrl+T at the screen level.

    State model (aa-coords, not bp-coords):
      * ``_aa_seq``   — the amino acid string (single-letter codes,
                         '*' for stop).
      * ``_cursor_pos`` — 0..len(_aa_seq) — sits visually ON
                          ``_aa_seq[cursor_pos]`` (reverse-video).
      * ``_user_sel`` — selection range in AA coords (half-open).
      * ``_codon_mode`` — True = codon-translated render; False = AA only.
      * ``_codon_table_raw`` — ``{codon: (aa, count)}`` from the
                                active codon table; set by the screen.
      * ``_codon_cache`` — ``{aa: best_codon}`` derived from
                            ``_codon_table_raw`` once per table change.

    N-/-C markers flank the protein (N-terminus left, C-terminus
    right) — biology convention. Width is 2 chars on each side so
    ``_FLANK_MARKER_WIDTH = 2``; the column-arithmetic helpers use
    that constant so changing the marker text in one place doesn't
    break click resolution.
    """

    DEFAULT_CSS = """
    ProteinEditor {
        height: 1fr;
        background: #0a0a0a;
    }
    ProteinEditor:focus-within { background: #0c0c0c; }
    #pe-scroll {
        height: 1fr;
        overflow-x: auto;
        overflow-y: hidden;
        scrollbar-gutter: stable;
    }
    #pe-view {
        width: auto;
        height: auto;
    }
    """

    class Changed(Message):
        """Sent on any AA / codon-mode / codon-table mutation."""

    class Loaded(Message):
        """Sent by `load()` on a wholesale buffer replacement, so the
        SynthesisScreen can reset the protein undo/redo history."""

    class CursorMoved(Message):
        """Sent on cursor or selection change (no dirty side-effect)."""

    class FeatureEditRequested(Message):
        """Enter on an AA inside a feature — or a double-click on the
        feature's lane art — posts this so the SynthesisScreen opens
        `FeatureEditModal` for that motif. `idx` indexes `self._aa_feats`
        at post time; the handler MUST re-validate it (a Changed could
        have shifted indices between post and dispatch)."""
        def __init__(self, idx: int):
            self.idx = int(idx)
            super().__init__()

    _FLANK_MARKER_N:        str = "N-"
    _FLANK_MARKER_C:        str = "-C"
    _FLANK_MARKER_WIDTH:    int = 2
    _FLANK_MARKER_STYLE:    str = "bold #FF6B9D"
    _DNA_BELOW_STYLE:       str = "dim #88CCFF"
    _AA_DEFAULT_STYLE:      str = "bold white"

    def __init__(self, **kwargs) -> None:
        super().__init__(**kwargs)
        self._aa_seq: str = ""
        self._cursor_pos: int = 0
        self._user_sel: "tuple[int, int] | None" = None
        self._sel_anchor: int = -1
        self._codon_mode: bool = True
        self._codon_table_raw: dict = {}
        self._codon_cache: dict[str, str] = {}
        # Drag-select state — mirrors SynthesisEditor.
        self._drag_start_aa: int = -1
        self._has_dragged: bool = False
        self._mouse_button_held: bool = False
        self._last_was_drag: bool = False
        # Centring pads — same scheme as SynthesisEditor so cursor /
        # click math has a single offset to subtract.
        self._pad_above_rows: int = 0
        self._pad_left_cols: int = 0
        # Sweep #15 (2026-05-20) — feature tracking in AA coords.
        # Each entry: {"start": int, "end": int, "label": str,
        #              "type": str, "color": str, "qualifiers": dict}
        # half-open AA coords. Render paints feature cells with the
        # `color` as the background style; selection + cursor stack
        # on top so feature backgrounds never obscure the cursor.
        self._aa_feats: list[dict] = []
        # Feature index picked at mouse-down on a motif's lane art, so
        # `on_click` can highlight (single) or edit (double) it. -1 = the
        # press did not land on lane art. Mirrors SynthesisEditor.
        self._mouse_down_lane_idx: int = -1

    def compose(self) -> ComposeResult:
        with ScrollableContainer(id="pe-scroll"):
            yield Static("", id="pe-view", markup=False)

    def on_mount(self) -> None:
        self._refresh_view()
        try:
            self.query_one("#pe-scroll", ScrollableContainer).can_focus = True
        except NoMatches:
            pass

    # ── Public API ─────────────────────────────────────────────────────────

    def load(self, aa_seq: str,
             feats: "list[dict] | None" = None) -> None:
        """Replace the buffer. Resets cursor + selection. Optional
        ``feats`` arg seeds the feature list — used by the protein-
        save round-trip so motif annotations survive load/save."""
        self._aa_seq = "".join(
            c for c in str(aa_seq or "").upper()
            if c in _PROTEIN_AA_ALPHABET
        )
        self._cursor_pos = 0
        self._user_sel = None
        self._sel_anchor = -1
        n = len(self._aa_seq)
        clean: list[dict] = []
        for f in (feats or []):
            try:
                s = int(f.get("start", 0))
                e = int(f.get("end", 0))
            except (TypeError, ValueError):
                continue
            if s < 0 or e > n or e <= s:
                continue
            clean.append(dict(f))
        self._aa_feats = clean
        self._refresh_view()
        # Reset the screen's protein undo history for the loaded buffer.
        self.post_message(self.Loaded())

    def get_state(self) -> "tuple[str, bool]":
        """Return (aa_seq, codon_mode) snapshot for dirty / save flow."""
        return self._aa_seq, self._codon_mode

    def get_feats(self) -> list[dict]:
        """Return a deepcopy of the AA-coord feature list. Used by the
        save flow so the persisted SeqRecord can't share mutable state
        with the live editor."""
        return [dict(f) for f in self._aa_feats]

    def snapshot(self) -> dict:
        """Full editor state for the undo/redo stack — residues, motif
        features (deep-copied), cursor, and selection."""
        return {
            "aa_seq": self._aa_seq,
            "feats": [dict(f) for f in self._aa_feats],
            "cursor": self._cursor_pos,
            "user_sel": self._user_sel,
        }

    def apply_snapshot(self, snap: dict) -> None:
        """Restore a snapshot from `snapshot()` WITHOUT emitting Changed
        / Loaded (so undo/redo doesn't push a history entry or reset the
        stack). Reassigns `_aa_feats` so downstream copies stay clean."""
        if not isinstance(snap, dict):
            return
        self._aa_seq = "".join(
            c for c in str(snap.get("aa_seq", "")).upper()
            if c in _PROTEIN_AA_ALPHABET
        )
        n = len(self._aa_seq)
        clean: list[dict] = []
        for f in (snap.get("feats") or []):
            try:
                s = int(f.get("start", 0))
                e = int(f.get("end", 0))
            except (TypeError, ValueError):
                continue
            if s < 0 or e > n or e <= s:
                continue
            clean.append(dict(f))
        self._aa_feats = clean
        self._cursor_pos = max(0, min(n, int(snap.get("cursor", 0))))
        sel = snap.get("user_sel")
        if (isinstance(sel, tuple) and len(sel) == 2
                and 0 <= sel[0] < sel[1] <= n):
            self._user_sel = (int(sel[0]), int(sel[1]))
        else:
            self._user_sel = None
        self._sel_anchor = -1
        self._refresh_view()
        self._ensure_cursor_visible()

    def add_feature(self, feat: dict) -> None:
        """Append a feature in AA coords. Caller is responsible for
        building the dict (start/end/label/type/color/qualifiers).
        Triggers a re-render so the colored band appears immediately."""
        try:
            s = int(feat.get("start", 0))
            e = int(feat.get("end", 0))
        except (TypeError, ValueError):
            return
        n = len(self._aa_seq)
        if s < 0 or e > n or e <= s:
            return
        self._aa_feats.append(dict(feat))
        self._refresh_view()
        self.post_message(self.Changed())

    def set_codon_mode(self, on: bool) -> None:
        if bool(on) == self._codon_mode:
            return
        self._codon_mode = bool(on)
        self._refresh_view()
        self.post_message(self.CursorMoved())

    def set_codon_table(self, raw: dict) -> None:
        """Update the active codon table. Rebuilds the ``_codon_cache``
        (aa → most-frequent codon) so re-renders are cheap."""
        try:
            self._codon_table_raw = dict(raw or {})
            self._codon_cache = self._build_codon_cache(self._codon_table_raw)
        except (TypeError, ValueError):
            _log.exception(
                "ProteinEditor: codon table load failed; falling back to NNN",
            )
            self._codon_table_raw = {}
            self._codon_cache = {}
        self._refresh_view()

    @staticmethod
    def _build_codon_cache(raw: dict) -> dict[str, str]:
        """``{aa: most_frequent_codon}`` derived from the raw codon
        usage table. Returns 'NNN' for any AA missing in the table
        (defensive — a hostile / partial table doesn't crash the
        renderer)."""
        try:
            aa_codons, _ = _codon_build_aa_map(raw)
        except (TypeError, ValueError):
            return {}
        cache: dict[str, str] = {}
        for aa, codons in aa_codons.items():
            if not codons:
                continue
            cache[aa] = codons[0][0]
        # Stop codon — not in aa_codons (filtered out by
        # _codon_build_aa_map). Pull the most-frequent stop codon
        # straight from the raw table.
        stop_codons = [
            (codon, int(cnt)) for codon, (aa, cnt) in raw.items()
            if aa == "*"
        ]
        if stop_codons:
            stop_codons.sort(key=lambda x: -x[1])
            cache["*"] = stop_codons[0][0]
        else:
            cache["*"] = "TAA"
        return cache

    def current_selection(self) -> "tuple[int, int] | None":
        return self._user_sel

    # ── Render ─────────────────────────────────────────────────────────────

    def _viewport_width(self) -> int:
        try:
            scroll = self.query_one("#pe-scroll", ScrollableContainer)
            return max(0, int(scroll.size.width))
        except (NoMatches, AttributeError):
            return 0

    def _viewport_height(self) -> int:
        try:
            scroll = self.query_one("#pe-scroll", ScrollableContainer)
            return max(0, int(scroll.size.height))
        except (NoMatches, AttributeError):
            return 0

    def _cols_per_aa(self) -> int:
        """How many columns one AA occupies in the rendered Text:
        3 in codon mode (centred letter + 3-bp codon below), 1 in
        aa-only mode."""
        return 3 if self._codon_mode else 1

    def _content_width(self) -> int:
        """Natural width of the marker-wrapped render."""
        if not self._aa_seq:
            return 64
        return 2 * self._FLANK_MARKER_WIDTH + len(self._aa_seq) * self._cols_per_aa()

    def _horizontal_center_pad(self) -> int:
        vp_w = self._viewport_width()
        c_w  = self._content_width()
        if vp_w <= 0 or c_w >= vp_w:
            return 0
        return (vp_w - c_w) // 2

    def _row_count(self) -> int:
        """Rows the rendered Text occupies (excluding centring pads).
        Codon mode = 2 (AA row + DNA codon row); AA-only = 1.
        Sweep #16: when AA features are present, multi-lane art is
        prepended — each lane = bar + label = 2 rows, stacked per
        the 2D greedy pack in `_build_protein_lane_text`. The base
        count grows by the actual pack height."""
        base = 2 if self._codon_mode else 1
        if not self._aa_feats:
            return base
        return base + self._lane_height()

    def _pack_aa_feats(self) -> "tuple[list[tuple[dict, int]], int]":
        """Greedy 2-rows-per-feature vertical pack of the AA-coord motif
        features (row 0 = bar adjacent to the AA strand, row 1 = label),
        newest-on-top. Returns ``(placements, total_rows)`` where
        ``placements`` is ``[(feat, bottom_row), ...]``.

        Single source of truth shared by the lane RENDERER
        (`_build_protein_lane_text`), the row-count helper
        (`_lane_height`), and the lane-click HIT-TESTER
        (`_lane_feature_at`) so all three agree on exactly which row +
        span each motif occupies — a click can't resolve to a different
        motif than the one drawn there."""
        n_aa = len(self._aa_seq)
        if n_aa == 0 or not self._aa_feats:
            return [], 0
        col_top = [-1] * n_aa
        placements: list[tuple[dict, int]] = []
        for f in self._aa_feats:
            try:
                fs = max(0, int(f.get("start", 0)))
                fe = min(n_aa, int(f.get("end", 0)))
            except (TypeError, ValueError):
                continue
            if fe <= fs:
                continue
            max_top = max(col_top[fs:fe])
            bottom_row = max_top + 1      # bar row
            top_row = bottom_row + 1      # label row
            col_top[fs:fe] = [top_row] * (fe - fs)
            placements.append((f, bottom_row))
        total_rows = max((p[1] + 2 for p in placements), default=0)
        return placements, total_rows

    def _lane_height(self) -> int:
        """Row count for the feature lane art at the current feature
        set (0 when no motifs). Delegates to the shared packer."""
        return self._pack_aa_feats()[1]

    def _vertical_center_pad(self) -> int:
        vp_h = self._viewport_height()
        rows = self._row_count()
        if vp_h <= 0 or rows >= vp_h:
            return 0
        return (vp_h - rows) // 2

    def _refresh_view(self) -> None:
        try:
            view = self.query_one("#pe-view", Static)
        except NoMatches:
            return
        if not self._aa_seq:
            placeholder = (
                "(empty protein — type amino acids, "
                "Ctrl+V (or your terminal's paste) to paste, "
                "Alt+T to toggle AA-only mode, "
                "pick a motif on the right to insert)"
            )
            empty = Text(
                placeholder,
                style="dim italic",
                no_wrap=True,
                overflow="crop",
            )
            vp_w = self._viewport_width()
            if vp_w > 0 and len(placeholder) < vp_w:
                pad_left = (vp_w - len(placeholder)) // 2
                empty = Text(" " * pad_left, no_wrap=True) + empty
                self._pad_left_cols = pad_left
            else:
                self._pad_left_cols = 0
            pad_above = self._vertical_center_pad()
            self._pad_above_rows = pad_above
            if pad_above > 0:
                empty = Text("\n" * pad_above, no_wrap=True) + empty
            view.update(empty)
            return
        # Build the body — codon mode = 2 rows, aa-only = 1 row.
        if self._codon_mode:
            txt = self._build_codon_mode_text()
        else:
            txt = self._build_aa_only_text()
        # Horizontal centring pad — short proteins sit at viewport
        # centre; long proteins left-anchor + horizontal scroll.
        pad_left = self._horizontal_center_pad()
        self._pad_left_cols = pad_left
        if pad_left > 0:
            pad_text = Text(" " * pad_left, no_wrap=True)
            try:
                lines = txt.split("\n")
            except (AttributeError, TypeError):
                lines = [txt]
            txt = Text("\n", no_wrap=True).join(
                pad_text + ln for ln in lines
            )
        # Vertical centring — same scheme as SynthesisEditor.
        pad_above = self._vertical_center_pad()
        self._pad_above_rows = pad_above
        if pad_above > 0:
            txt = Text("\n" * pad_above, no_wrap=True) + txt
        view.update(txt)

    def _build_codon_mode_text(self) -> Text:
        """Two-row Text: AA letters centred over their 3-bp codons.

        For each AA:
            AA row:  ' X '   (3 cells: leading space, letter, trailing space)
            DNA row: 'XYZ'   (3 cells: the codon)

        N- / -C markers flank both rows. Cursor at AA[N] reverse-
        videos column N*3+1 (the AA letter) AND the 3 cells beneath
        (the codon under the cursor). Selection paints the same
        background on AA + codon cells across the span.
        """
        cursor = self._cursor_pos
        sel = self._user_sel
        sel_lo, sel_hi = (sel if sel is not None else (-1, -1))
        n_aa = len(self._aa_seq)
        aa_row  = Text(no_wrap=True, overflow="crop")
        dna_row = Text(no_wrap=True, overflow="crop")
        # Flank markers — N-terminus left, C-terminus right.
        n_marker = Text(self._FLANK_MARKER_N,
                         style=self._FLANK_MARKER_STYLE, no_wrap=True)
        c_marker = Text(self._FLANK_MARKER_C,
                         style=self._FLANK_MARKER_STYLE, no_wrap=True)
        # Below-strand marker pad — DNA codon row gets same-width
        # blanks so the AA row's markers don't shift the codon row.
        blank_marker = Text(" " * self._FLANK_MARKER_WIDTH, no_wrap=True)
        aa_row.append_text(n_marker)
        dna_row.append_text(blank_marker)
        # Sweep #16 (2026-05-21): drop the per-cell feature
        # background painting — features now appear as a dithered
        # ▒-block row ABOVE the AA strand, matching the main seq
        # panel's ``_paint_feature_bar`` style. Cursor + selection
        # stay loud (cursor=reverse, sel=#003366 background); the
        # AA cell foreground is otherwise just the default style.
        for i, aa in enumerate(self._aa_seq):
            on_cursor = (i == cursor)
            in_sel    = (sel_lo <= i < sel_hi)
            # Sweep #40: stop codon ('*') overrides the default
            # AA fg colour with red; decorator (cell highlight,
            # cursor reverse) is preserved.
            base_fg = (f"bold {_STOP_AA_COLOR}"
                       if aa == _STOP_AA_CHAR
                       else self._AA_DEFAULT_STYLE)
            cell_style = ""
            if in_sel:
                cell_style = "on #003366"
            if on_cursor:
                cell_style = "reverse"
            aa_row.append(" ", style=cell_style)
            aa_row.append(aa,
                          style=f"{base_fg} {cell_style}".strip())
            aa_row.append(" ", style=cell_style)
            # DNA row: codon (3 chars) under the AA. Fallback NNN.
            codon = self._codon_cache.get(aa, "NNN")
            if len(codon) != 3:
                codon = "NNN"
            dna_style = (cell_style or self._DNA_BELOW_STYLE)
            for c in codon:
                dna_row.append(c, style=dna_style)
        aa_row.append_text(c_marker)
        dna_row.append_text(blank_marker)
        # Hint for past-end cursor: when cursor sits at n_aa (past
        # the last residue), draw a faint caret in the trailing
        # margin so the user can see WHERE the next insert lands.
        if cursor == n_aa and n_aa > 0:
            aa_row.append("│", style="bold #FF6B9D")
            dna_row.append(" ")
        # Multi-lane feature art prepended when motifs are present.
        # Empty case keeps the original 2-row layout (AA + codon) so
        # users who haven't inserted a motif see the same view they
        # always did.
        if self._aa_feats:
            lanes, _n = self._build_protein_lane_text(cols_per_aa=3)
            if _n > 0:
                return (
                    lanes
                    + Text("\n", no_wrap=True)
                    + aa_row
                    + Text("\n", no_wrap=True)
                    + dna_row
                )
        return aa_row + Text("\n", no_wrap=True) + dna_row

    def _build_aa_only_text(self) -> Text:
        """Single-row Text: contiguous AA letters. One cell per AA.
        Sweep #16: dither row prepended when features are present —
        AA cells no longer carry feature backgrounds; the dither bar
        above shows the feature color instead."""
        cursor = self._cursor_pos
        sel = self._user_sel
        sel_lo, sel_hi = (sel if sel is not None else (-1, -1))
        n_aa = len(self._aa_seq)
        row = Text(no_wrap=True, overflow="crop")
        n_marker = Text(self._FLANK_MARKER_N,
                         style=self._FLANK_MARKER_STYLE, no_wrap=True)
        c_marker = Text(self._FLANK_MARKER_C,
                         style=self._FLANK_MARKER_STYLE, no_wrap=True)
        row.append_text(n_marker)
        for i, aa in enumerate(self._aa_seq):
            on_cursor = (i == cursor)
            in_sel    = (sel_lo <= i < sel_hi)
            # Sweep #40: stop codon override (see `_build_aa_dna_text`).
            base_fg = (f"bold {_STOP_AA_COLOR}"
                       if aa == _STOP_AA_CHAR
                       else self._AA_DEFAULT_STYLE)
            style = base_fg
            if in_sel:
                style = f"{style} on #003366"
            if on_cursor:
                # Cursor reverses fg + bg; still emit the red so a
                # stop-on-cursor renders with red foreground when
                # reverse is active (visible on most terminals).
                style = (f"reverse {_STOP_AA_COLOR}"
                         if aa == _STOP_AA_CHAR
                         else "reverse")
            row.append(aa, style=style)
        row.append_text(c_marker)
        if cursor == n_aa and n_aa > 0:
            row.append("│", style="bold #FF6B9D")
        if self._aa_feats:
            lanes, _n = self._build_protein_lane_text(cols_per_aa=1)
            if _n > 0:
                return lanes + Text("\n", no_wrap=True) + row
        return row

    def _build_dither_row(self, *, cols_per_aa: int) -> Text:
        """Legacy single-row dither — kept as a back-compat alias
        for `_build_protein_lane_text` consumers that only want one
        line (test helpers). The real renderer uses the multi-lane
        variant below."""
        text, _rows = self._build_protein_lane_text(
            cols_per_aa=cols_per_aa,
        )
        if not text.plain:
            # Synthesise an empty single-row dither (all spaces) so
            # callers can still rely on a Text being returned.
            n_aa = len(self._aa_seq)
            blank_marker = Text(
                " " * self._FLANK_MARKER_WIDTH, no_wrap=True,
            )
            row = Text(no_wrap=True, overflow="crop")
            row.append_text(blank_marker)
            row.append(" " * (n_aa * cols_per_aa))
            row.append_text(blank_marker)
            return row
        # When multi-lane, the LAST line is the one adjacent to AA —
        # return that single line so simple consumers see the "bar"
        # nearest the strand. Multi-lane callers use the full text +
        # row count directly.
        lines = text.split("\n")
        return lines[-1] if lines else text

    def _build_protein_lane_text(
        self, *, cols_per_aa: int,
    ) -> "tuple[Text, int]":
        """Build multi-lane feature art above the AA strand, matching
        the seq panel's ``_chunk_lane_groups`` + ``_paint_feature_bar``
        + ``_paint_feature_label`` style.

        Each feature occupies 2 rows in its lane:
          * row 0 (adjacent to AA): the ▒-block bar with a ▶/◀
            strand arrowhead at the terminus
          * row 1 (above the bar): the feature label, centred within
            the span (truncated when wider than the span)

        Overlapping features stack — older features pack into the
        lane closest to the AA strand; newer features get pushed up.
        Greedy 2D packing identical to ``_pack_features_2d`` (the seq
        panel uses the same algorithm).

        Returns ``(text, n_rows)`` — the Text already includes the
        N-/-C marker-width padding on both sides so it column-aligns
        with the AA row. n_rows is the number of rendered lines
        (0 when no features → caller should skip the prepend).
        """
        n_aa = len(self._aa_seq)
        if n_aa == 0 or not self._aa_feats:
            return Text(""), 0
        total_cells = n_aa * cols_per_aa
        # ── 2D greedy pack (AA coords) ────────────────────────────
        # Shared with `_lane_height` + `_lane_feature_at` so the drawn
        # position and the click target never drift. Bar row closest to
        # AA; label row directly above.
        placements, total_rows = self._pack_aa_feats()
        if not placements:
            return Text(""), 0
        # ── Per-row segment lists (sweep #19 perf fix) ────────────
        # Pre-sweep this allocated a (rows × cells) grid and called
        # `Text.append` per cell — O(rows × cells) appends, which
        # measured at 354 ms for the 16.6k AA / 30-feature cap and
        # 2.5 s in the all-overlap worst case. New shape: collect
        # per-row segments (col_s, text, style) as we walk the
        # placements; emit at the end via run-merge so each
        # contiguous-style stretch becomes ONE append. Total work
        # drops to O(rows × segments) where segments ≪ cells.
        row_segments: list[list[tuple[int, int, str, str]]] = [
            [] for _ in range(total_rows)
        ]
        for f, bottom_row in placements:
            try:
                fs = max(0, int(f.get("start", 0)))
                fe = min(n_aa, int(f.get("end", 0)))
            except (TypeError, ValueError):
                continue
            color = str(f.get("color") or "").strip()
            if not color:
                continue
            try:
                strand = int(f.get("strand", 1) or 0)
            except (TypeError, ValueError):
                strand = 1
            col_s = fs * cols_per_aa
            col_e = fe * cols_per_aa
            bar_row   = bottom_row
            label_row = bottom_row + 1
            span = col_e - col_s
            # Bar segment — one ▒-run plus an optional terminus
            # arrow. Forward strand: ▒…▒▶; reverse: ◀▒…▒; unstranded:
            # ▒…▒.
            if span > 0:
                if strand >= 1 and span >= 1:
                    if span > 1:
                        row_segments[bar_row].append(
                            (col_s, col_s + span - 1, "▒" * (span - 1),
                             color),
                        )
                    row_segments[bar_row].append(
                        (col_s + span - 1, col_e, "▶", color),
                    )
                elif strand <= -1 and span >= 1:
                    row_segments[bar_row].append(
                        (col_s, col_s + 1, "◀", color),
                    )
                    if span > 1:
                        row_segments[bar_row].append(
                            (col_s + 1, col_e, "▒" * (span - 1),
                             color),
                        )
                else:
                    row_segments[bar_row].append(
                        (col_s, col_e, "▒" * span, color),
                    )
            # Label segment — centred within the bar span. Truncate
            # when wider than the span; skip when label is empty.
            label = str(f.get("label") or "").strip()
            if label and label_row < total_rows and span > 0:
                if len(label) > span:
                    label = label[:span]
                label_start = col_s + max(0, (span - len(label)) // 2)
                row_segments[label_row].append(
                    (label_start, label_start + len(label),
                     label, f"bold {color}"),
                )
        # ── Emit rows in reverse so highest stack sits FIRST  ─────
        # (closest to AA at the bottom). Same orientation as the
        # seq panel's above-DNA lanes. Within each row, sort
        # segments by col_s, then walk: emit blank padding,
        # segment, blank padding, … Multi-segment rows can have
        # overlaps (a label sitting on top of an earlier segment
        # from a different lane); last-wins on overlap matches the
        # grid behaviour from pre-sweep.
        blank_marker = Text(
            " " * self._FLANK_MARKER_WIDTH, no_wrap=True,
        )
        lines: list[Text] = []
        for row_idx in reversed(range(total_rows)):
            line = Text(no_wrap=True, overflow="crop")
            line.append_text(blank_marker)
            segs = row_segments[row_idx]
            if not segs:
                # Pure-blank row — single append for the whole span.
                line.append(" " * total_cells)
            else:
                # Sort segments left → right; resolve overlap by
                # keeping the LATER segment (last-wins, matches
                # pre-sweep grid-overwrite semantics).
                segs = sorted(segs, key=lambda s: s[0])
                # Drop segments fully covered by a later segment.
                resolved: list[tuple[int, int, str, str]] = []
                for i, (s, e, txt, st) in enumerate(segs):
                    masked = False
                    for j in range(i + 1, len(segs)):
                        s2, e2, _t2, _st2 = segs[j]
                        if s2 <= s and e2 >= e:
                            masked = True
                            break
                    if not masked:
                        resolved.append((s, e, txt, st))
                # Clip partial overlaps so adjacent segments don't
                # double-emit cells. We trim the LEFT of each
                # segment to start where the previous one ended.
                pen = 0
                for s, e, txt, st in resolved:
                    if s > pen:
                        line.append(" " * (s - pen))
                    if e <= pen:
                        continue
                    if s < pen:
                        # Trim the left overlap from this segment.
                        trim = pen - s
                        if trim >= len(txt):
                            continue
                        txt = txt[trim:]
                        s = pen
                    line.append(txt, style=st)
                    pen = e
                if pen < total_cells:
                    line.append(" " * (total_cells - pen))
            line.append_text(blank_marker)
            lines.append(line)
        return Text("\n", no_wrap=True).join(lines), total_rows

    # ── Cursor + selection ────────────────────────────────────────────────

    def _clamp_cursor(self) -> None:
        self._cursor_pos = max(0, min(len(self._aa_seq), self._cursor_pos))

    def set_cursor(self, pos: int, *, extend_sel: bool = False) -> None:
        n = len(self._aa_seq)
        pos = max(0, min(n, int(pos)))
        if extend_sel:
            # Direction-aware anchor — same fix as SynthesisEditor so
            # the FIRST shift+left includes the AA under the cursor
            # in the selection.
            if self._user_sel is None:
                if pos < self._cursor_pos:
                    self._sel_anchor = min(n, self._cursor_pos + 1)
                else:
                    self._sel_anchor = self._cursor_pos
            elif self._sel_anchor < 0:
                self._sel_anchor = self._cursor_pos
            anchor = self._sel_anchor
            lo, hi = sorted((anchor, pos))
            self._user_sel = (lo, hi) if lo != hi else None
        else:
            self._user_sel = None
            self._sel_anchor = -1
        self._cursor_pos = pos
        self._refresh_view()
        self._ensure_cursor_visible()
        self.post_message(self.CursorMoved())

    def _ensure_cursor_visible(self) -> None:
        try:
            scroll = self.query_one("#pe-scroll", ScrollableContainer)
        except NoMatches:
            return
        # Column of cursor's AA in the rendered Text = pad_left +
        # marker_width + cursor_pos * cols_per_aa. For codon mode the
        # AA letter sits at cell +1 of its 3-cell group so we shift
        # by +1 to land the scroll target right on the letter.
        cell_offset = 1 if self._codon_mode else 0
        target_col = (self._pad_left_cols + self._FLANK_MARKER_WIDTH
                       + self._cursor_pos * self._cols_per_aa() + cell_offset)
        try:
            vp_w = max(1, int(scroll.size.width))
            cur_x = int(scroll.scroll_x)
        except (AttributeError, TypeError):
            return
        margin = max(4, vp_w // 6)
        if target_col < cur_x + margin:
            scroll.scroll_to(x=max(0, target_col - margin), animate=False)
        elif target_col > cur_x + vp_w - margin:
            scroll.scroll_to(
                x=max(0, target_col - vp_w + margin), animate=False,
            )

    # ── Click → AA ────────────────────────────────────────────────────────

    def _click_to_aa(self, screen_x: int, screen_y: int) -> int:
        """Map a screen click to an AA position 0..len(_aa_seq).
        Clicks on the N- / -C markers / centring pad collapse to the
        nearest AA endpoint."""
        if not self._aa_seq:
            return 0
        try:
            view = self.query_one("#pe-view", Static)
        except NoMatches:
            return -1
        view_region = view.region
        if view_region.width == 0:
            return -1
        # `view.region.x` already reflects the horizontal scroll (goes
        # negative as you pan right), so `screen_x - region.x` is the
        # content column directly — adding `scroll_x` here would
        # double-count the pan and misresolve clicks after scrolling
        # (the SynthesisEditor had the same bug, fixed 2026-07-08).
        col = screen_x - view_region.x
        # Subtract centring pad + N- marker → column inside the AA
        # content area.
        aa_col = col - (self._pad_left_cols + self._FLANK_MARKER_WIDTH)
        if aa_col < 0:
            return 0
        # In codon mode each AA spans 3 columns; in aa-only mode 1.
        n_aa = len(self._aa_seq)
        cpa = self._cols_per_aa()
        idx = aa_col // cpa
        if idx >= n_aa:
            return n_aa
        return int(idx)

    def _feat_index(self, feat: dict) -> int:
        """Index of `feat` (by identity) in `self._aa_feats`, or -1."""
        for i, f in enumerate(self._aa_feats):
            if f is feat:
                return i
        return -1

    def _feature_at_cursor(self) -> int:
        """Index of the smallest AA feature enclosing the cursor, or -1.
        Smallest-enclosing so a short motif inside a longer one wins
        focus (matches SynthesisEditor + the main canvas)."""
        cur = self._cursor_pos
        n = len(self._aa_seq)
        if not (0 <= cur < n):
            return -1
        best_idx = -1
        best_span = -1
        for i, f in enumerate(self._aa_feats):
            try:
                s = int(f.get("start", 0))
                e = int(f.get("end", 0))
            except (TypeError, ValueError):
                continue
            if not (s <= cur < e):
                continue
            span = e - s
            if best_idx < 0 or span < best_span:
                best_idx = i
                best_span = span
        return best_idx

    def _lane_feature_at(self, screen_x: int, screen_y: int
                         ) -> "tuple[int, int]":
        """If (screen_x, screen_y) lands on a motif's lane art (the bar
        or label rows drawn ABOVE the AA strand), return
        ``(feat_idx, aa)``; else ``(-1, -1)``. Uses the shared
        `_pack_aa_feats` layout so the click target matches the render."""
        n = len(self._aa_seq)
        if n == 0 or not self._aa_feats:
            return -1, -1
        try:
            view = self.query_one("#pe-view", Static)
        except NoMatches:
            return -1, -1
        reg = view.region
        if reg.width == 0 or reg.height == 0:
            return -1, -1
        # `reg.x` / `reg.y` already include the scroll offset (they go
        # negative as you pan right), so do NOT add scroll_x/scroll_y —
        # that double-counted the pan and missed clicks after scrolling
        # (fixed 2026-07-08). `overflow-y` is hidden ⇒ no vertical scroll.
        aa_col = (screen_x - reg.x) - (
            self._pad_left_cols + self._FLANK_MARKER_WIDTH)
        if aa_col < 0:
            return -1, -1
        cpa = self._cols_per_aa()
        aa_idx = aa_col // cpa
        if aa_idx >= n:
            return -1, -1
        # Row within the vertically-centred Text. Lanes occupy the top
        # `total_rows` rows (emitted highest-stack-first); the AA strand
        # + codon DNA row sit BELOW them, so a render_row >= total_rows
        # is the strand, not lane art.
        render_row = (screen_y - reg.y) - self._pad_above_rows
        if render_row < 0:
            return -1, -1
        placements, total_rows = self._pack_aa_feats()
        if render_row >= total_rows:
            return -1, -1
        row_idx = total_rows - 1 - render_row
        for f, bottom_row in placements:
            # bar row = bottom_row; label row = bottom_row + 1.
            if row_idx not in (bottom_row, bottom_row + 1):
                continue
            fs = int(f.get("start", 0))
            fe = int(f.get("end", 0))
            if fs <= aa_idx < fe:
                idx = self._feat_index(f)
                if idx >= 0:
                    return idx, int(aa_idx)
        return -1, -1

    def _select_feature_span(self, idx: int, cursor_aa: int = -1) -> None:
        """Highlight the whole motif at `idx` (``_user_sel = (start,
        end)``) and park the cursor inside it so Enter opens its editor."""
        if not (0 <= idx < len(self._aa_feats)):
            return
        f = self._aa_feats[idx]
        s = max(0, int(f.get("start", 0)))
        e = min(len(self._aa_seq), int(f.get("end", 0)))
        if e <= s:
            return
        self._user_sel = (s, e)
        self._sel_anchor = s
        self._cursor_pos = cursor_aa if s <= cursor_aa < e else s
        self._refresh_view()
        self.post_message(self.CursorMoved())

    def _aa_row_idx(self, screen_x: int, screen_y: int) -> int:
        """AA index for a click ON the AA strand row (or the codon DNA
        row, in codon mode), else -1. Motif lanes + the marker-free
        vertical pad return -1 so a click/drag there can't move the
        cursor or start a phantom selection — motif lanes are handled by
        `_lane_feature_at`."""
        if not self._aa_seq:
            return 0
        try:
            view = self.query_one("#pe-view", Static)
        except NoMatches:
            return -1
        reg = view.region
        if reg.width == 0 or reg.height == 0:
            return -1
        render_row = (screen_y - reg.y) - self._pad_above_rows
        _placements, total_rows = self._pack_aa_feats()
        # The AA strand sits just below the lane stack (`total_rows`);
        # the codon DNA row (codon mode) is one row below that.
        last = total_rows + (1 if self._codon_mode else 0)
        if not (total_rows <= render_row <= last):
            return -1
        return self._click_to_aa(screen_x, screen_y)

    # ── Mouse handlers ────────────────────────────────────────────────────

    def on_mouse_down(self, event: MouseDown) -> None:
        if event.button != 1:
            return
        self._mouse_down_lane_idx = -1
        # Motif lane-art click → highlight the whole motif (matches the
        # DNA tab + the main canvas). Resolve before the plain AA mapping.
        lane_idx, lane_aa = self._lane_feature_at(
            event.screen_x, event.screen_y)
        if lane_idx >= 0 and not event.shift:
            self._mouse_down_lane_idx = lane_idx
            self._mouse_button_held = True
            self._drag_start_aa = -1
            self._has_dragged = False
            self._select_feature_span(lane_idx, lane_aa)
            return
        # Row-aware: only a click on the AA strand starts a cursor / drag
        # (no phantom selection on motif lanes or the blank pad).
        aa = self._aa_row_idx(event.screen_x, event.screen_y)
        if aa < 0:
            return
        self._mouse_button_held = True
        self._drag_start_aa = aa
        self._has_dragged = False
        if event.shift and self._cursor_pos >= 0:
            if self._sel_anchor < 0:
                self._sel_anchor = self._cursor_pos
            lo, hi = sorted((self._sel_anchor, aa))
            self._user_sel = (lo, hi) if lo != hi else None
        else:
            self._user_sel = None
            self._sel_anchor = aa
        self._cursor_pos = aa
        self._refresh_view()
        self.post_message(self.CursorMoved())

    def on_mouse_move(self, event: MouseMove) -> None:
        if not self._mouse_button_held or self._drag_start_aa < 0:
            return
        aa = self._click_to_aa(event.screen_x, event.screen_y)
        if aa < 0:
            return
        if aa != self._drag_start_aa:
            self._has_dragged = True
            lo, hi = sorted((self._drag_start_aa, aa))
            self._user_sel = (lo, hi) if lo != hi else None
            self._cursor_pos = aa
            self._refresh_view()
            self.post_message(self.CursorMoved())

    def on_mouse_up(self, event: MouseUp) -> None:
        if event.button != 1:
            return
        self._last_was_drag = self._has_dragged
        self._mouse_button_held = False
        self._drag_start_aa = -1
        self._has_dragged = False

    def on_click(self, event: Click) -> None:
        if self._last_was_drag:
            self._last_was_drag = False
            self._mouse_down_lane_idx = -1
            return
        # Motif lane-art click resolved at mouse-down: already
        # highlighted; a double-click additionally opens its editor.
        lane_idx = self._mouse_down_lane_idx
        self._mouse_down_lane_idx = -1
        if lane_idx >= 0:
            if event.chain >= 2 and 0 <= lane_idx < len(self._aa_feats):
                self.post_message(self.FeatureEditRequested(lane_idx))
            return
        aa = self._aa_row_idx(event.screen_x, event.screen_y)
        if aa < 0:
            return
        if not event.shift:
            self._cursor_pos = aa
            self._user_sel = None
            self._sel_anchor = aa
            self._refresh_view()
            self.post_message(self.CursorMoved())

    # ── Editing primitives ────────────────────────────────────────────────

    def insert_at_cursor(self, aas: str,
                         *, extend_adjacent_feats: bool = True,
                         feats: "list[dict] | None" = None) -> bool:
        """Insert ``aas`` at cursor. Non-AA chars are dropped with a
        notify. Total length capped at ``_PROTEIN_MAX_AA``.

        ``feats`` (2026-07-08, feature-rich protein paste): motif dicts
        rebased to ``[0, len(aas))`` — laid over the just-inserted
        residues so a copied protein region carries its motifs into the
        editor, mirroring the DNA tab's feature-rich paste.

        ``extend_adjacent_feats`` (sweep #17, 2026-05-21): True
        (default) extends a feature whose end == cursor by the
        inserted length — typing inside / appending to a feature's
        tail grows the feature bar, matching the seq panel's
        feel. False keeps a boundary feature at its original end;
        used by `_motif_insert_selected` so a second motif inserted
        at the 3' boundary of an existing motif lands as a SEPARATE
        downstream feature without stacking on top. Features whose
        start == cursor always shift right (the insert sits BEFORE
        their first AA) regardless of the kwarg. Features whose
        cursor sits STRICTLY INSIDE (fs < cur < fe) always extend —
        that's the "I'm typing inside a feature" case the user
        explicitly wants to preserve.
        """
        if not aas:
            return False
        if self._user_sel is not None:
            self._delete_range(*self._user_sel)
        clean = "".join(
            c for c in aas.upper()
            if c in _PROTEIN_AA_ALPHABET
        )
        if not clean:
            self.app.notify(
                "No valid amino acids in input "
                "(20 standard AAs + '*' only).",
                severity="warning",
            )
            return False
        if len(clean) != len(aas):
            self.app.notify(
                f"Dropped {len(aas) - len(clean)} non-AA char(s); "
                "kept the valid amino acids.",
                severity="information",
            )
        if len(self._aa_seq) + len(clean) > _PROTEIN_MAX_AA:
            remaining = max(0, _PROTEIN_MAX_AA - len(self._aa_seq))
            if remaining == 0:
                self.app.notify(
                    f"Protein cap reached ({_PROTEIN_MAX_AA:,} aa). "
                    "Delete some residues or split the protein.",
                    severity="warning",
                )
                return False
            clean = clean[:remaining]
            self.app.notify(
                f"Truncated to fit {_PROTEIN_MAX_AA:,} aa cap "
                f"(kept {len(clean):,} aa).",
                severity="warning",
            )
        self._clamp_cursor()
        cur = self._cursor_pos
        n_ins = len(clean)
        self._aa_seq = self._aa_seq[:cur] + clean + self._aa_seq[cur:]
        # Feature shift — same rules as SynthesisEditor's
        # `insert_at_cursor`. Strictly-inside (fs < cur < fe) ALWAYS
        # extends so typing inside a motif grows the bar. The
        # boundary case (fe == cur && fs < cur) is what the kwarg
        # controls — default extends (typing-at-tail), False keeps
        # the original end (separate-feature inserts).
        for f in self._aa_feats:
            try:
                fs = int(f.get("start", 0))
                fe = int(f.get("end", 0))
            except (TypeError, ValueError):
                continue
            if fs >= cur:
                f["start"] = fs + n_ins
            if extend_adjacent_feats:
                if fe >= cur and not (fe == cur and fs == cur):
                    f["end"] = fe + n_ins
            else:
                # Only extend when the cursor is STRICTLY inside
                # (fe > cur). Boundary features (fe == cur) keep
                # their original end so the caller's new feature
                # lands as a clean downstream sibling.
                if fe > cur:
                    f["end"] = fe + n_ins
        # Feature-rich paste: lay the copied region's motifs over the
        # just-inserted residues (caller passes them rebased to
        # [0, n_ins)), clipped to the inserted span so they can't spill
        # past it. Mirrors the DNA editor's feature-rich insert.
        if feats:
            for _cf in feats:
                try:
                    _cs = cur + max(0, int(_cf.get("start", 0)))
                    _ce = cur + min(n_ins, int(_cf.get("end", 0)))
                except (TypeError, ValueError):
                    continue
                if _ce > _cs:
                    _nf = dict(_cf)
                    _nf["start"] = _cs
                    _nf["end"] = _ce
                    self._aa_feats.append(_nf)
        self._cursor_pos = cur + n_ins
        self._user_sel = None
        self._sel_anchor = -1
        self._refresh_view()
        self._ensure_cursor_visible()
        self.post_message(self.Changed())
        return True

    def _delete_range(self, start: int, end: int) -> None:
        if start >= end:
            return
        self._aa_seq = self._aa_seq[:start] + self._aa_seq[end:]
        # Sweep #15: clip + shift AA-coord features on delete. Same
        # rules as SynthesisEditor._delete_range — fully-left untouched,
        # fully-right shifted, overlapping clipped, zero-survival
        # dropped.
        n_del = end - start
        new_feats: list[dict] = []
        for f in self._aa_feats:
            try:
                fs = int(f.get("start", 0))
                fe = int(f.get("end", 0))
            except (TypeError, ValueError):
                continue
            if fe <= start:
                # Entirely left of cut — untouched.
                new_feats.append(f)
                continue
            if fs >= end:
                # Entirely right of cut — shift left by n_del.
                f["start"] = fs - n_del
                f["end"]   = fe - n_del
                new_feats.append(f)
                continue
            # Overlapping the cut. Map the surviving span to the
            # post-delete coordinate system: the deleted window
            # [start, end) becomes a single point at `start`. Cells
            # past `end` shift left by n_del.
            #   new_start = min(fs, start)          # left of cut keeps its position
            #   new_end   = max(fe - n_del, start)  # right of cut shifts; clipped at start
            new_start = min(fs, start)
            new_end   = max(fe - n_del, start)
            if new_end <= new_start:
                continue   # zero-survival drop
            f["start"] = new_start
            f["end"]   = new_end
            new_feats.append(f)
        self._aa_feats = new_feats
        self._cursor_pos = start
        self._user_sel = None
        self._sel_anchor = -1

    def _feature_matching_selection(self) -> int:
        """Index of a motif whose AA span EXACTLY equals the current
        selection, or -1 — a lane-click highlight. See the DNA editor's
        method of the same name for the two-step-delete rationale."""
        if self._user_sel is None:
            return -1
        n = len(self._aa_seq)
        for i, f in enumerate(self._aa_feats):
            try:
                fs = max(0, int(f.get("start", 0)))
                fe = min(n, int(f.get("end", 0)))
            except (TypeError, ValueError):
                continue
            if (fs, fe) == self._user_sel:
                return i
        return -1

    def delete_at_cursor(self, *, forward: bool = False) -> bool:
        # Feature-first delete: the first Delete on a highlighted motif
        # removes only the annotation (keeping the residues + highlight);
        # a second Delete then removes the residues.
        fidx = self._feature_matching_selection()
        if fidx >= 0:
            self._aa_feats = self._aa_feats[:fidx] + self._aa_feats[fidx + 1:]
            self._refresh_view()
            self.post_message(self.Changed())
            return True
        if self._user_sel is not None:
            s, e = self._user_sel
            self._delete_range(s, e)
            self._refresh_view()
            self._ensure_cursor_visible()
            self.post_message(self.Changed())
            return True
        cur = self._cursor_pos
        if forward:
            if cur >= len(self._aa_seq):
                return False
            self._delete_range(cur, cur + 1)
        else:
            if cur <= 0:
                return False
            self._delete_range(cur - 1, cur)
        self._refresh_view()
        self._ensure_cursor_visible()
        self.post_message(self.Changed())
        return True

    def select_all(self) -> None:
        if not self._aa_seq:
            return
        self._user_sel = (0, len(self._aa_seq))
        self._sel_anchor = 0
        self._cursor_pos = len(self._aa_seq)
        self._refresh_view()

    # ── Paste handler ─────────────────────────────────────────────────────
    #
    # Mirrors SynthesisEditor.on_paste (sweep #28). Terminal
    # native-paste (Ctrl+V / Cmd+V / Ctrl+Shift+V / right-click /
    # middle-click, terminal-dependent) sends bracketed-paste
    # sequences that Textual converts into `events.Paste` messages.
    # We route the payload through `insert_at_cursor`, which AA-filters
    # (drops non-amino-acid chars with a notify), caps length at
    # `_PROTEIN_MAX_AA`, and handles the selection-replace case — so a
    # pasted amino-acid sequence lands at the cursor exactly like the
    # DNA tab pastes bases.

    def on_paste(self, event: Paste) -> None:
        """Insert bracketed-paste payload at the cursor. AA filtering +
        size-cap + selection-replace handled by `insert_at_cursor`.
        Feature-rich: when the payload matches the protein region just
        copied (Ctrl+C of a motif selection), the copied motifs ride
        along — the AA-coord mirror of the DNA tab's feature-rich paste."""
        text = getattr(event, "text", None)
        if not isinstance(text, str) or not text:
            return
        event.stop()
        feats = None
        cr = getattr(self.app, "_copied_protein_region", None)
        if cr:
            cleaned = "".join(c for c in text.upper()
                              if c in _PROTEIN_AA_ALPHABET)
            if cleaned and cleaned == (cr.get("aa") or "").upper():
                feats = cr.get("feats") or None
        # `extend_adjacent_feats=False` — a paste is a new chunk, so a
        # motif ending at the cursor must not grow beneath the pasted
        # residues (AA-coord mirror of the DNA on_paste fix, 2026-07-08).
        self.insert_at_cursor(text, feats=feats, extend_adjacent_feats=False)

    # ── Key handler ───────────────────────────────────────────────────────

    def on_key(self, event) -> None:
        k = event.key
        if k in ("ctrl+f", "alt+shift+f", "ctrl+s", "ctrl+n", "ctrl+o", "ctrl+r",
                  "ctrl+l", "ctrl+a", "ctrl+e", "ctrl+z", "ctrl+y",
                  "ctrl+t", "ctrl+m", "alt+t",
                  "escape", "tab", "shift+tab"):
            return
        if k == "left":
            event.stop()
            self.set_cursor(self._cursor_pos - 1)
            return
        if k == "right":
            event.stop()
            self.set_cursor(self._cursor_pos + 1)
            return
        if k == "shift+left":
            event.stop()
            self.set_cursor(self._cursor_pos - 1, extend_sel=True)
            return
        if k == "shift+right":
            event.stop()
            self.set_cursor(self._cursor_pos + 1, extend_sel=True)
            return
        if k == "home":
            event.stop()
            self.set_cursor(0)
            return
        if k == "end":
            event.stop()
            self.set_cursor(len(self._aa_seq))
            return
        if k == "shift+home":
            event.stop()
            self.set_cursor(0, extend_sel=True)
            return
        if k == "shift+end":
            event.stop()
            self.set_cursor(len(self._aa_seq), extend_sel=True)
            return
        if k == "pageup":
            event.stop()
            self.set_cursor(self._cursor_pos - 20)
            return
        if k == "pagedown":
            event.stop()
            self.set_cursor(self._cursor_pos + 20)
            return
        if k == "backspace":
            event.stop()
            self.delete_at_cursor(forward=False)
            return
        if k == "delete":
            event.stop()
            self.delete_at_cursor(forward=True)
            return
        # Enter on an AA inside a motif → open FeatureEditModal (mirrors
        # the DNA tab + main canvas). Scoped to the editor's own scroll
        # container having focus so a bubbled Enter from a sibling pane
        # can't trigger it. Outside a motif, a gentle notify.
        if k in ("enter", "return"):
            try:
                scroll = self.query_one("#pe-scroll", ScrollableContainer)
                if not scroll.has_focus:
                    return
            except NoMatches:
                return
            event.stop()
            idx = self._feature_at_cursor()
            if idx >= 0:
                self.post_message(self.FeatureEditRequested(idx))
            else:
                try:
                    self.app.notify(
                        "Place the cursor inside a motif first to open "
                        "the edit dialog.",
                        severity="information", timeout=3,
                    )
                except (AttributeError, NoMatches):
                    pass
            return
        ch = event.character
        if ch and len(ch) == 1 and ch.upper() in _PROTEIN_AA_ALPHABET:
            event.stop()
            self.insert_at_cursor(ch.upper())
            return

    def on_resize(self, _event) -> None:
        self._refresh_view()


