class _OperonProteinModal(ModalScreen):
    """Name + amino-acid sequence entry for the operon protein library.
    Dismisses ``{"name": str, "sequence": str}`` on Save, ``None`` on
    Cancel. Whitespace is stripped from the sequence and it's validated
    (canonical AAs only) before the modal closes."""

    _blocks_undo: bool = True

    BINDINGS = [Binding("escape", "cancel", "Cancel")]

    DEFAULT_CSS = """
    _OperonProteinModal { align: center middle; }
    #opm-dlg {
        width: 84; height: auto; background: $surface;
        border: solid $primary; padding: 1 2;
    }
    #opm-title {
        background: $primary-darken-2; color: $text; padding: 0 1;
        text-align: center; text-style: bold;
    }
    #opm-dlg Label { color: $text-muted; margin-top: 1; }
    #opm-status { height: 1; margin-top: 1; color: $error; }
    #opm-btns { height: 3; margin-top: 1; align: right middle; }
    #opm-btns Button { margin-right: 1; min-width: 12; }
    """

    def __init__(self, *, name: str = "", sequence: str = "",
                 title: str = " Add protein ") -> None:
        super().__init__()
        self._name0 = str(name or "")
        self._seq0 = str(sequence or "")
        self._title = str(title)
        self._dismissed: bool = False

    def _dismiss_once(self, result) -> None:
        if self._dismissed:
            return
        self._dismissed = True
        self.dismiss(result)

    def compose(self) -> ComposeResult:
        with Vertical(id="opm-dlg"):
            yield Static(self._title, id="opm-title")
            yield Label("Name:")
            yield Input(value=self._name0, placeholder="e.g. luxC",
                        id="opm-name")
            yield Label("Amino-acid sequence:")
            yield Input(value=self._seq0,
                        placeholder="MKFG… (single-letter, * = stop)",
                        id="opm-seq")
            yield Static("", id="opm-status")
            with Horizontal(id="opm-btns"):
                yield Button("Save", id="btn-opm-save", variant="primary")
                yield Button("Cancel", id="btn-opm-cancel")

    def on_mount(self) -> None:
        try:
            self.query_one("#opm-name", Input).focus()
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-opm-save")
    def _save(self, _) -> None:
        name = self.query_one("#opm-name", Input).value.strip()
        seq = "".join(self.query_one("#opm-seq", Input).value.split()).upper()
        err = (("protein name is required" if not name
                else _protein_seq_error(seq)))
        if not err and "*" in seq.rstrip("*"):
            err = "stop codon '*' is only allowed at the end of the sequence"
        if err:
            self.query_one("#opm-status", Static).update(err)
            return
        self._dismiss_once({"name": name, "sequence": seq})

    @on(Button.Pressed, "#btn-opm-cancel")
    def _cancel_btn(self, _) -> None:
        self._dismiss_once(None)

    def action_cancel(self) -> None:
        self._dismiss_once(None)


def _ensure_entry_vector_for_clone(app, grammar_id: str, on_ready) -> None:
    """Guarantee the chosen modular grammar has a VALID bound entry
    vector before the Domesticator clones into it, then invoke
    ``on_ready()``.

    On a fresh install — or any grammar the user never configured — no
    entry vector is bound, so `_part_to_cloned_seqrecord` would fall
    back to the pUPD2 stub and the saved "clone" would be just the bare
    insert + overhangs ("no cloning sites"). To prevent that silent
    degradation we pop `PlasmidPickerModal` so the user picks an
    acceptor from their own library. The pick is VALIDATED
    (`_gb_text_acceptor_cut_count` ≥ 2 of the grammar's enzyme sites —
    a real dropout cassette) before it is bound via `_set_entry_vector`;
    an unsuitable plasmid is rejected with a specific message and the
    picker re-opens. Cancelling the picker ABORTS the clone (``on_ready``
    is never called) — we never fabricate a stub the user didn't ask
    for. An already-valid binding is the fast path: ``on_ready`` fires
    immediately with no modal.
    """
    grammar = (_all_grammars().get(grammar_id)
               or _BUILTIN_GRAMMARS.get("gb_l0") or {})
    enzyme = grammar.get("enzyme") or "the grammar's enzyme"
    gname = grammar.get("name", grammar_id)
    ev = _get_entry_vector(grammar_id)
    if _entry_vector_is_valid_acceptor(ev, grammar):
        on_ready()
        return

    def _after_pick(picked_id) -> None:
        if not picked_id:
            app.notify(
                f"Clone cancelled — {gname} needs a bound entry vector "
                f"to clone the part into.",
                severity="warning",
            )
            return
        entry = _find_library_entry_by_id(picked_id)
        if entry is None:
            app.notify("Picked plasmid not found in the library.",
                       severity="error")
            return
        gb = entry.get("gb_text") or ""
        n_cuts = _gb_text_acceptor_cut_count(gb, grammar)
        if n_cuts < 2:
            ename = entry.get("name") or picked_id
            app.notify(
                f"'{ename}' has {n_cuts} {enzyme} site(s); a {gname} entry "
                f"vector needs at least 2 (the dropout cassette it swaps "
                f"for your part). Pick another plasmid.",
                severity="error",
            )
            # Re-open so the user can choose a real acceptor.
            app.push_screen(PlasmidPickerModal(), callback=_after_pick)
            return
        _set_entry_vector(grammar_id, {
            "name":    entry.get("name") or picked_id,
            "size":    entry.get("size") or 0,
            "source":  "library",
            "id":      picked_id,
            "gb_text": gb,
        })
        _log_event("entry_vector.bound", grammar_id=grammar_id,
                   role="", source="clone_fragment")
        app.notify(
            f"Bound '{entry.get('name') or picked_id}' as the {gname} "
            f"entry vector ({n_cuts} {enzyme} sites).",
        )
        on_ready()

    if not _load_library():
        # Nothing to pick from — an empty picker is a dead end. Guide the
        # user to get an acceptor into their library first (fresh install).
        app.notify(
            f"{gname} has no entry vector bound, and your library has no "
            f"plasmids to choose one from. Fetch or import an acceptor "
            f"(a plasmid with at least 2 {enzyme} sites) first, then clone.",
            severity="warning",
        )
        return
    app.notify(
        f"{gname} has no entry vector bound yet — pick an acceptor "
        f"plasmid from your library to clone the part into.",
        severity="information",
    )
    app.push_screen(PlasmidPickerModal(), callback=_after_pick)


class CloneRegionEnzymeModal(_OneShotDismissScreen, ModalScreen):
    """One-click "Clone selected region" — pick the restriction enzyme to add
    at each END of the highlighted region. On confirm the caller PCR-designs
    the RE-tailed cloning primers, builds the amplicon, and drops it into the
    Constructor's Traditional tab pre-configured with these two enzymes (the
    same handoff Synthesis ▸ Clone Fragment uses, but for an arbitrary stretch
    of an existing plasmid rather than a synthesised fragment). Dismisses
    ``{"enz5": <name>, "enz3": <name>}`` or ``None`` on cancel."""

    _blocks_undo: bool = True
    BINDINGS = [Binding("escape", "cancel", "Cancel")]
    DEFAULT_CSS = """
    #cre-dlg {
        width: 66; height: auto;
        background: $surface; border: solid $primary; padding: 1 2;
    }
    #cre-title {
        background: $primary-darken-2; color: $text;
        padding: 0 1; margin-bottom: 1; text-align: center;
    }
    #cre-hint { color: $text-muted; margin-bottom: 1; }
    #cre-row { height: auto; }
    .cre-col { width: 1fr; height: auto; padding-right: 1; }
    .cre-lbl { color: $text-muted; }
    #cre-btns { height: 3; margin-top: 1; align: right middle; }
    #cre-btns Button { margin-left: 2; }
    #cre-name { margin-top: 1; }
    #cre-vector { margin-bottom: 1; }
    """

    def __init__(self, default_name: str = "PCR-", insert_seq: str = "", *,
                 vector_choices: "list[tuple[str, str]] | None" = None,
                 vector_seq_for: "_Callable[[str], str] | None" = None) -> None:
        super().__init__()
        # Prefill for the amplicon-name box — mirrors Synthesis's "FRAG-…"
        # default so the user can name the PCR product (or leave the stub and
        # take the auto "<plasmid> <start>-<end>" fallback the caller applies).
        self._default_name = str(default_name or "PCR-")
        # The region being cloned (record-sliced, wrap-aware) — drives enzyme
        # viability marking + the suggested default pair.
        self._insert_seq = (insert_seq or "").upper()
        # Optional destination-vector picker (Phase 3): ``[(label, id)]`` plus a
        # lazy ``id -> seq`` resolver, so choosing a vector cross-checks enzyme
        # viability against it and pre-seeds the Constructor backbone.
        self._vector_choices: "list[tuple[str, str]]" = list(vector_choices or [])
        self._vector_seq_for = vector_seq_for
        self._vector_id: str = ""
        # Parsed-sequence cache so re-selecting a vector doesn't re-parse its
        # GenBank (the resolver does a full record parse per call).
        self._vec_seq_cache: "dict[str, str]" = {}

    def compose(self) -> ComposeResult:
        opts = _cloning_enzyme_options(self._insert_seq)
        d5, d3 = self._default_pair(opts, None)
        with Vertical(id="cre-dlg"):
            yield Static(" Clone selected region — pick the cut sites ",
                         id="cre-title")
            yield Static(self._compose_hint(self._insert_seq, None),
                         id="cre-hint", markup=False)
            if self._vector_choices:
                yield Static("Destination vector (optional — cross-checks the "
                             "cut sites):", classes="cre-lbl")
                yield Select([("(decide later)", "")] + self._vector_choices,
                             value="", id="cre-vector", allow_blank=False)
            with Horizontal(id="cre-row"):
                with Vertical(classes="cre-col"):
                    yield Static("5' end:", classes="cre-lbl")
                    yield Select(opts, value=d5, id="cre-enz5",
                                 allow_blank=False)
                with Vertical(classes="cre-col"):
                    yield Static("3' end:", classes="cre-lbl")
                    yield Select(opts, value=d3, id="cre-enz3",
                                 allow_blank=False)
            yield Static("Amplicon name (for saving the PCR product):",
                         classes="cre-lbl")
            yield Input(value=self._default_name, id="cre-name",
                        max_length=64)
            with Horizontal(id="cre-btns"):
                yield Button("Clone", variant="primary", id="cre-clone")
                yield Button("Cancel", id="cre-cancel")

    @staticmethod
    def _default_pair(opts: "list[tuple[str, str]]",
                      pair: "tuple[str, str] | None") -> "tuple[str, str]":
        """The two Select default values: the suggested pair when present, else
        the first two (usable-first-sorted) options — never blank."""
        vals = [v for _lbl, v in opts]
        if pair and pair[0] in vals and pair[1] in vals:
            return pair[0], pair[1]
        # The curated option list is never empty, so vals[0]/[1] always exist;
        # the "" guards keep the return strictly typed without a BLANK sentinel.
        d5 = vals[0] if vals else ""
        d3 = vals[1] if len(vals) > 1 else d5
        return d5, d3

    @staticmethod
    def _compose_hint(insert_seq: str, vector_seq: "str | None") -> str:
        """Status line: how many curated enzymes are unusable for this region
        (and vector, if chosen), so the marks aren't a silent surprise."""
        cls = _classify_cloning_enzymes(insert_seq)
        in_insert = sum(1 for v in cls.values() if v == "in_insert")
        base = ("Each end is PCR-amplified with the chosen enzyme's site added "
                "in the primer tail; use a different enzyme per end for "
                "directional cloning.")
        notes = []
        if in_insert:
            notes.append(f"{in_insert} enzyme(s) cut inside this selection (✗)")
        if vector_seq:
            unusable = sum(1 for n in _CLONING_RE_NAMES
                           if cls.get(n) == "safe"
                           and not _vector_has_site(vector_seq, n))
            if unusable:
                notes.append(f"{unusable} not in the chosen vector (⚠)")
        if notes:
            base += "  —  " + "; ".join(notes) + "; safe ones are listed first."
        return base

    def _resolve_vector_seq(self, vid: str) -> str:
        """Lazy, cached id → sequence via the caller's resolver (one parse per
        vector). Returns "" on any failure so viability falls back to
        insert-only."""
        if not vid or self._vector_seq_for is None:
            return ""
        if vid in self._vec_seq_cache:
            return self._vec_seq_cache[vid]
        try:
            seq = str(self._vector_seq_for(vid) or "").upper()
        except Exception:
            _log.debug("clone-region modal: vector seq resolve failed for %r",
                       vid, exc_info=True)
            seq = ""
        self._vec_seq_cache[vid] = seq
        return seq

    @on(Select.Changed, "#cre-vector")
    def _on_vector_changed(self, event: Select.Changed) -> None:
        vid = "" if event.value in (Select.BLANK, None) else str(event.value)
        self._vector_id = vid
        # Re-marking must never crash the picker — fall back to the existing
        # selection on any failure (the cut-site backstops still apply later).
        try:
            vseq = self._resolve_vector_seq(vid)
            opts = _cloning_enzyme_options(self._insert_seq, vseq or None)
            pair = _suggest_cloning_pair(self._insert_seq, vseq or None)
            d5, d3 = self._default_pair(opts, pair)
            s5 = self.query_one("#cre-enz5", Select)
            s3 = self.query_one("#cre-enz3", Select)
            with self.prevent(Select.Changed):
                s5.set_options(opts); s5.value = d5
                s3.set_options(opts); s3.value = d3
            self.query_one("#cre-hint", Static).update(
                self._compose_hint(self._insert_seq, vseq or None))
        except NoMatches:
            pass
        except Exception:
            _log.debug("clone-region modal: vector re-mark failed",
                       exc_info=True)

    def on_mount(self) -> None:
        # Default the dropdowns to the suggested insert-safe pair (compose set a
        # plausible default; refine once mounted so the suggestion wins).
        pair = _suggest_cloning_pair(self._insert_seq)
        if not pair:
            return
        try:
            opts = _cloning_enzyme_options(self._insert_seq)
            d5, d3 = self._default_pair(opts, pair)
            with self.prevent(Select.Changed):
                self.query_one("#cre-enz5", Select).value = d5
                self.query_one("#cre-enz3", Select).value = d3
        except NoMatches:
            pass

    def action_cancel(self) -> None:
        self.dismiss(None)

    @on(Button.Pressed, "#cre-cancel")
    def _cancel(self, _: Button.Pressed) -> None:
        self.dismiss(None)

    @on(Button.Pressed, "#cre-clone")
    def _clone(self, _: Button.Pressed) -> None:
        self._submit()

    @on(Input.Submitted, "#cre-name")
    def _name_submitted(self, _: Input.Submitted) -> None:
        # Enter in the name box clones (if both enzymes are picked) — the same
        # path as the Clone button, so the keyboard-only flow doesn't dead-end.
        self._submit()

    def _submit(self) -> None:
        try:
            enz5 = str(self.query_one("#cre-enz5", Select).value or "")
            enz3 = str(self.query_one("#cre-enz3", Select).value or "")
            raw  = str(self.query_one("#cre-name", Input).value or "")
        except NoMatches:
            self.dismiss(None)
            return
        if not enz5 or not enz3 or "BLANK" in enz5 or "BLANK" in enz3:
            self.notify("Pick an enzyme for each end.", severity="warning")
            return
        # Strip control bytes (a pasted name can carry them) + cap length so a
        # hostile / giant name can't bloat the donor row, the primer names, or
        # the toast. An empty / whitespace-only result falls back to the
        # caller's auto "<plasmid> <start>-<end>" label.
        name = _CONTROL_CHARS_RE.sub("", raw).strip()[:64]
        self.dismiss({"enz5": enz5, "enz3": enz3, "name": name,
                      "vector_id": self._vector_id})




class OperonCureModal(_OneShotDismissScreen, ModalScreen):
    """Manual cure for the NON-coding forbidden sites the auto-cure left intact
    (it never silently mutates a non-coding base — an RBS / regulator change
    would alter expression). Per site the user picks one valid single-base fix;
    only fixes that destroy the site WITHOUT spawning a new one are offered.
    Dismisses with a list of ``{pos, to}`` edits, or ``None`` on cancel."""

    BINDINGS = [Binding("escape", "cancel", "Cancel")]
    DEFAULT_CSS = """
    OperonCureModal { align: center middle; }
    #ocm-dlg {
        width: 84; height: auto; max-height: 90%;
        background: $surface; border: solid $primary; padding: 1 2;
    }
    #ocm-title {
        background: $primary-darken-2; color: $text;
        padding: 0 1; margin-bottom: 1; text-align: center;
    }
    #ocm-hint { color: $text-muted; margin-bottom: 1; }
    #ocm-list { height: auto; max-height: 20; }
    #ocm-list Select { margin-bottom: 1; }
    #ocm-btns { height: 3; margin-top: 1; align: right middle; }
    #ocm-btns Button { margin-left: 1; }
    """

    def __init__(self, seq: str, sites: "list[dict]", grammar: dict,
                 *, locked: "list[dict] | None" = None) -> None:
        super().__init__()
        self._seq = seq
        self._forbidden = (grammar.get("forbidden_sites")
                           or _GB_DOMESTICATION_FORBIDDEN)
        self._locked = list(locked or [])
        # Precompute the valid single-base fixes for each fixable site once.
        self._options: "list[tuple[dict, list[dict]]]" = []
        for s in (sites or []):
            opts = _operon_manual_fix_options(
                seq, int(s["pos"]), len(str(s["site"])), self._forbidden)
            self._options.append((s, opts))

    def compose(self) -> ComposeResult:
        with Vertical(id="ocm-dlg"):
            yield Static(" Manual cure — non-coding sites ", id="ocm-title")
            yield Static(
                "These forbidden sites sit outside any CDS. Pick a base fix for "
                "each (only fixes that don't spawn a new site are offered):",
                id="ocm-hint", markup=False)
            with VerticalScroll(id="ocm-list"):
                for i, (s, opts) in enumerate(self._options):
                    label = f"{s['enzyme']} {s['site']} at +{int(s['pos']) + 1}"
                    if opts:
                        yield Static(label, markup=False)
                        yield Select([(o["label"], str(j))
                                      for j, o in enumerate(opts)],
                                     id=f"ocm-sel-{i}", allow_blank=False,
                                     value="0")
                    else:
                        yield Static(
                            f"[red]{label} — no single-base fix; pick a "
                            f"different region.[/]", markup=True)
                for lk in self._locked:
                    yield Static(
                        f"[yellow]{lk['enzyme']} {lk['site']} at "
                        f"+{int(lk['pos']) + 1} — inside a CDS, no synonymous "
                        f"cure.[/]", markup=True)
            with Horizontal(id="ocm-btns"):
                yield Button("Apply fixes", id="ocm-apply", variant="primary")
                yield Button("Cancel", id="ocm-cancel")

    @on(Button.Pressed, "#ocm-cancel")
    def _on_cancel(self, _: Button.Pressed) -> None:
        self.dismiss(None)

    def action_cancel(self) -> None:
        self.dismiss(None)

    @on(Button.Pressed, "#ocm-apply")
    def _on_apply(self, _: Button.Pressed) -> None:
        edits: "list[dict]" = []
        unresolved = len(self._locked)
        for i, (s, opts) in enumerate(self._options):
            if not opts:
                unresolved += 1
                continue
            try:
                j = int(str(self.query_one(f"#ocm-sel-{i}", Select).value))
            except (NoMatches, ValueError):
                unresolved += 1
                continue
            if 0 <= j < len(opts):
                o = opts[j]
                edits.append({"pos": o["pos"], "to": o["to"]})
        if unresolved:
            self.app.notify(
                f"{unresolved} site(s) can't be cured here — the operon may "
                "still cut; pick a different region for those.",
                severity="warning")
        self.dismiss(edits)


class SynthesisScreen(_OneShotDismissScreen, Screen):
    """Full-screen gene-synthesis composer.

    Toolbar (top row): New / Load / Save / Save As / Rename / Insert site /
    Add feature / Close. Status bar shows name + bp + dirty flag. Editor
    fills the rest.

    Document model on save: ``_loaded_id`` carries the library entry id
    we're currently editing. On Save:
      * If ``_loaded_id`` is set → silent replace by id (the id-match
        branch in ``LibraryPanel.add_entry``).
      * If ``_loaded_id`` is None → prompt for name via
        ``NamePlasmidModal``; on accept, set ``_loaded_id`` and save.
    Save As always prompts, then re-targets ``_loaded_id``.

    Dismisses with ``None`` on Close / Esc. If the buffer is dirty,
    pushes ``SynthesisUnsavedChangesModal`` first.
    """

    # App-level Ctrl+Z would otherwise pop the canvas underneath while
    # the user is composing a fragment (invariant #41 — modal Ctrl+Z
    # opts out).
    _blocks_undo: bool = True

    BINDINGS = [
        Binding("escape", "cancel",        "Close", show=True),
        Binding("ctrl+s", "save",          "Save",  show=True),
        Binding("ctrl+n", "new_fragment",  "New",   show=True),
        Binding("ctrl+o", "load_fragment", "Load",  show=True),
        # Alt+Shift+F adds a feature (moved off Ctrl+F 2026-06-01 to keep
        # the add-feature key uniform with the main canvas, where Ctrl+F
        # is now Find-sequence). NOT Alt+F — Textual decodes ESC-f as
        # `ctrl+right` (see the PlasmidApp binding note). The synthesis
        # editor has no #seq-panel, so it doesn't wire a Find here.
        Binding("alt+shift+f", "add_feature",   "Add feature", show=True),
        Binding("ctrl+r", "insert_site",   "Insert site", show=True),
        # R (bare) — reveal restriction cut sites on the DNA tab, mirroring
        # the main sequence panel's `r` overlay toggle. The DNA editor
        # doesn't type 'R' (its keyboard set is ACGTN), so a bare R bubbles
        # up to this binding; on the protein tab the editor consumes 'R' as
        # Arg, so this never fires there (and the action guards anyway).
        Binding("r",      "toggle_restr_sites", "Cut sites", show=True),
        # Ctrl+Z / Ctrl+Y — undo / redo edits in the active tab's editor
        # (typed bases, deletes, pastes, inserts, feature edits). Screen-
        # level so they win over the app's canvas undo while Synthesis is
        # open. The editors' on_key already lets ctrl+z / ctrl+y bubble up.
        Binding("ctrl+z", "undo", "Undo", show=True),
        Binding("ctrl+y", "redo", "Redo", show=False),
        # Ctrl+C — copy the ACTIVE tab editor's selection (byte-perfect)
        # + carry its features. `priority=True` so it wins over the app's
        # own `ctrl+c` (also priority), which targets the main #seq-panel
        # (absent under Synthesis) — otherwise a Synthesis copy grabbed
        # the wrong / empty selection.
        Binding("ctrl+c", "copy_selection", "Copy", show=False,
                priority=True),
        Binding("ctrl+a", "select_all",    "Select all", show=False),
        # Screen-level Backspace / Delete fallback — only fires when
        # no focused widget consumed the keystroke (Input widgets
        # handle their own backspace internally, so this doesn't
        # interfere with typing in the search / name inputs). Routes
        # to the active editor's delete_at_cursor when the editor has
        # a visible selection — so a Ctrl+A → Backspace sequence
        # erases the highlighted fragment even if focus has drifted.
        Binding("backspace", "delete_selection_backward",
                "Delete selection", show=False),
        Binding("delete",    "delete_selection_forward",
                "Delete selection", show=False),
        # Alt+T — toggle protein-tab codon-translated mode vs
        # AA-only mode. No-op on the DNA tab. (NOT Ctrl+M — Ctrl+M is
        # the CR control character ^M at the terminal protocol level,
        # so the terminal swallows it before Textual sees it. Alt+T
        # sends an ESC-prefixed sequence that's unambiguous across
        # every supported terminal.)
        Binding("alt+t", "toggle_codon_mode", "AA mode toggle", show=True),
        Binding("tab",    "app.focus_next", "Next",      show=False),
    ]

    DEFAULT_CSS = """
    #syn-box {
        width: 100%; height: 1fr;
        background: $surface; padding: 0 1;
    }
    #syn-title {
        background: $primary-darken-2; color: $text;
        padding: 0 1; height: 1; text-align: center;
    }
    #syn-toolbar {
        height: 3; margin-top: 1; align: left middle;
        overflow-x: auto; overflow-y: hidden; scrollbar-size-horizontal: 1;
    }
    #syn-toolbar Button {
        margin-right: 1; min-width: 12;
    }
    #syn-status {
        height: 1; padding: 0 1; color: $text-muted;
    }
    /* Body split: editor on the left, feature library on the right.
       Mirrors the ExperimentsScreen entries-vs-details split. */
    #syn-tabs { width: 100%; height: 1fr; margin-top: 1; }
    #syn-tabs > TabPane { padding: 0; }
    #syn-dna-body-split, #syn-protein-body-split {
        width: 100%; height: 1fr; margin-top: 0;
    }
    #syn-editor-frame, #syn-protein-editor-frame {
        width: 4fr; height: 1fr;
        border: solid $primary-darken-2;
    }
    #syn-featlib-pane, #syn-motif-pane {
        width: 1fr; min-width: 28; height: 1fr;
        padding: 0 0 0 1;
    }
    #syn-featlib-title, #syn-motif-title {
        height: 1; color: $text-muted; padding: 0 1; text-align: center;
    }
    #syn-featlib-search, #syn-motif-search { height: 3; margin-top: 0; }
    #syn-featlib-table, #syn-motif-table {
        height: 1fr; min-height: 6;
        border: solid $primary-darken-2;
    }
    /* Four action buttons in a narrow (~1fr) side pane don't fit in a
       single row — at the editor's 4fr / pane 1fr split the pane is
       only ~30 cols, so a one-row layout pushed buttons 3 + 4 off the
       right edge (invisible). Lay them out 2x2 so every button stays
       on-screen regardless of terminal width. */
    #syn-featlib-btns, #syn-motif-btns {
        layout: grid;
        grid-size: 2 2;
        grid-columns: 1fr 1fr;
        grid-rows: 3;
        grid-gutter: 0 1;
        height: 6; margin-top: 1;
    }
    #syn-featlib-btns Button, #syn-motif-btns Button {
        width: 1fr; min-width: 8;
    }
    #syn-featlib-hint {
        height: 2; color: $text-muted; padding: 0 1;
    }
    /* "Open" loads an amino-acid sequence from a file into the protein
       editor — full-width below the motif buttons (where the catalog
       hint used to sit). */
    #btn-syn-protein-open { width: 100%; margin-top: 1; }
    /* Protein-tab top row: codon table + mode toggle. */
    #syn-protein-controls {
        height: 3; margin-top: 1; align: left middle;
    }
    #syn-codon-table-label { width: auto; padding: 1 1 0 1; color: $text-muted; }
    #syn-codon-table-select { width: 36; }
    #btn-syn-codon-manage { width: 12; min-width: 12; margin-left: 1; }
    #syn-codon-mode-label { width: auto; padding: 1 1 0 2; color: $text-muted; }
    #btn-syn-toggle-codon-mode { width: 18; min-width: 18; margin-left: 1; }
    #syn-protein-actions { height: 3; align: left middle; }
    #syn-codon-stops-label { width: auto; padding: 1 1 0 1; color: $text-muted; }
    #syn-codon-stops { width: 12; }
    #btn-syn-forbidden { width: 18; min-width: 18; margin-left: 1; }
    #btn-syn-optimize-dna { width: 18; min-width: 18; margin-left: 1; }
    #btn-syn-protein-clear { width: 9; min-width: 9; margin-left: 1; }
    /* DNA editor "Clear" — a thin action row below the editor; the
       editor takes the remaining height above it. */
    #syn-editor { height: 1fr; }
    #syn-dna-actions { height: 3; align: left middle; }
    #btn-syn-dna-clear { width: 9; min-width: 9; }
    #syn-bottom {
        height: 3; margin-top: 1; align: right middle;
    }
    #syn-bottom Button { margin-left: 1; min-width: 12; }
    /* Operon Design tab: builder (left, 3fr) + protein library (right, 1fr). */
    #syn-operon-split { width: 100%; height: 1fr; }
    #syn-operon-build { width: 4fr; height: 1fr; padding: 0 1 0 0; }
    #syn-operon-title {
        height: 1; background: $primary-darken-2; color: $text; padding: 0 1; text-align: center;
    }
    #syn-operon-lane {
        height: 2fr; min-height: 6; border: solid $primary-darken-2;
    }
    #syn-operon-lane-btns { height: 3; margin-top: 1; align: left middle; }
    #syn-operon-lane-btns Button { margin-right: 1; min-width: 5; }
    #syn-operon-flanks { height: 3; margin-top: 1; align: left middle; }
    .syn-operon-flank-label {
        width: auto; padding: 1 1 0 1; color: $text-muted;
    }
    #syn-operon-promoter, #syn-operon-terminator { width: 1fr; min-width: 12; }
    #syn-operon-actions { height: 3; margin-top: 1; align: left middle; }
    #syn-operon-actions Button { margin-right: 1; min-width: 16; }
    #syn-operon-output {
        height: 1fr; min-height: 4; padding: 0 1; margin-top: 1;
        border: solid $primary-darken-2; overflow-y: auto;
    }
    /* Native Operon Domestication sub-tab. */
    #syn-native-build { width: 100%; height: 1fr; padding: 0 1; }
    #syn-native-title {
        height: 1; background: $primary-darken-2; color: $text; padding: 0 1; text-align: center;
    }
    #syn-native-src-btns { height: 3; margin-top: 1; align: left middle; }
    #syn-native-src-btns Button { margin-right: 1; min-width: 14; }
    #syn-native-grammar-row { height: 3; margin-top: 1; align: left middle; }
    .syn-native-label { width: auto; padding: 1 1 0 1; color: $text-muted; }
    #syn-native-grammar { width: 1fr; min-width: 18; }
    #syn-native-extra-row { height: 3; margin-top: 1; align: left middle; }
    #syn-native-extra-enz { width: 1fr; min-width: 18; }
    #syn-native-actions { height: 3; margin-top: 1; align: left middle; }
    #syn-native-actions Button { margin-right: 1; min-width: 16; }
    #syn-native-output {
        height: 1fr; min-height: 6; padding: 0 1; margin-top: 1;
        border: solid $primary-darken-2; overflow-y: auto;
    }
    #syn-operon-lib-pane {
        width: 1fr; min-width: 30; height: 1fr; padding: 0 0 0 1;
    }
    #syn-operon-lib-title {
        height: 1; background: $primary-darken-2; color: $text; padding: 0 1; text-align: center;
    }
    #syn-operon-coll-select { width: 100%; }
    #syn-operon-prot-table {
        height: 1fr; min-height: 6; border: solid $primary-darken-2;
        margin-top: 1;
    }
    #syn-operon-lib-btns {
        layout: grid; grid-size: 2 4; grid-columns: 1fr 1fr;
        grid-rows: 3; grid-gutter: 0 1; height: 12; margin-top: 1;
    }
    #syn-operon-lib-btns Button { width: 1fr; min-width: 8; }
    """

    def __init__(self) -> None:
        super().__init__()
        # Per-tab document state. The DNA / Protein tabs each track
        # their own loaded library entry id, display name, and dirty
        # snapshot so switching tabs preserves edit context. Save /
        # Load / Rename actions dispatch based on the active tab.
        # `_loaded_id` / `_loaded_name` / `_dirty` / `_saved_snapshot`
        # are kept as the DNA-tab aliases so the existing handlers
        # don't need rewiring; the protein tab carries explicit
        # `_protein_*` variants. `_active_tab` is one of "dna" /
        # "protein" — read from the TabbedContent's active id on
        # action dispatch.
        self._loaded_id:   "str | None" = None
        self._loaded_name: "str | None" = None
        # Collection the DNA fragment was last saved into (chosen at
        # save time). Re-saves route back here so the document doesn't
        # duplicate into the active collection. None → active. [2026-05-30]
        self._loaded_collection: "str | None" = None
        self._saved_snapshot: "tuple[str, list[dict]] | None" = ("", [])
        self._dirty: bool = False
        # Feature library side panel — DNA tab.
        self._featlib_rows: list[tuple[str, dict]] = []
        # Protein tab state.
        self._protein_loaded_id:   "str | None" = None
        self._protein_loaded_name: "str | None" = None
        self._protein_loaded_collection: "str | None" = None
        self._protein_saved_snapshot: "str" = ""
        self._protein_dirty: bool = False
        # Stops selector auto-tracks the protein's trailing-'*' count (0 if
        # none); a manual change flips this False so the selector is then
        # authoritative on Optimize. A fresh load / open / new re-enables it.
        self._stops_auto: bool = True
        self._motif_rows: list[tuple[str, dict]] = []
        # Last directory the protein "Open" file picker landed in, so a
        # second Open re-opens where the user left off (None → $HOME).
        self._protein_open_dir: "str | None" = None
        # Active codon table — id ("name|taxid") plus raw dict. Set
        # by `_apply_codon_table_choice` on Select.Changed; defaults
        # to the first available table (built-in E. coli K12 always
        # present per `_codon_tables_load` invariant).
        self._codon_table_choice: "str" = ""
        self._codon_table_raw: dict = {}
        # Lock guarding cross-tab save operations so concurrent
        # actions (rapid Ctrl+S spam, GUI-vs-keyboard double-fire)
        # can't interleave a half-built SeqRecord with another
        # tab's. ATOMIC: build + library hand-off all happen inside.
        import threading as _thr
        self._save_lock = _thr.RLock()
        # Cached active-tab identifier — refreshed by
        # `_active_tab_id()` which queries the TabbedContent.
        self._active_tab_cache: str = "dna"
        # Operon Design tab. `_operon_genes` is the ordered gene list
        # (5'→3'); each gene is {name, cds (DNA), target (relative RBS
        # strength), achieved (float|None), on_target (bool|None)}. The
        # protein library panel on the right mirrors
        # `_load_protein_collections()`; `_operon_coll_choice` is the
        # selected collection name, `_operon_prot_rows` its proteins.
        self._operon_genes: list[dict] = []
        self._operon_coll_choice: str = ""
        self._operon_prot_rows: list[dict] = []
        self._operon_result: "dict | None" = None
        # Native Operon Domestication sub-tab: a lifted natural operon
        # {seq, feats (start/end/strand/type/label rebased to [0, span)),
        # source, name} pending cure + grammar clone (Phases 4-5). None until
        # the user lifts one.
        self._native_operon: "dict | None" = None
        # The cure + SOE design result {cured_seq, edits, primers, ...} and the
        # user's accumulated manual non-coding base fixes for the current run.
        self._native_result: "dict | None" = None
        self._native_manual_edits: "list[dict]" = []
        # ── Undo / redo ──────────────────────────────────────────────
        # Per-tab snapshot stacks. Each stack holds the FULL edit history
        # for that tab with the TOP being the current committed state, so
        # undo = pop current → redo, then re-apply the new top (the prior
        # state). Seeded on `on_mount` + reset on every editor `Loaded`
        # (new / load fragment) so Ctrl+Z can't reach a different
        # document's edits. `_undo_suspended` gates the Changed capture
        # while `apply_snapshot` repaints (an undo must not push itself).
        self._dna_undo: "list[dict]" = []
        self._dna_redo: "list[dict]" = []
        self._protein_undo: "list[dict]" = []
        self._protein_redo: "list[dict]" = []
        self._undo_suspended: bool = False

    # Cap on retained undo depth per tab — deep enough to cover a long
    # editing session, bounded so a scripted mega-paste loop can't grow
    # the stack without limit (each snapshot copies the feature list).
    _UNDO_MAX: int = 250

    def check_action(self, action: str, parameters: tuple) -> bool | None:
        return True

    def compose(self) -> ComposeResult:
        yield Header()
        # Carry the SpliceCraft top menu bar onto this screen (same pattern
        # as BABS / AUTOLAB) so the user can jump straight to another tool
        # without closing Synthesis first — the MenuBar self-dispatches to
        # `app.open_menu`. `action_open_synthesis` resurfaces this screen
        # instead of stacking a duplicate when Synthesis is re-clicked.
        with _MenuBarScroll(id="menubar-scroll"):
            yield MenuBar(id="menubar")
        with Vertical(id="syn-box"):
            yield Static(
                " Synthesis — gene-fragment composer ", id="syn-title",
            )
            with Horizontal(id="syn-toolbar"):
                yield Button("New",       id="btn-syn-new",
                              variant="primary")
                yield Button("Load",      id="btn-syn-load")
                yield Button("Save",      id="btn-syn-save",
                              variant="success")
                yield Button("Save As",   id="btn-syn-saveas")
                yield Button("Rename",    id="btn-syn-rename")
                yield Button("Insert Site", id="btn-syn-insertsite")
                yield Button("Add Feature", id="btn-syn-addfeat")
                yield Button("L0 Fragment", id="btn-syn-l0")
                yield Button("Clone Fragment", id="btn-syn-clone",
                              variant="warning")
            yield Static("", id="syn-status", markup=True)
            with TabbedContent(initial="syn-tab-dna", id="syn-tabs"):
                with TabPane("DNA", id="syn-tab-dna"):
                    yield from self._compose_dna_pane()
                with TabPane("Protein", id="syn-tab-protein"):
                    yield from self._compose_protein_pane()
                with TabPane("Operon Design", id="syn-tab-operon"):
                    # Two sub-modes: the original forward-design workbench
                    # (proteins → tuned RBS → assembled operon) and the new
                    # Native Operon Domestication (lift a natural operon → cure
                    # unwanted sites → clone into any grammar). Nested
                    # TabbedContent with its OWN id + unique tab ids so its CSS
                    # never collides with the outer #syn-tabs (cf. the #fsm
                    # id-collision lesson); its TabActivated stays unhandled
                    # since the outer handler is scoped to "#syn-tabs".
                    with TabbedContent(initial="syn-op-sub-synthetic",
                                       id="syn-operon-subtabs"):
                        with TabPane("Synthetic Operon Construction",
                                     id="syn-op-sub-synthetic"):
                            yield from self._compose_operon_pane()
                        with TabPane("Native Operon Domestication",
                                     id="syn-op-sub-native"):
                            yield from self._compose_native_operon_pane()
            with Horizontal(id="syn-bottom"):
                yield Button("Close", id="btn-syn-close")
        yield Footer()

    def _compose_dna_pane(self) -> ComposeResult:
        with Horizontal(id="syn-dna-body-split"):
            with Vertical(id="syn-editor-frame"):
                yield SynthesisEditor(id="syn-editor")
                # Mouse twin for Ctrl+N / toolbar New — clears the DNA
                # editor (prompts to save first when there are unsaved
                # edits), so every keyboard reset has a button on-tab.
                with Horizontal(id="syn-dna-actions"):
                    yield Button(
                        "Clear", id="btn-syn-dna-clear",
                        tooltip="Empty the DNA editor (prompts to save "
                                "first if there are unsaved changes).",
                    )
            with Vertical(id="syn-featlib-pane"):
                yield Static(
                    "[b]Feature library[/b]",
                    id="syn-featlib-title", markup=True,
                )
                yield Input(
                    placeholder="filter by name or type",
                    id="syn-featlib-search",
                )
                yield DataTable(
                    id="syn-featlib-table",
                    cursor_type="row",
                    zebra_stripes=True,
                )
                with Horizontal(id="syn-featlib-btns"):
                    yield Button(
                        "Insert", id="btn-syn-featlib-insert",
                        variant="primary",
                        tooltip=(
                            "Insert this feature's sequence at the "
                            "cursor AND annotate it."
                        ),
                    )
                    yield Button(
                        "Annotate", id="btn-syn-featlib-annotate",
                        tooltip=(
                            "Annotate the current selection with this "
                            "feature's type / colour (no DNA change). "
                            "Requires a selection."
                        ),
                    )
                    yield Button(
                        "Edit", id="btn-syn-featlib-edit",
                        tooltip=(
                            "Edit the selected library entry — "
                            "opens the same modal Features menu uses."
                        ),
                    )
                    yield Button(
                        "↻", id="btn-syn-featlib-refresh",
                        tooltip="Reload from the feature library "
                                 "(picks up entries added since opening "
                                 "Synthesis).",
                    )
                yield Static(
                    "[dim]Insert = sequence + annotation at cursor. "
                    "Annotate = overlay onto current selection.[/]",
                    id="syn-featlib-hint", markup=True,
                )

    def _compose_operon_pane(self) -> ComposeResult:
        with Horizontal(id="syn-operon-split"):
            # Left — the operon builder (lane + flanks + assemble + output).
            with Vertical(id="syn-operon-build"):
                yield Static(
                    "[b]Operon assembly[/b] — order CDSs 5'→3', tune each RBS",
                    id="syn-operon-title", markup=True,
                )
                yield DataTable(
                    id="syn-operon-lane", cursor_type="row",
                    zebra_stripes=True,
                )
                with Horizontal(id="syn-operon-lane-btns"):
                    yield Button("↑", id="btn-operon-up",
                                  tooltip="Move the selected gene up")
                    yield Button("↓", id="btn-operon-down",
                                  tooltip="Move the selected gene down")
                    yield Button("✕", id="btn-operon-remove",
                                  variant="error",
                                  tooltip="Remove the selected gene")
                    yield Button("Set target", id="btn-operon-target",
                                  tooltip="Set this gene's target relative "
                                          "RBS strength — the tuning knob.")
                with Horizontal(id="syn-operon-flanks"):
                    yield Static("Promoter:", classes="syn-operon-flank-label")
                    yield Input(placeholder="optional 5' promoter (DNA)",
                                id="syn-operon-promoter")
                    yield Static("Terminator:",
                                 classes="syn-operon-flank-label")
                    yield Input(placeholder="optional 3' terminator (DNA)",
                                id="syn-operon-terminator")
                with Horizontal(id="syn-operon-actions"):
                    yield Button("Assemble operon", id="btn-operon-assemble",
                                  variant="primary")
                    yield Button("→ DNA tab", id="btn-operon-to-dna",
                                  tooltip="Send the assembled operon to the "
                                          "DNA tab to add cut sites or clone "
                                          "it as a fragment.")
                yield Static(
                    "[dim]Design an operon:  1) New coll  2) Fetch / Paste / "
                    "Feature proteins\n 3) pick a protein → + Operon  "
                    "4) ↑ ↓ order, Set target per gene\n 5) Promoter / "
                    "Terminator → Assemble  6) → DNA tab (cut sites / clone)[/]",
                    id="syn-operon-output", markup=True,
                )
            # Right — the protein library (collections + their proteins).
            with Vertical(id="syn-operon-lib-pane"):
                yield Static("[b]Protein library[/b]",
                             id="syn-operon-lib-title", markup=True)
                yield Select([], id="syn-operon-coll-select",
                             allow_blank=True, prompt="(no collections)")
                yield DataTable(
                    id="syn-operon-prot-table", cursor_type="row",
                    zebra_stripes=True,
                )
                with Horizontal(id="syn-operon-lib-btns"):
                    yield Button("+ Operon", id="btn-operon-add",
                                  variant="primary",
                                  tooltip="Add the selected protein to the "
                                          "operon (codon-optimized to DNA).")
                    yield Button("Feature", id="btn-operon-from-feature",
                                  tooltip="Add a CDS from any plasmid as a "
                                          "protein in this collection.")
                    yield Button("Fetch", id="btn-operon-fetch",
                                  tooltip="Fetch a protein from NCBI by "
                                          "accession (e.g. AAK98552 for "
                                          "luxC) into this collection.")
                    yield Button("Paste", id="btn-operon-paste",
                                  tooltip="Type / paste a protein sequence "
                                          "into this collection.")
                    yield Button("New coll", id="btn-operon-new-coll")
                    yield Button("Rename", id="btn-operon-rename-coll")
                    yield Button("Delete", id="btn-operon-delete",
                                  variant="error",
                                  tooltip="Delete the selected protein, or "
                                          "the collection if it's empty.")

    def _compose_native_operon_pane(self) -> ComposeResult:
        """Native Operon Domestication: lift a natural operon (canvas
        selection / library plasmid / NCBI fetch), cure its unwanted Type IIS
        sites with primers (Scrub engine — synonymous inside CDS features,
        manual single-base override outside), then clone it into any grammar
        with features preserved. SOE-PCR primer set (lifting from a microbe,
        not synthesizing — every edit must be carried by a primer). The full
        pipeline (lift + cure + SOE-PCR + grammar-clone) is shipped."""
        with Vertical(id="syn-native-build"):
            yield Static(
                "[b]Native Operon Domestication[/b] — lift a natural operon, "
                "cure unwanted cut sites, clone into any grammar",
                id="syn-native-title", markup=True,
            )
            with Horizontal(id="syn-native-src-btns"):
                yield Button("Lift selection", id="btn-native-lift-sel",
                             variant="primary",
                             tooltip="Lift the operon highlighted on the main "
                                     "canvas (drag-select it before opening "
                                     "Synthesis — the selection persists).")
                yield Button("From plasmid", id="btn-native-from-plasmid",
                             tooltip="Lift the operon from a library plasmid "
                                     "(auto-detects the CDS span).")
                yield Button("From NCBI", id="btn-native-from-ncbi",
                             tooltip="Fetch a record by accession and lift its "
                                     "operon (auto-detects the CDS span).")
            with Horizontal(id="syn-native-grammar-row"):
                yield Static("Clone into grammar:", classes="syn-native-label")
                yield Select(_grammar_dropdown_options(),
                             id="syn-native-grammar", allow_blank=False,
                             value=self._native_default_grammar())
            with Horizontal(id="syn-native-extra-row"):
                yield Static("Also cure:", classes="syn-native-label")
                yield Input(placeholder="extra enzymes to remove, e.g. "
                                        "EcoRI, KpnI",
                            id="syn-native-extra-enz")
            with Horizontal(id="syn-native-actions"):
                yield Button("Cure & design primers", id="btn-native-cure",
                             variant="primary",
                             tooltip="Find + cure unwanted Type IIS sites "
                                     "(synonymous inside CDS, manual outside) "
                                     "and design the SOE-PCR primer set.")
                yield Button("Clone into grammar", id="btn-native-clone",
                             variant="success", disabled=True,
                             tooltip="Save the cured operon (cassette + "
                                     "features) to the library + its SOE "
                                     "primers to the primer library.")
            yield Static(
                "[dim]No operon lifted yet. Highlight an operon on the canvas "
                "and press Lift selection, or pull one From plasmid / From "
                "NCBI.[/]",
                id="syn-native-output", markup=True,
            )

    def _compose_protein_pane(self) -> ComposeResult:
        # Codon-table + mode toggle row above the protein body.
        with Horizontal(id="syn-protein-controls"):
            yield Static("Codon table:", id="syn-codon-table-label")
            yield Select(
                self._codon_table_options(),
                id="syn-codon-table-select",
                allow_blank=False,
            )
            yield Button(
                "Manage", id="btn-syn-codon-manage",
                tooltip="Browse, fetch from Kazusa, import your own (TSV), "
                        "or delete codon usage tables. Changes show up here "
                        "immediately.",
            )
            yield Static("Mode:", id="syn-codon-mode-label")
            yield Button(
                "Codon-translated", id="btn-syn-toggle-codon-mode",
                tooltip="Alt+T — toggle codon display under each AA.",
            )
        # Optimize-action row: stop count, forbidden sites, hand-off to DNA.
        with Horizontal(id="syn-protein-actions"):
            yield Static("Stops:", id="syn-codon-stops-label")
            yield Select(
                [("0 stops", "0"), ("1 stop", "1"),
                 ("2 stops", "2"), ("3 stops", "3")],
                value="0", allow_blank=False, id="syn-codon-stops",
                tooltip="Stop codons appended when optimizing. Auto-tracks the "
                        "trailing '*' run in your protein (0 if none); change "
                        "it to override (then it wins). 2–3 are "
                        "frequency-matched to the organism.")
            yield Button(
                _forbidden_sites_label(), id="btn-syn-forbidden",
                variant="default",
                tooltip="Choose which restriction-enzyme sites to avoid "
                        "(scrub) during codon optimization.")
            yield Button(
                "Optimize → DNA", id="btn-syn-optimize-dna", variant="primary",
                tooltip="Codon-optimize this protein and open the CDS in the "
                        "DNA tab as an editable fragment.")
            # Mouse twin for the protein-tab clear.
            yield Button(
                "Clear", id="btn-syn-protein-clear",
                tooltip="Empty the protein editor (prompts to save first "
                        "if there are unsaved changes).")
        with Horizontal(id="syn-protein-body-split"):
            with Vertical(id="syn-protein-editor-frame"):
                yield ProteinEditor(id="syn-protein-editor")
            with Vertical(id="syn-motif-pane"):
                yield Static(
                    "[b]Protein motifs / domains[/b]",
                    id="syn-motif-title", markup=True,
                )
                yield Input(
                    placeholder="filter by name or type",
                    id="syn-motif-search",
                )
                yield DataTable(
                    id="syn-motif-table",
                    cursor_type="row",
                    zebra_stripes=True,
                )
                with Horizontal(id="syn-motif-btns"):
                    yield Button(
                        "Insert", id="btn-syn-motif-insert",
                        variant="primary",
                        tooltip="Insert this motif's amino acid "
                                 "sequence at the cursor.",
                    )
                    yield Button(
                        "New", id="btn-syn-motif-new",
                        tooltip="Add a new custom motif to your "
                                "persistent library.",
                    )
                    yield Button(
                        "Edit", id="btn-syn-motif-edit",
                        tooltip=(
                            "Edit the selected motif. Built-in motifs "
                            "are copied to your local library on first "
                            "edit so changes persist."
                        ),
                    )
                    yield Button(
                        "Delete", id="btn-syn-motif-delete",
                        tooltip="Delete the selected user motif "
                                "(built-ins can't be deleted).",
                    )
                yield Button(
                    "Open", id="btn-syn-protein-open",
                    tooltip=(
                        "Open a single-entry FASTA / amino-acid file and "
                        "load its sequence into the protein editor."
                    ),
                )

    def _codon_table_options(self) -> list[tuple[str, str]]:
        """Build the Select widget's options from the codon-table
        registry. Returns ``[(label, value)]`` where value is the
        registry's ``name|taxid`` identifier."""
        try:
            tables = _codon_tables_load()
        except (OSError, ValueError, json.JSONDecodeError):
            _log.exception(
                "SynthesisScreen: codon table load failed; falling back to K12",
            )
            tables = []
        if not tables:
            return [("E. coli K12", "E. coli K12|83333")]
        opts: list[tuple[str, str]] = []
        for t in tables:
            name = str(t.get("name", "?") or "?")
            taxid = str(t.get("taxid", "") or "")
            label = f"{name}" + (f"  ({taxid})" if taxid else "")
            value = f"{name}|{taxid}"
            opts.append((label, value))
        return opts

    def _refresh_codon_table_options(
        self, select_choice: "str | None" = None,
    ) -> None:
        """Rebuild the codon-table Select from the live registry so a table
        just fetched / imported / deleted in the manager shows up without
        reopening Synthesis. Keeps the current selection when it still
        exists; switches to `select_choice` (a ``name|taxid``) when given and
        present; otherwise falls back to the first option. Assigning the
        value drives `_on_codon_table_changed`, which re-applies the table to
        the ProteinEditor and persists `active_codon_table`."""
        try:
            sel = self.query_one("#syn-codon-table-select", Select)
        except NoMatches:
            return
        opts = self._codon_table_options()
        if not opts:
            return
        values = [v for _label, v in opts]
        target = next(
            (c for c in (select_choice,
                          getattr(self, "_codon_table_choice", None))
              if c and c in values),
            values[0],
        )
        sel.set_options(opts)
        sel.value = target

    @on(Button.Pressed, "#btn-syn-codon-manage")
    def _on_manage_codon_tables(self, _) -> None:
        # Reach the codon-table manager (browse / fetch from Kazusa / import
        # your own via TSV / delete) without leaving Synthesis. On return the
        # dropdown is rebuilt so the change is visible immediately; a table
        # the user "Used" becomes the active selection.
        self.app.push_screen(SpeciesPickerModal(),
                             callback=self._codon_manager_closed)

    def _codon_manager_closed(self, entry: "dict | None") -> None:
        choice = None
        if entry:
            name = str(entry.get("name", "") or "?")
            taxid = str(entry.get("taxid", "") or "")
            choice = f"{name}|{taxid}"
        self._refresh_codon_table_options(select_choice=choice)

    # ── Protein → DNA: codon-optimize and hand off to the DNA tab ───────────

    @on(Button.Pressed, "#btn-syn-optimize-dna")
    def _on_optimize_to_dna(self, _) -> None:
        """Codon-optimize the protein-tab sequence and open the CDS in the
        DNA tab as a fresh, editable fragment. The Stops selector sets how
        many stop codons are appended — it auto-tracks the protein's trailing
        '*' run, but a manual change is authoritative here; the result is
        BsaI-scrubbed. Prompts before clobbering an unsaved DNA buffer (the
        DNA tab carries its own dirty flag, `_dirty`)."""
        try:
            pe = self.query_one("#syn-protein-editor", ProteinEditor)
        except NoMatches:
            return
        # Sanitize exactly as Mutato does: drop whitespace/digits/separators
        # but keep '*' so a trailing-stop run is meaningful (and a mid-run
        # stop is an explicit error rather than a silent drop).
        aa = re.sub(r"[\s\d>_\-]", "", pe.get_state()[0] or "").upper()
        if not aa:
            self.app.notify("Enter a protein sequence first.",
                             severity="warning")
            return
        # Strip a trailing '*' run — the Stops selector (which auto-tracked it)
        # decides how many stops we emit, so the body itself is stop-free. A
        # '*' anywhere else is a real error (premature stop), not silently
        # dropped.
        body = aa
        while body.endswith("*"):
            body = body[:-1]
        if "*" in body:
            self.app.notify("Stop codon '*' is only allowed at the END of "
                            "the protein.", severity="warning")
            return
        if not body:
            self.app.notify("Enter at least one amino acid.",
                             severity="warning")
            return
        bad = sorted({c for c in body if c not in "ACDEFGHIKLMNPQRSTVWY"})
        if bad:
            self.app.notify(f"Invalid amino-acid letters: {''.join(bad)}",
                             severity="warning")
            return
        raw = self._codon_table_raw
        if not raw:
            self.app.notify("No codon table selected.", severity="warning")
            return
        # The Stops selector is AUTHORITATIVE: it auto-tracks the protein's
        # trailing-'*' run but a manual change wins, and whatever it shows at
        # click time is the count we emit (0..3). The old `n_trailing if
        # n_trailing else sel_stops` let a loaded protein's trailing '*'
        # silently override a higher explicit choice — the "I picked 3, got 1"
        # bug. Clamp to the selector's own 0..3 range, defensively.
        try:
            sel_stops = int(str(self.query_one("#syn-codon-stops",
                                                Select).value))
        except (NoMatches, ValueError, TypeError):
            sel_stops = 0
        n_stops = max(0, min(3, sel_stops))
        name = self._protein_loaded_name or "optimized protein"

        def _proceed() -> None:
            # Staleguard: the confirm-modal callback (or any deferred
            # dispatch) can fire after the Synthesis screen was torn down —
            # don't kick off a worker against a dead screen. The worker's
            # apply re-checks `is_mounted` before touching widgets too.
            if not self.is_mounted:
                return
            self.app.notify("Optimizing codons…", timeout=2)
            self._optimize_to_dna_worker(body, dict(raw), name, n_stops)

        # "Prompt to discard" — only when the DNA tab has unsaved edits.
        if not self._dirty:
            _proceed()
            return

        def _on_confirm(go: "bool | None") -> None:
            if go:
                _proceed()
        self.app.push_screen(SynthesisReplaceDnaConfirmModal(),
                             callback=_on_confirm)

    @work(thread=True, exclusive=True, group="synthesis_protein_optimize")
    def _optimize_to_dna_worker(self, body: str, raw: dict,
                                  name: str, stops: int) -> None:
        """Off-thread codon-optimize + BsaI site-scrub (mirrors Mutato's
        `_optimize_worker`)."""
        try:
            cds = _codon_optimize(body, raw, stops=stops)
            cds, fixes = _codon_fix_sites(cds, body, raw,
                                          sites=_codon_forbidden_sites())
        except Exception as exc:
            _log.exception("Synthesis: protein → DNA optimize failed")
            self.app.call_from_thread(
                self.app.notify,
                f"Codon optimization failed: {exc}", severity="error")
            return
        self.app.call_from_thread(
            self._apply_optimize_to_dna, body, cds, fixes, raw, name, stops)

    def _apply_optimize_to_dna(self, body: str, cds: str, fixes: list,
                                 raw: dict, name: str, stops: int) -> None:
        if not self.is_mounted:
            return
        try:
            tabs = self.query_one("#syn-tabs", TabbedContent)
            ed = self.query_one("#syn-editor", SynthesisEditor)
        except NoMatches:
            return
        cds_feat = {
            "start": 0, "end": len(cds), "label": name, "type": "CDS",
            "color": _GB_TYPE_COLORS.get("CDS", "white"), "strand": 1,
            "qualifiers": {"label": [name], "translation": [body]},
        }
        # Fresh, unsaved DNA fragment — Save will prompt for a library name.
        self._loaded_id = None
        self._loaded_collection = None
        self._loaded_name = name
        self._saved_snapshot = ("", [])
        self._dirty = True
        ed.load(cds, [cds_feat])
        tabs.active = "syn-tab-dna"
        self.call_after_refresh(self._focus_dna_editor)
        self._refresh_status()
        cai = _codon_cai(cds, raw)
        gc = _codon_gc(cds)
        fix_note = f" · {len(fixes)} BsaI fix(es)" if fixes else ""
        self.app.notify(
            f"Optimized {len(body)} aa → {len(cds)} nt CDS · "
            f"CAI {cai:.2f} · GC {gc:.1f}%{fix_note}. "
            f"Now editable in the DNA tab.",
            severity="information")
        _log_event("synthesis.protein.optimize_to_dna",
                   aa=len(body), nt=len(cds), n_stops=stops,
                   n_fixes=len(fixes))

    @on(Button.Pressed, "#btn-syn-forbidden")
    def _on_pick_forbidden_sites(self, _) -> None:
        _open_forbidden_sites_picker(self, "#btn-syn-forbidden")

    def on_mount(self) -> None:
        self._refresh_status()
        try:
            self.query_one("#syn-editor", SynthesisEditor)
        except NoMatches:
            pass
        try:
            t = self.query_one("#syn-featlib-table", DataTable)
            t.add_columns("Name", "Type", "bp")
        except NoMatches:
            pass
        self._refresh_featlib_table()
        # Protein-tab init: motif table headers + load first codon
        # table into both the cache and the editor.
        try:
            mt = self.query_one("#syn-motif-table", DataTable)
            mt.add_columns("Name", "Type", "aa")
        except NoMatches:
            pass
        self._refresh_motif_table()
        self._init_codon_table()
        # Operon Design tab: lane + protein-table headers, then load the
        # protein collections into the library panel.
        try:
            lane = self.query_one("#syn-operon-lane", DataTable)
            lane.add_columns("#", "Gene", "Target", "Achieved", "OK")
        except NoMatches:
            pass
        try:
            pt = self.query_one("#syn-operon-prot-table", DataTable)
            pt.add_columns("Protein", "aa")
        except NoMatches:
            pass
        self._operon_refresh_collections()
        self._operon_refresh_lane()
        # Persistence: a FRESH screen each open, so restore the composed
        # data the LAST screen saved to the app on dismiss (if any) BEFORE
        # seeding the undo baselines, so the baseline reflects the restored
        # content. No-op on the very first open (nothing saved yet).
        self._restore_state_from_app()
        # Seed undo baselines so the FIRST edit in each tab is undoable
        # back to the current (possibly just-restored) state. A later
        # `Loaded` (Clear / load fragment) re-seeds against that content.
        self._seed_undo_baselines()

    def dismiss(self, result=None):
        """Save the composed data to the app BEFORE the screen closes, so
        a fresh screen on the next open can restore it. Overrides
        `_OneShotDismissScreen.dismiss` (still one-shot via super)."""
        try:
            self._save_state_to_app()
        except Exception:
            _log.exception("SynthesisScreen: state save on dismiss failed")
        return super().dismiss(result)

    def _on_tab_switch_away(self) -> None:
        """Persist hook the app's true-switch calls JUST before popping
        this tab for another (a true-switch uses `pop_screen`, which does
        NOT run the `dismiss` override — this covers that path so the
        composed work is saved either way)."""
        self._save_state_to_app()

    def _save_state_to_app(self) -> None:
        """Snapshot the DNA / Protein / Operon work + loaded metadata onto
        the app (`_synthesis_state`) so the next fresh screen restores it.
        Editors are still mounted here (dismiss runs while active)."""
        state: dict = {}
        try:
            ed = self.query_one("#syn-editor", SynthesisEditor)
            state["dna"] = ed.snapshot()
        except NoMatches:
            pass
        try:
            pe = self.query_one("#syn-protein-editor", ProteinEditor)
            state["protein"] = pe.snapshot()
            state["protein_codon_mode"] = pe._codon_mode
        except NoMatches:
            pass
        # DNA / Protein loaded-entry metadata so a re-open re-saves to the
        # same library entry rather than duplicating.
        state["dna_meta"] = (self._loaded_id, self._loaded_name,
                             self._loaded_collection, self._dirty,
                             self._saved_snapshot)
        state["protein_meta"] = (self._protein_loaded_id,
                                 self._protein_loaded_name,
                                 self._protein_loaded_collection,
                                 self._protein_dirty,
                                 self._protein_saved_snapshot)
        # Operon builder state (plain lists/dicts — deep-copied so a later
        # in-screen mutation can't rewrite the saved copy).
        import copy as _copy
        state["operon"] = {
            "genes": _copy.deepcopy(self._operon_genes),
            "result": _copy.deepcopy(self._operon_result),
            "native": _copy.deepcopy(self._native_operon),
            "native_result": _copy.deepcopy(self._native_result),
            "coll": self._operon_coll_choice,
        }
        state["active_tab"] = self._active_tab_id()
        self.app._synthesis_state = state   # type: ignore[attr-defined]

    def _restore_state_from_app(self) -> None:
        """Restore the data saved by the previous screen's dismiss. Uses
        `apply_snapshot` (no Changed/Loaded) so it neither dirties nor
        churns undo; the codon table was re-seeded by `_init_codon_table`
        earlier in on_mount."""
        state = getattr(self.app, "_synthesis_state", None)
        if not isinstance(state, dict):
            return
        dna = state.get("dna")
        if isinstance(dna, dict):
            try:
                self.query_one("#syn-editor",
                               SynthesisEditor).apply_snapshot(dna)
            except NoMatches:
                pass
        prot = state.get("protein")
        if isinstance(prot, dict):
            try:
                pe = self.query_one("#syn-protein-editor", ProteinEditor)
                if not state.get("protein_codon_mode", True):
                    pe.set_codon_mode(False)
                pe.apply_snapshot(prot)
            except NoMatches:
                pass
        dm = state.get("dna_meta")
        if isinstance(dm, tuple) and len(dm) == 5:
            (self._loaded_id, self._loaded_name, self._loaded_collection,
             self._dirty, self._saved_snapshot) = dm
        pm = state.get("protein_meta")
        if isinstance(pm, tuple) and len(pm) == 5:
            (self._protein_loaded_id, self._protein_loaded_name,
             self._protein_loaded_collection, self._protein_dirty,
             self._protein_saved_snapshot) = pm
        op = state.get("operon")
        if isinstance(op, dict):
            self._operon_genes = op.get("genes") or []
            self._operon_result = op.get("result")
            self._native_operon = op.get("native")
            self._native_result = op.get("native_result")
            self._operon_coll_choice = op.get("coll", "")
            self._operon_refresh_lane()
        tab = state.get("active_tab")
        if tab in ("dna", "protein", "operon"):
            try:
                self.query_one("#syn-tabs", TabbedContent).active = \
                    f"syn-tab-{tab}"
            except NoMatches:
                pass
        self._refresh_status()

    def _seed_undo_baselines(self) -> None:
        """Reset both tabs' undo/redo stacks to a single baseline = the
        editor's current state. Called on mount + whenever a wholesale
        load replaces a buffer (via the editors' `Loaded` message)."""
        try:
            ed = self.query_one("#syn-editor", SynthesisEditor)
            self._dna_undo = [ed.snapshot()]
            self._dna_redo = []
        except NoMatches:
            pass
        try:
            pe = self.query_one("#syn-protein-editor", ProteinEditor)
            self._protein_undo = [pe.snapshot()]
            self._protein_redo = []
        except NoMatches:
            pass

    def _init_codon_table(self) -> None:
        """Seed the codon-table cache + push it to the ProteinEditor.
        Honors the persisted `active_codon_table` setting (sweep #20)
        — if set, picks the table whose taxid matches; otherwise falls
        back to the first registry entry (K12 by convention)."""
        try:
            tables = _codon_tables_load()
        except (OSError, ValueError, json.JSONDecodeError):
            tables = []
        if not tables:
            _log.warning("SynthesisScreen: no codon tables available")
            return
        # Sweep #20: honor the persisted `active_codon_table` setting.
        # Empty/missing/unknown taxid falls back to tables[0].
        preferred_taxid = str(_get_setting("active_codon_table", "") or "")
        picked = None
        if preferred_taxid:
            picked = next(
                (t for t in tables
                  if str(t.get("taxid", "") or "") == preferred_taxid),
                None,
            )
        if picked is None:
            picked = tables[0]
        name = str(picked.get("name", "?") or "?")
        taxid = str(picked.get("taxid", "") or "")
        choice = f"{name}|{taxid}"
        self._codon_table_choice = choice
        self._codon_table_raw = dict(picked.get("raw") or {})
        try:
            sel = self.query_one("#syn-codon-table-select", Select)
            # Force the Select to the same choice so the Select.Changed
            # handler doesn't fire on its own initial value.
            sel.value = choice
        except NoMatches:
            pass
        try:
            pe = self.query_one("#syn-protein-editor", ProteinEditor)
            pe.set_codon_table(self._codon_table_raw)
        except NoMatches:
            pass

    # ── Operon Design tab ──────────────────────────────────────────────────
    def _operon_refresh_collections(self) -> None:
        """Reload the protein-collection list into the Select, keeping the
        current choice if it still exists, then refresh the protein table."""
        try:
            sel = self.query_one("#syn-operon-coll-select", Select)
        except NoMatches:
            return
        names = [str(c.get("name") or "")
                 for c in _load_protein_collections() if c.get("name")]
        sel.set_options([(n, n) for n in names])
        if self._operon_coll_choice in names:
            sel.value = self._operon_coll_choice
        elif names:
            self._operon_coll_choice = names[0]
            sel.value = names[0]
        else:
            self._operon_coll_choice = ""
        self._operon_refresh_proteins()

    def _operon_refresh_proteins(self) -> None:
        """Populate the protein table from the selected collection."""
        try:
            pt = self.query_one("#syn-operon-prot-table", DataTable)
        except NoMatches:
            return
        coll = next((c for c in _load_protein_collections()
                     if c.get("name") == self._operon_coll_choice), None)
        prots = [p for p in (coll.get("proteins", []) if coll else [])
                 if isinstance(p, dict)]
        self._operon_prot_rows = prots
        cur = pt.cursor_row
        pt.clear()
        for p in prots:
            seq = str(p.get("sequence") or "")
            pt.add_row(str(p.get("name") or "?"), str(len(seq)))
        if prots and 0 <= cur < len(prots):
            try:
                pt.move_cursor(row=cur)
            except Exception:
                pass

    def _operon_refresh_lane(self) -> None:
        """Rebuild the operon lane DataTable from `_operon_genes`."""
        try:
            lane = self.query_one("#syn-operon-lane", DataTable)
        except NoMatches:
            return
        cur = lane.cursor_row
        lane.clear()
        for i, g in enumerate(self._operon_genes):
            ach = g.get("achieved")
            on = g.get("on_target")
            if g.get("cds") is None:
                ok = Text("optimizing…", style="yellow")
            elif on is None:
                ok = Text("—")
            elif on:
                ok = Text("✓", style="green")
            else:
                ok = Text("capped", style="yellow")
            lane.add_row(
                str(i + 1),
                str(g.get("name") or "?"),
                str(g.get("target")),
                "—" if ach is None else f"{ach:.1f}",
                ok,
            )
        if self._operon_genes and 0 <= cur < len(self._operon_genes):
            try:
                lane.move_cursor(row=cur)
            except Exception:
                pass

    @on(Select.Changed, "#syn-operon-coll-select")
    def _operon_coll_changed(self, event: Select.Changed) -> None:
        val = event.value
        self._operon_coll_choice = "" if val is Select.BLANK else str(val)
        self._operon_refresh_proteins()

    def _operon_notify(self, msg: str, *, error: bool = False) -> None:
        self.notify(msg, severity="error" if error else "information",
                    timeout=7)

    def _operon_selected_protein(self) -> "dict | None":
        try:
            pt = self.query_one("#syn-operon-prot-table", DataTable)
        except NoMatches:
            return None
        idx = pt.cursor_row
        rows = self._operon_prot_rows
        return rows[idx] if 0 <= idx < len(rows) else None

    @on(Button.Pressed, "#btn-operon-new-coll")
    def _operon_new_coll(self, _) -> None:
        def _done(result) -> None:
            name = (result or {}).get("name", "") if isinstance(result, dict) else ""
            if not name:
                return
            err = _protein_collection_create(name)
            if err:
                self._operon_notify(err, error=True)
                return
            self._operon_coll_choice = _sanitize_label(str(name).strip(),
                                                       max_len=200)
            self._operon_refresh_collections()
            self._operon_notify(f"Created collection {self._operon_coll_choice!r}.")
        self.app.push_screen(GroupNamePromptModal(
            "", title=" New protein collection ",
            prompt="Name for the new protein collection:",
            placeholder="e.g. Lux operon"), _done)

    @on(Button.Pressed, "#btn-operon-paste")
    def _operon_paste(self, _) -> None:
        coll = self._operon_coll_choice
        if not coll:
            self._operon_notify("Create or select a collection first.",
                                error=True)
            return

        def _done(result) -> None:
            if not isinstance(result, dict):
                return
            err = _protein_collection_add(coll, result["name"],
                                          result["sequence"], source="pasted")
            if err:
                self._operon_notify(err, error=True)
                return
            self._operon_refresh_proteins()
            self._operon_notify(f"Added {result['name']!r} to {coll!r}.")
        self.app.push_screen(_OperonProteinModal(title=" Paste protein "), _done)

    @on(Button.Pressed, "#btn-operon-rename-coll")
    def _operon_rename_coll(self, _) -> None:
        old = self._operon_coll_choice
        if not old:
            self._operon_notify("Select a collection to rename.", error=True)
            return

        def _done(result) -> None:
            name = (result or {}).get("name", "") if isinstance(result, dict) else ""
            if not name:
                return
            err = _protein_collection_rename(old, name)
            if err:
                self._operon_notify(err, error=True)
                return
            self._operon_coll_choice = _sanitize_label(str(name).strip(),
                                                       max_len=200)
            self._operon_refresh_collections()
            self._operon_notify(f"Renamed to {self._operon_coll_choice!r}.")
        self.app.push_screen(GroupNamePromptModal(
            old, title=" Rename collection ",
            prompt="New collection name:"), _done)

    @on(Button.Pressed, "#btn-operon-delete")
    def _operon_delete(self, _) -> None:
        coll = self._operon_coll_choice
        if not coll:
            self._operon_notify("No collection selected.", error=True)
            return
        p = self._operon_selected_protein()
        if p is not None:
            err = _protein_collection_remove(coll, str(p.get("name")))
            if err:
                self._operon_notify(err, error=True)
                return
            self._operon_refresh_proteins()
            self._operon_notify(f"Deleted protein {p.get('name')!r}.")
        else:
            err = _protein_collection_delete(coll)     # empty collection
            if err:
                self._operon_notify(err, error=True)
                return
            self._operon_coll_choice = ""
            self._operon_refresh_collections()
            self._operon_notify(f"Deleted collection {coll!r}.")

    @on(Button.Pressed, "#btn-operon-add")
    def _operon_add_gene(self, _) -> None:
        p = self._operon_selected_protein()
        if p is None:
            self._operon_notify("Select a protein in the library first.",
                                error=True)
            return
        if not self._codon_table_raw:
            self._operon_notify("No codon table loaded.", error=True)
            return
        prot = str(p.get("sequence") or "")
        name = str(p.get("name") or "gene")
        # Codon-optimize OFF the UI thread (2026-06-12 audit): a multi-kb
        # protein is a ~200-400 ms compute that froze the terminal on every
        # "Add gene" click. The gene row is appended immediately with a
        # `cds=None` placeholder (instant feedback + click-order preserved —
        # filling by object reference can't reorder the lane) and the worker
        # fills the CDS. Assemble guards against any still-pending gene.
        # Mirrors `_optimize_to_dna_worker`.
        gene: dict = {"name": name, "cds": None, "target": 10.0,
                      "achieved": None, "on_target": None}
        self._operon_genes.append(gene)
        self._operon_invalidate_results()   # a new gene changes every context
        self._operon_refresh_lane()
        self._operon_notify(f"Optimizing {name}…")
        self._operon_add_gene_worker(gene, prot, dict(self._codon_table_raw))

    @work(thread=True, group="operon_add_gene")
    def _operon_add_gene_worker(self, gene: dict, prot: str,
                                 raw: dict) -> None:
        """Off-thread codon-optimize for a freshly-added operon gene. NOT
        exclusive: each Add accumulates a distinct gene, so a second Add
        must not cancel the first."""
        try:
            cds = _codon_optimize(prot, raw)
        except ValueError as exc:
            self.app.call_from_thread(self._operon_cancel_pending_gene,
                                      gene, str(exc))
            return
        if cds[-3:].upper() not in ("TAA", "TAG", "TGA"):
            cds += "TAA"                                # ensure a stop codon
        self.app.call_from_thread(self._operon_apply_added_gene, gene, cds)

    def _operon_apply_added_gene(self, gene: dict, cds: str) -> None:
        if not self.is_mounted:
            return
        if not any(g is gene for g in self._operon_genes):
            return                          # row deleted while optimizing
        gene["cds"] = cds
        self._operon_invalidate_results()
        self._operon_refresh_lane()
        self._operon_notify(
            f"Added {gene.get('name')} ({len(cds)} bp). Set its target, "
            "then Assemble.")

    def _operon_cancel_pending_gene(self, gene: dict, err: str) -> None:
        if not self.is_mounted:
            return
        self._operon_genes[:] = [g for g in self._operon_genes if g is not gene]
        self._operon_refresh_lane()
        self._operon_notify(f"Codon optimization failed: {err}", error=True)

    def _operon_lane_cursor(self) -> "int | None":
        try:
            lane = self.query_one("#syn-operon-lane", DataTable)
        except NoMatches:
            return None
        idx = lane.cursor_row
        return idx if 0 <= idx < len(self._operon_genes) else None

    def _operon_invalidate_results(self) -> None:
        """Reordering / editing genes changes the assembled context, so the
        last achieved strengths are stale — clear them + the stored result."""
        for g in self._operon_genes:
            g["achieved"] = None
            g["on_target"] = None
        self._operon_result = None

    @on(Input.Changed, "#syn-operon-promoter, #syn-operon-terminator")
    def _operon_flank_changed(self, _) -> None:
        # Editing the promoter / terminator after an Assemble makes the
        # stored result stale — → DNA tab would export the OLD sequence.
        if self._operon_result is not None:
            self._operon_invalidate_results()
            self._operon_refresh_lane()
            try:
                self.query_one("#syn-operon-output", Static).update(
                    "[yellow]Flanks changed — re-Assemble before exporting.[/]")
            except NoMatches:
                pass

    @on(Button.Pressed, "#btn-operon-up")
    def _operon_up(self, _) -> None:
        self._operon_lane_move(-1)

    @on(Button.Pressed, "#btn-operon-down")
    def _operon_down(self, _) -> None:
        self._operon_lane_move(+1)

    def _operon_lane_move(self, delta: int) -> None:
        idx = self._operon_lane_cursor()
        if idx is None:
            return
        new = idx + delta
        if not (0 <= new < len(self._operon_genes)):
            return
        g = self._operon_genes
        g[idx], g[new] = g[new], g[idx]
        self._operon_invalidate_results()
        self._operon_refresh_lane()
        try:
            self.query_one("#syn-operon-lane", DataTable).move_cursor(row=new)
        except Exception:
            pass

    @on(Button.Pressed, "#btn-operon-remove")
    def _operon_remove(self, _) -> None:
        idx = self._operon_lane_cursor()
        if idx is None:
            self._operon_notify("Select a gene to remove.", error=True)
            return
        name = self._operon_genes.pop(idx).get("name")
        self._operon_invalidate_results()
        self._operon_refresh_lane()
        self._operon_notify(f"Removed {name}.")

    @on(Button.Pressed, "#btn-operon-target")
    def _operon_set_target(self, _) -> None:
        idx = self._operon_lane_cursor()
        if idx is None:
            self._operon_notify("Select a gene in the lane first.", error=True)
            return
        cur = self._operon_genes[idx].get("target", 10.0)

        def _done(result) -> None:
            raw = (result or {}).get("name", "") if isinstance(result, dict) else ""
            if raw == "":
                return
            if not (0 <= idx < len(self._operon_genes)):  # lane changed under us
                return
            try:
                val = float(str(raw).strip())
            except ValueError:
                self._operon_notify("Target must be a number.", error=True)
                return
            if val < 0:
                self._operon_notify("Target must be ≥ 0.", error=True)
                return
            self._operon_genes[idx]["target"] = val
            self._operon_genes[idx]["achieved"] = None
            self._operon_genes[idx]["on_target"] = None
            self._operon_result = None
            self._operon_refresh_lane()
        self.app.push_screen(GroupNamePromptModal(
            str(cur), title=" Set RBS target ",
            prompt="Target relative RBS strength (a number; higher = stronger):",
            placeholder="e.g. 100"), _done)

    @on(Button.Pressed, "#btn-operon-assemble")
    def _operon_assemble(self, _) -> None:
        if not self._operon_genes:
            self._operon_notify("Add at least one gene first.", error=True)
            return
        pending = sum(1 for g in self._operon_genes if g.get("cds") is None)
        if pending:
            self._operon_notify(
                f"Still optimizing {pending} gene(s) — try again in a moment.",
                error=True)
            return
        promoter = self.query_one("#syn-operon-promoter", Input).value.strip()
        terminator = self.query_one("#syn-operon-terminator", Input).value.strip()
        genes = [{"cds": g["cds"], "target_strength": g["target"],
                  "name": g["name"]} for g in self._operon_genes]
        # Off-thread: each gene runs ~14 RBS-strength evals, each an
        # O(n³) pure-Python RNA cofold ([INV-107]) — a 5-gene operon
        # froze the UI ~1–3 s. Exclusive so a re-Assemble cancels the
        # prior run; the apply path re-checks the captured inputs against
        # the live lane/flanks before writing (stale-result guard).
        # (2026-06-11 audit.)
        self._operon_notify(f"Assembling {len(genes)} gene(s)…")
        self._operon_assemble_worker(genes, promoter, terminator)

    @work(thread=True, exclusive=True, group="operon_assemble")
    def _operon_assemble_worker(self, genes: "list[dict]", promoter: str,
                                  terminator: str) -> None:
        try:
            result = _assemble_operon(genes, promoter=promoter,
                                      terminator=terminator)
        except Exception as exc:
            _log.exception("Operon assembly failed")
            self.app.call_from_thread(
                self._operon_notify, f"Assembly failed: {exc}", error=True)
            return
        self.app.call_from_thread(
            self._apply_operon_assembly, genes, promoter, terminator, result)

    def _apply_operon_assembly(self, genes: "list[dict]", promoter: str,
                                 terminator: str, result: dict) -> None:
        if not self.is_mounted:
            return
        # Stale-result guard: the user may have edited the gene lane or
        # the promoter/terminator while we assembled, which would make
        # `result` mislabel the live config. Re-read and compare the
        # captured inputs; discard the apply if anything moved.
        try:
            cur_prom = self.query_one(
                "#syn-operon-promoter", Input).value.strip()
            cur_term = self.query_one(
                "#syn-operon-terminator", Input).value.strip()
        except NoMatches:
            return
        if ([g["cds"] for g in self._operon_genes]
                != [g["cds"] for g in genes]
                or cur_prom != promoter or cur_term != terminator):
            return
        self._operon_result = result
        for g, r in zip(self._operon_genes, result["genes"]):
            g["achieved"] = r["rel_strength"]
            g["on_target"] = r["on_target"]
        self._operon_refresh_lane()
        self._operon_render_output(result)
        self._operon_notify(f"Assembled {len(result['sequence'])} bp.")

    def _operon_render_output(self, result: dict) -> None:
        try:
            out = self.query_one("#syn-operon-output", Static)
        except NoMatches:
            return
        seq = result["sequence"]
        lines = [f"[b]Assembled operon[/b] — {len(seq)} bp, "
                 f"{len(result['genes'])} genes"]
        for r in result["genes"]:
            ach = r["rel_strength"]
            ach_s = "—" if ach is None else f"{ach:.1f}"
            flag = ("[green]on target[/]" if r["on_target"]
                    else "[yellow]capped by context[/]")
            lines.append(f"  {r['name']}: target {r['target']} → "
                         f"achieved {ach_s}  {flag}")
            # Show the actual designed RBS/UTR — the real deliverable of an
            # RBS-tuning tool — so the user can read/copy it without exporting
            # to the DNA tab. (#syn-operon-output scrolls when many genes.)
            rbs = r.get("rbs")
            if rbs:
                spc = r.get("spacing")
                spc_s = f"  [dim](spacer {spc})[/]" if spc is not None else ""
                lines.append(f"      [dim]RBS[/] [cyan]{rbs}[/]{spc_s}")
        lines.append("[dim]→ DNA tab to add cut sites or clone as a fragment.[/]")
        out.update("\n".join(lines))

    def _operon_layout_feats(self, result: dict) -> "list[dict]":
        """Convert the operon element layout to SynthesisEditor features so
        the DNA tab shows the annotated promoter / RBS / CDS / terminator."""
        kind_to_type = {"promoter": "promoter", "rbs": "RBS",
                        "cds": "CDS", "terminator": "terminator"}
        colors = {"promoter": "#7ec97e", "RBS": "#f2c14e",
                  "CDS": "#5b9bd5", "terminator": "#d57e7e"}
        feats: list[dict] = []
        for el in result.get("layout", []):
            ftype = kind_to_type.get(el.get("kind"), "misc_feature")
            name = str(el.get("name") or ftype)
            feats.append({
                "start": int(el["start"]), "end": int(el["end"]),
                "label": name, "type": ftype,
                "color": colors.get(ftype, "white"), "strand": 1,
                "qualifiers": {"label": [name]},
            })
        return feats

    @on(Button.Pressed, "#btn-operon-to-dna")
    def _operon_to_dna(self, _) -> None:
        if not self._operon_result:
            self._operon_notify("Assemble the operon first.", error=True)
            return
        try:
            ed = self.query_one("#syn-editor", SynthesisEditor)
        except NoMatches:
            return
        ed.load(self._operon_result["sequence"],
                self._operon_layout_feats(self._operon_result))
        # Re-target the DNA tab as a fresh, unsaved document.
        self._loaded_id = None
        self._loaded_name = "operon"
        self._loaded_collection = None
        self._dirty = True
        try:
            self.query_one("#syn-tabs", TabbedContent).active = "syn-tab-dna"
        except NoMatches:
            pass
        self._refresh_status()
        self._operon_notify("Operon sent to the DNA tab — add cut sites or "
                            "use Clone Fragment.")

    def _operon_translate(self, dna: str) -> "str | None":
        """Translate a CDS DNA (5'→3') to its protein, stopping at the
        first stop. Returns None if not translatable."""
        from Bio.Seq import Seq
        dna = "".join(str(dna or "").split()).upper().replace("U", "T")
        if len(dna) < 3 or (set(dna) - set("ACGT")):
            return None
        dna = dna[:len(dna) - (len(dna) % 3)]
        try:
            prot = str(Seq(dna).translate(to_stop=True))
        except Exception:
            return None
        return prot or None

    @on(Button.Pressed, "#btn-operon-from-feature")
    def _operon_from_feature(self, _) -> None:
        coll = self._operon_coll_choice
        if not coll:
            self._operon_notify("Create or select a collection first.",
                                error=True)
            return

        def _on_plasmid(entry_id) -> None:
            if not entry_id:
                return
            match = _find_library_entry_by_id(entry_id)
            if not match:
                return
            gb_text = match.get("gb_text", "")
            if not gb_text:
                self._operon_notify("That entry has no sequence.", error=True)
                return
            try:
                rec = _gb_text_to_record(gb_text)
            except Exception:
                _log.exception("Operon: failed to parse library entry")
                self._operon_notify("Could not parse that entry.", error=True)
                return
            feats = [f for f in _extract_feature_entries_from_record(rec)
                     if str(f.get("feature_type", "")).upper() in ("CDS", "GENE")]
            if not feats:
                self._operon_notify("That plasmid has no CDS / gene features.",
                                    error=True)
                return

            def _on_feat(picked) -> None:
                if not isinstance(picked, dict):
                    return
                name = str(picked.get("name") or "CDS")
                prot = self._operon_translate(str(picked.get("sequence") or ""))
                if prot is None:
                    self._operon_notify("Could not translate that feature to "
                                        "a protein.", error=True)
                    return
                err = _protein_collection_add(
                    coll, name, prot,
                    source=f"{match.get('name', 'plasmid')}:{name}")
                if err:
                    self._operon_notify(err, error=True)
                    return
                self._operon_refresh_proteins()
                self._operon_notify(
                    f"Added {name!r} ({len(prot)} aa) to {coll!r}.")
            self.app.push_screen(
                PlasmidFeaturePickerModal(feats,
                                          plasmid_name=match.get("name", "")),
                callback=_on_feat)
        self.app.push_screen(PlasmidPickerModal(None), callback=_on_plasmid)

    @on(Button.Pressed, "#btn-operon-fetch")
    def _operon_fetch(self, _) -> None:
        coll = self._operon_coll_choice
        if not coll:
            self._operon_notify("Create or select a collection first.",
                                error=True)
            return

        def _done(result) -> None:
            acc = (result or {}).get("name", "") if isinstance(result, dict) else ""
            acc = str(acc).strip()
            if not acc:
                return
            self._operon_notify(f"Fetching {acc} from NCBI — please wait.")
            self._operon_fetch_worker(coll, acc)
        self.app.push_screen(GroupNamePromptModal(
            "", title=" Fetch protein from NCBI ",
            prompt="NCBI protein accession (e.g. AAK98552 — luxC):",
            placeholder="accession"), _done)

    @work(thread=True, exclusive=True, group="operon_fetch")
    def _operon_fetch_worker(self, coll: str, accession: str) -> None:
        try:
            desc, seq = fetch_protein(accession)
        except Exception as exc:           # network / parse / validation / NCBI
            _log.warning("Operon protein fetch failed for %r: %s",
                         accession, exc)
            self.app.call_from_thread(
                self._operon_notify, f"Fetch failed: {exc}", error=True)
            return
        err = _protein_collection_add(coll, accession, seq,
                                      description=desc,
                                      source=f"NCBI:{accession}")
        self.app.call_from_thread(self._operon_fetch_done, coll, accession, err)

    def _operon_fetch_done(self, coll: str, accession: str,
                           err: "str | None") -> None:
        if not self.is_mounted:        # screen closed mid-fetch — nothing to do
            return
        if err:
            self._operon_notify(err, error=True)
            return
        self._operon_refresh_proteins()
        self._operon_notify(f"Fetched {accession} → {coll!r}.")

    # ── Native Operon Domestication ────────────────────────────────────────

    def _native_notify(self, msg: str, *, error: bool = False) -> None:
        self.notify(msg, severity="error" if error else "information",
                    timeout=7)

    def _native_default_grammar(self) -> str:
        """The destination-grammar Select's default: the active grammar if it
        still resolves, else the first option (always ≥ gb_l0 + moclo_plant)."""
        gids = [gid for _lbl, gid in _grammar_dropdown_options()]
        active = _get_setting("active_grammar", "gb_l0")
        return active if active in gids else (gids[0] if gids else "gb_l0")

    def _native_record_feats(self, rec, total: int) -> "list[dict]":
        """Every non-source feature of ``rec`` as a simple dict (start / end /
        strand / type / label + frame qualifiers) in RECORD coords — the shape
        ``_gather_region_feats`` and the Scrub cure engine consume. Wrap-aware
        via ``_feat_bounds``; reverse-strand CDSes keep ``strand == -1`` so the
        cure engine translates them in the right frame."""
        out: list[dict] = []
        for f in getattr(rec, "features", []) or []:
            if getattr(f, "type", "") == "source":
                continue
            bounds = _feat_bounds(f, total)
            if bounds is None:
                continue
            s, e, strand = bounds
            label = (f.qualifiers.get("label") or [""])[0] or f.type
            g: dict = {"start": s, "end": e, "strand": strand,
                       "type": f.type, "label": str(label)}
            for k in ("codon_start", "transl_table"):
                v = (f.qualifiers.get(k) or [None])[0]
                if v not in (None, ""):
                    try:
                        g[k] = int(v)
                    except (TypeError, ValueError):
                        pass
            out.append(g)
        return out

    def _native_operon_span(self, feats: "list[dict]",
                            total: int) -> "tuple[int, int] | None":
        """Operon extent = the smallest forward span covering every CDS feature
        (``min(start)..max(end)``), in record coords. ``None`` when there are no
        CDS features. An origin-spanning operon is the rare case the user should
        lift via a canvas selection instead."""
        cds = [f for f in feats if str(f.get("type", "")).upper() == "CDS"]
        if not cds:
            return None
        try:
            s = min(int(f["start"]) for f in cds)
            e = max(int(f["end"]) for f in cds)
        except (TypeError, ValueError, KeyError):
            return None
        if not (0 <= s < e <= total):
            return None
        return s, e

    def _native_set_operon(self, seq: str, feats: "list[dict]",
                           source: str, name: str,
                           *, source_id: "str | None" = None) -> None:
        """Store a lifted operon (``feats`` already rebased to ``[0, len(seq))``)
        and refresh the summary. ``source_id`` is the LIBRARY id of the plasmid
        the operon was lifted from (when known); the save writes the SOE primers
        back onto that source entry so it shows what/why each cure changes."""
        seq = (seq or "").upper()
        if not seq:
            self._native_notify("Lifted operon is empty.", error=True)
            return
        self._native_operon = {
            "seq": seq, "feats": list(feats or []),
            "source": source, "name": (name or "operon")[:60],
            "source_id": (str(source_id).strip() or None) if source_id else None,
        }
        self._native_refresh_display()
        cds = sum(1 for f in self._native_operon["feats"]
                  if str(f.get("type", "")).upper() == "CDS")
        self._native_notify(
            f"Lifted {len(seq):,} bp operon ({cds} CDS) — pick a grammar, "
            f"then Cure & design primers.")

    def _native_refresh_display(self) -> None:
        try:
            out = self.query_one("#syn-native-output", Static)
        except NoMatches:
            return
        op = self._native_operon
        if not op:
            out.update("[dim]No operon lifted yet. Highlight an operon on the "
                       "canvas and press Lift selection, or pull one From "
                       "plasmid / From NCBI.[/]")
            return
        feats = op["feats"]
        cds = [f for f in feats if str(f.get("type", "")).upper() == "CDS"]
        rev = sum(1 for f in cds if int(f.get("strand", 1)) == -1)
        fwd = len(cds) - rev
        strand_note = (f"{fwd} →" + (f" / {rev} ←" if rev else "")) if cds else "—"
        out.update(
            f"[b]{op['name']}[/b]  [dim]({op['source']})[/dim]\n"
            f"Lifted: [bold]{len(op['seq']):,} bp[/bold]    "
            f"CDS: [bold]{len(cds)}[/bold] ({strand_note})    "
            f"annotations: {len(feats)}\n"
            f"[dim]Pick a destination grammar, then Cure & design primers.[/]")

    @on(Button.Pressed, "#btn-native-lift-sel")
    def _native_lift_selection(self, _) -> None:
        """Lift the operon highlighted on the main canvas (its selection
        persists under the pushed Synthesis screen)."""
        rec = getattr(self.app, "_current_record", None)
        if rec is None:
            self._native_notify("Load a plasmid on the main canvas first.",
                                error=True)
            return
        try:
            sp = self.app.query_one("#seq-panel", SequencePanel)
            pm = self.app.query_one("#plasmid-map", PlasmidMap)
        except NoMatches:
            self._native_notify("Main canvas not available.", error=True)
            return
        sel = sp._user_sel or sp._sel_range
        if not sel:
            self._native_notify(
                "Highlight the operon on the canvas first — close Synthesis, "
                "drag across the bases, reopen, then Lift selection.",
                error=True)
            return
        start, end = int(sel[0]), int(sel[1])
        total = len(str(rec.seq))
        rlen = _feat_len(start, end, total) if total else 0
        if rlen < 18:
            self._native_notify(
                f"Selection too short ({rlen} bp; need ≥ 18).", error=True)
            return
        seq = _slice_circular(str(rec.seq).upper(), start, end)
        feats = self.app._gather_region_feats(  # type: ignore[attr-defined]
            pm._feats, start, end, total)
        disp = self.app._record_display_name(rec)  # type: ignore[attr-defined]
        # The canvas record is the active library plasmid — capture its id so
        # the save can write the SOE primers back onto that source entry.
        try:
            src_id = self.app.query_one("#library", LibraryPanel)._active_id
        except Exception:
            src_id = None
        self._native_set_operon(seq, feats, source=f"canvas:{disp}",
                                name=f"{disp} {start + 1}-{end}",
                                source_id=src_id)

    @on(Button.Pressed, "#btn-native-from-plasmid")
    def _native_from_plasmid(self, _) -> None:
        def _on_plasmid(entry_id) -> None:
            if not entry_id:
                return
            ent = _find_library_entry_by_id(entry_id)
            if not ent:
                return
            gb = ent.get("gb_text") or ""
            if not gb:
                self._native_notify("That entry has no sequence.", error=True)
                return
            try:
                rec = _gb_text_to_record(gb)
            except Exception:
                _log.exception("native operon: library parse failed")
                self._native_notify("Could not parse that entry.", error=True)
                return
            self._native_lift_from_record(
                rec, source=f"plasmid:{ent.get('name') or entry_id}",
                source_id=entry_id)
        self.app.push_screen(PlasmidPickerModal(None), _on_plasmid)

    @on(Button.Pressed, "#btn-native-from-ncbi")
    def _native_from_ncbi(self, _) -> None:
        def _done(result) -> None:
            acc = ((result or {}).get("name", "")
                   if isinstance(result, dict) else "")
            acc = str(acc).strip()
            if not acc:
                return
            self._native_notify(f"Fetching {acc} from NCBI — please wait.")
            self._native_fetch_worker(acc)
        self.app.push_screen(GroupNamePromptModal(
            "", title=" Fetch operon from NCBI ",
            prompt="NCBI nucleotide accession (e.g. M19536 — lux operon):",
            placeholder="accession"), _done)

    @work(thread=True, exclusive=True, group="native_fetch")
    def _native_fetch_worker(self, accession: str) -> None:
        try:
            rec = fetch_genbank(accession)
        except Exception as exc:
            _log.warning("native operon fetch failed for %r: %s",
                         accession, exc)
            self.app.call_from_thread(
                self._native_notify, f"Fetch failed: {exc}", error=True)
            return
        self.app.call_from_thread(
            self._native_lift_from_record, rec, f"ncbi:{accession}")

    def _native_lift_from_record(self, rec, source: str,
                                 *, source_id: "str | None" = None) -> None:
        """Auto-detect + lift the operon (first CDS → last CDS span) from a
        parsed / fetched record, rebasing its features to ``[0, span)``. Called
        on the main thread (plasmid path direct, NCBI path via
        ``call_from_thread``). ``source_id`` is the lifted-from library entry id
        (plasmid path); None for an NCBI fetch (no library entry to annotate)."""
        if not getattr(self, "is_mounted", True):
            return
        seq_full = str(getattr(rec, "seq", "") or "").upper()
        total = len(seq_full)
        if total < 18:
            self._native_notify("That record is too short.", error=True)
            return
        rec_feats = self._native_record_feats(rec, total)
        span = self._native_operon_span(rec_feats, total)
        if span is None:
            self._native_notify(
                "No CDS features found — can't auto-detect the operon. Load it "
                "on the canvas and use Lift selection instead.", error=True)
            return
        s, e = span
        seq = _slice_circular(seq_full, s, e)
        feats = self.app._gather_region_feats(  # type: ignore[attr-defined]
            rec_feats, s, e, total)
        disp = str(getattr(rec, "name", "") or getattr(rec, "id", "")
                   or "operon")
        self._native_set_operon(seq, feats, source=source,
                                name=f"{disp} operon", source_id=source_id)

    def _native_grammar_dict(self) -> dict:
        """The destination grammar dict the user picked in the Select."""
        try:
            gid = str(self.query_one("#syn-native-grammar", Select).value)
        except NoMatches:
            gid = _get_setting("active_grammar", "gb_l0")
        grammars = _all_grammars()
        return grammars.get(gid) or grammars.get("gb_l0") or _get_active_grammar()

    def _native_extra_enzymes(self) -> "list[str]":
        """Parse the 'Also cure' input → enzyme names (comma / space separated),
        e.g. 'EcoRI, KpnI' → ['EcoRI', 'KpnI']. Cured alongside the grammar's
        Type IIS sites."""
        try:
            raw = self.query_one("#syn-native-extra-enz", Input).value
        except NoMatches:
            return []
        return [t for t in re.split(r"[,\s]+", raw or "") if t]

    @on(Button.Pressed, "#btn-native-cure")
    def _native_cure(self, _) -> None:
        """Cure the lifted operon's Type IIS sites + design the SOE primer set,
        off-thread (a multi-kb operon scrub can take a moment — heavy compute in
        the trigger, not a modal)."""
        if not self._native_operon:
            self._native_notify("Lift an operon first.", error=True)
            return
        self._native_manual_edits = []          # a fresh run drops prior fixes
        self._native_notify("Curing + designing SOE primers…")
        self._native_cure_worker()

    @work(thread=True, exclusive=True, group="native_cure")
    def _native_cure_worker(self) -> None:
        op = self._native_operon
        if not op:
            return
        grammar = self._native_grammar_dict()
        extra = self._native_extra_enzymes()
        try:
            res = _design_operon_soe_primers(
                op["seq"], op["feats"], grammar,
                manual_edits=list(self._native_manual_edits),
                extra_enzymes=extra)
        except Exception as exc:
            _log.exception("native operon SOE design failed")
            self.app.call_from_thread(
                self._native_notify, f"Design failed: {exc}", error=True)
            return
        self.app.call_from_thread(self._native_cure_done, res)

    def _native_cure_done(self, res: dict) -> None:
        if not self.is_mounted:
            return
        if res.get("error"):
            self._native_notify(res["error"], error=True)
            return
        if res.get("needs_manual"):
            self._native_open_cure_modal(res.get("sites_skipped", []))
            return
        self._native_result = res
        self._native_show_result()

    def _native_open_cure_modal(self, flagged: "list[dict]") -> None:
        """Non-coding sites the auto-cure won't touch → let the user mark a valid
        single-base fix for each. On commit, accumulate the edits + re-design.
        CDS-locked sites (no synonymous cure) can't be fixed here."""
        op = self._native_operon
        if not op:
            return
        locked = [f for f in flagged if f.get("in_cds")]
        fixable = [f for f in flagged if not f.get("in_cds")]
        if not fixable:
            self._native_notify(
                f"{len(locked)} forbidden site(s) sit inside a CDS with no "
                "synonymous cure — pick a different operon region.", error=True)
            return

        def _on_fixes(edits) -> None:
            if not edits:
                return
            self._native_manual_edits.extend(edits)
            self._native_notify("Applying manual fixes + re-designing…")
            self._native_cure_worker()

        self.app.push_screen(
            OperonCureModal(op["seq"], fixable, self._native_grammar_dict(),
                            locked=locked),
            _on_fixes)

    def _native_show_result(self) -> None:
        res = self._native_result
        if not res:
            return
        try:
            out = self.query_one("#syn-native-output", Static)
        except NoMatches:
            return
        prims = res.get("primers", [])
        lines = "\n".join(
            f"  [cyan]{p['name']}[/cyan]  {len(p['seq'])} nt  "
            f"Tm {p['tm']}°C  [dim]{p['kind']}[/dim]"
            for p in prims)
        out.update(
            f"[b][green]Cured[/green][/b] — {len(res['cured_seq']):,} bp, "
            f"{len(res.get('edits', []))} cure(s), "
            f"{res.get('n_clusters', 0)} SOE junction(s).\n"
            f"[b]{len(prims)} primers[/b] (every cure primer-encoded):\n"
            f"{lines}\n"
            f"[dim]Clone into grammar to save the operon + primers.[/]")
        try:
            self.query_one("#btn-native-clone", Button).disabled = False
        except NoMatches:
            pass

    @on(Button.Pressed, "#btn-native-clone")
    def _native_clone(self, _) -> None:
        """Save the domesticated operon — prompting for two names + collections.

        One press persists FOUR artifacts (all via the sanctioned atomic,
        collision-safe helpers): the cured PCR amplicon (SOE primers bound + an
        amplify history) to the plasmid library, the grammar-tagged OPERON L0
        part to the parts bin, the part CLONED into its entry vector (insert +
        backbone history, individual genes — no whole-operon wrapper) to a
        plasmid collection, and every SOE primer to the primer library.

        The user names BOTH the cloned plasmid and the PCR fragment (prefilled
        ``PCR-…``) and picks a collection for each, via two chained
        `NamePlasmidModal`s. Cancelling EITHER prompt aborts the whole save —
        nothing is written — so there's never a half-saved operon."""
        op, res = self._native_operon, self._native_result
        if not op or not res:
            self._native_notify("Cure & design primers first.", error=True)
            return
        active = _get_active_collection_name() or "Default"
        base = str(op.get("name") or "operon").strip() or "operon"
        plasmid_default = (base[:46] + " (domesticated)")[:60]
        pcr_default = ("PCR-" + base)[:60]
        pending: dict = {}

        def _commit(pcr_name: str, pcr_coll: str) -> None:
            try:
                summary = self._native_save_outputs(
                    op, res,
                    plasmid_name=pending["name"], plasmid_coll=pending["coll"],
                    pcr_name=pcr_name, pcr_coll=pcr_coll,
                    primer_family=pending.get("family", ""),
                )
            except Exception as exc:
                _log.exception("native operon clone/save failed")
                self._native_notify(f"Save failed: {exc}", error=True)
                return
            clone_bit = (f"clone “{summary['plasmid_name']}” → "
                         f"{summary['plasmid_coll']}" if summary.get("cloned")
                         else "the OPERON part (clone skipped — no entry vector)")
            self._native_notify(
                f"Saved {clone_bit}, PCR fragment “{summary['pcr_name']}” → "
                f"{summary['pcr_coll']}, and {summary['n_primers']} SOE primers.")
            # Close the workbench, load the saved cloned plasmid onto the
            # canvas, and refresh + scroll the library to highlight it.
            if summary.get("clone_rec") is not None:
                self._native_focus_saved_clone(
                    summary["clone_rec"], str(summary.get("plasmid_name") or ""))

        def _on_pcr_named(result: "object") -> None:
            parsed = _name_modal_result(result, active)
            if parsed is None:
                return  # cancelled → abort, nothing written
            _commit(parsed[0], parsed[1])

        def _on_plasmid_named(result: "object") -> None:
            parsed = _name_modal_result(result, active)
            if parsed is None:
                return  # cancelled → abort
            pending["name"], pending["coll"] = parsed
            pending["family"] = (
                (result.get("primer_family") or "")
                if isinstance(result, dict) else ""
            ) or _sanitize_plasmid_name(base, fallback="operon")
            self.app.push_screen(
                NamePlasmidModal(pcr_default, target_label="PCR fragment",
                                 default_collection=active),
                callback=_on_pcr_named,
            )

        # The plasmid prompt also names the SOE primer family (one textbox →
        # every primer becomes `{family}-DOM-{#}-{F|R}`); the default is the
        # operon's name so the primers, clone, and fragment all read together.
        self.app.push_screen(
            NamePlasmidModal(plasmid_default, target_label="plasmid",
                             default_collection=active,
                             primer_family=_sanitize_plasmid_name(
                                 base, fallback="operon")),
            callback=_on_plasmid_named,
        )

    def _native_save_outputs(self, op: dict, res: dict, *,
                             plasmid_name: str, plasmid_coll: str,
                             pcr_name: str, pcr_coll: str,
                             primer_family: str = "") -> dict:
        """Persist the domesticated operon's four artifacts to the user-chosen
        names + collections (all via the sanctioned atomic, collision-safe
        helpers). Split from the modal flow (`_native_clone`) so the save is
        unit-testable without driving the two dialogs. Returns a summary dict
        (`plasmid_name`/`plasmid_coll`/`pcr_name`/`pcr_coll`/`n_primers`/
        `cloned`) for the toast."""
        from Bio.Seq import Seq
        from Bio.SeqRecord import SeqRecord
        from Bio.SeqFeature import SeqFeature, FeatureLocation
        grammar = self._native_grammar_dict()
        grammar_id = str(grammar.get("id") or "gb_l0")
        # Rebase the auto "operon-DOM-#-F/R" SOE primer names onto the user's
        # family → "{family}-DOM-#-F/R": the -DOM- domesticator suffix, the
        # positional pair number (#), and the F/R strand are all preserved.
        # One family name from the save modal renames the whole set the same
        # way on the PCR fragment, the clone, and the primer library.
        family = _sanitize_plasmid_name(primer_family or "operon",
                                        fallback="operon")

        def _fam(nm: "str | None") -> str:
            nm = str(nm or "")
            return (nm.replace("operon-DOM-", f"{family}-DOM-", 1)
                    if nm.startswith("operon-DOM-") else nm)
        cured = res["cured_seq"]
        pad = grammar.get("pad", _GB_PAD)
        site = grammar.get("site", _GB_L0_ENZYME_SITE)
        spacer = grammar.get("spacer", _GB_SPACER)
        op_oh5, op_oh3 = res.get("overhangs", ["AATG", "GCTT"])
        fwd_skip = int(res.get("fwd_skip", 0))
        fwd_tail = pad + site + spacer + op_oh5
        rev_tail = pad + site + spacer + _rc(op_oh3)
        # ATG-fusion: the leading start codon rides in the AATG overhang, so the
        # amplicon body is cured[fwd_skip:]; a cured position p lands at p+off.
        # The reverse primer's 5' tail is on the BOTTOM strand, so it lands on
        # the top-strand 3' end as its REVERSE COMPLEMENT — `_rc(rev_tail)`, NOT
        # the tail verbatim. The forward-tail bug made the amplicon 3' end carry
        # the reverse primer's 5' tail unreversed (its Esp3I site pointing the
        # wrong way), so the saved PCR fragment didn't end in `_rc(rev_primer)`
        # and the reverse primer's tail half rendered as bottom-strand DNA on
        # the fragment (user-reported: "the 3' end shows a reversal of the 5'
        # end of the reverse primer"). The amplicon is `fwd_primer + body +
        # _rc(rev_primer_tail)` — exactly what a tailed-primer PCR yields.
        amplicon = fwd_tail + cured[fwd_skip:] + _rc(rev_tail)
        off = len(fwd_tail) - fwd_skip
        # The FULL SOE primer set (flank pair PLUS every internal cure primer),
        # in the {name, seq, strand, tm} shape `_attach_named_primers_to_record`
        # wants — bound to BOTH the PCR fragment and the cloned plasmid so each
        # shows how it was built (strand from the primer's kind, "…-rev" → -1).
        run_primers = [
            {"name": _fam(p.get("name", "")), "seq": p.get("seq", ""),
             "strand": -1 if str(p.get("kind", "")).endswith("rev") else 1,
             "tm": p.get("tm")}
            for p in res.get("primers", []) if p.get("seq")
        ]
        flank = [p for p in res.get("primers", [])
                 if str(p.get("kind", "")).startswith("flank")]

        # ── 1. Cured PCR amplicon → plasmid library (primers bound + history) ──
        pcr_locus = (re.sub(r"[^A-Za-z0-9_-]+", "_", pcr_name).strip("_")
                     or "amplicon")[:16]
        rec = SeqRecord(Seq(amplicon), id=pcr_locus, name=pcr_locus,
                        description=("Native operon domesticated for "
                                     f"{grammar.get('name', 'grammar')}"),
                        annotations={"molecule_type": "DNA",
                                     "topology": "linear"})
        # Stamp the human (spaced) name so the fragment shows "PCR-VhLux", not
        # the sanitised underscore LOCUS, anywhere it's loaded ([INV-98]).
        rec._tui_display_name = pcr_name  # type: ignore[attr-defined]
        for f in op.get("feats", []):
            try:
                s = int(f["start"]) + off
                e = int(f["end"]) + off
            except (KeyError, TypeError, ValueError):
                continue
            if not (0 <= s < e <= len(amplicon)):
                continue
            rec.features.append(SeqFeature(
                FeatureLocation(s, e, strand=int(f.get("strand", 1) or 1)),
                type=str(f.get("type") or "misc_feature"),
                qualifiers={"label": [str(f.get("label")
                                          or f.get("type") or "feat")]}))
        # Bind the SOE primers to the PCR fragment, re-derived against the
        # amplicon — the SAME helper + binding the clone uses, so the fragment
        # and the clone show the same primers at the bases they anneal to.
        try:
            _attach_named_primers_to_record(rec, run_primers)
        except Exception:
            _log.exception("native operon: amplicon primer attach failed")
        gb_text = _record_to_gb_text(rec)
        # amplify-history (operation=amplifyFragment + the flank oligos) so the
        # PCR fragment's History tab records how it was made.
        amp_hx = _build_amplicon_history_xml(
            name=pcr_name, seq_len=len(amplicon),
            fwd_seq=flank[0]["seq"] if flank else "",
            rev_seq=flank[1]["seq"] if len(flank) > 1 else "",
            start_1based=1, end_1based=len(amplicon),
            fwd_name=_fam(flank[0].get("name") or "forward primer")
                     if flank else "forward primer",
            rev_name=_fam(flank[1].get("name") or "reverse primer")
                     if len(flank) > 1 else "reverse primer",
        )
        amp_entry = {"id": pcr_locus, "name": pcr_name, "size": len(amplicon),
                     "n_feats": len(rec.features), "source": "native_operon",
                     "added": _date.today().isoformat(), "gb_text": gb_text,
                     "kind": "amplicon"}
        if amp_hx:
            amp_entry["history_xml"] = amp_hx
        final_pcr_name = _commit_library_entry_to_collection(amp_entry, pcr_coll)

        # ── 2. Grammar-tagged OPERON L0 part → parts bin ──
        # CDS-equivalent: stored body is the FULL cured operon; the AATG
        # overhang carries the first gene's ATG and `_fuse_overhang_body` drops
        # the redundant ATG at assembly. Best-effort.
        part = {
            "name": plasmid_name, "type": "OPERON", "position": "Pos 3-4",
            "oh5": op_oh5, "oh3": op_oh3, "sequence": cured,
            "grammar": grammar_id, "level": 0,
            "insert_feats": list(op.get("feats", [])),
            "run_primers": run_primers,
        }
        if len(flank) == 2:
            part["fwd_primer"], part["rev_primer"] = (flank[0]["seq"],
                                                      flank[1]["seq"])
        try:
            bin_entries = _load_parts_bin()
            bin_entries.append(part)
            _save_parts_bin(bin_entries)
        except Exception:
            _log.exception("native operon: OPERON parts-bin save failed")

        # ── 3. Clone the part into its entry vector → plasmid collection ──
        # `_part_to_cloned_seqrecord` ligates the primed amplicon into the
        # grammar's entry vector (stub backbone when none is configured); the
        # individual genes carry through and the redundant whole-operon wrapper
        # is dropped (see `_with_run_primers`). Records an insert + backbone
        # (insertFragment) lineage. Best-effort — a clone hiccup must not sink
        # the already-saved amplicon / part / primers.
        cloned = False
        clone_rec_out = None
        final_clone_name = plasmid_name
        try:
            cloned_rec = _part_to_cloned_seqrecord(part)
            if cloned_rec is None:                       # defensive (type-narrows)
                raise ValueError("clone produced no record")
            clone_id = (re.sub(r"[^A-Za-z0-9_]+", "_", plasmid_name).strip("_")
                        or "operon")[:16]
            clone_entry = {
                "id": clone_id, "name": plasmid_name,
                "size": _seq_len(cloned_rec),
                "n_feats": len(cloned_rec.features or []),
                "source": "native_operon:l0",
                "added": _date.today().isoformat(),
                "gb_text": _record_to_gb_text(cloned_rec), "kind": "plasmid",
            }
            try:
                entry_vec = _get_entry_vector(grammar_id)
                if isinstance(entry_vec, dict) and entry_vec.get("gb_text"):
                    hist = _build_history_for_l0_clone(
                        name=plasmid_name, seq_len=_seq_len(cloned_rec),
                        grammar_id=grammar_id, grammar=grammar,
                        entry_vector=entry_vec, part=part)
                    if hist:
                        clone_entry["history_xml"] = hist
            except Exception:
                _log.debug("native operon: clone history build failed",
                           exc_info=True)
            final_clone_name = _commit_library_entry_to_collection(
                clone_entry, plasmid_coll)
            cloned = True
            clone_rec_out = cloned_rec
        except Exception:
            _log.exception("native operon: clone-into-vector save failed")

        # ── 4. SOE primers → primer library (family-rebased names) ──
        prims = _load_primers()
        for p in res.get("primers", []):
            prims.append({"name": _fam(p["name"]), "sequence": p["seq"],
                          "tm": p.get("tm"),
                          "source": f"native_operon:{final_clone_name}"})
        _save_primers(prims)

        # ── 5. Annotate the ORIGINAL source plasmid with the SOE primers ──
        # so the source shows WHERE + WHY each cure changes a base. Re-derived
        # against the source BY SEQUENCE (the flank pair binds the operon ends;
        # each cure primer binds its junction with the synonymous edit as a
        # mismatch), deduped by primer_seq, and persisted in place via
        # `_save_library` (reseats the cache + mirrors the active collection).
        # Library-sourced lifts only — an NCBI fetch has no entry to write to.
        # Best-effort: a write-back hiccup must not sink the saved artifacts.
        src_annotated = False
        source_id = str(op.get("source_id") or "")
        if source_id:
            try:
                lib_entries = _load_library()
                for e in lib_entries:
                    if not (isinstance(e, dict)
                            and (e.get("id") or "") == source_id):
                        continue
                    src_rec = _gb_text_to_record(e.get("gb_text", ""))
                    if _attach_named_primers_to_record(src_rec, run_primers):
                        e["gb_text"] = _record_to_gb_text(src_rec)
                        e["n_feats"] = sum(1 for f in src_rec.features
                                           if f.type != "source")
                        _save_library(lib_entries, async_sync=True)
                        src_annotated = True
                    break
            except Exception:
                _log.exception(
                    "native operon: source-plasmid primer annotate failed")

        return {"plasmid_name": final_clone_name, "plasmid_coll": plasmid_coll,
                "pcr_name": final_pcr_name, "pcr_coll": pcr_coll,
                "n_primers": len(res.get("primers", [])), "cloned": cloned,
                "clone_rec": clone_rec_out, "source_annotated": src_annotated}

    def _native_focus_saved_clone(self, clone_rec, clone_name: str) -> None:
        """Post-save UI focus (best-effort — never raises into the save flow):
        close the Synthesis workbench, load the cloned plasmid onto the canvas,
        repopulate the library to its latest state, and move the cursor to the
        saved entry so it's scrolled into view + highlighted."""
        app = self.app

        def _focus() -> None:
            try:
                app._apply_record(clone_rec)  # type: ignore[attr-defined]
            except Exception:
                _log.exception("native operon: load saved clone onto canvas failed")
            try:
                lib = app.query_one("#library", LibraryPanel)
                lib._repopulate()
                # Row keys are entry ids; the post-collision display name is what
                # we have, so map name → id, then move the cursor to that row.
                target_id = next(
                    (eid for eid, nm in getattr(lib, "_lib_full_names", {}).items()
                     if nm == clone_name), None)
                if target_id is not None:
                    tbl = lib.query_one("#lib-table", DataTable)
                    for i, rk in enumerate(tbl.rows.keys()):
                        if getattr(rk, "value", None) == target_id:
                            tbl.move_cursor(row=i)
                            break
            except Exception:
                _log.exception("native operon: library focus failed")

        # Close the workbench first, then defer the load + focus until after
        # the pop settles so the main screen's library panel is the query target.
        try:
            if app.screen is self:
                app.pop_screen()
        except Exception:
            _log.exception("native operon: close workbench failed")
        try:
            app.call_after_refresh(_focus)
        except Exception:
            _log.exception("native operon: schedule post-save focus failed")

    # ── Feature library side panel ─────────────────────────────────────────

    def _refresh_featlib_table(self, *, filter_str: str = "") -> None:
        """Repopulate the feature-library DataTable. Filters case-
        insensitively against the entry's `name`, `feature_type`, and
        `description`. Sorted natural by name so `mCherry` lands near
        `mCherry-2`."""
        try:
            t = self.query_one("#syn-featlib-table", DataTable)
        except NoMatches:
            return
        # Re-read on every refresh: a save in a sibling FeatureLibrary
        # screen could've landed new entries since we last looked. The
        # cost is one O(N) read; the user hits Refresh manually if they
        # need fresher state mid-edit.
        entries = [e for e in _load_features() if isinstance(e, dict)]
        entries.sort(key=lambda e: _natural_sort_key(
            (e.get("name") or "").lower()
        ))
        rows: list[tuple[str, dict]] = []
        needle = filter_str.strip().lower()
        for e in entries:
            name = str(e.get("name", "") or "")
            ftype = str(e.get("feature_type", "") or "")
            desc = str(e.get("description", "") or "")
            seq = str(e.get("sequence", "") or "")
            if needle:
                if (needle not in name.lower()
                        and needle not in ftype.lower()
                        and needle not in desc.lower()):
                    continue
            # Synthesise a row key — name + type + seq-hash so dup
            # names with different sequences still resolve uniquely.
            key = f"{name}|{ftype}|{hash(seq) & 0xFFFFFF:06x}"
            rows.append((key, e))
        self._featlib_rows = rows
        t.clear()
        for key, e in rows:
            name = e.get("name", "") or ""
            ftype = e.get("feature_type", "") or ""
            bp = len((e.get("sequence", "") or "").replace(" ", ""))
            t.add_row(name or "(unnamed)", ftype or "?", str(bp), key=key)

    @on(Input.Changed, "#syn-featlib-search")
    def _on_featlib_search(self, event: Input.Changed) -> None:
        self._refresh_featlib_table(filter_str=event.value)

    @on(Button.Pressed, "#btn-syn-featlib-refresh")
    def _on_featlib_refresh(self, _) -> None:
        try:
            needle = self.query_one("#syn-featlib-search", Input).value
        except NoMatches:
            needle = ""
        self._refresh_featlib_table(filter_str=needle)
        self.app.notify("Feature library reloaded.",
                         severity="information")

    @on(Button.Pressed, "#btn-syn-featlib-insert")
    def _on_featlib_insert(self, _) -> None:
        self._featlib_insert_selected(mode="insert")

    @on(Button.Pressed, "#btn-syn-featlib-annotate")
    def _on_featlib_annotate(self, _) -> None:
        self._featlib_insert_selected(mode="annotate")

    @on(Button.Pressed, "#btn-syn-featlib-edit")
    def _on_featlib_edit(self, _) -> None:
        """Open AddFeatureModal pre-filled with the selected library
        entry; on save, update features.json. Mirrors
        FeatureLibraryScreen.action_edit so the two screens stay
        coherent — edits made here surface there immediately."""
        entry = self._featlib_selected_entry()
        if entry is None:
            self.app.notify(
                "Pick an entry in the feature library first.",
                severity="information",
            )
            return
        # Find the entry's index in the persistent library by
        # (name, feature_type) — same key FeatureLibraryScreen uses.
        all_entries = _load_features()
        target_key = (
            entry.get("name"), entry.get("feature_type"),
        )
        target_idx = next(
            (i for i, e in enumerate(all_entries)
             if (e.get("name"), e.get("feature_type")) == target_key),
            -1,
        )
        if target_idx < 0:
            self.app.notify(
                "Entry no longer in the feature library.",
                severity="warning",
            )
            return
        def _cb(result):
            if not result:
                return
            new_entry = (
                result.get("entry")
                if isinstance(result, dict) else None
            )
            if not new_entry:
                return
            # Replace at target_idx and dedup if rename collides.
            current = _load_features()
            if target_idx >= len(current):
                return
            new_key = (
                new_entry.get("name"),
                new_entry.get("feature_type"),
            )
            for i in range(len(current) - 1, -1, -1):
                if i == target_idx:
                    continue
                e = current[i]
                if (e.get("name"), e.get("feature_type")) == new_key:
                    del current[i]
            current[target_idx if target_idx < len(current)
                    else len(current) - 1] = new_entry
            _save_features(current)
            self._refresh_featlib_table()
            _log_event(
                "synthesis.featlib.edit",
                name=new_entry.get("name"),
                type=new_entry.get("feature_type"),
            )
            self.app.notify(
                f"Updated '{new_entry.get('name')}' in the "
                "feature library.",
                severity="information",
            )
        self.app.push_screen(
            AddFeatureModal(prefill=entry),
            callback=_cb,
        )

    def _featlib_selected_entry(self) -> "dict | None":
        """Resolve the highlighted feature-library row → entry dict."""
        try:
            t = self.query_one("#syn-featlib-table", DataTable)
        except NoMatches:
            return None
        if t.cursor_row < 0 or t.row_count == 0:
            return None
        try:
            row_key = t.coordinate_to_cell_key(
                _Coordinate(t.cursor_row, 0)
            ).row_key
        except (LookupError, AttributeError):
            return None
        key_val = row_key.value if hasattr(row_key, "value") else str(row_key)
        for key, entry in self._featlib_rows:
            if key == key_val:
                return entry
        return None

    def _featlib_insert_selected(self, *, mode: str) -> None:
        """Apply the highlighted feature-library entry to the editor.

        ``mode == "insert"`` — insert the entry's sequence at the cursor
        and annotate the inserted bases with the entry's type / colour
        / qualifiers.

        ``mode == "annotate"`` — overlay the entry's annotation onto
        the editor's current selection (no DNA change). Requires a
        selection; notifies otherwise.
        """
        entry = self._featlib_selected_entry()
        if entry is None:
            self.app.notify(
                "Pick a feature in the library list first.",
                severity="information",
            )
            return
        try:
            ed = self.query_one("#syn-editor", SynthesisEditor)
        except NoMatches:
            return
        name = str(entry.get("name", "") or "feature")
        ftype = str(entry.get("feature_type", "") or "misc_feature")
        color = entry.get("color")
        if not color:
            color = _GB_TYPE_COLORS.get(ftype, "white")
        strand = int(entry.get("strand", 1) or 0)
        quals = dict(entry.get("qualifiers") or {})
        if "label" not in quals:
            quals["label"] = [name]
        if mode == "annotate":
            sel = ed.current_selection()
            if sel is None:
                self.app.notify(
                    "Highlight a region in the editor first to "
                    "annotate it.",
                    severity="information",
                )
                return
            s, e = sel
            if s >= e:
                return
            ed.add_feature({
                "start": s, "end": e,
                "label": name, "type": ftype,
                "color": str(color),
                "strand": strand,
                "qualifiers": quals,
            })
            _log_event("synthesis.featlib.annotate",
                       name=name, ftype=ftype, start=s, end=e)
            self.app.notify(
                f"Annotated bp {s}-{e} as '{name}' ({ftype}).",
                severity="information",
            )
            # Restore focus to the editor so the user can keep
            # typing immediately after the library Annotate.
            self._focus_dna_editor()
            return
        # mode == "insert"
        seq = "".join(
            c for c in str(entry.get("sequence", "") or "").upper()
            if c in _SYNTHESIS_TYPEABLE_BASES
        )
        if not seq:
            self.app.notify(
                f"Feature '{name}' has no usable sequence "
                "(ACGT/IUPAC only).",
                severity="warning",
            )
            return
        start = ed._cursor_pos
        # Strand orientation: if the library entry is reverse-strand,
        # insert the reverse complement so the annotation matches the
        # template strand the user sees in the editor.
        insert_seq = _rc(seq) if strand == -1 else seq
        # Sweep #17 (2026-05-21): `extend_adjacent_feats=False` so a
        # library entry inserted at the 3' boundary of an upstream
        # feature lands as a SEPARATE downstream feature (the new
        # annotation we add below) instead of stacking on top of an
        # upstream feature that grew to cover the insert. Typing-
        # inside-a-feature still extends because the boundary-only
        # rule lets `fs < cur < fe` paths through unchanged.
        ok = ed.insert_at_cursor(insert_seq, extend_adjacent_feats=False)
        if not ok:
            return
        end = start + len(insert_seq)
        ed.add_feature({
            "start": start, "end": end,
            "label": name, "type": ftype,
            "color": str(color),
            "strand": strand,
            "qualifiers": quals,
        })
        _log_event("synthesis.featlib.insert",
                   name=name, ftype=ftype,
                   start=start, end=end, bp=len(insert_seq))
        self.app.notify(
            f"Inserted '{name}' ({len(insert_seq)} bp) at bp {start}.",
            severity="information",
        )
        # Restore focus to the editor so the user can keep typing
        # immediately after the library Insert.
        self._focus_dna_editor()

    # ── Status line ───────────────────────────────────────────────────────

    def _active_tab_id(self) -> str:
        """Returns 'dna' or 'protein' depending on which tab is
        currently visible. Cached in `_active_tab_cache` so the
        accessor is cheap. Falls back to the cache on query failure."""
        try:
            tabs = self.query_one("#syn-tabs", TabbedContent)
            active = str(tabs.active or "")
        except (NoMatches, AttributeError):
            return self._active_tab_cache
        if active == "syn-tab-protein":
            self._active_tab_cache = "protein"
            return "protein"
        self._active_tab_cache = "dna"
        return "dna"

    def _refresh_status(self) -> None:
        """Dispatch status refresh to the active tab's renderer.
        Each tab carries its own dirty / loaded-name / cursor info
        so the status line reflects the surface the user is
        composing on."""
        is_protein = self._active_tab_id() == "protein"
        if is_protein:
            self._refresh_status_protein()
        else:
            self._refresh_status_dna()
        self._refresh_saveas_enabled(is_protein)

    def _refresh_saveas_enabled(self, is_protein: bool) -> None:
        """Enable **Save As** only once the active tab's fragment has
        been saved at least once. Save As forks a NEW copy of an
        existing entry; for a never-saved fragment it does exactly what
        Save does (prompt for a name), so leaving it live there is just
        a confusing duplicate. Disabled until there's an original to
        fork. Called from `_refresh_status`, which fires on load / save
        / rename / tab-switch / focus, so the state stays current."""
        loaded = self._protein_loaded_id if is_protein else self._loaded_id
        try:
            self.query_one("#btn-syn-saveas", Button).disabled = (loaded is None)
        except NoMatches:
            pass

    def _refresh_status_dna(self) -> None:
        try:
            status = self.query_one("#syn-status", Static)
            ed = self.query_one("#syn-editor", SynthesisEditor)
        except NoMatches:
            return
        seq, feats = ed.get_state()
        name = self._loaded_name or "(unsaved)"
        sel = ed.current_selection()
        # Build via Text.append so a user-typed name containing `[`
        # or other markup-significant chars can't accidentally break
        # the status render. Same defensive pattern as the addfeat
        # colour swatch (see `_refresh_color_swatch`).
        txt = Text()
        txt.append("[DNA] ", style="dim")
        txt.append(name, style="bold")
        if self._dirty:
            txt.append(" ●", style="yellow")
        txt.append(f"  ·  {len(seq):,} bp  ·  ")
        n_feats = len(feats)
        txt.append(f"{n_feats} feature{'s' if n_feats != 1 else ''}")
        # GC% of the current DNA — the key at-a-glance codon-optimize /
        # synthesis metric, recomputed live so it stays honest as the user
        # edits (an optimize's CAI is a point-in-time value in the toast; GC
        # is meaningful for any DNA and no longer vanishes with the toast).
        if seq:
            try:
                txt.append(f"  ·  GC {_codon_gc(seq):.1f}%")
            except Exception:
                pass
        txt.append(f"  ·  cursor {ed._cursor_pos}")
        if sel is not None:
            s, e = sel
            txt.append(f"  ·  sel {s}-{e} ({e - s} bp)")
        # Zoom state / hint (mirrors the main app's linear −/+/0 view).
        if ed._zoom_bp_per_col > 1:
            txt.append(f"  ·  zoom {ed._zoom_bp_per_col} bp/col",
                       style="cyan")
        else:
            txt.append("  ·  ", style="dim")
            txt.append("− zoom out", style="dim")
        status.update(txt)

    def _refresh_status_protein(self) -> None:
        try:
            status = self.query_one("#syn-status", Static)
            pe = self.query_one("#syn-protein-editor", ProteinEditor)
        except NoMatches:
            return
        aa_seq, codon_mode = pe.get_state()
        name = self._protein_loaded_name or "(unsaved)"
        sel = pe.current_selection()
        n_aa = len(aa_seq)
        n_bp = n_aa * 3
        mode_label = "codon" if codon_mode else "AA-only"
        # Codon table name (just the part before the '|' separator).
        table_label = self._codon_table_choice.split("|")[0] \
            if self._codon_table_choice else "?"
        txt = Text()
        txt.append("[Protein] ", style="dim")
        txt.append(name, style="bold")
        if self._protein_dirty:
            txt.append(" ●", style="yellow")
        txt.append(f"  ·  {n_aa:,} aa ({n_bp:,} bp)")
        txt.append(f"  ·  codons: {table_label}", style="dim")
        txt.append(f"  ·  mode: {mode_label}", style="dim")
        txt.append(f"  ·  cursor {pe._cursor_pos}")
        if sel is not None:
            s, e = sel
            txt.append(f"  ·  sel {s}-{e} ({e - s} aa)")
        status.update(txt)

    @on(SynthesisEditor.Changed)
    def _on_editor_changed(self, _event: "SynthesisEditor.Changed") -> None:
        """DNA editor mutation → mark DNA tab dirty + refresh status +
        push an undo snapshot (unless we're mid-undo/redo repaint)."""
        self._dirty = True
        self._capture_undo("dna")
        self._refresh_status()

    @on(SynthesisEditor.Loaded)
    def _on_editor_loaded(self, _event: "SynthesisEditor.Loaded") -> None:
        """DNA editor wholesale load → reset that tab's undo history so
        Ctrl+Z stays within the freshly-loaded fragment."""
        try:
            ed = self.query_one("#syn-editor", SynthesisEditor)
            self._dna_undo = [ed.snapshot()]
            self._dna_redo = []
        except NoMatches:
            pass

    @on(SynthesisEditor.FeatureEditRequested)
    def _on_feature_edit_requested(
        self, event: "SynthesisEditor.FeatureEditRequested",
    ) -> None:
        """Sweep #29: Enter on a base inside a feature → push
        FeatureEditModal for that feature. Mirrors the main-canvas
        seq panel's `action_open_selected_feature` UX, just wired
        against the synth editor's local `_feats` list instead of
        the canvas record.

        On Save: write the label / type / strand / color back to
        the feat dict at `event.idx` via `_feats =
        _feats + [...]` style reassignment so the
        `_CHUNK_STATIC_CACHE` invalidates cleanly (sacred invariant
        #4, same fix as `add_feature` got 2026-05-26)."""
        try:
            ed = self.query_one("#syn-editor", SynthesisEditor)
        except NoMatches:
            return
        idx = event.idx
        # Re-validate against current `_feats` length — a Changed
        # event could have shifted indices between post + dispatch.
        if idx < 0 or idx >= len(ed._feats):
            return
        feat = dict(ed._feats[idx])
        n = len(ed._seq)
        # Sequence slice for the read-only display in the modal.
        # The synth editor doesn't host wrap features (linear by
        # construction), so a plain slice is safe.
        s = int(feat.get("start", 0))
        e = int(feat.get("end",   0))
        seq_slice = ed._seq[s:e] if 0 <= s < e <= n else ""
        # Notes: prefer the feature's existing `note` qualifier.
        # New features added via the synth editor's library Insert
        # don't usually carry one, but a user-edited feat might.
        notes_q = feat.get("qualifiers", {}).get("note", [])
        notes_str = "\n".join(str(x) for x in notes_q) if notes_q else ""

        def _on_result(result) -> None:
            if not isinstance(result, dict):
                return
            # Sweep #29: the modal can now dismiss with a
            # group-operation action (split / group / ungroup /
            # save_group_as_entry) in addition to the legacy save.
            # Synth features live in the editor's local `_feats`
            # list, NOT the canvas record, so the group / ungroup
            # / save-as-library paths don't have a counterpart
            # here — surface a notify and short-circuit. Split
            # COULD work on a synth feature but rel-coord math
            # against an editor-local feat is its own scope; bail
            # for now. Save is the path that lands.
            action = result.get("action", "save")
            if action != "save":
                try:
                    self.app.notify(
                        f"'{action}' is a canvas-only operation; "
                        "open the feature on the main canvas to "
                        "use it.",
                        severity="information",
                    )
                except (AttributeError, NoMatches):
                    pass
                return
            # Sweep #29: rebuild the feat dict atomically — the
            # whole `_feats` list gets reassigned at the end so the
            # in-place-mutation cache bug we hit on `add_feature`
            # can't recur here. Write-back logic is shared with the
            # protein handler via `_apply_feature_edit_result`.
            target = self._apply_feature_edit_result(ed._feats[idx], result)
            new_feats = list(ed._feats)
            new_feats[idx] = target
            ed._feats = new_feats
            ed._refresh_view()
            ed.post_message(ed.Changed())
            # Restore focus to the editor so the user can keep
            # typing immediately after the feature edit dismisses.
            self._focus_dna_editor()

        self.app.push_screen(
            FeatureEditModal(idx, feat, n,
                              sequence=seq_slice, notes=notes_str),
            callback=_on_result,
        )

    @staticmethod
    def _apply_feature_edit_result(target: dict, result: dict) -> dict:
        """Apply a `FeatureEditModal` 'save' result (label / type /
        strand / color / notes) onto a COPY of `target` and return it.
        Shared by the DNA (`_feats`) and protein (`_aa_feats`)
        feature-edit handlers so the write-back — including the
        `SpliceCraft_strand=["double"]` persistence convention and the
        blank-line note split — stays identical across both tabs."""
        target = dict(target)
        new_label = result.get("label")
        if isinstance(new_label, str):
            label = new_label.strip() or target.get("label", "")
            target["label"] = label
            quals = dict(target.get("qualifiers") or {})
            quals["label"] = [label] if label else quals.get("label", [])
            target["qualifiers"] = quals
        new_type = result.get("type")
        if isinstance(new_type, str) and new_type.strip():
            target["type"] = new_type.strip()
        new_strand = result.get("strand")
        if isinstance(new_strand, int) and new_strand in (-1, 0, 1, 2):
            target["strand"] = new_strand
            quals = dict(target.get("qualifiers") or {})
            if new_strand == 2:
                quals["SpliceCraft_strand"] = ["double"]
            else:
                quals.pop("SpliceCraft_strand", None)
            target["qualifiers"] = quals
        new_color = result.get("color")
        if isinstance(new_color, str) and new_color.strip():
            target["color"] = new_color.strip()
        elif new_color is None or new_color == "":
            # Auto: drop the explicit color so palette logic picks at
            # render time.
            target["color"] = ""
        new_notes = result.get("notes")
        if isinstance(new_notes, str):
            quals = dict(target.get("qualifiers") or {})
            stripped = new_notes.strip()
            if stripped:
                quals["note"] = [
                    p.strip() for p in stripped.split("\n\n") if p.strip()
                ]
            else:
                quals.pop("note", None)
            target["qualifiers"] = quals
        return target

    @on(ProteinEditor.FeatureEditRequested)
    def _on_protein_feature_edit_requested(
        self, event: "ProteinEditor.FeatureEditRequested",
    ) -> None:
        """Enter on an AA inside a motif — or a double-click on its lane
        art — opens `FeatureEditModal` for that motif (AA coords). Mirror
        of the DNA `_on_feature_edit_requested`, writing back to the
        protein editor's `_aa_feats` via the shared
        `_apply_feature_edit_result`."""
        try:
            pe = self.query_one("#syn-protein-editor", ProteinEditor)
        except NoMatches:
            return
        idx = event.idx
        if idx < 0 or idx >= len(pe._aa_feats):
            return
        feat = dict(pe._aa_feats[idx])
        n = len(pe._aa_seq)
        s = int(feat.get("start", 0))
        e = int(feat.get("end", 0))
        # The read-only "sequence" box shows the motif's amino acids.
        seq_slice = pe._aa_seq[s:e] if 0 <= s < e <= n else ""
        notes_q = feat.get("qualifiers", {}).get("note", [])
        notes_str = "\n".join(str(x) for x in notes_q) if notes_q else ""

        def _on_result(result) -> None:
            if not isinstance(result, dict):
                return
            action = result.get("action", "save")
            if action != "save":
                try:
                    self.app.notify(
                        f"'{action}' is a canvas-only operation; open the "
                        "feature on the main canvas to use it.",
                        severity="information",
                    )
                except (AttributeError, NoMatches):
                    pass
                return
            if idx >= len(pe._aa_feats):
                return
            target = self._apply_feature_edit_result(pe._aa_feats[idx],
                                                     result)
            new_feats = list(pe._aa_feats)
            new_feats[idx] = target
            pe._aa_feats = new_feats
            pe._refresh_view()
            pe.post_message(pe.Changed())
            self._focus_protein_editor()

        self.app.push_screen(
            FeatureEditModal(idx, feat, n,
                              sequence=seq_slice, notes=notes_str),
            callback=_on_result,
        )

    def _focus_protein_editor(self) -> None:
        """Restore focus to the protein editor's scroll container after a
        modal flow so the user can keep typing residues. No-op off the
        protein tab or when unmounted (test / degenerate paths)."""
        if self._active_tab_id() != "protein":
            return
        try:
            pe = self.query_one("#syn-protein-editor", ProteinEditor)
            scroll = pe.query_one("#pe-scroll", ScrollableContainer)
        except NoMatches:
            return
        scroll.focus()

    @on(SynthesisEditor.CursorMoved)
    def _on_editor_cursor_moved(
        self, _event: "SynthesisEditor.CursorMoved",
    ) -> None:
        """DNA cursor / selection change → refresh status (no dirty)."""
        self._refresh_status()

    @on(ProteinEditor.Changed)
    def _on_protein_changed(self, _event: "ProteinEditor.Changed") -> None:
        """Protein editor mutation → mark protein tab dirty + (while
        auto-tracking) re-derive the Stops selector from the trailing '*'
        + push an undo snapshot."""
        self._protein_dirty = True
        self._capture_undo("protein")
        self._sync_stops_selector_from_protein()
        self._refresh_status()

    @on(ProteinEditor.Loaded)
    def _on_protein_loaded(self, _event: "ProteinEditor.Loaded") -> None:
        """Protein editor wholesale load → reset that tab's undo history."""
        try:
            pe = self.query_one("#syn-protein-editor", ProteinEditor)
            self._protein_undo = [pe.snapshot()]
            self._protein_redo = []
        except NoMatches:
            pass

    # ── Undo / redo ───────────────────────────────────────────────────────

    def _capture_undo(self, tab: str) -> None:
        """Push the active editor's current state onto `tab`'s undo stack
        (top = current). No-op while a `apply_snapshot` repaint is in
        flight (`_undo_suspended`) so an undo/redo can't record itself.
        A fresh edit clears the redo stack (it forks a new future)."""
        if self._undo_suspended:
            return
        if tab == "protein":
            try:
                ed = self.query_one("#syn-protein-editor", ProteinEditor)
            except NoMatches:
                return
            stack, redo = self._protein_undo, self._protein_redo
        else:
            try:
                ed = self.query_one("#syn-editor", SynthesisEditor)
            except NoMatches:
                return
            stack, redo = self._dna_undo, self._dna_redo
        stack.append(ed.snapshot())
        if len(stack) > self._UNDO_MAX:
            del stack[0]   # bound history; drops the oldest reachable state
        redo.clear()

    def action_undo(self) -> None:
        """Ctrl+Z — revert the active tab's editor one step."""
        is_protein = self._active_tab_id() == "protein"
        ed, stack, redo = self._active_undo_target(is_protein)
        if ed is None:
            return
        if len(stack) < 2:
            self.app.notify("Nothing to undo.", severity="information",
                            timeout=2)
            return
        redo.append(stack.pop())     # current state → redo
        prev = stack[-1]             # new top = the state to restore
        self._apply_undo_snapshot(ed, prev)
        if is_protein:
            self._protein_dirty = True
        else:
            self._dirty = True
        self._refresh_status()

    def action_redo(self) -> None:
        """Ctrl+Y — re-apply the last undone step in the active tab."""
        is_protein = self._active_tab_id() == "protein"
        ed, stack, redo = self._active_undo_target(is_protein)
        if ed is None:
            return
        if not redo:
            self.app.notify("Nothing to redo.", severity="information",
                            timeout=2)
            return
        snap = redo.pop()
        stack.append(snap)
        self._apply_undo_snapshot(ed, snap)
        if is_protein:
            self._protein_dirty = True
        else:
            self._dirty = True
        self._refresh_status()

    def _active_undo_target(self, is_protein: bool):
        """Return ``(editor_or_None, undo_stack, redo_stack)`` for the
        active tab. The stacks are ALWAYS the concrete per-tab lists (so
        the caller can index them without a None-check); only the editor
        is None when it isn't mounted (test / teardown paths), which the
        caller treats as "nothing to do"."""
        if is_protein:
            stack, redo = self._protein_undo, self._protein_redo
            selector, cls = "#syn-protein-editor", ProteinEditor
        else:
            stack, redo = self._dna_undo, self._dna_redo
            selector, cls = "#syn-editor", SynthesisEditor
        try:
            ed = self.query_one(selector, cls)
        except NoMatches:
            ed = None
        return ed, stack, redo

    def _apply_undo_snapshot(self, ed, snap: dict) -> None:
        """Repaint the editor from a snapshot with change-capture
        suspended (so the resulting refresh doesn't push a new undo
        entry) and focus restored to the editor."""
        self._undo_suspended = True
        try:
            ed.apply_snapshot(snap)
        finally:
            self._undo_suspended = False

    # ── Restriction-site overlay (R key) ──────────────────────────────────

    @_action_log("synthesis.toggle_restr")
    def action_toggle_restr_sites(self) -> None:
        """R — reveal / hide restriction cut sites on the DNA tab, the
        same overlay the main sequence panel toggles. DNA-tab only: the
        protein editor types 'R' as arginine, so this never fires from
        there, but guard anyway for a stray focus."""
        if self._active_tab_id() == "protein":
            self.app.notify(
                "Cut-site reveal is DNA-tab only (R types arginine on the "
                "Protein tab).",
                severity="information",
            )
            return
        try:
            ed = self.query_one("#syn-editor", SynthesisEditor)
        except NoMatches:
            return
        if not ed._seq:
            self.app.notify("Nothing to scan — the fragment is empty.",
                            severity="information", timeout=2)
            return
        on = ed.toggle_restr_overlay()
        if on:
            count = ed.restr_site_count()
            self.app.notify(
                f"Restriction sites shown — {count} site"
                f"{'s' if count != 1 else ''} in this fragment."
                if count else
                "Restriction overlay on — no sites for the active enzyme set.",
                timeout=3,
            )
        else:
            self.app.notify("Restriction sites hidden.", timeout=2)

    # ── Copy (Ctrl+C) ─────────────────────────────────────────────────────

    def action_copy_selection(self) -> None:
        """Ctrl+C — copy the ACTIVE tab editor's current selection to the
        clipboard byte-for-byte, and stash the selection's features
        (rebased to the copied span) so a paste back into a SpliceCraft
        editor carries the annotations. Routes by tab; a bare cursor with
        no selection notifies rather than copying the whole buffer."""
        if self._active_tab_id() == "protein":
            self._copy_protein_selection()
        else:
            self._copy_dna_selection()

    def _copy_dna_selection(self) -> None:
        try:
            ed = self.query_one("#syn-editor", SynthesisEditor)
        except NoMatches:
            return
        sel = ed.current_selection()
        if not sel:
            self.app.notify(
                "No selection — drag across bases or click a feature first.",
                severity="information", timeout=2)
            return
        s, e = int(sel[0]), int(sel[1])
        seq = ed._seq
        if not (0 <= s < e <= len(seq)):
            return
        top = seq[s:e].upper()
        # Rebase the selection's user features to [0, span) via the same
        # helper the main seq panel's feature-rich copy uses (linear here,
        # so the non-wrap path). Resite/recut overlays live in
        # `_restr_feats`, not `_feats`, so they're never carried.
        try:
            region_feats = self.app._gather_region_feats(  # type: ignore[attr-defined]
                ed._feats, s, e, len(seq))
        except (AttributeError, TypeError, ValueError):
            region_feats = []
        self.app._copied_region = {  # type: ignore[attr-defined]
            "seq": top, "feats": region_feats}
        mode, detail = _copy_to_clipboard_with_fallback(
            self.app, top, label="synthesis fragment")
        self.app._notify_copy_outcome(  # type: ignore[attr-defined]
            len(top), "bp", mode, detail)

    def _copy_protein_selection(self) -> None:
        try:
            pe = self.query_one("#syn-protein-editor", ProteinEditor)
        except NoMatches:
            return
        sel = pe.current_selection()
        if not sel:
            self.app.notify(
                "No selection — drag across residues or click a motif first.",
                severity="information", timeout=2)
            return
        s, e = int(sel[0]), int(sel[1])
        aa = pe._aa_seq
        if not (0 <= s < e <= len(aa)):
            return
        frag = aa[s:e].upper()
        try:
            region_feats = self.app._gather_region_feats(  # type: ignore[attr-defined]
                pe._aa_feats, s, e, len(aa))
        except (AttributeError, TypeError, ValueError):
            region_feats = []
        # Protein-coord copies ride a SEPARATE stash so a DNA paste can't
        # mistake AA letters for bases (the DNA `on_paste` matches against
        # `_copied_region["seq"]`, this against `_copied_protein_region`).
        self.app._copied_protein_region = {  # type: ignore[attr-defined]
            "aa": frag, "feats": region_feats}
        mode, detail = _copy_to_clipboard_with_fallback(
            self.app, frag, label="protein fragment")
        self.app._notify_copy_outcome(  # type: ignore[attr-defined]
            len(frag), "aa", mode, detail)

    def _protein_trailing_stops(self) -> int:
        """Count the protein editor's TRAILING '*' run (capped at the
        selector's max of 3). A mid-sequence '*' is NOT counted — that's an
        error the optimize path reports. Sanitised with the same filter
        `_on_optimize_to_dna` uses so the count matches what optimize sees."""
        try:
            pe = self.query_one("#syn-protein-editor", ProteinEditor)
        except NoMatches:
            return 0
        aa = re.sub(r"[\s\d>_\-]", "", (pe.get_state()[0] or "")).upper()
        n = 0
        while aa.endswith("*"):
            aa = aa[:-1]
            n += 1
        return min(3, n)

    def _sync_stops_selector_from_protein(self) -> None:
        """While auto-tracking, set the Stops selector to the protein's
        trailing-'*' count (0..3). No-op once the user has overridden it.
        Sets the value EQUAL to the trailing count, so the resulting
        `Select.Changed` is recognised as our own (not a user override)."""
        if not getattr(self, "_stops_auto", True):
            return
        try:
            sel = self.query_one("#syn-codon-stops", Select)
        except NoMatches:
            return
        val = str(self._protein_trailing_stops())
        if str(sel.value) != val:
            sel.value = val

    @on(Select.Changed, "#syn-codon-stops")
    def _on_stops_selector_changed(self, event: "Select.Changed") -> None:
        """A selector value that DIFFERS from the protein's trailing-'*' count
        is a deliberate user override → stop auto-tracking so the selector is
        authoritative on the next Optimize. Our own auto-sync always sets the
        value EQUAL to the trailing count, so it never trips this; a fresh
        load / open / new re-enables auto-tracking."""
        try:
            differs = str(event.value) != str(self._protein_trailing_stops())
        except Exception:
            differs = True
        if differs:
            self._stops_auto = False

