# ── Library status (workflow tag) ─────────────────────────────────────────────




@_agent_endpoint("set-plasmid-status", write=True)
def _h_set_plasmid_status(app, payload):
    """Set / clear a library entry's workflow status. Body:
    ``{name|id, status}``. ``status`` must be one of the values from
    `list-plasmid-statuses`, or empty string / null to clear. Anything
    else is treated as "clear" (matches `_sanitize_plasmid_status`'s
    documented strict-canonical-or-empty behaviour). Persists via
    `_save_library`, which mirrors into the active collection.

    Save-failure contract (audit sweep #4): wraps `_save_library`
    via `_agent_save_or_500` so disk-write failures surface as
    ``500 {"error": "save failed for library: ..."}`` with the UI
    user also notified — the in-memory cache stays consistent."""
    key = _sanitize_label(payload.get("name") or payload.get("id"),
                           max_len=200)
    if not key:
        return ({"error": "missing 'name' or 'id'"}, 400)
    raw_status = payload.get("status")
    if raw_status is None:
        new_status = ""
    elif isinstance(raw_status, str):
        new_status = _sanitize_plasmid_status(raw_status)
    else:
        return ({"error": "'status' must be a string or null"}, 400)

    def _apply():
        guard = _agent_dirty_guard(app, payload)
        if guard is not None:
            return guard
        # Sweep #30 (2026-05-28): full load -> mutate -> save RMW under
        # _cache_lock so a concurrent worker-thread library writer can't
        # interleave (see _h_delete_from_library). RLock re-enters through
        # _save_library. [INV-74]
        with _cache_lock:
            entries = _load_library()
            for e in entries:
                if e.get("name") == key or e.get("id") == key:
                    e["status"] = new_status
                    if (err := _agent_save_or_500(
                            lambda: _save_library(entries),
                            "library")) is not None:
                        return err
                    _agent_refresh_library_panel(app)
                    return new_status
            return None

    result = app.call_from_thread(_apply)
    if isinstance(result, tuple):
        return result
    if result is None:
        return ({"error": f"no library entry matching {key!r}"}, 404)
    return {"ok": True, "name": key, "status": result}


@_agent_endpoint("rename-plasmid", write=True)
def _h_rename_plasmid(app, payload):
    """Rename a library plasmid's display name. Body: ``{old|id, new}``.

    The remediation for snag #12: a plasmid whose display name got
    mangled to an underscore slug can be renamed back to its spaced
    form. ``new`` is the human display name (spaces / ``+`` preserved) —
    NOT the GenBank LOCUS, which stays the LOCUS-safe ``id``. Looks the
    entry up in the ACTIVE collection by ``old`` name or ``id``, the same
    scope as ``set-plasmid-status`` / ``delete-from-library`` (use
    ``set-active-collection`` to reach another collection). Refuses with
    ``409`` if ``new`` is already used by a DIFFERENT entry in the
    collection. Persists via ``_save_library`` (mirrors into the active
    collection) and re-stamps the loaded record's ``_tui_display_name``
    if it's the one on the canvas, so a follow-up save can't re-bake the
    old name.

    Keys other than ``old``/``id``/``new``/``force`` are echoed under
    ``ignored`` (snag #14)."""
    key = _sanitize_label(payload.get("old") or payload.get("id"),
                           max_len=200)
    if not key:
        return ({"error": "missing 'old' or 'id'"}, 400)
    new_name = _sanitize_label(payload.get("new"), max_len=200)
    if not new_name:
        return ({"error": "missing or invalid 'new'"}, 400)

    def _apply():
        guard = _agent_dirty_guard(app, payload)
        if guard is not None:
            return guard
        # Full load -> mutate -> save RMW under _cache_lock so a
        # concurrent worker-thread library writer can't interleave
        # (mirrors _h_set_plasmid_status / _h_delete_from_library). RLock
        # re-enters through _save_library. [INV-74]
        with _cache_lock:
            entries = _load_library()
            target = None
            for e in entries:
                if e.get("name") == key or e.get("id") == key:
                    target = e
                    break
            if target is None:
                return None
            if new_name == (target.get("name") or ""):
                return ("noop", target)
            # A DIFFERENT entry already owns `new_name` — refuse rather
            # than create a name-ambiguous pair the name-based load/delete
            # paths can't disambiguate.
            if any((e.get("name") or "") == new_name
                   and e.get("id") != target.get("id") for e in entries):
                return ("clash", None)
            target["name"] = new_name
            if (err := _agent_save_or_500(
                    lambda: _save_library(entries), "library")) is not None:
                return err
            cur = getattr(app, "_current_record", None)
            if cur is not None and cur.id == target.get("id"):
                try:
                    cur._tui_display_name = new_name  # type: ignore[attr-defined]
                except Exception:
                    pass
            _agent_refresh_library_panel(app)
            return ("ok", target)

    result = app.call_from_thread(_apply)
    if result is None:
        active = _get_active_collection_name()
        return ({"error":
                  f"no library entry matching {key!r} in the active "
                  f"collection {active!r} — rename operates on the active "
                  f"collection only (like set-plasmid-status). Use "
                  f"set-active-collection to switch to its home first; "
                  f"search-library shows which collection holds it."}, 404)
    if isinstance(result, tuple) and result and isinstance(result[0], str):
        tag, tgt = result
        if tag == "clash":
            return ({"error":
                      f"another entry is already named {new_name!r} in "
                      f"this collection"}, 409)
        return {"ok": True,
                "id": (tgt.get("id", "") if tgt else ""),
                "old": key, "new": new_name,
                "renamed": tag == "ok",
                "ignored": _agent_ignored_keys(payload,
                                               {"old", "id", "new"})}
    # Otherwise an error tuple (dirty-guard 409 / save-failure 500).
    return result


# ── Per-grammar entry vectors ─────────────────────────────────────────────────






@_agent_endpoint("set-entry-vector", write=True)
def _h_set_entry_vector(app, payload):
    """Set or clear a grammar's entry vector. Body to set:
    ``{grammar_id, name, gb_text, source?}``; body to clear:
    ``{grammar_id, clear: true}``. ``gb_text`` is parsed once to
    confirm it's valid GenBank and to extract the size — the parsed
    record itself is discarded; only the original text is persisted
    so the grammar editor's "open file" round-trip stays byte-exact."""
    guard = _agent_dirty_guard(app, payload)
    if guard is not None:
        return guard
    gid = payload.get("grammar_id")
    if not isinstance(gid, str) or not gid:
        return ({"error": "missing or non-string 'grammar_id'"}, 400)

    if bool(payload.get("clear")):
        def _clear():
            _set_entry_vector(gid, None)
        if (err := _agent_save_or_500(
                lambda: app.call_from_thread(_clear),
                "entry_vectors")) is not None:
            return err
        return {"ok": True, "grammar_id": gid, "vector": None}

    name = _sanitize_label(payload.get("name"), max_len=200)
    if not name:
        return ({"error": "missing 'name'"}, 400)
    gb_text = payload.get("gb_text")
    if not isinstance(gb_text, str) or not gb_text.strip():
        return ({"error": "missing or non-string 'gb_text'"}, 400)
    # Cap at 500 KB — well above any realistic plasmid GenBank text
    # (a heavily-annotated 50 kb destination vector is ~100 KB), but
    # below the HTTP transport's 1 MiB body cap so this inner check
    # is reachable. Tighter ceiling means a malformed payload bounces
    # before the BioPython parser starts allocating intermediate
    # objects.
    if len(gb_text) > 500 * 1024:
        return ({"error": "'gb_text' too large (max 500 KB)"}, 400)
    try:
        rec = _gb_text_to_record(gb_text)
    except Exception as exc:
        return ({"error": f"gb_text parse failed: {exc}"}, 400)
    source_raw = payload.get("source")
    source = source_raw if isinstance(source_raw, str) else ""
    vector = {
        "name":     name,
        "size":     _seq_len(rec),
        "source":   source[:300],   # cap source for paranoia
        "gb_text":  gb_text,
    }

    def _apply():
        _set_entry_vector(gid, vector)

    if (err := _agent_save_or_500(
            lambda: app.call_from_thread(_apply),
            "entry_vectors")) is not None:
        return err
    out = dict(vector); out.pop("gb_text", None)
    return {"ok": True, "grammar_id": gid, "vector": out}


