def _settings_validator_choice(*choices):
    def _v(value):
        if isinstance(value, str) and value in choices:
            return value, None
        return None, "must be one of " + ", ".join(repr(c) for c in choices)
    return _v
















# ── Parts bin CRUD (Tier 4 — mirrors PartsBinModal) ───────────────────────────








@_agent_endpoint("delete-part", write=True)
def _h_delete_part(app, payload):
    """Remove a part by `name` (optionally `grammar`), optionally scoped to a
    ``{bin}``. Without ``bin`` it deletes from the active bin; with ``bin`` it
    removes from THAT named bin's own parts (SC-M) — so you can prune a bin
    (e.g. strip stale parts) without touching the active one. Removing a part
    that also lives in another bin is safe. Refuses (409) to delete from a
    named bin while it's ACTIVE — switch away first. Returns count deleted;
    404 if nothing matches."""
    name = _sanitize_label(payload.get("name"), max_len=200)
    if not name:
        return ({"error": "missing 'name'"}, 400)
    grammar = payload.get("grammar")
    if grammar is not None and not isinstance(grammar, str):
        return ({"error": "'grammar' must be string"}, 400)
    bin_in = payload.get("bin")

    def _match(p):
        if p.get("name") != name:
            return False
        if grammar and (p.get("grammar") or "") != grammar:
            return False
        return True

    def _apply():
        # Sweep #26: RMW under `_cache_lock`; writes route through
        # `_agent_save_or_500` for notify-on-failure parity.
        with _cache_lock:
            if bin_in not in (None, ""):
                if not isinstance(bin_in, str):
                    return ({"error": "'bin' must be a string"}, 400)
                bin_name = bin_in.strip()
                if bin_name == (_get_active_parts_bin_name() or ""):
                    return ({"error":
                              f"{bin_name!r} is the active parts bin — "
                              f"set-active-parts-bin to another bin before "
                              f"deleting from it, so the live mirror stays "
                              f"consistent"}, 409)
                bins = _load_parts_bin_collections()
                tgt = next((b for b in bins
                            if (b.get("name") or "") == bin_name), None)
                if tgt is None:
                    return ({"error":
                              f"no parts bin named {bin_name!r}"}, 404)
                entries = tgt.get("parts") or []
                kept = [p for p in entries if not _match(p)]
                if len(kept) == len(entries):
                    return ({"error":
                              f"no part named {name!r} in bin {bin_name!r}"
                              + (f" (grammar {grammar!r})" if grammar
                                 else "")}, 404)
                tgt["parts"] = kept
                err = _agent_save_or_500(
                    lambda: _save_parts_bin_collections(bins),
                    "parts_bin_collections")
                if err:
                    return err
                return len(entries) - len(kept)
            entries = _load_parts_bin()
            kept = [p for p in entries if not _match(p)]
            if len(kept) == len(entries):
                return ({"error": f"no part named {name!r}"
                          + (f" in grammar {grammar!r}" if grammar else "")}, 404)
            err = _agent_save_or_500(
                lambda: _save_parts_bin(kept), "parts_bin",
            )
            if err:
                return err
        return len(entries) - len(kept)

    result = app.call_from_thread(_apply)
    if isinstance(result, tuple):
        return result
    return {"ok": True, "deleted": result, "name": name,
            "bin": (bin_in.strip() if isinstance(bin_in, str) and bin_in.strip()
                    else "")}








