@_agent_endpoint("capture-snapshot", write=True)
def _h_capture_snapshot(app, payload):
    """Write a Markdown UI snapshot (same content as Alt+D) and
    return the file path. Useful for an agent assembling a bug
    report: snapshot first, then bundle the log dir.

    Marked `write=True` because the call writes a new file under
    `<DATA_DIR>/ui_snapshots/`; the snapshot itself doesn't mutate
    user data, but creating a file is a write side-effect.
    """
    def _apply():
        try:
            snap = _collect_ui_snapshot(app)
            text = _format_ui_snapshot(snap)
            path = _save_ui_snapshot(text)
            return str(path)
        except OSError as exc:
            _log.exception("agent capture-snapshot: write failed")
            return ({"error": f"snapshot write failed: {_scrub_path(str(exc))}"}, 500)
        except (ValueError, AttributeError, TypeError) as exc:
            # `_collect_ui_snapshot` is defensive (returns empty fields
            # rather than raising on missing widgets) but a future
            # snapshot field that touches a not-yet-mounted widget
            # could still raise. Narrowed from base `Exception` so a
            # genuine bug (e.g. KeyboardInterrupt during shutdown)
            # propagates rather than being silently mapped to 500.
            _log.exception("agent capture-snapshot: collect failed")
            return ({"error": f"snapshot collect failed: {_scrub_path(str(exc))}"}, 500)
    result = app.call_from_thread(_apply)
    if isinstance(result, tuple):
        return result
    return {"ok": True, "path": result}


# ── Data-safety endpoints (backups + pre-update snapshots) ────────────────────














# ── Design / simulation endpoints (Gibson, mutagenesis, primer design) ────────




@_agent_endpoint("gibson-assemble", write=True)
def _h_gibson_assemble(app, payload):
    """Run a Gibson simulation AND save the product to the library.
    Body extends ``simulate-gibson`` with:

      * ``product_name?: str = "gibson-<n>"`` — library entry name
        (autoname collision is resolved by bumping).

    Returns the simulator result plus ``saved_name`` and
    ``saved_id`` of the new library entry. Saves directly via
    `_save_library` (not through `_gibson_save_worker`'s UI path)
    because there's no Textual app on this thread — we're the
    agent.
    """
    guard = _agent_dirty_guard(app, payload)
    if guard is not None:
        return guard
    # Run simulator first via the read-only handler to share validation.
    sim_resp = _h_simulate_gibson(app, payload)
    if isinstance(sim_resp, tuple):
        return sim_resp
    result = sim_resp["result"]
    if not result.get("success"):
        return ({"error": "Gibson simulation failed; see 'result' for "
                  "details",
                  "result": result}, 422)
    base_name = _sanitize_label(payload.get("product_name"),
                                  max_len=80) or "gibson"
    rec = _gibson_record_from_result(result, name=base_name)
    if rec is None:
        return ({"error": "failed to build SeqRecord from product"}, 500)
    try:
        gb_text = _record_to_gb_text(rec)
    except Exception as exc:
        _log.exception("agent gibson-assemble: gb_text serialise failed")
        return ({"error": f"gb_text serialise failed: {_scrub_path(str(exc))}"}, 500)
    # Sweep #26: RMW under `_cache_lock` so the autoname-bump + insert
    # + save are atomic. Pre-fix two concurrent gibson-assemble calls
    # could both pick the same "gibson-2" autoname (each saw the same
    # pre-fix existing set) and the second save would silently
    # overwrite the first via the standard cache-reseat race.
    # Also routed through `_agent_save_or_500` for parity with the
    # rest of the create endpoints (proper notify-on-failure).
    with _cache_lock:
        entries = _load_library()
        existing = {e.get("name") for e in entries if isinstance(e, dict)}
        n = 1
        name = base_name
        while name in existing:
            n += 1
            name = f"{base_name}-{n}"
        # Re-stamp the rec with the disambiguated name so the in-memory
        # record + library entry agree on the LOCUS line.
        rec.id = name
        rec.name = name
        try:
            gb_text = _record_to_gb_text(rec)
        except Exception as exc:
            _log.exception("agent gibson-assemble: gb_text serialise failed")
            return ({"error": f"gb_text serialise failed: {_scrub_path(str(exc))}"}, 500)
        entry = {
            "id":      name,
            "name":    name,
            "size":    _seq_len(rec),
            "n_feats": len(rec.features or []),
            "source":  "agent:gibson",
            "added":   _date.today().isoformat(),
            "gb_text": gb_text,
            # P0-2: real assembly lineage — each input fragment becomes a
            # parent node (cross-referenced to the library by name so a
            # fragment saved earlier carries its own sub-lineage), instead
            # of the flat createDocument leaf an agent build used to get.
            "history_xml": _build_history_for_agent_assembly(
                name=name, seq_len=_seq_len(rec),
                circular=bool(payload.get("circular", True)),
                manipulation="gibsonAssembly",
                parents=[_agent_assembly_parent(f, f"F{i + 1}")
                         for i, f in enumerate(
                             payload.get("fragments") or [])]),
        }
        entries.insert(0, entry)
        if (err := _agent_save_or_500(
                lambda: _save_library(entries), "library")) is not None:
            return err
    # Sweep #25 (2026-05-23): UI refresh MUST go through
    # `call_from_thread` from the HTTP worker thread — every other
    # library-mutating endpoint (`_h_create_collection`,
    # `_h_delete_collection`, `_h_rename_collection`,
    # `_h_set_active_collection`, `_h_bulk_import_folder`) does this;
    # Gibson was the one site missed. Pre-fix the unwrapped call
    # could touch DataTable rows from the wrong thread, risking UI
    # crash or panel/disk state divergence.
    if app is not None and hasattr(app, "call_from_thread"):
        app.call_from_thread(_agent_refresh_library_panel, app)
    else:
        _agent_refresh_library_panel(app)
    return {"ok": True, "saved_name": name, "saved_id": name,
            "result": result}


@_agent_endpoint("traditional-clone", write=True)
def _h_traditional_clone(app, payload):
    """Run a traditional restriction-cloning reaction AND save the product to
    the library — the restriction-cloning analog of `gibson-assemble`. Body
    extends `simulate-traditional-cloning` with:

      * ``product_name?: str`` — library entry name (autoname-bumped on
        collision).
      * ``vector_frag_idx?: int`` — which digested vector fragment is the
        backbone (from `simulate-traditional-cloning`'s `products`).
      * ``insert_circular?: bool = false`` — set true when ``insert_seq`` is a
        PLASMID you're cutting a cassette OUT of (e.g. an Ω multigene): it's
        digested into candidate fragments instead of treated as a linear PCR
        product.
      * ``insert_frag_idx?: int`` — which insert fragment is the cassette (from
        ``insert_fragments`` / a `products` entry); needed when a circular
        insert leaves more than one candidate.
      * ``orientation?: "forward" | "reverse"`` — insert orientation.
      * ``carry_annotations?: bool = false`` — lift the vector's and insert's
        OWN features onto the ligated product (split at the cuts, shifted to
        product coordinates) so the clone isn't feature-bare and needs no
        follow-up `transfer-annotations`. Features are sourced from the
        ``vector_name`` / ``insert_name`` library entries you already pass for
        lineage; a side whose passed sequence doesn't EXACTLY match its named
        entry is skipped (reported in ``carry_warnings`` — rotation-matching
        isn't attempted, so coordinates can't be mis-placed). Requires at least
        one of ``vector_name`` / ``insert_name`` (else 400); an unknown name is
        404. The response echoes ``annotations_carried`` + ``carry_warnings``.

    When the digest + ligation yields EXACTLY ONE compatible product it's
    saved automatically. When more than one is compatible — a palindromic
    cutter ligates both orientations, OR (the common case) both vector
    fragments accept the insert because a 2-enzyme digest leaves each piece
    with one cut of each kind — the call returns ``409`` listing the options;
    pass ``vector_frag_idx`` and/or ``orientation`` to disambiguate. It NEVER
    silently picks by fragment size (the never-assume-the-smaller-fragment-is-
    the-insert rule). The product is saved circular ([INV-127]: the design IS
    the product — a real digest + ligation, not a hand-built final)."""
    guard = _agent_dirty_guard(app, payload)
    if guard is not None:
        return guard
    info, err = _agent_traditional_cloning_candidates(payload)
    if err is not None:
        return err
    assert info is not None             # err is None ⇒ info is populated
    products = info["products"]
    if not products:
        return ({"error":
                  "no compatible ligation product — the insert's sticky ends "
                  "don't match any vector fragment. Check that the same "
                  "enzymes cut both, and see 'incompatible'.",
                  "incompatible": info["incompatible"]}, 422)
    # Optional disambiguation by fragment index(es) and/or orientation.
    vfi = payload.get("vector_frag_idx")
    ifi = payload.get("insert_frag_idx")
    orient = payload.get("orientation")
    if orient is not None and orient not in ("forward", "reverse"):
        return ({"error": "'orientation' must be 'forward' or 'reverse'"}, 400)
    chosen = products
    if vfi is not None:
        vfi_int = _coerce_int(vfi, name="vector_frag_idx")
        if isinstance(vfi_int, str):
            return ({"error": vfi_int}, 400)
        chosen = [p for p in chosen if p["vector_frag_idx"] == vfi_int]
    if ifi is not None:
        ifi_int = _coerce_int(ifi, name="insert_frag_idx")
        if isinstance(ifi_int, str):
            return ({"error": ifi_int}, 400)
        chosen = [p for p in chosen if p.get("insert_frag_idx", 0) == ifi_int]
    if orient is not None:
        chosen = [p for p in chosen if p["orientation"] == orient]
    if not chosen:
        return ({"error":
                  "no compatible product matches the given vector_frag_idx / "
                  "insert_frag_idx / orientation",
                  "available": [{"vector_frag_idx": p["vector_frag_idx"],
                                  "insert_frag_idx": p.get("insert_frag_idx", 0),
                                  "orientation": p["orientation"],
                                  "length": p["length"]}
                                 for p in products]}, 404)
    if len(chosen) > 1:
        return ({"error":
                  "ambiguous — more than one compatible product. Pass "
                  "'vector_frag_idx' / 'insert_frag_idx' and/or 'orientation' "
                  "to pick one (this endpoint never guesses by fragment size).",
                  "options": [{"vector_frag_idx": p["vector_frag_idx"],
                                "insert_frag_idx": p.get("insert_frag_idx", 0),
                                "orientation": p["orientation"],
                                "length": p["length"],
                                "n_features": p["n_features"]}
                               for p in chosen]}, 409)
    product = chosen[0]
    # Build the product record by reusing the Gibson result→record builder
    # (same {product_seq, features, circular} shape). A ligated plasmid is
    # circular.
    fake_result = {
        "success":     True,
        "product_seq": product["sequence"],
        "features":    product["features"],
        "circular":    True,
    }
    base_name = _sanitize_label(payload.get("product_name"),
                                  max_len=80) or "clone"
    rec = _gibson_record_from_result(fake_result, name=base_name)
    if rec is None:
        return ({"error": "failed to build SeqRecord from product"}, 500)
    # Atomic autoname-bump + insert + save (mirrors `gibson-assemble`).
    with _cache_lock:
        entries = _load_library()
        existing = {e.get("name") for e in entries if isinstance(e, dict)}
        n = 1
        name = base_name
        while name in existing:
            n += 1
            name = f"{base_name}-{n}"
        rec.id = name
        rec.name = name
        try:
            gb_text = _record_to_gb_text(rec)
        except Exception as exc:
            _log.exception("agent traditional-clone: gb_text serialise failed")
            return ({"error":
                      f"gb_text serialise failed: {_scrub_path(str(exc))}"},
                    500)
        entry = {
            "id":      name,
            "name":    name,
            "size":    _seq_len(rec),
            "n_feats": len(rec.features or []),
            "source":  "agent:traditional",
            "added":   _date.today().isoformat(),
            "gb_text": gb_text,
            # P0-2: real assembly lineage — vector + insert as parents
            # (pass `vector_name` / `insert_name` to link them to saved
            # library entries), not a flat createDocument leaf.
            "history_xml": _build_history_for_agent_assembly(
                name=name, seq_len=_seq_len(rec), circular=True,
                manipulation="restrictionLigation",
                parents=[
                    _agent_assembly_parent(
                        {"sequence": payload.get("vector_seq") or "",
                         "name": payload.get("vector_name")}, "vector"),
                    _agent_assembly_parent(
                        {"sequence": payload.get("insert_seq") or "",
                         "name": payload.get("insert_name")}, "insert"),
                ]),
        }
        entries.insert(0, entry)
        if (err := _agent_save_or_500(
                lambda: _save_library(entries), "library")) is not None:
            return err
    if app is not None and hasattr(app, "call_from_thread"):
        app.call_from_thread(_agent_refresh_library_panel, app)
    else:
        _agent_refresh_library_panel(app)
    return {"ok": True, "saved_name": name, "saved_id": name,
            "vector_frag_idx": product["vector_frag_idx"],
            "insert_frag_idx": product.get("insert_frag_idx", 0),
            "orientation":     product["orientation"],
            "length":          product["length"],
            "insert":          info["insert"],
            "annotations_carried": info.get("annotations_carried", False),
            "carry_warnings":      info.get("carry_warnings", [])}


@_agent_endpoint("golden-gate-assemble", write=True)
def _h_golden_gate_assemble(app, payload):
    """Run a Golden Gate / MoClo (Type IIS) assembly AND save the product to
    the library — the Type IIS counterpart to `gibson-assemble`. Body extends
    `simulate-golden-gate` with ``product_name?: str``.

    Digests the parts + vector with the enzyme (BsaI by default), chains them
    by overhang into a circular product, and saves it (source
    ``agent:golden-gate``). A failed assembly (no closed circle, a part that
    doesn't release exactly one fragment, a non-Type-IIS enzyme) returns 422
    with the assembler ``result`` so you can see why; fidelity warnings (a
    non-unique junction overhang, a residual enzyme site) ride along in
    ``result.warnings``. [INV-127: the design IS the product.]"""
    guard = _agent_dirty_guard(app, payload)
    if guard is not None:
        return guard
    parts, vseq, enzyme, err = _agent_golden_gate_inputs(payload)
    if err is not None:
        return err
    # `err is None` ⇒ the other three are populated; assert so pyright narrows
    # them off the (… | None) union the helper's tuple return widens to.
    assert parts is not None and vseq is not None and enzyme is not None
    try:
        result = _simulate_golden_gate(parts, vseq, enzyme=enzyme)
    except Exception as exc:
        _log.exception("agent golden-gate-assemble: assembler failed")
        return ({"error": f"assembler failed: {_scrub_path(str(exc))}"}, 500)
    if not result.get("ok"):
        return ({"error": "Golden Gate assembly failed; see 'result' for "
                  "details", "result": result}, 422)
    fake_result = {"success": True, "product_seq": result["product_seq"],
                   "features": [], "circular": True}
    base_name = _sanitize_label(payload.get("product_name"),
                                  max_len=80) or "goldengate"
    rec = _gibson_record_from_result(fake_result, name=base_name)
    if rec is None:
        return ({"error": "failed to build SeqRecord from product"}, 500)
    with _cache_lock:
        entries = _load_library()
        existing = {e.get("name") for e in entries if isinstance(e, dict)}
        n = 1
        name = base_name
        while name in existing:
            n += 1
            name = f"{base_name}-{n}"
        rec.id = name
        rec.name = name
        try:
            gb_text = _record_to_gb_text(rec)
        except Exception as exc:
            _log.exception("agent golden-gate-assemble: gb_text serialise "
                           "failed")
            return ({"error":
                      f"gb_text serialise failed: {_scrub_path(str(exc))}"},
                    500)
        entry = {
            "id":      name,
            "name":    name,
            "size":    _seq_len(rec),
            "n_feats": len(rec.features or []),
            "source":  "agent:golden-gate",
            "added":   _date.today().isoformat(),
            "gb_text": gb_text,
            # P0-2: real assembly lineage — each part + the vector as a
            # parent (named inputs nest their own sub-lineage), not a flat
            # createDocument leaf.
            "history_xml": _build_history_for_agent_assembly(
                name=name, seq_len=_seq_len(rec), circular=True,
                manipulation="goldenGateAssembly",
                parents=[_agent_assembly_parent(p, f"part {i + 1}")
                         for i, p in enumerate(payload.get("parts") or [])]
                        + [_agent_assembly_parent(payload.get("vector"),
                                                  "vector")]),
        }
        entries.insert(0, entry)
        if (err := _agent_save_or_500(
                lambda: _save_library(entries), "library")) is not None:
            return err
    if app is not None and hasattr(app, "call_from_thread"):
        app.call_from_thread(_agent_refresh_library_panel, app)
    else:
        _agent_refresh_library_panel(app)
    return {"ok": True, "saved_name": name, "saved_id": name,
            "result": result}


def _agent_resolve_save_dest(payload):
    """Resolve the optional ``collection`` save-destination (agent-API
    feedback). Returns ``(dest_name, None)`` — the ACTIVE collection when
    ``collection`` is omitted/empty, else the named collection (active OR
    non-active; a non-active dest routes the saved construct into THAT
    collection like ``copy-plasmid {to}`` instead of 409ing). Returns
    ``(None, (err, code))`` on an invalid or unknown collection. Resolve
    EARLY in the handler so a bad destination fails before the clone."""
    coll_in = payload.get("collection")
    if coll_in in (None, ""):
        return _get_active_collection_name(), None
    coll_name = _normalize_collection_name(coll_in)
    if coll_name is None:
        return None, ({"error": "invalid 'collection'"}, 400)
    if _find_collection(coll_name) is None:
        return None, ({"error": f"no collection named {coll_name!r}"}, 404)
    return coll_name, None


def _agent_save_constructed_entry(app, rec, *, base_name, source_tag,
                                  id_fallback, dest_coll, history_builder):
    """Persist a freshly-built construct (domesticate-part / assemble-into-
    entry-vector) into ``dest_coll`` — the single chokepoint both share.

    Dedupes the display name + LOCUS-safe id against the DESTINATION's own
    entries, stamps them onto ``rec`` (``_tui_display_name`` keeps spaces,
    [INV-98]), serialises gb_text, attaches lineage via ``history_builder``
    (called as ``(save_name, seq_len) -> xml | ""``), inserts at the front,
    and refreshes the library panel.

    Routing (agent-API feedback): when ``dest_coll`` is the ACTIVE collection
    the live mirror (`_load_library`/`_save_library`) is updated so the GUI
    panel reflects it; a NON-active dest inserts into that collection's
    ``plasmids`` in collections.json (the proven `copy-plasmid {to}` path) and
    leaves the active mirror untouched. The whole dedup→build→insert→save runs
    under one ``_cache_lock`` for a coherent snapshot. Returns
    ``(entry, None)`` or ``(None, (err, code))``."""
    to_active = (dest_coll == _get_active_collection_name())
    with _cache_lock:
        if to_active:
            entries = _load_library()
            _commit, _what = (lambda: _save_library(entries)), "library"
        else:
            colls = _load_collections()
            tgt = next((c for c in colls
                        if (c.get("name") or "") == dest_coll), None)
            if tgt is None:        # raced away between resolve and here
                return None, ({"error":
                                f"no collection named {dest_coll!r}"}, 404)
            entries = tgt.setdefault("plasmids", [])
            _commit, _what = (lambda: _save_collections(colls)), "collections"
        existing = {e.get("name") for e in entries if isinstance(e, dict)}
        existing_ids = {e.get("id") for e in entries if isinstance(e, dict)}
        n, save_name = 1, base_name
        while save_name in existing:
            n += 1
            save_name = f"{base_name}-{n}"
        # Disambiguate the LOCUS-safe id against existing ids too: two distinct
        # names sharing a 32-char prefix scrub to the SAME id, and this inserts
        # directly (bypassing add_entry's id-dedup), so without the bump a
        # later load-by-id returns the WRONG plasmid (code-review; mirrors
        # LibraryPanel._make_unique_entry_id).
        _base_id = (re.sub(r"[^A-Za-z0-9_-]+", "_", save_name).strip("_")[:32]
                    or id_fallback)
        safe_id, _bump = _base_id, 2
        while safe_id in existing_ids:
            safe_id = f"{_base_id[:28]}_{_bump}"
            _bump += 1
        rec.id = rec.name = safe_id
        rec._tui_display_name = save_name  # type: ignore[attr-defined]
        try:
            gb_text = _record_to_gb_text(rec)
        except Exception as exc:
            _log.exception("agent %s: gb_text serialise failed", source_tag)
            return None, ({"error":
                            f"gb_text serialise failed: {_scrub_path(str(exc))}"},
                          500)
        entry = {
            "id":      safe_id,
            "name":    save_name,
            "size":    _seq_len(rec),
            "n_feats": len([f for f in rec.features if f.type != "source"]),
            "source":  source_tag,
            "added":   _date.today().isoformat(),
            "gb_text": gb_text,
        }
        try:
            hist = history_builder(save_name, _seq_len(rec))
            if hist:
                entry["history_xml"] = hist
        except Exception:
            _log.debug("agent %s: history build failed", source_tag,
                       exc_info=True)
        entries.insert(0, entry)
        if (err := _agent_save_or_500(_commit, _what)) is not None:
            return None, err
    if app is not None and hasattr(app, "call_from_thread"):
        app.call_from_thread(_agent_refresh_library_panel, app)
    else:
        _agent_refresh_library_panel(app)
    return entry, None


@_agent_endpoint("domesticate-part", write=True)
def _h_domesticate_part(app, payload):
    """Domesticate a part into its configured Golden-Braid / MoClo entry
    vector — the real Synthesis-tab L0 clone, now agent-reachable (agent-API
    feedback P0-1). Digests the configured entry vector + the part's primed
    amplicon at the grammar's Type IIS enzyme, ligates the insert into the
    backbone, and SAVES the circular L0 plasmid (to the active collection, or
    the one named by ``collection``) with its construction lineage (insert +
    entry vector) attached — the same engine the GUI Domesticator / Parts-Bin
    "Save to Collection" uses.

    Body: ``{sequence, oh5, oh3, name, grammar?="gb_l0", type?,
             fwd_primer?, rev_primer?, collection?, product_name?}``.

    * ``sequence`` — the part insert (IUPAC DNA).
    * ``oh5`` / ``oh3`` — the 5' / 3' fusion overhangs (typically 4 nt) the
      domestication primers add; they MUST match the entry vector's dropout
      overhangs (this is what makes the part clone).
    * ``name`` — the part's display name (also the saved plasmid name unless
      ``product_name`` overrides).
    * ``grammar`` — cloning grammar id (default ``gb_l0``); its configured
      entry vector (set via ``set-entry-vector``) is digested.
    * ``type`` — part shape (``CDS`` / ``Promoter`` / …) for the annotation.
    * ``fwd_primer`` / ``rev_primer`` — the domestication primers, attached
      to the clone (re-derived against its sequence) so its History shows
      how it was built.

    **P1-5 — fails loud, never stubs:** if no entry vector is configured
    for the grammar, OR its dropout overhangs don't match the part (the
    IIS-digest AND overhang-splice tiers both fail), this returns ``422``
    rather than silently emitting a pUPD2-stub backbone — a stub L0 is a
    wrong construct an automated caller can't tell apart from a real clone.

    Returns ``{ok, saved_name, saved_id, length, grammar, entry_vector,
    collection}``.
    """
    guard = _agent_dirty_guard(app, payload)
    if guard is not None:
        return guard
    seq, serr = _sanitize_bases(payload.get("sequence"))
    if serr is not None:
        return ({"error": f"'sequence': {serr}"}, 400)
    if not seq:
        return ({"error": "missing/empty 'sequence'"}, 400)
    name = _sanitize_label(payload.get("name"), max_len=200)
    if not name:
        return ({"error": "missing or invalid 'name'"}, 400)
    oh5, e5 = _sanitize_bases(payload.get("oh5"), max_len=50)
    if e5 is not None or not oh5:
        return ({"error": "'oh5' must be a non-empty IUPAC overhang (≤50 nt)"},
                400)
    oh3, e3 = _sanitize_bases(payload.get("oh3"), max_len=50)
    if e3 is not None or not oh3:
        return ({"error": "'oh3' must be a non-empty IUPAC overhang (≤50 nt)"},
                400)
    grammar_id = _sanitize_label(payload.get("grammar") or "gb_l0", max_len=60)
    grammar = _all_grammars().get(grammar_id)
    if grammar is None:
        return ({"error": f"unknown grammar {grammar_id!r}"}, 400)
    # P1-5 fail-loud, part 1: require a configured entry vector up front so
    # the agent gets a clear "configure one" error instead of a stub.
    entry_vector = _get_entry_vector(grammar_id)
    if not (isinstance(entry_vector, dict) and entry_vector.get("gb_text")):
        return ({"error":
                  f"no entry vector configured for grammar {grammar_id!r} — "
                  "set one with set-entry-vector first (refusing to stub a "
                  "pUPD2 backbone)"}, 422)
    # Collection routing (agent-API feedback): the L0 files into the active
    # collection by default; an explicit non-active `collection` routes it
    # THERE (like copy-plasmid {to}) instead of 409ing. Resolved up front so
    # a bad destination fails before the (expensive) clone.
    dest_coll, derr = _agent_resolve_save_dest(payload)
    if derr is not None:
        return derr

    part = {
        "name":       name,
        "sequence":   seq,
        "oh5":        oh5,
        "oh3":        oh3,
        "grammar":    grammar_id,
        "type":       _sanitize_label(payload.get("type"), max_len=40) or "",
        "fwd_primer": str(payload.get("fwd_primer") or ""),
        "rev_primer": str(payload.get("rev_primer") or ""),
    }
    # Two-tier Golden-Braid nesting: if the configured vector's EXTERNAL acceptor
    # overhangs differ from the passed (category) overhangs — a UPD/pUPD-style
    # vector, e.g. external CTCG/TGAG vs category AATG/GCTT — record them so the
    # clone builds a NESTED amplicon (external pair wrapping the category pair),
    # exactly as design-gb-part designs the primers. This lets a caller pass the
    # part's category overhangs and still clone into a two-tier acceptor without
    # having to know the external pair. One-tier vectors (external == category)
    # are unaffected. `entry_vector` is already resolved + validated above.
    _dom_enz = grammar.get("enzyme") if isinstance(grammar, dict) else None
    _ext_oh = (_entry_vector_acceptor_overhangs(grammar_id, "", _dom_enz)
               if _dom_enz else None)
    if _ext_oh and (_ext_oh[0].upper(), _ext_oh[1].upper()) != \
            (oh5.upper(), oh3.upper()):
        part["entry_oh5"], part["entry_oh3"] = _ext_oh
    # P1-5 fail-loud, part 2: allow_stub=False raises when both real-clone
    # tiers fail (e.g. the vector's dropout overhangs don't match).
    try:
        rec = _part_to_cloned_seqrecord(part, allow_stub=False)
    except ValueError as exc:
        return ({"error": f"domestication failed: {exc}"}, 422)
    except Exception as exc:
        _log.exception("agent domesticate-part: clone failed")
        return ({"error": f"clone failed: {_scrub_path(str(exc))}"}, 500)
    if rec is None:
        return ({"error": "domestication produced no record"}, 422)

    base_name = _sanitize_label(payload.get("product_name"), max_len=80) or name
    # L0 lineage (INV-93 / P0-1): the cloned plasmid → its insert part + entry
    # vector, matching the GUI Domesticator's history tree.
    entry, save_err = _agent_save_constructed_entry(
        app, rec, base_name=base_name, source_tag="agent:domesticate",
        id_fallback="part", dest_coll=dest_coll,
        history_builder=lambda nm, sl: _build_history_for_l0_clone(
            name=nm, seq_len=sl, grammar_id=grammar_id, grammar=grammar,
            entry_vector=entry_vector, part=part))
    if entry is None:
        return save_err
    return {"ok": True, "saved_name": entry["name"], "saved_id": entry["id"],
            "length": entry["size"], "grammar": grammar_id,
            "entry_vector": entry_vector.get("name") or "",
            "collection": dest_coll,
            "ignored": _agent_ignored_keys(payload, {
                "sequence", "oh5", "oh3", "name", "grammar", "type",
                "fwd_primer", "rev_primer", "collection", "product_name"})}


@_agent_endpoint("domesticate-parts", write=True)
def _h_domesticate_parts(app, payload):
    """Batch domestication — run ``domesticate-part`` for each item in ONE
    call (agent-API feedback P1-6), so building N L0 parts doesn't round-trip
    the rate limiter N times. Body: ``{parts: [ {sequence, oh5, oh3, name,
    grammar?, type?, fwd_primer?, rev_primer?, collection?, product_name?},
    … ]}`` — each item is exactly a ``domesticate-part`` body.

    The canvas dirty-guard is checked ONCE up front: domestication saves the
    L0 to the library and never touches the canvas, so per-item guards would
    only re-check the same flag. Each part is then domesticated independently
    and its outcome reported per-item — one part that can't clone (no
    configured entry vector, dropout-overhang mismatch → 422) is reported
    without aborting the rest of the batch.

    Returns ``{ok, built, total, results:[{name, ok, saved_name?, saved_id?,
    length?, collection?, error?, code?}]}`` — ``built`` is how many L0s
    actually saved."""
    guard = _agent_dirty_guard(app, payload)
    if guard is not None:
        return guard
    parts = payload.get("parts")
    if not isinstance(parts, list) or not parts:
        return ({"error": "'parts' must be a non-empty list"}, 400)
    if len(parts) > 200:
        return ({"error": "too many parts (max 200 per batch)"}, 400)
    results, built = [], 0
    for idx, part in enumerate(parts):
        if not isinstance(part, dict):
            results.append({"name": None, "ok": False,
                            "error": f"parts[{idx}] must be an object"})
            continue
        nm = part.get("name")
        # Reuse the single-part endpoint verbatim (no logic drift). force=True
        # skips its per-item dirty-guard — already checked once above.
        res = _h_domesticate_part(app, {**part, "force": True})
        if isinstance(res, dict):           # success payload
            built += 1
            results.append({"name": nm, "ok": True,
                            "saved_name": res.get("saved_name"),
                            "saved_id":   res.get("saved_id"),
                            "length":     res.get("length"),
                            "collection": res.get("collection")})
        else:                               # (error_dict, code) tuple
            err  = res[0] if isinstance(res, tuple) else {}
            code = res[1] if isinstance(res, tuple) else 500
            results.append({"name": nm, "ok": False,
                            "error": err.get("error", "domestication failed"),
                            "code": code})
    return {"ok": True, "built": built, "total": len(parts),
            "results": results}


@_agent_endpoint("assemble-into-entry-vector", write=True)
def _h_assemble_into_entry_vector(app, payload):
    """Assemble multiple sources into a configured Golden-Braid / MoClo
    acceptor — the multi-source level-up clone (L0 parts → α/L1 TU, or TUs
    → Ω/L2 module), the real engine the GUI Constructor's "Save To Library"
    uses (agent-API feedback P0-1). Chains the sources by their fusion
    overhangs, ligates the chain into the cut acceptor at the level-up Type
    IIS enzyme, and SAVES the circular product (to the active collection, or
    the one named by ``collection``) with assembly lineage.

    Body: ``{sources, grammar?="gb_l0", source_level?=0, role?, name,
             product_name?, collection?}``.

    * ``sources`` — ordered list. For ``source_level=0`` each is an L0 part
      ``{name, sequence, oh5, oh3, type?}`` whose fusion overhangs must
      CHAIN (each source's ``oh3`` == the next source's ``oh5``). For
      ``source_level>=1`` each is an assembled plasmid ``{name, gb_text}``
      (digested at the level-up enzyme to release its insert).
    * ``grammar`` — cloning grammar id (default ``gb_l0``).
    * ``source_level`` — 0 for L0→L1 (TU), 1 for L1→L2 (module), …; the
      level-up enzyme alternates per level (``Esp3I``↔``BsaI`` for Golden
      Braid).
    * ``role`` — which acceptor slot (e.g. ``Alpha1`` / ``Omega1``); its
      configured entry vector (``set-entry-vector``) is digested. See
      ``list-entry-vectors`` for the configured roles.
    * ``name`` — the product's display + saved name.

    **Fails loud (422)** when no entry vector is configured for
    ``(grammar, role)``, OR when the assembly can't close — a junction
    overhang mismatch, an acceptor lacking the level-up sites, or the
    level-up enzyme finding no clean digest (note: the L2→binary hop is a
    known engine gap). It never silently emits a wrong construct.

    Returns ``{ok, saved_name, saved_id, length, grammar, source_level,
    role, n_sources, collection}``.
    """
    guard = _agent_dirty_guard(app, payload)
    if guard is not None:
        return guard
    name = _sanitize_label(payload.get("name"), max_len=200)
    if not name:
        return ({"error": "missing or invalid 'name'"}, 400)
    grammar_id = _sanitize_label(payload.get("grammar") or "gb_l0", max_len=60)
    grammar = _all_grammars().get(grammar_id)
    if grammar is None:
        return ({"error": f"unknown grammar {grammar_id!r}"}, 400)
    source_level = _coerce_int(payload.get("source_level", 0),
                               name="source_level")
    if isinstance(source_level, str):
        return ({"error": source_level}, 400)
    if not (0 <= source_level <= 10):
        return ({"error": "'source_level' out of range [0, 10]"}, 400)
    role = _sanitize_label(payload.get("role"), max_len=40) or ""
    # P1-5 fail-loud, part 1: require a configured acceptor for (grammar,
    # role) up front so the agent gets a clear "configure one" error.
    entry_vector = _get_entry_vector(grammar_id, role)
    if not (isinstance(entry_vector, dict) and entry_vector.get("gb_text")):
        return ({"error":
                  f"no entry vector configured for grammar {grammar_id!r} "
                  f"role {role!r} — set one with set-entry-vector (see "
                  "list-entry-vectors for configured roles)"}, 422)
    # Collection routing (agent-API feedback): files into the active
    # collection by default; an explicit non-active `collection` routes the
    # product THERE (like copy-plasmid {to}) instead of 409ing.
    dest_coll, derr = _agent_resolve_save_dest(payload)
    if derr is not None:
        return derr
    sources = payload.get("sources")
    if not isinstance(sources, list) or not sources:
        return ({"error": "'sources' must be a non-empty list"}, 400)
    if len(sources) > 30:
        return ({"error": "too many sources (max 30)"}, 400)
    src_dicts: list[dict] = []
    for i, s in enumerate(sources):
        if not isinstance(s, dict):
            return ({"error": f"source[{i}] is not an object"}, 400)
        nm = _sanitize_label(s.get("name"), max_len=200) or f"src{i + 1}"
        if source_level <= 0:
            seq, e = _sanitize_bases(s.get("sequence"))
            if e is not None or not seq:
                return ({"error":
                          f"source[{i}] needs a 'sequence' (IUPAC DNA)"}, 400)
            oh5, e5 = _sanitize_bases(s.get("oh5"), max_len=50)
            oh3, e3 = _sanitize_bases(s.get("oh3"), max_len=50)
            if e5 is not None or not oh5 or e3 is not None or not oh3:
                return ({"error":
                          f"source[{i}] needs non-empty 'oh5'/'oh3' "
                          "overhangs (≤50 nt)"}, 400)
            src_dicts.append({
                "name": nm, "sequence": seq, "oh5": oh5, "oh3": oh3,
                "type": _sanitize_label(s.get("type"), max_len=40) or "",
                "grammar": grammar_id, "level": 0,
            })
        else:
            gb = s.get("gb_text")
            if not isinstance(gb, str) or not gb.strip():
                return ({"error":
                          f"source[{i}] needs 'gb_text' for level "
                          f"{source_level}"}, 400)
            if len(gb) > _BULK_IMPORT_MAX_BYTES:
                return ({"error": f"source[{i}] gb_text too large"}, 400)
            src_dicts.append({
                "name": nm, "gb_text": gb,
                "grammar": grammar_id, "level": source_level,
            })
    # P1-5 fail-loud, part 2: the assembly cloner returns None on any
    # failure (junction mismatch, no clean level-up digest, …) — surface a
    # 422 with the likely causes, never a stub.
    try:
        rec = _clone_assembly_into_entry_vector(
            src_dicts, entry_vector, grammar,
            source_level=source_level, name=name)
    except Exception as exc:
        _log.exception("agent assemble-into-entry-vector: clone failed")
        return ({"error": f"assembly failed: {_scrub_path(str(exc))}"}, 500)
    if rec is None:
        return ({"error":
                  "assembly could not close — check that each source's oh3 "
                  "matches the next source's oh5, the acceptor carries the "
                  "level-up enzyme's sites, and the level-up enzyme finds a "
                  "clean digest (the L2→binary hop is a known engine gap). "
                  "Refusing to emit a stub."}, 422)

    base_name = _sanitize_label(payload.get("product_name"), max_len=80) or name
    # Assembly lineage: each source + the acceptor as a parent node. Source
    # size = bp length for L0 sources; 0 (unknown) for L1+ gb_text sources —
    # NOT len(gb_text), which counts GenBank header/annotation chars and
    # inflated the History size badge (code-review). A source that matches a
    # saved library entry by name gets its real size from the cross-ref.
    _parents = ([{"name": s["name"], "size": len(s.get("sequence") or "")}
                 for s in src_dicts]
                + [{"name": entry_vector.get("name") or "entry vector",
                    "size": entry_vector.get("size") or 0}])
    entry, save_err = _agent_save_constructed_entry(
        app, rec, base_name=base_name, source_tag="agent:assemble",
        id_fallback="assembly", dest_coll=dest_coll,
        history_builder=lambda nm, sl: _build_history_for_agent_assembly(
            name=nm, seq_len=sl, circular=True,
            manipulation=(f"goldenBraid L{source_level}"
                          f"→L{source_level + 1} assembly"),
            parents=_parents))
    if entry is None:
        return save_err
    return {"ok": True, "saved_name": entry["name"], "saved_id": entry["id"],
            "length": entry["size"], "grammar": grammar_id,
            "source_level": source_level, "role": role,
            "n_sources": len(src_dicts), "collection": dest_coll,
            "ignored": _agent_ignored_keys(payload, {
                "sources", "grammar", "source_level", "role", "name",
                "product_name", "collection"})}


